/**
 * Fetch all available habit categories
 * Returns a list of category filters including 'All' and all unique categories from templates
 *
 * @returns Array of category objects with id, label, and icon
 * @example
 * ```ts
 * const categories = useQuery(api.categories.list, {});
 * // Returns: [{ id: 'all', label: 'All', icon: '✨' }, ...]
 * ```
 */
export const list = query({
  args: {},
  handler: async (ctx) => {
    // Fetch all templates to get unique categories
    const templates = await ctx.db.query('templates').collect();

    // Early return if no templates exist
    if (templates.length === 0) {
      return [{ icon: '✨', id: 'all' as const, label: 'All' }];
    }

    // Extract unique categories from templates
    const uniqueCategories = Array.from(
      new Set(templates.map((template) => template.category))
    ).sort();

    // Define category metadata (icon and label for each category)
    const categoryMetadata: Record<
      string,
      { icon: string; label: string }
    > = {
      andrew_huberman: { icon: '🔬', label: 'Huberman' },
      breathing: { icon: '🌬️', label: 'Breathing' },
      creativity: { icon: '🎨', label: 'Creativity' },
      financial: { icon: '💰', label: 'Financial' },
      health_fitness: { icon: '💪', label: 'Health' },
      learning: { icon: '📚', label: 'Learning' },
      longevity: { icon: '🧬', label: 'Longevity' },
      mental_health: { icon: '🧠', label: 'Mental Health' },
      mindfulness: { icon: '🧘', label: 'Mindfulness' },
      morning_routine: { icon: '🌅', label: 'Morning' },
      productivity: { icon: '🎯', label: 'Productivity' },
      recovery: { icon: '🔄', label: 'Recovery' },
      sleep: { icon: '😴', label: 'Sleep' },
      social: { icon: '👥', label: 'Social' },
    };

    // Build category filters with alphabetical property ordering
    const categories = uniqueCategories.map((categoryId) => {
      const metadata = categoryMetadata[categoryId] || {
        icon: '📌',
        label: categoryId.charAt(0).toUpperCase() + categoryId.slice(1).replace(/_/g, ' '),
      };

      return {
        icon: metadata.icon,
        id: categoryId,
        label: metadata.label,
      };
    });

    // Always include 'All' as the first category (alphabetical properties)
    return [
      { icon: '✨', id: 'all' as const, label: 'All' },
      ...categories,
    ];
  },
});

import { query } from './_generated/server';
import { v } from 'convex/values';

export const getCharacterStats = query({
  args: {},
  handler: async (ctx) => {
    try {
      // Get all active habits
      const habits = await ctx.db
        .query('habits')
        .filter((q) => q.neq(q.field('archived'), true))
        .collect();

      // Get all tracking data
      const allTracking = await ctx.db.query('tracking').collect();

      // Calculate streaks for each habit
      const habitStreaks = new Map<string, number>();
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      for (const habit of habits) {
        const habitTracking = allTracking
          .filter((t) => t.habitId === habit._id && t.completed)
          .map((t) => new Date(t.date).getTime())
          .sort((a, b) => b - a);

        let streak = 0;
        for (const [i, element] of habitTracking.entries()) {
          const expectedDate = new Date(today);
          expectedDate.setDate(today.getDate() - i);
          expectedDate.setHours(0, 0, 0, 0);
          const expectedTime = expectedDate.getTime();

          if (element === expectedTime) {
            streak++;
          } else {
            break;
          }
        }
        habitStreaks.set(habit._id, streak);
      }

      // Calculate XP
      let totalXP = 0;
      const completedTracking = allTracking.filter((t) => t.completed);

      for (const tracking of completedTracking) {
        const habit = habits.find((h) => h._id === tracking.habitId);
        if (!habit) continue;

        // Base XP: 10 per completion
        let xp = 10;

        // Streak bonus: +2 XP per day in current streak
        const streak = habitStreaks.get(habit._id) || 0;
        xp += Math.min(streak * 2, 50); // Cap streak bonus at 50

        // Strength bonus: up to +10 XP based on habit strength
        const strength = habit.strength || 0;
        xp += Math.floor(strength * 10);

        totalXP += xp;
      }

      // Calculate level using square root progression
      const level = Math.floor(Math.sqrt(totalXP / 50)) + 1;
      const xpForCurrentLevel = (level - 1) ** 2 * 50;
      const xpForNextLevel = level ** 2 * 50;
      const xpInCurrentLevel = totalXP - xpForCurrentLevel;
      const xpNeededForNextLevel = xpForNextLevel - xpForCurrentLevel;

      // Calculate attributes

      // Vitality: Overall consistency (average completion rate over last 30 days)
      const thirtyDaysAgo = new Date(today);
      thirtyDaysAgo.setDate(today.getDate() - 30);
      const last30DaysTracking = allTracking.filter((t) => {
        const trackingDate = new Date(t.date);
        return trackingDate >= thirtyDaysAgo && trackingDate <= today;
      });
      const possibleCompletions = habits.length * 30;
      const actualCompletions = last30DaysTracking.filter(
        (t) => t.completed
      ).length;
      const vitality = Math.min(
        100,
        Math.round((actualCompletions / Math.max(possibleCompletions, 1)) * 100)
      );

      // Strength: Average streak strength across all habits
      const streakValues = [...habitStreaks.values()];
      const avgStreak =
        streakValues.length > 0
          ? streakValues.reduce((a, b) => a + b, 0) / streakValues.length
          : 0;
      const strength = Math.min(100, Math.round(avgStreak * 10)); // 10-day streak = 100 strength

      // Wisdom: Based on total unique days tracked (experience)
      const uniqueDates = new Set(
        allTracking.filter((t) => t.completed).map((t) => t.date)
      );
      const totalDaysTracked = uniqueDates.size;
      const wisdom = Math.min(100, Math.round((totalDaysTracked / 100) * 100)); // 100 days = 100 wisdom

      // Energy: Recent activity (last 7 days completion rate)
      const sevenDaysAgo = new Date(today);
      sevenDaysAgo.setDate(today.getDate() - 7);
      const last7DaysTracking = allTracking.filter((t) => {
        const trackingDate = new Date(t.date);
        return trackingDate >= sevenDaysAgo && trackingDate <= today;
      });
      const possibleLast7Days = habits.length * 7;
      const actualLast7Days = last7DaysTracking.filter(
        (t) => t.completed
      ).length;
      const energy = Math.min(
        100,
        Math.round((actualLast7Days / Math.max(possibleLast7Days, 1)) * 100)
      );

      // Calculate stats
      const streakArray = [...habitStreaks.values()];
      const maxStreak = streakArray.length > 0 ? Math.max(...streakArray) : 0;
      const totalPower = vitality + strength + wisdom + energy;
      const activeHabits = habits.length;

      // Get title based on level
      const titles = [
        'Novice',
        'Habit Hero',
        'Routine Master',
        'Consistency Champion',
        'Discipline Legend',
        'Zen Master',
        'Unstoppable Force',
      ];
      const titleIndex = Math.min(Math.floor(level / 5), titles.length - 1);
      const title = titles[titleIndex];

      return {
        attributes: {
          energy,
          strength,
          vitality,
          wisdom,
        },
        level,
        stats: {
          activeHabits,
          dayStreak: maxStreak,
          totalPower,
        },
        title,
        totalXP,
        xp: xpInCurrentLevel,
        xpToNextLevel: xpNeededForNextLevel,
      };
    } catch (error) {
      console.error('Error calculating character stats:', error);
      // Return default stats on error
      return {
        attributes: {
          energy: 0,
          strength: 0,
          vitality: 0,
          wisdom: 0,
        },
        level: 1,
        stats: {
          activeHabits: 0,
          dayStreak: 0,
          totalPower: 0,
        },
        title: 'Novice',
        totalXP: 0,
        xp: 0,
        xpToNextLevel: 50,
      };
    }
  },
  returns: v.object({
    attributes: v.object({
      energy: v.number(),
      strength: v.number(),
      vitality: v.number(),
      wisdom: v.number(),
    }),
    level: v.number(),
    stats: v.object({
      activeHabits: v.number(),
      dayStreak: v.number(),
      totalPower: v.number(),
    }),
    title: v.string(),
    totalXP: v.number(),
    xp: v.number(),
    xpToNextLevel: v.number(),
  }),
});

/**
 * Simple diagnostic to see what's actually in your database
 * Run: npx convex run diagnose:show
 */

import { query, mutation } from './_generated/server';
import { calculateHabitStrength } from './habitStrength';

export const show = query({
  handler: async (ctx) => {
    const habits = await ctx.db.query('habits').collect();

    const results = [];

    for (const habit of habits) {
      const tracking = await ctx.db
        .query('tracking')
        .withIndex('by_habit_and_date', (q) => q.eq('habitId', habit._id))
        .collect();

      const completed = tracking.filter((t) => t.completed).length;

      results.push({
        completedEntries: completed,
        currentStrength: habit.strength,
        hasStrengthField: typeof habit.strength,
        lastUpdated: habit.strengthUpdatedAt || 'never',
        name: habit.name,
        strengthLevel: habit.strengthLevel || 'not set',
        strengthPercent: habit.strength
          ? `${(habit.strength * 100).toFixed(1)}%`
          : 'null',
        trackingEntries: tracking.length,
      });
    }

    return {
      diagnosis:
        habits.length === 0
          ? '❌ No habits found in database'
          : results.every((h) => h.hasStrengthField === 'undefined')
            ? "❌ Schema field 'strength' doesn't exist - run 'npx convex dev'"
            : results.every(
                  (h) => h.currentStrength === null || h.currentStrength === 0
                )
              ? '⚠️ Strength exists but all at 0% - needs initialization'
              : '✅ Some habits have strength values',
      habits: results,
      totalHabits: habits.length,
    };
  },
});

export const fix = mutation({
  handler: async (ctx) => {
    console.log('🔧 Forcing habit strength calculation...');

    const habits = await ctx.db.query('habits').collect();
    let fixed = 0;

    for (const habit of habits) {
      const tracking = await ctx.db
        .query('tracking')
        .withIndex('by_habit_and_date', (q) => q.eq('habitId', habit._id))
        .collect();

      if (tracking.length === 0) {
        await ctx.db.patch(habit._id, {
          strength: 0,
          strengthLevel: 'starting',
          strengthUpdatedAt: Date.now(),
        });
        console.log(`  ${habit.name}: Set to 0% (no tracking data)`);
        continue;
      }

      // Calculate from all history
      const sorted = tracking
        .map((t) => ({ ...t, date: t.date }))
        .sort((a, b) => a.date.localeCompare(b.date));

      let strength = 0;
      for (const entry of sorted) {
        strength = calculateHabitStrength(
          strength,
          entry.completed,
          0.175,
          0.15
        );
      }

      const level =
        strength < 0.2
          ? 'starting'
          : strength < 0.4
            ? 'building'
            : strength < 0.6
              ? 'developing'
              : strength < 0.8
                ? 'strong'
                : 'automatic';

      await ctx.db.patch(habit._id, {
        strength,
        strengthLevel: level,
        strengthUpdatedAt: Date.now(),
      });

      console.log(
        `  ${habit.name}: ${(strength * 100).toFixed(1)}% (${level})`
      );
      fixed++;
    }

    console.log(`✅ Fixed ${fixed} habits`);
    return { fixed, total: habits.length };
  },
});

