import { v } from 'convex/values';
import { mutation, query } from './_generated/server';
import { calculateMomentumStrengthSnapshot } from './habitStrength';
import { calculateStreakFromHistory } from "./streakUtils";

function getTodayDateKey(): string {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function maxDateKey(a: string, b: string): string {
  return a > b ? a : b;
}

export const create = mutation({
  args: {
    // Cue - Implementation Intention (Gollwitzer, 1999: 2-3x follow-through)
    cueAfterBehavior: v.optional(v.string()),
    cueLocation: v.optional(v.string()),
    cueTime: v.optional(v.string()),
    icon: v.optional(v.string()),
    iconColor: v.optional(v.string()),
    name: v.string(),
    notes: v.optional(v.string()),
    preferredTime: v.optional(v.string()),
    remindersEnabled: v.optional(v.boolean()),
    reminderSound: v.optional(v.string()),
    reminderTime: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    // Get authenticated user (optional for now during auth debugging)
    const identity = await ctx.auth.getUserIdentity();
    const userId = identity?.subject;

    console.log('habits.create: identity =', identity ? 'PRESENT' : 'MISSING');
    if (identity) {
      console.log('habits.create: userId =', userId);
    }

    // Get all existing habits for this user to determine next order value
    const allHabits = await ctx.db.query('habits').collect();
    let maxOrder = -1;
    for (const habit of allHabits) {
      const order = habit.order ?? -1;
      if (order > maxOrder) {
        maxOrder = order;
      }
    }

    return await ctx.db.insert('habits', {
      userId, // Store Clerk user ID if available
      bestStreak: 0,
      createdAt: Date.now(),
      // Cue - Implementation Intention (Story 1.9.5)
      cueAfterBehavior: args.cueAfterBehavior,
      cueLocation: args.cueLocation,
      cueTime: args.cueTime,
      // Initialize streak tracking fields (Story 1.3)
      currentStreak: 0,

      icon: args.icon,

      iconColor: args.iconColor,

      lastCompletedDate: undefined,

      name: args.name,

      notes: args.notes,

      order: maxOrder + 1,

      // Huberman day phase timing
      preferredTime: args.preferredTime,

      remindersEnabled: args.remindersEnabled,

      reminderSound: args.reminderSound,
      reminderTime: args.reminderTime,

      // Initialize habit strength fields (v2.0 momentum-based formula)
      strength: 0,
      strengthLevel: 'starting',
      strengthUpdatedAt: Date.now(),
    });
  },
  returns: v.id('habits'),
});

export const updateNotes = mutation({
  args: {
    habitId: v.id('habits'),
    notes: v.string(),
  },
  handler: async (ctx, args) => {
    await ctx.db.patch(args.habitId, {
      notes: args.notes,
    });
    return null;
  },
  returns: v.null(),
});

export const update = mutation({
  args: {
    // Cue - Implementation Intention (Gollwitzer, 1999)
    cueAfterBehavior: v.optional(v.string()),
    cueLocation: v.optional(v.string()),
    cueTime: v.optional(v.string()),
    daysOfWeek: v.optional(v.array(v.number())),
    frequency: v.optional(v.string()),
    goalDuration: v.optional(v.number()),
    habitId: v.id('habits'),
    goalUnit: v.optional(v.string()),
    icon: v.optional(v.string()),
    iconColor: v.optional(v.string()),
    name: v.optional(v.string()),
    notes: v.optional(v.string()),
    why: v.optional(v.string()),
    identity: v.optional(v.string()),
    preferredTime: v.optional(v.string()),
    remindersEnabled: v.optional(v.boolean()),
    reminderSound: v.optional(v.string()),
    reminderTime: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    const { habitId, ...updates } = args;

    // Remove undefined fields
    const cleanedUpdates = Object.fromEntries(
      Object.entries(updates).filter(([_, value]) => value !== undefined)
    );

    await ctx.db.patch(habitId, cleanedUpdates);
    return null;
  },
  returns: v.null(),
});

