export const toggleHabit = mutation({
  args: { date: v.string(), habitId: v.id('habits') },
  handler: async (ctx, args) => {
    // Validate date format as YYYY-MM-DD
    const isValidDate = /^\d{4}-\d{2}-\d{2}$/.test(args.date);
    if (!isValidDate)
      throw new Error('Invalid date format; expected YYYY-MM-DD');

    // Prevent future dates - only allow today or past dates
    const [yearStr, monthStr, dayStr] = args.date.split('-');
    const inputDate = new Date(
      Number(yearStr),
      Number(monthStr) - 1,
      Number(dayStr)
    );
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    inputDate.setHours(0, 0, 0, 0);

    if (inputDate > today) {
      throw new Error('Cannot track habits for future dates');
    }

    const existing = await ctx.db
      .query('tracking')
      .withIndex('by_habit_and_date', (q) =>
        q.eq('habitId', args.habitId).eq('date', args.date)
      )
      .unique();

    const newCompletedStatus = existing ? !existing.completed : true;

    await (existing
      ? ctx.db.patch(existing._id, {
          completed: newCompletedStatus,
        })
      : ctx.db.insert('tracking', {
          completed: true,
          date: args.date,
          habitId: args.habitId,
        }));

    // Update habit strength and streak based on full tracking history
    const habit = await ctx.db.get(args.habitId);
    if (habit) {
      // Query all tracking for this habit to count TOTAL completions
      const allTracking = await ctx.db
        .query('tracking')
        .withIndex('by_habit_and_date', (q) => q.eq('habitId', args.habitId))
        .collect();

      const maxTrackingDateKey = allTracking.reduce(
        (maxKey, record) => maxDateKey(maxKey, record.date),
        args.date
      );

      const evaluationDateKey = maxDateKey(
        getTodayDateKey(),
        maxDateKey(args.date, maxTrackingDateKey)
      );

      const snapshot = calculateMomentumStrengthSnapshot({
        habitCreatedAt: habit.createdAt,
        throughDate: evaluationDateKey,
        tracking: allTracking.map((record) => ({
          completed: record.completed,
          date: record.date,
        })),
      });

      // Calculate streak from full tracking history (supports backfills)
      const streakData = calculateStreakFromHistory(
        allTracking.map((t) => ({ date: t.date, completed: t.completed })),
        evaluationDateKey
      );

      const previousStrength100 = (habit.strength ?? 0) * 100;

      console.log('🔧 Habit Strength Update (momentum-based):', {
        action: newCompletedStatus ? 'TOGGLE ON' : 'TOGGLE OFF',
        change: `${(snapshot.strength100 - previousStrength100).toFixed(2)}%`,
        date: args.date,
        daysProcessed: snapshot.daysProcessed,
        evaluationDateKey,
        habitName: habit.name,
        newStrength: `${snapshot.strength100.toFixed(1)}%`,
        previousStrength: `${previousStrength100.toFixed(1)}%`,
      });

      await ctx.db.patch(args.habitId, {
        bestStreak: streakData.bestStreak,
        currentStreak: streakData.currentStreak,
        lastCompletedDate: streakData.lastCompletedDate,
        strength: snapshot.strength,
        strengthLevel: snapshot.strengthLevel,
        strengthUpdatedAt: Date.now(),
      });
    }

    return null;
  },
  returns: v.null(),
});

export const getTracking = query({
  args: { dates: v.array(v.string()) },
  handler: async (ctx, args) => {
    if (args.dates.length === 0) return [];

    // Optimize by querying a single date range then filtering to requested dates
    const sortedDates = [...args.dates].sort();
    const startDate = sortedDates[0];
    const endDate = sortedDates.at(-1);
    if (!endDate) return [];

    const range = await ctx.db
      .query('tracking')
      .filter((q) =>
        q.and(
          q.gte(q.field('date'), startDate),
          q.lte(q.field('date'), endDate)
        )
      )
      .collect();

    const dateSet = new Set(args.dates);
    return range.filter((t) => dateSet.has(t.date));
  },
  returns: v.array(
    v.object({
      _creationTime: v.number(),
      _id: v.id('tracking'),
      completed: v.boolean(),
      date: v.string(),
      habitId: v.id('habits'),
      userId: v.optional(v.string()),
    })
  ),
});

export const getStats = query({
  args: { habitId: v.id('habits') },
  handler: async (ctx, args) => {
    const tracking = await ctx.db
      .query('tracking')
      .withIndex('by_habit_and_date', (q) => q.eq('habitId', args.habitId))
      .collect();

    const sortedDates = tracking
      .filter((t) => t.completed)
      .map((t) => new Date(t.date).getTime())
      .sort((a, b) => b - a);

    let streak = 0;
    const now = new Date();
    now.setHours(0, 0, 0, 0);

    for (const [i, sortedDate] of sortedDates.entries()) {
      const expectedDate = new Date(now);
      expectedDate.setDate(now.getDate() - i);
      expectedDate.setHours(0, 0, 0, 0);
      const expectedTime = expectedDate.getTime();

      if (sortedDate === expectedTime) {
        streak++;
      } else {
        break;
      }
    }

    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
    thirtyDaysAgo.setHours(0, 0, 0, 0);
    const recentTracking = tracking.filter((t) => {
      const date = new Date(t.date);
      return date >= thirtyDaysAgo && t.completed;
    });

    const consistency = Math.max(
      0,
      Math.min(100, Math.round((recentTracking.length / 30) * 100))
    );

    return { consistency, streak };
  },
  returns: v.object({ consistency: v.number(), streak: v.number() }),
});

/**
 * Initialize habit strength for all existing habits using NEW momentum-based formula
 * Run this once to populate strength values for habits that don't have them yet
 * Uses recalculateHabitStrength which simulates the new formula day-by-day
 */
import { mutation } from './_generated/server';
import { v } from 'convex/values';
import { calculateNewStrength, getStrengthLevel } from './habitStrength';

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

export const initializeAllHabitsStrength = mutation({
  args: {},
  handler: async (ctx) => {
    const habits = await ctx.db
      .query('habits')
      .filter((q) => q.neq(q.field('archived'), true))
      .collect();

    console.log(`🔄 Initializing strength for ${habits.length} habits...`);

    let initialized = 0;
    let skipped = 0;

    for (const habit of habits) {
      // Skip if already has strength
      if (habit.strength !== undefined) {
        console.log(`  ⏭️  Skipping ${habit.name} - already has strength`);
        skipped++;
        continue;
      }

      // Get all tracking data for this habit
      const tracking = await ctx.db
        .query('tracking')
        .withIndex('by_habit_and_date', (q) => q.eq('habitId', habit._id))
        .collect();

      console.log(`  ▸ Found ${tracking.length} tracking entries`);

      if (tracking.length === 0) {
        // No tracking data = start at 0
        await ctx.db.patch(habit._id, {
          strength: 0,
          strengthLevel: 'starting',
          strengthUpdatedAt: Date.now(),
        });
        console.log(`  ✅ ${habit.name}: 0% (starting) - no tracking data`);
        initialized++;
        continue;
      }

      // Simulate day-by-day progression with NEW momentum-based formula
      const sortedTracking = tracking.sort((a, b) => a.date.localeCompare(b.date));
      let currentStrength = 0; // Start from 0
      const completionsByDate = new Map<string, boolean>();

      for (const record of sortedTracking) {
        completionsByDate.set(record.date, record.completed);
      }

      // Process each day chronologically
      for (const record of sortedTracking) {
        const recordDate = new Date(record.date);
        const sevenDaysAgo = new Date(recordDate);
        sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

        // Count completions in last 7 days (before this date)
        let completionsLast7Days = 0;
        for (const [date, completed] of completionsByDate.entries()) {
          const checkDate = new Date(date);
          if (checkDate >= sevenDaysAgo && checkDate < recordDate && completed) {
            completionsLast7Days++;
          }
        }

        // Apply NEW momentum-based formula
        currentStrength = calculateNewStrength(
          currentStrength,
          record.completed,
          completionsLast7Days
        );
      }

      // Convert to 0-1 scale for storage
      const finalStrength = currentStrength / 100;
      const strengthLevel = getStrengthLevel(finalStrength);

      // Update habit with calculated strength
      await ctx.db.patch(habit._id, {
        strength: finalStrength,
        strengthLevel,
        strengthUpdatedAt: Date.now(),
      });

      console.log(
        `  ✅ ${habit.name}: ${currentStrength.toFixed(1)}% (${strengthLevel})`
      );
      initialized++;
    }

    console.log(
      `\n✨ Complete! Initialized: ${initialized}, Skipped: ${skipped}`
    );

    return {
      initialized,
      skipped,
      total: habits.length,
    };
  },
  returns: v.object({
    initialized: v.number(),
    skipped: v.number(),
    total: v.number(),
  }),
});

