import { View, Text, StyleSheet, Pressable } from 'react-native';
import { GestureDetector, Gesture } from 'react-native-gesture-handler';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
  runOnJS,
  Easing,
} from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { Archive, Undo2 } from 'lucide-react-native';

export interface ArchiveUndoToastProps {
  /** Toast visibility */
  visible: boolean;

  /** Name of the archived habit */
  habitName: string;

  /** Duration before auto-dismiss in ms (default: 5000) */
  duration?: number;

  /** On dismiss callback (called when toast disappears) */
  onDismiss?: () => void;

  /** On undo callback (called when user taps undo) */
  onUndo?: () => void;
}

const DISMISS_THRESHOLD = 50;

export function ArchiveUndoToast({
  visible,
  habitName,
  duration = 5000,
  onDismiss,
  onUndo,
}: ArchiveUndoToastProps) {
  const insets = useSafeAreaInsets();

  // Animation values
  const translateY = useSharedValue(100);
  const opacity = useSharedValue(0);
  const progressWidth = useSharedValue(100); // percentage

  // Handle dismiss
  const handleDismiss = useCallback(() => {
    translateY.value = withSpring(100, {
      damping: 15,
      stiffness: 150,
    });
    opacity.value = withTiming(0, { duration: 200 });
    progressWidth.value = 100;

    if (onDismiss) {
      setTimeout(() => {
        onDismiss();
      }, 250);
    }
  }, [onDismiss, translateY, opacity, progressWidth]);

  // Handle undo action
  const handleUndo = useCallback(() => {
    if (onUndo) {
      onUndo();
    }
    handleDismiss();
  }, [onUndo, handleDismiss]);

  // Enter/exit animation
  useEffect(() => {
    if (visible) {
      // Reset and start animations
      progressWidth.value = 100;

      // Slide up and fade in
      translateY.value = withSpring(0, {
        damping: 15,
        stiffness: 150,
      });
      opacity.value = withTiming(1, { duration: 200 });

      // Animate progress bar countdown
      progressWidth.value = withTiming(0, {
        duration: duration,
        easing: Easing.linear,
      });

      // Auto-dismiss after duration
      const timer = setTimeout(() => {
        handleDismiss();
      }, duration);

      return () => clearTimeout(timer);
    } else {
      // Slide down and fade out
      translateY.value = withSpring(100, {
        damping: 15,
        stiffness: 150,
      });
      opacity.value = withTiming(0, { duration: 200 });
    }
  }, [visible, duration, handleDismiss, translateY, opacity, progressWidth]);

  // Pan gesture for swipe to dismiss
  const panGesture = Gesture.Pan()
    .onUpdate((event) => {
      // Only allow downward swipe
      if (event.translationY > 0) {
        translateY.value = event.translationY;
        opacity.value = 1 - event.translationY / 100;
      }
    })
    .onEnd((event) => {
      // Use Math.round on velocity to avoid precision loss error in Reanimated
      const velocityY = Math.round(event.velocityY);
      if (event.translationY > DISMISS_THRESHOLD || velocityY > 500) {
        runOnJS(handleDismiss)();
      } else {
        // Spring back to visible position
        translateY.value = withSpring(0, {
          damping: 15,
          stiffness: 150,
        });
        opacity.value = withTiming(1, { duration: 150 });
      }
    });

  // Animated styles
  const containerStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ translateY: translateY.value }],
  }));

  const progressStyle = useAnimatedStyle(() => ({
    width: `${progressWidth.value}%`,
  }));

  if (!visible) return null;

  return (
    <View
      pointerEvents='box-none'
      style={[styles.container, { bottom: insets.bottom + 16 }]}
    >
      <GestureDetector gesture={panGesture}>
        <Animated.View
          accessible
          accessibilityLabel={`${habitName} archived. Tap undo to restore.`}
          accessibilityLiveRegion='polite'
          accessibilityRole='alert'
          style={[styles.toast, containerStyle]}
        >
          {/* Content */}
          <View style={styles.content}>
            {/* Icon */}
            <View style={styles.iconContainer}>
              <Archive color='#b45309' size={18} strokeWidth={2} />
            </View>

            {/* Message */}
            <Text numberOfLines={1} style={styles.message}>
              <Text style={styles.habitName}>"{habitName}"</Text>
              <Text style={styles.messageText}> archived</Text>
            </Text>

            {/* Undo Button */}
            <Pressable
              accessibilityLabel='Undo archive'
              accessibilityRole='button'
              style={({ pressed }) => [
                styles.undoButton,
                pressed && styles.undoButtonPressed,
              ]}
              onPress={handleUndo}
            >
              <Undo2 color='#b45309' size={14} strokeWidth={2.5} />
              <Text style={styles.undoText}>UNDO</Text>
            </Pressable>
          </View>

          {/* Progress bar */}
          <View style={styles.progressContainer}>
            <Animated.View style={[styles.progressBar, progressStyle]} />
          </View>
        </Animated.View>
      </GestureDetector>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    left: 20,
    position: 'absolute',
    right: 20,
    zIndex: 9999,
  },
  content: {
    alignItems: 'center',
    flexDirection: 'row',
    gap: 12,
    paddingHorizontal: 16,
    paddingTop: 14,
    paddingBottom: 16,
  },
  habitName: {
    color: '#1c1917', // stone-900 - matches app text
    fontWeight: '600',
  },
  iconContainer: {
    alignItems: 'center',
    backgroundColor: '#fef3c7', // amber-100 - warm and matches swipe
    borderRadius: 10,
    height: 36,
    justifyContent: 'center',
    width: 36,
  },
  message: {
    flex: 1,
    fontSize: 14,
  },
  messageText: {
    color: '#78716c', // stone-500 - warm gray
  },
  progressBar: {
    backgroundColor: '#d97706', // amber-600 - slightly deeper
    height: '100%',
  },
  progressContainer: {
    backgroundColor: '#fef3c7', // amber-100
    borderBottomLeftRadius: 22,
    borderBottomRightRadius: 22,
    height: 3,
    overflow: 'hidden',
    width: '100%',
  },
  toast: {
    backgroundColor: '#ffffff', // white - matches habit cards
    borderColor: '#f5f5f4', // stone-100 - matches card borders
    borderRadius: 24, // matches card rounded-3xl
    borderWidth: 1,
    maxWidth: 400,
    overflow: 'hidden',
    shadowColor: '#78716c', // stone-500 - warm shadow
    shadowOffset: { width: 0, height: 6 },
    shadowOpacity: 0.12,
    shadowRadius: 16,
    width: '100%',
    elevation: 8,
  },
  undoButton: {
    alignItems: 'center',
    backgroundColor: '#fef3c7', // amber-100
    borderRadius: 10,
    flexDirection: 'row',
    gap: 6,
    paddingHorizontal: 14,
    paddingVertical: 10,
  },
  undoButtonPressed: {
    backgroundColor: '#fde68a', // amber-200
  },
  undoText: {
    color: '#b45309', // amber-700 - richer contrast
    fontSize: 13,
    fontWeight: '700',
    letterSpacing: 0.3,
  },
});

export default ArchiveUndoToast;

import { useMutation, useQuery } from 'convex/react';
import { Alert } from 'react-native';
import * as Haptics from 'expo-haptics';
import { api } from '../../../convex/_generated/api';
import type { Id } from '../../../convex/_generated/dataModel';

export const useArchivedHabitsModalLogic = () => {
  const archivedHabits = useQuery(api.habits.listArchived) ?? [];
  const unarchiveHabit = useMutation(api.habits.unarchive);
  const removeHabit = useMutation(api.habits.remove);

  const handleRestore = async (habitId: Id<'habits'>, habitName: string): Promise<boolean> => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);

    try {
      await unarchiveHabit({ habitId });
      // Success haptic feedback after restore completes
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
      return true;
    } catch (error) {
      console.error('Failed to restore habit:', error);
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error);
      Alert.alert(
        'Error',
        `Failed to restore "${habitName}". Please try again.`
      );
      return false;
    }
  };

  const handlePermanentDelete = (habitId: Id<'habits'>, habitName: string) => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);

    Alert.alert(
      `Permanently Delete "${habitName}"?`,
      'This will permanently delete the habit and all its tracking data. This action cannot be undone.',
      [
        {
          style: 'cancel',
          text: 'Cancel',
        },
        {
          onPress: async () => {
            try {
              await removeHabit({ habitId });
              Haptics.notificationAsync(
                Haptics.NotificationFeedbackType.Success
              );
            } catch (error) {
              console.error('Failed to delete habit:', error);
              Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error);
              Alert.alert(
                'Error',
                `Failed to delete "${habitName}". Please try again.`
              );
            }
          },
          style: 'destructive',
          text: 'Delete Forever',
        },
      ],
      { cancelable: true }
    );
  };

  return {
    archivedHabits,
    handlePermanentDelete,
    handleRestore,
  };
};

