import { useEffect, useState, useCallback } from 'react';
import { ScrollView, Text, TouchableOpacity, View } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { BlurView } from 'expo-blur';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { ChevronLeft, X, Check } from 'lucide-react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withDelay,
  withSpring,
  withTiming,
  withSequence,
  Easing,
  cancelAnimation,
} from 'react-native-reanimated';
import { useArchivedHabitsModalLogic } from './ArchivedHabitsModal.hooks';
import { useReduceMotion } from '../../hooks/useReduceMotion';
import type { Id } from '../../../convex/_generated/dataModel';

interface ArchivedHabitsModalProps {
  onClose: () => void;
  onBack: () => void;
}

// Get strength level info based on percentage
const getStrengthInfo = (strength: number) => {
  if (strength >= 80) return { emoji: '⚡', label: 'Automatic', bgColor: 'bg-purple-50', textColor: 'text-purple-700' };
  if (strength >= 60) return { emoji: '💪', label: 'Strong', bgColor: 'bg-emerald-50', textColor: 'text-emerald-700' };
  if (strength >= 40) return { emoji: '🌳', label: 'Developing', bgColor: 'bg-teal-50', textColor: 'text-teal-700' };
  if (strength >= 20) return { emoji: '🌿', label: 'Building', bgColor: 'bg-yellow-50', textColor: 'text-yellow-700' };
  return { emoji: '🌱', label: 'Starting', bgColor: 'bg-rose-50', textColor: 'text-rose-600' };
};

// Get strength gradient color
const getStrengthGradientColor = (strength: number): string => {
  if (strength >= 80) return '#A855F7'; // purple-500
  if (strength >= 60) return '#10B981'; // emerald-500
  if (strength >= 40) return '#14B8A6'; // teal-500
  if (strength >= 20) return '#EAB308'; // yellow-500
  return '#F43F5E'; // rose-500
};

// Format relative time
const getRelativeTime = (timestamp: number): string => {
  const now = Date.now();
  const diffMs = now - timestamp;
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

  if (diffDays === 0) return 'today';
  if (diffDays === 1) return 'yesterday';
  if (diffDays < 7) return `${diffDays} days ago`;
  if (diffDays < 30) {
    const weeks = Math.floor(diffDays / 7);
    return `${weeks} week${weeks > 1 ? 's' : ''} ago`;
  }
  const months = Math.floor(diffDays / 30);
  return `${months} month${months > 1 ? 's' : ''} ago`;
};

// Animation constants
const CARD_ANIMATION_DURATION = 300; // 300ms per card
const CARD_ANIMATION_STAGGER = 50; // 50ms stagger between cards

// Exit animation constants
const EXIT_ANIMATION_DURATION = 300;

// Animated habit card component
interface AnimatedHabitCardProps {
  habit: {
    _id: Id<'habits'>;
    name: string;
    icon?: string;
    iconColor?: string;
    strength?: number;
    currentStreak?: number;
    totalCompletions?: number;
    archivedAt?: number;
    _creationTime: number;
  };
  index: number;
  reducedMotion: boolean;
  onRestore: (id: Id<'habits'>, name: string) => Promise<boolean>;
  onDelete: (id: Id<'habits'>, name: string) => void;
}

function AnimatedHabitCard({
  habit,
  index,
  reducedMotion,
  onRestore,
  onDelete,
}: AnimatedHabitCardProps) {
  const [isRestoring, setIsRestoring] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  const cardOpacity = useSharedValue(reducedMotion ? 1 : 0);
  const cardTranslateY = useSharedValue(reducedMotion ? 0 : 20);
  const cardTranslateX = useSharedValue(0);
  const cardScale = useSharedValue(1);
  const successScale = useSharedValue(0);

  useEffect(() => {
    if (reducedMotion) {
      // Instant appearance for reduced motion
      cardOpacity.value = 1;
      cardTranslateY.value = 0;
      return;
    }

    const delay = index * CARD_ANIMATION_STAGGER;

    cardOpacity.value = withDelay(
      delay,
      withTiming(1, { duration: CARD_ANIMATION_DURATION, easing: Easing.out(Easing.cubic) })
    );
    cardTranslateY.value = withDelay(
      delay,
      withSpring(0, { damping: 18, stiffness: 120 })
    );

    return () => {
      cancelAnimation(cardOpacity);
      cancelAnimation(cardTranslateY);
    };
  }, [index, reducedMotion, cardOpacity, cardTranslateY]);

  // Handle restore with exit animation
  const handleRestorePress = useCallback(async () => {
    if (isRestoring) return;

    setIsRestoring(true);

    // Call restore and check success
    const success = await onRestore(habit._id, habit.name);

    if (success) {
      setShowSuccess(true);

      // Show success checkmark animation
      successScale.value = withSequence(
        withSpring(1.2, { damping: 10, stiffness: 200 }),
        withSpring(1, { damping: 15, stiffness: 150 })
      );

      // Exit animation after brief success display
      setTimeout(() => {
        if (reducedMotion) {
          // Instant removal for reduced motion
          cardOpacity.value = 0;
        } else {
          // Smooth slide out to right with fade
          cardTranslateX.value = withTiming(100, {
            duration: EXIT_ANIMATION_DURATION,
            easing: Easing.out(Easing.cubic)
          });
          cardOpacity.value = withTiming(0, {
            duration: EXIT_ANIMATION_DURATION,
            easing: Easing.out(Easing.cubic)
          });
          cardScale.value = withTiming(0.95, {
            duration: EXIT_ANIMATION_DURATION,
            easing: Easing.out(Easing.cubic)
          });
        }
      }, 400); // Show success state for 400ms before animating out
    } else {
      setIsRestoring(false);
    }
  }, [habit._id, habit.name, isRestoring, onRestore, reducedMotion, cardOpacity, cardTranslateX, cardScale, successScale]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: cardOpacity.value,
    transform: [
      { translateY: cardTranslateY.value },
      { translateX: cardTranslateX.value },
      { scale: cardScale.value },
    ],
  }));

  const successIconStyle = useAnimatedStyle(() => ({
    transform: [{ scale: successScale.value }],
  }));

  const strength = (habit.strength ?? 0) * 100;
  const strengthInfo = getStrengthInfo(strength);
  const gradientColor = getStrengthGradientColor(strength);
  const archiveDate = habit.archivedAt || habit._creationTime;

  return (
    <Animated.View style={animatedStyle}>
      <View
        className='overflow-hidden rounded-2xl border border-stone-200 bg-white'
        style={{
          shadowColor: '#000',
          shadowOffset: { width: 0, height: 2 },
          shadowOpacity: 0.05,
          shadowRadius: 8,
          elevation: 2,
        }}
      >
        {/* Strength Fill Background */}
        <View className='absolute inset-0' style={{ width: `${Math.min(strength, 100)}%` }}>
          <LinearGradient
            colors={[`${gradientColor}20`, `${gradientColor}08`, `${gradientColor}00`]}
            start={{ x: 0, y: 0.5 }}
            end={{ x: 1, y: 0.5 }}
            style={{ flex: 1 }}
          />
        </View>

        <View className='relative p-4'>
          {/* Top Row: Icon, Name, Archive Date */}
          <View className='mb-3 flex-row items-start'>
            <View className='flex-row items-center gap-3'>
              {/* Color Accent Bar + Icon */}
              <View className='relative'>
                <View
                  className='absolute bottom-0 left-0 top-0 w-1 rounded-full'
                  style={{ backgroundColor: habit.iconColor || '#6366F1' }}
                />
                <Text className='pl-3 text-2xl'>{habit.icon || '📝'}</Text>
              </View>
              <View className='flex-1'>
                <Text className='text-base font-semibold text-stone-900'>
                  {habit.name}
                </Text>
                <View className='mt-0.5 flex-row items-center gap-1'>
                  <Text className='text-xs text-stone-400'>
                    Archived {new Date(archiveDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                  </Text>
                  <Text className='text-stone-300'>•</Text>
                  <Text className='text-xs text-stone-400'>
                    {getRelativeTime(archiveDate)}
                  </Text>
                </View>
              </View>
            </View>
          </View>

          {/* Stats Row */}
          <View className='mb-3 flex-row flex-wrap gap-2'>
            {/* Strength Badge */}
            <View className={`flex-row items-center gap-1.5 rounded-lg px-2.5 py-1 ${strengthInfo.bgColor}`}>
              <Text className='text-sm'>{strengthInfo.emoji}</Text>
              <Text className={`text-xs font-semibold ${strengthInfo.textColor}`}>
                {Math.round(strength)}% {strengthInfo.label}
              </Text>
            </View>

            {/* Streak Badge */}
            {(habit.currentStreak ?? 0) > 0 ? (
              <View className='flex-row items-center gap-1.5 rounded-lg bg-amber-50 px-2.5 py-1'>
                <Text className='text-sm'>🔥</Text>
                <Text className='text-xs font-semibold text-amber-700'>
                  {habit.currentStreak} day streak
                </Text>
              </View>
            ) : (
              <View className='flex-row items-center gap-1.5 rounded-lg bg-stone-100 px-2.5 py-1'>
                <Text className='text-sm'>🔥</Text>
                <Text className='text-xs font-semibold text-stone-500'>
                  No streak
                </Text>
              </View>
            )}

            {/* Total Completions Badge */}
            {(habit.totalCompletions ?? 0) > 0 && (
              <View className='flex-row items-center gap-1.5 rounded-lg bg-blue-50 px-2.5 py-1'>
                <Text className='text-xs font-bold text-blue-600'>✓</Text>
                <Text className='text-xs font-semibold text-blue-700'>
                  {habit.totalCompletions} total
                </Text>
              </View>
            )}
          </View>

          {/* Action Buttons */}
          <View className='flex-row gap-2'>
            <TouchableOpacity
              accessibilityLabel={`Restore ${habit.name}`}
              accessibilityRole='button'
              disabled={isRestoring}
              className={`flex-1 flex-row items-center justify-center gap-2 rounded-xl border-2 py-2.5 ${
                showSuccess
                  ? 'border-emerald-500 bg-emerald-50'
                  : isRestoring
                    ? 'border-blue-300 opacity-70'
                    : 'border-blue-500'
              }`}
              onPress={handleRestorePress}
            >
              {showSuccess ? (
                <Animated.View style={successIconStyle} className='flex-row items-center gap-2'>
                  <View className='h-5 w-5 items-center justify-center rounded-full bg-emerald-500'>
                    <Check color='#ffffff' size={14} strokeWidth={3} />
                  </View>
                  <Text className='text-xs font-bold tracking-wide text-emerald-600'>
                    RESTORED!
                  </Text>
                </Animated.View>
              ) : (
                <>
                  <Text className={isRestoring ? 'text-blue-300' : 'text-blue-500'}>↩</Text>
                  <Text className={`text-xs font-bold tracking-wide ${isRestoring ? 'text-blue-300' : 'text-blue-500'}`}>
                    {isRestoring ? 'RESTORING...' : 'RESTORE'}
                  </Text>
                </>
              )}
            </TouchableOpacity>
            <TouchableOpacity
              accessibilityLabel={`Permanently delete ${habit.name}`}
              accessibilityRole='button'
              disabled={isRestoring}
              className={`flex-1 flex-row items-center justify-center gap-2 rounded-xl border-2 border-red-400 py-2.5 ${
                isRestoring ? 'opacity-50' : ''
              }`}
              onPress={() => onDelete(habit._id, habit.name)}
            >
              <Text className='text-red-400'>🗑</Text>
              <Text className='text-xs font-bold tracking-wide text-red-400'>
                DELETE
              </Text>
            </TouchableOpacity>
          </View>
        </View>
      </View>
    </Animated.View>
  );
}

export default function ArchivedHabitsModal({
  onClose,
  onBack,
}: ArchivedHabitsModalProps) {
  const insets = useSafeAreaInsets();
  const reducedMotion = useReduceMotion();
  const { archivedHabits, handleRestore, handlePermanentDelete } =
    useArchivedHabitsModalLogic();

  return (
    <>
      {/* Header - dynamic padding for Dynamic Island/notch with subtle blur */}
      <BlurView
        intensity={20}
        tint='light'
        style={{
          paddingTop: insets.top + 8,
          paddingHorizontal: 0,
          paddingBottom: 8,
        }}
      >
        <View className='mb-2 flex-row items-center justify-between'>
          <TouchableOpacity
            accessibilityLabel='Back to settings'
            accessibilityRole='button'
            className='h-11 w-11 items-center justify-center rounded-2xl bg-stone-100/80'
            onPress={onBack}
            style={{
              shadowColor: '#000',
              shadowOffset: { width: 0, height: 1 },
              shadowOpacity: 0.05,
              shadowRadius: 3,
              elevation: 1,
            }}
          >
            <ChevronLeft color='#57534e' size={24} strokeWidth={2} />
          </TouchableOpacity>
          <Text className='flex-1 text-center text-xl font-bold text-stone-900'>
            Archived Habits
          </Text>
          <TouchableOpacity
            accessibilityLabel='Close'
            accessibilityRole='button'
            className='h-11 w-11 items-center justify-center rounded-2xl bg-stone-100/80'
            onPress={onClose}
            style={{
              shadowColor: '#000',
              shadowOffset: { width: 0, height: 1 },
              shadowOpacity: 0.05,
              shadowRadius: 3,
              elevation: 1,
            }}
          >
            <X color='#78716c' size={22} strokeWidth={2} />
          </TouchableOpacity>
        </View>
      </BlurView>

      {/* Stats Summary Bar */}
      {archivedHabits.length > 0 && (
        <View className='mb-4 flex-row items-center justify-between rounded-xl bg-stone-50 px-4 py-3'>
          <View className='flex-row items-center gap-2'>
            <Text className='text-lg'>📦</Text>
            <Text className='text-sm font-medium text-stone-600'>
              {archivedHabits.length} archived habit{archivedHabits.length !== 1 ? 's' : ''}
            </Text>
          </View>
        </View>
      )}

      <ScrollView
        className='flex-1'
        showsVerticalScrollIndicator={false}
        contentContainerStyle={{ paddingBottom: insets.bottom + 16 }}
      >
        {archivedHabits.length === 0 ? (
          /* Empty State */
          <View className='items-center justify-center px-6 py-16'>
            {/* Illustration - using plant/growth metaphor for warmth */}
            <View className='mb-6 items-center'>
              <View className='relative'>
                <View className='h-28 w-32 items-center justify-center rounded-2xl bg-gradient-to-br from-emerald-50 to-teal-100'>
                  <Text className='mt-2 text-5xl'>🌱</Text>
                </View>
                {/* Sparkles - repositioned for balance */}
                <Text className='absolute -right-3 -top-3 text-xl'>🌟</Text>
                <Text className='absolute -bottom-2 -left-3 text-lg'>✨</Text>
              </View>
            </View>

            {/* Text Content - warmer, more encouraging copy */}
            <Text className='mb-2 text-center text-2xl font-bold tracking-tight text-stone-900'>
              Your Habits Are Thriving!
            </Text>
            <Text className='mb-1 text-center text-base text-stone-500'>
              All your habits are active and growing.
            </Text>
            <Text className='mb-6 max-w-xs text-center text-sm text-stone-400'>
              When you need a break from a habit, swipe left to archive it here for safekeeping.
            </Text>

            {/* Pro Tip Card - warmer color scheme */}
            <View className='w-full max-w-xs rounded-2xl border border-emerald-100 bg-emerald-50 p-4'>
              <View className='flex-row items-start gap-3'>
                <Text className='text-2xl'>💚</Text>
                <View className='flex-1'>
                  <Text className='mb-1 text-sm font-medium text-emerald-800'>Good to Know</Text>
                  <Text className='text-xs leading-5 text-emerald-700'>
                    Archiving preserves all your progress and streaks. You can restore habits anytime and pick up right where you left off!
                  </Text>
                </View>
              </View>
            </View>
          </View>
        ) : (
          /* Habit Cards with staggered entrance animations */
          <View className='gap-3'>
            {archivedHabits.map((habit, index) => (
              <AnimatedHabitCard
                key={habit._id}
                habit={habit}
                index={index}
                reducedMotion={reducedMotion}
                onRestore={handleRestore}
                onDelete={handlePermanentDelete}
              />
            ))}
          </View>
        )}
      </ScrollView>
    </>
  );
}

/**
 * BinaryCell Component
 *
 * Individual cell in the GitHub-style binary heatmap.
 * Displays a simple colored square (done = habit color, missed = gray).
 *
 * Cell states:
 * - done: Habit completed (habit color)
 * - missed: Habit not completed (gray)
 * - today: Current day (ring outline in habit color)
 * - future: Future date (faded)
 * - beforeCreation: Before habit was created (very faded)
 */

import React, { memo, useCallback } from 'react';
import { View, Pressable, StyleSheet, Platform } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  FadeIn,
} from 'react-native-reanimated';

import type { BinaryCellProps } from './types';
import { getCellState, getBinaryCellAccessibilityLabel } from './utils';
import {
  CELL_SIZE,
  CELL_BORDER_RADIUS,
  ANIMATION,
  COLORS,
  FOCUS,
} from './constants';
import { useReduceMotion } from '../../hooks/useReduceMotion';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

/**
 * BinaryCell - A single cell in the binary heatmap grid
 *
 * This component renders a small square that represents a single day
 * in the habit tracking grid. It uses binary (on/off) visualization:
 * - Completed days show in the habit's accent color
 * - Missed days show in gray
 * - Today has a ring outline
 * - Future dates are faded
 */
export const BinaryCell = memo(function BinaryCell({
  day,
  index,
  habitColor,
  onPress,
}: BinaryCellProps) {
  const scale = useSharedValue(1);
  const reduceMotion = useReduceMotion();

  // Calculate animation delay based on cell position
  const staggerDelay = reduceMotion ? 0 : index * ANIMATION.CELL_STAGGER_DELAY;

  // Animated scale style for tap feedback
  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  // Handle press in - scale down for tap feedback
  const handlePressIn = useCallback(() => {
    if (day && !day.isFuture && !day.isBeforeCreation && !reduceMotion) {
      scale.value = withSpring(ANIMATION.TAP_SCALE, { damping: 15 });
    }
  }, [day, reduceMotion, scale]);

  // Handle press out - scale back to normal
  const handlePressOut = useCallback(() => {
    if (!reduceMotion) {
      scale.value = withSpring(1, { damping: 15 });
    }
  }, [reduceMotion, scale]);

  // Handle press - call onPress callback
  const handlePress = useCallback(() => {
    if (day && onPress && !day.isFuture && !day.isBeforeCreation) {
      onPress(day.date, day.completed);
    }
  }, [day, onPress]);

  // Generate accessibility label
  const accessibilityLabel = getBinaryCellAccessibilityLabel(day);

  // Fade-in animation (respects reduced motion)
  const fadeInAnimation = reduceMotion
    ? undefined
    : FadeIn.delay(staggerDelay).duration(ANIMATION.CELL_FADE_DURATION);

  // Empty padding cell (null day)
  if (day === null) {
    return (
      <Animated.View
        accessible
        accessibilityLabel={accessibilityLabel}
        accessibilityRole='text'
        entering={fadeInAnimation}
        style={styles.cell}
      />
    );
  }

  // Determine the visual state
  const cellState = getCellState(day);

  // Get the background color based on state
  const getBackgroundColor = (): string => {
    switch (cellState) {
      case 'done':
        return habitColor;
      case 'today':
        return day.completed ? habitColor : 'transparent';
      case 'missed':
        return COLORS.CELL_EMPTY;
      case 'future':
        return COLORS.CELL_FUTURE;
      case 'beforeCreation':
        return COLORS.CELL_BEFORE_CREATION;
      default:
        return COLORS.CELL_EMPTY;
    }
  };

  // Determine if this cell is interactive (can be pressed)
  const isInteractive = !day.isFuture && !day.isBeforeCreation;

  // Non-interactive cells (future, beforeCreation)
  if (!isInteractive) {
    return (
      <Animated.View
        accessible
        accessibilityLabel={accessibilityLabel}
        accessibilityRole='text'
        entering={fadeInAnimation}
        style={[
          styles.cell,
          styles.cellInner,
          { backgroundColor: getBackgroundColor() },
          cellState === 'future' && styles.futureCell,
        ]}
      />
    );
  }

  // Interactive cells (done, missed, today)
  // Simplified rendering - apply background directly to avoid nested View issues
  const bgColor = getBackgroundColor();

  return (
    <Animated.View
      accessible
      accessibilityHint={day.isToday ? 'Today' : 'Tap to toggle completion'}
      accessibilityLabel={accessibilityLabel}
      accessibilityRole='button'
      accessibilityState={{ selected: day.completed }}
      entering={fadeInAnimation}
      style={[
        styles.cell,
        styles.cellInner,
        { backgroundColor: bgColor },
        // Today ring effect
        cellState === 'today' && {
          borderColor: habitColor,
          borderWidth: COLORS.TODAY_RING_WIDTH,
          backgroundColor: day.completed ? bgColor : COLORS.CARD_BACKGROUND,
        },
      ]}
    />
  );
});

const styles = StyleSheet.create({
  cell: {
    alignItems: 'center',
    height: CELL_SIZE,
    justifyContent: 'center',
    width: CELL_SIZE,
  },
  cellInner: {
    borderRadius: CELL_BORDER_RADIUS,
    height: CELL_SIZE,
    width: CELL_SIZE,
  },
  futureCell: {
    opacity: 0.4,
  },
  // Web-specific focus styles for keyboard navigation
  webFocus: {
    borderColor: FOCUS.RING_COLOR,
    borderRadius: CELL_BORDER_RADIUS + FOCUS.RING_OFFSET,
    borderWidth: FOCUS.RING_WIDTH,
    outlineColor: FOCUS.RING_COLOR,
    outlineOffset: FOCUS.RING_OFFSET,
    outlineStyle: 'solid',
    outlineWidth: FOCUS.RING_WIDTH,
  },
  // Web-specific hover styles (applied via spread)
  webHover: {
    cursor: 'pointer',
  },
});

export default BinaryCell;

/**
 * BinaryHeatmapGrid Component
 *
 * Renders the main 7-row grid for the GitHub-style binary heatmap.
 * Each row represents a day of the week (Sunday through Saturday),
 * and each column represents a week in the selected time range.
 *
 * Layout:
 * - Day labels column (S/M/T/W/T/F/S) on the left
 * - Horizontally scrollable grid of BinaryCell components
 * - Cells are organized by row (day-of-week) for proper layout
 *
 * Performance Optimizations:
 * - Uses React.memo() on GridRow and BinaryHeatmapGrid components
 * - Memoizes row transformation via useMemo()
 * - Stable callback references via useCallback()
 * - Key stability: uses date strings or stable position-based keys
 * - No virtualization needed: max 364 cells (1y) is well within efficient render limits
 */

import React, { memo, useMemo, useCallback } from 'react';
import { View, Text, ScrollView, StyleSheet } from 'react-native';

import type { BinaryHeatmapGridProps, BinaryDay } from './types';
// Force Metro rebuild - timestamp: 2025-12-30T22:00
import { BinaryCell } from './BinaryCell';
import { MonthLabelsRow } from './MonthLabelsRow';
import {
  CELL_SIZE,
  CELL_GAP,
  DAY_LABEL_WIDTH,
  DAY_LABELS,
  COLORS,
  GRID,
  MONTH_LABEL,
} from './constants';
import { calculateCellAnimationDelay } from './utils';

/**
 * Memoized row component to prevent unnecessary re-renders of entire rows
 * when only a single cell changes. Each row renders cells for a specific
 * day of the week (Sunday=0 through Saturday=6).
 */
interface GridRowProps {
  dayIndex: number;
  row: (BinaryDay | null)[];
  habitColor: string;
  onCellPress: (date: string, completed: boolean) => void;
}

// Inline cell rendering to bypass Metro caching issues with BinaryCell
const GridRow = memo(function GridRow({
  dayIndex,
  row,
  habitColor,
  onCellPress,
}: GridRowProps) {
  return (
    <View accessibilityRole='row' style={styles.gridRow}>
      {row.map((day, weekIndex) => {
        // Determine background color inline
        let bgColor = COLORS.CELL_EMPTY;
        if (day === null) {
          bgColor = 'transparent';
        } else if (day.isBeforeCreation) {
          bgColor = COLORS.CELL_BEFORE_CREATION;
        } else if (day.isFuture) {
          bgColor = COLORS.CELL_FUTURE;
        } else if (day.completed) {
          bgColor = habitColor;
        }

        return (
          <View
            key={day?.date ?? `empty-${dayIndex}-${weekIndex}`}
            style={[
              styles.cellWrapper,
              {
                width: CELL_SIZE,
                height: CELL_SIZE,
                borderRadius: 2,
                backgroundColor: bgColor,
                opacity: day?.isFuture ? 0.4 : 1,
              },
              // Today ring
              day?.isToday && {
                borderWidth: 2,
                borderColor: habitColor,
              },
            ]}
          />
        );
      })}
    </View>
  );
});

/**
 * BinaryHeatmapGrid - The main grid component for the binary heatmap
 *
 * This component transforms the week-based data structure into a row-based
 * layout for rendering. Each row represents a day of the week (0=Sunday through
 * 6=Saturday), and each column represents a week from the time range.
 *
 * The grid scrolls horizontally to accommodate larger time ranges (6m, 1y).
 */
export const BinaryHeatmapGrid = memo(function BinaryHeatmapGrid({
  gridData,
  habitColor,
  onCellPress,
}: BinaryHeatmapGridProps) {
  const { weeks, monthLabels } = gridData;

  // Transform week-based data to row-based for rendering
  // weeks[weekIndex][dayIndex] -> rows[dayIndex][weekIndex]
  const rows = useMemo(() => {
    const result: (BinaryDay | null)[][] = [];

    // Initialize 7 empty rows (one for each day of week)
    for (let dayIndex = 0; dayIndex < GRID.ROWS; dayIndex++) {
      result[dayIndex] = [];
    }

    // Transpose: for each week, extract the day at each position
    for (const [weekIndex, week] of weeks.entries()) {
      for (let dayIndex = 0; dayIndex < GRID.ROWS; dayIndex++) {
        // Get the day from this week, or null if not present
        result[dayIndex][weekIndex] = week[dayIndex] ?? null;
      }
    }

    return result;
  }, [weeks]);

  // Handle cell press with day data
  const handleCellPress = useCallback(
    (date: string, completed: boolean) => {
      onCellPress?.(date, completed);
    },
    [onCellPress]
  );

  // Calculate total width for the scrollable content
  const gridContentWidth = weeks.length * (CELL_SIZE + CELL_GAP);

  return (
    <View style={styles.container}>
      {/* Day labels column */}
      <View style={styles.dayLabelsColumn}>
        {/* Spacer for month labels row alignment */}
        <View style={styles.monthLabelSpacer} />

        {DAY_LABELS.map((label, index) => (
          <View key={`label-${index}`} style={styles.dayLabelCell}>
            <Text
              accessible
              accessibilityLabel={`${getDayFullName(index)} row`}
              accessibilityRole='text'
              style={styles.dayLabelText}
            >
              {label}
            </Text>
          </View>
        ))}
      </View>

      {/* Scrollable grid area */}
      <ScrollView
        horizontal
        accessibilityLabel='Habit completion heatmap grid'
        accessibilityRole='grid'
        contentContainerStyle={[
          styles.gridScrollContent,
          { width: gridContentWidth },
        ]}
        showsHorizontalScrollIndicator={false}
      >
        <View style={styles.gridContentContainer}>
          {/* Month labels row above the grid */}
          <MonthLabelsRow
            gridWidth={gridContentWidth}
            monthLabels={monthLabels}
          />

          {/* Grid cells */}
          <View style={styles.gridContainer}>
            {rows.map((row, dayIndex) => (
              <GridRow
                key={`row-${dayIndex}`}
                dayIndex={dayIndex}
                habitColor={habitColor}
                row={row}
                onCellPress={handleCellPress}
              />
            ))}
          </View>
        </View>
      </ScrollView>
    </View>
  );
});

/**
 * Get the full day name for accessibility
 */
function getDayFullName(dayIndex: number): string {
  const fullNames = [
    'Sunday',
    'Monday',
    'Tuesday',
    'Wednesday',
    'Thursday',
    'Friday',
    'Saturday',
  ];
  return fullNames[dayIndex] || '';
}

const styles = StyleSheet.create({
  cellWrapper: {
    marginRight: CELL_GAP,
  },
  container: {
    flexDirection: 'row',
  },
  dayLabelCell: {
    height: CELL_SIZE,
    justifyContent: 'center',
    marginBottom: CELL_GAP,
  },
  dayLabelsColumn: {
    marginRight: CELL_GAP,
    width: DAY_LABEL_WIDTH,
  },
  dayLabelText: {
    color: COLORS.TEXT_SECONDARY,
    fontSize: 10,
    fontWeight: '500',
    paddingRight: 4,
    textAlign: 'right',
  },
  gridContainer: {
    flexDirection: 'column',
  },
  gridContentContainer: {
    flexDirection: 'column',
  },
  gridRow: {
    flexDirection: 'row',
    marginBottom: CELL_GAP,
  },
  gridScrollContent: {
    flexGrow: 1,
  },
  monthLabelSpacer: {
    height: MONTH_LABEL.HEIGHT + CELL_GAP,
  },
});

export default BinaryHeatmapGrid;

