/**
 * BinaryHeatmap Component
 *
 * Main container component for the GitHub-style binary heatmap.
 * Grid rendering is inline to avoid Metro caching issues with child components.
 */

import React, { memo, useState, useMemo, useCallback, useRef } from 'react';
import { View, StyleSheet, Text, ScrollView } from 'react-native';

import type { BinaryHeatmapProps, TimeRange, BinaryDay } from './types';
import { HeatmapLegend } from './HeatmapLegend';
import { HeatmapTooltip } from './HeatmapTooltip';
import { generateBinaryGrid } from './utils';
import { COLORS, CELL_SIZE, CELL_GAP, DAY_LABEL_WIDTH, GRID, MONTH_LABEL } from './constants';

const FIXED_TIME_RANGE: TimeRange = '6m';
const DAY_LABELS = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];

export const BinaryHeatmap = memo(function BinaryHeatmap({
  habitId: _habitId,
  completedDates,
  habitCreatedAt,
  habitColor,
  currentStreak: _currentStreak,
  onDayPress,
}: BinaryHeatmapProps) {
  const [tooltipDay, setTooltipDay] = useState<BinaryDay | null>(null);
  const [tooltipPosition, setTooltipPosition] = useState({ x: 0, y: 0 });
  const [tooltipVisible, setTooltipVisible] = useState(false);

  const gridData = useMemo(
    () => generateBinaryGrid(FIXED_TIME_RANGE, completedDates, habitCreatedAt),
    [completedDates, habitCreatedAt]
  );

  // Transform weeks to rows (day-of-week based)
  const rows = useMemo(() => {
    const result: (BinaryDay | null)[][] = [];
    for (let dayIndex = 0; dayIndex < GRID.ROWS; dayIndex++) {
      result[dayIndex] = [];
    }
    for (const week of gridData.weeks) {
      for (let dayIndex = 0; dayIndex < GRID.ROWS; dayIndex++) {
        result[dayIndex].push(week[dayIndex] ?? null);
      }
    }
    return result;
  }, [gridData.weeks]);

  const dayLookupMap = useMemo(() => {
    const map = new Map<string, BinaryDay>();
    for (const week of gridData.weeks) {
      for (const day of week) {
        if (day !== null) {
          map.set(day.date, day);
        }
      }
    }
    return map;
  }, [gridData.weeks]);

  const onDayPressRef = useRef(onDayPress);
  onDayPressRef.current = onDayPress;
  const dayLookupMapRef = useRef(dayLookupMap);
  dayLookupMapRef.current = dayLookupMap;

  const handleCellPress = useCallback((date: string, completed: boolean) => {
    const day = dayLookupMapRef.current.get(date);
    if (day) {
      setTooltipDay(day);
      setTooltipPosition({ x: 100, y: 50 });
      setTooltipVisible(true);
    }
    onDayPressRef.current?.(date, completed);
  }, []);

  const handleTooltipClose = useCallback(() => {
    setTooltipVisible(false);
    setTooltipDay(null);
  }, []);

  // Calculate grid width
  const gridContentWidth = gridData.weeks.length * (CELL_SIZE + CELL_GAP);

  return (
    <View style={styles.container}>
      {/* DEBUG: Orange bar to confirm this code is running */}
      <View style={{ backgroundColor: '#FF6600', height: 8, marginBottom: 4 }} />

      {/* Header */}
      <View style={styles.header}>
        <Text style={styles.headerTitle}>Activity</Text>
      </View>

      {/* Grid - rendered inline */}
      <View style={styles.gridWrapper}>
        <View style={styles.gridContainer}>
          {/* Day labels column */}
          <View style={styles.dayLabelsColumn}>
            <View style={styles.monthLabelSpacer} />
            {DAY_LABELS.map((label, index) => (
              <View key={`label-${index}`} style={styles.dayLabelCell}>
                <Text style={styles.dayLabelText}>{label}</Text>
              </View>
            ))}
          </View>

          {/* Scrollable grid */}
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={{ width: gridContentWidth }}
          >
            <View>
              {/* Month labels */}
              <View style={styles.monthLabelsRow}>
                {gridData.monthLabels.map((ml, i) => (
                  <Text
                    key={`month-${i}`}
                    style={[
                      styles.monthLabel,
                      { left: ml.weekIndex * (CELL_SIZE + CELL_GAP) },
                    ]}
                  >
                    {ml.label}
                  </Text>
                ))}
              </View>

              {/* Grid rows - inline styles like working test */}
              {rows.map((row, dayIndex) => (
                <View key={`row-${dayIndex}`} style={{ flexDirection: 'row', marginBottom: CELL_GAP }}>
                  {row.map((day, weekIndex) => {
                    // Determine background color
                    let bgColor = COLORS.CELL_EMPTY;
                    if (day === null) {
                      bgColor = 'transparent';
                    } else if (day.isBeforeCreation) {
                      bgColor = COLORS.CELL_BEFORE_CREATION;
                    } else if (day.isFuture) {
                      bgColor = COLORS.CELL_FUTURE;
                    } else if (day.completed) {
                      bgColor = habitColor;
                    }

                    return (
                      <View
                        key={day?.date ?? `empty-${dayIndex}-${weekIndex}`}
                        style={{
                          width: CELL_SIZE,
                          height: CELL_SIZE,
                          marginRight: CELL_GAP,
                          borderRadius: 2,
                          backgroundColor: bgColor,
                          opacity: day?.isFuture ? 0.4 : 1,
                          borderWidth: day?.isToday ? 2 : 0,
                          borderColor: day?.isToday ? habitColor : 'transparent',
                        }}
                      />
                    );
                  })}
                </View>
              ))}
            </View>
          </ScrollView>
        </View>
      </View>

      {/* Legend */}
      <HeatmapLegend
        completionRate={gridData.stats.completionRate}
        habitColor={habitColor}
      />

      {/* Tooltip */}
      {tooltipDay && (
        <HeatmapTooltip
          day={tooltipDay}
          position={tooltipPosition}
          visible={tooltipVisible}
          onClose={handleTooltipClose}
        />
      )}
    </View>
  );
});

const styles = StyleSheet.create({
  cell: {
    borderRadius: 2,
    height: CELL_SIZE,
    marginRight: CELL_GAP,
    width: CELL_SIZE,
  },
  container: {
    backgroundColor: COLORS.CARD_BACKGROUND,
    borderRadius: 12,
    padding: 16,
  },
  dayLabelCell: {
    height: CELL_SIZE,
    justifyContent: 'center',
    marginBottom: CELL_GAP,
  },
  dayLabelsColumn: {
    marginRight: CELL_GAP,
    width: DAY_LABEL_WIDTH,
  },
  dayLabelText: {
    color: COLORS.TEXT_SECONDARY,
    fontSize: 10,
    fontWeight: '500',
    textAlign: 'right',
  },
  gridContainer: {
    flexDirection: 'row',
  },
  gridRow: {
    flexDirection: 'row',
    marginBottom: CELL_GAP,
  },
  gridWrapper: {
    marginTop: 12,
  },
  header: {
    alignItems: 'center',
    flexDirection: 'row',
    justifyContent: 'space-between',
  },
  headerTitle: {
    color: COLORS.TEXT_PRIMARY,
    fontSize: 14,
    fontWeight: '600',
  },
  monthLabel: {
    color: COLORS.TEXT_SECONDARY,
    fontSize: 10,
    position: 'absolute',
  },
  monthLabelsRow: {
    height: MONTH_LABEL.HEIGHT,
    marginBottom: CELL_GAP,
    position: 'relative',
  },
  monthLabelSpacer: {
    height: MONTH_LABEL.HEIGHT + CELL_GAP,
  },
});

export default BinaryHeatmap;

/**
 * HeatmapLegend Component
 *
 * A simple binary legend for the GitHub-style heatmap.
 * Shows "Missed" (gray) and "Done" (habit color) indicators
 * with a completion percentage.
 *
 * Layout per spec:
 * [○ Missed] [● Done]          86% completion
 */

import React, { memo } from 'react';
import { View, Text, StyleSheet } from 'react-native';

import type { HeatmapLegendProps } from './types';
import { LEGEND_INDICATOR_SIZE, COLORS, CELL_BORDER_RADIUS } from './constants';

/**
 * Format completion rate as a rounded percentage string
 */
const formatCompletionRate = (rate: number): string => {
  return `${Math.round(rate)}%`;
};

/**
 * HeatmapLegend - Displays the binary legend for the heatmap
 *
 * This component shows two indicators:
 * - Missed: gray square indicating days the habit was not completed
 * - Done: colored square (using habit color) indicating completed days
 *
 * Also displays the overall completion percentage for the visible period.
 */
export const HeatmapLegend = memo(function HeatmapLegend({
  habitColor,
  completionRate,
}: HeatmapLegendProps) {
  return (
    <View
      accessible
      accessibilityLabel={`Legend: Gray for missed days, colored for completed days. ${formatCompletionRate(completionRate)} completion rate`}
      accessibilityRole='text'
      style={styles.container}
    >
      {/* Left side: Legend indicators */}
      <View style={styles.indicators}>
        {/* Missed indicator */}
        <View
          accessible
          accessibilityLabel='Missed: gray'
          accessibilityRole='text'
          style={styles.indicator}
        >
          <View
            style={[
              styles.indicatorSquare,
              { backgroundColor: COLORS.CELL_EMPTY },
            ]}
          />
          <Text style={styles.indicatorLabel}>Missed</Text>
        </View>

        {/* Done indicator */}
        <View
          accessible
          accessibilityLabel='Done: colored'
          accessibilityRole='text'
          style={styles.indicator}
        >
          <View
            style={[styles.indicatorSquare, { backgroundColor: habitColor }]}
          />
          <Text style={styles.indicatorLabel}>Done</Text>
        </View>
      </View>

      {/* Right side: Completion percentage */}
      <Text
        accessible
        accessibilityLabel={`${formatCompletionRate(completionRate)} completion`}
        accessibilityRole='text'
        style={[styles.completionText, { color: habitColor }]}
      >
        {formatCompletionRate(completionRate)} compl
      </Text>
    </View>
  );
});

const styles = StyleSheet.create({
  completionText: {
    fontSize: 12,
    fontWeight: '600',
  },
  container: {
    alignItems: 'center',
    flexDirection: 'row',
    justifyContent: 'space-between',
    paddingHorizontal: 4,
    paddingVertical: 8,
  },
  indicator: {
    alignItems: 'center',
    flexDirection: 'row',
    marginRight: 12,
  },
  indicatorLabel: {
    color: COLORS.TEXT_SECONDARY,
    fontSize: 11,
    marginLeft: 4,
  },
  indicators: {
    alignItems: 'center',
    flexDirection: 'row',
  },
  indicatorSquare: {
    borderRadius: CELL_BORDER_RADIUS,
    height: LEGEND_INDICATOR_SIZE,
    width: LEGEND_INDICATOR_SIZE,
  },
});

export default HeatmapLegend;

/**
 * HeatmapTooltip Component
 *
 * Tooltip that displays date and status information when hovering (web)
 * or long-pressing (mobile) a cell in the binary heatmap.
 *
 * Tooltip content examples per spec:
 * - "Dec 15: Done ✓"
 * - "Jul 7: Missed"
 * - "Dec 30: Today"
 * - "Jan 5: Future"
 *
 * Styling per spec:
 * - Background: #1c1917 (stone-900)
 * - Text: white, 11px, font-weight 500
 * - Padding: 6px 10px
 * - Border-radius: 6px
 * - Arrow pointing down
 */

import React, { memo, useEffect } from 'react';
import { View, Text, StyleSheet, Modal, Pressable } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withTiming,
  withSpring,
} from 'react-native-reanimated';

import type { HeatmapTooltipProps } from './types';
import { formatTooltipText } from './utils';
import { COLORS, TOOLTIP } from './constants';
import { useReduceMotion } from '../../hooks/useReduceMotion';

const AnimatedView = Animated.createAnimatedComponent(View);

/**
 * HeatmapTooltip - Shows date and completion status on hover/long-press
 *
 * This component renders a floating tooltip positioned above a cell.
 * It displays the date and completion status in a compact format.
 *
 * Features:
 * - Fade-in/out animation
 * - Arrow pointing to the cell below
 * - Modal overlay for dismissal
 * - Respects reduced motion preferences
 */
export const HeatmapTooltip = memo(function HeatmapTooltip({
  day,
  position,
  visible,
  onClose,
}: HeatmapTooltipProps) {
  const opacity = useSharedValue(0);
  const scale = useSharedValue(0.9);
  const reduceMotion = useReduceMotion();

  // Animation configuration
  const animationDuration = reduceMotion ? 0 : 150;

  // Handle visibility changes with animation
  useEffect(() => {
    if (visible) {
      opacity.value = withTiming(1, { duration: animationDuration });
      // Use withTiming when reduced motion is enabled, withSpring otherwise
      scale.value = reduceMotion
        ? withTiming(1, { duration: 0 })
        : withSpring(1, { damping: 20, stiffness: 300 });
    } else {
      opacity.value = withTiming(0, { duration: animationDuration });
      scale.value = withTiming(0.9, { duration: animationDuration });
    }
  }, [visible, opacity, scale, animationDuration, reduceMotion]);

  // Animated styles for fade and scale
  const animatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ scale: scale.value }],
  }));

  // Format the tooltip text using the utility function
  const tooltipText = formatTooltipText(day);

  // Don't render if not visible (after animation completes)
  if (!visible) {
    return null;
  }

  // Calculate tooltip position (centered above the cell)
  // Position.x and position.y represent the center-top of the target cell
  const tooltipStyle = {
    left: position.x,
    top: position.y - TOOLTIP.OFFSET,
  };

  return (
    <Modal
      transparent
      animationType='none'
      visible={visible}
      onRequestClose={onClose}
    >
      {/* Backdrop for dismissing tooltip */}
      <Pressable
        accessibilityHint='Tap anywhere to close tooltip'
        accessibilityLabel='Close tooltip'
        accessibilityRole='button'
        style={styles.backdrop}
        onPress={onClose}
      >
        {/* Tooltip container */}
        <AnimatedView
          accessible
          accessibilityLabel={tooltipText}
          accessibilityLiveRegion='polite'
          accessibilityRole='tooltip'
          style={[styles.tooltip, tooltipStyle, animatedStyle]}
        >
          {/* Tooltip content */}
          <Text style={styles.tooltipText}>{tooltipText}</Text>

          {/* Arrow pointing down */}
          <View style={styles.arrow} />
        </AnimatedView>
      </Pressable>
    </Modal>
  );
});

const styles = StyleSheet.create({
  arrow: {
    alignSelf: 'center',
    borderLeftColor: 'transparent',
    borderLeftWidth: TOOLTIP.ARROW_SIZE,
    borderRightColor: 'transparent',
    borderRightWidth: TOOLTIP.ARROW_SIZE,
    borderTopColor: COLORS.TOOLTIP_BACKGROUND,
    borderTopWidth: TOOLTIP.ARROW_SIZE,
    bottom: -TOOLTIP.ARROW_SIZE,
    height: 0,
    position: 'absolute',
    width: 0,
  },
  backdrop: {
    backgroundColor: 'transparent',
    flex: 1,
  },
  tooltip: {
    alignItems: 'center',
    backgroundColor: COLORS.TOOLTIP_BACKGROUND,
    borderRadius: TOOLTIP.BORDER_RADIUS,
    paddingHorizontal: TOOLTIP.PADDING_X,
    paddingVertical: TOOLTIP.PADDING_Y,
    position: 'absolute',
    // Transform to center the tooltip horizontally on the position point
    transform: [{ translateX: -50 }],
  },
  tooltipText: {
    color: COLORS.TOOLTIP_TEXT,
    fontSize: TOOLTIP.FONT_SIZE,
    fontWeight: '500',
  },
});

export default HeatmapTooltip;

/**
 * MonthLabelsRow Component
 *
 * Renders the month labels row above the binary heatmap grid.
 * Each label is positioned at the start of its corresponding month's first week.
 *
 * Layout:
 * - Labels are positioned absolutely based on week index
 * - Each label shows abbreviated month name (e.g., "Oct", "Nov", "Dec")
 * - Labels handle edge cases where months may span multiple weeks
 */

import React, { memo } from 'react';
import { View, Text, StyleSheet } from 'react-native';

import type { BinaryMonthLabel } from './types';
import { CELL_SIZE, CELL_GAP, COLORS, MONTH_LABEL } from './constants';

export interface MonthLabelsRowProps {
  /** Array of month labels with their starting week indices */
  monthLabels: BinaryMonthLabel[];

  /** Total width of the grid content (for container sizing) */
  gridWidth: number;
}

/**
 * MonthLabelsRow - Renders month labels above the heatmap grid
 *
 * Positions month labels at their corresponding week indices.
 * Labels are horizontally spaced to align with week columns.
 */
export const MonthLabelsRow = memo(function MonthLabelsRow({
  monthLabels,
  gridWidth,
}: MonthLabelsRowProps) {
  // Calculate the width of each cell + gap for positioning
  const cellUnit = CELL_SIZE + CELL_GAP;

  // If no labels, still render empty container for consistent spacing
  if (monthLabels.length === 0) {
    return (
      <View
        accessible
        accessibilityLabel='Month labels row'
        accessibilityRole='header'
        style={[styles.container, { width: gridWidth }]}
      />
    );
  }

  return (
    <View
      accessible
      accessibilityLabel='Month labels row'
      accessibilityRole='header'
      style={[styles.container, { width: gridWidth }]}
    >
      {monthLabels.map((monthLabel, index) => {
        // Calculate the left position based on week index
        const leftPosition = monthLabel.weekIndex * cellUnit;

        // Calculate width: extend to next month label or end of grid
        const nextLabelIndex = index + 1;
        const nextLeftPosition =
          nextLabelIndex < monthLabels.length
            ? monthLabels[nextLabelIndex].weekIndex * cellUnit
            : gridWidth;

        // Width is difference between positions, minimum of MIN_WIDTH
        const width = Math.max(
          nextLeftPosition - leftPosition,
          MONTH_LABEL.MIN_WIDTH
        );

        return (
          <View
            key={`month-${monthLabel.label}-${monthLabel.weekIndex}`}
            style={[
              styles.labelContainer,
              {
                left: leftPosition,
                width,
              },
            ]}
          >
            <Text
              accessible
              accessibilityLabel={`${getFullMonthName(monthLabel.label)} column`}
              accessibilityRole='text'
              style={styles.labelText}
            >
              {monthLabel.label}
            </Text>
          </View>
        );
      })}
    </View>
  );
});

/**
 * Get full month name from abbreviated label for accessibility
 */
function getFullMonthName(abbreviation: string): string {
  const monthMap: Record<string, string> = {
    Apr: 'April',
    Aug: 'August',
    Dec: 'December',
    Feb: 'February',
    Jan: 'January',
    Jul: 'July',
    Jun: 'June',
    Mar: 'March',
    May: 'May',
    Nov: 'November',
    Oct: 'October',
    Sep: 'September',
  };

  return monthMap[abbreviation] || abbreviation;
}

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    height: MONTH_LABEL.HEIGHT,
    marginBottom: CELL_GAP,
    position: 'relative',
  },
  labelContainer: {
    height: MONTH_LABEL.HEIGHT,
    justifyContent: 'flex-end',
    position: 'absolute',
    top: 0,
  },
  labelText: {
    color: COLORS.TEXT_SECONDARY,
    fontSize: MONTH_LABEL.FONT_SIZE,
    fontWeight: '500',
  },
});

export default MonthLabelsRow;

