/**
 * MonthlyCalendarGrid Component
 *
 * Full monthly calendar view with habit-colored completion indicators.
 * Uses inline styles for dynamic habit colors to avoid NativeWind conflicts.
 */

import React, { memo, useState, useMemo, useCallback } from 'react';
import { View, Text, Pressable, StyleSheet } from 'react-native';
import { ChevronLeft, ChevronRight, Calendar } from 'lucide-react-native';
import {
  format,
  startOfMonth,
  endOfMonth,
  eachDayOfInterval,
  isSameDay,
  startOfToday,
  addMonths,
  subMonths,
  isBefore,
  isAfter,
  startOfWeek,
  endOfWeek,
} from 'date-fns';
import type { Id } from '../../../convex/_generated/dataModel';

// Stone color palette
const COLORS = {
  TEXT_PRIMARY: '#1c1917',
  TEXT_SECONDARY: '#78716c',
  TEXT_TERTIARY: '#a8a29e',
  TEXT_MUTED: '#d6d3d1',
  BORDER: '#e7e5e4',
  CARD_BG: '#ffffff',
};

/**
 * Converts hex color to rgba with alpha
 */
function hexToRgba(hex: string, alpha: number): string {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  if (!result) return `rgba(16, 185, 129, ${alpha})`; // fallback emerald
  const r = parseInt(result[1], 16);
  const g = parseInt(result[2], 16);
  const b = parseInt(result[3], 16);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

interface DayData {
  date: Date;
  dateString: string;
  dayNumber: number;
  isCurrentMonth: boolean;
  isToday: boolean;
  isFuture: boolean;
  isBeforeCreation: boolean;
  isCompleted: boolean;
}

interface MonthlyCalendarGridProps {
  habitId: Id<'habits'>;
  completedDates: Set<string>;
  habitColor: string;
  habitCreatedAt?: number;
  onDayPress?: (date: string, completed: boolean) => void;
}

const DAY_HEADERS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

export const MonthlyCalendarGrid = memo(function MonthlyCalendarGrid({
  habitId: _habitId,
  completedDates,
  habitColor,
  habitCreatedAt,
  onDayPress,
}: MonthlyCalendarGridProps) {
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const today = startOfToday();

  // Generate calendar days for the current month
  const days = useMemo(() => {
    const monthStart = startOfMonth(currentMonth);
    const monthEnd = endOfMonth(currentMonth);
    const calendarStart = startOfWeek(monthStart, { weekStartsOn: 1 });
    const calendarEnd = endOfWeek(monthEnd, { weekStartsOn: 1 });

    return eachDayOfInterval({ start: calendarStart, end: calendarEnd }).map((date): DayData => {
      const dateString = format(date, 'yyyy-MM-dd');
      const isCurrentMonth = date.getMonth() === currentMonth.getMonth();
      const isToday = isSameDay(date, today);
      const isFuture = isAfter(date, today);
      const isCompleted = completedDates.has(dateString);
      const isBeforeCreation = habitCreatedAt
        ? isBefore(date, new Date(habitCreatedAt)) && !isCompleted
        : false;

      return {
        date,
        dateString,
        dayNumber: date.getDate(),
        isCurrentMonth,
        isToday,
        isFuture,
        isBeforeCreation,
        isCompleted,
      };
    });
  }, [currentMonth, today, completedDates, habitCreatedAt]);

  // Chunk days into weeks for row-based rendering
  const weeks = useMemo(() => {
    const result: DayData[][] = [];
    for (let i = 0; i < days.length; i += 7) {
      result.push(days.slice(i, i + 7));
    }
    return result;
  }, [days]);

  const goToPreviousMonth = useCallback(() => {
    setCurrentMonth((prev) => subMonths(prev, 1));
  }, []);

  const goToNextMonth = useCallback(() => {
    setCurrentMonth((prev) => addMonths(prev, 1));
  }, []);

  const handleDayPress = useCallback(
    (dateString: string, isCompleted: boolean) => {
      onDayPress?.(dateString, isCompleted);
    },
    [onDayPress]
  );

  // Get text color based on day state
  const getTextColor = (day: DayData): string => {
    if (!day.isCurrentMonth) return COLORS.TEXT_MUTED;
    if (day.isFuture) return COLORS.TEXT_TERTIARY;
    return COLORS.TEXT_PRIMARY;
  };

  return (
    <View style={styles.container}>
      {/* Day Headers */}
      <View style={styles.row}>
        {DAY_HEADERS.map((day) => (
          <View key={day} style={styles.headerCell}>
            <Text style={styles.headerText}>{day}</Text>
          </View>
        ))}
      </View>

      {/* Calendar Grid - row by row */}
      {weeks.map((week, weekIndex) => (
        <View key={`week-${weekIndex}`} style={styles.row}>
          {week.map((day) => {
            const showCompleted = day.isCompleted && day.isCurrentMonth && !day.isFuture;
            const isToday = day.isToday;

            return (
              <Pressable
                key={day.dateString}
                style={styles.dayWrapper}
                onPress={() => handleDayPress(day.dateString, day.isCompleted)}
                disabled={day.isFuture || day.isBeforeCreation}
              >
                <View
                  style={[
                    styles.dayCell,
                    showCompleted && { backgroundColor: hexToRgba(habitColor, 0.15) },
                    isToday && { borderWidth: 2, borderColor: habitColor },
                  ]}
                >
                  <Text
                    style={[
                      styles.dayText,
                      { color: getTextColor(day) },
                      isToday && styles.todayText,
                    ]}
                  >
                    {day.dayNumber}
                  </Text>

                  {/* Completion dot */}
                  {showCompleted && (
                    <View style={[styles.dot, { backgroundColor: habitColor }]} />
                  )}
                </View>
              </Pressable>
            );
          })}
        </View>
      ))}

      {/* Month Navigation */}
      <View style={styles.navigation}>
        <Pressable style={styles.monthButton}>
          <Calendar size={16} color={COLORS.TEXT_SECONDARY} />
          <Text style={styles.monthText}>{format(currentMonth, 'MMM yyyy')}</Text>
        </Pressable>

        <View style={styles.navButtons}>
          <Pressable style={styles.navButton} onPress={goToPreviousMonth}>
            <ChevronLeft size={20} color={COLORS.TEXT_SECONDARY} />
          </Pressable>
          <Pressable style={styles.navButton} onPress={goToNextMonth}>
            <ChevronRight size={20} color={COLORS.TEXT_SECONDARY} />
          </Pressable>
        </View>
      </View>
    </View>
  );
});

// Compact styles for above-fold layout
const styles = StyleSheet.create({
  container: {
    backgroundColor: COLORS.CARD_BG,
    borderRadius: 16, // Match HabitStrengthSection (rounded-2xl)
    marginTop: 12,
    padding: 16, // Compact padding (was 20)
    // Shadow matching HabitStrengthSection
    shadowColor: '#1c1917',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.05,
    shadowRadius: 8,
    elevation: 2,
  },
  dayCell: {
    alignItems: 'center',
    borderRadius: 8, // Slightly smaller radius
    height: 36, // Compact height (was 40)
    justifyContent: 'center',
    width: 36, // Compact width (was 40)
  },
  dayText: {
    fontSize: 14, // Slightly smaller (was 15)
    fontWeight: '500',
  },
  dayWrapper: {
    alignItems: 'center',
    flex: 1,
    height: 38, // Compact height (was 44)
    justifyContent: 'center',
  },
  dot: {
    borderRadius: 2.5,
    bottom: 3,
    height: 5, // Slightly smaller (was 6)
    position: 'absolute',
    width: 5,
  },
  headerCell: {
    alignItems: 'center',
    flex: 1,
  },
  headerText: {
    color: COLORS.TEXT_SECONDARY,
    fontSize: 11, // Compact (was 13)
    fontWeight: '500',
  },
  monthButton: {
    alignItems: 'center',
    borderColor: COLORS.BORDER,
    borderRadius: 16,
    borderWidth: 1,
    flexDirection: 'row',
    gap: 6,
    paddingHorizontal: 12, // Compact (was 16)
    paddingVertical: 6, // Compact (was 8)
  },
  monthText: {
    color: COLORS.TEXT_PRIMARY,
    fontSize: 13, // Compact (was 14)
    fontWeight: '600',
  },
  navButton: {
    alignItems: 'center',
    borderColor: COLORS.BORDER,
    borderRadius: 16,
    borderWidth: 1,
    height: 36, // Compact (was 40)
    justifyContent: 'center',
    width: 36,
  },
  navButtons: {
    flexDirection: 'row',
    gap: 8,
  },
  navigation: {
    alignItems: 'center',
    borderTopColor: COLORS.BORDER,
    borderTopWidth: 1,
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginTop: 12, // Compact (was 16)
    paddingTop: 12, // Compact (was 16)
  },
  row: {
    flexDirection: 'row',
    marginBottom: 1, // Tighter rows (was 2)
  },
  todayText: {
    fontWeight: '700',
  },
});

export default MonthlyCalendarGrid;

/**
 * StatsRow Component
 *
 * Displays habit statistics in a row format below the heatmap:
 * - Frequency badge (e.g., "Daily", "Weekly")
 * - Streak badge with fire icon showing current streak count
 * - Settings button for habit configuration
 *
 * This component follows the design spec:
 * - Frequency badge: bg-stone-100 text-stone-900
 * - Streak badge: bg-habit-color-50 text-habit-color with fire icon
 * - Settings button: 36x36px circular
 */

import React, { memo, useCallback } from 'react';
import {
  View,
  Text,
  Pressable,
  StyleSheet,
  Platform,
  type ViewStyle,
  type TextStyle,
} from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  useReducedMotion,
} from 'react-native-reanimated';
import { Settings, Flame } from 'lucide-react-native';

import type { StatsRowProps } from './types';
import { COLORS, FOCUS } from './constants';

/**
 * Configuration for the stats row
 */
const STATS_CONFIG = {
  /** Badge border radius */
  BADGE_BORDER_RADIUS: 8,

  /** Badge horizontal padding */
  BADGE_PADDING_X: 12,

  /** Badge vertical padding */
  BADGE_PADDING_Y: 6,

  /** Icon size for flame */
  FLAME_ICON_SIZE: 14,

  /** Press scale factor */
  PRESS_SCALE: 0.95,

  /** Settings button dimensions */
  SETTINGS_BUTTON_SIZE: 36,

  /** Icon size for settings */
  SETTINGS_ICON_SIZE: 18,
  /** Spring config for press animation */
  SPRING_CONFIG: {
    damping: 15,
    stiffness: 400,
  },
} as const;

/**
 * Animated Pressable for press feedback
 */
const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

/**
 * Utility to generate a lighter shade of a hex color (for badge background)
 * Creates a 50-level color (very light tint)
 */
function getHabitColor50(hexColor: string): string {
  // Parse hex to RGB
  const hex = hexColor.replace('#', '');
  const r = Number.parseInt(hex.slice(0, 2), 16);
  const g = Number.parseInt(hex.slice(2, 4), 16);
  const b = Number.parseInt(hex.slice(4, 6), 16);

  // Blend with white at 90% to create a very light tint (like Tailwind's 50 level)
  const blendFactor = 0.9;
  const newR = Math.round(r + (255 - r) * blendFactor);
  const newG = Math.round(g + (255 - g) * blendFactor);
  const newB = Math.round(b + (255 - b) * blendFactor);

  return `#${newR.toString(16).padStart(2, '0')}${newG.toString(16).padStart(2, '0')}${newB.toString(16).padStart(2, '0')}`;
}

/**
 * StatsRow - Displays frequency badge, streak count, and settings button
 *
 * Layout:
 * [Frequency Badge] [🔥 Streak Badge]           [⚙️ Settings]
 *
 * The streak badge dynamically colors based on the habit's accent color,
 * creating a cohesive visual theme with the heatmap above.
 */
export const StatsRow = memo(function StatsRow({
  frequency,
  currentStreak,
  habitColor,
  onSettingsPress,
}: StatsRowProps) {
  const shouldReduceMotion = useReducedMotion();
  const settingsScale = useSharedValue(1);

  // Handle settings button press in/out
  const handleSettingsPressIn = useCallback(() => {
    if (!shouldReduceMotion) {
      settingsScale.value = withSpring(
        STATS_CONFIG.PRESS_SCALE,
        STATS_CONFIG.SPRING_CONFIG
      );
    }
  }, [settingsScale, shouldReduceMotion]);

  const handleSettingsPressOut = useCallback(() => {
    if (!shouldReduceMotion) {
      settingsScale.value = withSpring(1, STATS_CONFIG.SPRING_CONFIG);
    }
  }, [settingsScale, shouldReduceMotion]);

  // Animated style for settings button
  const settingsAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: settingsScale.value }],
  }));

  // Dynamic streak badge colors
  const streakBadgeBackground = getHabitColor50(habitColor);

  // Format streak text
  const streakText =
    currentStreak === 1 ? '1 day streak' : `${currentStreak} day streak`;

  return (
    <View
      accessible
      accessibilityLabel='Habit statistics'
      accessibilityRole='none'
      style={styles.container}
    >
      {/* Left side: badges */}
      <View style={styles.badgesContainer}>
        {/* Frequency badge */}
        <View
          accessible
          accessibilityLabel={`Frequency: ${frequency}`}
          accessibilityRole='text'
          style={styles.frequencyBadge}
        >
          <Text style={styles.frequencyText}>{frequency}</Text>
        </View>

        {/* Streak badge */}
        {currentStreak > 0 && (
          <View
            accessible
            accessibilityLabel={`Current streak: ${streakText}`}
            accessibilityRole='text'
            style={[
              styles.streakBadge,
              { backgroundColor: streakBadgeBackground },
            ]}
          >
            <Flame
              color={habitColor}
