        <View
          className='absolute left-0 top-0 bottom-0 pointer-events-none'
          style={{ width: 60, zIndex: 5 }}
        >
          <LinearGradient
            colors={[
              'rgba(249, 250, 251, 1)',    // Solid background
              'rgba(249, 250, 251, 0.95)',
              'rgba(249, 250, 251, 0.8)',
              'rgba(249, 250, 251, 0.5)',
              'rgba(249, 250, 251, 0.2)',
