import { TimePickerModal } from './TimePickerModal';
import { NextReminderBadge } from './NextReminderBadge';

/**
 * Reminder preset configuration
 */
export interface ReminderPreset {
  id: string;
  label: string;
  emoji: string;
  hour: number;
  minute: number;
}

/**
 * Default reminder presets matching Huberman phases
 */
export const DEFAULT_PRESETS: ReminderPreset[] = [
  { emoji: '🌅', hour: 7, id: 'morning', label: '7 AM', minute: 0 },
  { emoji: '☀️', hour: 12, id: 'midday', label: '12 PM', minute: 0 },
  { emoji: '🌙', hour: 20, id: 'evening', label: '8 PM', minute: 0 },
];

/**
 * Props for the EnhancedReminderSelector component
 */
export interface EnhancedReminderSelectorProps {
  /** Whether reminders are enabled */
  enabled: boolean;
  /** Current reminder time as Date object */
  reminderTime: Date;
  /** Called when toggle is switched */
  onToggle: (enabled: boolean) => void;
  /** Called when time changes (preset or custom) */
  onTimeChange: (time: Date) => void;
  /** Optional custom presets (defaults to morning/midday/evening) */
  presets?: ReminderPreset[];
  /** Whether to show the next reminder badge (default: true) */
  showNextReminder?: boolean;
}

/**
 * Props for individual preset buttons
 */
interface PresetButtonProps {
  preset: ReminderPreset;
  isSelected: boolean;
  onPress: () => void;
  reduceMotion: boolean;
}

/**
 * Individual preset button with animation
 */
const PresetButtonComponent = ({
  preset,
  isSelected,
  onPress,
  reduceMotion,
}: PresetButtonProps) => {
  const scaleAnim = useRef(new Animated.Value(1)).current;

  const handlePressIn = useCallback(() => {
    if (reduceMotion) return;
    Animated.spring(scaleAnim, {
      friction: 10,
      tension: 300,
      toValue: 0.96,
      useNativeDriver: true,
    }).start();
  }, [scaleAnim, reduceMotion]);

  const handlePressOut = useCallback(() => {
    if (reduceMotion) {
      scaleAnim.setValue(1);
      return;
    }
    Animated.spring(scaleAnim, {
      friction: 15,
      tension: 150,
      toValue: 1,
      useNativeDriver: true,
    }).start();
  }, [scaleAnim, reduceMotion]);

  return (
    <Pressable
      accessibilityLabel={`Set reminder for ${preset.label}`}
      accessibilityRole='button'
      accessibilityState={{ selected: isSelected }}
      className='flex-1'
      testID={`preset-${preset.id}`}
      onPress={onPress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
    >
      {/* V12: Larger preset buttons (py-3.5) for better touch targets and premium feel */}
      <Animated.View
        className='items-center justify-center rounded-2xl px-3 py-3.5'
        style={[
          {
            backgroundColor: isSelected ? '#ECFDF5' : '#f5f5f4', // emerald-50 / stone-100
            borderColor: isSelected ? '#10B981' : 'transparent', // emerald-500
            borderWidth: isSelected ? 2 : 1,
            transform: [{ scale: scaleAnim }],
          },
        ]}
      >
        <Text className='mb-1 text-lg'>{preset.emoji}</Text>
        <Text
          className='text-sm font-medium'
          style={{ color: isSelected ? '#059669' : '#57534e' }} // emerald-600 / stone-600
        >
          {preset.label}
        </Text>
      </Animated.View>
    </Pressable>
  );
};

const PresetButton = memo(PresetButtonComponent);

/**
 * EnhancedReminderSelector - Full-featured reminder configuration UI.
 *
 * Features:
 * - Toggle row with bell icon and switch
 * - Quick preset buttons (Morning/Midday/Evening)
 * - Custom time button that opens native TimePickerModal
 * - Selected preset shows green border
 * - Custom time shows green border when set
 * - Next reminder badge updates on time change
 * - Keyboard dismissed on any interaction
 * - All elements have accessibility labels
 * - Haptic feedback on selection
 *
 * V12 Updates:
 * - Larger toggle row (py-4, h-10 icon)
 * - Larger preset buttons (py-3.5, text-lg emoji)
 * - More spacing between elements (gap-3, mt-4)
 * - Larger touch targets for premium feel
 *
 * Usage:
 * ```tsx
 * <EnhancedReminderSelector
 *   enabled={reminderEnabled}
 *   reminderTime={reminderTime}
 *   onToggle={setReminderEnabled}
 *   onTimeChange={setReminderTime}
 * />
 * ```
 */
const EnhancedReminderSelectorComponent = ({
  enabled,
  reminderTime,
  onToggle,
  onTimeChange,
  presets = DEFAULT_PRESETS,
  showNextReminder = true,
}: EnhancedReminderSelectorProps) => {
  const [showTimePicker, setShowTimePicker] = useState(false);
  const { triggerSelection } = useHapticFeedback();
  const reduceMotion = useReduceMotion();

  // Determine which preset is selected (if any)
  const selectedPreset = useMemo(() => {
    const hour = reminderTime.getHours();
    const minute = reminderTime.getMinutes();
    return (
      presets.find((p) => p.hour === hour && p.minute === minute)?.id || null
    );
  }, [reminderTime, presets]);

  // Check if current time is a custom time (not matching any preset)
  const isCustomTime = selectedPreset === null;

  // Format custom time for display
  const customTimeLabel = useMemo(() => {
    if (!isCustomTime) return 'Custom time...';
    return formatReminderTime(reminderTime);
  }, [isCustomTime, reminderTime]);

  // Handle preset selection
  const handlePresetSelect = useCallback(
    (preset: ReminderPreset) => {
      Keyboard.dismiss();
      triggerSelection();
      const newTime = new Date();
      newTime.setHours(preset.hour, preset.minute, 0, 0);
      onTimeChange(newTime);

      // Announce for screen readers
      AccessibilityInfo.announceForAccessibility(
        `Reminder set for ${preset.label}`
      );
    },
    [onTimeChange, triggerSelection]
  );

  // Handle custom time button press
  const handleCustomTimePress = useCallback(() => {
    Keyboard.dismiss();
    triggerSelection();
    setShowTimePicker(true);
  }, [triggerSelection]);

  // Handle custom time confirmation from picker
  const handleCustomTimeConfirm = useCallback(
    (time: Date) => {
      triggerSelection();
      onTimeChange(time);
      setShowTimePicker(false);

      // Announce for screen readers
      const formattedTime = formatReminderTime(time);
      AccessibilityInfo.announceForAccessibility(
        `Custom reminder set for ${formattedTime}`
      );
    },
    [onTimeChange, triggerSelection]
  );

  // Handle toggle change
  const handleToggle = useCallback(
    (value: boolean) => {
      Keyboard.dismiss();
      triggerSelection();
      onToggle(value);

      // Announce for screen readers
      AccessibilityInfo.announceForAccessibility(
        value ? 'Reminders enabled' : 'Reminders disabled'
      );
    },
    [onToggle, triggerSelection]
  );

  return (
    <View className='mb-6' testID='enhanced-reminder-selector'>
      {/* Toggle Row - V12: Larger padding and icon for premium feel */}
      <View
        className='flex-row items-center justify-between rounded-2xl border border-stone-200 bg-white px-4 py-4'
        style={{
          elevation: 1,
          shadowColor: '#000',
          shadowOffset: { height: 1, width: 0 },
          shadowOpacity: 0.05,
          shadowRadius: 2,
        }}
      >
        {/* Bell Icon + Label - V12: Larger icon container (h-10 w-10) */}
        <View className='flex-row items-center gap-3'>
          <View className='h-10 w-10 items-center justify-center rounded-full bg-amber-100'>
            <Bell color='#f59e0b' size={18} />
          </View>
          <Text className='text-base font-medium text-stone-900'>
            Daily Reminder
          </Text>
        </View>

        {/* Toggle Switch */}
        <Switch
          accessibilityLabel={enabled ? 'Disable reminder' : 'Enable reminder'}
          accessibilityRole='switch'
          ios_backgroundColor='#d6d3d1'
          testID='reminder-toggle'
          thumbColor='#ffffff'
          trackColor={{ false: '#d6d3d1', true: '#10B981' }}
          value={enabled}
          onValueChange={handleToggle}
        />
      </View>

      {/* Time Selection UI (shown when enabled) */}
      {enabled && (
        <View className='mt-4'>
          {/* Preset Buttons Row - V12: Larger gap (gap-3) for better spacing */}
          <View className='mb-4 flex-row gap-3' testID='preset-buttons'>
            {presets.map((preset) => (
              <PresetButton
                key={preset.id}
                isSelected={selectedPreset === preset.id}
                preset={preset}
                reduceMotion={reduceMotion}
                onPress={() => handlePresetSelect(preset)}
              />
            ))}
          </View>

          {/* Custom Time Link - V12: Larger touch target (py-3) */}
          <Pressable
            accessibilityHint='Opens time picker'
            accessibilityLabel={
              isCustomTime
                ? `Custom time set to ${customTimeLabel}. Double tap to change.`
                : 'Set a custom reminder time'
            }
            accessibilityRole='button'
            className='mb-4 flex-row items-center justify-center py-3'
            testID='custom-time-button'
            onPress={handleCustomTimePress}
          >
            {isCustomTime ? (
              <>
                <Clock color='#059669' size={16} />
                <Text className='ml-1.5 text-sm font-medium text-emerald-600'>
                  {customTimeLabel}
                </Text>
                <Text className='ml-1 text-sm text-emerald-600'>
                  (tap to change)
                </Text>
              </>
            ) : (
              <>
                <Text className='text-sm font-medium text-emerald-600'>
                  Pick a different time
                </Text>
                <Text className='ml-1 text-emerald-600'>→</Text>
              </>
            )}
          </Pressable>

          {/* Next Reminder Badge */}
          {showNextReminder && (
            <View className='items-center'>
              <NextReminderBadge
                enabled={enabled}
                reminderTime={reminderTime}
              />
            </View>
          )}
        </View>
      )}

      {/* Time Picker Modal */}
      <TimePickerModal
        initialTime={reminderTime}
        visible={showTimePicker}
        onCancel={() => setShowTimePicker(false)}
        onConfirm={handleCustomTimeConfirm}
      />
    </View>
  );
};

export const EnhancedReminderSelector = memo(EnhancedReminderSelectorComponent);

export default EnhancedReminderSelector;

import { memo, useCallback, useEffect, useRef, useState } from 'react';
import { Text, TextInput, View } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withTiming,
} from 'react-native-reanimated';
import STRINGS from '../../../constants/strings';
import useHapticFeedback from '../../../hooks/useHapticFeedback';

const AnimatedTextInput = Animated.createAnimatedComponent(TextInput);

interface HabitNameFieldProps {
  value: string;
  onChange: (text: string) => void;
  autoFocus: boolean;
}

const MAX_LENGTH = 50;
const MAX_CHARS = 40; // V11: Soft limit for character counter
const WARNING_THRESHOLD = 30;
const SHOW_THRESHOLD = 20;

const HabitNameFieldComponent = ({
  value,
  onChange,
  autoFocus,
}: HabitNameFieldProps) => {
  const charCount = value.length;
  const showCounter = charCount > SHOW_THRESHOLD;
  const isWarning = charCount > WARNING_THRESHOLD;
  const isError = charCount > MAX_CHARS;
  const [isFocused, setIsFocused] = useState(false);
  const { triggerWarning } = useHapticFeedback();
  const previousCount = useRef(charCount);

  // Animation values for focus state
  const focusProgress = useSharedValue(0);

  // V11: Shake animation for character limit
  const shakeTranslate = useSharedValue(0);

  // Update focus animation
  useEffect(() => {
    focusProgress.value = withTiming(isFocused ? 1 : 0, { duration: 200 });
  }, [isFocused, focusProgress]);

  // Animated style for input focus
  const animatedInputStyle = useAnimatedStyle(() => ({
    borderColor:
      focusProgress.value > 0.5
        ? '#10B981' // primary.500 - emerald
        : isError
          ? '#EF4444' // red-500
          : '#e7e5e4', // stone-200
    borderWidth: 2,
    elevation: focusProgress.value * 2,
    shadowColor: '#10B981',
    shadowOffset: { height: 0, width: 0 },
    shadowOpacity: focusProgress.value * 0.1,
    shadowRadius: focusProgress.value * 3,
    transform: [{ translateX: shakeTranslate.value }],
  }));

  // V11: Trigger haptic and shake when exceeding MAX_CHARS
  useEffect(() => {
    // Trigger haptic at hard limit (50)
    if (charCount === MAX_LENGTH && previousCount.current < MAX_LENGTH) {
      triggerWarning();
    }
    // V11: Shake animation when exceeding soft limit (40)
    if (charCount > MAX_CHARS && previousCount.current <= MAX_CHARS) {
      triggerWarning();
      // Shake animation: 10px right, 10px left, 10px right, center
      shakeTranslate.value = withTiming(10, { duration: 50 }, () => {
        shakeTranslate.value = withTiming(-10, { duration: 50 }, () => {
          shakeTranslate.value = withTiming(10, { duration: 50 }, () => {
            shakeTranslate.value = withTiming(0, { duration: 50 });
          });
        });
      });
    }
    previousCount.current = charCount;
  }, [charCount, triggerWarning, shakeTranslate]);

  const handleFocus = useCallback(() => setIsFocused(true), []);
  const handleBlur = useCallback(() => setIsFocused(false), []);

  // V11: Determine counter color based on character count
  const counterColor = isError
    ? '#EF4444' // red-500
    : isWarning
      ? '#F59E0B' // amber-500
      : '#78716c'; // stone-500

  return (
    <View className='mb-3'>
      <AnimatedTextInput
        blurOnSubmit
        accessibilityHint='Enter a name for your habit, up to 50 characters'
        accessibilityLabel='Habit name'
        autoFocus={autoFocus}
        className='h-14 rounded-xl bg-white px-4 text-base text-stone-800'
        maxLength={MAX_LENGTH}
        placeholder={STRINGS.CREATE_HABIT.namePlaceholder}
        placeholderTextColor='#a8a29e'
        returnKeyType='done'
        style={animatedInputStyle}
        value={value}
        onBlur={handleBlur}
        onChangeText={onChange}
        onFocus={handleFocus}
      />

      {/* V11: Character counter - only show when > 20 chars */}
      {showCounter && (
        <Text
          accessibilityLabel={`${charCount} of ${MAX_CHARS} characters used${isWarning ? ', approaching limit' : ''}${isError ? ', limit exceeded' : ''}`}
          accessibilityRole='text'
          className='mt-1 text-center text-xs'
          style={{ color: counterColor }}
        >
          {charCount}/{MAX_CHARS}
        </Text>
      )}
    </View>
  );
};

export const HabitNameField = memo(HabitNameFieldComponent);

import { useEffect, useRef, useState } from 'react';
import { Animated, Text, View } from 'react-native';
import STRINGS from '../../../constants/strings';
import { SkeletonCard } from './SkeletonLoader';
import { HUBERMAN_PHASES, type HubermanPhase } from '../../../constants/hubermanPhases';

interface HabitPreviewProps {
  habitName: string;
  selectedEmoji: string | null;
  selectedColor: string;
  timeOfDay?: HubermanPhase | null;
}

export const HabitPreview = ({
  habitName,
  selectedEmoji,
  selectedColor,
  timeOfDay,
}: HabitPreviewProps) => {
  const isEmpty = !habitName && !selectedEmoji;
  const [showSkeleton, setShowSkeleton] = useState(false);

  // Animations
  const iconScale = useRef(new Animated.Value(1)).current;
  const contentOpacity = useRef(new Animated.Value(1)).current;
  const contentScale = useRef(new Animated.Value(1)).current;
  const pulseAnim = useRef(new Animated.Value(1)).current;

  // Brief skeleton on mount for polish
  useEffect(() => {
    setShowSkeleton(true);
    const timer = setTimeout(() => setShowSkeleton(false), 400);
    return () => clearTimeout(timer);
  }, []);

  // Pulse ring animation on emoji icon
  useEffect(() => {
    if (!isEmpty && selectedEmoji) {
      const pulse = Animated.loop(
        Animated.sequence([
          Animated.timing(pulseAnim, {
            toValue: 1.15,
            duration: 1200,
            useNativeDriver: true,
          }),
          Animated.timing(pulseAnim, {
            toValue: 1,
            duration: 1200,
            useNativeDriver: true,
          }),
        ])
      );
      pulse.start();
      return () => pulse.stop();
    }
  }, [isEmpty, selectedEmoji, pulseAnim]);

  // Trigger spring animation when content changes
  useEffect(() => {
    if (!isEmpty) {
      // Bounce the icon
      Animated.sequence([
        Animated.spring(iconScale, {
          toValue: 1.15,
          tension: 180,
          friction: 8,
          useNativeDriver: true,
        }),
        Animated.spring(iconScale, {
          toValue: 1,
          tension: 180,
          friction: 8,
          useNativeDriver: true,
        }),
      ]).start();

      // Subtle content pulse
      Animated.sequence([
        Animated.spring(contentScale, {
          toValue: 1.02,
          tension: 200,
          friction: 10,
          useNativeDriver: true,
        }),
        Animated.spring(contentScale, {
          toValue: 1,
          tension: 200,
          friction: 10,
          useNativeDriver: true,
        }),
      ]).start();
    }
  }, [habitName, selectedEmoji, selectedColor, isEmpty, iconScale, contentScale]);

  // Get time of day display text
  const getTimeOfDayLabel = () => {
    if (!timeOfDay) return 'Daily';
    const phase = HUBERMAN_PHASES[timeOfDay];
    return phase ? `Daily • ${phase.icon} ${phase.shortLabel}` : 'Daily';
  };

  // Generate accessibility label based on current state
  const getAccessibilityLabel = () => {
    if (isEmpty) {
      return 'Habit preview: No habit configured yet. Enter a name and select an icon to preview.';
    }
    const nameText = habitName || 'Unnamed habit';
    const emojiText = selectedEmoji ? `with icon ${selectedEmoji}` : 'without icon';
    const timeText = getTimeOfDayLabel();
    return `Habit preview: ${nameText} ${emojiText}. Schedule: ${timeText}`;
  };

  return (
    <View
      accessible
      accessibilityLabel={getAccessibilityLabel()}
      accessibilityRole='summary'
      className='mb-4 mt-3 overflow-hidden rounded-2xl bg-white p-3'
      style={{
        borderWidth: 2,
        borderColor: isEmpty ? '#e7e5e4' : selectedColor, // #e7e5e4 = stone-200
      }}
    >
      <Text className='mb-2 text-xs font-semibold text-stone-500'>✨ Live Preview</Text>

      {showSkeleton ? (
        <View className='py-2'>
          <SkeletonCard />
        </View>
      ) : isEmpty ? (
        <View className='items-center py-4'>
          <Text className='mb-2 text-4xl'>✨</Text>
          <Text className='mb-1 text-sm font-medium text-stone-500'>Your habit will appear here</Text>
          <Text className='text-xs text-stone-400'>Try: "Meditate", "Run", or "Read"</Text>
        </View>
      ) : (
        <Animated.View style={{ opacity: contentOpacity, transform: [{ scale: contentScale }] }}>
          <View className='flex-row items-center gap-3'>
            <Animated.View style={{ transform: [{ scale: iconScale }] }}>
              {selectedEmoji ? (
                <View className='relative'>
                  {/* Pulse ring behind icon */}
                  <Animated.View
                    className='absolute inset-0 rounded-2xl'
                    style={{
                      backgroundColor: selectedColor,
                      opacity: 0.3,
                      transform: [{ scale: pulseAnim }],
                    }}
                  />
                  <View
                    className='h-14 w-14 items-center justify-center rounded-2xl'
                    style={{ backgroundColor: selectedColor }}
                  >
                    <Text className='text-[28px]'>{selectedEmoji}</Text>
                  </View>
                </View>
              ) : (
                <View className='h-14 w-14 items-center justify-center rounded-2xl bg-stone-200'>
                  <Text className='text-xl text-stone-400'>?</Text>
                </View>
              )}
            </Animated.View>
            <View className='flex-1'>
              {habitName ? (
                <Text className='text-lg font-semibold text-stone-800' numberOfLines={1}>
                  {habitName}
                </Text>
              ) : (
                <Text className='text-lg font-semibold text-stone-400'>
                  {STRINGS.CREATE_HABIT.namePlaceholder}
                </Text>
              )}
              <Text className='text-sm text-stone-500'>
                {getTimeOfDayLabel()}
              </Text>
            </View>
          </View>
        </Animated.View>
      )}
    </View>
  );
};

