  // Nutrition
  { emoji: '🍎', name: 'Eat a healthy snack', color: '#ef4444' },
  { emoji: '🥗', name: 'Eat vegetables', color: '#84cc16' },
  { emoji: '🍊', name: 'Take vitamins', color: '#fb923c' },
  { emoji: '☕', name: 'No coffee after 2pm', color: '#78716c' },
  { emoji: '🥤', name: 'No soda today', color: '#78716c' },

  // Mental & Learning
  { emoji: '📖', name: 'Read 10 minutes', color: '#f59e0b' },
  { emoji: '📝', name: 'Journal 3 lines', color: '#f97316' },
  { emoji: '🙏', name: 'Practice gratitude', color: '#ec4899' },
  { emoji: '🧠', name: 'Learn something new', color: '#3b82f6' },
  { emoji: '📚', name: 'Study 30 minutes', color: '#eab308' },
  { emoji: '✍️', name: 'Write 100 words', color: '#a855f7' },

  // Productivity & Focus
  { emoji: '📱', name: 'No phone for 1 hour', color: '#78716c' },
  { emoji: '🎯', name: 'Complete daily goal', color: '#dc2626' },
  { emoji: '📅', name: 'Plan tomorrow', color: '#0891b2' },
  { emoji: '🧹', name: 'Clean for 10 minutes', color: '#06b6d4' },
  { emoji: '✅', name: 'Make my bed', color: '#10b981' },
  { emoji: '⏰', name: 'Time block work', color: '#7c3aed' },

  // Social & Creative
  { emoji: '👨‍👩‍👧‍👦', name: 'Call family', color: '#f472b6' },
  { emoji: '💌', name: 'Text a friend', color: '#fb7185' },
  { emoji: '🎨', name: 'Creative time', color: '#ec4899' },
  { emoji: '🎸', name: 'Practice instrument', color: '#a855f7' },
  { emoji: '📷', name: 'Take a photo', color: '#6366f1' },
  { emoji: '🌱', name: 'Tend to plants', color: '#22c55e' },
];

// Separate component to fix Rules of Hooks
interface SuggestionChipProps {
  emoji: string | null;
  name: string;
  color: string;
  onPick: (emoji: string | null, name: string, color: string) => void;
}

const SuggestionChip = ({ emoji, name, color, onPick }: SuggestionChipProps) => {
  const scale = useRef(new Animated.Value(1)).current;
  const { triggerSelection } = useHapticFeedback();

  return (
    <Animated.View style={{ transform: [{ scale }] }}>
      <Pressable
        accessibilityRole='button'
        accessibilityLabel={`Use template ${name}`}
        className='flex-row items-center rounded-full bg-white px-3 py-2'
        style={{ borderColor: '#d6d3d1', borderWidth: 1 }}
        onPressIn={() => {
          Animated.timing(scale, {
            duration: Motion.duration.fast,
            easing: Motion.easing.inEase,
            toValue: 0.96,
            useNativeDriver: true,
          }).start();
        }}
        onPressOut={() => {
          Animated.timing(scale, {
            duration: Motion.duration.base,
            easing: Motion.easing.outEase,
            toValue: 1,
            useNativeDriver: true,
          }).start();
        }}
        onPress={() => {
          triggerSelection();
          onPick(emoji, name, color);
        }}
      >
        {emoji && <Text className='mr-2 text-base'>{emoji}</Text>}
        <Text className='text-sm font-medium text-[#1c1917]'>{name}</Text>
        <Text className='ml-1 text-xs'>✨</Text>
      </Pressable>
    </Animated.View>
  );
};

export const NameSuggestions = ({ query, onPick }: NameSuggestionsProps) => {
  const [isLoading, setIsLoading] = useState(true);

  const items = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (q.length < 2) return SUGGESTIONS.slice(0, 4);
    return SUGGESTIONS.filter(({ name }) => name.toLowerCase().includes(q)).slice(0, 6);
  }, [query]);

  // Simulate brief loading for polish
  useEffect(() => {
    setIsLoading(true);
    const timer = setTimeout(() => setIsLoading(false), 300);
    return () => clearTimeout(timer);
  }, [query]);

  if (items.length === 0) return null;

  return (
    <View className='mb-6'>
      <Text className='mb-2 text-xs font-semibold uppercase tracking-wide text-[#78716c]'>💡 Tap to use</Text>
      {isLoading ? (
        <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerClassName='gap-2'>
          {[1, 2, 3, 4].map((i) => (
            <SkeletonButton key={i} />
          ))}
        </ScrollView>
      ) : (
        <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerClassName='gap-2'>
          {items.map(({ emoji, name, color }) => (
            <SuggestionChip
              key={`${emoji ?? 'none'}-${name}`}
              emoji={emoji}
              name={name}
              color={color}
              onPick={onPick}
            />
          ))}
        </ScrollView>
      )}
    </View>
  );
};

export default NameSuggestions;

import { useMemo } from 'react';
import { Text, View } from 'react-native';
import Animated, { FadeIn, FadeOut } from 'react-native-reanimated';
import { Clock } from 'lucide-react-native';
import { formatReminderTime } from '../../../utils/notifications';

/**
 * Props for the NextReminderBadge component.
 */
export interface NextReminderBadgeProps {
  /** The reminder time as a Date object */
  reminderTime: Date;
  /** Whether reminders are enabled */
  enabled: boolean;
}

/**
 * Calculate the next reminder occurrence text.
 *
 * - If the time is in the future today: "Today at X:XX AM/PM (in Yh Zm)"
 * - If the time has passed today: "Tomorrow at X:XX AM/PM"
 *
 * @param time The reminder time
 * @returns Formatted string showing when the next reminder will fire
 */
export function getNextReminderText(time: Date): string {
  const now = new Date();
  const reminderToday = new Date(now);
  reminderToday.setHours(time.getHours(), time.getMinutes(), 0, 0);

  const formattedTime = formatReminderTime(time);

  if (reminderToday > now) {
    // Today - show relative time
    const diffMs = reminderToday.getTime() - now.getTime();
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    const diffMins = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));

    if (diffHours > 0) {
      if (diffMins > 0) {
        return `Today at ${formattedTime} (in ${diffHours}h ${diffMins}m)`;
      }
      return `Today at ${formattedTime} (in ${diffHours} hour${diffHours === 1 ? '' : 's'})`;
    }
    return `Today at ${formattedTime} (in ${diffMins} minute${diffMins === 1 ? '' : 's'})`;
  } else {
    // Tomorrow
    return `Tomorrow at ${formattedTime}`;
  }
}

/**
 * NextReminderBadge - Displays when the next reminder will fire.
 *
 * Features:
 * - Shows "Today at X" when time is in future today
 * - Shows "Tomorrow at X" when time has passed today
 * - Shows relative time "(in X hours)" or "(in X minutes)"
 * - Amber background with clock icon
 * - Accessible text for screen readers
 * - Fade animation on enter/exit
 *
 * Usage:
 * ```tsx
 * <NextReminderBadge
 *   reminderTime={new Date()}
 *   enabled={true}
 * />
 * ```
 */
export const NextReminderBadge = ({
  reminderTime,
  enabled,
}: NextReminderBadgeProps) => {
  // Don't render if reminders are disabled
  if (!enabled) {
    return null;
  }

  // Memoize the text computation
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const text = useMemo(() => getNextReminderText(reminderTime), [reminderTime]);

  return (
    <Animated.View
      accessibilityLabel={`Next reminder: ${text}`}
      accessibilityRole='text'
      entering={FadeIn.duration(200).delay(100)}
      exiting={FadeOut.duration(150)}
      testID='next-reminder-badge'
    >
      <View className='flex-row items-center justify-center gap-1.5 rounded-full bg-amber-100 px-3 py-1.5'>
        <Clock color='#92400E' size={12} />
        <Text className='text-xs font-medium text-amber-800'>Next: {text}</Text>
      </View>
    </Animated.View>
  );
};

export default NextReminderBadge;

import { Text, TouchableOpacity, View } from 'react-native';
import {
  type HubermanPhase,
  HUBERMAN_PHASES,
  PHASE_ORDER,
} from '../../../constants/hubermanPhases';
import useHapticFeedback from '../../../hooks/useHapticFeedback';

interface PhaseSelectorProps {
  selectedPhase: HubermanPhase | null;
  onSelect: (phase: HubermanPhase | null) => void;
}

export const PhaseSelector = ({ selectedPhase, onSelect }: PhaseSelectorProps) => {
  const { triggerSelection } = useHapticFeedback();

  const handlePhasePress = (phase: HubermanPhase) => {
    triggerSelection();
    // Toggle off if already selected
    onSelect(selectedPhase === phase ? null : phase);
  };

  return (
    <View className='mb-6 rounded-2xl border-2 border-[#8B5CF6]/20 bg-gradient-to-r p-4' style={{ backgroundColor: '#FAFAFF' }}>
      <View className='mb-2 flex-row items-center'>
        <Text className='text-lg'>🧠</Text>
        <Text className='ml-2 text-base font-bold text-stone-800'>
          Huberman Day Phase
        </Text>
        <View className='ml-2 rounded-full bg-[#8B5CF6]/10 px-2 py-0.5'>
          <Text className='text-[10px] font-semibold text-[#8B5CF6]'>SCIENCE-BACKED</Text>
        </View>
      </View>
      <Text className='mb-4 text-[13px] text-stone-500'>
        Match your habit to optimal times based on circadian biology
      </Text>

      <View className='gap-2'>
        {PHASE_ORDER.map((phaseId) => {
          const phase = HUBERMAN_PHASES[phaseId];
          const isSelected = selectedPhase === phaseId;

          return (
            <TouchableOpacity
              key={phaseId}
              accessibilityLabel={`Select ${phase.label}`}
              accessibilityRole='button'
              accessibilityState={{ selected: isSelected }}
              className={`flex-row items-center rounded-xl border-2 px-3 py-3 ${
                isSelected
                  ? 'border-[#3B82F6] bg-[#EFF6FF]'
                  : 'border-transparent bg-[#F5F5F5]'
              }`}
              onPress={() => handlePhasePress(phaseId)}
            >
              <Text className='mr-2 text-lg'>{phase.icon}</Text>
              <View className='flex-1'>
                <View className='flex-row items-center'>
                  <Text
                    className={`text-sm font-semibold ${
                      isSelected ? 'text-[#3B82F6]' : 'text-stone-800'
                    }`}
                  >
                    {phase.shortLabel}
                  </Text>
                  <Text className='ml-2 text-xs text-stone-500'>
                    {phase.timeRange}
                  </Text>
                </View>
                <Text className='mt-0.5 text-xs text-stone-500'>
                  {phase.description}
                </Text>
              </View>
              {isSelected && (
                <View className='h-5 w-5 items-center justify-center rounded-full bg-[#3B82F6]'>
                  <Text className='text-xs text-white'>✓</Text>
                </View>
              )}
            </TouchableOpacity>
          );
        })}
      </View>

      {selectedPhase && (
        <View className='mt-3 rounded-lg bg-[#F0FDF4] p-3'>
          <Text className='text-xs font-medium text-[#166534]'>
            Best for: {HUBERMAN_PHASES[selectedPhase].activities.slice(0, 3).join(', ')}
          </Text>
        </View>
      )}
    </View>
  );
};

export default PhaseSelector;

import { useEffect, useRef } from 'react';
import { Animated, Pressable, Text, View } from 'react-native';
import { Sparkles, Lock } from 'lucide-react-native';
import { Motion } from '../../../constants/motion';
import useHapticFeedback from '../../../hooks/useHapticFeedback';

interface PremiumTeaserProps {
  habitName: string;
  onUpgrade: () => void;
}

// Mock AI suggestions based on habit name
const getAISuggestions = (name: string): string[] => {
  const q = name.toLowerCase();

  if (q.includes('read')) {
    return ['Best time: 9 PM before bed', 'Pair with: Evening tea ☕'];
  }
  if (q.includes('meditat') || q.includes('mindful')) {
    return ['Best time: 7 AM after waking', 'Pair with: Morning stretch 🧘'];
  }
  if (q.includes('run') || q.includes('jog') || q.includes('walk')) {
    return ['Best time: 6:30 AM', 'Pair with: Drink water 💧'];
  }
  if (q.includes('water') || q.includes('drink')) {
    return ['Best time: Every 2 hours', 'Start with: After each meal'];
  }
  if (q.includes('journal') || q.includes('write')) {
    return ['Best time: Before bed', 'Pair with: Gratitude practice 🙏'];
  }
  if (q.includes('workout') || q.includes('gym') || q.includes('exercise')) {
    return ['Best time: 5 PM after work', 'Pair with: Protein shake 🥤'];
  }

  return [
    'Personalized timing suggestions',
    'Smart habit pairing recommendations',
  ];
};

export const PremiumTeaser = ({ habitName, onUpgrade }: PremiumTeaserProps) => {
  const { triggerSelection } = useHapticFeedback();
  const shimmerAnim = useRef(new Animated.Value(0)).current;
  const slideAnim = useRef(new Animated.Value(20)).current;
  const opacityAnim = useRef(new Animated.Value(0)).current;

  const suggestions = getAISuggestions(habitName);

  // Entrance animation
  useEffect(() => {
    if (habitName.trim().length >= 3) {
      Animated.parallel([
        Animated.timing(opacityAnim, {
          delay: 500,
          duration: Motion.duration.enter,
          toValue: 1,
          useNativeDriver: true,
        }),
        Animated.spring(slideAnim, {
          damping: 15,
          delay: 500,
          stiffness: 150,
          toValue: 0,
          useNativeDriver: true,
        }),
      ]).start();
    }
  }, [habitName, opacityAnim, slideAnim]);

  // Shimmer animation loop
  useEffect(() => {
    const shimmer = Animated.loop(
      Animated.sequence([
        Animated.timing(shimmerAnim, {
          duration: 1500,
          toValue: 1,
          useNativeDriver: true,
        }),
        Animated.timing(shimmerAnim, {
          duration: 1500,
          toValue: 0,
          useNativeDriver: true,
        }),
      ])
    );
    shimmer.start();
    return () => shimmer.stop();
  }, [shimmerAnim]);

  if (habitName.trim().length < 3) {
    return null;
  }

  const shimmerOpacity = shimmerAnim.interpolate({
    inputRange: [0, 0.5, 1],
    outputRange: [0.3, 0.6, 0.3],
  });

  return (
    <Animated.View
      className='mb-6'
      style={{
        opacity: opacityAnim,
        transform: [{ translateY: slideAnim }],
      }}
    >
      <Pressable
        accessibilityLabel='Unlock AI suggestions with Premium'
        accessibilityRole='button'
        className='overflow-hidden rounded-2xl'
        onPress={() => {
          triggerSelection();
          onUpgrade();
        }}
      >
        {/* Background with gradient effect */}
        <View className='bg-gradient-to-r from-violet-50 to-indigo-50 p-4'>
          {/* Shimmer overlay */}
          <Animated.View
            className='absolute inset-0 bg-gradient-to-r from-transparent via-violet-200/30 to-transparent'
            style={{ opacity: shimmerOpacity }}
          />

          {/* Content */}
          <View className='relative'>
            {/* Header */}
            <View className='mb-3 flex-row items-center justify-between'>
              <View className='flex-row items-center'>
                <Sparkles color='#7c3aed' size={18} />
                <Text className='ml-2 text-sm font-bold text-violet-700'>
                  AI Suggestions
                </Text>
              </View>
              <View className='flex-row items-center rounded-full bg-violet-100 px-2 py-1'>
                <Lock color='#6d28d9' size={12} />
                <Text className='ml-1 text-[10px] font-bold text-violet-700'>
                  PRO
                </Text>
              </View>
            </View>

            {/* Blurred suggestions preview */}
            <View className='mb-3'>
              {suggestions.map((suggestion, index) => (
                <View
                  key={index}
                  className='mb-1 flex-row items-center'
                  style={{ opacity: 0.7 }}
                >
                  <Text className='mr-2 text-violet-500'>•</Text>
                  <Text
                    className='text-sm text-violet-800'
                    style={{
                      textShadowColor: 'rgba(124, 58, 237, 0.5)',
                      textShadowOffset: { height: 0, width: 0 },
                      textShadowRadius: 4,
                    }}
                  >
                    {suggestion}
                  </Text>
                </View>
              ))}
            </View>

            {/* CTA */}
            <View className='flex-row items-center justify-between rounded-xl bg-violet-500/20 px-3 py-2'>
              <Text className='text-xs font-medium text-violet-700'>
                Unlock personalized insights
              </Text>
              <Text className='text-xs font-bold text-violet-600'>
                Try Premium →
              </Text>
            </View>
          </View>
        </View>
      </Pressable>
    </Animated.View>
  );
};

export default PremiumTeaser;

