import { memo, useCallback, useEffect, useMemo, useRef } from 'react';
import { Animated, Pressable, Text, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { LinearGradient } from 'expo-linear-gradient';
import { Check } from 'lucide-react-native';
import STRINGS from '../../../constants/strings';
import { Motion } from '../../../constants/motion';
import { useKeyboardState } from '../hooks/useKeyboardState';
import useHapticFeedback from '../../../hooks/useHapticFeedback';

interface StickyCreateBarProps {
  disabled: boolean;
  onPress: () => void;
  selectedColor?: string;
}

/**
 * Creates a darker shade of a hex color for gradient effect
 * @param hex - The hex color (e.g., '#22C55E')
 * @param percent - How much darker (0-100), default 20%
 * @returns The darker hex color
 */
const darkenColor = (hex: string, percent: number = 20): string => {
  // Remove # if present
  const color = hex.replace('#', '');

  // Parse RGB values
  const r = Number.parseInt(color.slice(0, 2), 16);
  const g = Number.parseInt(color.slice(2, 4), 16);
  const b = Number.parseInt(color.slice(4, 6), 16);

  // Calculate darker values
  const darkerR = Math.max(0, Math.floor(r * (1 - percent / 100)));
  const darkerG = Math.max(0, Math.floor(g * (1 - percent / 100)));
  const darkerB = Math.max(0, Math.floor(b * (1 - percent / 100)));

  // Convert back to hex
  return `#${darkerR.toString(16).padStart(2, '0')}${darkerG.toString(16).padStart(2, '0')}${darkerB.toString(16).padStart(2, '0')}`;
};

// Default green color for the button when no color is selected
const DEFAULT_BUTTON_COLOR = '#22C55E';

const StickyCreateBarComponent = ({
  disabled,
  onPress,
  selectedColor,
}: StickyCreateBarProps) => {
  const insets = useSafeAreaInsets();
  const { isKeyboardVisible, keyboardHeight } = useKeyboardState();
  const { triggerSuccess, triggerMediumImpact } = useHapticFeedback();
  const scale = useRef(new Animated.Value(1)).current;

  // Animation for smooth color transitions
  const colorOpacity = useRef(new Animated.Value(1)).current;
  const previousColorRef = useRef<string>(
    selectedColor ?? DEFAULT_BUTTON_COLOR
  );

  // V11: Track previous disabled state for enable animation
  const wasDisabled = useRef(disabled);

  // Animate color transitions when selectedColor changes
  useEffect(() => {
    const currentColor = selectedColor ?? DEFAULT_BUTTON_COLOR;
    if (previousColorRef.current !== currentColor) {
      // Quick fade out and in for smooth color transition
      Animated.sequence([
        Animated.timing(colorOpacity, {
          duration: Motion.duration.fast,
          easing: Motion.easing.inEase,
          toValue: 0.85,
          useNativeDriver: true,
        }),
        Animated.timing(colorOpacity, {
          duration: Motion.duration.base,
          easing: Motion.easing.outEase,
          toValue: 1,
          useNativeDriver: true,
        }),
      ]).start();
      previousColorRef.current = currentColor;
    }
  }, [selectedColor, colorOpacity]);

  // V11: Bounce animation + haptic when button becomes enabled
  useEffect(() => {
    if (wasDisabled.current && !disabled) {
      // Button just became enabled - play bounce animation + haptic
      // V11 Task 8: Medium impact haptic for button enable
      triggerMediumImpact();

      Animated.sequence([
        Animated.timing(scale, {
          duration: 100,
          easing: Motion.easing.outEase,
          toValue: 1.02,
          useNativeDriver: true,
        }),
        Animated.timing(scale, {
          duration: 100,
          easing: Motion.easing.inEase,
          toValue: 1,
          useNativeDriver: true,
        }),
      ]).start();
    }
    wasDisabled.current = disabled;
  }, [disabled, scale, triggerMediumImpact]);

  const bottom = useMemo(() => {
    // Keep bar above keyboard if visible; otherwise rest on safe area
    if (isKeyboardVisible) return keyboardHeight + 12;
    return Math.max(insets.bottom, 12) + 12;
  }, [insets.bottom, isKeyboardVisible, keyboardHeight]);

  // Compute gradient colors based on selected color (or default green)
  const buttonColor = selectedColor ?? DEFAULT_BUTTON_COLOR;
  const gradientColors = useMemo(() => {
    if (disabled) {
      return ['#a8a29e', '#78716c'] as const; // Disabled gray gradient
    }
    return [buttonColor, darkenColor(buttonColor, 25)] as const;
  }, [disabled, buttonColor]);

  const handlePress = useCallback(() => {
    if (!disabled) {
      triggerSuccess();
      onPress();
    }
  }, [disabled, onPress, triggerSuccess]);

  const handlePressIn = useCallback(() => {
    Animated.timing(scale, {
      duration: Motion.duration.fast,
      easing: Motion.easing.inEase,
      toValue: 0.96,
      useNativeDriver: true,
    }).start();
  }, [scale]);

  const handlePressOut = useCallback(() => {
    Animated.timing(scale, {
      duration: Motion.duration.base,
      easing: Motion.easing.outEase,
      toValue: 1,
      useNativeDriver: true,
    }).start();
  }, [scale]);

  return (
    <View
      pointerEvents='box-none'
      style={{
        bottom: 0,
        left: 0,
        paddingBottom: bottom - 12,
        position: 'absolute',
        right: 0,
      }}
    >
      {/* Gradient fade mask to smoothly hide content scrolling behind CTA */}
      <LinearGradient
        colors={['transparent', 'rgba(250, 249, 247, 0.9)', '#faf9f7']}
        locations={[0, 0.4, 1]}
        pointerEvents='none'
        style={{ height: 32 }}
      />
      <View className='bg-[#faf9f7] px-4 pb-2'>
        {/* Motivation text - V9 addition */}
        <View
          accessible
          accessibilityLabel={`${STRINGS.CREATE_HABIT.motivationHighlight}${STRINGS.CREATE_HABIT.motivationSuffix}`}
          accessibilityRole='text'
          className='items-center mb-3'
        >
          <Text className='text-[13px] text-stone-500'>
            <Text className='text-emerald-600 font-semibold'>
              {STRINGS.CREATE_HABIT.motivationHighlight}
            </Text>
            {STRINGS.CREATE_HABIT.motivationSuffix}
          </Text>
        </View>
        <View className='rounded-2xl bg-white/95 p-2 shadow-lg shadow-stone-300/40'>
          <Animated.View
            style={{ opacity: colorOpacity, transform: [{ scale }] }}
          >
            <Pressable
              accessibilityLabel={
                disabled
                  ? 'Create habit, disabled. Enter at least 2 characters.'
                  : STRINGS.CREATE_HABIT.createAction
              }
              accessibilityRole='button'
              accessibilityState={{ disabled }}
              accessibilityHint={disabled ? 'Enter a habit name to enable' : 'Tap to create your new habit'}
              disabled={disabled}
              onPress={handlePress}
              onPressIn={handlePressIn}
              onPressOut={handlePressOut}
            >
              <LinearGradient
                className='flex-row items-center justify-center rounded-xl py-3.5'
                colors={gradientColors}
                end={{ x: 1, y: 1 }}
                start={{ x: 0, y: 0 }}
              >
                <Check color='#ffffff' size={18} strokeWidth={2.5} />
                <Text className='ml-2 text-[15px] font-semibold text-white'>
                  {STRINGS.CREATE_HABIT.createAction}
                </Text>
              </LinearGradient>
            </Pressable>
          </Animated.View>
        </View>
        {/* Home indicator bar */}
        <View className='mt-3 items-center'>
          <View className='h-1 w-32 rounded-full bg-stone-300/60' />
        </View>
      </View>
    </View>
  );
};

export const StickyCreateBar = memo(StickyCreateBarComponent);

export default StickyCreateBar;

import { useCallback, useEffect, useRef } from 'react';
import { Animated, Pressable, Text, View, Keyboard } from 'react-native';
import { Motion } from '../../../constants/motion';
import useHapticFeedback from '../../../hooks/useHapticFeedback';

interface StyleSectionProps {
  colors: readonly string[];
  onSelectColor: (color: string) => void;
  selectedColor: string;
  disabled?: boolean;
}

// Animated touchable for color buttons
interface AnimatedButtonProps {
  accessibilityLabel: string;
  children: React.ReactNode;
  isSelected: boolean;
  onPress: () => void;
  style?: object;
}

const AnimatedButton = ({
  accessibilityLabel,
  children,
  isSelected,
  onPress,
  style,
}: AnimatedButtonProps) => {
  const scale = useRef(new Animated.Value(1)).current;
  const wasSelected = useRef(isSelected);
  const { triggerSelection } = useHapticFeedback();

  // Trigger selection "pop" animation when this color becomes selected
  useEffect(() => {
    if (isSelected && !wasSelected.current) {
      // Animate: quick scale up then settle back
      Animated.sequence([
        Animated.timing(scale, {
          duration: Motion.duration.fast,
          easing: Motion.easing.outEase,
          toValue: 1.15,
          useNativeDriver: true,
        }),
        Animated.spring(scale, {
          damping: 12,
          stiffness: 180,
          toValue: 1,
          useNativeDriver: true,
        }),
      ]).start();
    }
    wasSelected.current = isSelected;
  }, [isSelected, scale]);

  const handlePressIn = useCallback(() => {
    Animated.timing(scale, {
      duration: Motion.duration.fast,
      easing: Motion.easing.inEase,
      toValue: 0.9,
      useNativeDriver: true,
    }).start();
  }, [scale]);

  const handlePressOut = useCallback(() => {
    Animated.timing(scale, {
      duration: Motion.duration.base,
      easing: Motion.easing.outEase,
      toValue: 1,
      useNativeDriver: true,
    }).start();
  }, [scale]);

  const handlePress = useCallback(() => {
    triggerSelection();
    onPress();
  }, [onPress, triggerSelection]);

  return (
    <Animated.View style={{ transform: [{ scale }] }}>
      <Pressable
        accessibilityLabel={accessibilityLabel}
        accessibilityRole='button'
        accessibilityState={{ selected: isSelected }}
        style={style}
        onPress={handlePress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
      >
        {children}
      </Pressable>
    </Animated.View>
  );
};

export const StyleSection = ({
  colors,
  onSelectColor,
  selectedColor,
  disabled = false,
}: StyleSectionProps) => {
  const handleColorSelect = useCallback(
    (color: string) => {
      if (disabled) return;
      Keyboard.dismiss(); // Dismiss keyboard when tapping color
      onSelectColor(color);
    },
    [onSelectColor, disabled]
  );

  // Split colors into rows of 8 for 3-row layout
  const colorRows = [];
  for (let i = 0; i < colors.length; i += 8) {
    colorRows.push(colors.slice(i, i + 8));
  }

  return (
    <Animated.View
      className='mb-6 rounded-2xl bg-white p-4'
      pointerEvents={disabled ? 'none' : 'auto'}
      style={{ opacity: disabled ? 0.4 : 1 }}
    >
      <Text className='mb-3 text-sm font-bold text-stone-800'>Color</Text>

      {/* Color Picker - 24 colors in 3 rows of 8 */}
      <View>
        {colorRows.map((row, rowIndex) => (
          <View
            key={`color-row-${rowIndex}`}
            className='mb-2 flex-row justify-between'
          >
            {row.map((color) => (
              <AnimatedButton
                key={color}
                accessibilityLabel={`Select color ${color}`}
                isSelected={selectedColor === color}
                style={{
                  alignItems: 'center',
                  backgroundColor: color,
                  borderColor:
                    selectedColor === color ? '#292524' : 'transparent',
                  borderRadius: 18,
                  borderWidth: selectedColor === color ? 3 : 0,
                  height: 36,
                  justifyContent: 'center',
                  width: 36,
                }}
                onPress={() => handleColorSelect(color)}
              >
                {selectedColor === color && (
                  <Text className='text-xs font-bold text-white'>✓</Text>
                )}
              </AnimatedButton>
            ))}
          </View>
        ))}
      </View>
    </Animated.View>
  );
};

export default StyleSection;

import { useEffect, useRef } from 'react';
import { Animated, Modal, Pressable, Text, View } from 'react-native';
import useHapticFeedback from '../../../hooks/useHapticFeedback';

interface SuccessAnimationProps {
  habitName: string;
  onComplete: () => void;
  selectedColor: string;
  selectedEmoji: string | null;
  visible: boolean;
}

interface ConfettiParticleProps {
  color: string;
  delay: number;
  left: number;
}

const ConfettiParticle = ({ color, delay, left }: ConfettiParticleProps) => {
  const translateY = useRef(new Animated.Value(-50)).current;
  const translateX = useRef(new Animated.Value(0)).current;
  const rotate = useRef(new Animated.Value(0)).current;
  const opacity = useRef(new Animated.Value(1)).current;

  useEffect(() => {
    const randomX = (Math.random() - 0.5) * 100;
    const duration = 1500 + Math.random() * 500;

    Animated.parallel([
      Animated.timing(translateY, {
        delay,
        duration,
        toValue: 400,
        useNativeDriver: true,
      }),
      Animated.timing(translateX, {
        delay,
        duration,
        toValue: randomX,
        useNativeDriver: true,
      }),
      Animated.timing(rotate, {
        delay,
        duration,
        toValue: Math.random() * 360,
        useNativeDriver: true,
      }),
      Animated.timing(opacity, {
        delay: delay + duration - 300,
        duration: 300,
        toValue: 0,
        useNativeDriver: true,
      }),
    ]).start();
  }, [delay, opacity, rotate, translateX, translateY]);

  return (
    <Animated.View
      className="absolute h-3 w-3"
      style={{
        backgroundColor: color,
        borderRadius: 2,
        left: `${left}%`,
        opacity,
        top: 0,
        transform: [
          { translateY },
          { translateX },
          {
            rotate: rotate.interpolate({
              inputRange: [0, 360],
              outputRange: ['0deg', '360deg'],
            }),
          },
        ],
      }}
    />
  );
};

const CONFETTI_COLORS = ['#f59e0b', '#3b82f6', '#10b981', '#ec4899', '#8b5cf6', '#f97316'];

export const SuccessAnimation = ({
  habitName,
  onComplete,
  selectedColor,
  selectedEmoji,
  visible,
}: SuccessAnimationProps) => {
  const { triggerSuccess } = useHapticFeedback();

  // Animation values
  const backdropOpacity = useRef(new Animated.Value(0)).current;
  const cardScale = useRef(new Animated.Value(0.5)).current;
  const cardOpacity = useRef(new Animated.Value(0)).current;
  const iconScale = useRef(new Animated.Value(0)).current;
  const textOpacity = useRef(new Animated.Value(0)).current;
  const buttonOpacity = useRef(new Animated.Value(0)).current;
  const buttonTranslateY = useRef(new Animated.Value(20)).current;

  useEffect(() => {
    if (visible) {
      triggerSuccess();

      // Sequence of animations
      Animated.sequence([
        // Backdrop fade in
        Animated.timing(backdropOpacity, {
          duration: 200,
          toValue: 1,
          useNativeDriver: true,
        }),
        // Card bounce in
        Animated.parallel([
          Animated.spring(cardScale, {
            damping: 10,
            stiffness: 200,
            toValue: 1,
            useNativeDriver: true,
          }),
          Animated.timing(cardOpacity, {
            duration: 200,
            toValue: 1,
            useNativeDriver: true,
          }),
        ]),
        // Icon bounce
        Animated.spring(iconScale, {
          damping: 8,
          stiffness: 300,
          toValue: 1,
          useNativeDriver: true,
        }),
        // Text fade in
        Animated.timing(textOpacity, {
          duration: 200,
          toValue: 1,
          useNativeDriver: true,
        }),
        // Button slide up
        Animated.parallel([
          Animated.timing(buttonOpacity, {
            duration: 200,
            toValue: 1,
            useNativeDriver: true,
          }),
          Animated.spring(buttonTranslateY, {
            damping: 15,
            stiffness: 200,
            toValue: 0,
            useNativeDriver: true,
          }),
        ]),
      ]).start();
    }
  }, [
    visible,
    triggerSuccess,
    backdropOpacity,
    cardScale,
    cardOpacity,
    iconScale,
    textOpacity,
    buttonOpacity,
    buttonTranslateY,
  ]);

  const handleComplete = () => {
    // Animate out
    Animated.parallel([
      Animated.timing(cardScale, {
        duration: 200,
        toValue: 0.9,
        useNativeDriver: true,
      }),
      Animated.timing(cardOpacity, {
        duration: 200,
        toValue: 0,
        useNativeDriver: true,
      }),
      Animated.timing(backdropOpacity, {
        duration: 200,
        toValue: 0,
        useNativeDriver: true,
      }),
    ]).start(() => {
      onComplete();
    });
  };

  if (!visible) return null;

  // Generate confetti particles
  const confettiParticles = Array.from({ length: 30 }, (_, i) => ({
    color: CONFETTI_COLORS[i % CONFETTI_COLORS.length],
    delay: Math.random() * 400,
    id: i,
    left: Math.random() * 100,
  }));

  return (
    <Modal animationType="none" transparent visible={visible}>
      <Animated.View
        className="flex-1 items-center justify-center bg-black/50"
        style={{ opacity: backdropOpacity }}
      >
        {/* Confetti */}
        <View className="absolute inset-x-0 top-0 h-full overflow-hidden">
          {confettiParticles.map((particle) => (
            <ConfettiParticle
              key={particle.id}
              color={particle.color}
              delay={particle.delay}
              left={particle.left}
            />
          ))}
        </View>

        {/* Success Card */}
        <Animated.View
          className="mx-8 items-center rounded-3xl bg-white px-8 py-10"
          style={{
            opacity: cardOpacity,
            shadowColor: '#000',
            shadowOffset: { height: 10, width: 0 },
            shadowOpacity: 0.15,
            shadowRadius: 20,
            transform: [{ scale: cardScale }],
          }}
        >
          {/* Animated Icon */}
          <Animated.View
            className="mb-6 h-24 w-24 items-center justify-center rounded-3xl"
            style={{
              backgroundColor: selectedColor || '#DBEAFE',
              transform: [{ scale: iconScale }],
            }}
          >
            <Text className="text-5xl">{selectedEmoji || '🎯'}</Text>
          </Animated.View>

          {/* Success Text */}
          <Animated.View className="items-center" style={{ opacity: textOpacity }}>
            <Text className="mb-2 text-center text-2xl font-bold tracking-tight text-stone-800">
              {habitName}
            </Text>
            <Text className="text-center text-lg text-stone-500">created! 🎉</Text>
            <Text className="mt-4 text-center text-sm text-stone-400">
              Your streak starts now
            </Text>
          </Animated.View>

          {/* CTA Button */}
          <Animated.View
            className="mt-8 w-full"
            style={{
              opacity: buttonOpacity,
              transform: [{ translateY: buttonTranslateY }],
            }}
          >
            <Pressable
              accessibilityLabel="Start tracking habit"
              accessibilityRole="button"
              className="items-center rounded-2xl bg-stone-900 py-4"
              onPress={handleComplete}
            >
              <Text className="text-base font-semibold text-white">
                Let's get started! →
              </Text>
            </Pressable>
          </Animated.View>
        </Animated.View>
      </Animated.View>
    </Modal>
  );
};

export default SuccessAnimation;

import { useCallback, useRef } from 'react';
import { Animated, Pressable, Text, View } from 'react-native';
import { Motion } from '../../../constants/motion';
import useHapticFeedback from '../../../hooks/useHapticFeedback';

interface SuggestionChip {
  name: string;
  emoji: string;
  color: string;
}

interface SuggestionChipsProps {
  onSelect: (chip: SuggestionChip) => void;
  visible: boolean;
}

const SUGGESTION_CHIPS: SuggestionChip[] = [
  { name: 'Drink water', emoji: '💧', color: '#3B82F6' },
  { name: 'Read 10 min', emoji: '📖', color: '#8B5CF6' },
  { name: 'Meditate', emoji: '🧘', color: '#22C55E' },
  { name: 'Exercise', emoji: '🏃', color: '#F97316' },
  { name: 'Journal', emoji: '✍️', color: '#EC4899' },
  { name: 'Sleep 8h', emoji: '😴', color: '#1E293B' },
];

interface ChipButtonProps {
  chip: SuggestionChip;
  onPress: () => void;
}

const ChipButton = ({ chip, onPress }: ChipButtonProps) => {
  const scale = useRef(new Animated.Value(1)).current;
  const { triggerSelection } = useHapticFeedback();

  const handlePressIn = useCallback(() => {
    Animated.timing(scale, {
      duration: Motion.duration.fast,
      easing: Motion.easing.inEase,
      toValue: 0.95,
      useNativeDriver: true,
    }).start();
  }, [scale]);

  const handlePressOut = useCallback(() => {
    Animated.spring(scale, {
      toValue: 1,
      damping: 12,
      stiffness: 200,
      useNativeDriver: true,
    }).start();
  }, [scale]);

  const handlePress = useCallback(() => {
    triggerSelection();
    onPress();
  }, [triggerSelection, onPress]);

  return (
    <Animated.View style={{ transform: [{ scale }] }}>
      <Pressable
        accessibilityLabel={`Quick add ${chip.name} habit`}
        accessibilityRole="button"
        className="mr-2 mb-2 flex-row items-center rounded-full bg-white px-3 py-2"
        style={{
          borderWidth: 1,
          borderColor: '#e7e5e4', // stone-200
          shadowColor: '#000',
          shadowOffset: { width: 0, height: 1 },
          shadowOpacity: 0.05,
          shadowRadius: 2,
        }}
        onPress={handlePress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
      >
        <Text className="mr-1.5 text-base">{chip.emoji}</Text>
        <Text className="text-sm font-medium text-stone-700">{chip.name}</Text>
      </Pressable>
    </Animated.View>
  );
};

export const SuggestionChips = ({ onSelect, visible }: SuggestionChipsProps) => {
  if (!visible) return null;

  return (
    <View className="mb-3">
      <Text className="mb-2 text-xs font-medium text-stone-500">
        QUICK START
      </Text>
      <View className="flex-row flex-wrap">
        {SUGGESTION_CHIPS.map((chip) => (
          <ChipButton
            key={chip.name}
            chip={chip}
            onPress={() => onSelect(chip)}
          />
        ))}
      </View>
    </View>
  );
};

export default SuggestionChips;
export type { SuggestionChip };

