export const useCreateHabitModal = ({ visible, onClose, habitToEdit }: CreateHabitModalProps) => {
  const isEditMode = !!habitToEdit;
  const form = useHabitForm({ habitToEdit });
  const { triggerSuccess } = useHapticFeedback();
  const {
    closeColorPicker,
    dayPhase,
    fullHabitName,
    habitName,
    reminderSound,
    reminderTime,
    remindersEnabled,
    resetForm,
    selectedColor,
    selectedEmoji,
    setFrequency,
    setHabitName,
    setSelectedColor,
    setSelectedEmoji,
    setShowTimePicker,
  } = form;
  const createHabit = useMutation(api.habits.create);
  const updateHabit = useMutation(api.habits.update);
  const applyTemplate = useCallback(
    (template: HabitTemplate) => {
      const { emoji, name } = extractTemplateDetails(template);
      setSelectedEmoji(emoji);
      setHabitName(name);
      if (template.iconColor) setSelectedColor(template.iconColor);
      if (template.frequency) setFrequency(template.frequency);
    },
    [setHabitName, setSelectedColor, setSelectedEmoji, setFrequency]
  );

  const template = useTemplateBrowser({ isEditMode, visible, onTemplateSelect: applyTemplate });
  const science = useScienceModal({ onSelectTemplate: applyTemplate });
  const { reset: resetTemplateCategories, closeTemplateBrowser } = template;
  const { close: closeScienceModal } = science;

  useEffect(() => {
    if (!visible || isEditMode) return;
    resetForm();
    resetTemplateCategories();
    closeTemplateBrowser();
    closeScienceModal();
  }, [
    visible,
    isEditMode,
    resetForm,
    resetTemplateCategories,
    closeTemplateBrowser,
    closeScienceModal,
  ]);
  const handleCreate = useCallback(async () => {
    if (!habitName.trim() || !fullHabitName) return;

    let hasReminders = remindersEnabled;
    if (remindersEnabled) {
      if (Platform.OS === 'web') {
        Alert.alert(
          'Reminders on Mobile Only',
          'Local reminder notifications can only be scheduled from the iOS/Android app. Your reminder settings will be saved.'
        );
      } else {
        const allowed = await ensureNotificationPermissions();
        if (!allowed) {
          hasReminders = false;
          Alert.alert(
            'Notifications Disabled',
            'Enable notifications in your device settings to receive habit reminders.'
          );
        }
      }
    }

    if (isEditMode && habitToEdit) {
      if (hasReminders) {
        if (Platform.OS !== 'web') {
          const scheduled = await scheduleHabitReminder({
            body: 'Time to check in on your habit progress!',
            habitId: habitToEdit._id,
            reminderTime,
            skipPermissionCheck: true,
            title: fullHabitName,
          });

          if (!scheduled) {
            hasReminders = false;
            Alert.alert(
              'Reminder Not Scheduled',
              'We could not schedule this reminder on this device. Your reminder settings were saved.'
            );
            await cancelHabitReminder(habitToEdit._id);
          }
        }
      } else {
        if (Platform.OS !== 'web') {
          await cancelHabitReminder(habitToEdit._id);
        }
      }

      await updateHabit({
        habitId: habitToEdit._id,
        icon: selectedEmoji ?? undefined,
        iconColor: selectedColor,
        name: fullHabitName,
        notes: habitToEdit.notes ?? '',
        preferredTime: dayPhase ?? undefined,
        remindersEnabled: hasReminders,
        reminderSound: hasReminders ? reminderSound : undefined,
        reminderTime: hasReminders ? formatReminderTime(reminderTime) : undefined,
      });
    } else {
      const habitId = await createHabit({
        icon: selectedEmoji ?? undefined,
        iconColor: selectedColor,
        name: fullHabitName,
        notes: '',
        preferredTime: dayPhase ?? undefined,
        remindersEnabled: hasReminders,
        reminderSound: hasReminders ? reminderSound : undefined,
        reminderTime: hasReminders ? formatReminderTime(reminderTime) : undefined,
      });
      if (hasReminders && habitId && Platform.OS !== 'web') {
        const scheduled = await scheduleHabitReminder({
          body: 'Time to check in on your habit progress!',
          habitId,
          reminderTime,
          skipPermissionCheck: true,
          title: fullHabitName,
        });

        if (!scheduled) {
          Alert.alert(
            'Reminder Not Scheduled',
            'We could not schedule this reminder on this device. Your reminder settings were saved.'
          );
        }
      }
    }

    resetForm();
    closeColorPicker();
    setShowTimePicker(false);
    template.reset();
    template.closeTemplateBrowser();
    science.close();
    triggerSuccess();
    onClose();
  }, [createHabit, closeColorPicker, dayPhase, habitToEdit, isEditMode, onClose, reminderSound, reminderTime, remindersEnabled, resetForm, science, selectedColor, selectedEmoji, setShowTimePicker, template, updateHabit, fullHabitName]);

  return { isEditMode, form, template, science, handleCreate };
};

import { useCallback, useEffect, useMemo, useState } from 'react';
import { DEFAULT_COLOR } from '../constants';
import type { HabitDoc } from '../types';
import { buildHabitName, parseHabitName, parseReminderTime } from '../utils';
import {
  type HubermanPhase,
  getPhaseFromPreferredTime,
} from '../../../constants/hubermanPhases';
import {
  type ReminderOption,
  getReminderTimeForOption,
  REMINDER_OPTIONS,
} from '../components/ReminderSelector';
import { getSmartReminderDefault } from '../../../utils/reminderDefaults';

const DEFAULT_SOUND = 'Default';

/**
 * Derives the reminder option from habit's reminder time
 * Maps existing reminder times to V8 unified options
 */
const getReminderOptionFromTime = (
  remindersEnabled: boolean | undefined,
  reminderTime: string | undefined
): ReminderOption => {
  if (!remindersEnabled || !reminderTime) {
    return 'none';
  }

  // Parse the time string (e.g., "7:00 AM", "12:00 PM", "8:00 PM")
  const parsed = parseReminderTime(reminderTime);
  const hours = parsed.getHours();

  // Map to closest option based on hour
  if (hours >= 5 && hours < 10) return 'morning';
  if (hours >= 10 && hours < 16) return 'midday';
  if (hours >= 16 || hours < 5) return 'evening';

  return 'none';
};

interface UseHabitFormOptions {
  habitToEdit?: HabitDoc | null;
}

export const useHabitForm = ({ habitToEdit }: UseHabitFormOptions) => {
  const parsed = useMemo(
    () => parseHabitName(habitToEdit?.name ?? ''),
    [habitToEdit?.name]
  );

  const [habitName, setHabitName] = useState(parsed.name);
  const [selectedEmoji, setSelectedEmoji] = useState<string | null>(
    parsed.emoji
  );
  const [selectedColor, setSelectedColor] = useState(
    habitToEdit?.iconColor ?? DEFAULT_COLOR
  );
  const [isColorPickerVisible, setColorPickerVisible] = useState(false);
  const [remindersEnabled, setRemindersEnabled] = useState(
    habitToEdit?.remindersEnabled ?? false
  );
  const [reminderTime, setReminderTime] = useState(() =>
    parseReminderTime(habitToEdit?.reminderTime)
  );
  const [showTimePicker, setShowTimePicker] = useState(false);
  const [reminderSound, setReminderSound] = useState(
    habitToEdit?.reminderSound ?? DEFAULT_SOUND
  );
  const [frequency, setFrequency] = useState<string>(
    habitToEdit?.frequency ?? ''
  );
  const [dayPhase, setDayPhase] = useState<HubermanPhase | null>(
    getPhaseFromPreferredTime(habitToEdit?.preferredTime)
  );
  const [reminderOption, setReminderOptionState] = useState<ReminderOption>(
    getReminderOptionFromTime(
      habitToEdit?.remindersEnabled,
      habitToEdit?.reminderTime
    )
  );

  const fullHabitName = useMemo(
    () => buildHabitName(selectedEmoji, habitName),
    [selectedEmoji, habitName]
  );

  /**
   * Sets the reminder option and syncs related states
   * - Updates remindersEnabled based on option
   * - Sets reminderTime from the option's predefined time
   * - Maps to corresponding dayPhase for habit metadata
   */
  const setReminderOption = useCallback((option: ReminderOption) => {
    setReminderOptionState(option);

    if (option === 'none') {
      setRemindersEnabled(false);
      setDayPhase(null);
    } else {
      setRemindersEnabled(true);
      const time = getReminderTimeForOption(option);
      if (time) {
        setReminderTime(time);
      }

      // Map reminder option to Huberman phase for habit metadata
      const phaseMap: Record<Exclude<ReminderOption, 'none'>, HubermanPhase> = {
        evening: 'phase3_pull',
        midday: 'phase2_pivot',
        morning: 'phase1_push',
      };
      setDayPhase(phaseMap[option]);
    }
  }, []);

  useEffect(() => {
    if (!habitToEdit) {
      return;
    }

    setHabitName(parsed.name);
    setSelectedEmoji(parsed.emoji);
    setSelectedColor(habitToEdit.iconColor ?? DEFAULT_COLOR);
    setRemindersEnabled(habitToEdit.remindersEnabled ?? false);
    setReminderTime(parseReminderTime(habitToEdit.reminderTime));
    setReminderSound(habitToEdit.reminderSound ?? DEFAULT_SOUND);
    setFrequency(habitToEdit.frequency ?? '');
    setDayPhase(getPhaseFromPreferredTime(habitToEdit.preferredTime));
    setReminderOptionState(
      getReminderOptionFromTime(
        habitToEdit.remindersEnabled,
        habitToEdit.reminderTime
      )
    );
  }, [habitToEdit, parsed]);

  const resetForm = useCallback(() => {
    // V11: Use time-aware smart default for reminder selection
    const smartDefault = getSmartReminderDefault();

    setHabitName('');
    setSelectedEmoji(null);
    setSelectedColor(DEFAULT_COLOR);
    setColorPickerVisible(false);
    setRemindersEnabled(false);
    setReminderTime(parseReminderTime());
    setShowTimePicker(false);
    setReminderSound(DEFAULT_SOUND);
    setFrequency('');
    setDayPhase(null);
    setReminderOptionState(smartDefault);
  }, []);

  return {
    closeColorPicker: () => setColorPickerVisible(false),
    dayPhase,
    frequency,
    fullHabitName,
    habitName,
    isColorPickerVisible,
    openColorPicker: () => setColorPickerVisible(true),
    reminderOption,
    remindersEnabled,
    reminderSound,
    reminderTime,
    resetForm,
    selectedColor,
    selectedEmoji,
    setDayPhase,
    setFrequency,
    setHabitName,
    setReminderOption,
    setRemindersEnabled,
    setReminderSound,
    setReminderTime,
    setSelectedColor,
    setSelectedEmoji,
    setShowTimePicker,
    showTimePicker,
  };
};

import { useMemo } from 'react';
import { useQuery } from 'convex/react';
import { api } from '../../../../convex/_generated/api';
import type { Category, HabitTemplate } from '../types';

export const useHabitTemplates = (category: Category) => {
  const templates = useQuery(api.templates.list, {});
  const isLoading = templates === undefined;

  const filtered = useMemo(() => {
    if (!templates) return [];
    if (category === 'all') return templates;
    return templates.filter((template) => template.category === category);
  }, [category, templates]);

  return { filtered, isLoading };
};

import { useCallback, useState } from 'react';
import type { HabitTemplate } from '../types';

interface UseScienceModalOptions {
  onSelectTemplate: (template: HabitTemplate) => void;
}

export const useScienceModal = ({ onSelectTemplate }: UseScienceModalOptions) => {
  const [isVisible, setVisible] = useState(false);
  const [template, setTemplate] = useState<HabitTemplate | null>(null);

  const open = useCallback((next: HabitTemplate) => {
    setTemplate(next);
    setVisible(true);
  }, []);

  const close = useCallback(() => setVisible(false), []);

  const useTemplate = useCallback(() => {
    if (!template) return;
    onSelectTemplate(template);
    setVisible(false);
  }, [template, onSelectTemplate]);

  return { isVisible, template, open, close, useTemplate };
};

import { useCallback, useMemo, useRef } from 'react';
import { Animated, Easing } from 'react-native';

export const useTemplateAnimation = () => {
  const anim = useRef(new Animated.Value(0)).current;

  const chevronRotation = useMemo(
    () =>
      anim.interpolate({
        inputRange: [0, 1],
        outputRange: ['0deg', '90deg'] as const,
      }),
    [anim]
  );

  const translateY = useMemo(
    () =>
      anim.interpolate({
        inputRange: [0, 1],
        outputRange: [-12, 0],
      }),
    [anim]
  );

  const animateOpen = useCallback(() => {
    anim.stopAnimation();
    Animated.timing(anim, {
      duration: 220,
      easing: Easing.out(Easing.ease),
      toValue: 1,
      useNativeDriver: true,
    }).start();
  }, [anim]);

  const animateClose = useCallback((onFinished?: () => void) => {
    anim.stopAnimation();
    Animated.timing(anim, {
      duration: 180,
      easing: Easing.out(Easing.ease),
      toValue: 0,
      useNativeDriver: true,
    }).start(({ finished }) => {
      if (finished) onFinished?.();
    });
  }, [anim]);

  const resetAnimation = useCallback(() => {
    anim.stopAnimation();
    anim.setValue(0);
  }, [anim]);

  return { anim, chevronRotation, translateY, animateOpen, animateClose, resetAnimation };
};

import { useCallback, useEffect, useRef, useState } from 'react';
import type { ScrollView } from 'react-native';
import { useQuery } from 'convex/react';
import { api } from '../../../../convex/_generated/api';
import type { Category, CategoryFilter, HabitTemplate } from '../types';
import { useKeyboardState } from './useKeyboardState';
import { useTemplateAnimation } from './useTemplateAnimation';
import { useTemplateBrowserHandlers } from './useTemplateBrowserHandlers';
import { useTemplateScrollIndicators } from './useTemplateScrollIndicators';
import { useHabitTemplates } from './useHabitTemplates';
interface UseTemplateBrowserOptions {
  isEditMode: boolean;
  visible: boolean;
  onTemplateSelect: (template: HabitTemplate) => void;
}

export const useTemplateBrowser = ({ isEditMode, visible, onTemplateSelect }: UseTemplateBrowserOptions) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isVisible, setIsVisible] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<Category>('all');
  const [hasScrolledPastHero, setHasScrolledPastHero] = useState(false);
  const scrollViewRef = useRef<ScrollView | null>(null);
  const { isKeyboardVisible, keyboardHeight } = useKeyboardState();
  const { anim, chevronRotation, translateY, animateOpen, animateClose, resetAnimation } =
    useTemplateAnimation();
  const { showTopShadow, showBottomShadow, handleScroll, handleContentSizeChange, handleLayout, resetIndicators } =
    useTemplateScrollIndicators();
  const { filtered, isLoading } = useHabitTemplates(selectedCategory);
  const categoriesQuery = useQuery(api.categories.list, {});
  const fallbackCategories: CategoryFilter[] = [
    { icon: '✨', id: 'all', label: 'All' },
  ];
  const categories =
    (categoriesQuery as CategoryFilter[] | undefined) ?? fallbackCategories;
  const handleCategoryPress = useCallback((category: Category) => setSelectedCategory(category), []);
  const {
    openBrowser,
    closeBrowser,
    handleHeroPress,
    handleMainScroll,
    handleReminderPress,
    handleTemplateSelect,
    resetVisibility,
  } = useTemplateBrowserHandlers({
    isEditMode,
    isOpen,
    setIsOpen,
    setIsVisible,
    setHasScrolledPastHero,
    animateOpen,
    animateClose,
    scrollViewRef,
    onTemplateSelect,
  });

  useEffect(() => { resetIndicators(); }, [filtered.length, isOpen, resetIndicators]);
  useEffect(() => {
    if (visible) return;
    resetVisibility();
    resetAnimation();
    setSelectedCategory('all');
  }, [resetAnimation, resetVisibility, visible]);
  const shouldShowTemplateReminder = !isEditMode && hasScrolledPastHero && !isVisible;
  const reminderBottomOffset = isKeyboardVisible ? keyboardHeight + 24 : 24;
  const reset = useCallback(() => setSelectedCategory('all'), []);

  return {
    categories,
    chevronRotation,
    closeTemplateBrowser: closeBrowser,
    filteredTemplates: filtered,
    handleCategoryPress,
    handleHeroPress,
    handleMainScroll,
    handleReminderPress,
    handleTemplateListContentSizeChange: handleContentSizeChange,
    handleTemplateListLayout: handleLayout,
    handleTemplateListScroll: handleScroll,
    handleTemplateSelect,
    isLoadingTemplates: isLoading,
    isTemplateBrowserOpen: isOpen,
    isTemplateBrowserVisible: isVisible,
    reminderBottomOffset,
    reset,
    scrollViewRef,
    selectedCategory,
    shouldShowTemplateReminder,
    showTemplateBottomShadow: showBottomShadow,
    showTemplateTopShadow: showTopShadow,
    templateBrowserAnim: anim,
    templateBrowserTranslate: translateY,
  };
};

import { useCallback, type Dispatch, type SetStateAction } from 'react';
import type { NativeScrollEvent, NativeSyntheticEvent, ScrollView } from 'react-native';
import type { HabitTemplate } from '../types';

interface UseTemplateBrowserHandlersOptions {
  isEditMode: boolean;
  isOpen: boolean;
  setIsOpen: Dispatch<SetStateAction<boolean>>;
  setIsVisible: Dispatch<SetStateAction<boolean>>;
  setHasScrolledPastHero: Dispatch<SetStateAction<boolean>>;
  animateOpen: () => void;
  animateClose: (onFinished?: () => void) => void;
  scrollViewRef: React.RefObject<ScrollView | null>;
  onTemplateSelect: (template: HabitTemplate) => void;
}

export const useTemplateBrowserHandlers = ({
  isEditMode,
  isOpen,
  setIsOpen,
  setIsVisible,
  setHasScrolledPastHero,
  animateOpen,
  animateClose,
  scrollViewRef,
  onTemplateSelect,
}: UseTemplateBrowserHandlersOptions) => {
  const openBrowser = useCallback(() => {
    setIsOpen(true);
    setIsVisible(true);
    setHasScrolledPastHero(false);
    animateOpen();
  }, [animateOpen, setHasScrolledPastHero, setIsOpen, setIsVisible]);

  const closeBrowser = useCallback(() => {
    animateClose(() => setIsVisible(false));
    setIsOpen(false);
  }, [animateClose, setIsOpen, setIsVisible]);

  const handleHeroPress = useCallback(() => {
    if (isOpen) return closeBrowser();
    openBrowser();
    requestAnimationFrame(() =>
      scrollViewRef.current?.scrollTo({ animated: true, y: 0 })
    );
  }, [closeBrowser, isOpen, openBrowser, scrollViewRef]);

  const handleMainScroll = useCallback(
    (event: NativeSyntheticEvent<NativeScrollEvent>) => {
      if (isEditMode || isOpen) return;
      const next = event.nativeEvent.contentOffset.y > 120;
      setHasScrolledPastHero((prev) => (prev === next ? prev : next));
    },
    [isEditMode, isOpen, setHasScrolledPastHero]
  );

  const handleReminderPress = useCallback(() => {
    if (isOpen) return;
    scrollViewRef.current?.scrollTo({ animated: true, y: 0 });
    setTimeout(openBrowser, 160);
  }, [isOpen, openBrowser, scrollViewRef]);

  const handleTemplateSelect = useCallback(
    (template: HabitTemplate) => {
      onTemplateSelect(template);
      closeBrowser();
    },
    [closeBrowser, onTemplateSelect]
  );

  const resetVisibility = useCallback(() => {
    setIsOpen(false);
    setIsVisible(false);
    setHasScrolledPastHero(false);
  }, [setHasScrolledPastHero, setIsOpen, setIsVisible]);

  return {
    openBrowser,
    closeBrowser,
    handleHeroPress,
    handleMainScroll,
    handleReminderPress,
    handleTemplateSelect,
    resetVisibility,
  };
};

import { useCallback, useState } from 'react';
import type {
  NativeScrollEvent,
  NativeSyntheticEvent,
  ScrollView,
} from 'react-native';

interface UseTemplateHeroOptions {
  isEditMode: boolean;
  isOpen: boolean;
  scrollViewRef: React.RefObject<ScrollView | null>;
  openBrowser: () => void;
  closeBrowser: () => void;
}

export const useTemplateHero = ({
  isEditMode,
  isOpen,
  scrollViewRef,
  openBrowser,
  closeBrowser,
}: UseTemplateHeroOptions) => {
  const [hasScrolledPastHero, setHasScrolledPastHero] = useState(false);

  const handleHeroPress = useCallback(() => {
    if (isOpen) return closeBrowser();
    openBrowser();
    requestAnimationFrame(() =>
      scrollViewRef.current?.scrollTo({ animated: true, y: 0 })
    );
  }, [closeBrowser, isOpen, openBrowser, scrollViewRef]);

  const handleMainScroll = useCallback(
    (event: NativeSyntheticEvent<NativeScrollEvent>) => {
      if (isEditMode || isOpen) return;
      const offsetY = event.nativeEvent.contentOffset.y;
      setHasScrolledPastHero((prev) => {
        const next = offsetY > 120;
        return prev === next ? prev : next;
      });
    },
    [isEditMode, isOpen]
  );

  const handleReminderPress = useCallback(() => {
    if (isOpen) return;
    scrollViewRef.current?.scrollTo({ animated: true, y: 0 });
    setTimeout(openBrowser, 160);
  }, [isOpen, openBrowser, scrollViewRef]);

  return {
    hasScrolledPastHero,
    setHasScrolledPastHero,
    handleHeroPress,
    handleMainScroll,
    handleReminderPress,
  };
};

import { useCallback, useRef, useState } from 'react';
import type { LayoutChangeEvent, NativeScrollEvent, NativeSyntheticEvent } from 'react-native';

export const useTemplateScrollIndicators = () => {
  const scrollOffset = useRef(0);
  const metrics = useRef({ contentHeight: 0, layoutHeight: 0 });
  const [showTopShadow, setShowTopShadow] = useState(false);
  const [showBottomShadow, setShowBottomShadow] = useState(false);

  const updateShadows = useCallback(() => {
    const { contentHeight, layoutHeight } = metrics.current;
    const offsetY = scrollOffset.current;
    const hasScrollable = contentHeight > layoutHeight + 1;
    setShowTopShadow(hasScrollable && offsetY > 4);
    setShowBottomShadow(
      hasScrollable && contentHeight - (offsetY + layoutHeight) > 4
    );
  }, []);

  const handleScroll = useCallback(
    (event: NativeSyntheticEvent<NativeScrollEvent>) => {
      const { contentOffset, layoutMeasurement, contentSize } =
        event.nativeEvent;
      scrollOffset.current = contentOffset.y;
      metrics.current = {
        contentHeight: contentSize.height,
        layoutHeight: layoutMeasurement.height,
      };
      updateShadows();
    },
    [updateShadows]
  );

  const handleContentSizeChange = useCallback(
    (_width: number, height: number) => {
      metrics.current = { ...metrics.current, contentHeight: height };
      updateShadows();
    },
    [updateShadows]
  );

  const handleLayout = useCallback(
    (event: LayoutChangeEvent) => {
      metrics.current = {
        ...metrics.current,
        layoutHeight: event.nativeEvent.layout.height,
      };
      updateShadows();
    },
    [updateShadows]
  );

  const resetIndicators = useCallback(() => {
    scrollOffset.current = 0;
    metrics.current = { ...metrics.current, contentHeight: 0 };
    setShowTopShadow(false);
    setShowBottomShadow(false);
  }, []);

  return {
    showTopShadow,
    showBottomShadow,
    handleScroll,
    handleContentSizeChange,
    handleLayout,
    resetIndicators,
  };
};

