import { Animated, Easing } from 'react-native';

export function runHighlightAnimation(
  cardScale: Animated.Value,
  highlightGlow: Animated.Value
) {
  Animated.parallel([
    Animated.sequence([
      Animated.spring(cardScale, {
        damping: 12,
        stiffness: 200,
        toValue: 1.04,
        useNativeDriver: true,
      }),
      Animated.spring(cardScale, {
        damping: 15,
        stiffness: 250,
        toValue: 1,
        useNativeDriver: true,
      }),
    ]),
    Animated.sequence([
      Animated.timing(highlightGlow, {
        duration: 300,
        easing: Easing.out(Easing.ease),
        toValue: 1,
        useNativeDriver: true,
      }),
      Animated.timing(highlightGlow, {
        duration: 400,
        easing: Easing.inOut(Easing.ease),
        toValue: 0.5,
        useNativeDriver: true,
      }),
      Animated.timing(highlightGlow, {
        duration: 300,
        easing: Easing.out(Easing.ease),
        toValue: 1,
        useNativeDriver: true,
      }),
      Animated.timing(highlightGlow, {
        duration: 500,
        easing: Easing.in(Easing.ease),
        toValue: 0,
        useNativeDriver: true,
      }),
    ]),
  ]).start();
}

export function runIconPulseLoop(iconPulse: Animated.Value) {
  Animated.loop(
    Animated.sequence([
      Animated.timing(iconPulse, {
        duration: 1000,
        easing: Easing.inOut(Easing.ease),
        toValue: 1.05,
        useNativeDriver: true,
      }),
      Animated.timing(iconPulse, {
        duration: 1000,
        easing: Easing.inOut(Easing.ease),
        toValue: 1,
        useNativeDriver: true,
      }),
    ])
  ).start();
}

export function runNewRecordAnimation(
  newRecordScale: Animated.Value,
  newRecordOpacity: Animated.Value,
  cardScale: Animated.Value
) {
  Animated.parallel([
    Animated.spring(newRecordScale, {
      friction: 5,
      tension: 200,
      toValue: 1,
      useNativeDriver: true,
    }),
    Animated.timing(newRecordOpacity, {
      duration: 200,
      toValue: 1,
      useNativeDriver: true,
    }),
    Animated.sequence([
      Animated.spring(cardScale, {
        friction: 8,
        tension: 200,
        toValue: 1.03,
        useNativeDriver: true,
      }),
      Animated.spring(cardScale, {
        friction: 10,
        tension: 200,
        toValue: 1,
        useNativeDriver: true,
      }),
    ]),
  ]).start();
}

export function hideNewRecordBadge(
  newRecordScale: Animated.Value,
  newRecordOpacity: Animated.Value,
  setShowNewRecord: (show: boolean) => void
) {
  Animated.parallel([
    Animated.timing(newRecordScale, {
      duration: 200,
      toValue: 0,
      useNativeDriver: true,
    }),
    Animated.timing(newRecordOpacity, {
      duration: 200,
      toValue: 0,
      useNativeDriver: true,
    }),
  ]).start(() => setShowNewRecord(false));
}

import { useRef, useEffect, useState } from 'react';
import { Animated, Easing } from 'react-native';
import {
  runHighlightAnimation,
  runIconPulseLoop,
  runNewRecordAnimation,
  hideNewRecordBadge,
} from './animationSequences';

interface AnimationParams {
  isJustCreated: boolean;
  reduceMotionPreference: boolean;
  isWeekComplete: boolean;
  isNewPersonalRecord: boolean;
  triggerSuccess: () => void;
}

export function useDraggableHabitAnimations({
  isJustCreated,
  reduceMotionPreference,
  isWeekComplete,
  isNewPersonalRecord,
  triggerSuccess,
}: AnimationParams) {
  const fade = useRef(new Animated.Value(0)).current;
  const translateY = useRef(new Animated.Value(12)).current;
  const archiveFlash = useRef(new Animated.Value(0)).current;
  const cardScale = useRef(new Animated.Value(1)).current;
  const iconPulse = useRef(new Animated.Value(1)).current;
  const highlightGlow = useRef(new Animated.Value(0)).current;
  const newRecordScale = useRef(new Animated.Value(0)).current;
  const newRecordOpacity = useRef(new Animated.Value(0)).current;
  const [showNewRecord, setShowNewRecord] = useState(false);

  useEntranceAnimation(fade, translateY);
  useHighlightAnimation(
    isJustCreated,
    reduceMotionPreference,
    cardScale,
    highlightGlow
  );
  useIconPulse(isWeekComplete, reduceMotionPreference, iconPulse);
  useNewRecordAnimation(
    isNewPersonalRecord,
    reduceMotionPreference,
    triggerSuccess,
    newRecordScale,
    newRecordOpacity,
    cardScale,
    setShowNewRecord
  );

  return {
    archiveFlash,
    cardScale,
    fade,
    highlightGlow,
    iconPulse,
    newRecordOpacity,
    newRecordScale,
    showNewRecord,
    translateY,
  };
}

function useEntranceAnimation(
  fade: Animated.Value,
  translateY: Animated.Value
) {
  useEffect(() => {
    Animated.parallel([
      Animated.timing(fade, {
        duration: 320,
        easing: Easing.out(Easing.cubic),
        toValue: 1,
        useNativeDriver: true,
      }),
      Animated.timing(translateY, {
        duration: 320,
        easing: Easing.out(Easing.cubic),
        toValue: 0,
        useNativeDriver: true,
      }),
    ]).start();
  }, [fade, translateY]);
}

function useHighlightAnimation(
  isJustCreated: boolean,
  reduceMotionPreference: boolean,
  cardScale: Animated.Value,
  highlightGlow: Animated.Value
) {
  useEffect(() => {
    if (!isJustCreated || reduceMotionPreference) {
      highlightGlow.setValue(0);
      return;
    }
    highlightGlow.setValue(0);
    cardScale.setValue(0.95);
    const timeout = setTimeout(
      () => runHighlightAnimation(cardScale, highlightGlow),
      200
    );
    return () => clearTimeout(timeout);
  }, [cardScale, highlightGlow, isJustCreated, reduceMotionPreference]);
}

function useIconPulse(
  isWeekComplete: boolean,
  reduceMotionPreference: boolean,
  iconPulse: Animated.Value
) {
  useEffect(() => {
    if (isWeekComplete && !reduceMotionPreference) {
      runIconPulseLoop(iconPulse);
    } else {
      iconPulse.setValue(1);
    }
  }, [isWeekComplete, iconPulse, reduceMotionPreference]);
}

function useNewRecordAnimation(
  isNewPersonalRecord: boolean,
  reduceMotionPreference: boolean,
  triggerSuccess: () => void,
  newRecordScale: Animated.Value,
  newRecordOpacity: Animated.Value,
  cardScale: Animated.Value,
  setShowNewRecord: (show: boolean) => void
) {
  useEffect(() => {
    if (!isNewPersonalRecord || reduceMotionPreference) return;
    setShowNewRecord(true);
    triggerSuccess();
    runNewRecordAnimation(newRecordScale, newRecordOpacity, cardScale);
    const timeout = setTimeout(() => {
      hideNewRecordBadge(newRecordScale, newRecordOpacity, setShowNewRecord);
    }, 3000);
    return () => clearTimeout(timeout);
  }, [isNewPersonalRecord, reduceMotionPreference, triggerSuccess]);
}

import { Animated, Easing } from 'react-native';
import * as Haptics from 'expo-haptics';
import type { Habit } from './types';

interface PressHandlersParams {
  cardScale: Animated.Value;
  archiveFlash: Animated.Value;
  habit: Habit;
  onArchive?: (habitId: string) => void;
  onLongPress?: ((habit?: Habit) => void) | (() => void);
  triggerSelection: () => void;
}

export function usePressHandlers({
  cardScale,
  archiveFlash,
  habit,
  onArchive,
  onLongPress,
  triggerSelection,
}: PressHandlersParams) {
  const handleLongPress = () => {
    if (!onLongPress) return;
    triggerSelection();
    onLongPress(habit);
  };

  const handlePressIn = () => {
    Animated.spring(cardScale, {
      damping: 12,
      stiffness: 200,
      toValue: 0.97,
      useNativeDriver: true,
    }).start();
  };

  const handlePressOut = () => {
    Animated.spring(cardScale, {
      damping: 10,
      stiffness: 180,
      toValue: 1,
      useNativeDriver: true,
    }).start();
  };

  const handleSwipeableOpen = () => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);

    Animated.sequence([
      Animated.timing(archiveFlash, {
        duration: 120,
        easing: Easing.out(Easing.ease),
        toValue: 1,
        useNativeDriver: true,
      }),
      Animated.timing(archiveFlash, {
        duration: 220,
        easing: Easing.out(Easing.ease),
        toValue: 0,
        useNativeDriver: true,
      }),
    ]).start();

    if (onArchive) {
      onArchive(habit._id);
    }
  };

  return {
    handleLongPress,
    handlePressIn,
    handlePressOut,
    handleSwipeableOpen,
  };
}

import { useRef, useEffect } from 'react';
import {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withSequence,
  withTiming,
  withDelay,
  Easing as ReanimatedEasing,
} from 'react-native-reanimated';

import { getStrengthLabel } from './strengthUtils';

export function useStrengthAnimation(
  strengthPercent: number,
  reduceMotionPreference: boolean
) {
  const strengthEmojiScale = useSharedValue(1);
  const strengthEmojiOpacity = useSharedValue(1);
  const strengthEmojiRotation = useSharedValue(0);
  const previousStrengthLevelRef = useRef(getStrengthLabel(strengthPercent));

  useEffect(() => {
    const currentLabel = getStrengthLabel(strengthPercent);
    const levelChanged = previousStrengthLevelRef.current !== currentLabel;
    previousStrengthLevelRef.current = currentLabel;

    if (reduceMotionPreference) return;

    if (levelChanged) {
      runLevelUpAnimation(
        strengthEmojiOpacity,
        strengthEmojiScale,
        strengthEmojiRotation
      );
    } else {
      runSubtlePulse(strengthEmojiScale);
    }
  }, [strengthPercent, reduceMotionPreference]);

  const strengthEmojiAnimatedStyle = useAnimatedStyle(() => ({
    opacity: strengthEmojiOpacity.value,
    transform: [
      { scale: strengthEmojiScale.value },
      { rotate: `${Math.round(strengthEmojiRotation.value)}deg` },
    ],
  }));

  return { strengthEmojiAnimatedStyle };
}

function runLevelUpAnimation(
  opacity: { value: number },
  scale: { value: number },
  rotation: { value: number }
) {
  opacity.value = withTiming(0.3, {
    duration: 150,
    easing: ReanimatedEasing.out(ReanimatedEasing.ease),
  });
  scale.value = withTiming(0.6, {
    duration: 150,
    easing: ReanimatedEasing.out(ReanimatedEasing.ease),
  });
  rotation.value = withSequence(
    withTiming(-8, {
      duration: 80,
      easing: ReanimatedEasing.inOut(ReanimatedEasing.ease),
    }),
    withTiming(8, {
      duration: 80,
      easing: ReanimatedEasing.inOut(ReanimatedEasing.ease),
    }),
    withTiming(0, {
      duration: 60,
      easing: ReanimatedEasing.out(ReanimatedEasing.ease),
    })
  );
  opacity.value = withDelay(
    150,
    withTiming(1, {
      duration: 200,
      easing: ReanimatedEasing.out(ReanimatedEasing.ease),
    })
  );
  scale.value = withDelay(
    150,
    withSequence(
      withSpring(1.4, { damping: 6, stiffness: 120 }),
      withSpring(1, { damping: 10, stiffness: 180 })
    )
  );
}

function runSubtlePulse(scale: { value: number }) {
  scale.value = withSequence(
    withTiming(1.08, {
      duration: 100,
      easing: ReanimatedEasing.out(ReanimatedEasing.ease),
    }),
    withSpring(1, { damping: 15, stiffness: 200 })
  );
}

import { memo } from 'react';
