import { memo, useCallback, useMemo } from 'react';
import { FlatList, Text, View } from 'react-native';
import { Search } from 'lucide-react-native';
import { EmojiItem } from './EmojiItem';
import { EMOJIS_PER_ROW } from '../EmojiPicker.constants';

interface EmojiGridProps {
  displayedEmojis: string[];
  selectedEmoji?: string | null;
  categoryName: string;
  isSearching: boolean;
  onEmojiSelect: (emoji: string) => void;
}

export const EmojiGrid = memo(
  ({
    displayedEmojis,
    selectedEmoji,
    categoryName,
    isSearching,
    onEmojiSelect,
  }: EmojiGridProps) => {
    const emojiRows = useMemo(() => {
      const rows: string[][] = [];
      for (let i = 0; i < displayedEmojis.length; i += EMOJIS_PER_ROW) {
        rows.push(displayedEmojis.slice(i, i + EMOJIS_PER_ROW));
      }
      return rows;
    }, [displayedEmojis]);

    const renderEmojiItem = useCallback(
      ({ item }: { item: string[] }) => (
        <View style={{ flexDirection: 'row' }}>
          {item.map((emoji) => (
            <EmojiItem
              key={emoji}
              emoji={emoji}
              isSelected={selectedEmoji === emoji}
              onPress={() => onEmojiSelect(emoji)}
            />
          ))}
        </View>
      ),
      [selectedEmoji, onEmojiSelect]
    );

    if (displayedEmojis.length === 0) {
      return (
        <View className='flex-1 items-center justify-center bg-white'>
          <Search color='#78716c' size={48} />
          <Text className='mt-3 text-base font-medium text-stone-800'>
            No emojis found
          </Text>
          <Text className='mt-1 text-sm text-stone-500'>
            Try a different search term
          </Text>
        </View>
      );
    }

    return (
      <View className='flex-1 bg-white'>
        {!isSearching && (
          <View className='px-4 pb-2 pt-3'>
            <Text className='text-xs font-semibold uppercase tracking-wider text-stone-500'>
              {categoryName}
            </Text>
          </View>
        )}
        <FlatList
          removeClippedSubviews
          showsVerticalScrollIndicator
          contentContainerStyle={{
            paddingBottom: 16,
            paddingHorizontal: 8,
          }}
          data={emojiRows}
          initialNumToRender={10}
          keyExtractor={(_, index) => `row-${index}`}
          maxToRenderPerBatch={10}
          renderItem={renderEmojiItem}
          windowSize={5}
        />
      </View>
    );
  }
);

EmojiGrid.displayName = 'EmojiGrid';

import { memo, useCallback, useRef } from 'react';
import { Animated, Pressable, Text } from 'react-native';
import { EMOJIS_PER_ROW } from '../EmojiPicker.constants';
import type { EmojiItemProps } from '../EmojiPicker.types';

export const EmojiItem = memo(
  ({ emoji, isSelected, onPress }: EmojiItemProps) => {
    const scaleAnim = useRef(new Animated.Value(1)).current;

    const handlePressIn = useCallback(() => {
      Animated.spring(scaleAnim, {
        bounciness: 4,
        speed: 50,
        toValue: 0.9,
        useNativeDriver: true,
      }).start();
    }, [scaleAnim]);

    const handlePressOut = useCallback(() => {
      Animated.spring(scaleAnim, {
        bounciness: 4,
        speed: 50,
        toValue: isSelected ? 1.1 : 1,
        useNativeDriver: true,
      }).start();
    }, [scaleAnim, isSelected]);

    return (
      <Pressable
        accessibilityLabel={`Select ${emoji} emoji`}
        accessibilityRole='button'
        style={{
          aspectRatio: 1,
          padding: 2,
          width: `${100 / EMOJIS_PER_ROW}%`,
        }}
        onPress={onPress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
      >
        <Animated.View
          style={[
            {
              alignItems: 'center',
              backgroundColor: isSelected ? '#f5f5f4' : '#fafaf9',
              borderColor: isSelected ? '#10b981' : 'transparent',
              borderRadius: 12,
              borderWidth: isSelected ? 2 : 0,
              flex: 1,
              justifyContent: 'center',
              minHeight: 44,
              minWidth: 44,
            },
            {
              transform: [{ scale: scaleAnim }],
            },
          ]}
        >
          <Text style={{ fontSize: 28 }}>{emoji}</Text>
        </Animated.View>
      </Pressable>
    );
  }
);

EmojiItem.displayName = 'EmojiItem';

import { memo, useCallback, useRef } from 'react';
import { Animated, Pressable, Text } from 'react-native';
import type { QuickAccessEmojiItemProps } from '../EmojiPicker.types';

export const QuickAccessEmojiItem = memo(
  ({
    emoji,
    isSelected,
    onPress,
    accessibilityLabelSuffix = '',
  }: QuickAccessEmojiItemProps) => {
    const scaleAnim = useRef(new Animated.Value(isSelected ? 1.1 : 1)).current;

    const handlePressIn = useCallback(() => {
      Animated.spring(scaleAnim, {
        bounciness: 4,
        speed: 50,
        toValue: 0.9,
        useNativeDriver: true,
      }).start();
    }, [scaleAnim]);

    const handlePressOut = useCallback(() => {
      Animated.spring(scaleAnim, {
        bounciness: 4,
        speed: 50,
        toValue: isSelected ? 1.1 : 1,
        useNativeDriver: true,
      }).start();
    }, [scaleAnim, isSelected]);

    const accessibilityLabel = accessibilityLabelSuffix
      ? `Select ${emoji} emoji ${accessibilityLabelSuffix}`
      : `Select ${emoji} emoji`;

    return (
