/**
 * FloatingXPText Component
 *
 * Displays "+X XP" text that floats up and fades out
 * Used when user completes a habit or earns bonus XP
 *
 * Based on Part B: Micro-Transitions Strategy
 * Duration: 800ms
 * Movement: Floats up 40px
 * Opacity: 1 → 0
 */

import React, { useEffect } from 'react';
import { StyleSheet } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  Easing,
  runOnJS,
} from 'react-native-reanimated';
import { LinearGradient } from 'expo-linear-gradient';

export interface FloatingXPTextProps {
  /** XP value to display (e.g., 10, 50, 100) */
  value: number;

  /** Position where animation starts */
  startPosition: { x: number; y: number };

  /** Callback when animation completes */
  onComplete?: () => void;

  /** Show coin icon instead of XP */
  showCoin?: boolean;
}

export function FloatingXPText({
  value,
  startPosition,
  onComplete,
  showCoin = false,
}: FloatingXPTextProps) {
  const translateY = useSharedValue(0);
  const opacity = useSharedValue(1);

  useEffect(() => {
    // Animate upward movement
    translateY.value = withTiming(-40, {
      duration: 800,
      easing: Easing.out(Easing.cubic),
    });

    // Animate fade out
    opacity.value = withTiming(
      0,
      {
        duration: 800,
        easing: Easing.in(Easing.cubic),
      },
      (finished) => {
        if (finished && onComplete) {
          runOnJS(onComplete)();
        }
      }
    );
  }, []);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ translateY: translateY.value }],
    opacity: opacity.value,
  }));

  return (
    <Animated.View
      style={[
        styles.container,
        {
          position: 'absolute',
          left: startPosition.x,
          top: startPosition.y,
        },
        animatedStyle,
      ]}
      pointerEvents="none"
    >
      {showCoin ? (
        // Coin variant (gold color)
        <Animated.Text style={styles.coinText}>
          +{value} 🪙
        </Animated.Text>
      ) : (
        // XP variant (green gradient - simulate with shadow for now)
        <Animated.Text style={styles.xpText}>
          +{value} XP
        </Animated.Text>
      )}
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    justifyContent: 'center',
    zIndex: 1000,
  },
  xpText: {
    fontSize: 18,
    fontWeight: 'bold',
    color: '#10B981', // Green 500
    textShadowColor: '#10B981',
    textShadowOffset: { width: 0, height: 0 },
    textShadowRadius: 8,
  },
  coinText: {
    fontSize: 18,
    fontWeight: 'bold',
    color: '#F59E0B', // Amber 500
    textShadowColor: '#F59E0B',
    textShadowOffset: { width: 0, height: 0 },
    textShadowRadius: 8,
  },
});

export default FloatingXPText;

/**
 * Manual button to force habit strength update
 * This bypasses any toggle issues and directly updates strength
 */

import React, { useState } from 'react';
import { Pressable, Text, View, ActivityIndicator } from 'react-native';
import { useMutation } from 'convex/react';
import { api } from '../../convex/_generated/api';
import type { Id } from '../../convex/_generated/dataModel';

interface ForceUpdateButtonProps {
  habitId: Id<'habits'>;
  habitName: string;
  currentStrength: number;
}

type UpdateStrengthResponse = {
  baseline: number;
  compliance: number;
  daysSinceCreation: number;
  newStrength: number;
  predictionProbability: number;
  previousStrength: number;
  strengthLevel: string;
};

const assertUpdateStrengthResponse: (
  response: unknown
) => asserts response is UpdateStrengthResponse = (response: unknown) => {
  if (!response || typeof response !== 'object') {
    throw new Error('Unexpected empty response from updateHabitStrength');
  }

  const candidate = response as Partial<UpdateStrengthResponse>;
  if (
    typeof candidate.previousStrength !== 'number' ||
    typeof candidate.newStrength !== 'number'
  ) {
    throw new TypeError('updateHabitStrength returned unexpected payload');
  }
};

export function ForceUpdateButton({
  habitId,
  habitName: _habitName,
  currentStrength,
}: ForceUpdateButtonProps) {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);
  const updateStrength = useMutation(api.habitStrength.updateHabitStrength);

  const handleClick = async () => {
    setLoading(true);
    setResult(null);

    try {
      const today = new Date().toISOString().split('T')[0];
      const response = await updateStrength({
        behaviorPerformed: true,
        date: today,
        habitId,
      });

      assertUpdateStrengthResponse(response);
      setResult(
        `✅ ${response.previousStrength.toFixed(3)} → ${response.newStrength.toFixed(3)}`
      );
      console.log('Force update result:', response);
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      setResult(`❌ Error: ${errorMessage}`);
      console.error('Force update error:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <View className='mt-2 gap-2'>
      <Pressable
        className={`rounded-lg px-4 py-2 ${
          loading ? 'bg-stone-400' : 'bg-green-600'
        }`}
        disabled={loading}
        onPress={handleClick}
      >
        {loading ? (
          <View className='flex-row items-center justify-center gap-2'>
            <ActivityIndicator color='white' size='small' />
            <Text className='font-semibold text-white'>Updating...</Text>
          </View>
        ) : (
          <Text className='text-center font-semibold text-white'>
            🚀 Force Update Strength +15%
          </Text>
        )}
      </Pressable>

      {result && (
        <View
          className={`rounded-lg p-2 ${
            result.startsWith('✅') ? 'bg-green-100' : 'bg-red-100'
          }`}
        >
          <Text
            className={`text-xs ${
              result.startsWith('✅') ? 'text-green-800' : 'text-red-800'
            }`}
          >
            {result}
          </Text>
        </View>
      )}

      <Text className='text-xs text-stone-500'>
        Current: {(currentStrength * 100).toFixed(1)}%
      </Text>
    </View>
  );
}

/**
 * FullsizeTemplatePreview - Main orchestration component
 * A fullsize preview modal for template cards
 */

import React from 'react';
import { View, ScrollView } from 'react-native';
import Animated from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Modal from '../Modal';
import { useReduceMotion } from '../../hooks/useReduceMotion';
import {
  HeroSection,
  DescriptionSection,
  ScienceBox,
  TipsBox,
  FooterSection,
  ModalHeader,
  ConfettiOverlay,
} from './components';
import {
  useEntranceAnimations,
  useSuccessAnimations,
  useButtonAnimations,
  useAnimatedStyles,
  useHandlers,
} from './hooks';
import { layoutStyles } from './styles';
import { DEFAULT_ICON_COLOR } from './FullsizeTemplatePreview.constants';
import type { FullsizeTemplatePreviewProps } from './FullsizeTemplatePreview.types';

export default function FullsizeTemplatePreview({
  template,
  visible,
  onClose,
  onImport,
  onCustomize,
  isImporting = false,
  isImported = false,
}: FullsizeTemplatePreviewProps) {
  const insets = useSafeAreaInsets();
  const reducedMotion = useReduceMotion();
  const iconColor = template?.iconColor?.trim() || DEFAULT_ICON_COLOR;
  const entranceAnimations = useEntranceAnimations({
    reducedMotion,
    template,
    visible,
  });
  const successAnimations = useSuccessAnimations({ isImported, reducedMotion });
  const {
    closeButtonScale,
    importButtonScale,
    customizeButtonScale,
    createPressHandlers,
  } = useButtonAnimations({ reducedMotion });
  const handlers = useHandlers({
    isImported,
    isImporting,
    onClose,
    onCustomize,
    onImport,
    reducedMotion,
    template,
  });
  const animatedStyles = useAnimatedStyles({
    ...entranceAnimations,
    closeButtonScale,
    customizeButtonScale,
    importButtonScale,
    ...successAnimations,
  });

  if (!template) return null;
  const tips = (template as any).tips;

  return (
    <Modal
      disableBackdropClose={isImporting}
      variant='fullScreen'
      visible={visible}
      onClose={handlers.handleClose}
    >
      <Animated.View
        style={[layoutStyles.container, animatedStyles.contentStyle]}
      >
        <Animated.View
          pointerEvents='none'
          style={[
            layoutStyles.successGlowOverlay,
            { backgroundColor: '#22c55e' },
            animatedStyles.successGlowStyle,
          ]}
        />
        <ModalHeader
          closeButtonAnimatedOpacityStyle={
            animatedStyles.closeButtonAnimatedOpacityStyle
          }
          closeButtonPressHandlers={createPressHandlers(closeButtonScale, 0.9)}
          closeButtonStyle={animatedStyles.closeButtonStyle}
          topInset={insets.top}
          onClose={handlers.handleClose}
        />
        <ScrollView
          bounces
          contentContainerStyle={layoutStyles.contentContainer}
          showsVerticalScrollIndicator={false}
        >
          <HeroSection
            iconAnimatedStyle={animatedStyles.iconAnimatedStyle}
            iconColor={iconColor}
            iconGlowStyle={animatedStyles.iconGlowStyle}
            template={template}
          />
          <DescriptionSection description={template.description} />
          <ScienceBox
            template={template}
            onResearchPress={handlers.handleResearchPress}
          />
          {tips && Array.isArray(tips) && tips.length > 0 && (
            <TipsBox iconColor={iconColor} tips={tips} />
          )}
          <View style={layoutStyles.bottomSpacer} />
        </ScrollView>
        <FooterSection
          bottomInset={insets.bottom}
          checkmarkAnimatedStyle={animatedStyles.checkmarkAnimatedStyle}
          createPressHandlers={createPressHandlers}
          customizeButtonScale={customizeButtonScale}
          customizeButtonStyle={animatedStyles.customizeButtonStyle}
          iconColor={iconColor}
          importButtonScale={importButtonScale}
          importButtonStyle={animatedStyles.importButtonStyle}
          isImported={isImported}
          isImporting={isImporting}
          successButtonGlowStyle={animatedStyles.successButtonGlowStyle}
          successIconBounceStyle={animatedStyles.successIconBounceStyle}
          templateName={template.name}
          onCustomize={handlers.handleCustomize}
          onImport={handlers.handleImport}
        />
        <ConfettiOverlay
          ref={successAnimations.confettiRef}
          visible={isImported && !reducedMotion}
        />
      </Animated.View>
    </Modal>
  );
}

