    closeButtonStyle,
    contentStyle,
    customizeButtonStyle,
    iconAnimatedStyle,
    iconGlowStyle,
    importButtonStyle,
    successButtonGlowStyle,
    successGlowStyle,
    successIconBounceStyle,
