/**
 * Entrance animation logic for FullsizeTemplatePreview
 */

import { useEffect } from 'react';
import {
  useSharedValue,
  withSpring,
  withDelay,
  withTiming,
  Easing,
} from 'react-native-reanimated';
import { Springs } from '../../../constants/motion';
import type { Doc } from '../../../../convex/_generated/dataModel';

interface UseEntranceAnimationsProps {
  visible: boolean;
  template: Doc<'templates'> | null;
  reducedMotion: boolean;
}

export const useEntranceAnimations = ({
  visible,
  template,
  reducedMotion,
}: UseEntranceAnimationsProps) => {
  const backdropOpacity = useSharedValue(0);
  const contentTranslateY = useSharedValue(100);
  const contentOpacity = useSharedValue(0);
  const iconScale = useSharedValue(0.8);
  const iconGlowScale = useSharedValue(1);
  const iconGlowOpacity = useSharedValue(0.25);
  const closeButtonOpacity = useSharedValue(1);

  useEffect(() => {
    if (visible && template) {
      backdropOpacity.value = 0;
      contentTranslateY.value = 100;
      contentOpacity.value = 0;
      iconScale.value = 0.8;
      closeButtonOpacity.value = 0;

      if (reducedMotion) {
        backdropOpacity.value = 0.5;
        contentTranslateY.value = 0;
        contentOpacity.value = 1;
        iconScale.value = 1;
        closeButtonOpacity.value = 1;
      } else {
        backdropOpacity.value = withTiming(0.5, {
          duration: 350,
          easing: Easing.out(Easing.cubic),
        });
        contentTranslateY.value = withSpring(0, Springs.gentle);
        contentOpacity.value = withTiming(1, {
          duration: 400,
          easing: Easing.out(Easing.cubic),
        });
        closeButtonOpacity.value = withDelay(
          200,
          withTiming(1, { duration: 300, easing: Easing.out(Easing.cubic) })
        );
        iconScale.value = withDelay(250, withSpring(1, Springs.micro));
        iconGlowScale.value = withDelay(400, withSpring(1.12, Springs.pulse));
      }
    }
  }, [visible, template, reducedMotion]);

  return {
    backdropOpacity,
    closeButtonOpacity,
    contentOpacity,
    contentTranslateY,
    iconGlowOpacity,
    iconGlowScale,
    iconScale,
  };
};

/**
 * Event handlers for FullsizeTemplatePreview
 */

import { useCallback } from 'react';
import { Linking } from 'react-native';
import * as Haptics from 'expo-haptics';
import type { Doc, Id } from '../../../../convex/_generated/dataModel';

interface UseHandlersProps {
  template: Doc<'templates'> | null;
  isImporting: boolean;
  isImported: boolean;
  reducedMotion: boolean;
  onClose: () => void;
  onImport: (templateId: Id<'templates'>) => void;
  onCustomize: (template: Doc<'templates'>) => void;
}

export const useHandlers = ({
  template,
  isImporting,
  isImported,
  reducedMotion,
  onClose,
  onImport,
  onCustomize,
}: UseHandlersProps) => {
  const handleClose = useCallback(() => {
    if (!reducedMotion) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    }
    onClose();
  }, [onClose, reducedMotion]);

  const handleImport = useCallback(() => {
    if (!template || isImporting || isImported) return;
    if (!reducedMotion) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    }
    onImport(template._id);
  }, [template, isImporting, isImported, onImport, reducedMotion]);

  const handleCustomize = useCallback(() => {
    if (!template) return;
    if (!reducedMotion) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    }
    onCustomize(template);
  }, [template, onCustomize, reducedMotion]);

  const handleResearchPress = useCallback(async () => {
    if (!template?.scientificLink) return;
    if (!reducedMotion) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    }
    const canOpen = await Linking.canOpenURL(template.scientificLink);
    if (canOpen) {
      await Linking.openURL(template.scientificLink);
    }
  }, [template?.scientificLink, reducedMotion]);

  return {
    handleClose,
    handleCustomize,
    handleImport,
    handleResearchPress,
  };
};

/**
 * Success state animation logic for FullsizeTemplatePreview
 */

import { useEffect, useCallback, useRef } from 'react';
import {
  useSharedValue,
  withSpring,
  withDelay,
  withSequence,
  withTiming,
  Easing,
} from 'react-native-reanimated';
import * as Haptics from 'expo-haptics';
import ConfettiCannon from 'react-native-confetti-cannon';

interface UseSuccessAnimationsProps {
  isImported: boolean;
  reducedMotion: boolean;
}

export const useSuccessAnimations = ({
  isImported,
  reducedMotion,
}: UseSuccessAnimationsProps) => {
  const confettiRef = useRef<ConfettiCannon>(null);
  const successGlow = useSharedValue(0);
  const successGlowScale = useSharedValue(1);
  const checkmarkScale = useSharedValue(0);
  const checkmarkRotation = useSharedValue(-30);
  const successButtonGlow = useSharedValue(0);
  const successIconBounce = useSharedValue(0);

  const triggerSuccessHaptic = useCallback(() => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
  }, []);

  const triggerConfetti = useCallback(() => {
    if (confettiRef.current && !reducedMotion) confettiRef.current.start();
  }, [reducedMotion]);

  useEffect(() => {
    if (isImported) {
      if (reducedMotion) {
        checkmarkScale.value = 1;
        checkmarkRotation.value = 0;
        successGlow.value = 0.4;
        successGlowScale.value = 1;
        successButtonGlow.value = 0;
        successIconBounce.value = 0;
      } else {
        triggerSuccessHaptic();
        triggerConfetti();
        successGlow.value = withSequence(
          withTiming(0.5, { duration: 150, easing: Easing.out(Easing.ease) }),
          withTiming(0.2, { duration: 300, easing: Easing.inOut(Easing.ease) }),
          withTiming(0, { duration: 500, easing: Easing.out(Easing.ease) })
        );
        successGlowScale.value = withSequence(
          withTiming(1.3, { duration: 200, easing: Easing.out(Easing.ease) }),
          withTiming(1, { duration: 400, easing: Easing.inOut(Easing.ease) })
        );
        checkmarkScale.value = withDelay(
          100,
          withSpring(1, { damping: 6, mass: 1, stiffness: 180 })
        );
        checkmarkRotation.value = withDelay(
          100,
          withSpring(0, { damping: 10, stiffness: 150 })
        );
        successButtonGlow.value = withDelay(
          200,
          withSequence(
            withTiming(1, { duration: 200 }),
            withTiming(0.3, { duration: 300 }),
            withTiming(0.8, { duration: 200 }),
            withTiming(0.4, { duration: 400 })
          )
        );
        successIconBounce.value = withDelay(
          300,
          withSequence(
            withSpring(-3, { damping: 8, stiffness: 300 }),
            withSpring(0, { damping: 12, stiffness: 200 })
          )
        );
      }
    } else {
      checkmarkScale.value = 0;
      checkmarkRotation.value = -30;
      successGlow.value = 0;
      successGlowScale.value = 1;
      successButtonGlow.value = 0;
      successIconBounce.value = 0;
    }
  }, [isImported, reducedMotion, triggerSuccessHaptic, triggerConfetti]);

  return {
    checkmarkRotation,
    checkmarkScale,
    confettiRef,
    successButtonGlow,
    successGlow,
    successGlowScale,
    successIconBounce,
  };
};

