import { useState } from 'react';
import { format, parseISO } from 'date-fns';
import {
  AlertTriangle,
  ChevronLeft,
  Flame,
  MoreVertical,
} from 'lucide-react-native';
import {
  Modal,
  View,
  Pressable,
  ScrollView,
  Text,
  TouchableOpacity,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import type { Id } from '../../convex/_generated/dataModel';
import { getEmojiAndName } from './DraggableHabit/DraggableHabit.hooks';
import { StatsCard } from './HabitCalendarModal/StatsCard';
import { ActivityLog } from './HabitCalendarModal/ActivityLog';
import { CalendarTabs } from './HabitCalendarModal/CalendarTabs';
import HeatmapCalendar from './HabitCalendarModal/HeatmapCalendar';
import HabitCalendarView from './HabitCalendarView';
import {
  calculateBestStreak,
  calculateCompletionPercentage,
} from '../utils/habitCalculations';
import HabitEditScreen from '../screens/HabitEditScreen';

type CalendarView = 'month' | 'year';

interface Habit {
  _id: Id<'habits'>;
  name: string;
  notes?: string;
  strength?: number;
  frequency?: string;
  reminderTime?: string;
  preferredTime?: string;
  [key: string]: any;
}

interface HabitCalendarModalProps {
  visible: boolean;
  onClose: () => void;
  habit: Habit | null;
  streak: number;
  tracking: Array<{
    _creationTime: number;
    habitId: Id<'habits'>;
    date: string;
    completed: boolean;
  }>;
  toggleHabit: (args: { habitId: Id<'habits'>; date: string }) => void;
  /** Optional callback to navigate to HabitDetail's Motivation tab for advanced features */
  onOpenMotivationTab?: () => void;
}

export default function HabitCalendarModal({
  visible,
  onClose,
  habit,
  streak,
  tracking,
  toggleHabit,
  onOpenMotivationTab,
}: HabitCalendarModalProps) {
  const [showEditScreen, setShowEditScreen] = useState(false);
  const [calendarView, setCalendarView] = useState<CalendarView>('month');

  if (!habit) return null;

  const { emoji, name } = getEmojiAndName(habit.name);
  const scheduleLabel = buildScheduleLabel(habit);
  const todayDateString = format(new Date(), 'yyyy-MM-dd');
  const habitTrackingEntries = tracking.filter((t) => t.habitId === habit._id);
  const habitTracking = habitTrackingEntries.map((t) => ({
    completed: t.completed,
    date: t.date,
  }));
  const todayTracking = habitTrackingEntries.find(
    (t) => t.date === todayDateString
  );
  const isTodayCompleted = Boolean(todayTracking?.completed);
  const recentMissBadge = getLatestMissedBadge(
    habitTrackingEntries,
    todayDateString
  );
  const markTodayLabel = isTodayCompleted ? 'Completed today' : 'Mark Today Done';

  const handleEditPress = () => {
    setShowEditScreen(true);
  };

  const handleCloseEdit = () => {
    setShowEditScreen(false);
  };

  const bestStreak = calculateBestStreak(habitTracking);
  const completionPercentage = calculateCompletionPercentage(
    habit.createdAt || Date.now(),
    habitTracking
  );

  // Filter tracking for activity log
  const activityTracking = habitTrackingEntries;

  const handleQuickLogPress = () => {
    if (isTodayCompleted) return;
    toggleHabit({ habitId: habit._id, date: todayDateString });
  };

  // Handler for navigating to advanced features (Cue, Affirmations, Vision Board)
  // This closes the edit screen, closes this modal, and opens HabitDetail's Motivation tab
  const handleOpenAdvancedFeatures = () => {
    setShowEditScreen(false);
    onClose();
    onOpenMotivationTab?.();
  };

  return (
    <Modal animationType='slide' visible={visible} onRequestClose={onClose}>
      <SafeAreaView className='flex-1 bg-[#F8F5F1]'>
        {/* Navigation Header */}
        <View className='flex-row items-center justify-between px-4 pb-4 pt-2'>
          <Pressable
            accessibilityHint='Return to the previous screen'
            accessibilityRole='button'
            className='h-10 w-10 items-center justify-center rounded-full active:bg-stone-200'
            onPress={onClose}
          >
            <ChevronLeft color='#1c1917' size={24} />
          </Pressable>
          <Text className='text-xl font-bold text-stone-900'>{name}</Text>
          <Pressable
            accessibilityLabel='Habit options'
            accessibilityRole='button'
            className='h-10 w-10 items-center justify-center rounded-full active:bg-stone-200'
            onPress={handleEditPress}
          >
            <MoreVertical color='#1c1917' size={20} />
          </Pressable>
        </View>

        <ScrollView className='px-4' showsVerticalScrollIndicator={false}>
          {/* Status Ribbon */}
          <View className='mt-2'>
            <View
              className='rounded-3xl bg-white p-5'
              style={{
                shadowColor: '#1c1917',
                shadowOffset: { width: 0, height: 12 },
                shadowOpacity: 0.08,
                shadowRadius: 24,
              }}
            >
              <View className='flex-row gap-4'>
                <View className='items-center'>
                  <View className='h-16 w-16 items-center justify-center rounded-2xl bg-blue-50'>
                    <Text className='text-4xl'>{emoji}</Text>
                  </View>
                </View>

                <View className='flex-1'>
                  <View className='flex-row items-start justify-between'>
                    <View className='flex-1 pr-4'>
                      <Text className='text-xl font-semibold text-stone-900'>
                        {name}
                      </Text>
                      {scheduleLabel ? (
                        <Text className='mt-1 text-sm text-stone-500'>
                          {scheduleLabel}
                        </Text>
                      ) : null}
                      {habit.notes ? (
                        <Text
                          className='mt-2 text-sm text-stone-500'
                          numberOfLines={2}
                        >
                          {habit.notes}
                        </Text>
                      ) : null}
                    </View>

                    <View className='items-end'>
                      <View className='flex-row items-center rounded-full bg-orange-50 px-3 py-1'>
                        <Flame color='#ea580c' size={16} />
                        <Text className='ml-1 text-xs font-semibold text-orange-700'>
                          Current streak
                        </Text>
                      </View>
                      <Text className='mt-2 text-lg font-semibold text-stone-900'>
                        {streak} days
                      </Text>
                      <Text className='text-xs text-stone-400'>
                        Best {bestStreak} {bestStreak === 1 ? 'day' : 'days'}
                      </Text>
                    </View>
                  </View>

                  {recentMissBadge ? (
                    <View className='mt-3 flex-row items-center gap-1.5 rounded-full bg-amber-50 px-3 py-1'>
                      <AlertTriangle color='#b45309' size={14} />
                      <Text className='text-xs font-medium text-amber-700'>
                        {recentMissBadge} · Tap to review
                      </Text>
                    </View>
                  ) : null}

                  <View className='mt-4 flex-row gap-3'>
                    <TouchableOpacity
                      accessibilityLabel={
                        isTodayCompleted
                          ? 'Today already completed'
                          : 'Mark this habit as done today'
                      }
                      accessibilityRole='button'
                      className={`flex-1 rounded-2xl px-4 py-3 ${
                        isTodayCompleted ? 'bg-stone-200' : 'bg-blue-500'
                      }`}
                      disabled={isTodayCompleted}
                      onPress={handleQuickLogPress}
                    >
                      <Text
                        className={`text-center text-base font-semibold ${
                          isTodayCompleted ? 'text-stone-600' : 'text-white'
                        }`}
                      >
                        {markTodayLabel}
                      </Text>
                    </TouchableOpacity>

                    <Pressable
                      accessibilityLabel='Edit habit'
                      accessibilityRole='button'
                      className='w-[110px] items-center justify-center rounded-2xl border border-stone-200 px-3'
                      onPress={handleEditPress}
                    >
                      <Text className='text-sm font-semibold text-stone-700'>
                        Edit habit
                      </Text>
                    </Pressable>
                  </View>
                </View>
              </View>
            </View>
          </View>

          {/* Stats Card */}
          <View className='mt-5'>
            <StatsCard
              bestStreak={bestStreak}
              completionPercentage={completionPercentage}
              currentStreak={streak}
              emoji={emoji}
              habitName={habit.name}
              habitNotes={habit.notes}
              showHeader={false}
            />
          </View>

          {/* Calendar Tabs - Switch between Month and Year view */}
          <View className='mt-8'>
            <CalendarTabs
              activeView={calendarView}
              onViewChange={setCalendarView}
            />

            {/* Conditional Calendar Rendering */}
            {calendarView === 'month' ? (
              <HabitCalendarView
                habitId={habit._id}
                toggleHabit={toggleHabit}
                tracking={tracking}
              />
            ) : (
              <HeatmapCalendar
                habitId={habit._id}
                monthsToShow={6}
                tracking={tracking}
              />
            )}
          </View>

          {/* Activity Log - Matches Figma styling */}
          <View className='mt-8 pb-6'>
            <ActivityLog tracking={activityTracking} />
          </View>
        </ScrollView>
      </SafeAreaView>

      {/* Habit Edit Screen */}
      <HabitEditScreen
        habitId={habit._id}
        visible={showEditScreen}
        onClose={handleCloseEdit}
        onOpenCueEditor={onOpenMotivationTab ? handleOpenAdvancedFeatures : undefined}
        onOpenAffirmationsEditor={onOpenMotivationTab ? handleOpenAdvancedFeatures : undefined}
        onOpenVisionBoard={onOpenMotivationTab ? handleOpenAdvancedFeatures : undefined}
      />
    </Modal>
  );
}

const FREQUENCY_LABELS: Record<string, string> = {
  daily: 'Daily',
  weekly: 'Weekly',
  custom: 'Custom',
};

function buildScheduleLabel(habit: Habit) {
  const { frequency, reminderTime, preferredTime } = habit;
  const formattedFrequency = frequency
    ? FREQUENCY_LABELS[frequency] ||
      frequency
        .split('_')
        .map((segment) => segment.charAt(0).toUpperCase() + segment.slice(1))
        .join(' ')
    : undefined;
  const formattedTime = reminderTime
    ? reminderTime
    : preferredTime
    ? preferredTime.charAt(0).toUpperCase() + preferredTime.slice(1)
    : undefined;

  if (formattedFrequency && formattedTime) {
    return `${formattedFrequency} · ${formattedTime}`;
  }

  return formattedFrequency || formattedTime;
}

type TrackingEntry = HabitCalendarModalProps['tracking'][number];

function getLatestMissedBadge(
  trackingEntries: TrackingEntry[],
  todayDate: string
) {
  const previousMiss = trackingEntries
    .filter((entry) => !entry.completed && entry.date < todayDate)
    .sort((a, b) => (a.date < b.date ? 1 : -1))[0];

  if (!previousMiss) {
    return null;
  }

  return `Missed ${format(parseISO(previousMiss.date), 'EEE')}`;
}

import { View, Text } from 'react-native';
import { CheckCircle2, FastForward } from 'lucide-react-native';
import {
  formatActivityDate,
  formatActivityTime,
} from '../../utils/habitCalculations';

interface ActivityEntry {
  _creationTime: number;
  date: string;
  completed: boolean;
}

interface ActivityLogProps {
  tracking: ActivityEntry[];
}

export function ActivityLog({ tracking }: ActivityLogProps) {
  // Sort by date descending (most recent first) and limit to 20 entries
  const sortedActivities = [...tracking]
    .sort((a, b) => {
      // Sort by date first
      const dateCompare = b.date.localeCompare(a.date);
      if (dateCompare !== 0) return dateCompare;
      // If same date, sort by creation time
      return b._creationTime - a._creationTime;
    })
    .slice(0, 20);

  if (sortedActivities.length === 0) {
    return (
      <View className='mt-6'>
        <Text className='mb-4 text-lg font-bold text-stone-900'>
          Activity Log
        </Text>
        <View className='rounded-xl bg-stone-50 p-6'>
          <Text className='text-center text-sm text-stone-500'>
            No activity logged yet
          </Text>
        </View>
      </View>
    );
  }

  return (
    <View className='mt-6'>
      <Text className='mb-4 text-lg font-bold text-stone-900'>
        Activity Log
      </Text>
      <View className='gap-3'>
        {sortedActivities.map((activity, index) => (
          <View
            key={`${activity.date}-${activity._creationTime}`}
            className='flex-row items-center justify-between rounded-xl bg-white p-4'
          >
            {/* Left side - Status and Date */}
            <View className='flex-1'>
              <Text className='text-base font-semibold text-stone-900'>
                {activity.completed ? 'Completed' : 'Skipped'}
              </Text>
              <Text className='mt-0.5 text-sm text-stone-500'>
                {formatActivityDate(activity.date)}
              </Text>
            </View>

            {/* Right side - Time with Icon */}
            <View className='flex-row items-center gap-2'>
              {activity.completed ? (
                <CheckCircle2 color='#10b981' fill='#10b981' size={18} />
              ) : (
                <FastForward color='#a8a29e' size={18} />
              )}
              <Text
                className={`text-sm font-semibold ${
                  activity.completed ? 'text-emerald-500' : 'text-stone-500'
                }`}
              >
                {formatActivityTime(activity._creationTime)}
              </Text>
            </View>
          </View>
        ))}
      </View>
    </View>
  );
}

import {
  format,
  subMonths,
  startOfMonth,
  endOfMonth,
  eachDayOfInterval,
  getDay,
} from 'date-fns';
import { View, Text } from 'react-native';
import type { Id } from '../../../convex/_generated/dataModel';

interface HeatmapCalendarProps {
  habitId: Id<'habits'>;
  tracking: Array<{ habitId: Id<'habits'>; date: string; completed: boolean }>;
  monthsToShow?: number;
}

export default function HeatmapCalendar({
  habitId,
  tracking,
  monthsToShow = 6,
}: HeatmapCalendarProps) {
  const today = new Date();
  const maxOccurrences = 5; // Maximum occurrences of a weekday in a month

  // Generate array of months to display (current month and previous months)
  const months = Array.from({ length: monthsToShow }, (_, i) =>
    subMonths(today, monthsToShow - 1 - i)
  );

  // Create a map of completed dates for quick lookup
  const completedDates = new Set(
    tracking
      .filter((t) => t.habitId === habitId && t.completed)
      .map((t) => t.date)
  );

  // Get days grouped by week day (0 = Sunday, 1 = Monday, etc.)
  const getDaysByWeekDay = (days: Date[]) => {
    const byWeekDay: Date[][] = Array.from({ length: 7 }, () => []);
    for (const day of days) {
      const weekDay = getDay(day);
      byWeekDay[weekDay].push(day);
    }
    return byWeekDay;
  };

  return (
    <View className='rounded-xl bg-stone-50 px-4 py-3'>
      {/* Month labels */}
      <View className='mb-3 flex-row'>
        <View className='w-12' />
        {months.map((month, monthIndex) => (
          <View key={monthIndex} className='flex-1'>
            <Text className='text-center text-xs font-medium text-stone-500'>
              {format(month, 'MMM')}
            </Text>
          </View>
        ))}
      </View>

      {/* Day rows - showing Mon, Thu, Sun as in Figma */}
      {[1, 4, 0].map((dayOfWeek) => {
        const dayLabel =
          dayOfWeek === 0 ? 'Sun' : dayOfWeek === 1 ? 'Mon' : 'Thu';

        return (
          <View key={dayOfWeek} className='mb-2.5 flex-row'>
            {/* Day label */}
            <View className='w-12 justify-center'>
              <Text className='text-xs text-stone-400'>{dayLabel}</Text>
            </View>

            {/* Dots for each month */}
            {months.map((month, monthIndex) => {
              const monthStart = startOfMonth(month);
              const monthEnd = endOfMonth(month);
              const days = eachDayOfInterval({
                end: monthEnd,
                start: monthStart,
              });
              const byWeekDay = getDaysByWeekDay(days);
              const daysForThisWeekDay = byWeekDay[dayOfWeek] || [];

              return (
                <View
                  key={monthIndex}
                  className='flex-1 flex-row justify-center gap-1.5'
                >
                  {Array.from({ length: maxOccurrences }).map(
                    (_, slotIndex) => {
                      const day = daysForThisWeekDay[slotIndex];

                      if (!day) {
                        // Empty slot for alignment
                        return (
                          <View
                            key={`empty-${monthIndex}-${slotIndex}`}
                            className='h-1.5 w-1.5'
                          />
                        );
                      }

                      const dateString = format(day, 'yyyy-MM-dd');
                      const isCompleted = completedDates.has(dateString);
                      const isFuture = day > today;

                      return (
                        <View
                          key={dateString}
                          className='h-1.5 w-1.5 rounded-full'
                          style={{
                            backgroundColor: isFuture
                              ? '#e7e5e4'
                              : isCompleted
                                ? '#10b981'
                                : '#d6d3d1',
                          }}
                        />
                      );
                    }
                  )}
                </View>
              );
            })}
          </View>
        );
      })}
    </View>
  );
}

/**
 * MonthlyCalendar Component
 * Matches Figma design: Monthly calendar grid with blue dots for completed days
 * and black circle around current day
 */

import { View, Text, Pressable } from 'react-native';
import { ChevronLeft, ChevronRight } from 'lucide-react-native';
import {
  format,
  startOfMonth,
  endOfMonth,
  eachDayOfInterval,
  getDay,
  isSameDay,
  startOfToday,
} from 'date-fns';
import { useState } from 'react';
import type { Id } from '../../../convex/_generated/dataModel';

interface MonthlyCalendarProps {
  habitId: Id<'habits'>;
  tracking: Array<{ habitId: Id<'habits'>; date: string; completed: boolean }>;
  toggleHabit: (args: { habitId: Id<'habits'>; date: string }) => void;
}

export function MonthlyCalendar({
  habitId,
  tracking,
  toggleHabit,
}: MonthlyCalendarProps) {
  const [currentDate, setCurrentDate] = useState(new Date());
  const today = startOfToday();

  // Get all days in the current month
  const monthStart = startOfMonth(currentDate);
  const monthEnd = endOfMonth(currentDate);
  const daysInMonth = eachDayOfInterval({ end: monthEnd, start: monthStart });

  // Calculate empty cells before first day (0 = Sunday, 6 = Saturday)
  const firstDayOfWeek = getDay(monthStart);
  const emptyDays = Array.from({ length: firstDayOfWeek }, (_, i) => i);

  // Check if a date is completed
  const isCompleted = (date: Date) => {
    const dateString = format(date, 'yyyy-MM-dd');
    return tracking.some(
      (t) => t.habitId === habitId && t.date === dateString && t.completed
    );
  };

  // Navigation handlers
  const goToPreviousMonth = () => {
    const newDate = new Date(currentDate);
    newDate.setMonth(newDate.getMonth() - 1);
    setCurrentDate(newDate);
  };

  const goToNextMonth = () => {
    const newDate = new Date(currentDate);
    newDate.setMonth(newDate.getMonth() + 1);
    setCurrentDate(newDate);
  };

  return (
    <View>
      {/* Header with Month/Year and Navigation */}
      <View className='mb-4 flex-row items-center justify-between'>
        <Text className='text-lg font-bold text-stone-900'>
          {format(currentDate, 'MMMM yyyy')}
        </Text>

        <View className='flex-row gap-2'>
          <Pressable
            className='h-8 w-8 items-center justify-center rounded-full active:bg-stone-100'
            onPress={goToPreviousMonth}
          >
            <ChevronLeft color='#1c1917' size={20} />
          </Pressable>

          <Pressable
            className='h-8 w-8 items-center justify-center rounded-full active:bg-stone-100'
            onPress={goToNextMonth}
          >
            <ChevronRight color='#1c1917' size={20} />
          </Pressable>
        </View>
      </View>

      {/* Day Names Row */}
      <View className='mb-3 flex-row'>
        {['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].map((day) => (
          <View key={day} className='w-[14.28%] items-center'>
            <Text className='text-sm font-medium text-stone-500'>{day}</Text>
          </View>
        ))}
      </View>

      {/* Calendar Grid */}
      <View className='flex-row flex-wrap'>
        {/* Empty cells before first day */}
        {emptyDays.map((i) => (
          <View key={`empty-${i}`} className='mb-2 h-7 w-[14.28%]' />
        ))}

        {/* Actual days */}
        {daysInMonth.map((date) => {
          const isToday = isSameDay(date, today);
          const hasCompletion = isCompleted(date);
          const dateString = format(date, 'yyyy-MM-dd');

          return (
            <Pressable
              key={dateString}
              className='mb-2 w-[14.28%] items-center'
              onPress={() => toggleHabit({ date: dateString, habitId })}
            >
              <View className='relative items-center'>
                {/* Day number with optional black circle for today */}
                {isToday ? (
                  <View className='h-8 w-8 items-center justify-center rounded-full bg-stone-900'>
                    <Text className='text-base font-bold text-white'>
                      {format(date, 'd')}
                    </Text>
                  </View>
                ) : (
                  <View className='h-7 items-center justify-center'>
                    <Text className='text-base font-semibold text-stone-900'>
                      {format(date, 'd')}
                    </Text>
                  </View>
                )}

                {/* Blue dot for completed days */}
                {hasCompletion && (
                  <View className='absolute -bottom-1 h-1 w-1 rounded-full bg-blue-500' />
                )}
              </View>
            </Pressable>
          );
        })}
      </View>
    </View>
  );
}

