/**
 * useEntranceHandlers Hook
 * Provides handlers for entrance animation control
 */

import { useCallback } from 'react';
import { cancelAnimation } from 'react-native-reanimated';
import { ACCENT_TARGET_WIDTH } from './constants';
import { runFadeUp, runAccentSlideDown, runWidthExpansion } from './animations';
import type {
  UseEntranceHandlersOptions,
  UseEntranceHandlersReturn,
} from './types';

export function useEntranceHandlers({
  values,
  variant,
  delay,
  reduceMotion,
  onAnimationComplete,
}: UseEntranceHandlersOptions): UseEntranceHandlersReturn {
  const {
    accentOpacity,
    accentScaleY,
    accentWidth,
    cardOpacity,
    cardTranslateY,
    contentOpacity,
    contentTranslateX,
    isAnimating,
  } = values;

  const setInstantVisible = useCallback(() => {
    cardOpacity.value = 1;
    cardTranslateY.value = 0;
    accentScaleY.value = 1;
    accentWidth.value = ACCENT_TARGET_WIDTH;
    accentOpacity.value = 1;
    contentOpacity.value = 1;
    contentTranslateX.value = 0;
  }, [
    accentOpacity,
    accentScaleY,
    accentWidth,
    cardOpacity,
    cardTranslateY,
    contentOpacity,
    contentTranslateX,
  ]);

  const triggerEntrance = useCallback(() => {
    if (reduceMotion || variant === 'none') {
      setInstantVisible();
      isAnimating.value = false;
      onAnimationComplete?.();
      return;
    }
    isAnimating.value = true;
    const execute = () => {
      switch (variant) {
        case 'fadeUp': {
          runFadeUp(values, onAnimationComplete);
          break;
        }
        case 'accentSlideDown': {
          runAccentSlideDown(values, onAnimationComplete);
          break;
        }
        case 'widthExpansion': {
          runWidthExpansion(values, onAnimationComplete);
          break;
        }
        default: {
          runAccentSlideDown(values, onAnimationComplete);
        }
      }
    };
    if (delay > 0) {
      setTimeout(execute, delay);
    } else {
      execute();
    }
  }, [
    reduceMotion,
    variant,
    delay,
    setInstantVisible,
    onAnimationComplete,
    values,
    isAnimating,
  ]);

  const resetAnimation = useCallback(() => {
    const allValues = [
      cardOpacity,
      cardTranslateY,
      accentScaleY,
      accentWidth,
      accentOpacity,
      contentOpacity,
      contentTranslateX,
    ];
    for (const val of allValues) cancelAnimation(val);
    cardOpacity.value = 0;
    cardTranslateY.value = 20;
    accentScaleY.value = 0;
    accentWidth.value = 0;
    accentOpacity.value = 0;
    contentOpacity.value = 0;
    contentTranslateX.value = -10;
    isAnimating.value = false;
  }, [
    accentOpacity,
    accentScaleY,
    accentWidth,
    cardOpacity,
    cardTranslateY,
    contentOpacity,
    contentTranslateX,
    isAnimating,
  ]);

  return { resetAnimation, setInstantVisible, triggerEntrance };
}

/**
 * Tap Gesture Handler
 * Handles tap-to-toggle completion with haptic feedback
 */

import { Gesture } from 'react-native-gesture-handler';
import { withSpring, runOnJS, type SharedValue } from 'react-native-reanimated';
import * as Haptics from 'expo-haptics';
import type { Id } from '../../../../../convex/_generated/dataModel';
import { Springs } from '../../../constants/motion';

interface TapGestureOptions {
  id: Id<'habits'>;
  completed: boolean;
  disabled: boolean;
  isToggling: boolean;
  cardScale: SharedValue<number>;
  today: string;
  onPress?: () => void;
  setIsToggling: (value: boolean) => void;
  toggleCompletionMutation: (args: {
    date: string;
    habitId: Id<'habits'>;
  }) => Promise<unknown>;
  triggerCompletionCelebration: () => void;
  triggerUncheckAnimation: () => void;
}

export function createTapGesture(options: TapGestureOptions) {
  const {
    id,
    completed,
    disabled,
    isToggling,
    cardScale,
    today,
    onPress,
    setIsToggling,
    toggleCompletionMutation,
    triggerCompletionCelebration,
    triggerUncheckAnimation,
  } = options;

  return Gesture.Tap()
    .onBegin(() => {
      cardScale.value = withSpring(0.96, Springs.button);
    })
    .onFinalize(() => {
      cardScale.value = withSpring(1, Springs.button);
    })
    .onEnd(() => {
      if (!disabled && !isToggling) {
        if (completed) {
          runOnJS(() => {
            Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(
              () => {}
            );
          })();
          triggerUncheckAnimation();
        } else {
          runOnJS(() => {
            Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium).catch(
              () => {}
            );
          })();
          triggerCompletionCelebration();
        }
        runOnJS(setIsToggling)(true);
        runOnJS(async () => {
          try {
            await toggleCompletionMutation({ date: today, habitId: id });
          } catch (error) {
            console.error('Toggle completion failed:', error);
          } finally {
            setTimeout(() => {
              setIsToggling(false);
            }, 300);
          }
        })();
        if (onPress) {
          runOnJS(onPress)();
        }
      }
    });
}

/**
 * useHabitCard Hook - Core orchestration logic
 */

import { useState } from 'react';
import { useSharedValue, useAnimatedStyle } from 'react-native-reanimated';
import { useMutation, useQuery } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { useAppTheme } from '../../theme';
import { useHabitCardEntrance } from './useHabitCardEntrance';
import { useHabitCardAnimations } from './useHabitCardAnimations';
import { useHabitCardGestures } from './useHabitCardGestures';
import { useHabitCardEffects } from './useHabitCardEffects';
import { getStrengthColor, getBackgroundColor } from './HabitCard.utils';
import type { HabitCardProps } from './HabitCard.types';

export function useHabitCard(props: HabitCardProps) {
  const {
    id,
    name,
    color,
    strength,
    atRisk = false,
    completed: completedProp = false,
    disabled = false,
    onPress,
    onLongPress,
    entranceVariant = 'widthExpansion',
    entranceDelay = 0,
    triggerEntrance: shouldTriggerEntrance = true,
    onEntranceComplete,
  } = props;

  const theme = useAppTheme();
  const translateX = useSharedValue(0);
  const cardScale = useSharedValue(1);
  const strengthFillWidth = useSharedValue(strength);
  const [showFloatingXP, setShowFloatingXP] = useState(false);
  const [xpPosition, setXPPosition] = useState({ x: 0, y: 0 });
  const [isToggling, setIsToggling] = useState(false);

  const today = new Date().toISOString().split('T')[0];
  const completedQuery = useQuery(api.tracking.getCompletionStatus, {
    date: today,
    habitId: id,
  });
  const completed = completedQuery ?? completedProp;
  const toggleCompletionMutation = useMutation(api.tracking.toggleCompletion);

  const entrance = useHabitCardEntrance({
    autoTrigger: shouldTriggerEntrance,
    delay: entranceDelay,
    onAnimationComplete: onEntranceComplete,
    variant: entranceVariant,
  });

  const animations = useHabitCardAnimations({
    cardScale,
    setShowFloatingXP,
    setXPPosition,
    translateX,
  });

  const { composedGesture } = useHabitCardGestures({
    cardScale,
    completed,
    disabled,
    id,
    isToggling,
    name,
    onLongPress,
    onPress,
    setIsToggling,
    today,
    toggleCompletionMutation,
    translateX,
    triggerCompletionCelebration: animations.triggerCompletionCelebration,
    triggerUncheckAnimation: animations.triggerUncheckAnimation,
  });

  useHabitCardEffects({
    checkmarkRotate: animations.checkmarkRotate,
    checkmarkScale: animations.checkmarkScale,
    completed,
    strength,
    strengthFillWidth,
  });

  const strengthFillStyle = useAnimatedStyle(() => ({
    width: `${strengthFillWidth.value}%`,
  }));

  return {
    accentColor: color || theme.custom.colors.primary[500],
    animations,
    backgroundColor: getBackgroundColor(completed, atRisk, theme),
    borderRadius: theme.custom.borderRadius.large,
    completed,
    composedGesture,
    entrance,
    setShowFloatingXP,
    showFloatingXP,
    strengthColor: getStrengthColor(strength, theme),
    strengthFillStyle,
    theme,
    translateX,
    xpPosition,
  };
}

