  accentColor,
  accessibilityHint,
  accessibilityLabel,
  completionIcon,
  completed,
  disabled,
  highContrastMode,
  isToday,
  onPress,
  shape,
}) => {
  const { completion, buttonScale, combinedScale } =
    useHabitDayToggleAnimations({
      completed,
      isToday,
    });

  const { handlePressIn, handlePressOut, handlePress } =
    useHabitDayToggleHandlers({
      buttonScale,
      completed,
