import { useMemo, useState } from 'react';
import { parse, format } from 'date-fns';
import type { Id } from '../../../convex/_generated/dataModel';
import { useHabitChainVisualizerLogic } from './HabitChainVisualizer.hooks';
import { useHapticFeedback } from '../../hooks/useHapticFeedback';
import { useToggleDayHandler } from './useToggleDayHandler';
import type { HabitStatus } from './types';

interface UseChainVisualizerStateParams {
  weekDateStrings: string[];
  weekStatus: HabitStatus[];
  celebrationsEnabled: boolean;
  reduceMotionPreference: boolean;
  habitId: Id<'habits'>;
  onToggle: (args: { habitId: Id<'habits'>; date: string }) => void;
  onWeekComplete?: (args: { completedDate: string }) => void;
}

export const useChainVisualizerState = ({
  weekDateStrings,
  weekStatus,
  celebrationsEnabled,
  reduceMotionPreference,
  habitId,
  onToggle,
  onWeekComplete,
}: UseChainVisualizerStateParams) => {
  const { isCompleted, isFutureDate, isToday } = useHabitChainVisualizerLogic(
    weekDateStrings,
    weekStatus
  );
  const [activeBurst, setActiveBurst] = useState<string | null>(null);

  const { triggerSelection, triggerSuccess } = useHapticFeedback({
    isEnabled: celebrationsEnabled,
    preference: reduceMotionPreference,
  });

  const shouldReduceMotion = useMemo(
    () => reduceMotionPreference || !celebrationsEnabled,
    [celebrationsEnabled, reduceMotionPreference]
  );

  const todayLabel = format(new Date(), 'MMM d, EEE').toUpperCase();

  const dateLabels = useMemo(
    () =>
      weekDateStrings.map((dateString) => {
        const parsedDate = parse(dateString, 'yyyy-MM-dd', new Date());
        return format(parsedDate, 'MMM d, EEE').toUpperCase();
      }),
    [weekDateStrings]
  );

  const handleToggleDay = useToggleDayHandler({
    celebrationsEnabled,
    habitId,
    onToggle,
    onWeekComplete,
    setActiveBurst,
    triggerSelection,
    triggerSuccess,
    weekStatus,
  });

  return {
    activeBurst,
    dateLabels,
    handleToggleDay,
    isCompleted,
    isFutureDate,
    isToday,
    setActiveBurst,
    shouldReduceMotion,
    todayLabel,
  };
};

import { useEffect, useMemo, useRef } from 'react';
import { Animated, Easing } from 'react-native';

interface UseHabitDayToggleAnimationsParams {
  completed: boolean;
  isToday: boolean;
}

export const useHabitDayToggleAnimations = ({
  completed,
  isToday,
}: UseHabitDayToggleAnimationsParams) => {
  const completion = useRef(new Animated.Value(completed ? 1 : 0)).current;
  const buttonScale = useRef(new Animated.Value(1)).current;
  const breathingPulse = useRef(new Animated.Value(1)).current;

  // Combine scale values using Animated.multiply
  const combinedScale = useMemo(
    () => Animated.multiply(buttonScale, breathingPulse),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    []
  );

  useEffect(() => {
    let animation: Animated.CompositeAnimation | null = null;

    animation = completed
      ? Animated.parallel([
          Animated.spring(buttonScale, {
            friction: 6,
            tension: 300,
            toValue: 1,
            useNativeDriver: true,
          }),
          Animated.timing(completion, {
            duration: 220,
            easing: Easing.out(Easing.cubic),
            toValue: 1,
            useNativeDriver: true,
          }),
        ])
      : Animated.timing(completion, {
          duration: 150,
          easing: Easing.in(Easing.ease),
          toValue: 0,
          useNativeDriver: true,
        });

    animation.start();

    return () => {
      animation?.stop();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [completed]);

  useEffect(() => {
    if (!completed && isToday) {
      const breathingAnimation = Animated.loop(
        Animated.sequence([
          Animated.timing(breathingPulse, {
            duration: 1500,
            easing: Easing.inOut(Easing.ease),
            toValue: 1.03,
            useNativeDriver: true,
          }),
          Animated.timing(breathingPulse, {
            duration: 1500,
            easing: Easing.inOut(Easing.ease),
            toValue: 1,
            useNativeDriver: true,
          }),
        ])
      );
      breathingAnimation.start();

      return () => {
        breathingAnimation.stop();
      };
    } else {
      breathingPulse.setValue(1);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [completed, isToday]);

  return { buttonScale, combinedScale, completion };
};

import { useCallback, useRef } from 'react';
import type { Id } from '../../../convex/_generated/dataModel';
import type { HabitStatus } from './types';

interface UseToggleDayHandlerParams {
  weekStatus: HabitStatus[];
  celebrationsEnabled: boolean;
  habitId: Id<'habits'>;
  onToggle: (args: { habitId: Id<'habits'>; date: string }) => void;
  onWeekComplete?: (args: { completedDate: string }) => void;
  triggerSelection: () => void;
  triggerSuccess: () => void;
  setActiveBurst: (dateString: string | null) => void;
}

export const useToggleDayHandler = ({
  weekStatus,
  celebrationsEnabled,
  habitId,
  onToggle,
  onWeekComplete,
  triggerSelection,
  triggerSuccess,
  setActiveBurst,
}: UseToggleDayHandlerParams) => {
  const weekStatusRef = useRef(weekStatus);
  weekStatusRef.current = weekStatus;

  const handleToggleDay = useCallback(
    (
      dateString: string,
      completed: boolean,
      disabled: boolean,
      index: number
    ) => {
      if (disabled) {
        triggerSelection();
        return;
      }

      const isTogglingToComplete = !completed;
      const currentWeekStatus = weekStatusRef.current;
      const willCompleteWeek =
        isTogglingToComplete &&
        currentWeekStatus.every((status, i) =>
          i === index ? true : status === 'done'
        );

      if (completed || !celebrationsEnabled) {
        triggerSelection();
      } else {
        triggerSuccess();
        if (willCompleteWeek) {
          setActiveBurst(dateString);
        }
      }

      onToggle({ date: dateString, habitId });

      if (willCompleteWeek) {
        onWeekComplete?.({ completedDate: dateString });
      }
    },
    [
      celebrationsEnabled,
      habitId,
      onToggle,
      onWeekComplete,
      triggerSelection,
      triggerSuccess,
      setActiveBurst,
    ]
  );

  return handleToggleDay;
};

/**
 * HabitDetailTabs Component
 *
 * Tab bar navigation for the Habit Detail screen.
 * Uses a pill/segment control style with smooth sliding animation.
 */

import React, { useCallback, useEffect } from 'react';
import { View, LayoutChangeEvent } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  useDerivedValue,
} from 'react-native-reanimated';
import * as Haptics from 'expo-haptics';

import type { TabType, HabitDetailTabsProps } from './HabitDetailTabs.types';
import {
  TABS,
  PILL_SPRING_CONFIG,
  CONTAINER_PADDING,
  TAB_GAP,
} from './HabitDetailTabs.constants';
import { TabButton } from './components/TabButton';

export function HabitDetailTabs({
  activeTab,
  onTabChange,
}: HabitDetailTabsProps) {
  const containerWidth = useSharedValue(0);
  const indicatorPosition = useSharedValue(
    TABS.findIndex((t) => t.id === activeTab)
  );

  const pillWidth = useDerivedValue(() => {
    if (containerWidth.value === 0) return 0;
    const availableWidth =
      containerWidth.value -
      CONTAINER_PADDING * 2 -
      TAB_GAP * (TABS.length - 1);
    return availableWidth / TABS.length;
  });

  const handleLayout = useCallback(
    (event: LayoutChangeEvent) => {
      containerWidth.value = event.nativeEvent.layout.width;
    },
    [containerWidth]
  );

  useEffect(() => {
    const index = TABS.findIndex((t) => t.id === activeTab);
    indicatorPosition.value = withSpring(index, PILL_SPRING_CONFIG);
  }, [activeTab, indicatorPosition]);

  const pillStyle = useAnimatedStyle(() => {
    const width = pillWidth.value;
    if (width === 0) return { opacity: 0 };
    const leftOffset =
      CONTAINER_PADDING + indicatorPosition.value * (width + TAB_GAP);
    return { left: leftOffset, opacity: 1, width };
  });

  const handleTabPress = useCallback(
    (tab: TabType) => {
      if (tab !== activeTab) {
        Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
        onTabChange(tab);
      }
    },
    [activeTab, onTabChange]
  );

  return (
    <View
      accessibilityRole='tablist'
      className='mx-4 my-3'
      onLayout={handleLayout}
    >
      <View className='relative rounded-xl bg-stone-100 p-1'>
        <Animated.View
          className='absolute bottom-1 top-1 rounded-lg bg-violet-600 shadow-sm'
          style={pillStyle}
        />
        <View className='flex-row' style={{ gap: TAB_GAP }}>
          {TABS.map((tab) => (
            <TabButton
              key={tab.id}
              isActive={activeTab === tab.id}
              label={tab.label}
              onPress={() => handleTabPress(tab.id)}
            />
          ))}
        </View>
      </View>
    </View>
  );
}

export default HabitDetailTabs;

/**
 * TabContent Component
 * Manages tab content with scroll position preservation and animations
 */

import React, { useRef } from 'react';
import { View, ScrollView } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withTiming,
  Easing,
} from 'react-native-reanimated';

import type {
  TabType,
  TabContentProps,
  TabSectionProps,
  TabPaneProps,
} from './HabitDetailTabs.types';

const AnimatedView = Animated.View;

function TabPane({ children, isActive, tabId }: TabPaneProps) {
  const scrollRef = useRef<ScrollView>(null);
  const scrollPosition = useRef(0);

  const opacity = useSharedValue(isActive ? 1 : 0);
  const translateY = useSharedValue(isActive ? 0 : 10);

  React.useEffect(() => {
    if (isActive) {
      opacity.value = withTiming(1, {
        duration: 200,
        easing: Easing.out(Easing.cubic),
      });
      translateY.value = withTiming(0, {
        duration: 200,
        easing: Easing.out(Easing.cubic),
      });
    } else {
      opacity.value = 0;
      translateY.value = 10;
    }
  }, [isActive, opacity, translateY]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ translateY: translateY.value }],
  }));

  if (!isActive) {
    return null;
  }

  return (
    <AnimatedView
      accessible
      accessibilityLabel={`${tabId} tab content`}
      className='flex-1'
      style={animatedStyle}
    >
      {children}
    </AnimatedView>
  );
}

export function TabContent({ activeTab, children }: TabContentProps) {
  const childArray = React.Children.toArray(children);

  return (
    <View className='flex-1'>
      {childArray.map((child) => {
        if (!React.isValidElement<TabSectionProps>(child)) return null;

        const tabId = child.props.tabId;
        const isActive = tabId === activeTab;

        return (
          <TabPane key={tabId} isActive={isActive} tabId={tabId}>
            {child}
          </TabPane>
        );
      })}
    </View>
  );
}

export function TabSection({ children }: TabSectionProps) {
  return <>{children}</>;
}

export default TabContent;

/**
 * HabitNotesSection Component
 * Displays notes for a specific habit with recent note preview, count badge, and add action
 *
 * Story 1.9.3 - Habit Detail Notes Module
 */

import React from 'react';
import { View, Text, Pressable } from 'react-native';
import { format } from 'date-fns';
import { StickyNote, Plus, ChevronRight, Edit3 } from 'lucide-react-native';
import * as Haptics from 'expo-haptics';
import { clsx } from 'clsx';
import type { Doc } from '../../../convex/_generated/dataModel';

interface HabitNotesSectionProps {
  /** Notes for this habit (should already be filtered by habitId and sorted desc) */
  notes: Doc<'notes'>[];
  /** Callback when user taps "Add Note" */
  onAddNote: () => void;
  /** Callback when user taps "View All" to open full notes list */
  onViewAll: () => void;
  /** Callback when user taps a note to edit it */
  onEditNote?: (note: Doc<'notes'>) => void;
}

/**
 * Section Card wrapper for consistent styling
 */
function SectionCard({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <View
      className={clsx(
        'rounded-2xl bg-white p-4 shadow-sm shadow-stone-200/50',
        className
      )}
    >
      {children}
    </View>
  );
}

export function HabitNotesSection({
  notes,
  onAddNote,
  onViewAll,
  onEditNote,
}: HabitNotesSectionProps) {
  const noteCount = notes.length;
  const mostRecentNote = notes[0]; // Notes should already be sorted desc

  const handleAddNote = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onAddNote();
  };

  const handleViewAll = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onViewAll();
  };

  const handleEditNote = (note: Doc<'notes'>) => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onEditNote?.(note);
  };

  return (
    <SectionCard className="border-l-4 border-amber-400">
      {/* Header with title, count badge, and add button */}
      <View className="mb-3 flex-row items-center justify-between">
        <View className="flex-row items-center gap-2">
          <View className="h-10 w-10 items-center justify-center rounded-xl bg-amber-100">
            <StickyNote
              className="text-amber-500"
              size={20}
              strokeWidth={2.25}
            />
          </View>
          <View>
            <View className="flex-row items-center gap-2">
              <Text className="font-semibold text-stone-800">Notes</Text>
              {noteCount > 0 && (
                <View
                  accessibilityLabel={`${noteCount} ${noteCount === 1 ? 'note' : 'notes'}`}
                  className="rounded-full bg-amber-100 px-2 py-0.5"
                >
                  <Text className="text-xs font-medium text-amber-700">
                    {noteCount}
                  </Text>
                </View>
              )}
            </View>
            <Text className="text-xs text-stone-500">
              Track what works for you
            </Text>
          </View>
        </View>
        <Pressable
          accessibilityLabel="Add note"
          accessibilityRole="button"
          className="rounded-full bg-amber-500 px-3 py-1.5 active:bg-amber-600"
          onPress={handleAddNote}
        >
          <View className="flex-row items-center gap-1">
            <Plus color="#ffffff" size={14} strokeWidth={2.5} />
            <Text className="text-xs font-semibold text-white">Add</Text>
          </View>
        </Pressable>
      </View>

      {/* Content area */}
      {noteCount === 0 ? (
        /* Empty state */
        <Pressable
          accessibilityLabel="Add your first note"
          accessibilityRole="button"
          className="items-center rounded-xl bg-amber-50/50 py-6 active:bg-amber-50"
          onPress={handleAddNote}
        >
          <StickyNote className="mb-2 text-amber-200" size={28} />
          <Text className="text-center text-sm text-stone-500">
            Record insights to learn what works best
          </Text>
          <Text className="mt-1 text-xs font-medium text-amber-600">
            Add your first note
          </Text>
        </Pressable>
      ) : (
        <View className="gap-3">
          {/* Most recent note preview */}
          <Pressable
            accessibilityLabel={`Most recent note: ${mostRecentNote.body.slice(0, 50)}`}
            accessibilityRole="button"
            className="rounded-xl border border-stone-100 bg-stone-50/50 p-4 active:bg-stone-100"
            onPress={() => handleEditNote(mostRecentNote)}
          >
            <View className="mb-2 flex-row items-center justify-between">
              <Text className="text-xs font-medium text-stone-500">
                {format(new Date(mostRecentNote.date), 'MMM d, yyyy')}
              </Text>
              <Edit3 className="text-stone-400" size={14} />
            </View>
            <Text
              className="text-sm leading-5 text-stone-700"
              numberOfLines={3}
            >
              {mostRecentNote.body}
            </Text>
          </Pressable>

          {/* View All button (only show if more than 1 note) */}
          {noteCount > 1 && (
            <Pressable
              accessibilityLabel={`View all ${noteCount} notes`}
              accessibilityRole="button"
              className="flex-row items-center justify-center gap-1 rounded-xl border border-dashed border-stone-200 bg-white py-3 active:bg-stone-50"
              onPress={handleViewAll}
            >
              <Text className="text-sm font-medium text-stone-600">
                View all ({noteCount})
              </Text>
              <ChevronRight className="text-stone-400" size={16} />
            </Pressable>
          )}
        </View>
      )}
    </SectionCard>
  );
}

export default HabitNotesSection;

