    color: colors.text.secondary,
    marginBottom: spacing.xs,
    marginTop: spacing.md,
  },
  rankNumber: {
    ...typography.bodyBold,
    color: colors.text.tertiary,
    fontSize: 14,
  },
  riskBadge: {
    alignItems: 'center',
    backgroundColor: '#FEE2E2',
    borderRadius: 4,
    flexDirection: 'row',
    marginLeft: spacing.xs,
    paddingHorizontal: spacing.xs,
    paddingVertical: 2,
  },
  riskText: {
    ...typography.caption,
    color: colors.error,
    fontSize: 10,
    marginLeft: 2,
  },
  separator: {
    backgroundColor: colors.border,
    height: 1,
    marginVertical: spacing.xs,
  },
  statItem: {
    alignItems: 'center',
