    marginRight: spacing.md,
  },
  statText: {
    ...typography.caption,
    color: colors.text.tertiary,
    marginLeft: spacing.xxs,
  },
  strengthPercentage: {
    ...typography.h3,
    color: colors.primary[500],
    marginBottom: spacing.xs,
  },
});

/**
 * HabitStrengthHistory Component
 *
 * Main container that composes all Habit Strength History sub-components.
 * Displays habit strength evolution using exponential smoothing algorithm.
 *
 * @see habit-strength-history-spec.md for design details
 */

import React from 'react';
import { View, Text, Pressable } from 'react-native';
import Animated, {
  FadeIn,
  FadeInUp,
  useReducedMotion,
} from 'react-native-reanimated';
import { Info, Zap } from 'lucide-react-native';

import { useHabitStrength } from '../../hooks/useHabitStrength';

import { HabitStrengthHistorySkeleton } from './HabitStrengthHistorySkeleton';
import { StrengthComparisonCards } from './StrengthComparisonCards';
import { StrengthTimelineChart } from './StrengthTimelineChart';
import { StrengthInsightsRow } from './StrengthInsightsRow';
import type { HabitStrengthHistoryProps } from './types';

// Animation constants
const SECTION_FADE_DURATION = 400;
const SECTION_SLIDE_DURATION = 400;
const SECTION_SLIDE_DELAY = 200;

// Placeholder for info button handler - can be extended to show modal
const handleInfoPress = () => {
  // TODO: Show info modal explaining habit strength calculation
};

interface EmptyStrengthStateProps {
  habitAgeDays: number;
  reduceMotion: boolean;
}

/**
 * Encouraging empty state shown when habit has no completions yet.
 */
function EmptyStrengthState({
  habitAgeDays,
  reduceMotion,
}: EmptyStrengthStateProps) {
  const entering = reduceMotion
    ? FadeIn.duration(SECTION_FADE_DURATION)
    : FadeInUp.duration(SECTION_SLIDE_DURATION).delay(SECTION_SLIDE_DELAY);

  const message =
    habitAgeDays <= 1
      ? 'Complete your first day to start building strength!'
      : 'Complete today to start building your habit strength!';

  return (
    <Animated.View
      accessible
      accessibilityLabel='Habit strength history - No completions yet'
      className='gap-4'
      entering={entering}
      testID='habit-strength-history-empty'
    >
      <View className='flex-row items-center justify-between'>
        <Text className='text-base font-semibold text-stone-700'>
          Strength History
        </Text>
        <Pressable
          accessible
          accessibilityLabel='Learn more about habit strength'
          accessibilityRole='button'
          hitSlop={{ bottom: 10, left: 10, right: 10, top: 10 }}
          testID='strength-history-info-button'
          onPress={handleInfoPress}
        >
          <Info color='#78716c' size={18} />
        </Pressable>
      </View>

      <View className='items-center justify-center rounded-xl bg-stone-50 px-6 py-8'>
        <View className='mb-3 h-12 w-12 items-center justify-center rounded-full bg-amber-100'>
          <Zap color='#d97706' size={24} />
        </View>
        <Text className='mb-1 text-center text-base font-semibold text-stone-700'>
          Ready to Build Strength
        </Text>
        <Text className='text-center text-sm text-stone-500'>{message}</Text>
      </View>
    </Animated.View>
  );
}

interface SectionHeaderProps {
  title: string;
  onInfoPress?: () => void;
}

/**
 * Section header with title and info icon button
 */
function SectionHeader({ title, onInfoPress }: SectionHeaderProps) {
  return (
    <View className='flex-row items-center justify-between'>
      <Text className='text-base font-semibold text-stone-700'>{title}</Text>
      <Pressable
        accessible
        accessibilityLabel='Learn more about habit strength'
        accessibilityRole='button'
        hitSlop={{ bottom: 10, left: 10, right: 10, top: 10 }}
        testID='strength-history-info-button'
        onPress={onInfoPress}
      >
        <Info color='#78716c' size={18} />
      </Pressable>
    </View>
  );
}

/**
 * HabitStrengthHistory - Main container component
 *
 * Composes all sub-components and manages data flow via useHabitStrength hook.
 */
export function HabitStrengthHistory({
  habitId: _habitId,
  completedDates,
  habitCreatedAt,
  habitColor,
}: HabitStrengthHistoryProps) {
  const shouldReduceMotion = useReducedMotion();

  const { currentStrength, strengthHistory, metrics, isCalculating } =
    useHabitStrength(completedDates, habitCreatedAt);

  if (isCalculating) {
    return (
      <HabitStrengthHistorySkeleton
        reduceMotion={shouldReduceMotion ?? false}
      />
    );
  }

  // Show encouraging empty state if no completions ever
  const hasNoCompletions = completedDates.size === 0;
  if (hasNoCompletions) {
    return (
      <EmptyStrengthState
        habitAgeDays={metrics.habitAgeDays}
        reduceMotion={shouldReduceMotion ?? false}
      />
    );
  }

  const slideUpEntering = shouldReduceMotion
    ? FadeIn.duration(SECTION_FADE_DURATION)
    : FadeInUp.duration(SECTION_SLIDE_DURATION).delay(SECTION_SLIDE_DELAY);

  return (
    <Animated.View
      accessible
      accessibilityLabel='Habit strength history section'
      accessibilityRole='none'
      className='gap-4'
      entering={slideUpEntering}
      testID='habit-strength-history'
    >
      <SectionHeader title='Strength History' onInfoPress={handleInfoPress} />

      <StrengthComparisonCards
        completedDates={completedDates}
        current={currentStrength}
        deltaVsMonth={metrics.deltaVsMonth}
        habitAgeDays={metrics.habitAgeDays}
        oneYearAgo={metrics.oneYearAgo}
        thirtyDaysAgo={metrics.thirtyDaysAgo}
      />

      <StrengthTimelineChart
        habitColor={habitColor}
        strengthHistory={strengthHistory}
      />

      <StrengthInsightsRow
        deltaVsMonth={metrics.deltaVsMonth}
        lowest={metrics.lowest}
        peak={metrics.peak}
      />
    </Animated.View>
  );
}

export default HabitStrengthHistory;

/**
 * HabitStrengthHistorySkeleton Component
 *
 * Loading skeleton for the Habit Strength History section.
 * Displays shimmer placeholders matching the layout of the actual content.
 *
 * Features:
 * - 3 pulse cards for comparison section
 * - Gradient shimmer effect for timeline chart
 * - 3 insight cards with icon placeholders
 * - Respects reduced motion preference
 */

import React, { useEffect } from 'react';
import { StyleSheet, View } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import Animated, {
  Easing,
  interpolate,
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withTiming,
} from 'react-native-reanimated';

import { SkeletonLoader } from '../SkeletonLoader/SkeletonLoader';

const AnimatedLinearGradient = Animated.createAnimatedComponent(LinearGradient);

/**
 * Skeleton colors matching the design system
 */
const SKELETON_COLORS = {
  base: '#E7E5E4', // stone-200
  highlight: '#F5F5F4', // stone-100
} as const;

/**
 * Shimmer animation duration in milliseconds
 */
const SHIMMER_DURATION = 1500;

interface GradientShimmerSkeletonProps {
  height: number;
  borderRadius?: number;
  reduceMotion?: boolean;
}

/**
 * Skeleton element with gradient sweep shimmer animation.
 * Used for larger elements like charts where the gradient effect is more visible.
 */
function GradientShimmerSkeleton({
  height,
  borderRadius = 12,
  reduceMotion = false,
}: GradientShimmerSkeletonProps) {
  const shimmerPosition = useSharedValue(0);

  useEffect(() => {
    if (reduceMotion) {
      // For reduced motion, keep a static state
      shimmerPosition.value = 0.5;
      return;
    }

    shimmerPosition.value = withRepeat(
      withTiming(1, {
        duration: SHIMMER_DURATION,
        easing: Easing.inOut(Easing.ease),
      }),
      -1, // Infinite repeat
      false // Don't reverse
    );
  }, [shimmerPosition, reduceMotion]);

  const animatedStyle = useAnimatedStyle(() => {
    // Animate the gradient from left to right
    const translateX = interpolate(shimmerPosition.value, [0, 1], [-200, 200]);
    return {
      transform: [{ translateX }],
    };
  });

  return (
    <View
      style={[
        styles.gradientContainer,
        {
          borderRadius,
          height,
        },
      ]}
      testID='skeleton-chart-gradient'
    >
      <AnimatedLinearGradient
        colors={[
          SKELETON_COLORS.base,
          SKELETON_COLORS.highlight,
          SKELETON_COLORS.base,
        ]}
        end={{ x: 1, y: 0.5 }}
        start={{ x: 0, y: 0.5 }}
        style={[StyleSheet.absoluteFillObject, styles.gradient, animatedStyle]}
      />
    </View>
  );
}

interface HabitStrengthHistorySkeletonProps {
  reduceMotion?: boolean;
}

export function HabitStrengthHistorySkeleton({
  reduceMotion = false,
}: HabitStrengthHistorySkeletonProps) {
  return (
    <View
      accessible
      accessibilityLabel='Loading habit strength history'
      className='gap-4'
      testID='habit-strength-history-skeleton'
    >
      {/* Header skeleton */}
      <View className='flex-row items-center justify-between'>
        <SkeletonLoader
          borderRadius={6}
          height={20}
          reduceMotion={reduceMotion}
          width={140}
        />
        <SkeletonLoader
          borderRadius={10}
          height={20}
          reduceMotion={reduceMotion}
          width={20}
        />
      </View>

      {/* Comparison cards skeleton (3 pulse cards) */}
      <View className='flex-row gap-2'>
        {[0, 1, 2].map((i) => (
          <View
            key={i}
            className='flex-1 items-center rounded-xl bg-stone-50 p-3'
            testID={`skeleton-card-${i}`}
          >
            <SkeletonLoader
              borderRadius={28}
              height={56}
              reduceMotion={reduceMotion}
              width={56}
            />
            <View className='mt-2 w-full items-center gap-1'>
              <SkeletonLoader
                borderRadius={4}
                height={12}
                reduceMotion={reduceMotion}
                width={40}
              />
              <SkeletonLoader
                borderRadius={4}
                height={12}
                reduceMotion={reduceMotion}
                width={60}
              />
            </View>
          </View>
        ))}
      </View>

      {/* Timeline chart skeleton with gradient shimmer */}
      <GradientShimmerSkeleton
        borderRadius={12}
        height={120}
        reduceMotion={reduceMotion}
      />

      {/* Insights row skeleton (3 cards) */}
      <View className='flex-row gap-2'>
        {[0, 1, 2].map((i) => (
          <View
            key={i}
            className='flex-1 flex-row items-center gap-2 rounded-lg bg-stone-50 px-3 py-2.5'
            testID={`skeleton-insight-${i}`}
          >
            <SkeletonLoader
              borderRadius={9}
              height={18}
              reduceMotion={reduceMotion}
              width={18}
            />
            <View className='flex-1 gap-1'>
              <SkeletonLoader
                borderRadius={4}
                height={14}
                reduceMotion={reduceMotion}
                width={40}
              />
              <SkeletonLoader
                borderRadius={3}
                height={10}
                reduceMotion={reduceMotion}
                width={50}
              />
            </View>
          </View>
        ))}
      </View>
    </View>
  );
}

