/**
 * StrengthTimelineChart Component - SVG area chart for habit strength evolution
 */

import React, { useMemo } from 'react';
import Animated, { FadeIn } from 'react-native-reanimated';

import { getStrengthColor } from '../strengthUtils';
import {
  DEFAULT_HEIGHT,
  DEFAULT_CHART_COLOR,
  MIN_HISTORY_LENGTH,
  PATH_ANIMATION_DURATION,
} from './constants';
import { generateChartPaths } from './pathUtils';
import { generateXAxisLabels, calculateTrendDescription } from './axisUtils';
import { useChartDimensions } from './useChartDimensions';
import { usePathAnimation } from './usePathAnimation';
import { usePulseAnimation } from './usePulseAnimation';
import { ChartSvg } from './ChartSvg';
import { XAxisLabels } from './XAxisLabels';
import { NoDataState, BuildingHistoryState } from './EmptyStates';
import type { StrengthTimelineChartProps } from './types';

export function StrengthTimelineChart({
  strengthHistory,
  habitColor,
  height = DEFAULT_HEIGHT,
}: StrengthTimelineChartProps) {
  const dimensions = useChartDimensions(height);

  const chartColor = useMemo(() => {
    if (habitColor) return habitColor;
    if (strengthHistory.length > 0)
      return getStrengthColor(strengthHistory.at(-1)!.strength);
    return DEFAULT_CHART_COLOR;
  }, [habitColor, strengthHistory]);

  const { areaPath, linePath, lastPoint } = useMemo(
    () => generateChartPaths(strengthHistory, dimensions),
    [strengthHistory, dimensions]
  );

  const xAxisLabels = useMemo(
    () => generateXAxisLabels(strengthHistory.length, dimensions),
    [strengthHistory.length, dimensions]
  );

  const { animatedLineProps } = usePathAnimation({
    historyLength: strengthHistory.length,
  });
  const { pulsingRingProps } = usePulseAnimation({ lastPoint });
  const trendDescription = useMemo(
    () => calculateTrendDescription(strengthHistory),
    [strengthHistory]
  );

  if (strengthHistory.length === 0) return <NoDataState height={height} />;
  if (strengthHistory.length < MIN_HISTORY_LENGTH)
    return <BuildingHistoryState height={height} />;

  return (
    <Animated.View
      accessible
      accessibilityLabel={`Strength timeline chart showing ${strengthHistory.length} days of history. ${trendDescription}`}
      accessibilityRole='image'
      className='overflow-hidden rounded-xl bg-stone-50'
      entering={FadeIn.duration(PATH_ANIMATION_DURATION)}
    >
      <ChartSvg
        animatedLineProps={animatedLineProps}
        areaPath={areaPath}
        chartColor={chartColor}
        dimensions={dimensions}
        lastPoint={lastPoint}
        linePath={linePath}
        pulsingRingProps={pulsingRingProps}
      />
      <XAxisLabels labels={xAxisLabels} />
    </Animated.View>
  );
}

export default StrengthTimelineChart;

/**
 * Habit Strength Utility Functions
 *
 * Provides calculation and formatting utilities for habit strength
 * using an exponential smoothing algorithm (Loop Habit Tracker style).
 *
 * Key Concepts:
 * - Strength grows on completions: strength + (1 - strength) * GROWTH_RATE
 * - Strength decays on misses: strength * DECAY_RATE
 * - Thresholds: 0-29% weak, 30-69% developing, 70-100% strong
 *
 * @see habit-strength-history-spec.md Section 3
 */

import { addDays, differenceInDays, format, startOfDay } from 'date-fns';

import type {
  StrengthAlgorithmConfig,
  StrengthColors,
  StrengthLabel,
  StrengthSnapshot,
} from './types';

// Algorithm constants (based on Loop Habit Tracker)
const DEFAULT_GROWTH_RATE = 0.05; // ~5% growth per completion
const DEFAULT_DECAY_RATE = 0.95; // ~5% decay per miss
const DEFAULT_MAX_SAMPLE_POINTS = 100;

// Threshold constants for strength labels
const WEAK_THRESHOLD = 30;
const STRONG_THRESHOLD = 70;

/**
 * Color palette for each strength level.
 * Based on design spec Section 7.1.
 *
 * WCAG AA Compliance:
 * - Primary colors meet 4.5:1 contrast ratio for normal text on white/light backgrounds
 * - Red-600 (4.83:1), Amber-700 (5.02:1), Emerald-700 (5.48:1)
 */
const STRENGTH_COLOR_MAP: Record<StrengthLabel, StrengthColors> = {
  developing: {
    // Amber-700 (WCAG AA: 5.02:1)
    background: '#fffbeb',
    primary: '#b45309', // Amber-50
    ring: '#fcd34d', // Amber-300
  },
  strong: {
    // Emerald-700 (WCAG AA: 5.48:1)
    background: '#ecfdf5',
    primary: '#047857', // Emerald-50
    ring: '#6ee7b7', // Emerald-300
  },
  weak: {
    // Red-600 (WCAG AA: 4.83:1)
    background: '#fef2f2',
    primary: '#dc2626', // Red-50
    ring: '#fca5a5', // Red-300
  },
};

/**
 * Format a date as YYYY-MM-DD string for consistent lookup.
 */
export function formatDateString(date: Date): string {
  return format(date, 'yyyy-MM-dd');
}

/**
 * Calculate habit strength at a specific target date.
 *
 * Iterates day-by-day from habit creation to the target date,
 * applying growth on completions and decay on misses.
 *
 * @param completedDates - Set of completed dates in YYYY-MM-DD format
 * @param habitCreatedAt - Date when the habit was created
 * @param targetDate - Date to calculate strength for
 * @param config - Optional algorithm configuration
 * @returns Strength as a percentage (0-100)
 *
 * @example
 * const strength = calculateStrengthAtDate(
 *   new Set(['2024-01-01', '2024-01-02']),
 *   new Date('2024-01-01'),
 *   new Date('2024-01-02')
 * );
 * // Returns ~10 (two completions from zero)
 */
export function calculateStrengthAtDate(
  completedDates: Set<string>,
  habitCreatedAt: Date,
  targetDate: Date,
  config: Partial<StrengthAlgorithmConfig> = {}
): number {
  const growthRate = config.growthRate ?? DEFAULT_GROWTH_RATE;
  const decayRate = config.decayRate ?? DEFAULT_DECAY_RATE;

  // Normalize dates to start of day for consistent comparison
  const startDate = startOfDay(habitCreatedAt);
  const endDate = startOfDay(targetDate);

  // If target is before creation, return 0
  if (endDate < startDate) {
    return 0;
  }

  let strength = 0;
  let currentDate = startDate;

  // Iterate day by day
  while (currentDate <= endDate) {
    const dateStr = formatDateString(currentDate);

    // Growth on completion (approaches 100% asymptotically), decay on miss (exponential toward 0)
    strength = completedDates.has(dateStr)
      ? strength + (1 - strength) * growthRate
      : strength * decayRate;

    currentDate = addDays(currentDate, 1);
  }

  // Return as percentage (0-100), rounded to 1 decimal place
  return Math.round(strength * 1000) / 10;
}

/**
 * Get the human-readable strength label based on percentage.
 *
 * Thresholds:
 * - 0-29%: "weak" (habit not established)
 * - 30-69%: "developing" (building consistency)
 * - 70-100%: "strong" (habit is automatic)
 *
 * @param strength - Strength percentage (0-100)
 * @returns Strength label
 */
export function getStrengthLabel(strength: number): StrengthLabel {
  if (strength < WEAK_THRESHOLD) {
    return 'weak';
  }
  if (strength < STRONG_THRESHOLD) {
    return 'developing';
  }
  return 'strong';
}

/**
 * Get the primary color for a strength value.
 *
 * @param strength - Strength percentage (0-100)
 * @returns Color hex string
 */
export function getStrengthColor(strength: number): string {
  const label = getStrengthLabel(strength);
  return STRENGTH_COLOR_MAP[label].primary;
}

/**
 * Get the full color palette for a strength value.
 *
 * @param strength - Strength percentage (0-100)
 * @returns StrengthColors object with primary, background, and ring colors
 */
export function getStrengthColors(strength: number): StrengthColors {
  const label = getStrengthLabel(strength);
  return STRENGTH_COLOR_MAP[label];
}

/**
 * Generate a complete strength timeline from habit creation to today.
 *
 * For performance with long histories (2+ years), samples down to
 * maxSamplePoints while preserving key events (start, end, peaks, valleys).
 *
 * @param completedDates - Set of completed dates in YYYY-MM-DD format
 * @param habitCreatedAt - Date when the habit was created
 * @param sampleSize - Maximum number of data points (default: 100)
 * @returns Array of StrengthSnapshot objects for charting
 */
export function generateStrengthTimeline(
  completedDates: Set<string>,
  habitCreatedAt: Date,
  sampleSize: number = DEFAULT_MAX_SAMPLE_POINTS
): StrengthSnapshot[] {
  const startDate = startOfDay(habitCreatedAt);
  const endDate = startOfDay(new Date());

  const totalDays = differenceInDays(endDate, startDate) + 1;

  // If we have fewer days than sample size, return all days
  if (totalDays <= sampleSize) {
    return generateFullTimeline(completedDates, startDate, endDate);
  }

  // Sample evenly across the timeline
  return generateSampledTimeline(
    completedDates,
    startDate,
    endDate,
    totalDays,
    sampleSize
  );
}

/**
 * Generate full timeline without sampling.
 */
function generateFullTimeline(
  completedDates: Set<string>,
  startDate: Date,
  endDate: Date
): StrengthSnapshot[] {
  const timeline: StrengthSnapshot[] = [];
  let strength = 0;
  let currentDate = startDate;

  while (currentDate <= endDate) {
    const dateStr = formatDateString(currentDate);

    strength = completedDates.has(dateStr)
      ? strength + (1 - strength) * DEFAULT_GROWTH_RATE
      : strength * DEFAULT_DECAY_RATE;

    const strengthPercent = Math.round(strength * 1000) / 10;

    timeline.push({
      date: new Date(currentDate),
      dateString: dateStr,
      label: getStrengthLabel(strengthPercent),
      strength: strengthPercent,
    });

    currentDate = addDays(currentDate, 1);
  }

  return timeline;
}

/**
 * Generate sampled timeline for long histories.
 * Ensures start, end, and evenly distributed points are included.
 */
function generateSampledTimeline(
  completedDates: Set<string>,
  startDate: Date,
  endDate: Date,
  totalDays: number,
  sampleSize: number
): StrengthSnapshot[] {
  // First, calculate the full strength values
  const fullStrengths: Array<{ date: Date; strength: number }> = [];
  let strength = 0;
  let currentDate = startDate;

  while (currentDate <= endDate) {
    const dateStr = formatDateString(currentDate);

    strength = completedDates.has(dateStr)
      ? strength + (1 - strength) * DEFAULT_GROWTH_RATE
      : strength * DEFAULT_DECAY_RATE;

    fullStrengths.push({
      date: new Date(currentDate),
      strength: Math.round(strength * 1000) / 10,
    });

    currentDate = addDays(currentDate, 1);
  }

  // Sample evenly, always including first and last
  const timeline: StrengthSnapshot[] = [];
  const step = (totalDays - 1) / (sampleSize - 1);

  for (let i = 0; i < sampleSize; i++) {
    const index = Math.round(i * step);
    const sample = fullStrengths[index];

    timeline.push({
      date: sample.date,
      dateString: formatDateString(sample.date),
      label: getStrengthLabel(sample.strength),
      strength: sample.strength,
    });
  }

  return timeline;
}

/**
 * Calculate peak and lowest strength values from a timeline.
 *
 * The lowest value excludes day 1 (which is always 0 or near-0)
 * to provide a more meaningful "lowest point" metric.
 *
 * @param strengthHistory - Array of strength snapshots
 * @returns Object with peak and lowest snapshots
 */
export function calculateStrengthExtremes(
  strengthHistory: StrengthSnapshot[]
): { peak: StrengthSnapshot; lowest: StrengthSnapshot } {
  if (strengthHistory.length === 0) {
    const now = new Date();
    const emptySnapshot: StrengthSnapshot = {
      date: now,
      dateString: formatDateString(now),
      label: 'weak',
      strength: 0,
    };
    return { lowest: emptySnapshot, peak: emptySnapshot };
  }

  // Find peak
  let peak = strengthHistory[0];
  for (const snapshot of strengthHistory) {
    if (snapshot.strength > peak.strength) {
      peak = snapshot;
    }
  }

  // Find lowest (excluding first day)
  let lowest =
    strengthHistory.length > 1 ? strengthHistory[1] : strengthHistory[0];
  for (let i = 1; i < strengthHistory.length; i++) {
    if (strengthHistory[i].strength < lowest.strength) {
      lowest = strengthHistory[i];
    }
  }

  return { lowest, peak };
}

/**
 * Calculate the delta (change) between two strength values.
 * Returns positive for improvement, negative for decline.
 *
 * @param current - Current strength
 * @param previous - Previous strength
 * @returns Rounded delta value
 */
export function calculateDelta(current: number, previous: number): number {
  return Math.round((current - previous) * 10) / 10;
}

/**
 * Calculate the completion rate as a percentage.
 *
 * @param completedDates - Set of completed dates in YYYY-MM-DD format
 * @param habitAgeDays - Number of days since habit creation
 * @returns Completion rate as percentage (0-100)
 */
export function calculateCompletionRate(
  completedDates: Set<string>,
  habitAgeDays: number
): number {
  if (habitAgeDays <= 0) {
    return 0;
  }
  const completedCount = completedDates.size;
  return Math.round((completedCount / habitAgeDays) * 100);
}

/**
 * Check if the user has a perfect completion streak (100% completion rate).
 *
 * @param completedDates - Set of completed dates in YYYY-MM-DD format
 * @param habitAgeDays - Number of days since habit creation
 * @returns True if the user has completed every day since habit creation
 */
export function isPerfectStreak(
  completedDates: Set<string>,
  habitAgeDays: number
): boolean {
  // Need at least 3 days to show "Perfect!" badge (to avoid trivial cases)
  if (habitAgeDays < 3) {
    return false;
  }
  return completedDates.size >= habitAgeDays;
}

/**
 * HabitStrengthIndicator Component
 * Based on UX Specification Section 4.2
 *
 * Variants: Compact (list), Full (detail), Graph (trend line - premium)
 * States: Starting 🌱 (0-20%), Building 🌿 (20-40%), Developing 🌳 (40-60%),
 *         Strong 💪 (60-80%), Automatic ⚡ (80-100%)
 * Animation: Progress bar fills with spring physics, emoji changes with scale bounce
 * Accessibility: Announces "Meditation habit, 65% strength, Strong level"
 */

import React, { useEffect, useRef } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withSequence,
  withTiming,
  withDelay,
  Easing,
} from 'react-native-reanimated';
import { useAppTheme } from '../../theme';

// Safely import AccessibilityInfo (may not be available in all environments)
let AccessibilityInfo: any;
try {
  AccessibilityInfo = require('react-native').AccessibilityInfo;
} catch (e) {
  AccessibilityInfo = null;
}

export type StrengthLevel =
  | 'starting'
  | 'building'
  | 'developing'
  | 'strong'
  | 'automatic';

export type StrengthVariant = 'compact' | 'full' | 'graph';

interface HabitStrengthIndicatorProps {
  /** Strength value (0-100 scale) */
  strength: number;

  /** Optional override for strength level */
  strengthLevel?: StrengthLevel;

  /** Display variant */
  variant?: StrengthVariant;

  /** Show percentage number */
  showPercentage?: boolean;

  /** Show label text (Full variant only) */
  showLabel?: boolean;

  /** Habit name for accessibility */
  habitName?: string;

  /** Historical data for graph variant (array of strength values over time) */
  historicalData?: number[];
}

/**
 * Strength Level Configuration
 * Colors from theme/colors.ts strength levels
 */
const STRENGTH_LEVEL_CONFIG: Record<
  StrengthLevel,
  {
    emoji: string;
    label: string;
    description: string;
    minThreshold: number;
    maxThreshold: number;
  }
> = {
  automatic: {
    description: 'Fully automatic',
    emoji: '⚡',
    label: 'Automatic',
    maxThreshold: 100,
    minThreshold: 80,
  },
  building: {
    description: 'Making progress',
    emoji: '🌿',
    label: 'Building',
    maxThreshold: 40,
    minThreshold: 20,
  },
  developing: {
    description: 'Getting stronger',
    emoji: '🌳',
    label: 'Developing',
    maxThreshold: 60,
    minThreshold: 40,
  },
  starting: {
    description: 'Just beginning',
    emoji: '🌱',
    label: 'Starting Out',
    maxThreshold: 20,
    minThreshold: 0,
  },
  strong: {
    description: 'Well-established',
    emoji: '💪',
    label: 'Strong',
    maxThreshold: 80,
    minThreshold: 60,
  },
};

/**
 * Get strength level from percentage
 */
function getStrengthLevel(strength: number): StrengthLevel {
  if (strength < 20) return 'starting';
  if (strength < 40) return 'building';
  if (strength < 60) return 'developing';
  if (strength < 80) return 'strong';
  return 'automatic';
}

export default function HabitStrengthIndicator({
  strength,
  strengthLevel,
  variant = 'compact',
  showPercentage = true,
  showLabel = true,
  habitName,
  historicalData = [],
}: HabitStrengthIndicatorProps) {
  const theme = useAppTheme();
  const level = strengthLevel || getStrengthLevel(strength);
  const config = STRENGTH_LEVEL_CONFIG[level];

  // Get color from theme based on strength level
  const getStrengthColor = (): string => {
    switch (level) {
      case 'starting': {
        return theme.custom.colors.strength.starting;
      }
      case 'building': {
        return theme.custom.colors.strength.building;
      }
      case 'developing': {
        return theme.custom.colors.strength.developing;
      }
      case 'strong': {
        return theme.custom.colors.strength.strong;
      }
      case 'automatic': {
        return theme.custom.colors.strength.automatic;
      }
    }
  };

  // Track previous level to detect actual level changes
  const previousLevelRef = useRef<StrengthLevel>(level);

  // Animation values
  const progressWidth = useSharedValue(0);
  const emojiScale = useSharedValue(1);
  const emojiOpacity = useSharedValue(1);
  const emojiRotation = useSharedValue(0);

  // Animate progress bar and emoji when strength/level changes
  useEffect(() => {
    // Smooth progress bar fill
    progressWidth.value = withSpring(strength, {
      damping: 15,
      stiffness: 150,
    });

    // Detect if level actually changed (meaningful transition)
    const levelChanged = previousLevelRef.current !== level;
    previousLevelRef.current = level;

    if (levelChanged) {
      // 🌱→🌿→🌳 LEVEL-UP ANIMATION: Meaningful growth transition
      // Phase 1: Fade out + shrink old emoji (transformation begins)
      emojiOpacity.value = withTiming(0.3, {
        duration: 150,
        easing: Easing.out(Easing.ease),
      });
      emojiScale.value = withTiming(0.6, {
        duration: 150,
        easing: Easing.out(Easing.ease),
      });
      // Gentle wobble like a plant swaying
      emojiRotation.value = withSequence(
        withTiming(-8, { duration: 80, easing: Easing.inOut(Easing.ease) }),
        withTiming(8, { duration: 80, easing: Easing.inOut(Easing.ease) }),
        withTiming(0, { duration: 60, easing: Easing.out(Easing.ease) })
      );

      // Phase 2: Fade in + grow new emoji (emergence)
      emojiOpacity.value = withDelay(
        150,
        withTiming(1, { duration: 200, easing: Easing.out(Easing.ease) })
      );
      emojiScale.value = withDelay(
        150,
        withSequence(
          // Grow with overshoot (blossoming)
          withSpring(1.4, { damping: 6, stiffness: 120 }),
          // Settle to final size (rooted)
          withSpring(1, { damping: 10, stiffness: 180 })
        )
      );
    } else {
      // Regular strength update: subtle pulse to acknowledge change
      emojiScale.value = withSequence(
        withTiming(1.08, { duration: 100, easing: Easing.out(Easing.ease) }),
        withSpring(1, { damping: 15, stiffness: 200 })
      );
    }
  }, [strength, level]);

  // Accessibility announcement
  useEffect(() => {
    const message = habitName
      ? `${habitName}, ${Math.round(strength)}% strength, ${config.label} level`
      : `${Math.round(strength)}% strength, ${config.label} level`;

    AccessibilityInfo?.announceForAccessibility?.(message);
  }, [strength, level, habitName]);

  // Animated styles
  const progressBarStyle = useAnimatedStyle(() => ({
    width: `${progressWidth.value}%`,
  }));

  const emojiStyle = useAnimatedStyle(() => ({
    opacity: emojiOpacity.value,
    transform: [
      { scale: emojiScale.value },
      // Round to avoid "Loss of precision during arithmetic conversion" error in Reanimated
      { rotate: `${Math.round(emojiRotation.value)}deg` },
    ],
  }));

  // Compact Variant (for habit list)
  if (variant === 'compact') {
    return (
      <View
        accessible
        accessibilityLabel={`${Math.round(strength)}% strength, ${config.label}`}
        accessibilityRole='progressbar'
        style={styles.compactContainer}
      >
        <Animated.Text style={[styles.compactEmoji, emojiStyle]}>
          {config.emoji}
        </Animated.Text>

        <View
          style={[
            styles.compactBarContainer,
            { backgroundColor: theme.custom.colors.gray[200] },
          ]}
        >
          <Animated.View
            style={[
              styles.compactBar,
              progressBarStyle,
              { backgroundColor: getStrengthColor() },
            ]}
          />
        </View>

        {showPercentage && (
          <Text
            style={[
              theme.custom.typography.bodySmall,
              styles.percentage,
              { color: theme.custom.colors.gray[600] },
            ]}
          >
            {Math.round(strength)}%
          </Text>
        )}
      </View>
    );
  }

  // Full Variant (for habit detail)
  if (variant === 'full') {
    return (
      <View
        accessible
        accessibilityLabel={`${Math.round(strength)}% strength, ${config.label} level. ${config.description}`}
        accessibilityRole='progressbar'
        style={styles.fullContainer}
      >
        {showLabel && (
          <View style={styles.fullHeader}>
            <View style={styles.fullLabelContainer}>
              <Animated.Text style={[styles.fullEmoji, emojiStyle]}>
                {config.emoji}
              </Animated.Text>
              <Text
                style={[
                  theme.custom.typography.heading3,
                  { color: theme.custom.colors.gray[900] },
                ]}
              >
                {config.label}
              </Text>
            </View>

            {showPercentage && (
              <Text
                style={[
                  theme.custom.typography.heading2,
                  {
                    color: getStrengthColor(),
                    fontFamily: theme.custom.fontFamilies.monospace,
                  },
                ]}
              >
                {Math.round(strength)}%
              </Text>
            )}
          </View>
        )}

        <View
          style={[
            styles.fullBarContainer,
            { backgroundColor: theme.custom.colors.gray[200] },
          ]}
        >
          <Animated.View
            style={[
              styles.fullBar,
              progressBarStyle,
              { backgroundColor: getStrengthColor() },
            ]}
          />
        </View>

        {showLabel && (
          <Text
            style={[
              theme.custom.typography.caption,
              { color: theme.custom.colors.gray[500] },
            ]}
          >
            {config.description}
          </Text>
        )}
      </View>
    );
  }

  // Graph Variant (trend line for premium analytics)
  if (variant === 'graph') {
    // TODO: Implement graph variant with Victory Native or react-native-svg
    // For now, show a placeholder
    return (
      <View style={styles.graphContainer}>
        <Text
          style={[
            theme.custom.typography.caption,
            { color: theme.custom.colors.gray[500] },
          ]}
        >
          Graph variant - Coming soon (Premium feature)
        </Text>
        {/* This will be implemented in Phase 7: Premium Features */}
      </View>
    );
  }

  return null;
}

const styles = StyleSheet.create({
  compactBar: {
    borderRadius: 2,
    height: '100%',
  },

  compactBarContainer: {
    borderRadius: 2,
    flex: 1,
    height: 4,
    overflow: 'hidden',
  },
  // Compact variant (list view)
  compactContainer: {
    alignItems: 'center',
    flexDirection: 'row',
    gap: 6,
  },
  compactEmoji: {
    fontSize: 16,
  },

  fullBar: {
    borderRadius: 4,
    height: '100%',
  },

  fullBarContainer: {
    borderRadius: 4,
    height: 8,
    overflow: 'hidden',
    width: '100%',
  },
  // Full variant (detail view)
  fullContainer: {
    gap: 8,
  },
  fullEmoji: {
    fontSize: 32,
  },
  fullHeader: {
    alignItems: 'center',
    flexDirection: 'row',
    justifyContent: 'space-between',
  },
  fullLabelContainer: {
    alignItems: 'center',
    flexDirection: 'row',
    gap: 8,
  },
  // Graph variant (premium)
  graphContainer: {
    alignItems: 'center',
    height: 120,
    justifyContent: 'center',
  },

  percentage: {
    minWidth: 40,
    textAlign: 'right',
  },
});

export { STRENGTH_LEVEL_CONFIG, getStrengthLevel };

