/**
 * Habit Strength Section - Constants
 *
 * Sizing, colors, and animation configuration values for the
 * HabitStrengthSection component and its sub-components.
 */

import type { StrengthLabel } from '../HabitStrengthHistory/types';

// ============================================================================
// Layout & Sizing
// ============================================================================

/** Circular progress ring dimensions (compact for above-fold layout) */
export const RING_SIZE = 64; // Reduced from 72 to fit above fold
export const RING_STROKE_WIDTH = 5; // Slightly thinner for smaller ring
export const RING_RADIUS = (RING_SIZE - RING_STROKE_WIDTH) / 2;
export const RING_CIRCUMFERENCE = 2 * Math.PI * RING_RADIUS;

/** Chart dimensions (compact for above-fold layout) */
export const CHART_HEIGHT = 88; // Reduced from 112 to fit above fold
export const CHART_PADDING_X = 16;
export const CHART_PADDING_TOP = 6; // Reduced from 8
export const CHART_PADDING_BOTTOM = 20; // Reduced from 24, space for X-axis labels

/** Grid line configuration */
export const GRID_LINE_COUNT = 3; // 0%, 50%, 100%
export const GRID_LINE_DASH = '4,4';
export const GRID_LINE_OPACITY = 0.2;

/** Pulsing dot size */
export const DOT_RADIUS = 4;
export const DOT_PULSE_RADIUS = 8;

// ============================================================================
// Colors
// ============================================================================

/** Strength level colors based on design system */
export const STRENGTH_COLORS: Record<
  StrengthLabel,
  {
    primary: string;
    background: string;
    gradient: {
      start: string;
      end: string;
    };
  }
> = {
  strong: {
    primary: '#10b981', // emerald-500
    background: '#ecfdf5', // emerald-50
    gradient: {
      start: 'rgba(16, 185, 129, 0.25)', // 25% opacity
      end: 'rgba(16, 185, 129, 0.02)', // 2% opacity
    },
  },
  developing: {
    primary: '#f59e0b', // amber-500
    background: '#fffbeb', // amber-50
    gradient: {
      start: 'rgba(245, 158, 11, 0.25)',
      end: 'rgba(245, 158, 11, 0.02)',
    },
  },
  weak: {
    primary: '#ef4444', // red-500
    background: '#fef2f2', // red-50
    gradient: {
      start: 'rgba(239, 68, 68, 0.25)',
      end: 'rgba(239, 68, 68, 0.02)',
    },
  },
};

/** Neutral colors */
export const COLORS = {
  /** Card background */
  cardBackground: '#ffffff',
  /** Text primary */
  textPrimary: '#1c1917', // stone-900
  /** Text secondary */
  textSecondary: '#78716c', // stone-500
  /** Text muted */
  textMuted: '#a8a29e', // stone-400
  /** Border/divider color */
  border: '#e7e5e4', // stone-200
  /** Grid line color */
  gridLine: '#d6d3d1', // stone-300
  /** Positive delta color */
  positive: '#10b981', // emerald-500
  /** Negative delta color */
  negative: '#ef4444', // red-500
  /** Ring track color */
  ringTrack: '#f5f5f4', // stone-100
};

// ============================================================================
// Animation Timing
// ============================================================================

export const ANIMATION = {
  /** Ring fill animation duration (ms) */
  ringDuration: 1000,
  /** Number count-up duration (ms) */
  countUpDuration: 800,
  /** Chart path draw duration (ms) */
  chartDrawDuration: 1500,
  /** Pulsing dot animation duration (ms) */
  pulseDuration: 2000,
  /** Fade-in animation duration (ms) */
  fadeInDuration: 300,
  /** Easing function for animations */
  easing: 'ease-out',
};

// ============================================================================
// Time Range Labels
// ============================================================================

/** Time range toggle options */
export const TIME_RANGE_OPTIONS = [
  { value: '1m' as const, label: '1M' },
  { value: '3m' as const, label: '3M' },
  { value: '1y' as const, label: '1Y' },
];

/** Days for each time range */
export const TIME_RANGE_DAYS = {
  '1m': 30,
  '3m': 90,
  '1y': 365,
};

// ============================================================================
// Strength Labels
// ============================================================================

/** Human-readable labels for strength levels */
export const STRENGTH_LABELS: Record<StrengthLabel, string> = {
  strong: 'Strong',
  developing: 'Developing',
  weak: 'Weak',
};

/**
 * Habit Strength Section - Utility Functions
 *
 * Data transformation helpers for the HabitStrengthSection component.
 */

import { subDays, startOfDay, addDays, differenceInDays, format } from 'date-fns';

import type { StrengthSnapshot, StrengthLabel } from '../HabitStrengthHistory/types';
import {
  calculateStrengthAtDate,
  getStrengthLabel,
} from '../HabitStrengthHistory/strengthUtils';
import type { TimeRange, ExtendedStrengthMetrics } from './types';
import { TIME_RANGE_DAYS } from './constants';

/**
 * Filter strength history based on time range selection.
 *
 * @param history - Full strength history array
 * @param timeRange - Selected time range (1m/1y/all)
 * @returns Filtered history array
 */
export function filterHistoryByTimeRange(
  history: StrengthSnapshot[],
  timeRange: TimeRange
): StrengthSnapshot[] {
  if (history.length === 0) {
    return history;
  }

  const days = TIME_RANGE_DAYS[timeRange];
  const cutoffDate = startOfDay(subDays(new Date(), days));

  return history.filter((snapshot) => snapshot.date >= cutoffDate);
}

/**
 * Calculate week-over-week delta.
 *
 * @param completedDates - Set of completed dates
 * @param habitCreatedAt - Habit creation date
 * @param currentStrength - Current strength value
 * @returns Week-over-week change
 */
export function calculateWeekDelta(
  completedDates: Set<string>,
  habitCreatedAt: Date,
  currentStrength: number
): number {
  const today = startOfDay(new Date());
  const oneWeekAgo = subDays(today, 7);

  // If habit is less than 7 days old, return current strength as delta
  if (oneWeekAgo < startOfDay(habitCreatedAt)) {
    return currentStrength;
  }

  const weekAgoStrength = calculateStrengthAtDate(
    completedDates,
    habitCreatedAt,
    oneWeekAgo
  );

  // Round to integer to match displayed values
  return Math.round(currentStrength - weekAgoStrength);
}

/**
 * Calculate month-over-month delta.
 *
 * @param completedDates - Set of completed dates
 * @param habitCreatedAt - Habit creation date
 * @param currentStrength - Current strength value
 * @returns Month-over-month change
 */
export function calculateMonthDelta(
  completedDates: Set<string>,
  habitCreatedAt: Date,
  currentStrength: number
): number {
  const today = startOfDay(new Date());
  const thirtyDaysAgo = subDays(today, 30);

  // If habit is less than 30 days old, return current strength as delta
  if (thirtyDaysAgo < startOfDay(habitCreatedAt)) {
    return currentStrength;
  }

  const monthAgoStrength = calculateStrengthAtDate(
    completedDates,
    habitCreatedAt,
    thirtyDaysAgo
  );

  // Round to integer to match displayed values
  return Math.round(currentStrength - monthAgoStrength);
}

/**
 * Calculate extended metrics for the HabitStrengthSection.
 *
 * @param completedDates - Set of completed dates
 * @param habitCreatedAt - Habit creation timestamp (ms)
 * @param currentStrength - Current strength value (from database or calculated)
 * @param _deltaVsMonth - Deprecated: Month-over-month delta (now calculated internally)
 * @param strengthHistory - Full strength history
 * @param timeRange - Selected time range
 * @returns Extended metrics object
 */
export function calculateExtendedMetrics(
  completedDates: Set<string>,
  habitCreatedAt: number,
  currentStrength: number,
  _deltaVsMonth: number, // Ignored - we calculate this ourselves now
  strengthHistory: StrengthSnapshot[],
  timeRange: TimeRange
): ExtendedStrengthMetrics {
  const createdAtDate = new Date(habitCreatedAt);

  // Calculate week delta using current strength (from database)
  const deltaVsWeek = calculateWeekDelta(
    completedDates,
    createdAtDate,
    currentStrength
  );

  // Calculate month delta using current strength (from database)
  // This ensures consistency when habitStrength is passed from the database
  const deltaVsMonth = calculateMonthDelta(
    completedDates,
    createdAtDate,
    currentStrength
  );

  // Filter history by time range
  const filteredHistory = filterHistoryByTimeRange(strengthHistory, timeRange);

  // Get strength label
  const label = getStrengthLabel(currentStrength);

  return {
    current: Math.round(currentStrength),
    label,
    deltaVsMonth,
    deltaVsWeek,
    sinceStart: Math.round(currentStrength), // Since start = current (started at 0)
    strengthHistory: filteredHistory,
  };
}

/**
 * Sample strength history for chart display.
 * Reduces data points while preserving shape for performance.
 *
 * @param history - Strength history array
 * @param maxPoints - Maximum number of points to return
 * @returns Sampled history array
 */
export function sampleHistoryForChart(
  history: StrengthSnapshot[],
  maxPoints: number = 50
): StrengthSnapshot[] {
  if (history.length <= maxPoints) {
    return history;
  }

  const result: StrengthSnapshot[] = [];
  const step = (history.length - 1) / (maxPoints - 1);

  for (let i = 0; i < maxPoints; i++) {
    const index = Math.round(i * step);
    result.push(history[index]);
  }

  return result;
}

/** Exponential smoothing constants (matches Loop Habit Tracker) */
const GROWTH_RATE = 0.05; // +5% of remaining on completion
const DECAY_RATE = 0.95;  // -5% on miss

/**
 * Generate strength history directly from completedDates.
 *
 * This bypasses the useHabitStrength hook which may have incorrect
 * habitCreatedAt timestamps. Instead, we find the earliest completion
 * date and simulate the exponential smoothing algorithm from there.
 *
 * @param completedDates - Set of completion dates (YYYY-MM-DD format)
 * @param timeRange - Time range filter (1m/1y/all)
 * @returns Array of StrengthSnapshot for charting
 */
export function generateChartDataFromCompletions(
  completedDates: Set<string>,
  timeRange: TimeRange
): StrengthSnapshot[] {
  if (completedDates.size === 0) {
    return [];
  }

  // Find the earliest completion date
  const sortedDates = Array.from(completedDates).sort();
  const earliestDate = startOfDay(new Date(sortedDates[0]));
  const today = startOfDay(new Date());

  // Apply time range filter to start date
  const days = TIME_RANGE_DAYS[timeRange];
  const timeRangeStart = startOfDay(subDays(today, days));

  // Use the later of earliest completion or time range start
  const chartStartDate = timeRangeStart > earliestDate ? timeRangeStart : earliestDate;

  // We need to calculate strength from the very beginning to get accurate values
  // even if we only display from chartStartDate
  const totalDays = differenceInDays(today, earliestDate) + 1;

  // Generate full history from earliest date
  const fullHistory: StrengthSnapshot[] = [];
  let strength = 0;
  let currentDate = earliestDate;

  for (let i = 0; i < totalDays; i++) {
    const dateStr = format(currentDate, 'yyyy-MM-dd');
    const wasCompleted = completedDates.has(dateStr);

    // Apply exponential smoothing
    if (wasCompleted) {
      strength = strength + (1 - strength) * GROWTH_RATE;
    } else {
      strength = strength * DECAY_RATE;
    }

    // Convert to percentage (0-100)
    const strengthPercent = Math.round(strength * 1000) / 10;

    // Only include in result if on or after chart start date
    if (currentDate >= chartStartDate) {
      fullHistory.push({
        date: new Date(currentDate),
        dateString: dateStr,
        strength: strengthPercent,
        label: getStrengthLabel(strengthPercent),
      });
    }

    currentDate = addDays(currentDate, 1);
  }

  return fullHistory;
}

/**
 * HabitsAtRiskWidget Component
 * Phase 4: Retention Engine - Predictive Intelligence
 *
 * Displays habits with low predicted completion probability (<40%).
 * Provides intervention suggestions and quick actions to improve retention.
 *
 * UX Spec Reference: Section 2.1 - Habits at Risk Widget (Premium)
 * PRD Reference: Epic 3 - Adaptive Interventions
 */

import React from 'react';
import { View, Text, Pressable, StyleSheet } from 'react-native';
import { useQuery } from 'convex/react';
import { api } from '../../convex/_generated/api';
import { useAppTheme } from '../theme';
import type { Id } from '../../convex/_generated/dataModel';

interface HabitsAtRiskWidgetProps {
  onHabitPress: (habitId: Id<'habits'>) => void;
}

/**
 * At-risk habit type from predictions query
 * Matches the return type from api.predictions.getHabitsAtRisk
 */
interface AtRiskHabit {
  _id: Id<'habits'>;
  name: string;
  icon: string;
  strength: number;
  accessibility: number;
  predictedProbability: number;
  riskLevel: string; // 'high' or 'medium' from query
}

/**
 * Get intervention suggestion based on habit strength
 * Lower strength = more intensive intervention needed
 */
function getInterventionSuggestion(strength: number): string {
  if (strength < 0.3) return 'Needs intensive support';
  if (strength < 0.5) return 'Gentle reminder recommended';
  return 'Quick check-in suggested';
}

/**
 * HabitsAtRiskWidget
 *
 * Shows habits with <40% predicted completion probability.
 * Provides proactive alerts to help users maintain consistency.
 */
export function HabitsAtRiskWidget({ onHabitPress }: HabitsAtRiskWidgetProps) {
  const theme = useAppTheme();

  // Query habits with low prediction probability (default threshold: 0.4)
  const atRiskHabits = useQuery(api.predictions.getHabitsAtRisk, {
    threshold: 0.4, // <40% completion probability
  });

  // Don't show widget if loading or no at-risk habits
  if (!atRiskHabits || atRiskHabits.length === 0) {
    return null;
  }

  return (
    <View style={[styles.container, { borderColor: '#FCD34D' }]}>
      {/* Header */}
      <View style={styles.header}>
        <Text
          style={[styles.title, { color: theme.custom.colors.warning[700] }]}
        >
          ⚠️ Habits at Risk
        </Text>
        <Text
          style={[styles.subtitle, { color: theme.custom.colors.gray[600] }]}
        >
          {atRiskHabits.length}{' '}
          {atRiskHabits.length === 1 ? 'habit needs' : 'habits need'} attention
        </Text>
      </View>

      {/* At-Risk Habit Cards */}
      {atRiskHabits.map((habit: AtRiskHabit, index: number) => (
        <Pressable
          key={`at-risk-${index}`}
          accessibilityHint={`This habit has ${Math.round(habit.predictedProbability * 100)}% chance of completion tomorrow`}
          accessibilityLabel={`View ${habit.name} habit details`}
          accessibilityRole='button'
          style={({ pressed }) => [
            styles.habitCard,
            { backgroundColor: '#FFFBEB' },
            pressed && { opacity: 0.7 },
          ]}
          onPress={() => onHabitPress(habit._id)}
        >
          <View style={styles.habitInfo}>
            <Text
              style={[
                styles.habitName,
                { color: theme.custom.colors.gray[900] },
              ]}
            >
              {habit.icon} {habit.name}
            </Text>
            <Text
              style={[
                styles.prediction,
                { color: theme.custom.colors.warning[700] },
              ]}
            >
              {Math.round(habit.predictedProbability * 100)}% chance tomorrow
            </Text>
          </View>

          <View style={styles.interventionBadge}>
            <Text
              style={[
                styles.interventionText,
                { color: theme.custom.colors.warning[700] },
              ]}
            >
              {getInterventionSuggestion(habit.strength)}
            </Text>
          </View>
        </Pressable>
      ))}

      {/* View All Link */}
      <Pressable
        accessibilityLabel='View all predictions'
        accessibilityRole='button'
        style={styles.viewAllButton}
      >
        <Text
          style={[
            styles.viewAllText,
            { color: theme.custom.colors.primary[600] },
          ]}
        >
          View All Predictions →
        </Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    backgroundColor: '#FFF',
    borderRadius: 12,
    borderWidth: 1,
    marginHorizontal: 16,
    marginVertical: 16,
    padding: 16,
  },
  habitCard: {
    borderRadius: 8,
    marginBottom: 8,
    padding: 12,
  },
  habitInfo: {
    marginBottom: 6,
  },
  habitName: {
    fontSize: 16,
    fontWeight: '500',
    marginBottom: 2,
  },
  header: {
    marginBottom: 12,
  },
  interventionBadge: {
    alignSelf: 'flex-start',
  },
  interventionText: {
    fontSize: 12,
    fontWeight: '500',
  },
  prediction: {
    fontSize: 14,
  },
  subtitle: {
    fontSize: 14,
  },
  title: {
    fontSize: 18,
    fontWeight: '600',
    marginBottom: 4,
  },
  viewAllButton: {
    marginTop: 8,
    paddingVertical: 8,
  },
  viewAllText: {
    fontSize: 14,
    fontWeight: '500',
  },
});

export default HabitsAtRiskWidget;

