import React from 'react';
import { View } from 'react-native';
import { Clock, Zap } from 'lucide-react-native';
import { AnimatedContent } from './AnimatedContent';
import { StartNowButton } from './StartNowButton';
import { QuickAction } from './QuickAction';
import type { ActivationHabitData } from './types';

interface ActivationModalActionsProps {
  habit: ActivationHabitData;
  visible: boolean;
  reduceMotion: boolean;
  paddingBottom: number;
  onStartNow: () => void;
  onSnooze: () => void;
  onJustTwoMin: () => void;
}

/**
 * ActivationModalActions - Bottom action buttons
 */
export function ActivationModalActions({
  habit,
  visible,
  reduceMotion,
  paddingBottom,
  onStartNow,
  onSnooze,
  onJustTwoMin,
}: ActivationModalActionsProps) {
  const hasWhy = !!habit.why;
  const hasWOOP = !!habit.woopObstacle && !!habit.woopPlan;
  const hasCue =
    !!habit.cueTime || !!habit.cueLocation || !!habit.cueAfterBehavior;

  const startButtonIndex =
    (hasWhy ? 1 : 0) + (hasWOOP ? 1 : 0) + (hasCue ? 1 : 0) + 1;
  const quickActionsIndex = startButtonIndex + 1;

  return (
    <View
      className='border-t border-stone-200 bg-white px-4 pt-4'
      style={{ paddingBottom }}
    >
      {/* Start Now - Primary CTA */}
      <AnimatedContent
        index={startButtonIndex}
        reduceMotion={reduceMotion}
        visible={visible}
      >
        <StartNowButton reduceMotion={reduceMotion} onPress={onStartNow} />
      </AnimatedContent>

      {/* Quick Actions */}
      <AnimatedContent
        index={quickActionsIndex}
        reduceMotion={reduceMotion}
        visible={visible}
      >
        <View className='mt-3 flex-row gap-3'>
          <QuickAction
            icon={<Clock className='text-stone-500' size={16} />}
            label='Snooze'
            onPress={onSnooze}
          />
          <QuickAction
            icon={<Zap className='text-amber-500' size={16} />}
            label='Just 2 Min'
            onPress={onJustTwoMin}
          />
        </View>
      </AnimatedContent>
    </View>
  );
}

import React from 'react';
import { View, ScrollView } from 'react-native';
import { AnimatedContent } from './AnimatedContent';
import { HabitCard } from './HabitCard';
import { WhySection } from './WhySection';
import { WOOPReminder } from './WOOPReminder';
import { CueReminder } from './CueReminder';
import type { ActivationHabitData } from './types';

interface ActivationModalContentProps {
  habit: ActivationHabitData;
  visible: boolean;
  reduceMotion: boolean;
}

/**
 * ActivationModalContent - Scrollable content sections
 */
export function ActivationModalContent({
  habit,
  visible,
  reduceMotion,
}: ActivationModalContentProps) {
  const hasWhy = !!habit.why;
  const hasWOOP = !!habit.woopObstacle && !!habit.woopPlan;
  const hasCue =
    !!habit.cueTime || !!habit.cueLocation || !!habit.cueAfterBehavior;

  return (
    <ScrollView
      className='flex-1 px-4'
      contentContainerStyle={{ paddingBottom: 24 }}
      showsVerticalScrollIndicator={false}
    >
      {/* Habit Card */}
      <AnimatedContent index={0} reduceMotion={reduceMotion} visible={visible}>
        <HabitCard habit={habit} reduceMotion={reduceMotion} />
      </AnimatedContent>

      {/* Your Why */}
      {hasWhy && (
        <AnimatedContent
          index={1}
          reduceMotion={reduceMotion}
          visible={visible}
        >
          <View className='mt-4'>
            <WhySection why={habit.why!} />
          </View>
        </AnimatedContent>
      )}

      {/* WOOP IF-THEN Reminder */}
      {hasWOOP && (
        <AnimatedContent
          index={hasWhy ? 2 : 1}
          reduceMotion={reduceMotion}
          visible={visible}
        >
          <View className='mt-4'>
            <WOOPReminder
              obstacle={habit.woopObstacle!}
              plan={habit.woopPlan!}
            />
          </View>
        </AnimatedContent>
      )}

      {/* Cue Reminder */}
      {hasCue && (
        <AnimatedContent
          index={(hasWhy ? 1 : 0) + (hasWOOP ? 1 : 0) + 1}
          reduceMotion={reduceMotion}
          visible={visible}
        >
          <View className='mt-4'>
            <CueReminder
              afterBehavior={habit.cueAfterBehavior}
              location={habit.cueLocation}
              time={habit.cueTime}
            />
          </View>
        </AnimatedContent>
      )}
    </ScrollView>
  );
}

import React, { useEffect } from 'react';
import { View, Text } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withDelay,
  withSequence,
} from 'react-native-reanimated';
import { Flame, Target } from 'lucide-react-native';
import type { ActivationHabitData } from './types';
import { SPRING_BOUNCY, SPRING_BUTTON } from './constants';

interface HabitCardProps {
  habit: ActivationHabitData;
  reduceMotion?: boolean;
}

/**
 * HabitCard - Displays habit info with streak at top of modal
 */
export function HabitCard({ habit, reduceMotion }: HabitCardProps) {
  const streakScale = useSharedValue(1);

  useEffect(() => {
    if (reduceMotion || !habit.currentStreak) return;

    // Subtle pulse on streak number
    streakScale.value = withDelay(
      400,
      withSequence(withSpring(1.1, SPRING_BOUNCY), withSpring(1, SPRING_BUTTON))
    );
  }, [reduceMotion, habit.currentStreak, streakScale]);

  const streakAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: streakScale.value }],
  }));

  return (
    <View className='flex-row items-center rounded-2xl bg-white p-4 shadow-sm shadow-stone-200/50'>
      {/* Habit Icon */}
      <View className='mr-4 h-14 w-14 items-center justify-center rounded-xl bg-amber-100'>
        <Text className='text-2xl'>{habit.icon || '✨'}</Text>
      </View>

      {/* Habit Info */}
      <View className='flex-1'>
        <Text className='text-lg font-semibold text-stone-800'>
          {habit.name}
        </Text>
        <View className='mt-1 flex-row items-center gap-3'>
          {/* Streak */}
          {habit.currentStreak !== undefined && habit.currentStreak > 0 && (
            <Animated.View
              className='flex-row items-center gap-1'
              style={streakAnimatedStyle}
            >
              <Flame className='text-orange-500' size={14} />
              <Text className='text-sm font-medium text-stone-600'>
                {habit.currentStreak} day streak
              </Text>
            </Animated.View>
          )}
          {/* Completions */}
          {habit.totalCompletions !== undefined &&
            habit.totalCompletions > 0 && (
              <View className='flex-row items-center gap-1'>
                <Target className='text-emerald-500' size={14} />
                <Text className='text-sm text-stone-500'>
                  {habit.totalCompletions} total
                </Text>
              </View>
            )}
        </View>
      </View>
    </View>
  );
}

