function FeatureCheck({
  icon: Icon,
  title,
  subtitle,
  isHighlighted,
  index,
  reduceMotion,
}: {
  icon: React.ComponentType<any>;
  title: string;
  subtitle: string;
  isHighlighted: boolean;
  index: number;
  reduceMotion: boolean;
}) {
  const opacity = useSharedValue(0);
  const translateX = useSharedValue(-20);

  React.useEffect(() => {
    if (reduceMotion) {
      opacity.value = 1;
      translateX.value = 0;
      return;
