/**
 * Main PremiumFeatureLock component
 */
export function PremiumFeatureLock({
  feature,
  onUpgrade,
  onLockViewed,
  variant = 'inline',
  showScience = false,
  reduceMotion = false,
  className,
  testID,
}: PremiumFeatureLockProps) {
  // Track when lock is viewed (for analytics)
  React.useEffect(() => {
    if (onLockViewed) {
      onLockViewed(feature);
    }
  }, [feature, onLockViewed]);

  if (variant === 'inline') {
    return (
      <View className={className}>
        <InlineLock
          reduceMotion={reduceMotion}
          testID={testID}
          onUpgrade={onUpgrade}
        />
      </View>
    );
  }

  if (variant === 'overlay') {
    return (
      <OverlayLock
        feature={feature}
        reduceMotion={reduceMotion}
        showScience={showScience}
        testID={testID}
        onUpgrade={onUpgrade}
      />
    );
  }

  return (
    <View className={className}>
      <CardLock
        feature={feature}
        reduceMotion={reduceMotion}
        showScience={showScience}
        testID={testID}
        onUpgrade={onUpgrade}
      />
    </View>
  );
}

/**
 * Feature limit indicator - shows free tier usage
 */
export function FeatureLimitBadge({
  current,
  limit,
  isPremium,
  onUpgrade,
  reduceMotion = false,
  testID,
}: {
  current: number;
  limit: number;
  isPremium: boolean;
  onUpgrade: () => void;
  reduceMotion?: boolean;
  testID?: string;
}) {
  const { triggerLightImpact } = useHapticFeedback({});
  const isAtLimit = !isPremium && current >= limit;

  const handlePress = useCallback(() => {
    if (!isPremium) {
      triggerLightImpact();
      onUpgrade();
    }
  }, [isPremium, onUpgrade, triggerLightImpact]);

  if (isPremium) {
    return null;
  }

  return (
    <Pressable
      accessibilityHint={isAtLimit ? 'Tap to upgrade for unlimited' : undefined}
      accessibilityLabel={`${current} of ${limit} free used`}
      accessibilityRole={isAtLimit ? 'button' : 'text'}
      disabled={!isAtLimit}
      testID={testID}
      onPress={handlePress}
    >
      <View
        className={`flex-row items-center gap-1 rounded-full px-2 py-0.5 ${
          isAtLimit ? 'bg-amber-100' : 'bg-stone-100'
        }`}
      >
        <Text
          className={`text-xs font-medium ${
            isAtLimit ? 'text-amber-700' : 'text-stone-600'
          }`}
        >
          {current}/{limit} Free
        </Text>
        {isAtLimit && <ChevronRight className='text-amber-600' size={12} />}
      </View>
    </Pressable>
  );
}

