/**
 * FailureViz Component
 * Dedicated failure visualization for Rescue Mode
 *
 * Part of the Motivation System - Rescue phase
 * Story T8.4: Create `FailureViz` component (always shows failure)
 *
 * Scientific Basis:
 * - Andrew Huberman (Stanford) Dual Visualization Protocol
 * - Key insight: In Rescue Mode, ALWAYS show failure (user is struggling)
 * - Loss aversion (Kahneman & Tversky, Nobel Prize): Losses hurt 2x more
 *
 * Differences from ContextAwareViz:
 * - Always shows failure visualization (no motivation check)
 * - More dramatic, urgent styling
 * - Includes streak loss preview
 * - Designed for emotional impact
 */

import React, { useEffect } from 'react';
import { View, Text } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withSequence,
  withTiming,
  withDelay,
} from 'react-native-reanimated';
import { AlertTriangle, Brain, Heart, User, Flame } from 'lucide-react-native';
import { clsx } from 'clsx';

// Animation spring configs
const SPRING_BOUNCY = { damping: 8, stiffness: 300 };
const SPRING_GENTLE = { damping: 28, mass: 1, stiffness: 180 };

/** Failure visualization data */
export interface FailureVisualizationData {
  /** How body feels when failing */
  failureBody?: string;
  /** How mind feels when failing */
  failureMind?: string;
  /** Emotions when failing */
  failureEmotion?: string;
}

export interface FailureVizProps {
  /** Visualization data from the habit */
  visualization: FailureVisualizationData | undefined;
  /** Current streak count (for streak loss preview) */
  streakCount?: number;
  /** Whether to skip animations for accessibility */
  reduceMotion?: boolean;
  /** Optional className for container styling */
  className?: string;
}

/**
 * VizField - Individual visualization field with icon
 */
function VizField({
  label,
  value,
  icon,
  index,
  reduceMotion,
}: {
  label: string;
  value: string;
  icon: React.ReactNode;
  index: number;
  reduceMotion: boolean;
}) {
  const translateX = useSharedValue(reduceMotion ? 0 : -10);
  const opacity = useSharedValue(reduceMotion ? 1 : 0);

  useEffect(() => {
    if (reduceMotion) {
      translateX.value = 0;
      opacity.value = 1;
      return;
    }

    const delay = index * 100 + 200;

    translateX.value = withDelay(delay, withSpring(0, SPRING_GENTLE));
    opacity.value = withDelay(delay, withTiming(1, { duration: 300 }));
  }, [reduceMotion, index, translateX, opacity]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ translateX: translateX.value }],
  }));

  return (
    <Animated.View
      className='flex-row items-start gap-3 py-2'
      style={animatedStyle}
    >
      <View className='mt-0.5 h-8 w-8 items-center justify-center rounded-lg bg-rose-100'>
        {icon}
      </View>
      <View className='flex-1'>
        <Text className='text-xs font-medium text-rose-600'>{label}</Text>
        <Text className='text-sm leading-5 text-rose-800'>{value}</Text>
      </View>
    </Animated.View>
  );
}

/**
 * StreakLossPreview - Shows what user will lose if they skip
 */
function StreakLossPreview({
  streakCount,
  reduceMotion,
}: {
  streakCount: number;
  reduceMotion: boolean;
}) {
  const scale = useSharedValue(1);

  useEffect(() => {
    if (reduceMotion) return;

    // Shake animation to emphasize loss
    scale.value = withDelay(
      600,
      withSequence(
        withSpring(1.05, SPRING_BOUNCY),
        withSpring(1, SPRING_BOUNCY)
      )
    );
  }, [reduceMotion, scale]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  return (
    <Animated.View
      className='mt-3 flex-row items-center gap-2 rounded-xl bg-rose-500/10 p-3'
      style={animatedStyle}
    >
      <Flame className='text-rose-500' size={18} />
      <Text className='flex-1 text-sm font-medium text-rose-700'>
        {streakCount} days gone. Starting over from zero.
      </Text>
    </Animated.View>
  );
}

/**
 * EmptyVizState - Shown when no visualization data is available
 */
function EmptyVizState() {
  return (
    <View className='items-center justify-center py-6'>
      <View className='mb-3 h-12 w-12 items-center justify-center rounded-full bg-rose-100'>
        <AlertTriangle className='text-rose-500' size={24} />
      </View>
      <Text className='mb-2 text-center text-sm font-medium text-stone-600'>
        Imagine how you'll feel if you skip
      </Text>
      <Text className='text-center text-xs text-stone-500'>
        Add failure visualization in the Motivation tab
      </Text>
    </View>
  );
}

/**
 * FailureViz - Main component
 *
 * Always shows failure visualization for Rescue Mode.
 * Uses rose/red color scheme to create urgency and
 * leverage loss aversion psychology.
 */
export function FailureViz({
  visualization,
  streakCount,
  reduceMotion = false,
  className,
}: FailureVizProps) {
  // Animation values
  const scale = useSharedValue(reduceMotion ? 1 : 0.95);
  const opacity = useSharedValue(reduceMotion ? 1 : 0);

  useEffect(() => {
    if (reduceMotion) {
      scale.value = 1;
      opacity.value = 1;
      return;
    }

    // Entrance animation
    scale.value = withSpring(1, SPRING_GENTLE);
    opacity.value = withTiming(1, { duration: 300 });
  }, [reduceMotion, scale, opacity]);

  const containerAnimatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ scale: scale.value }],
  }));

  const hasAnyField =
    visualization?.failureBody ||
    visualization?.failureMind ||
    visualization?.failureEmotion;

  return (
    <Animated.View
      className={clsx(
        'rounded-2xl border-l-4 border-l-rose-400 bg-rose-50/80 p-4',
        className
      )}
      style={containerAnimatedStyle}
    >
      {/* Header */}
      <View className='mb-4 flex-row items-center gap-3'>
        <View className='h-10 w-10 items-center justify-center rounded-xl bg-rose-100'>
          <AlertTriangle className='text-rose-600' size={20} />
        </View>
        <View className='flex-1'>
          <Text className='text-base font-semibold text-rose-800'>
            If You Skip Today...
          </Text>
          <Text className='text-xs text-rose-500'>
            Feel the weight of not doing this
          </Text>
        </View>
      </View>

      {/* Visualization content */}
      {hasAnyField ? (
        <View className='gap-1'>
          {visualization?.failureBody && (
            <VizField
              icon={<User className='text-rose-500' size={16} />}
              index={0}
              label='Body'
              reduceMotion={reduceMotion}
              value={visualization.failureBody}
            />
          )}
          {visualization?.failureMind && (
            <VizField
              icon={<Brain className='text-rose-500' size={16} />}
              index={1}
              label='Mind'
              reduceMotion={reduceMotion}
              value={visualization.failureMind}
            />
          )}
          {visualization?.failureEmotion && (
            <VizField
              icon={<Heart className='text-rose-500' size={16} />}
              index={2}
              label='Emotion'
              reduceMotion={reduceMotion}
              value={visualization.failureEmotion}
            />
          )}
        </View>
      ) : (
        <EmptyVizState />
      )}

      {/* Streak loss preview */}
      {streakCount !== undefined && streakCount > 0 && (
        <StreakLossPreview
          reduceMotion={reduceMotion}
          streakCount={streakCount}
        />
      )}

      {/* Science tip */}
      <View className='mt-3 rounded-lg bg-rose-100/50 px-3 py-2'>
        <Text className='text-center text-xs text-rose-600'>
          💡 Loss aversion: This feeling moves you 2x more effectively than
          rewards
        </Text>
      </View>
    </Animated.View>
  );
}

export default FailureViz;

/**
 * PreviousStreakVoiceNotes Component
 * Displays voice notes from the user's best streak period during rescue mode
 *
 * Scientific Basis:
 * - Voice has 40% higher emotional recall than text (cognitive psychology)
 * - Reconnecting with "peak motivation self" during struggle creates powerful anchor
 * - Hearing your own voice from when you were most committed reinforces identity
 *
 * Part of the Motivation System - Rescue phase
 * Story: Streak Recovery with Voice Note from past self
 */

import React, { useCallback, useEffect, useState } from 'react';
import { View, Text, Pressable } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';
import {
  Flame,
  ChevronDown,
  ChevronUp,
  Sparkles,
  Mic,
} from 'lucide-react-native';
import { clsx } from 'clsx';
import * as Haptics from 'expo-haptics';

import { VoiceNotePlaybackUI } from '../Workshop/VoiceNotePlaybackUI';

// Animation spring configs
const SPRING_BUTTON = { damping: 15, stiffness: 300 };

/**
 * Voice note with streak context data
 */
export interface StreakVoiceNoteData {
  /** Voice note ID */
  id: string;
  /** Audio URI for playback */
  audioUrl: string;
  /** Duration in seconds */
  duration: number;
  /** Optional label */
  label?: string;
  /** When the note was created */
  createdAt: number;
  /** Which day of the streak this was recorded (1-indexed) */
  streakAtRecording: number;
  /** How many days ago this was recorded */
  daysAgo: number;
}

export interface PreviousStreakVoiceNotesProps {
  /** Voice notes from the best streak period */
  voiceNotes: StreakVoiceNoteData[];
  /** The user's best streak (for context display) */
  bestStreak: number;
  /** Called when any voice note playback starts */
  onPlayStart?: () => void;
  /** Called when any voice note playback finishes */
  onPlayFinish?: () => void;
  /** Whether to skip animations for accessibility */
  reduceMotion?: boolean;
}

/**
 * Individual voice note card with streak context
 */
function StreakVoiceNoteCard({
  voiceNote,
  bestStreak,
  isExpanded,
  onToggleExpand,
  onPlayStart,
  onPlayFinish,
  reduceMotion = false,
}: {
  voiceNote: StreakVoiceNoteData;
  bestStreak: number;
  isExpanded: boolean;
  onToggleExpand: () => void;
  onPlayStart?: () => void;
  onPlayFinish?: () => void;
  reduceMotion?: boolean;
}) {
  const scale = useSharedValue(1);

  const handlePressIn = useCallback(() => {
    scale.value = withSpring(0.98, SPRING_BUTTON);
  }, [scale]);

  const handlePressOut = useCallback(() => {
    scale.value = withSpring(1, SPRING_BUTTON);
  }, [scale]);

  const handlePress = useCallback(() => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onToggleExpand();
  }, [onToggleExpand]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  // Format days ago text
  const daysAgoText =
    voiceNote.daysAgo === 0
      ? 'Today'
      : voiceNote.daysAgo === 1
        ? 'Yesterday'
        : `${voiceNote.daysAgo} days ago`;

  return (
    <Animated.View
      className='mb-3 overflow-hidden rounded-xl border border-amber-200 bg-gradient-to-br from-amber-50 to-orange-50'
      style={animatedStyle}
    >
      {/* Header - always visible, expandable */}
      <Pressable
        accessibilityLabel={`Voice note from day ${voiceNote.streakAtRecording} of ${bestStreak} day streak, recorded ${daysAgoText}. ${isExpanded ? 'Collapse' : 'Expand'} to play.`}
        accessibilityRole='button'
        className='flex-row items-center justify-between p-3'
        onPress={handlePress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
      >
        <View className='flex-1 flex-row items-center gap-3'>
          {/* Mic icon with streak badge */}
          <View className='relative'>
            <View className='h-10 w-10 items-center justify-center rounded-full bg-amber-100'>
              <Mic className='text-amber-600' size={18} />
            </View>
            {/* Streak day badge */}
            <View className='absolute -bottom-1 -right-1 flex-row items-center gap-0.5 rounded-full bg-orange-500 px-1.5 py-0.5'>
              <Flame className='text-white' size={10} />
              <Text className='text-[10px] font-bold text-white'>
                {voiceNote.streakAtRecording}
              </Text>
            </View>
          </View>

          {/* Text content */}
          <View className='flex-1'>
            <Text className='text-sm font-semibold text-amber-800'>
              Day {voiceNote.streakAtRecording} of your {bestStreak}-day streak
            </Text>
            <Text className='text-xs text-amber-600'>{daysAgoText}</Text>
          </View>
        </View>

        {/* Expand/collapse chevron */}
        <View className='ml-2 h-8 w-8 items-center justify-center rounded-full bg-amber-100'>
          {isExpanded ? (
            <ChevronUp className='text-amber-600' size={16} />
          ) : (
            <ChevronDown className='text-amber-600' size={16} />
          )}
        </View>
      </Pressable>

      {/* Expanded content - playback UI */}
      {isExpanded && (
        <View className='border-t border-amber-200 p-3'>
          <VoiceNotePlaybackUI
            audioUri={voiceNote.audioUrl}
            initialDuration={voiceNote.duration}
            label={voiceNote.label}
            reduceMotion={reduceMotion}
            showSpeedControl={false}
            onPlayFinish={onPlayFinish}
            onPlayStart={onPlayStart}
          />
          {voiceNote.label && (
            <Text className='mt-2 text-xs italic text-amber-600'>
              "{voiceNote.label}"
            </Text>
          )}
        </View>
      )}
    </Animated.View>
  );
}

/**
 * PreviousStreakVoiceNotes - Shows voice notes from the user's best streak
 *
 * Displayed in Rescue Mode to help users reconnect with their most committed self.
 * Each note shows the day of the streak it was recorded on, creating powerful
 * temporal context ("You recorded this on Day 14 of your 21-day streak").
 */
export function PreviousStreakVoiceNotes({
  voiceNotes,
  bestStreak,
  onPlayStart,
  onPlayFinish,
  reduceMotion = false,
}: PreviousStreakVoiceNotesProps) {
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Auto-expand the first note on mount (the one from highest streak day)
  useEffect(() => {
    if (voiceNotes.length > 0 && expandedId === null) {
      setExpandedId(voiceNotes[0].id);
    }
  }, [voiceNotes, expandedId]);

  const handleToggleExpand = useCallback(
    (id: string) => {
      if (expandedId === id) {
        setExpandedId(null);
      } else {
        setExpandedId(id);
        Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      }
    },
    [expandedId]
  );

  if (voiceNotes.length === 0) {
    return null;
  }

  return (
    <View className='rounded-2xl border-l-4 border-l-amber-400 bg-white p-4'>
      {/* Section header */}
      <View className='mb-3 flex-row items-center gap-2'>
        <View className='h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-amber-100 to-orange-100'>
          <Flame className='text-amber-600' size={20} />
        </View>
        <View className='flex-1'>
          <Text className='text-lg font-bold text-amber-800'>
            Your Best Streak Self
          </Text>
