} from 'react-native-reanimated';
import { Check } from 'lucide-react-native';
import * as Haptics from 'expo-haptics';

import { SPRING_BUTTON } from '../constants';
import type { DoneButtonProps } from '../types';

export function DoneButton({ onPress, reduceMotion = false }: DoneButtonProps) {
  const scale = useSharedValue(1);
  const glowOpacity = useSharedValue(0.5);

  // Pulsing glow effect
  useEffect(() => {
    if (reduceMotion) {
      glowOpacity.value = 0.5;
      return;
    }

    const pulseGlow = () => {
      glowOpacity.value = withTiming(0.8, { duration: 800 }, (finished) => {
        if (finished) {
          glowOpacity.value = withTiming(
            0.5,
            { duration: 800 },
            (finished2) => {
              if (finished2) {
                runOnJS(pulseGlow)();
              }
            }
          );
        }
      });
    };

    pulseGlow();
  }, [reduceMotion, glowOpacity]);

  const handlePressIn = useCallback(() => {
    scale.value = withSpring(0.96, SPRING_BUTTON);
  }, [scale]);

  const handlePressOut = useCallback(() => {
    scale.value = withSpring(1, SPRING_BUTTON);
  }, [scale]);

  const handlePress = useCallback(() => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    onPress();
  }, [onPress]);

  const buttonAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  const glowAnimatedStyle = useAnimatedStyle(() => ({
    opacity: glowOpacity.value,
  }));

  return (
    <Animated.View className='relative' style={buttonAnimatedStyle}>
      {/* Glow effect - emerald for celebration */}
      <Animated.View
        className='absolute -inset-2 rounded-2xl bg-emerald-400/40 blur-xl'
        style={glowAnimatedStyle}
      />
      <Pressable
        accessibilityHint='Close celebration and continue'
        accessibilityLabel='Done'
        accessibilityRole='button'
        className='flex-row items-center justify-center gap-3 rounded-xl bg-emerald-500 px-8 py-4'
        onPress={handlePress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
      >
        <Check className='text-white' size={24} />
        <Text className='text-lg font-bold text-white'>Done</Text>
      </Pressable>
    </Animated.View>
  );
}

/**
 * ConfettiParticle - Individual confetti particle with physics-based animation
 */

import React, { useEffect } from 'react';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withTiming,
  interpolate,
  Extrapolation,
} from 'react-native-reanimated';

import type { ConfettiParticleProps } from '../types';

export function ConfettiParticle({
  color,
  delay,
  angle,
  reduceMotion,
}: ConfettiParticleProps) {
  const progress = useSharedValue(0);
  // Round all values to avoid "Loss of precision during arithmetic conversion" error
  const distance = Math.round(100 + Math.random() * 60);
  const rotation = Math.round(Math.random() * 720);
  const size = Math.round(6 + Math.random() * 6);

  useEffect(() => {
    if (reduceMotion) return;

    progress.value = withDelay(delay, withTiming(1, { duration: 1200 }));
  }, [delay, reduceMotion, progress]);

  // Round to avoid precision errors in Reanimated's native layer
  const translateX = Math.round(Math.cos(angle) * distance);
  const translateY = Math.round(Math.sin(angle) * distance) - 50; // Bias upward

  const animatedStyle = useAnimatedStyle(() => {
    const p = progress.value;
    const currentX = interpolate(
      p,
      [0, 1],
      [0, translateX],
      Extrapolation.CLAMP
    );
    const currentY = interpolate(
      p,
      [0, 0.3, 1],
      [0, translateY * 0.3, translateY + 100],
      Extrapolation.CLAMP
    );
    const scale = interpolate(
      p,
      [0, 0.2, 0.8, 1],
      [0, 1.2, 1, 0.3],
      Extrapolation.CLAMP
    );
    const opacity = interpolate(
      p,
      [0, 0.2, 0.8, 1],
      [0, 1, 1, 0],
      Extrapolation.CLAMP
    );
    const rotate = interpolate(p, [0, 1], [0, rotation], Extrapolation.CLAMP);

    return {
      opacity,
      transform: [
        { translateX: currentX },
        { translateY: currentY },
        { scale },
        { rotate: `${rotate}deg` },
      ],
    };
  });

  if (reduceMotion) return null;

  return (
    <Animated.View
      style={[
        {
          backgroundColor: color,
          borderRadius: size / 2,
          height: size,
          position: 'absolute',
          width: size,
        },
        animatedStyle,
      ]}
    />
  );
}

/**
 * useCelebrationScreen - State management hook for CelebrationScreen
 */

import { useCallback, useEffect, useState } from 'react';
import type { EmojiType } from '../QuickReflection';
import type { CelebrationHabitData } from './types';

interface UseCelebrationScreenParams {
  habit: CelebrationHabitData | null;
  selectedEmoji?: EmojiType;
  reflectionNote?: string;
  onEmojiSelect?: (emoji: EmojiType) => void;
  onNoteChange?: (note: string) => void;
  onDone?: () => void;
  onClose: () => void;
  onRecordVoice?: () => void;
  onWriteLetter?: () => void;
}

export function useCelebrationScreen({
  habit,
  selectedEmoji,
  reflectionNote = '',
  onEmojiSelect,
  onNoteChange,
  onDone,
  onClose,
  onRecordVoice,
  onWriteLetter,
}: UseCelebrationScreenParams) {
  const [localEmoji, setLocalEmoji] = useState<EmojiType | undefined>(
    selectedEmoji
  );
  const [localNote, setLocalNote] = useState(reflectionNote);

  // Sync with props
  useEffect(() => {
    setLocalEmoji(selectedEmoji);
  }, [selectedEmoji]);

  useEffect(() => {
    setLocalNote(reflectionNote);
  }, [reflectionNote]);

  const handleEmojiSelect = useCallback(
    (emoji: EmojiType) => {
      setLocalEmoji(emoji);
      onEmojiSelect?.(emoji);
    },
    [onEmojiSelect]
  );

  const handleNoteChange = useCallback(
    (note: string) => {
      setLocalNote(note);
      onNoteChange?.(note);
    },
    [onNoteChange]
  );

  const handleDone = useCallback(() => {
    onDone?.();
    onClose();
  }, [onDone, onClose]);

  const handleRecordVoice = useCallback(() => {
    onRecordVoice?.();
  }, [onRecordVoice]);

  const handleWriteLetter = useCallback(() => {
    onWriteLetter?.();
  }, [onWriteLetter]);

  // Computed values
  const hasStreak = (habit?.currentStreak ?? 0) > 0;
  const hasStats =
    habit?.completionRate !== undefined ||
    habit?.bestStreak !== undefined ||
    habit?.totalCompletions !== undefined;

  return {
    handleDone,
    handleEmojiSelect,
    handleNoteChange,
    handleRecordVoice,
    handleWriteLetter,
    hasStats,
    hasStreak,
    localEmoji,
    localNote,
  };
}

