          <AffirmationItem
            key={affirmation.id}
            affirmation={affirmation}
            isPremium={isPremium}
            onDelete={() => onDelete(affirmation.id)}
            onEdit={() => onEdit(affirmation)}
            onSchedule={onSchedule ? () => onSchedule(affirmation) : undefined}
          />
        ))}
        {remainingCount > 0 && (
          <Text className='mt-1 text-center text-xs text-stone-400'>
            +{remainingCount} more
