  return (
    <Pressable
      accessibilityLabel={
        locked
          ? `Locked letter: ${letter.title || 'Letter'}, unlocks in ${daysUntilUnlock} days`
          : `${isNew ? 'Unread letter' : 'Letter'}: ${letter.title || 'Letter'}`
      }
      accessibilityRole='button'
