        'flex-row items-center gap-3 rounded-xl p-3',
        locked ? 'bg-stone-50' : isNew ? 'bg-violet-50' : 'bg-stone-50'
      )}
      onPress={onPress}
    >
      <View
        className={clsx(
          'h-10 w-10 items-center justify-center rounded-full',
          locked ? 'bg-stone-200' : isNew ? 'bg-violet-500' : 'bg-violet-100'
