      <KeyboardAvoidingView
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
        className='flex-1 bg-black'
      >
        <ViewerHeader
          isDeleting={viewer.isDeleting}
          onClose={onClose}
          onDelete={viewer.handleDelete}
          onToggleEdit={viewer.toggleEdit}
        />
        <View className='flex-1 items-center justify-center'>
          {image.imageUrl && (
            <Image
              accessibilityIgnoresInvertColors
              resizeMode='contain'
              source={{ uri: image.imageUrl }}
              style={{ height: SCREEN_WIDTH, width: SCREEN_WIDTH }}
            />
          )}
        </View>
        <CaptionArea
          captionText={viewer.captionText}
          image={image}
          isEditingCaption={viewer.isEditingCaption}
          isSaving={viewer.isSaving}
          onCancel={viewer.handleCancel}
          onChangeText={viewer.setCaptionText}
          onSave={viewer.handleSaveCaption}
        />
      </KeyboardAvoidingView>
    </Modal>
  );
}

/**
 * SectionCard Component - Consistent card styling with press animation
 */

import React, { useCallback } from 'react';
import { View, Pressable } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  interpolate,
} from 'react-native-reanimated';
import { clsx } from 'clsx';
import * as Haptics from 'expo-haptics';
import { SPRING_BUTTON } from '../../../animations';

interface SectionCardProps {
  children: React.ReactNode;
  className?: string;
  onPress?: () => void;
  accessibilityLabel?: string;
  disabled?: boolean;
}

const cardClass = 'rounded-xl border border-stone-200 bg-white p-3';
const staticShadow = {
  elevation: 2,
  shadowColor: '#000',
  shadowOffset: { height: 2, width: 0 },
  shadowOpacity: 0.05,
  shadowRadius: 8,
};

export function SectionCard({
  children,
  className,
  onPress,
  accessibilityLabel,
  disabled,
}: SectionCardProps) {
  const scale = useSharedValue(1);
  const shadowOpacity = useSharedValue(0.05);
  const elevation = useSharedValue(2);

  const animatedStyle = useAnimatedStyle(() => ({
    elevation: elevation.value,
    shadowOffset: {
      height: interpolate(elevation.value, [1, 2], [1, 2]),
      width: 0,
    },
    shadowOpacity: shadowOpacity.value,
    shadowRadius: interpolate(elevation.value, [1, 2], [4, 8]),
    transform: [{ scale: scale.value }],
  }));

  const handlePressIn = useCallback(() => {
    'worklet';
    scale.value = withSpring(0.98, SPRING_BUTTON);
    shadowOpacity.value = withSpring(0.02, SPRING_BUTTON);
    elevation.value = withSpring(1, SPRING_BUTTON);
  }, [scale, shadowOpacity, elevation]);

  const handlePressOut = useCallback(() => {
    'worklet';
    scale.value = withSpring(1, SPRING_BUTTON);
    shadowOpacity.value = withSpring(0.05, SPRING_BUTTON);
    elevation.value = withSpring(2, SPRING_BUTTON);
  }, [scale, shadowOpacity, elevation]);

  const handlePress = useCallback(() => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onPress?.();
  }, [onPress]);

  if (onPress) {
    return (
      <Animated.View style={[animatedStyle, { shadowColor: '#000' }]}>
        <Pressable
          accessibilityLabel={accessibilityLabel}
          accessibilityRole='button'
          accessibilityState={{ disabled }}
          className={clsx(cardClass, className)}
          disabled={disabled}
          onPress={handlePress}
          onPressIn={handlePressIn}
          onPressOut={handlePressOut}
        >
          {children}
        </Pressable>
      </Animated.View>
    );
  }

  return (
    <View className={clsx(cardClass, className)} style={staticShadow}>
      {children}
    </View>
  );
}

