/**
 * YourWhySection Component
 * Displays and allows editing of the user's "why" statement for a habit
 *
 * Part of the Motivation System Workshop tab
 * Story T1.2-T1.5: Create YourWhySection component with empty/filled states
 *
 * Scientific Basis:
 * - Self-Determination Theory (Deci & Ryan): Intrinsic motivation from personal meaning
 * - Noom clinical studies: Users with defined purpose show 3x higher retention
 */

import React, { useCallback, useEffect } from 'react';
import { View, Text, Pressable } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
  withSequence,
  interpolate,
  runOnJS,
} from 'react-native-reanimated';
import { Plus, Check, Pencil } from 'lucide-react-native';
import { clsx } from 'clsx';
import * as Haptics from 'expo-haptics';
import {
  PulsingIcon,
  CompletionCheckmark,
  SPRING_BUTTON,
  SPRING_GENTLE,
  STAGGER_DELAY,
} from '../../animations';

export interface YourWhySectionProps {
  /** The habit's "why" statement (undefined if not set) */
  why: string | undefined;
  /** Callback when user taps to edit/add their why */
  onPress: () => void;
  /** Whether to run entrance animations (first tab visit only) */
  shouldAnimate?: boolean;
  /** Whether to skip animations for accessibility */
  reduceMotion?: boolean;
  /** Section index for staggered animation timing */
  sectionIndex?: number;
}

/**
 * SectionCard Component for consistent styling with press animation
 * Matches mockup: app-card with border, 16px radius, subtle shadow
 */
function SectionCard({
  children,
  className,
  onPress,
  accessibilityLabel,
}: {
  children: React.ReactNode;
  className?: string;
  onPress?: () => void;
  accessibilityLabel?: string;
}) {
  const scale = useSharedValue(1);
  const shadowOpacity = useSharedValue(0.05);
  const elevation = useSharedValue(2);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
    shadowOpacity: shadowOpacity.value,
    shadowRadius: interpolate(elevation.value, [1, 2], [4, 8]),
    shadowOffset: {
      width: 0,
      height: interpolate(elevation.value, [1, 2], [1, 2]),
    },
    elevation: elevation.value,
  }));

  const handlePressIn = useCallback(() => {
    'worklet';
    scale.value = withSpring(0.98, SPRING_BUTTON);
    shadowOpacity.value = withSpring(0.02, SPRING_BUTTON);
    elevation.value = withSpring(1, SPRING_BUTTON);
  }, [scale, shadowOpacity, elevation]);

  const handlePressOut = useCallback(() => {
    'worklet';
    scale.value = withSpring(1, SPRING_BUTTON);
    shadowOpacity.value = withSpring(0.05, SPRING_BUTTON);
    elevation.value = withSpring(2, SPRING_BUTTON);
  }, [scale, shadowOpacity, elevation]);

  const handlePress = useCallback(() => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onPress?.();
  }, [onPress]);

  if (onPress) {
    return (
      <Animated.View
        style={[
          animatedStyle,
          { shadowColor: '#000' },
        ]}
      >
        <Pressable
          accessibilityLabel={accessibilityLabel}
          accessibilityRole="button"
          className={clsx('rounded-xl border border-stone-200 bg-white p-3', className)}
          onPress={handlePress}
          onPressIn={handlePressIn}
          onPressOut={handlePressOut}
        >
          {children}
        </Pressable>
      </Animated.View>
    );
  }

  return (
    <View
      className={clsx(
        'rounded-xl border border-stone-200 bg-white p-3',
        className
      )}
      style={{
        shadowColor: '#000',
        shadowOffset: { width: 0, height: 2 },
        shadowOpacity: 0.05,
        shadowRadius: 8,
        elevation: 2,
      }}
    >
      {children}
    </View>
  );
}

/**
 * AnimatedSection Component for staggered entrance animations
 */
function AnimatedSection({
  children,
  index,
  shouldAnimate,
  reduceMotion = false,
}: {
  children: React.ReactNode;
  index: number;
  shouldAnimate: boolean;
  reduceMotion?: boolean;
}) {
  const INITIAL_TRANSLATE_Y = 24;

  const translateY = useSharedValue(
    shouldAnimate && !reduceMotion ? INITIAL_TRANSLATE_Y : 0
  );
  const opacity = useSharedValue(shouldAnimate && !reduceMotion ? 0 : 1);

  useEffect(() => {
    if (!shouldAnimate || reduceMotion) {
      translateY.value = 0;
      opacity.value = 1;
      return;
    }

    const delay = index * STAGGER_DELAY;

    const timeout = setTimeout(() => {
      translateY.value = withSpring(0, SPRING_GENTLE);
      opacity.value = withTiming(1, { duration: 300 });
    }, delay);

    return () => clearTimeout(timeout);
  }, [shouldAnimate, reduceMotion, index, translateY, opacity]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ translateY: translateY.value }],
    opacity: opacity.value,
  }));

  return <Animated.View style={animatedStyle}>{children}</Animated.View>;
}

/**
 * YourWhySection - Main component
 *
 * Displays the user's "why" statement with:
 * - Empty state: Pulsing heart icon with "Set up" CTA
 * - Filled state: Rose-tinted card with the why statement in quotes
 * - Completion checkmark when filled
 * - Rose accent color (border-l-rose-400)
 */
export function YourWhySection({
  why,
  onPress,
  shouldAnimate = false,
  reduceMotion = false,
  sectionIndex = 0,
}: YourWhySectionProps) {
  const hasWhy = !!why;

  return (
    <AnimatedSection
      index={sectionIndex}
      shouldAnimate={shouldAnimate}
      reduceMotion={reduceMotion}
    >
      <SectionCard
        accessibilityLabel={hasWhy ? 'Edit your why' : 'Add your why'}
        onPress={onPress}
        className="border-l-4 border-l-rose-400"
      >
        {/* Header row: icon + title on left, action on right */}
        <View className="mb-1.5 flex-row items-center justify-between">
          <View className="flex-row items-center gap-2">
            <Text className="text-base">❤️</Text>
            <Text className="text-xs font-semibold text-rose-600">
              Your Why
            </Text>
          </View>
          {hasWhy ? (
            <Pencil className="text-stone-400" size={14} />
          ) : (
            <View className="flex-row items-center gap-1">
              <Plus className="text-rose-600" size={12} />
              <Text className="text-xs font-medium text-rose-600">Set up</Text>
            </View>
          )}
        </View>

        {/* Content */}
        {hasWhy ? (
          <Text className="text-sm italic leading-relaxed text-stone-700">
            "{why}"
          </Text>
        ) : (
          <Text className="text-sm text-stone-500">
            Define your deeper motivation
          </Text>
        )}

        {/* Completion checkmark */}
        <CompletionCheckmark
          isVisible={hasWhy}
          sectionIndex={sectionIndex}
          shouldAnimate={shouldAnimate}
          reduceMotion={reduceMotion}
        />
      </SectionCard>
    </AnimatedSection>
  );
}

export default YourWhySection;

/**
 * VisualizationGuide Component
 * Based on Andrew Huberman's research on effective goal visualization
 *
 * Key principles:
 * - Process visualization (visualize steps, not just outcomes)
 * - Obstacle/fear visualization (anticipate challenges)
 * - Contrast visualization (current vs desired state)
 * - Action-focused imagery (next small step)
 *
 * References:
 * - Huberman Lab Podcast: Goal Setting & Neural Mechanisms
 * - Research on mental contrasting (Oettingen, 2014)
 * - Implementation intentions (Gollwitzer, 1999)
 */

import React, { useState } from 'react';
import { View, Text, Pressable, ScrollView } from 'react-native';
import Animated, { FadeInDown, FadeIn, SlideInRight } from 'react-native-reanimated';
import {
  Brain,
  Eye,
  Target,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  Sparkles,
  ChevronDown,
  ChevronUp,
  Lightbulb,
  Zap,
  Mountain,
  ArrowRight,
} from 'lucide-react-native';
import * as Haptics from 'expo-haptics';

interface VisualizationTechnique {
  bad: {
    description: string;
    example: string;
    icon: React.ReactNode;
    title: string;
    why: string;
  };
  good: {
    description: string;
    example: string;
    icon: React.ReactNode;
    title: string;
    why: string;
  };
  id: string;
}

const VISUALIZATION_TECHNIQUES: VisualizationTechnique[] = [
  {
    bad: {
      description: 'Fantasizing only about the end goal (e.g., seeing yourself fit and successful)',
      example: '"I imagine myself having already achieved my goal, feeling amazing and confident."',
      icon: <XCircle className="text-rose-500" size={18} />,
      title: 'Outcome-Only Fantasy',
      why: 'Reduces dopamine drive and tricks brain into feeling satisfied before taking action',
    },
    good: {
      description: 'Visualize the specific steps and actions you need to take',
      example: '"I see myself putting on my running shoes, stepping outside, and taking the first steps."',
      icon: <CheckCircle2 className="text-emerald-500" size={18} />,
      title: 'Process Visualization',
      why: 'Activates motor planning regions and creates neural pathways for action',
    },
    id: 'process',
  },
  {
    bad: {
      description: 'Ignoring potential obstacles and assuming everything will go smoothly',
      example: '"I just stay positive and trust that it will all work out."',
      icon: <XCircle className="text-rose-500" size={18} />,
      title: 'Blind Optimism',
      why: 'Leaves you unprepared and more likely to quit when challenges arise',
    },
    good: {
      description: 'Anticipate obstacles and mentally rehearse overcoming them',
      example: '"When I feel tired after work, I will put on my workout clothes immediately before sitting down."',
      icon: <CheckCircle2 className="text-emerald-500" size={18} />,
      title: 'Obstacle Anticipation',
      why: 'Prepares your brain with pre-planned responses (implementation intentions)',
    },
    id: 'obstacles',
  },
  {
    bad: {
      description: 'Dwelling on past failures or current struggles without direction',
      example: '"I keep thinking about all the times I\'ve failed before."',
      icon: <XCircle className="text-rose-500" size={18} />,
      title: 'Ruminating on Failure',
      why: 'Creates learned helplessness and strengthens negative neural patterns',
    },
    good: {
      description: 'Compare current state with desired state to create productive tension',
      example: '"Right now I skip workouts, but I want to be someone who never misses. What\'s different?"',
      icon: <CheckCircle2 className="text-emerald-500" size={18} />,
      title: 'Mental Contrasting',
      why: 'Creates motivational gap that drives action without demotivating',
    },
    id: 'contrast',
  },
  {
    bad: {
      description: 'Focusing only on distant, abstract goals',
      example: '"Someday I\'ll be healthy and have great habits."',
      icon: <XCircle className="text-rose-500" size={18} />,
      title: 'Vague Future Focus',
      why: 'Too abstract for brain to create actionable plans',
    },
    good: {
      description: 'Focus on the very next action you need to take',
      example: '"Tomorrow at 7am, I will drink a glass of water before checking my phone."',
      icon: <CheckCircle2 className="text-emerald-500" size={18} />,
      title: 'Next Action Focus',
      why: 'Concrete, specific actions activate prefrontal cortex planning',
    },
    id: 'next-action',
  },
];

interface VisualizationCardProps {
  technique: VisualizationTechnique;
}

function VisualizationCard({ technique }: VisualizationCardProps) {
  const [expanded, setExpanded] = useState(false);

  const handleToggle = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    setExpanded(!expanded);
  };

  return (
    <Animated.View
      className="overflow-hidden rounded-2xl border border-stone-100 bg-white/90"
      entering={FadeInDown.delay(100).springify()}
    >
      {/* Header */}
      <Pressable
        accessibilityLabel={`${expanded ? 'Collapse' : 'Expand'} ${technique.good.title} technique`}
        accessibilityRole="button"
        className="flex-row items-center gap-3 p-4 active:bg-stone-50"
        onPress={handleToggle}
      >
        <View className="h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-violet-100 to-indigo-100">
          <Brain className="text-violet-600" size={20} />
        </View>
        <View className="flex-1">
          <Text className="text-base font-semibold text-stone-800">
            {technique.good.title}
          </Text>
          <Text className="text-xs text-stone-500">
            vs. {technique.bad.title}
          </Text>
        </View>
        {expanded ? (
          <ChevronUp className="text-stone-400" size={20} />
        ) : (
          <ChevronDown className="text-stone-400" size={20} />
        )}
      </Pressable>

      {/* Expanded Content */}
      {expanded && (
        <Animated.View
          className="border-t border-stone-100 bg-stone-50/50 px-4 pb-4"
          entering={FadeIn.duration(200)}
        >
          {/* Good Visualization */}
          <View className="mt-4">
            <View className="mb-2 flex-row items-center gap-2">
              {technique.good.icon}
              <Text className="text-sm font-semibold text-emerald-700">
                ✓ Effective Approach
              </Text>
            </View>
            <View className="rounded-xl bg-emerald-50 p-3">
              <Text className="text-sm leading-relaxed text-stone-700">
                {technique.good.description}
              </Text>
              <View className="mt-3 rounded-lg bg-white/80 p-2.5">
                <Text className="text-xs italic text-stone-600">
                  {technique.good.example}
                </Text>
              </View>
              <View className="mt-2 flex-row items-start gap-2">
                <Lightbulb className="mt-0.5 text-amber-500" size={14} />
                <Text className="flex-1 text-xs text-stone-600">
                  <Text className="font-medium">Why it works: </Text>
                  {technique.good.why}
                </Text>
              </View>
            </View>
          </View>

          {/* Bad Visualization */}
          <View className="mt-4">
            <View className="mb-2 flex-row items-center gap-2">
              {technique.bad.icon}
              <Text className="text-sm font-semibold text-rose-700">
                ✗ Common Mistake
              </Text>
            </View>
            <View className="rounded-xl bg-rose-50 p-3">
              <Text className="text-sm leading-relaxed text-stone-700">
                {technique.bad.description}
              </Text>
              <View className="mt-3 rounded-lg bg-white/80 p-2.5">
                <Text className="text-xs italic text-stone-600">
                  {technique.bad.example}
                </Text>
              </View>
              <View className="mt-2 flex-row items-start gap-2">
                <AlertTriangle className="mt-0.5 text-rose-500" size={14} />
                <Text className="flex-1 text-xs text-stone-600">
                  <Text className="font-medium">Why to avoid: </Text>
                  {technique.bad.why}
                </Text>
              </View>
            </View>
          </View>
        </Animated.View>
      )}
    </Animated.View>
  );
}

interface QuickTipProps {
  description: string;
  icon: React.ReactNode;
  title: string;
}

function QuickTip({ description, icon, title }: QuickTipProps) {
  return (
    <View className="flex-row items-start gap-3 rounded-xl bg-gradient-to-r from-amber-50 to-orange-50 p-3">
      <View className="h-8 w-8 items-center justify-center rounded-lg bg-amber-100">
        {icon}
      </View>
      <View className="flex-1">
        <Text className="text-sm font-semibold text-stone-800">{title}</Text>
        <Text className="mt-0.5 text-xs leading-relaxed text-stone-600">
          {description}
        </Text>
      </View>
    </View>
  );
}

export interface VisualizationGuideProps {
  habitName?: string;
  onClose?: () => void;
}

export function VisualizationGuide({ habitName, onClose }: VisualizationGuideProps) {
  const [showAllTechniques, setShowAllTechniques] = useState(false);

  const displayedTechniques = showAllTechniques
    ? VISUALIZATION_TECHNIQUES
    : VISUALIZATION_TECHNIQUES.slice(0, 2);

  const handleShowMore = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    setShowAllTechniques(!showAllTechniques);
  };

  return (
    <View className="gap-5">
      {/* Header with Huberman branding */}
      <Animated.View
        className="overflow-hidden rounded-2xl bg-gradient-to-br from-violet-600 via-indigo-600 to-purple-700 p-5"
        entering={FadeInDown.delay(50).springify()}
      >
        <View className="flex-row items-start gap-3">
          <View className="h-12 w-12 items-center justify-center rounded-2xl bg-white/20">
            <Eye className="text-white" size={24} />
          </View>
          <View className="flex-1">
            <Text className="text-lg font-bold text-white">
              Goal Visualization
            </Text>
            <Text className="mt-0.5 text-sm text-violet-100">
              Science-backed techniques from neuroscience research
            </Text>
          </View>
        </View>

        <View className="mt-4 flex-row items-center gap-2 rounded-xl bg-white/10 p-3">
