/**
 * YourProgressCard Component
 *
 * @deprecated This component is deprecated and will be removed in the next major version.
 * Use `ProgressSectionConsolidated` from `../ProgressSectionConsolidated` instead.
 *
 * Migration Guide:
 * - Import `ProgressSectionConsolidated` from `../ProgressSectionConsolidated`
 * - Pass the same props to the new consolidated component
 * - The new component combines YourProgressCard, PersonalBestsCard, and ThisMonthCard
 *   into a single unified card with improved visual hierarchy
 *
 * Old:
 *   <YourProgressCard strength={75} weeklyChange={5} ... />
 *   <PersonalBestsCard streakRecords={...} ... />
 *   <ThisMonthCard dayStats={...} ... />
 *
 * New:
 *   <ProgressSectionConsolidated tracking={...} strength={75} ... />
 *
 * Section 1: Combines Habit Strength + actionable guidance.
 * Features:
 * - Progress ring (88px) with emoji + percentage
 * - Level badge with trend indicator (+X%)
 * - Progress bar to next level with emoji markers
 * - Actionable tip based on weak days pattern
 * - Teal/emerald gradient theme
 */

import React, { useEffect, useMemo } from 'react';
import { View, Text, Pressable, AccessibilityInfo } from 'react-native';
import Svg, { Circle } from 'react-native-svg';
import Animated, {
  useSharedValue,
  useAnimatedProps,
  useAnimatedStyle,
  useDerivedValue,
  withTiming,
  withDelay,
  withSpring,
  Easing,
  runOnJS,
  SharedValue,
} from 'react-native-reanimated';
import { TrendingUp, TrendingDown, Minus, Info, ChevronRight } from 'lucide-react-native';
import * as Haptics from 'expo-haptics';

import type { YourProgressCardProps, LevelConfig } from './types';

const AnimatedCircle = Animated.createAnimatedComponent(Circle);

// Level configurations
const STRENGTH_LEVELS: Record<string, LevelConfig> = {
  automatic: {
    color: '#059669', // emerald-600
    colorLight: '#d1fae5', // emerald-100
    description: 'This habit is second nature!',
    emoji: '⚡',
    label: 'Automatic',
    maxThreshold: 100,
    minThreshold: 80,
  },
  building: {
    color: '#16a34a', // green-600
    colorLight: '#dcfce7', // green-100
    description: 'Making good progress',
    emoji: '🌿',
    label: 'Building',
    maxThreshold: 40,
    minThreshold: 20,
  },
  developing: {
    color: '#0d9488', // teal-600
    colorLight: '#ccfbf1', // teal-100
    description: 'Getting stronger every day',
    emoji: '🌳',
    label: 'Developing',
    maxThreshold: 60,
    minThreshold: 40,
  },
  starting: {
    color: '#65a30d', // lime-600
    colorLight: '#ecfccb', // lime-100
    description: 'Just getting started',
    emoji: '🌱',
    label: 'Starting Out',
    maxThreshold: 20,
    minThreshold: 0,
  },
  strong: {
    color: '#0891b2', // cyan-600
    colorLight: '#cffafe', // cyan-100
    description: 'Well-established habit',
    emoji: '💪',
    label: 'Strong',
    maxThreshold: 80,
    minThreshold: 60,
  },
};

const getStrengthLevel = (strength: number): LevelConfig => {
  if (strength < 20) return STRENGTH_LEVELS.starting;
  if (strength < 40) return STRENGTH_LEVELS.building;
  if (strength < 60) return STRENGTH_LEVELS.developing;
  if (strength < 80) return STRENGTH_LEVELS.strong;
  return STRENGTH_LEVELS.automatic;
};

const getNextLevel = (strength: number): LevelConfig | null => {
  if (strength >= 80) return null;
  if (strength < 20) return STRENGTH_LEVELS.building;
  if (strength < 40) return STRENGTH_LEVELS.developing;
  if (strength < 60) return STRENGTH_LEVELS.strong;
  return STRENGTH_LEVELS.automatic;
};

// Animation constants
const RING_ANIMATION_DURATION = 1200;

/**
 * AnimatedPercentageText - Displays the strength percentage with counting animation
 */
function AnimatedPercentageText({
  animatedValue,
}: {
  animatedValue: SharedValue<number>;
}) {
  const [displayText, setDisplayText] = React.useState('0%');

  useDerivedValue(() => {
    const formatted = `${Math.round(animatedValue.value)}%`;
    runOnJS(setDisplayText)(formatted);
    return formatted;
  });

  return (
    <Text className="text-lg font-bold text-stone-900" accessibilityElementsHidden>
      {displayText}
    </Text>
  );
}

export function YourProgressCard({
  strength,
  weeklyChange = 0,
  actionableTip,
  onInfoPress,
}: YourProgressCardProps) {
  const clampedStrength = Math.max(0, Math.min(100, strength));
  const level = getStrengthLevel(clampedStrength);
  const nextLevel = getNextLevel(clampedStrength);

  // Ring dimensions (88px as per spec)
  const ringSize = 88;
  const strokeWidth = 8;
  const radius = (ringSize - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const center = ringSize / 2;

  // Track reduce motion preference
  const [reduceMotion, setReduceMotion] = React.useState(false);

  // Animations
  const animatedStrength = useSharedValue(0);
  const emojiScale = useSharedValue(0);

  useEffect(() => {
    AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
  }, []);

  useEffect(() => {
    if (reduceMotion) {
      animatedStrength.value = clampedStrength;
      emojiScale.value = 1;
      return;
    }

    // Ring fill animation - 1200ms with ease-out
    animatedStrength.value = withTiming(clampedStrength, {
      duration: RING_ANIMATION_DURATION,
      easing: Easing.out(Easing.cubic),
    });

    // Emoji scale animation
    emojiScale.value = withDelay(
      300,
      withSpring(1, { damping: 8, stiffness: 150 })
    );
  }, [clampedStrength, reduceMotion]);

  const animatedCircleProps = useAnimatedProps(() => {
    const progress = animatedStrength.value / 100;
    return {
      strokeDashoffset: circumference * (1 - progress),
    };
  });

  const emojiAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: emojiScale.value }],
  }));

  const handleInfoPress = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onInfoPress?.();
  };

  // Trend indicator component
  const TrendIndicator = () => {
    if (weeklyChange > 0) {
      return (
        <View className="flex-row items-center gap-1 rounded-full bg-emerald-100 px-2 py-0.5">
          <TrendingUp className="text-emerald-600" size={12} />
          <Text className="text-xs font-semibold text-emerald-600">
            +{weeklyChange}%
          </Text>
        </View>
      );
    }
    if (weeklyChange < 0) {
      return (
        <View className="flex-row items-center gap-1 rounded-full bg-red-100 px-2 py-0.5">
          <TrendingDown className="text-red-600" size={12} />
          <Text className="text-xs font-semibold text-red-600">
            {weeklyChange}%
          </Text>
        </View>
      );
    }
    return (
      <View className="flex-row items-center gap-1 rounded-full bg-stone-100 px-2 py-0.5">
        <Minus className="text-stone-500" size={12} />
        <Text className="text-xs font-semibold text-stone-500">Stable</Text>
      </View>
    );
  };

  // Calculate progress within current level for the progress bar
  const levelProgress = useMemo(() => {
    if (!nextLevel) return 100; // At max level
    const levelRange = nextLevel.minThreshold - level.minThreshold;
    const currentProgress = clampedStrength - level.minThreshold;
    return Math.min(100, Math.max(0, (currentProgress / levelRange) * 100));
  }, [clampedStrength, level, nextLevel]);

  return (
    <View
      className="overflow-hidden rounded-2xl shadow-sm shadow-stone-200/50"
      accessibilityRole="summary"
      accessibilityLabel={`Habit strength at ${Math.round(clampedStrength)}%, ${level.label} level${weeklyChange !== 0 ? `, ${weeklyChange > 0 ? 'up' : 'down'} ${Math.abs(weeklyChange)}% this week` : ''}`}
    >
      {/* Gradient Background */}
      <View className="absolute inset-0 bg-gradient-to-br from-teal-50/30 via-white to-emerald-50/30" />
      <View className="absolute inset-0 border border-teal-500/20 rounded-2xl" />

      <View className="p-4">
        {/* Header */}
        <View className="mb-3 flex-row items-center justify-between">
          <Text className="text-sm font-semibold text-stone-600">Your Progress</Text>
          <Pressable
            accessibilityLabel="Learn about habit strength"
            accessibilityRole="button"
            className="h-7 w-7 items-center justify-center rounded-full bg-stone-100 active:bg-stone-200"
            onPress={handleInfoPress}
          >
            <Info className="text-stone-500" size={16} />
          </Pressable>
        </View>

        {/* Main content: Ring + Level info */}
        <View className="mb-4 flex-row items-center">
          {/* Progress Ring */}
          <View style={{ width: ringSize, height: ringSize }}>
            <Svg width={ringSize} height={ringSize}>
              {/* Background track */}
              <Circle
                cx={center}
                cy={center}
                fill="none"
                r={radius}
                stroke="#f3f4f6"
                strokeWidth={strokeWidth}
              />
              {/* Progress arc */}
              <AnimatedCircle
                animatedProps={animatedCircleProps}
                cx={center}
                cy={center}
                fill="none"
                origin={`${center}, ${center}`}
                r={radius}
                rotation="-90"
                stroke={level.color}
                strokeDasharray={circumference}
                strokeDashoffset={circumference}
                strokeLinecap="round"
                strokeWidth={strokeWidth}
              />
            </Svg>

            {/* Center content */}
            <View
              className="absolute items-center justify-center"
              style={{ width: ringSize, height: ringSize }}
            >
              <Animated.Text className="text-xl" style={emojiAnimatedStyle}>
                {level.emoji}
              </Animated.Text>
              <AnimatedPercentageText animatedValue={animatedStrength} />
            </View>
          </View>

          {/* Level info */}
          <View className="ml-4 flex-1">
            <View className="flex-row items-center gap-2 mb-1">
              <View
                className="rounded-full px-2.5 py-0.5"
                style={{ backgroundColor: level.colorLight }}
              >
                <Text className="text-xs font-semibold" style={{ color: level.color }}>
                  {level.label}
                </Text>
              </View>
              <TrendIndicator />
            </View>

            <Text className="text-xs text-stone-500 mb-2">
              {level.description}
            </Text>

            {nextLevel && (
              <Text className="text-[10px] text-stone-400">
                {Math.round(nextLevel.minThreshold - clampedStrength)}% to {nextLevel.emoji} {nextLevel.label}
              </Text>
            )}
          </View>
        </View>

        {/* Progress bar to next level */}
        <View className="mb-3">
          <View className="h-2 overflow-hidden rounded-full bg-stone-100">
            <Animated.View
              className="h-full rounded-full"
              style={{
                width: `${levelProgress}%`,
                backgroundColor: level.color,
              }}
            />
          </View>
          <View className="mt-1.5 flex-row justify-between">
            {['🌱', '🌿', '🌳', '💪', '⚡'].map((emoji, i) => (
              <Text key={i} className="text-[10px]">
                {emoji}
              </Text>
            ))}
          </View>
        </View>

        {/* Actionable tip */}
        <View
          className="flex-row items-center gap-2 rounded-xl p-3"
          style={{ backgroundColor: 'rgba(20, 184, 166, 0.1)' }}
          accessibilityLabel={`Tip: ${actionableTip}`}
        >
          <Text className="text-base">💡</Text>
          <Text className="flex-1 text-sm text-teal-700">{actionableTip}</Text>
          <ChevronRight className="text-teal-400" size={16} />
        </View>
      </View>
    </View>
  );
}

export default YourProgressCard;

/**
 * ProgressSection Utility Functions
 *
 * Calculation functions for habit insights and statistics.
 */

import type { HabitTrackingEntry } from '../../features/habits/types';
import type { DayStats, StreakRecord, TrendComparison } from './types';
import {
  differenceInDays,
  getTodayString,
  formatDateString,
} from '../../utils/dateUtils';

// Day labels
const DAY_LABELS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

/**
 * Calculate completion rate by day of week
 *
 * @param tracking - Array of habit tracking entries
 * @param habitCreatedAt - Optional timestamp when habit was created
 * @returns Array of DayStats for each day of the week
 */
export function calculateDayOfWeekStats(
  tracking: HabitTrackingEntry[],
  habitCreatedAt?: number
): DayStats[] {
  const dayStats: Record<number, { completed: number; total: number }> = {};

  // Initialize all days
  for (let i = 0; i < 7; i++) {
    dayStats[i] = { completed: 0, total: 0 };
  }

  // Get the start date (habit creation or first tracking entry)
  const startDate = habitCreatedAt
    ? new Date(habitCreatedAt)
    : tracking.length > 0
      ? new Date(tracking[tracking.length - 1].date)
      : new Date();

  const today = new Date();
  today.setHours(23, 59, 59, 999);

  // Create a set of completed dates for quick lookup
  const completedDates = new Set(
    tracking.filter((t) => t.completed).map((t) => t.date)
  );

  // Iterate through each day from start to today
  const current = new Date(startDate);
  current.setHours(0, 0, 0, 0);

  while (current <= today) {
    const dayOfWeek = current.getDay();
    const dateStr = formatDateString(current);

    dayStats[dayOfWeek].total++;
    if (completedDates.has(dateStr)) {
      dayStats[dayOfWeek].completed++;
    }

    current.setDate(current.getDate() + 1);
  }

  return DAY_LABELS.map((day, index) => ({
    day,
    dayIndex: index,
    completed: dayStats[index].completed,
    total: dayStats[index].total,
    rate:
      dayStats[index].total > 0
        ? Math.round((dayStats[index].completed / dayStats[index].total) * 100)
        : 0,
  }));
}

/**
 * Calculate the current streak from tracking data
 * Uses UTC-normalized date utilities to match backend calculations
 *
 * @param tracking - Array of habit tracking entries
 * @returns Number of consecutive days in the current streak
 */
export function calculateCurrentStreak(tracking: HabitTrackingEntry[]): number {
  const completedDates = new Set(
    tracking.filter((t) => t.completed).map((t) => t.date)
  );

  if (completedDates.size === 0) return 0;

  let streak = 0;
  const todayStr = getTodayString();

  // Start from today or yesterday if today not completed
  let checkDate = todayStr;
  if (!completedDates.has(todayStr)) {
    // Get yesterday using proper date math
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    checkDate = formatDateString(yesterday);
  }

  // Count consecutive days backwards
  while (streak < 400) {
    if (completedDates.has(checkDate)) {
      streak++;
      // Go to previous day
      const [year, month, day] = checkDate.split('-').map(Number);
      const prevDate = new Date(year, month - 1, day);
      prevDate.setDate(prevDate.getDate() - 1);
      checkDate = formatDateString(prevDate);
    } else {
      break;
    }
  }

  return streak;
}

/**
 * Calculate all streak records from tracking data
 * Uses UTC-normalized date utilities for consistent calculation
 *
 * @param tracking - Array of habit tracking entries
 * @param currentStreak - Current active streak count
 * @returns Array of top 5 streak records sorted by length
 */
export function calculateStreakRecords(
  tracking: HabitTrackingEntry[],
  currentStreak: number
): StreakRecord[] {
  if (tracking.length === 0) return [];

  // Get all completed dates sorted (ascending)
  const completedDates = tracking
    .filter((t) => t.completed)
    .map((t) => t.date)
    .sort();

  if (completedDates.length === 0) return [];

  const streaks: StreakRecord[] = [];
  let streakStart = completedDates[0];
  let streakDays = 1;
  let prevDateStr = completedDates[0];

  for (let i = 1; i < completedDates.length; i++) {
    const currDateStr = completedDates[i];
    // Use consistent differenceInDays utility (UTC normalization)
    const diffDays = differenceInDays(currDateStr, prevDateStr);

    if (diffDays === 1) {
      // Consecutive day
      streakDays++;
    } else if (diffDays > 1) {
      // Gap found, save previous streak if >= 2 days
      if (streakDays >= 2) {
        streaks.push({
          days: streakDays,
          startDate: streakStart,
          endDate: prevDateStr,
          isCurrent: false,
        });
      }
      // Start new streak
      streakStart = currDateStr;
      streakDays = 1;
    }
    // If diffDays === 0, same day entry (shouldn't happen with unique dates), skip

    prevDateStr = currDateStr;
  }

  // Don't forget the last streak
  if (streakDays >= 2) {
    const today = getTodayString();
    const lastDate = completedDates[completedDates.length - 1];
    // Check if last date is today or yesterday (streak is still active)
    const daysSinceLastCompletion = differenceInDays(today, lastDate);
    const isCurrent = daysSinceLastCompletion <= 1;

    streaks.push({
      days: streakDays,
      startDate: streakStart,
      endDate: lastDate,
      isCurrent: isCurrent && currentStreak > 0,
    });
  }

  // Sort by days descending
  streaks.sort((a, b) => b.days - a.days);

  // Mark the current streak if it exists but wasn't captured
  if (currentStreak > 0) {
    const currentIdx = streaks.findIndex((s) => s.isCurrent);
    if (currentIdx === -1 && currentStreak >= 2) {
      // Current streak not in list, add it
      const today = getTodayString();
      const startDate = new Date();
      startDate.setDate(startDate.getDate() - currentStreak + 1);
      streaks.push({
        days: currentStreak,
        startDate: formatDateString(startDate),
        endDate: today,
        isCurrent: true,
      });
      streaks.sort((a, b) => b.days - a.days);
    }
  }

  return streaks.slice(0, 5); // Top 5
}

/**
 * Calculate trend comparison between this month and last month
 *
 * @param tracking - Array of habit tracking entries
 * @returns Object with thisMonth, lastMonth rates and change
 */
export function calculateTrendComparison(
  tracking: HabitTrackingEntry[]
): TrendComparison {
  const today = new Date();
  const thisMonthStart = new Date(today.getFullYear(), today.getMonth(), 1);
  const lastMonthStart = new Date(today.getFullYear(), today.getMonth() - 1, 1);
  const lastMonthEnd = new Date(today.getFullYear(), today.getMonth(), 0);

  let thisMonthCompleted = 0;
  let thisMonthTotal = 0;
  let lastMonthCompleted = 0;
  let lastMonthTotal = 0;

  const completedDates = new Set(
    tracking.filter((t) => t.completed).map((t) => t.date)
  );

  // This month
  const current = new Date(thisMonthStart);
  while (current <= today) {
    thisMonthTotal++;
    if (completedDates.has(formatDateString(current))) {
      thisMonthCompleted++;
    }
    current.setDate(current.getDate() + 1);
  }

  // Last month
  const lastCurrent = new Date(lastMonthStart);
  while (lastCurrent <= lastMonthEnd) {
    lastMonthTotal++;
    if (completedDates.has(formatDateString(lastCurrent))) {
      lastMonthCompleted++;
    }
    lastCurrent.setDate(lastCurrent.getDate() + 1);
  }

  const thisMonthRate =
    thisMonthTotal > 0
      ? Math.round((thisMonthCompleted / thisMonthTotal) * 100)
      : 0;
  const lastMonthRate =
    lastMonthTotal > 0
      ? Math.round((lastMonthCompleted / lastMonthTotal) * 100)
      : 0;

  return {
    thisMonth: thisMonthRate,
    lastMonth: lastMonthRate,
    change: thisMonthRate - lastMonthRate,
  };
}

/**
 * Generate an actionable tip based on user's weak days pattern
 *
 * @param dayStats - Array of day statistics
 * @param currentStreak - Current active streak count
 * @returns Actionable tip string
 */
export function generateActionableTip(
  dayStats: DayStats[],
  currentStreak: number
): string {
  // Find weak days (below 70% completion rate with at least some data)
  const weakDays = dayStats
    .filter((d) => d.total > 0 && d.rate < 70)
    .sort((a, b) => a.rate - b.rate)
    .slice(0, 2);

  // If user is on a good streak, encourage them
  if (currentStreak >= 7) {
    return 'Amazing streak! Keep the momentum going.';
  }

  // If there are weak days, suggest focusing on them
  if (weakDays.length > 0) {
    const dayNames = weakDays.map((d) => d.day).join(' & ');
    return `Focus on ${dayNames} to level up!`;
  }

  // If all days are good but short streak, encourage consistency
  if (currentStreak > 0 && currentStreak < 7) {
    return `${7 - currentStreak} more days to hit a week streak!`;
  }

  // Default tip
  return 'Complete today to start a new streak!';
}

/**
 * Get the best and worst performing days
 *
 * @param dayStats - Array of day statistics
 * @returns Object with bestDay and worstDay (or null if no data)
 */
export function getBestAndWorstDays(dayStats: DayStats[]): {
  bestDay: DayStats | null;
  worstDay: DayStats | null;
} {
  const withData = dayStats.filter((d) => d.total > 0);

  if (withData.length === 0) {
    return { bestDay: null, worstDay: null };
  }

  const bestDay = withData.reduce((best, curr) =>
    curr.rate > best.rate ? curr : best
  );

  const worstDay = withData.reduce((worst, curr) =>
    curr.rate < worst.rate ? curr : worst
  );

  return { bestDay, worstDay };
}

/**
 * ActionableTipCard Component
 *
 * CTA section with personalized actionable tip.
 * Uses violet/indigo gradient for visual appeal.
 *
 * Features:
 * - Gradient background (violet-50 to indigo-50)
 * - Icon container (40px circle, violet-100 bg)
 * - Tip text from generator
 * - Optional subtitle for context
 * - Chevron for tap affordance
 * - Press animation with spring
 * - Haptic feedback on tap
 * - Quick actions bottom sheet on press
 * - Full accessibility support
 *
 * @see docs/specs/habit-details-screen/progress-consolidated-redesign.md
 * @see docs/specs/habit-details-screen/progress-tab-improvements-spec.md
 */

import React, { useEffect, useState, useCallback, useMemo } from 'react';
import { View, Text, Pressable } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  Easing,
} from 'react-native-reanimated';
import { Ionicons } from '@expo/vector-icons';

import { useHapticFeedback } from '../../hooks/useHapticFeedback';
import { useReduceMotion } from '../../hooks/useReduceMotion';
import { Springs } from '../../constants/motion';

import type { ActionableTipCardProps } from './types';
import { TipQuickActionsSheet } from './TipQuickActionsSheet';
import {
  determineTipTypeFromText,
  type QuickAction,
} from './TipQuickActionsSheetTypes';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

/** Duration of entrance animation (ms) */
const ENTRANCE_DURATION = 400;

/**
 * ActionableTipCard Component
 *
 * Displays a personalized actionable tip with gradient background,
 * icon, and chevron for tap affordance.
 * Now includes a quick actions bottom sheet for immediate user action.
 * Memoized to prevent re-renders when parent updates unrelated props.
 */
export const ActionableTipCard = React.memo(function ActionableTipCard({
  tip,
  subtitle,
  currentStreak = 0,
  onPress,
  onQuickAction,
}: ActionableTipCardProps) {
  const reduceMotion = useReduceMotion();
  const { triggerLightImpact } = useHapticFeedback();

  // Quick actions sheet state
  const [isSheetVisible, setIsSheetVisible] = useState(false);

  // Determine tip type and focus day from tip text
  const { tipType, focusDayName } = useMemo(
    () => determineTipTypeFromText(tip, currentStreak),
    [tip, currentStreak]
  );

  // Entrance animation values
  const opacity = useSharedValue(reduceMotion ? 1 : 0);
  const translateY = useSharedValue(reduceMotion ? 0 : 10);

  // Press animation
  const pressScale = useSharedValue(1);

  // Entrance animation effect
  useEffect(() => {
    if (reduceMotion) {
      opacity.value = 1;
      translateY.value = 0;
      return;
    }

    opacity.value = withTiming(1, {
      duration: ENTRANCE_DURATION,
      easing: Easing.out(Easing.cubic),
    });

    translateY.value = withSpring(0, {
      damping: 18,
      stiffness: 120,
    });
  }, [reduceMotion, opacity, translateY]);

  // Press handlers
  const handlePressIn = useCallback(() => {
    pressScale.value = withSpring(0.98, Springs.button);
  }, [pressScale]);

  const handlePressOut = useCallback(() => {
    pressScale.value = withSpring(1, Springs.button);
  }, [pressScale]);

  const handlePress = useCallback(() => {
    triggerLightImpact();
    // If onQuickAction is provided, show the quick actions sheet
    if (onQuickAction) {
      setIsSheetVisible(true);
    }
    // Also call legacy onPress if provided
    onPress?.();
  }, [triggerLightImpact, onQuickAction, onPress]);

  const handleSheetClose = useCallback(() => {
    setIsSheetVisible(false);
  }, []);

  const handleQuickAction = useCallback(
    (action: QuickAction) => {
      onQuickAction?.(action);
    },
    [onQuickAction]
  );

  // Animated styles
  const containerStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ translateY: translateY.value }, { scale: pressScale.value }],
  }));

  // The card is interactive if onPress or onQuickAction is provided
  const isInteractive = !!onPress || !!onQuickAction;

  const accessibilityLabel = subtitle
    ? `Tip: ${tip}. ${subtitle}`
    : `Tip: ${tip}`;
  const accessibilityHint = isInteractive
    ? onQuickAction
      ? 'Double tap to view quick actions'
      : 'Double tap to open this tip'
    : undefined;

  return (
    <>
      <AnimatedPressable
        accessibilityHint={accessibilityHint}
        accessibilityLabel={accessibilityLabel}
        accessibilityRole={isInteractive ? 'button' : 'text'}
        disabled={!isInteractive}
        style={containerStyle}
        testID='actionable-tip-card'
        onPress={handlePress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
      >
        <View
          className='flex-row items-center gap-3 rounded-xl border border-violet-100 p-3'
          style={{
            // Gradient from violet-50 to indigo-50
            // Since RN doesn't support linear-gradient natively, we use a solid background
            // that matches the design intent (light violet/indigo tint)
            backgroundColor: '#f5f3ff', // violet-50
          }}
        >
          {/* Icon Container */}
          <View
            accessibilityElementsHidden
            className='h-10 w-10 flex-shrink-0 items-center justify-center rounded-full'
            importantForAccessibility='no-hide-descendants'
            style={{ backgroundColor: '#ede9fe' }} // violet-100
          >
            <Text className='text-lg'>💡</Text>
          </View>

          {/* Text Content */}
          <View className='flex-1'>
            <Text
              className='text-sm font-medium'
              style={{ color: '#4c1d95' }} // violet-900
            >
              {tip}
            </Text>
            {subtitle && (
              <Text
                className='mt-0.5 text-xs'
                style={{ color: '#7c3aed' }} // violet-600
              >
                {subtitle}
              </Text>
            )}
          </View>

          {/* Chevron (only when interactive) */}
          {isInteractive && (
            <View
              accessibilityElementsHidden
              importantForAccessibility='no-hide-descendants'
            >
              <Ionicons
                color='#a78bfa' // violet-400
                name='chevron-forward'
                size={20}
                style={{ flexShrink: 0 }}
              />
            </View>
          )}
        </View>
      </AnimatedPressable>

      {/* Quick Actions Bottom Sheet */}
      {onQuickAction && (
        <TipQuickActionsSheet
          currentStreak={currentStreak}
          focusDayName={focusDayName}
          tipText={tip}
          tipType={tipType}
          visible={isSheetVisible}
          onActionPress={handleQuickAction}
          onClose={handleSheetClose}
        />
      )}
    </>
  );
});

export default ActionableTipCard;

/**
 * CompactStrengthRing Component
 *
 * A compact 56px version of the strength ring for use in StatsGrid.
 * Displays the habit strength percentage with an animated SVG ring.
 *
 * Features:
 * - 56px diameter ring (reduced from 100px)
 * - Animated progress ring with level-based colors
 * - Optional trend badge
 * - Full accessibility support
 *
 * @see docs/specs/habit-details-screen/progress-tab-improvements-spec.md
 */

import React, { useEffect, useMemo } from 'react';
import { View, Text } from 'react-native';
import Svg, { Circle } from 'react-native-svg';
import Animated, {
  useSharedValue,
  useAnimatedProps,
  withTiming,
  Easing,
} from 'react-native-reanimated';

import { useReduceMotion } from '../../hooks/useReduceMotion';
import { getLevelFromStrength } from './types';
import type { CompactStrengthRingProps } from './StatsGridTypes';

const AnimatedCircle = Animated.createAnimatedComponent(Circle);

/** Animation duration for ring fill */
const RING_ANIMATION_DURATION = 800;

/** Ring dimensions - compact 56px version */
const RING_SIZE = 56;
const STROKE_WIDTH = 6;
const RADIUS = (RING_SIZE - STROKE_WIDTH) / 2;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;
const CENTER = RING_SIZE / 2;

/**
 * CompactStrengthRing - A compact strength indicator ring
 * Memoized to prevent re-renders when parent updates unrelated props
 */
export const CompactStrengthRing = React.memo(function CompactStrengthRing({
  strength,
  weeklyChange = 0,
}: CompactStrengthRingProps) {
  const reduceMotion = useReduceMotion();

  // Clamp strength to 0-100
  const clampedStrength = useMemo(
    () => Math.max(0, Math.min(100, strength)),
    [strength]
  );

  // Get level info for colors
  const levelInfo = useMemo(
    () => getLevelFromStrength(clampedStrength),
    [clampedStrength]
  );

  // Animation shared value
  const animatedStrength = useSharedValue(reduceMotion ? clampedStrength : 0);

  // Run ring fill animation
  useEffect(() => {
    if (reduceMotion) {
      animatedStrength.value = clampedStrength;
      return;
    }

    animatedStrength.value = withTiming(clampedStrength, {
      duration: RING_ANIMATION_DURATION,
      easing: Easing.out(Easing.cubic),
    });
  }, [clampedStrength, reduceMotion, animatedStrength]);

  // Animated props for the progress circle
  const animatedCircleProps = useAnimatedProps(() => ({
    // Round to avoid "Loss of precision during arithmetic conversion" error in Reanimated
    strokeDashoffset: Math.round(CIRCUMFERENCE * (1 - animatedStrength.value / 100)),
  }));

  // Trend badge configuration
  const getTrendBadge = () => {
    if (weeklyChange === 0) return null;

    const isPositive = weeklyChange > 0;
    const bgColor = isPositive ? '#dcfce7' : '#fee2e2'; // green-100 : red-100
    const textColor = isPositive ? '#16a34a' : '#dc2626'; // green-600 : red-600
    const prefix = isPositive ? '+' : '';

    return (
      <View
        accessibilityLabel={`${isPositive ? 'Up' : 'Down'} ${Math.abs(weeklyChange)} percent`}
        className='absolute -right-1 -top-1 rounded-full px-1'
        style={{ backgroundColor: bgColor }}
      >
        <Text className='text-[8px] font-semibold' style={{ color: textColor }}>
          {prefix}
          {weeklyChange}%
        </Text>
      </View>
    );
  };

  const accessibilityLabel = `Habit strength at ${Math.round(clampedStrength)} percent${
    weeklyChange === 0
      ? ''
      : `, ${weeklyChange > 0 ? 'up' : 'down'} ${Math.abs(weeklyChange)} percent this week`
  }`;

  return (
    <View
      accessibilityLabel={accessibilityLabel}
      accessibilityRole='progressbar'
      accessibilityValue={{
        max: 100,
        min: 0,
        now: clampedStrength,
      }}
      className='relative'
      style={{ height: RING_SIZE, width: RING_SIZE }}
    >
      {/* SVG Ring */}
      <Svg height={RING_SIZE} width={RING_SIZE}>
        {/* Background track */}
        <Circle
          cx={CENTER}
          cy={CENTER}
          fill='none'
          r={RADIUS}
          stroke='#f3f4f6' // gray-100
          strokeWidth={STROKE_WIDTH}
        />
        {/* Animated progress arc */}
        <AnimatedCircle
          animatedProps={animatedCircleProps}
          cx={CENTER}
          cy={CENTER}
          fill='none'
          origin={`${CENTER}, ${CENTER}`}
          r={RADIUS}
          rotation='-90'
          stroke={levelInfo.color}
          strokeDasharray={CIRCUMFERENCE}
          strokeDashoffset={CIRCUMFERENCE}
          strokeLinecap='round'
          strokeWidth={STROKE_WIDTH}
        />
      </Svg>

      {/* Center content: emoji */}
      <View
        className='absolute items-center justify-center'
        style={{ height: RING_SIZE, width: RING_SIZE }}
      >
        <Text className='text-lg'>{levelInfo.emoji}</Text>
      </View>

      {/* Optional trend badge */}
      {getTrendBadge()}
    </View>
  );
});

export default CompactStrengthRing;

