source:
/**
 * ConsistencyIndexCard Component
 * Shows a rolling average consistency score that's more forgiving than streaks
 *
 * Unlike streaks which reset to zero on a single miss, consistency index
 * uses weighted rolling averages (30/60/90 days) to show true long-term progress.
 * Recent days are weighted slightly higher (0.98 decay factor).
 */

import React, { useMemo } from 'react';
import { View, Text, Pressable } from 'react-native';
import Animated, { FadeInDown } from 'react-native-reanimated';
import { Activity, Info, TrendingUp, TrendingDown } from 'lucide-react-native';
import Svg, { Circle } from 'react-native-svg';
import * as Haptics from 'expo-haptics';
import type { ConsistencyIndexResult } from '../CalendarHeatmap/utils';

export interface ConsistencyIndexCardProps {
  /** Consistency index data */
  consistencyIndex: ConsistencyIndexResult;
  /** Previous period's overall score for comparison */
  previousOverall?: number;
  /** Callback when info button is pressed */
  onInfoPress?: () => void;
}

/**
 * Circular progress ring component
 */
function ProgressRing({
  progress,
  size = 80,
  strokeWidth = 8,
  color = '#8b5cf6',
}: {
  progress: number;
  size?: number;
  strokeWidth?: number;
  color?: string;
}) {
  const radius = (size - strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;
  const strokeDashoffset = circumference - (progress / 100) * circumference;

  return (
    <Svg width={size} height={size} style={{ transform: [{ rotate: '-90deg' }] }}>
      {/* Background circle */}
      <Circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        stroke="#e7e5e4"
        strokeWidth={strokeWidth}
        fill="transparent"
      />
      {/* Progress circle */}
      <Circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        stroke={color}
        strokeWidth={strokeWidth}
        fill="transparent"
        strokeDasharray={circumference}
        strokeDashoffset={strokeDashoffset}
        strokeLinecap="round"
      />
    </Svg>
  );
}

/**
 * Get color based on consistency score
 */
function getScoreColor(score: number): string {
  if (score >= 80) return '#10b981'; // emerald-500 - excellent
  if (score >= 60) return '#8b5cf6'; // violet-500 - good
  if (score >= 40) return '#f59e0b'; // amber-500 - moderate
  return '#ef4444'; // red-500 - needs work
}

/**
 * Get feedback message based on consistency score
 */
function getFeedbackMessage(score: number): string {
  if (score >= 80) return 'Excellent consistency! Keep it up.';
  if (score >= 60) return 'Good progress! You\'re building a solid habit.';
  if (score >= 40) return 'Making progress. Try to increase frequency.';
  return 'Room to grow. Every day counts!';
}

export function ConsistencyIndexCard({
  consistencyIndex,
  previousOverall,
  onInfoPress,
}: ConsistencyIndexCardProps) {
  const { overall, day30, day60, day90 } = consistencyIndex;

  // Calculate change from previous period
  const change = useMemo(() => {
    if (previousOverall === undefined) return null;
    return overall - previousOverall;
  }, [overall, previousOverall]);

  const scoreColor = getScoreColor(overall);
  const feedbackMessage = getFeedbackMessage(overall);

  const handleInfoPress = () => {
    Haptics.selectionAsync();
    onInfoPress?.();
  };

  return (
    <Animated.View
      entering={FadeInDown.delay(150).springify()}
      className="bg-white rounded-2xl border border-stone-200 p-4 shadow-sm"
      accessibilityRole="summary"
      accessibilityLabel={`Consistency Index: ${overall} percent overall`}
    >
      {/* Header */}
      <View className="flex-row items-center justify-between mb-3">
        <View className="flex-row items-center gap-2">
          <View className="w-8 h-8 rounded-lg bg-violet-100 items-center justify-center">
            <Activity size={16} className="text-violet-600" />
          </View>
          <Text className="font-semibold text-stone-800">Consistency Index</Text>
        </View>

        <Pressable
          onPress={handleInfoPress}
          className="p-1 rounded-full"
          accessibilityRole="button"
          accessibilityLabel="Learn more about consistency index"
          accessibilityHint="Opens explanation of how consistency is calculated"
        >
          <Info size={16} className="text-stone-400" />
        </Pressable>
      </View>

      {/* Main Content */}
      <View className="flex-row items-center gap-4">
        {/* Progress Ring */}
        <View className="relative w-20 h-20 items-center justify-center">
          <ProgressRing progress={overall} color={scoreColor} />
          <View className="absolute inset-0 items-center justify-center">
            <Text className="text-xl font-bold text-stone-800">{overall}%</Text>
          </View>
        </View>

        {/* Breakdown */}
        <View className="flex-1 space-y-2">
          <View className="flex-row justify-between">
            <Text className="text-sm text-stone-500">30-day avg</Text>
            <Text className="text-sm font-medium text-stone-700">{day30}%</Text>
          </View>
          <View className="flex-row justify-between">
            <Text className="text-sm text-stone-500">60-day avg</Text>
            <Text className="text-sm font-medium text-stone-700">{day60}%</Text>
          </View>
          <View className="flex-row justify-between">
            <Text className="text-sm text-stone-500">90-day avg</Text>
            <Text className="text-sm font-medium text-stone-700">{day90}%</Text>
          </View>
        </View>
      </View>

      {/* Change indicator */}
      {change !== null && (
        <View className="flex-row items-center justify-center mt-3 pt-3 border-t border-stone-100">
          {change >= 0 ? (
            <TrendingUp size={14} className="text-emerald-500 mr-1" />
          ) : (
            <TrendingDown size={14} className="text-amber-500 mr-1" />
          )}
          <Text
            className={`text-xs font-medium ${
              change >= 0 ? 'text-emerald-600' : 'text-amber-600'
            }`}
          >
            {change >= 0 ? '+' : ''}{change}% vs last period
          </Text>
        </View>
      )}

      {/* Feedback Tip */}
      <View className="mt-3 bg-stone-50 rounded-lg p-2">
        <Text className="text-xs text-stone-500">
          💡 {feedbackMessage}
        </Text>
      </View>
    </Animated.View>
  );
}

export default ConsistencyIndexCard;

/**
 * DayBar Component
 *
 * Individual animated bar for the WeeklyPatternChart.
 * Shows a single day's completion rate with staggered animation.
 *
 * @see docs/specs/habit-details-screen/progress-consolidated-redesign.md
 */

import React, { useEffect } from 'react';
import { View, Text } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withDelay,
  withSpring,
  withTiming,
  Easing,
} from 'react-native-reanimated';

/** Single character day labels */
const DAY_LABELS_SHORT = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];

/** Delay between each bar's animation start (ms) */
const BAR_STAGGER_DELAY = 50;

/** Bar dimensions per spec */
const BAR_WIDTH = 20;
const BAR_MAX_HEIGHT = 40;

/**
 * Get bar color based on performance rate and best/worst status
 */
function getBarColor(rate: number, isBest: boolean, isWorst: boolean): string {
  if (isBest) return '#10b981'; // emerald-500
  if (isWorst) return '#fbbf24'; // amber-400
  if (rate >= 70) return '#a8a29e'; // stone-400
  if (rate >= 50) return '#d6d3d1'; // stone-300
  return '#e7e5e4'; // stone-200
}

export interface DayBarProps {
  dayIndex: number;
  rate: number;
  isBest: boolean;
  isWorst: boolean;
  maxRate: number;
  index: number;
  reduceMotion: boolean;
}

/**
 * Individual animated day bar
 * Memoized to prevent unnecessary re-renders when sibling bars update
 */
export const DayBar = React.memo(function DayBar({
  dayIndex,
  rate,
  isBest,
  isWorst,
  maxRate,
  index,
  reduceMotion,
}: DayBarProps) {
  const scaleY = useSharedValue(reduceMotion ? 1 : 0);
  const opacity = useSharedValue(reduceMotion ? 1 : 0);

  // Calculate normalized height (0-1 range)
  const normalizedHeight = maxRate > 0 ? rate / maxRate : 0;
  // Ensure minimum visible height for non-zero values
  const minHeightRatio = rate > 0 ? 0.15 : 0.05;
  const finalHeightRatio = Math.max(normalizedHeight, minHeightRatio);
  const barHeight = finalHeightRatio * BAR_MAX_HEIGHT;

  useEffect(() => {
    if (reduceMotion) {
      scaleY.value = 1;
      opacity.value = 1;
      return;
    }

    const delay = index * BAR_STAGGER_DELAY;

    opacity.value = withDelay(
      delay,
      withTiming(1, {
        duration: 200,
        easing: Easing.out(Easing.cubic),
      })
    );

    scaleY.value = withDelay(
      delay,
      withSpring(1, {
        damping: 12,
        stiffness: 100,
      })
    );
  }, [index, reduceMotion, scaleY, opacity]);

  const barStyle = useAnimatedStyle(() => ({
    height: barHeight,
    opacity: opacity.value,
    transform: [{ scaleY: scaleY.value }],
  }));

  const barColor = getBarColor(rate, isBest, isWorst);

  // Day label styling
  const labelColor = isBest
    ? 'text-emerald-600 font-bold'
    : isWorst
      ? 'text-amber-600 font-bold'
      : 'text-stone-500';

  const accessibilityLabel = `${DAY_LABELS_SHORT[dayIndex]}: ${rate}% completion${isBest ? ', best day' : ''}${isWorst ? ', focus day' : ''}`;

  return (
    <View
      accessibilityLabel={accessibilityLabel}
      accessibilityRole='text'
      className='items-center'
      style={{ width: BAR_WIDTH }}
    >
      {/* Bar container - aligned to bottom */}
      <View
        className='items-center justify-end'
        style={{ height: BAR_MAX_HEIGHT }}
      >
        <Animated.View
          className='rounded-t-sm'
          style={[
            {
              backgroundColor: barColor,
              transformOrigin: 'bottom',
              width: BAR_WIDTH - 4,
            },
            barStyle,
          ]}
        />
      </View>
      {/* Day label */}
      <Text className={`mt-1 text-[10px] ${labelColor}`}>
        {DAY_LABELS_SHORT[dayIndex]}
      </Text>
    </View>
  );
});

export default DayBar;

/**
 * HeroStrengthSection Component
 *
 * Hero section displaying the main habit strength progress ring
 * with level information and trend indicator.
 * Memoized to prevent re-renders when parent updates unrelated props.
 *
 * @see docs/specs/habit-details-screen/progress-consolidated-redesign.md
 */

import React, { useEffect, useMemo } from 'react';
import { View, Text, AccessibilityInfo } from 'react-native';
import Svg, { Circle } from 'react-native-svg';
import Animated, {
  useSharedValue,
  useAnimatedProps,
  useAnimatedStyle,
  withTiming,
  withDelay,
  withSpring,
  Easing,
} from 'react-native-reanimated';

import type { HeroStrengthSectionProps } from './types';
import { getProgressToNextLevel } from './types';
import { TrendIndicator } from './TrendIndicator';
import { AnimatedPercentageText } from './AnimatedPercentageText';

const AnimatedCircle = Animated.createAnimatedComponent(Circle);

const RING_ANIMATION_DURATION = 1200;
const EMOJI_SCALE_DELAY = 300;

/** Ring dimensions - defined at module level to avoid recreation */
const RING_SIZE = 100;
const STROKE_WIDTH = 10;
const RADIUS = (RING_SIZE - STROKE_WIDTH) / 2;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;
const CENTER = RING_SIZE / 2;

export const HeroStrengthSection = React.memo(function HeroStrengthSection({
  strength,
  weeklyChange = 0,
}: HeroStrengthSectionProps) {
  // Memoize strength clamping to prevent recalculation
  const clampedStrength = useMemo(
    () => Math.max(0, Math.min(100, strength)),
    [strength]
  );

  // Memoize level data derivation
  const { currentLevel, nextLevel, progressPercent, pointsToNext } = useMemo(
    () => getProgressToNextLevel(clampedStrength),
    [clampedStrength]
  );

  const [reduceMotion, setReduceMotion] = React.useState(false);
  const animatedStrength = useSharedValue(0);
  const emojiScale = useSharedValue(0);
  const progressBarWidth = useSharedValue(0);

  useEffect(() => {
    void AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
  }, []);

  useEffect(() => {
    if (reduceMotion) {
      animatedStrength.value = clampedStrength;
      emojiScale.value = 1;
      progressBarWidth.value = progressPercent;
      return;
    }
    animatedStrength.value = withTiming(clampedStrength, {
      duration: RING_ANIMATION_DURATION,
      easing: Easing.out(Easing.cubic),
    });
    emojiScale.value = withDelay(
      EMOJI_SCALE_DELAY,
      withSpring(1, { damping: 8, stiffness: 150 })
    );
    progressBarWidth.value = withDelay(
      200,
      withTiming(progressPercent, {
        duration: 800,
        easing: Easing.out(Easing.cubic),
      })
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [clampedStrength, reduceMotion, progressPercent]);

  const animatedCircleProps = useAnimatedProps(() => ({
    // Round to avoid "Loss of precision during arithmetic conversion" error in Reanimated
    strokeDashoffset: Math.round(CIRCUMFERENCE * (1 - animatedStrength.value / 100)),
  }));
  const emojiAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: emojiScale.value }],
  }));
  const progressBarAnimatedStyle = useAnimatedStyle(() => ({
    width: `${progressBarWidth.value}%`,
  }));

  const accessLabel = `Habit strength at ${Math.round(clampedStrength)} percent, ${currentLevel.label} level${weeklyChange === 0 ? '' : `, ${weeklyChange > 0 ? 'up' : 'down'} ${Math.abs(weeklyChange)} percent this week`}`;

  return (
    <View
      accessibilityLabel={accessLabel}
      accessibilityRole='summary'
      className='mb-5 flex-row items-center gap-4'
    >
      <View
        style={{
          elevation: 4,
          height: RING_SIZE,
          shadowColor: currentLevel.color,
          shadowOffset: { height: 0, width: 0 },
          shadowOpacity: 0.3,
          shadowRadius: 8,
          width: RING_SIZE,
        }}
      >
        <Svg height={RING_SIZE} width={RING_SIZE}>
          <Circle
            cx={CENTER}
            cy={CENTER}
            fill='none'
            r={RADIUS}
            stroke='#f3f4f6'
            strokeWidth={STROKE_WIDTH}
          />
          <AnimatedCircle
            animatedProps={animatedCircleProps}
            cx={CENTER}
            cy={CENTER}
            fill='none'
            origin={`${CENTER}, ${CENTER}`}
            r={RADIUS}
            rotation='-90'
            stroke={currentLevel.color}
            strokeDasharray={CIRCUMFERENCE}
            strokeDashoffset={CIRCUMFERENCE}
            strokeLinecap='round'
            strokeWidth={STROKE_WIDTH}
          />
        </Svg>
        <View
          className='absolute items-center justify-center'
          style={{ height: RING_SIZE, width: RING_SIZE }}
        >
          <Animated.Text className='text-2xl' style={emojiAnimatedStyle}>
            {currentLevel.emoji}
          </Animated.Text>
          <AnimatedPercentageText animatedValue={animatedStrength} />
        </View>
      </View>
      <View className='flex-1'>
        <View className='mb-1.5 flex-row items-center gap-2'>
          <View
            className='rounded-full px-3 py-1'
            style={{ backgroundColor: currentLevel.bgColor }}
          >
            <Text
              className='text-sm font-semibold'
              style={{ color: currentLevel.color }}
            >
              {currentLevel.label}
            </Text>
          </View>
          <TrendIndicator weeklyChange={weeklyChange} />
        </View>
        <Text className='mb-1 text-sm text-stone-600'>
          {currentLevel.description}
        </Text>
        <View className='flex-row items-center gap-1.5'>
          <View className='h-1.5 flex-1 overflow-hidden rounded-full bg-stone-100'>
            <Animated.View
              className='h-full rounded-full'
              style={[
                { backgroundColor: currentLevel.color },
                progressBarAnimatedStyle,
              ]}
            />
          </View>
          {nextLevel ? (
            <Text className='whitespace-nowrap text-[10px] text-stone-400'>
              {pointsToNext}% to {nextLevel.emoji}
            </Text>
          ) : (
            <Text className='whitespace-nowrap text-[10px] text-stone-400'>
              Max level! {currentLevel.emoji}
            </Text>
          )}
        </View>
      </View>
    </View>
  );
});

