/**
 * InsightChips Component
 *
 * Horizontal scroll container with key insight chips.
 * Displays: Current Streak, Best Day, Focus Day, Monthly Progress
 *
 * Features:
 * - Horizontal scroll with touch momentum
 * - Staggered entrance animations (50ms delay per chip)
 * - Pulse animation for active streak chip
 * - Haptic feedback on tap
 * - Full accessibility support
 *
 * @see docs/specs/habit-details-screen/progress-consolidated-redesign.md
 */

import React, { useEffect, useMemo } from 'react';
import { View, Text, ScrollView, Pressable } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  withDelay,
  withSpring,
  withRepeat,
  withSequence,
  Easing,
  cancelAnimation,
} from 'react-native-reanimated';

import { useHapticFeedback } from '../../hooks/useHapticFeedback';
import { useReduceMotion } from '../../hooks/useReduceMotion';
import { Motion, Springs } from '../../constants/motion';

import type { InsightChipsProps, InsightChipData } from './types';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

/** Stagger delay between chip entrance animations (ms) */
const CHIP_STAGGER_DELAY = 50;

/** Duration of chip entrance animation (ms) */
const CHIP_ENTRANCE_DURATION = 300;

/** Pulse animation cycle duration (ms) */
const PULSE_DURATION = 2000;

interface InsightChipProps {
  chip: InsightChipData;
  index: number;
  reduceMotion: boolean;
  onHapticFeedback: () => void;
}

/** Border color mapping - defined at module level to avoid recreation */
const BORDER_COLOR_MAP: Record<string, string> = {
  'amber-200': '#fde68a',
  'emerald-200': '#a7f3d0',
  'orange-200': '#fed7aa',
  'violet-200': '#ddd6fe',
};

/**
 * Individual insight chip with entrance and pulse animations
 * Memoized to prevent unnecessary re-renders when parent updates
 */
const InsightChip = React.memo(function InsightChip({
  chip,
  index,
  reduceMotion,
  onHapticFeedback,
}: InsightChipProps) {
  // Entrance animation values
  const opacity = useSharedValue(reduceMotion ? 1 : 0);
  const translateX = useSharedValue(reduceMotion ? 0 : 20);

  // Pulse animation for active streak
  const pulseScale = useSharedValue(1);
  const pulseOpacity = useSharedValue(0);

  // Press animation
  const pressScale = useSharedValue(1);

  // Entrance animation effect
  useEffect(() => {
    if (reduceMotion) {
      opacity.value = 1;
      translateX.value = 0;
      return;
    }

    const delay = index * CHIP_STAGGER_DELAY;
    opacity.value = withDelay(
      delay,
      withTiming(1, {
        duration: CHIP_ENTRANCE_DURATION,
        easing: Easing.out(Easing.cubic),
      })
    );
    translateX.value = withDelay(
      delay,
      withSpring(0, { damping: 18, stiffness: 120 })
    );
  }, [index, reduceMotion, opacity, translateX]);

  // Pulse animation effect for active streak
  useEffect(() => {
    if (!chip.hasPulse || reduceMotion) {
      pulseScale.value = 1;
      pulseOpacity.value = 0;
      return;
    }

    // Scale pulse: 1 -> 1.05 -> 1 (continuous)
    pulseScale.value = withRepeat(
      withSequence(
        withTiming(1.05, { duration: PULSE_DURATION / 2 }),
        withTiming(1, { duration: PULSE_DURATION / 2 })
      ),
      -1, // Repeat forever
      true // Reverse
    );

    // Opacity pulse for the outer ring: 0 -> 0.6 -> 0 (continuous)
    pulseOpacity.value = withRepeat(
      withSequence(
        withTiming(0.6, { duration: PULSE_DURATION / 2 }),
        withTiming(0, { duration: PULSE_DURATION / 2 })
      ),
      -1,
      false
    );

    return () => {
      cancelAnimation(pulseScale);
      cancelAnimation(pulseOpacity);
    };
  }, [chip.hasPulse, reduceMotion, pulseScale, pulseOpacity]);

  // Press handlers
  const handlePressIn = () => {
    pressScale.value = withSpring(0.95, Springs.button);
  };

  const handlePressOut = () => {
    pressScale.value = withSpring(1, Springs.button);
  };

  const handlePress = () => {
    onHapticFeedback();
    chip.onPress?.();
  };

  // Animated styles
  const containerStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ translateX: translateX.value }, { scale: pressScale.value }],
  }));

  const pulseRingStyle = useAnimatedStyle(() => ({
    opacity: pulseOpacity.value,
    transform: [{ scale: pulseScale.value }],
  }));

  const borderColor = BORDER_COLOR_MAP[chip.borderColor] || '#e7e5e4';

  const accessibilityLabel = `${chip.label}: ${chip.value}${chip.hasPulse ? ', active streak' : ''}`;
  const accessibilityHint = chip.isInteractive
    ? 'Double tap to view details'
    : undefined;

  return (
    <AnimatedPressable
      accessibilityHint={accessibilityHint}
      accessibilityLabel={accessibilityLabel}
      accessibilityRole={chip.isInteractive ? 'button' : 'text'}
      disabled={!chip.isInteractive}
      style={containerStyle}
      onPress={handlePress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
    >
      <View
        className='relative rounded-xl bg-white px-3 py-2.5'
        style={{
          borderColor,
          borderWidth: 1,
          minHeight: 56, // Increased touch target height
          minWidth: 90,
        }}
      >
        {/* Pulse ring overlay for active streak */}
        {chip.hasPulse && (
          <Animated.View
            className='absolute -inset-0.5 rounded-xl'
            pointerEvents='none'
            style={[
              {
                borderColor: '#fb923c', // orange-400
                borderWidth: 2,
              },
              pulseRingStyle,
            ]}
          />
        )}

        {/* Stacked layout: emoji on top, value + label below */}
        <View className='flex-row items-center gap-2'>
          <Text className='text-lg'>{chip.icon}</Text>
          <View>
            <Text className='text-base font-bold text-stone-800'>
              {chip.value}
            </Text>
            <Text className='text-[10px] text-stone-500'>{chip.label}</Text>
          </View>
        </View>
      </View>
    </AnimatedPressable>
  );
});

/**
 * InsightChips Component
 *
 * Horizontal scroll container with key insight chips showing:
 * - Current streak (with pulse animation if active)
 * - Best performing day
 * - Focus day (worst day - interactive)
 * - Monthly completion rate
 */
export function InsightChips({
  currentStreak,
  bestDay,
  focusDay,
  monthlyCompleted,
  monthlyTotal,
  onFocusDayPress,
}: InsightChipsProps) {
  const reduceMotion = useReduceMotion();
  const { triggerSelection } = useHapticFeedback();

  // Build chip data array
  const chips = useMemo<InsightChipData[]>(() => {
    const chipData: InsightChipData[] = [];

    // Current Streak chip
    chipData.push({
      borderColor: 'orange-200',
      hasPulse: currentStreak > 0,
      icon: '🔥',
      id: 'streak',
      isInteractive: false,
      label: 'Current Streak',
      value: currentStreak === 1 ? '1 day' : `${currentStreak} days`,
    });

    // Best Day chip
    if (bestDay) {
      chipData.push({
        borderColor: 'emerald-200',
        icon: '🏆',
        id: 'bestDay',
        isInteractive: false,
        label: `${Math.round(bestDay.rate)}% completion`,
        value: bestDay.name,
      });
    }

    // Focus Day chip (interactive)
    if (focusDay) {
      chipData.push({
        borderColor: 'amber-200',
        icon: '⚡',
        id: 'focusDay',
        isInteractive: !!onFocusDayPress,
        label: 'Focus day',
        onPress: onFocusDayPress,
        value: focusDay.name,
      });
    }

    // Monthly Progress chip
    chipData.push({
      borderColor: 'violet-200',
      icon: '📅',
      id: 'monthly',
      isInteractive: false,
      label: 'This month',
      value: `${monthlyCompleted}/${monthlyTotal}`,
    });

    return chipData;
  }, [
    currentStreak,
    bestDay,
    focusDay,
    monthlyCompleted,
    monthlyTotal,
    onFocusDayPress,
  ]);

  return (
    <View className='mb-4'>
      <ScrollView
        horizontal
        accessibilityLabel='Habit insights'
        accessibilityRole='list'
        contentContainerStyle={{ gap: 8, paddingRight: 8 }}
        showsHorizontalScrollIndicator={false}
        style={{ marginHorizontal: -4 }}
      >
        {chips.map((chip, index) => (
          <InsightChip
            key={chip.id}
            chip={chip}
            index={index}
            reduceMotion={reduceMotion}
            onHapticFeedback={triggerSelection}
          />
        ))}
      </ScrollView>
    </View>
  );
}

export default InsightChips;

/**
 * MilestoneProgress Component
 *
 * Gamification component showing progress toward next meaningful milestone.
 * Provides visual feedback on streak progress with milestone badges.
 *
 * Features:
 * - Progress bar showing current streak vs next milestone
 * - Badge icon at end of progress bar
 * - "X days away" countdown
 * - No-streak state with encouraging CTA
 * - Celebration state when milestone is hit
 * - Full accessibility support
 * - Respects reduce motion preference
 *
 * @see docs/specs/habit-details-screen/progress-tab-improvements-spec.md
 */

import React, { useEffect, useMemo } from 'react';
import { View, Text, StyleSheet, Pressable } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  withRepeat,
  withSequence,
  Easing,
  interpolate,
} from 'react-native-reanimated';
import { Ionicons } from '@expo/vector-icons';

import { useReduceMotion } from '../../hooks/useReduceMotion';
import { Springs } from '../../constants/motion';

import type { MilestoneProgressProps } from './MilestoneProgressTypes';
import {
  calculateMilestoneProgress,
  MILESTONES,
} from './MilestoneProgressTypes';

/** Animation timing constants */
const ENTRANCE_DURATION = 300;
const PROGRESS_BAR_DURATION = 800;
const PULSE_DURATION = 2000;
const CELEBRATION_DURATION = 3000;

/**
 * MilestoneProgress - Shows progress toward next streak milestone
 * Memoized to prevent unnecessary re-renders
 */
export const MilestoneProgress = React.memo(function MilestoneProgress({
  currentStreak,
  onMilestoneHit,
  celebratedMilestones = [],
}: MilestoneProgressProps) {
  const reduceMotion = useReduceMotion();

  // Calculate milestone progress
  const milestoneData = useMemo(
    () => calculateMilestoneProgress(currentStreak, celebratedMilestones),
    [currentStreak, celebratedMilestones]
  );

  const {
    nextMilestone,
    daysRemaining,
    progressPercentage,
    displayState,
    previousMilestone,
  } = milestoneData;

  // Animation shared values
  const containerScale = useSharedValue(reduceMotion ? 1 : 0.95);
  const containerOpacity = useSharedValue(reduceMotion ? 1 : 0);
  const progressWidth = useSharedValue(reduceMotion ? progressPercentage : 0);
  const badgePulse = useSharedValue(1);
  const celebrationScale = useSharedValue(1);

  // Entrance animation
  useEffect(() => {
    if (reduceMotion) {
      containerScale.value = 1;
      containerOpacity.value = 1;
      progressWidth.value = progressPercentage;
      return;
    }

    // Scale spring entrance
    containerScale.value = withSpring(1, Springs.gentle);

    // Opacity fade in
    containerOpacity.value = withTiming(1, {
      duration: ENTRANCE_DURATION,
      easing: Easing.out(Easing.cubic),
    });

    // Animate progress bar width
    progressWidth.value = withTiming(progressPercentage, {
      duration: PROGRESS_BAR_DURATION,
      easing: Easing.out(Easing.cubic),
    });
  }, [
    reduceMotion,
    progressPercentage,
    containerScale,
    containerOpacity,
    progressWidth,
  ]);

  // Badge pulse animation (when close to milestone)
  useEffect(() => {
    if (reduceMotion || daysRemaining > 3) {
      badgePulse.value = 1;
      return;
    }

    // Gentle pulse when within 3 days of milestone
    badgePulse.value = withRepeat(
      withSequence(
        withTiming(1.1, {
          duration: PULSE_DURATION / 2,
          easing: Easing.inOut(Easing.ease),
        }),
        withTiming(1, {
          duration: PULSE_DURATION / 2,
          easing: Easing.inOut(Easing.ease),
        })
      ),
      -1, // Infinite
      true // Reverse
    );
  }, [reduceMotion, daysRemaining, badgePulse]);

  // Celebration animation
  useEffect(() => {
    if (displayState !== 'just-hit' || reduceMotion) {
      celebrationScale.value = 1;
      return;
    }

    // Bouncy celebration animation
    celebrationScale.value = withSequence(
      withSpring(1.2, Springs.bouncy),
      withTiming(1, { duration: 500 })
    );

    // Call callback if provided - check if current streak matches any milestone
    if (onMilestoneHit) {
      const justHitMilestone = MILESTONES.find((m) => m.days === currentStreak);
      if (justHitMilestone) {
        onMilestoneHit(justHitMilestone.days);
      }
    }
  }, [
    displayState,
    reduceMotion,
    celebrationScale,
    onMilestoneHit,
    currentStreak,
  ]);

  // Container animated style
  const containerAnimatedStyle = useAnimatedStyle(() => ({
    opacity: containerOpacity.value,
    transform: [{ scale: containerScale.value }],
  }));

  // Progress bar animated style
  const progressAnimatedStyle = useAnimatedStyle(() => ({
    width: `${progressWidth.value}%`,
  }));

  // Badge animated style
  const badgeAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: badgePulse.value }],
  }));

  // Celebration animated style
  const celebrationAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: celebrationScale.value }],
  }));

  // Build accessibility label
  const accessibilityLabel = useMemo(() => {
    if (displayState === 'no-streak') {
      return 'No active streak. Start your streak today to reach the Habit Starter milestone at 3 days.';
    }

    if (displayState === 'just-hit') {
      const milestone = MILESTONES.find((m) => m.days === currentStreak);
      return `Congratulations! You hit ${currentStreak} days and earned the ${milestone?.name ?? 'milestone'} badge!`;
    }

    if (nextMilestone) {
      return `Next milestone: ${nextMilestone.days} days, ${nextMilestone.name}. ${daysRemaining} days away. Progress: ${progressPercentage} percent.`;
    }

    return `Congratulations! You've achieved all milestones with ${currentStreak} days streak!`;
  }, [
    displayState,
    currentStreak,
    nextMilestone,
    daysRemaining,
    progressPercentage,
  ]);

  // Render no-streak state
  if (displayState === 'no-streak') {
    return (
      <Animated.View
        accessibilityLabel={accessibilityLabel}
        accessibilityRole='text'
        style={[styles.container, containerAnimatedStyle]}
        testID='milestone-progress'
      >
        <View style={styles.noStreakContainer}>
          <Ionicons
            color='#9ca3af'
            name='arrow-forward-circle-outline'
            size={24}
            style={styles.noStreakIcon}
          />
          <View style={styles.noStreakTextContainer}>
            <Text style={styles.noStreakTitle}>Start your streak today!</Text>
            <Text style={styles.noStreakSubtext}>
              3 days to unlock {MILESTONES[0].badge} {MILESTONES[0].name}
            </Text>
          </View>
        </View>
      </Animated.View>
    );
  }

  // Render celebration state
  if (displayState === 'just-hit') {
    const hitMilestone = MILESTONES.find((m) => m.days === currentStreak);
    const nextAfterHit = nextMilestone;

    return (
      <Animated.View
        accessibilityLabel={accessibilityLabel}
        accessibilityRole='text'
        style={[
          styles.container,
          styles.celebrationContainer,
          containerAnimatedStyle,
        ]}
        testID='milestone-progress'
      >
        <Animated.View
          style={[styles.celebrationContent, celebrationAnimatedStyle]}
        >
          <Text style={styles.celebrationEmoji}>🎉</Text>
          <Text style={styles.celebrationTitle}>
            You hit {currentStreak} days! {hitMilestone?.badge}
          </Text>
          <Text style={styles.celebrationSubtext}>
            {hitMilestone?.name ?? 'Milestone achieved'}
          </Text>
          {nextAfterHit && (
            <Text style={styles.nextMilestoneText}>
              Next: {nextAfterHit.days} days {nextAfterHit.badge}
            </Text>
          )}
        </Animated.View>
      </Animated.View>
    );
  }

  // Render in-progress state
  return (
    <Animated.View
      accessibilityLabel={accessibilityLabel}
      accessibilityRole='progressbar'
      accessibilityValue={{
        max: 100,
        min: 0,
        now: progressPercentage,
      }}
      style={[styles.container, containerAnimatedStyle]}
      testID='milestone-progress'
    >
      {/* Header */}
      <View style={styles.header}>
        <View style={styles.headerLeft}>
          <Text style={styles.headerTitle}>
            Next Milestone: {nextMilestone?.days} Days
          </Text>
          <Animated.Text style={[styles.badgeIcon, badgeAnimatedStyle]}>
            {nextMilestone?.badge}
          </Animated.Text>
        </View>
        <Text style={styles.daysAway}>
          {daysRemaining} {daysRemaining === 1 ? 'day' : 'days'} away
        </Text>
      </View>

      {/* Milestone name */}
      <Text style={styles.milestoneName}>{nextMilestone?.name}</Text>

      {/* Progress bar */}
      <View style={styles.progressBarContainer}>
        {/* Background track */}
        <View style={styles.progressBarTrack}>
          {/* Filled progress */}
          <Animated.View
            style={[styles.progressBarFill, progressAnimatedStyle]}
          />
        </View>

        {/* Badge at end */}
        <Animated.View style={[styles.progressBadge, badgeAnimatedStyle]}>
          <Text style={styles.progressBadgeText}>{nextMilestone?.badge}</Text>
        </Animated.View>
      </View>

      {/* Progress label */}
      <View style={styles.progressLabel}>
        <Text style={styles.progressLabelText}>
          {previousMilestone ? `${previousMilestone.days}` : '0'}
        </Text>
        <Text style={styles.progressLabelText}>{currentStreak} days</Text>
        <Text style={styles.progressLabelText}>{nextMilestone?.days}</Text>
      </View>
    </Animated.View>
  );
});

