/**
 * ProgressSectionConsolidated Component
 *
 * Main container for the consolidated Progress tab content.
 * Combines all sub-components into a single unified card with
 * clear visual hierarchy: Hero → Insights → Pattern → Action
 *
 * This component replaces the separate YourProgressCard,
 * PersonalBestsCard, and ThisMonthCard with a unified design.
 *
 * Key improvements over the 3-card approach:
 * - Single neutral gradient theme (vs 3 different gradients)
 * - Hero section with clear primary metric
 * - Horizontal scroll insight chips (reduces vertical space)
 * - Compact weekly pattern chart
 * - Collapsible streak records
 * - ~35% reduction in vertical space
 *
 * @see docs/specs/habit-details-screen/progress-consolidated-redesign.md
 */

import React, { useMemo } from 'react';
import { View, Text } from 'react-native';
import Animated, { FadeInDown } from 'react-native-reanimated';

import type { ProgressSectionConsolidatedProps } from './types';
import {
  calculateDayOfWeekStats,
  calculateCurrentStreak,
  calculateStreakRecords,
  generateActionableTip,
  getBestAndWorstDays,
} from '../ProgressSection/utils';
import { calculateMonthlyChangeForStatsGrid } from '../../utils/trendCalculations';

import { StatsGrid } from './StatsGrid';
import { MilestoneProgress } from './MilestoneProgress';
import { WeeklyPatternChart } from './WeeklyPatternChart';
import { ActionableTipCard } from './ActionableTipCard';
import { StreakRecordsAccordion } from './StreakRecordsAccordion';

/**
 * ProgressSectionConsolidated Component
 *
 * Unified progress section that consolidates all progress information
 * into a single card with clear visual hierarchy.
 */
export function ProgressSectionConsolidated({
  tracking,
  habitCreatedAt,
  strength,
  weeklyChange = 0,
  onInfoPress: _onInfoPress, // Kept for backwards compatibility
  onFocusDayPress,
  onSeeAllPress,
  onTipPress,
  onTipQuickAction,
}: ProgressSectionConsolidatedProps) {
  // Convert habitCreatedAt string to timestamp for utils
  const habitCreatedTimestamp = useMemo(() => {
    if (!habitCreatedAt) return;
    try {
      return new Date(habitCreatedAt).getTime();
    } catch {
      return;
    }
  }, [habitCreatedAt]);

  // Calculate day of week statistics
  const dayStats = useMemo(
    () => calculateDayOfWeekStats(tracking, habitCreatedTimestamp),
    [tracking, habitCreatedTimestamp]
  );

  // Calculate current streak
  const currentStreak = useMemo(
    () => calculateCurrentStreak(tracking),
    [tracking]
  );

  // Calculate streak records for accordion
  const streakRecords = useMemo(
    () => calculateStreakRecords(tracking, currentStreak),
    [tracking, currentStreak]
  );

  // Calculate monthly change for trend indicator
  const monthlyChange = useMemo(
    () => calculateMonthlyChangeForStatsGrid(tracking),
    [tracking]
  );

  // Get best and worst performing days
  const { bestDay, worstDay } = useMemo(
    () => getBestAndWorstDays(dayStats),
    [dayStats]
  );

  // Generate actionable tip based on patterns
  const actionableTip = useMemo(
    () => generateActionableTip(dayStats, currentStreak),
    [dayStats, currentStreak]
  );

  // Calculate this month's completed/total days
  const { monthlyCompleted, monthlyTotal } = useMemo(() => {
    const today = new Date();
    const thisMonthStart = new Date(today.getFullYear(), today.getMonth(), 1);

    const completedDates = new Set(
      tracking.filter((t) => t.completed).map((t) => t.date)
    );

    let completed = 0;
    let total = 0;

    const current = new Date(thisMonthStart);
    while (current <= today) {
      total++;
      if (completedDates.has(current.toISOString().split('T')[0])) {
        completed++;
      }
      current.setDate(current.getDate() + 1);
    }

    return { monthlyCompleted: completed, monthlyTotal: total };
  }, [tracking]);

  // Determine if we have enough data to show detailed sections
  const hasEnoughData = tracking.length >= 7;

  // Format best/worst days for InsightChips
  const bestDayData = useMemo(() => {
    if (!bestDay) return null;
    return { name: bestDay.day, rate: bestDay.rate };
  }, [bestDay]);

  const focusDayData = useMemo(() => {
    if (!worstDay) return null;
    // Only show focus day if it's different from best day and below 70%
    if (bestDay && worstDay.dayIndex === bestDay.dayIndex) return null;
    if (worstDay.rate >= 70) return null;
    return { name: worstDay.day, rate: worstDay.rate };
  }, [worstDay, bestDay]);

  return (
    <Animated.View
      accessibilityLabel='Progress section'
      accessibilityRole='summary'
      entering={FadeInDown.delay(100).springify()}
    >
      {/* Unified Card Container */}
      <View
        className='overflow-hidden rounded-2xl p-4'
        style={{
          // Neutral gradient background: white → stone-50 → stone-100
          backgroundColor: '#ffffff',
          borderColor: 'rgba(214, 211, 209, 0.6)', // stone-300/60
          borderWidth: 1,
          // Subtle shadow
          elevation: 2,
          shadowColor: '#000',
          shadowOffset: { height: 1, width: 0 },
          shadowOpacity: 0.1,
          shadowRadius: 3,
        }}
      >
        {/* Section 1: Stats Grid (replaces HeroStrengthSection + InsightChips) */}
        {/* Phase 1 redesign: Compact 2x2 grid with embedded strength ring */}
        <StatsGrid
          bestDay={bestDayData}
          currentStreak={currentStreak}
          focusDay={focusDayData}
          monthlyChange={monthlyChange}
          monthlyCompleted={monthlyCompleted}
          monthlyTotal={monthlyTotal}
          strength={strength}
          weeklyChange={weeklyChange}
          onFocusDayPress={onFocusDayPress}
        />

        {/* Section 2: Milestone Progress (Phase 2 gamification) */}
        <MilestoneProgress currentStreak={currentStreak} />

        {/* Section 3: Weekly Pattern Chart (only with enough data) */}
        {hasEnoughData && (
          <WeeklyPatternChart
            dayStats={dayStats}
            onSeeAllPress={onSeeAllPress}
          />
        )}

        {/* Section 4: Actionable Tip with Quick Actions */}
        <ActionableTipCard
          currentStreak={currentStreak}
          subtitle={
            currentStreak > 0
              ? `${currentStreak} day streak${currentStreak === 1 ? '' : 's'} and counting!`
              : undefined
          }
          tip={actionableTip}
          onPress={onTipPress}
          onQuickAction={onTipQuickAction}
        />

        {/* Section 5: Streak Records Accordion (only with enough data) */}
        {hasEnoughData && (
          <StreakRecordsAccordion
            currentStreak={currentStreak}
            streakRecords={streakRecords}
          />
        )}
      </View>
    </Animated.View>
  );
}

export default ProgressSectionConsolidated;

/**
 * StatCard Component
 *
 * Individual stat card for the StatsGrid displaying a single metric
 * with icon, value, label, and optional trend indicator.
 *
 * Features:
 * - Color-coded backgrounds per stat type
 * - Staggered entrance animation
 * - Press animation for interactive cards
 * - Trend indicator badge
 * - Full accessibility support
 *
 * @see docs/specs/habit-details-screen/progress-tab-improvements-spec.md
 */

import React, { useEffect } from 'react';
import { View, Text, Pressable } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  withDelay,
  withSpring,
  Easing,
} from 'react-native-reanimated';
import { TrendingUp, TrendingDown } from 'lucide-react-native';

import { Springs } from '../../constants/motion';
import type { StatCardProps } from './StatsGridTypes';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

/** Stagger delay between card entrance animations (ms) */
const CARD_STAGGER_DELAY = 50;

/** Duration of card entrance animation (ms) */
const CARD_ENTRANCE_DURATION = 280;

/**
 * StatCard - Individual stat display card
 * Memoized to prevent unnecessary re-renders
 */
export const StatCard = React.memo(function StatCard({
  config,
  index,
  reduceMotion,
  isInteractive = false,
  onPress,
  onHapticFeedback,
}: StatCardProps) {
  // Entrance animation values
  const opacity = useSharedValue(reduceMotion ? 1 : 0);
  const scale = useSharedValue(reduceMotion ? 1 : 0.9);

  // Press animation
  const pressScale = useSharedValue(1);

  // Run entrance animation
  useEffect(() => {
    if (reduceMotion) {
      opacity.value = 1;
      scale.value = 1;
      return;
    }

    const delay = index * CARD_STAGGER_DELAY;

    opacity.value = withDelay(
      delay,
      withTiming(1, {
        duration: CARD_ENTRANCE_DURATION,
        easing: Easing.out(Easing.cubic),
      })
    );

    scale.value = withDelay(delay, withSpring(1, Springs.gentle));
  }, [index, reduceMotion, opacity, scale]);

  // Press handlers
  const handlePressIn = () => {
    if (!isInteractive) return;
    pressScale.value = withSpring(0.95, Springs.button);
  };

  const handlePressOut = () => {
    if (!isInteractive) return;
    pressScale.value = withSpring(1, Springs.button);
  };

  const handlePress = () => {
    if (!isInteractive || !onPress) return;
    onHapticFeedback();
    onPress();
  };

  // Animated styles
  const containerStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ scale: scale.value * pressScale.value }],
  }));

  // Trend indicator component
  const renderTrendIndicator = () => {
    if (!config.showTrend || config.trend === undefined || config.trend === 0) {
      return null;
    }

    const isPositive = config.trend > 0;
    const Icon = isPositive ? TrendingUp : TrendingDown;
    const color = isPositive ? '#16a34a' : '#dc2626'; // green-600 : red-600
    const bgColor = isPositive ? '#dcfce7' : '#fee2e2'; // green-100 : red-100
    const prefix = isPositive ? '+' : '';
    const label = config.id === 'monthly' ? '' : '%';

    return (
      <View
        accessibilityLabel={`${isPositive ? 'Up' : 'Down'} ${Math.abs(config.trend)}${label}`}
        className='ml-1 flex-row items-center rounded-full px-1.5 py-0.5'
        style={{ backgroundColor: bgColor }}
      >
        <Icon color={color} size={10} />
        <Text className='ml-0.5 text-[10px] font-medium' style={{ color }}>
          {prefix}
          {config.trend}
          {label}
        </Text>
      </View>
    );
  };

  const accessibilityLabel = `${config.label}: ${config.value}${
    config.showTrend && config.trend
      ? `, ${config.trend > 0 ? 'up' : 'down'} ${Math.abs(config.trend)}`
      : ''
  }`;

  const accessibilityHint = isInteractive
    ? 'Double tap to view details'
    : undefined;

  return (
    <AnimatedPressable
      accessibilityHint={accessibilityHint}
      accessibilityLabel={accessibilityLabel}
      accessibilityRole={isInteractive ? 'button' : 'text'}
      disabled={!isInteractive}
      style={containerStyle}
      onPress={handlePress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
    >
      <View
        className='flex-1 rounded-xl px-3 py-2'
        style={{
          backgroundColor: config.backgroundColor,
          minHeight: 60,
        }}
      >
        {/* Icon and Value row */}
        <View className='flex-row items-center'>
          <Text className='text-base'>{config.icon}</Text>
          <Text className='ml-1.5 text-base font-bold text-stone-900'>
            {config.value}
          </Text>
          {renderTrendIndicator()}
        </View>

        {/* Label */}
        <Text className='mt-0.5 text-xs text-stone-500'>{config.label}</Text>
      </View>
    </AnimatedPressable>
  );
});

export default StatCard;

/**
 * StatsGrid Component
 *
 * Compact 2x2 layout displaying key habit statistics with a strength ring.
 * Replaces the horizontal scroll InsightChips with a more scannable grid.
 *
 * Layout:
 * ┌─────────────┬─────────────────────────────┐
 * │             │  🔥 14      │  📅 18/21    │
 * │  Strength   │  Day Streak │  This Month  │
 * │    Ring     ├─────────────┼──────────────┤
 * │   (56px)    │  🏆 Tue     │  ⚡ Sat      │
 * │             │  Best Day   │  Focus Day   │
 * └─────────────┴─────────────────────────────┘
 *
 * Features:
 * - Compact 56px strength ring
 * - 4 color-coded stat cards in 2x2 grid
 * - Trend indicators on monthly and strength
 * - Staggered entrance animations
 * - Focus day is interactive
 * - Full accessibility support
 *
 * @see docs/specs/habit-details-screen/progress-tab-improvements-spec.md
 */

import React, { useMemo, useEffect } from 'react';
import { View } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
} from 'react-native-reanimated';

import { useHapticFeedback } from '../../hooks/useHapticFeedback';
import { useReduceMotion } from '../../hooks/useReduceMotion';
import { Springs } from '../../constants/motion';

import { CompactStrengthRing } from './CompactStrengthRing';
import { StatCard } from './StatCard';
import type { StatsGridProps, StatItemConfig } from './StatsGridTypes';
import { STAT_CARD_COLORS } from './StatsGridTypes';

/**
 * StatsGrid - Compact 2x2 statistics grid with strength ring
 * Memoized to prevent unnecessary re-renders
 */
export const StatsGrid = React.memo(function StatsGrid({
  strength,
  currentStreak,
  monthlyCompleted,
  monthlyTotal,
  bestDay,
  focusDay,
  weeklyChange = 0,
  monthlyChange,
  onFocusDayPress,
}: StatsGridProps) {
  const reduceMotion = useReduceMotion();
  const { triggerSelection } = useHapticFeedback();

  // Entrance animation for container
  const containerScale = useSharedValue(reduceMotion ? 1 : 0.95);

  useEffect(() => {
    if (reduceMotion) {
      containerScale.value = 1;
      return;
    }

    containerScale.value = withSpring(1, Springs.gentle);
  }, [reduceMotion, containerScale]);

  const containerStyle = useAnimatedStyle(() => ({
    transform: [{ scale: containerScale.value }],
  }));

  // Build stat cards configuration
  const statCards = useMemo<StatItemConfig[]>(() => {
    const cards: StatItemConfig[] = [];

    // Streak card (top-left of grid)
    cards.push(
      {
        backgroundColor: STAT_CARD_COLORS.streak.bgHex,
        icon: '🔥',
        id: 'streak',
        label: currentStreak === 1 ? 'Day Streak' : 'Day Streak',
        value: currentStreak === 1 ? '1' : `${currentStreak}`,
      },
      {
        backgroundColor: STAT_CARD_COLORS.monthly.bgHex,
        icon: '📅',
        id: 'monthly',
        label: 'This Month',
        showTrend: monthlyChange !== undefined && monthlyChange !== 0,
        trend: monthlyChange,
        value: `${monthlyCompleted}/${monthlyTotal}`,
      }
    );

    // Best Day card (bottom-left of grid)
    if (bestDay) {
      cards.push({
        backgroundColor: STAT_CARD_COLORS.bestDay.bgHex,
        icon: '🏆',

        id: 'bestDay',
        // Abbreviate to first 3 chars
        label: `Best Day (${Math.round(bestDay.rate)}%)`,
        value: bestDay.name.slice(0, 3),
      });
    }

    // Focus Day card (bottom-right of grid)
    if (focusDay) {
      cards.push({
        backgroundColor: STAT_CARD_COLORS.focusDay.bgHex,
        icon: '⚡',

        id: 'focusDay',
        // Abbreviate to first 3 chars
        label: `Focus Day (${Math.round(focusDay.rate)}%)`,
        value: focusDay.name.slice(0, 3),
      });
    }

    return cards;
  }, [
    currentStreak,
    monthlyCompleted,
    monthlyTotal,
    bestDay,
    focusDay,
    monthlyChange,
  ]);

  // Separate cards into rows for grid layout
  const topRowCards = statCards.slice(0, 2);
  const bottomRowCards = statCards.slice(2, 4);

  const accessibilityLabel = `Statistics overview: ${currentStreak} day streak, ${monthlyCompleted} of ${monthlyTotal} days this month${
    bestDay ? `, best day is ${bestDay.name}` : ''
  }${focusDay ? `, focus day is ${focusDay.name}` : ''}`;

  return (
    <Animated.View
      accessibilityLabel={accessibilityLabel}
      accessibilityRole='summary'
      className='mb-4'
      style={containerStyle}
    >
      <View className='flex-row'>
        {/* Left side: Compact Strength Ring */}
        <View className='mr-3 items-center justify-center'>
          <CompactStrengthRing
            strength={strength}
            weeklyChange={weeklyChange}
          />
        </View>

        {/* Right side: 2x2 Stats Grid */}
        <View className='flex-1'>
          {/* Top row */}
          <View className='mb-2 flex-row gap-2'>
            {topRowCards.map((card, index) => (
              <View key={card.id} className='flex-1'>
                <StatCard
                  config={card}
                  index={index}
                  isInteractive={false}
                  reduceMotion={reduceMotion}
                  onHapticFeedback={triggerSelection}
                />
              </View>
            ))}
          </View>

          {/* Bottom row */}
          <View className='flex-row gap-2'>
            {bottomRowCards.map((card, index) => (
              <View key={card.id} className='flex-1'>
                <StatCard
                  config={card}
                  index={index + 2} // Continue stagger from top row
                  isInteractive={card.id === 'focusDay' && !!onFocusDayPress}
                  reduceMotion={reduceMotion}
                  onHapticFeedback={triggerSelection}
                  onPress={card.id === 'focusDay' ? onFocusDayPress : undefined}
                />
              </View>
            ))}
          </View>
        </View>
      </View>
    </Animated.View>
  );
});

export default StatsGrid;

/**
 * StreakRecordsAccordion Component
 *
 * Collapsible section showing streak medal records.
 * Collapsed by default to reduce cognitive load.
 *
 * Features:
 * - Collapsed by default with medal preview (🥇6 🥈6 🥉2)
 * - Expand/collapse animation (height + opacity)
 * - Medal display when expanded (same as PersonalBestsCard medals)
 * - Current streak highlighted with pulse animation + "NOW 🔥" badge
 * - Accessibility announcements for state changes
 *
 * @see docs/specs/habit-details-screen/progress-consolidated-redesign.md
 */

import React, { useState, useCallback, useEffect, useMemo } from 'react';
import { View, Text, Pressable } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  withRepeat,
  withSequence,
  Easing,
  interpolate,
  runOnJS,
} from 'react-native-reanimated';
import { Ionicons } from '@expo/vector-icons';

import { useReduceMotion } from '../../hooks/useReduceMotion';
import { useHapticFeedback } from '../../hooks/useHapticFeedback';

import type { StreakRecordsAccordionProps } from './types';

/** Animation duration for expand/collapse (ms) */
const ANIMATION_DURATION = 250;

/** Medal configurations */
const MEDALS = ['🥇', '🥈', '🥉'] as const;
const MEDAL_COLORS = [
  {
    bg: '#fffbeb', // amber-50
    border: '#fde68a',
    // amber-700
    subtext: '#f59e0b',
    // amber-200
    text: '#b45309', // amber-500
  },
  {
    bg: '#fafaf9', // stone-50
    border: '#e7e5e4',
    // stone-700
    subtext: '#78716c',
    // stone-200
    text: '#44403c', // stone-500
  },
  {
    bg: '#fff7ed', // orange-50
    border: '#fed7aa',
    // orange-700
    subtext: '#f97316',
    // orange-200
    text: '#c2410c', // orange-500
  },
] as const;

/**
 * Format date for display (e.g., "Dec 1")
 */
function formatDate(dateString: string): string {
  try {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { day: 'numeric', month: 'short' });
  } catch {
    return dateString;
  }
}

/**
 * StreakRecordsAccordion Component
 *
 * Displays a collapsible section with streak medal records.
 * Memoized to prevent re-renders when parent updates unrelated props.
 */
export const StreakRecordsAccordion = React.memo(
  function StreakRecordsAccordion({
    streakRecords,
    currentStreak,
    defaultExpanded = false,
  }: StreakRecordsAccordionProps) {
    const reduceMotion = useReduceMotion();
    const { triggerSelection } = useHapticFeedback();

    const [isExpanded, setIsExpanded] = useState(defaultExpanded);
    const [contentHeight, setContentHeight] = useState(0);
    const [hasContentMeasured, setHasContentMeasured] = useState(false);

    // Animation values
    const expandProgress = useSharedValue(defaultExpanded ? 1 : 0);
    const chevronRotation = useSharedValue(defaultExpanded ? 180 : 0);

    // Pulse animation for current streak
    const pulseScale = useSharedValue(1);
    const pulseOpacity = useSharedValue(0.6);

    // Start pulse animation for current streak
    useEffect(() => {
      if (reduceMotion || currentStreak === 0) return;

      // 2000ms infinite pulse
      pulseScale.value = withRepeat(
        withSequence(
          withTiming(1.05, {
            duration: 1000,
            easing: Easing.inOut(Easing.ease),
          }),
          withTiming(1, { duration: 1000, easing: Easing.inOut(Easing.ease) })
        ),
        -1,
        true
      );

      pulseOpacity.value = withRepeat(
        withSequence(
          withTiming(1, { duration: 1000, easing: Easing.inOut(Easing.ease) }),
          withTiming(0.6, { duration: 1000, easing: Easing.inOut(Easing.ease) })
        ),
        -1,
        true
      );
    }, [currentStreak, reduceMotion, pulseScale, pulseOpacity]);

    // Handle content height measurement
    const handleContentLayout = useCallback((event: any) => {
      const { height } = event.nativeEvent.layout;
      if (height > 0) {
        setContentHeight(height);
        setHasContentMeasured(true);
      }
    }, []);

    // Toggle expand/collapse
    const handleToggle = useCallback(() => {
      triggerSelection();
      const newExpanded = !isExpanded;
      setIsExpanded(newExpanded);

      const duration = reduceMotion ? 0 : ANIMATION_DURATION;
      const targetValue = newExpanded ? 1 : 0;
      const chevronTarget = newExpanded ? 180 : 0;

      expandProgress.value = withTiming(targetValue, {
        duration,
        easing: Easing.out(Easing.ease),
      });

      chevronRotation.value = withTiming(chevronTarget, {
        duration,
        easing: Easing.out(Easing.ease),
      });
    }, [
      isExpanded,
      reduceMotion,
      triggerSelection,
      expandProgress,
      chevronRotation,
    ]);

    // Animated styles for content container
    const contentAnimatedStyle = useAnimatedStyle(() => {
      const height = interpolate(
        expandProgress.value,
        [0, 1],
        [0, contentHeight]
      );
      const opacity = expandProgress.value;

      return {
        height: hasContentMeasured ? height : 'auto',
        opacity,
        overflow: 'hidden',
      };
    });

    // Animated style for chevron rotation
    const chevronAnimatedStyle = useAnimatedStyle(() => ({
      // Round to avoid "Loss of precision during arithmetic conversion" error in Reanimated
      transform: [{ rotate: `${Math.round(chevronRotation.value)}deg` }],
    }));

    // Animated style for pulse effect on current streak
    const pulseAnimatedStyle = useAnimatedStyle(() => ({
      opacity: pulseOpacity.value,
      transform: [{ scale: pulseScale.value }],
    }));

    // Memoize top 3 records to avoid recalculation
    const top3Records = useMemo(
      () => streakRecords.slice(0, 3),
      [streakRecords]
    );
    const hasRecords = top3Records.length > 0;

    // Memoize preview text generation
    const previewText = useMemo(
      () =>
        top3Records.map((record, i) => `${MEDALS[i]}${record.days}`).join(' '),
      [top3Records]
    );

    // Memoize accessibility label generation
    const accessibilityLabel = useMemo(
      () =>
        hasRecords
