                    </Text>
                    <Text
                      className='text-lg font-bold'
                      style={{ color: '#d6d3d1' }} // stone-300
                    >
                      -
                    </Text>
                    <Text
                      className='text-[9px]'
                      style={{ color: '#d6d3d1' }} // stone-300
                    >
                      days
                    </Text>
                  </View>
