/**
 * TipQuickActionsSheet Types
 *
 * Type definitions for the tip quick actions bottom sheet component.
 * This sheet provides contextual quick actions based on the tip type
 * to help users take immediate action on their habits.
 *
 * @see docs/specs/habit-details-screen/progress-tab-improvements-spec.md
 */

/**
 * Types of tips that can be displayed in the ActionableTipCard
 * Each type corresponds to different quick actions
 */
export type TipType =
  | 'focusDay' // Tip about weak day performance (e.g., "Focus on Saturday")
  | 'lowStreak' // Tip about building/maintaining streaks
  | 'goodStreak' // Encouraging tip when streak is going well
  | 'weekStreak' // Tip about reaching 7-day milestone
  | 'noData'; // Default tip when insufficient data

/**
 * Quick action configuration
 */
export interface QuickAction {
  /** Unique identifier for the action */
  id: string;
  /** Display label for the action */
  label: string;
  /** Icon name from lucide-react-native */
  icon: 'bell' | 'edit-3' | 'calendar' | 'target' | 'heart' | 'zap';
  /** Optional subtitle with additional context */
  subtitle?: string;
  /** Action type for tracking/handling */
  actionType:
    | 'setReminder'
    | 'editHabit'
    | 'viewHistory'
    | 'reviewWhy'
    | 'makeSmaller'
    | 'celebrate';
  /** Optional extra data for the action */
  data?: Record<string, unknown>;
}

/**
 * Props for the TipQuickActionsSheet component
 */
export interface TipQuickActionsSheetProps {
  /** Whether the sheet is visible */
  visible: boolean;
  /** The tip text being displayed */
  tipText: string;
  /** The type of tip for determining available actions */
  tipType: TipType;
  /** Day name for focus day tips (e.g., "Saturday") */
  focusDayName?: string;
  /** Current streak count for context */
  currentStreak?: number;
  /** Callback when an action is selected */
  onActionPress: (action: QuickAction) => void;
  /** Callback when the sheet is closed */
  onClose: () => void;
}

/**
 * Get quick actions based on tip type
 */
export function getQuickActionsForTipType(
  tipType: TipType,
  focusDayName?: string,
  currentStreak?: number
): QuickAction[] {
  switch (tipType) {
    case 'focusDay': {
      return [
        {
          actionType: 'setReminder',
          data: { dayName: focusDayName },
          icon: 'bell',
          id: 'set-reminder',
          label: `Set ${focusDayName || 'day'} reminder`,
          subtitle: 'Get a notification to stay on track',
        },
        {
          actionType: 'makeSmaller',
          data: { dayName: focusDayName },
          icon: 'edit-3',
          id: 'make-smaller',
          label: `Make habit easier on ${focusDayName || 'this day'}`,
          subtitle: 'Adjust to a smaller version for tough days',
        },
        {
          actionType: 'viewHistory',
          data: { dayName: focusDayName },
          icon: 'calendar',
          id: 'view-history',
          label: `View ${focusDayName || 'day'} history`,
          subtitle: 'See your pattern on this day',
        },
      ];
    }

    case 'lowStreak': {
      return [
        {
          actionType: 'setReminder',
          icon: 'bell',
          id: 'set-daily-reminder',
          label: 'Set daily reminder',
          subtitle: 'Never forget with a daily nudge',
        },
        {
          actionType: 'makeSmaller',
          icon: 'zap',
          id: 'try-smaller',
          label: 'Try a smaller version',
          subtitle: 'Start with 2 minutes to build momentum',
        },
        {
          actionType: 'reviewWhy',
          icon: 'heart',
          id: 'review-why',
          label: 'Review your why',
          subtitle: 'Reconnect with your motivation',
        },
      ];
    }

    case 'goodStreak': {
      return [
        {
          actionType: 'celebrate',
          icon: 'zap',
          id: 'keep-going',
          label: 'Keep the momentum!',
          subtitle: `${currentStreak || 0} days strong!`,
        },
        {
          actionType: 'setReminder',
          icon: 'bell',
          id: 'set-reminder',
          label: "Ensure you don't miss tomorrow",
          subtitle: 'Set a reminder to stay consistent',
        },
      ];
    }

    case 'weekStreak': {
      return [
        {
          actionType: 'celebrate',
          icon: 'zap',
          id: 'celebrate',
          label: 'Celebrate your progress!',
          subtitle: 'A week streak is a major milestone',
        },
        {
          actionType: 'editHabit',
          icon: 'target',
          id: 'set-target',
          label: 'Set a new goal',
          subtitle: 'Aim for 14 days next!',
        },
      ];
    }

    default: {
      return [
        {
          actionType: 'celebrate',
          icon: 'zap',
          id: 'complete-today',
          label: 'Complete today to start',
          subtitle: 'Your first step toward building a habit',
        },
        {
          actionType: 'setReminder',
          icon: 'bell',
          id: 'set-reminder',
          label: 'Set a reminder',
          subtitle: 'Get notified at the right time',
        },
      ];
    }
  }
}

/**
 * Determine tip type from tip text
 * Parses the actionable tip message to determine which quick actions to show
 */
export function determineTipTypeFromText(
  tipText: string,
  currentStreak: number
): { tipType: TipType; focusDayName?: string } {
  // Focus day pattern: "Focus on X & Y to level up!" or "Focus on X to level up!"
  const focusDayMatch = tipText.match(
    /Focus on ([A-Za-z]+(?:\s*&\s*[A-Za-z]+)?)/i
  );
  if (focusDayMatch) {
    // Extract first day name if multiple (e.g., "Sat & Sun" -> "Sat")
    const dayPart = focusDayMatch[1].split('&')[0].trim();
    return { focusDayName: dayPart, tipType: 'focusDay' };
  }

  // Good streak pattern: "Amazing streak!" or similar
  if (
    tipText.toLowerCase().includes('amazing streak') ||
    tipText.toLowerCase().includes('keep the momentum')
  ) {
    return { tipType: 'goodStreak' };
  }

  // Week streak pattern: "more days to hit a week streak"
  if (tipText.toLowerCase().includes('week streak')) {
    return { tipType: 'weekStreak' };
  }

  // Low/no streak pattern: "Complete today to start"
  if (
    tipText.toLowerCase().includes('complete today') ||
    tipText.toLowerCase().includes('start a new streak')
  ) {
    return { tipType: currentStreak > 0 ? 'lowStreak' : 'noData' };
  }

  // Default to low streak if there's any tip but no streak
  if (currentStreak === 0) {
    return { tipType: 'noData' };
  }

  return { tipType: 'lowStreak' };
}

/**
 * TodaysFocusCard Component
 *
 * Provides immediate, contextual motivation at the top of Progress tab.
 * Displays different states based on user's current progress and streak.
 *
 * @see docs/specs/habit-details-screen/progress-tab-improvements-spec.md
 */

import React from 'react';
import { View } from 'react-native';
import Animated from 'react-native-reanimated';
import { LinearGradient } from 'expo-linear-gradient';

import { useReduceMotion } from '../../../hooks/useReduceMotion';
import type { TodaysFocusCardProps } from '../TodaysFocusCardTypes';

import { styles } from './TodaysFocusCard.styles';
import { ConfettiBurst } from './components/ConfettiBurst';
import { FocusIcon } from './components/FocusIcon';
import { FocusTextContent } from './components/FocusTextContent';
import { ShareButton } from './components/ShareButton';
import { DismissButton } from './components/DismissButton';
import {
  useFocusState,
  useFocusAnimations,
  useCelebrationEffects,
} from './hooks';

export const TodaysFocusCard = React.memo(function TodaysFocusCard(
  props: TodaysFocusCardProps
) {
  const { currentStreak, onMilestoneCelebrated, onShare } = props;
  const reduceMotion = useReduceMotion();

  const focusStateResult = useFocusState(props);
  const animations = useFocusAnimations(reduceMotion);
  const celebration = useCelebrationEffects(
    focusStateResult.focusState,
    reduceMotion,
    animations.badgeScale,
    animations.shareButtonOpacity,
    currentStreak,
    onMilestoneCelebrated,
    onShare
  );

  const { focusState, config, celebrationConfig } = focusStateResult;

  return (
    <Animated.View
      accessibilityLabel={focusStateResult.accessibilityLabel}
      accessibilityRole='text'
      style={[styles.container, animations.containerAnimatedStyle]}
    >
      <ConfettiBurst isActive={celebration.showConfetti} />
      <LinearGradient
        colors={config.gradientColors}
        end={{ x: 1, y: 1 }}
        start={{ x: 0, y: 0 }}
        style={styles.gradient}
      >
        {!reduceMotion && (
          <Animated.View
            style={[styles.shimmerOverlay, animations.shimmerAnimatedStyle]}
          >
            <LinearGradient
              colors={['transparent', 'rgba(255,255,255,0.4)', 'transparent']}
              end={{ x: 1, y: 0.5 }}
              start={{ x: 0, y: 0.5 }}
              style={styles.shimmerGradient}
            />
          </Animated.View>
        )}

        <View style={styles.content}>
          <FocusIcon
            badgeAnimatedStyle={animations.badgeAnimatedStyle}
            celebrationConfig={celebrationConfig}
            config={config}
            focusState={focusState}
          />
          <FocusTextContent {...focusStateResult} reduceMotion={reduceMotion} />
          <ShareButton
            focusState={focusState}
            iconColor={config.iconColor}
            shareButtonAnimatedStyle={animations.shareButtonAnimatedStyle}
            onPress={celebration.handleSharePress}
            onShare={onShare}
          />
        </View>

        <DismissButton
          focusState={focusState}
          subTextColor={config.subTextColor}
          onMilestoneCelebrated={onMilestoneCelebrated}
          onPress={celebration.handleCelebrationAcknowledge}
        />
      </LinearGradient>
    </Animated.View>
  );
});

export default TodaysFocusCard;

/**
 * ConfettiParticle Component
 *
 * A single confetti particle with its own animated values.
 * Used by ConfettiBurst to create the celebration effect.
 */

import React, { useEffect } from 'react';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  withSequence,
  withDelay,
  Easing,
} from 'react-native-reanimated';

import { styles } from '../TodaysFocusCard.styles';

export interface ConfettiParticleProps {
  angle: number;
  color: string;
  delay: number;
  distance: number;
  isActive: boolean;
  size: number;
}

export const ConfettiParticle = React.memo(function ConfettiParticle({
  angle,
  color,
  delay,
  distance,
  isActive,
  size,
}: ConfettiParticleProps) {
  const opacity = useSharedValue(0);
  const scale = useSharedValue(0);
  const translateX = useSharedValue(0);
  const translateY = useSharedValue(0);

  useEffect(() => {
    if (isActive) {
      // Round to avoid "Loss of precision during arithmetic conversion" error
      const targetX = Math.round(Math.cos(angle) * distance);
      const targetY = Math.round(Math.sin(angle) * distance) - 30; // Bias upward

      // Reset to center
      translateX.value = 0;
      translateY.value = 0;
      scale.value = 0;
      opacity.value = 0;

      // Animate outward with spring physics
      translateX.value = withDelay(
        delay,
        withSpring(targetX, { damping: 12, mass: 1, stiffness: 200 })
      );
      translateY.value = withDelay(
        delay,
        withSpring(targetY, { damping: 12, mass: 1, stiffness: 200 })
      );
      scale.value = withDelay(
        delay,
        withSequence(
          withSpring(1.3, { damping: 8, stiffness: 300 }),
          withTiming(0, { duration: 400, easing: Easing.out(Easing.ease) })
        )
      );
      opacity.value = withDelay(
        delay,
        withSequence(
          withTiming(1, { duration: 50 }),
          withDelay(
            250,
            withTiming(0, { duration: 350, easing: Easing.out(Easing.ease) })
          )
        )
      );
    }
  }, [
    isActive,
    angle,
    delay,
    distance,
    opacity,
    scale,
    translateX,
    translateY,
  ]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [
      { translateX: translateX.value },
      { translateY: translateY.value },
      { scale: scale.value },
    ],
  }));

  return (
    <Animated.View
      style={[
        styles.confettiParticle,
        {
          backgroundColor: color,
          borderRadius: size / 2,
          height: size,
          width: size,
        },
        animatedStyle,
      ]}
    />
  );
});

export default ConfettiParticle;

/**
 * useCelebrationEffects Hook
 *
 * Handles celebration state animations and confetti effects.
 */

import { useEffect, useState, useCallback } from 'react';
import {
  withSpring,
  withTiming,
  withSequence,
  withDelay,
  SharedValue,
} from 'react-native-reanimated';
import * as Haptics from 'expo-haptics';

import type { FocusState } from '../../TodaysFocusCardTypes';
import { CONFETTI_DURATION } from '../TodaysFocusCard.constants';

export interface UseCelebrationEffectsResult {
  showConfetti: boolean;
  handleCelebrationAcknowledge: () => void;
  handleSharePress: () => void;
}

export function useCelebrationEffects(
  focusState: FocusState,
  reduceMotion: boolean,
  badgeScale: SharedValue<number>,
  shareButtonOpacity: SharedValue<number>,
  currentStreak: number,
  onMilestoneCelebrated?: (milestone: number) => void,
  onShare?: () => void
): UseCelebrationEffectsResult {
  const [showConfetti, setShowConfetti] = useState(false);

  useEffect(() => {
    if (focusState === 'celebrating' && !reduceMotion) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy);
      setShowConfetti(true);
      const timer = setTimeout(() => setShowConfetti(false), CONFETTI_DURATION);

      badgeScale.value = withSequence(
        withSpring(1.4, { damping: 8, stiffness: 200 }),
        withSpring(1, { damping: 12, stiffness: 150 })
      );
      shareButtonOpacity.value = withDelay(
        400,
        withTiming(1, { duration: 300 })
      );

      return () => clearTimeout(timer);
    } else if (focusState === 'celebrating' && reduceMotion) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
      badgeScale.value = 1;
      shareButtonOpacity.value = 1;
    }
  }, [focusState, reduceMotion, badgeScale, shareButtonOpacity]);

  const handleCelebrationAcknowledge = useCallback(() => {
    if (focusState === 'celebrating' && onMilestoneCelebrated) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      onMilestoneCelebrated(currentStreak);
    }
  }, [focusState, currentStreak, onMilestoneCelebrated]);

  const handleSharePress = useCallback(() => {
    if (onShare) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
      onShare();
    }
  }, [onShare]);

  return {
    handleCelebrationAcknowledge,
    handleSharePress,
    showConfetti,
  };
}

/**
 * useFocusAnimations Hook
 *
 * Animation hooks for entrance, shimmer, celebration, and badge effects.
 */

import { useEffect } from 'react';
import {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  withRepeat,
  withSequence,
  withDelay,
  Easing,
  interpolate,
  SharedValue,
} from 'react-native-reanimated';

import { Springs } from '../../../../constants/motion';
import {
  ENTRANCE_DURATION,
  SHIMMER_DURATION,
} from '../TodaysFocusCard.constants';

export interface UseFocusAnimationsResult {
  scale: SharedValue<number>;
  opacity: SharedValue<number>;
  shimmerPosition: SharedValue<number>;
  badgeScale: SharedValue<number>;
  shareButtonOpacity: SharedValue<number>;
  containerAnimatedStyle: ReturnType<typeof useAnimatedStyle>;
  shimmerAnimatedStyle: ReturnType<typeof useAnimatedStyle>;
  badgeAnimatedStyle: ReturnType<typeof useAnimatedStyle>;
  shareButtonAnimatedStyle: ReturnType<typeof useAnimatedStyle>;
}

export function useFocusAnimations(
  reduceMotion: boolean
): UseFocusAnimationsResult {
  const scale = useSharedValue(reduceMotion ? 1 : 0.95);
  const opacity = useSharedValue(reduceMotion ? 1 : 0);
  const shimmerPosition = useSharedValue(0);
  const badgeScale = useSharedValue(0);
  const shareButtonOpacity = useSharedValue(0);

  // Entrance animation
  useEffect(() => {
    if (reduceMotion) {
      scale.value = 1;
      opacity.value = 1;
      return;
    }

    scale.value = withSpring(1, {
      ...Springs.gentle,
      damping: 20,
      stiffness: 200,
    });
    opacity.value = withTiming(1, {
      duration: ENTRANCE_DURATION,
      easing: Easing.out(Easing.cubic),
    });
  }, [reduceMotion, scale, opacity]);

  // Shimmer animation
  useEffect(() => {
    if (reduceMotion) return;

    shimmerPosition.value = withRepeat(
      withSequence(
        withTiming(1, {
          duration: SHIMMER_DURATION,
          easing: Easing.inOut(Easing.ease),
        }),
        withTiming(0, { duration: 0 })
      ),
      -1,
      false
    );
  }, [reduceMotion, shimmerPosition]);

  // Animated styles
  const containerAnimatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ scale: scale.value }],
  }));

  const shimmerAnimatedStyle = useAnimatedStyle(() => ({
    opacity: interpolate(shimmerPosition.value, [0, 0.5, 1], [0, 0.3, 0]),
    transform: [
      { translateX: interpolate(shimmerPosition.value, [0, 1], [-200, 400]) },
    ],
  }));

  const badgeAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: badgeScale.value }],
  }));

  const shareButtonAnimatedStyle = useAnimatedStyle(() => ({
    opacity: shareButtonOpacity.value,
  }));

  return {
    badgeAnimatedStyle,
    badgeScale,
    containerAnimatedStyle,
    opacity,
    scale,
    shareButtonAnimatedStyle,
    shareButtonOpacity,
    shimmerAnimatedStyle,
    shimmerPosition,
  };
}

/**
 * useFocusState Hook
 *
 * Computes the focus state, goal values, and accessibility labels.
 */

import { useMemo } from 'react';

import type {
  TodaysFocusCardProps,
  FocusState,
} from '../../TodaysFocusCardTypes';
import {
  getCelebrationMilestone,
  getNextCelebrationMilestone,
} from '../../TodaysFocusCardTypes';
import {
  determineFocusState,
  calculateGoalValue,
} from '../TodaysFocusCard.utils';
import { FOCUS_STATE_CONFIGS } from '../TodaysFocusCard.constants';

export interface UseFocusStateResult {
  focusState: FocusState;
  config: (typeof FOCUS_STATE_CONFIGS)[FocusState];
  goalValue: number;
  goalLabel: string;
  message: string;
  celebrationConfig: ReturnType<typeof getCelebrationMilestone>;
  celebrationSubtext: string | null;
  nextMilestoneLabel: string | null;
  accessibilityLabel: string;
}

export function useFocusState(
  props: TodaysFocusCardProps
): UseFocusStateResult {
  const { currentStreak, bestStreak, celebratedMilestones = [] } = props;

  const focusState = useMemo(
    () => determineFocusState(props, celebratedMilestones),
    [props, celebratedMilestones]
  );

  const celebrationConfig = useMemo(
    () =>
      focusState === 'celebrating'
        ? getCelebrationMilestone(currentStreak)
        : null,
    [focusState, currentStreak]
  );

  const config = FOCUS_STATE_CONFIGS[focusState];
  const goalValue = useMemo(
    () => calculateGoalValue(focusState, props),
    [focusState, props]
  );

  const message = useMemo(() => {
    switch (focusState) {
      case 'thriving': {
        return config.getMessage(goalValue);
      }
      case 'building':
      case 'completed':
      case 'celebrating': {
        return config.getMessage(currentStreak);
      }
      case 'recovering': {
        return config.getMessage(bestStreak);
      }
      default: {
        return config.getMessage(0);
      }
    }
  }, [focusState, config, goalValue, currentStreak, bestStreak]);

  const goalLabel = config.getGoalLabel();

  const celebrationSubtext = useMemo(() => {
    if (focusState === 'celebrating' && celebrationConfig) {
      return celebrationConfig.subtext;
    }
    return null;
  }, [focusState, celebrationConfig]);

  const nextMilestoneLabel = useMemo(() => {
    if (focusState === 'celebrating') {
      const nextMilestone = getNextCelebrationMilestone(currentStreak);
      if (nextMilestone) {
        return `Next: ${nextMilestone.days} days ${nextMilestone.badge}`;
      }
    }
    return null;
  }, [focusState, currentStreak]);

  const accessibilityLabel =
    focusState === 'celebrating'
      ? `Milestone celebration: ${message}. ${celebrationSubtext ?? ''}. Next goal: ${goalValue} days`
      : `Today's focus: ${message}. Goal: ${goalValue} ${goalLabel}`;

  return {
    accessibilityLabel,
    celebrationConfig,
    celebrationSubtext,
    config,
    focusState,
    goalLabel,
    goalValue,
    message,
    nextMilestoneLabel,
  };
}

/**
 * TodaysFocusCard Types
 *
 * Type definitions for the Today's Focus Card component.
 * This component provides contextual motivation at the top of Progress tab.
 *
 * @see docs/specs/habit-details-screen/progress-tab-improvements-spec.md
 */

/**
 * Focus states for the Today's Focus Card
 *
 * Each state represents a different user context with specific messaging
 * and visual treatment:
 *
 * - thriving: streak ≥ 7, weekly ≥ 5 (emerald→teal gradient)
 * - building: streak 3-6 (teal→cyan gradient)
 * - starting: habitAge < 7 (blue→indigo gradient)
 * - struggling: streak = 0, weekly < 3 (amber→orange gradient)
 * - recovering: streak = 0, bestStreak > 7 (violet→purple gradient)
 * - completed: isCompletedToday = true (green→emerald gradient)
 * - celebrating: Just hit a milestone (gold→amber gradient with confetti)
 */
export type FocusState =
  | 'thriving'
  | 'building'
  | 'starting'
  | 'struggling'
  | 'recovering'
  | 'completed'
  | 'celebrating';

/**
 * Configuration for each focus state
 */
export interface FocusStateConfig {
  /** Gradient colors [start, end] */
  gradientColors: [string, string];
  /** Ionicons icon name */
  icon: string;
  /** Icon color */
  iconColor: string;
  /** Primary text color */
  textColor: string;
  /** Secondary text color */
  subTextColor: string;
  /** Function to generate message based on goal/streak value */
  getMessage: (value: number) => string;
  /** Function to get goal label */
  getGoalLabel: () => string;
}

/**
 * Props for TodaysFocusCard component
 *
 * @example
 * ```tsx
 * <TodaysFocusCard
 *   currentStreak={14}
 *   isCompletedToday={false}
 *   weeklyCompletion={6}
 *   habitAge={30}
 *   bestStreak={21}
 *   celebratedMilestones={[7, 14]}
 *   onMilestoneCelebrated={(milestone) => console.log(`Celebrated ${milestone}`)}
 * />
 * ```
 */
export interface TodaysFocusCardProps {
  /** Current streak in days (0 if no active streak) */
  currentStreak: number;

  /** Whether the habit has been completed today */
  isCompletedToday: boolean;

  /** Number of days completed this week (0-7) */
  weeklyCompletion: number;

  /** Age of the habit in days since creation */
  habitAge: number;

  /** Best streak ever achieved in days */
  bestStreak: number;

  /** Array of milestones that have already been celebrated (to avoid re-celebrating) */
  celebratedMilestones?: number[];

  /** Callback when a milestone celebration is acknowledged */
  onMilestoneCelebrated?: (milestone: number) => void;

  /** Optional callback when share button is pressed during celebration */
  onShare?: () => void;
}

/**
 * Milestone thresholds for goal calculation
 */
export const MILESTONE_THRESHOLDS = [
  3, 7, 14, 21, 30, 60, 90, 100, 365,
] as const;

/**
 * Type for milestone values
 */
export type MilestoneValue = (typeof MILESTONE_THRESHOLDS)[number];

/**
 * Milestone configuration for celebrations
 */
export interface MilestoneCelebrationConfig {
  /** Number of days for this milestone */
  days: number;
  /** Badge emoji for this milestone */
  badge: string;
  /** Display name for this milestone */
  name: string;
  /** Celebration message */
  message: string;
  /** Subtext for encouragement */
  subtext: string;
}

/**
 * Celebration milestone configurations
 */
export const CELEBRATION_MILESTONES: MilestoneCelebrationConfig[] = [
  {
    badge: '⚡',
    days: 3,
    message: '🎉 You hit 3 days!',
    name: 'Habit Starter',
    subtext: "You're building momentum!",
  },
  {
    badge: '⭐',
    days: 7,
    message: '🎉 You hit 7 days!',
    name: 'Week Warrior',
    subtext: 'A whole week strong!',
  },
  {
    badge: '🔥',
    days: 14,
    message: '🎉 You hit 14 days!',
    name: 'Two Week Titan',
    subtext: 'Two weeks of consistency!',
  },
  {
    badge: '🏅',
    days: 21,
    message: '🎉 You hit 21 days!',
    name: 'Habit Builder',
    subtext: "You're building a real habit!",
  },
  {
    badge: '🏆',
    days: 30,
    message: '🎉 You hit 30 days!',
    name: 'Monthly Master',
    subtext: 'A full month - incredible!',
  },
  {
    badge: '💎',
    days: 60,
    message: '🎉 You hit 60 days!',
    name: 'Two Month Diamond',
    subtext: 'Diamond-level dedication!',
  },
  {
    badge: '🌟',
    days: 90,
    message: '🎉 You hit 90 days!',
    name: 'Quarterly Legend',
    subtext: 'A quarter year of excellence!',
  },
  {
    badge: '💯',
    days: 100,
    message: '🎉 You hit 100 days!',
    name: 'Century Club',
    subtext: 'Welcome to the Century Club!',
  },
  {
    badge: '👑',
    days: 365,
    message: '🎉 You hit 365 days!',
    name: 'Year Hero',
    subtext: "A whole year - you're legendary!",
  },
];

/**
 * Gets the celebration milestone config for a given streak
 */
export function getCelebrationMilestone(
  currentStreak: number
): MilestoneCelebrationConfig | null {
  return CELEBRATION_MILESTONES.find((m) => m.days === currentStreak) ?? null;
}

/**
 * Gets the next milestone after the current streak
 */
export function getNextCelebrationMilestone(
  currentStreak: number
): MilestoneCelebrationConfig | null {
  return CELEBRATION_MILESTONES.find((m) => m.days > currentStreak) ?? null;
}

