/**
 * QuickStatsStrip Component
 * Displays 3 key habit metrics: streak, strength, success rate
 * Features animated counting on load with staggered timing
 */

import React, { useEffect, useState, useRef } from 'react';
import { View, Text, Pressable, AccessibilityInfo } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';
import * as Haptics from 'expo-haptics';

export interface QuickStatsStripProps {
  /** Key to trigger animation replay (e.g., increment when modal opens) */
  animationKey?: number;
  currentStreak: number;
  habitStrength: number;
  onStatPress?: (statType: 'streak' | 'strength' | 'success') => void;
  successRate: number;
}

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

// Animation constants
const ANIMATION_DURATION = 800;
const STAGGER_DELAY = 100;

interface StatCardProps {
  accessibilityHint?: string;
  animationKey?: number;
  color: string;
  delay: number;
  emoji: string;
  label: string;
  onPress?: () => void;
  reduceMotion: boolean;
  suffix?: string;
  targetValue: number;
}

function StatCard({
  accessibilityHint,
  animationKey,
  color,
  delay,
  emoji,
  label,
  onPress,
  reduceMotion,
  suffix = '',
  targetValue,
}: StatCardProps) {
  const scale = useSharedValue(1);
  const [displayValue, setDisplayValue] = useState(targetValue);

  // Track which animationKey we last animated for, and with what final value
  const animatedForKey = useRef<string | null>(null);

  // Counting animation - triggers when we have a new animationKey AND valid targetValue
  useEffect(() => {
    // Create a unique key combining animationKey and whether we have real data
    const currentKey = `${animationKey}-${targetValue > 0}`;

    // Skip if reduce motion or no animationKey
    if (reduceMotion || animationKey === undefined) {
      setDisplayValue(targetValue);
      return;
    }

    // Skip if targetValue is 0 (waiting for data)
    if (targetValue === 0) {
      setDisplayValue(0);
      return;
    }

    // Skip if we already animated for this exact scenario
    if (animatedForKey.current === currentKey) {
      return;
    }

    // Mark this scenario as animated
    animatedForKey.current = currentKey;

    // Reset to 0 and animate
    setDisplayValue(0);

    const startTime = Date.now() + delay + 50;

    const interval = setInterval(() => {
      const now = Date.now();

      if (now < startTime) {
        return;
      }

      const elapsed = now - startTime;
      const progress = Math.min(elapsed / ANIMATION_DURATION, 1);

      // Cubic ease-out
      const easedProgress = 1 - Math.pow(1 - progress, 3);
      const currentValue = Math.round(easedProgress * targetValue);

      setDisplayValue(currentValue);

      if (progress >= 1) {
        clearInterval(interval);
        setDisplayValue(targetValue);
      }
    }, 16);

    return () => clearInterval(interval);
  }, [animationKey, targetValue, delay, reduceMotion, label]);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  const handlePressIn = () => {
    scale.value = withSpring(0.95, { damping: 15, stiffness: 300 });
  };

  const handlePressOut = () => {
    scale.value = withSpring(1, { damping: 15, stiffness: 300 });
  };

  const handlePress = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onPress?.();
  };

  return (
    <AnimatedPressable
      accessibilityHint={accessibilityHint}
      accessibilityLabel={`${label}: ${targetValue}${suffix}`}
      accessibilityRole="button"
      className="flex-1 items-center rounded-xl bg-white p-3 shadow-sm shadow-stone-200/50"
      onPress={handlePress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
      style={animatedStyle}
    >
      <Text
        className={`text-2xl font-bold ${color}`}
        accessibilityElementsHidden
      >
        {displayValue}{suffix}
      </Text>
      <View className="flex-row items-center gap-1" accessibilityElementsHidden>
        <Text className="text-xs">{emoji}</Text>
        <Text className="text-xs text-stone-500">{label}</Text>
      </View>
    </AnimatedPressable>
  );
}

export function QuickStatsStrip({
  animationKey,
  currentStreak,
  habitStrength,
  onStatPress,
  successRate,
}: QuickStatsStripProps) {
  // Track reduce motion preference
  const [reduceMotion, setReduceMotion] = useState(false);

  useEffect(() => {
    AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
    const subscription = AccessibilityInfo.addEventListener(
      'reduceMotionChanged',
      setReduceMotion
    );
    return () => subscription?.remove();
  }, []);

  return (
    <View
      accessible
      accessibilityLabel="Habit statistics"
      className="flex-row gap-2"
    >
      <StatCard
        accessibilityHint="Opens streak details"
        animationKey={animationKey}
        color="text-orange-500"
        delay={0}
        emoji="🔥"
        label="streak"
        onPress={() => onStatPress?.('streak')}
        reduceMotion={reduceMotion}
        targetValue={currentStreak}
      />
      <StatCard
        accessibilityHint="Opens habit strength details"
        animationKey={animationKey}
        color="text-violet-500"
        delay={STAGGER_DELAY}
        emoji="💪"
        label="strength"
        onPress={() => onStatPress?.('strength')}
        reduceMotion={reduceMotion}
        suffix="%"
        targetValue={Math.round(habitStrength * 100)}
      />
      <StatCard
        accessibilityHint="Opens success rate details"
        animationKey={animationKey}
        color="text-emerald-500"
        delay={STAGGER_DELAY * 2}
        emoji="✓"
        label="success"
        onPress={() => onStatPress?.('success')}
        reduceMotion={reduceMotion}
        suffix="%"
        targetValue={Math.round(successRate)}
      />
    </View>
  );
}

export default QuickStatsStrip;

import { useEffect, useMemo, useRef } from 'react';
import { Animated, Easing, Pressable, Text, View } from 'react-native';
import { useHapticFeedback } from '../hooks/useHapticFeedback';

interface RewardCelebrationToastProps {
  message: string;
  onDismiss: () => void;
  onPrimaryAction: () => void;
  onSecondaryAction: () => void;
  streak?: number;
  visible: boolean;
}

const AnimatedContainer = Animated.createAnimatedComponent(View);

export const RewardCelebrationToast = ({
  message,
  onDismiss,
  onPrimaryAction,
  onSecondaryAction,
  streak,
  visible,
}: RewardCelebrationToastProps) => {
  const translateY = useRef(new Animated.Value(160)).current;
  const opacity = useRef(new Animated.Value(0)).current;
  const { triggerSelection, triggerLightImpact } = useHapticFeedback({});

  useEffect(() => {
    if (visible) {
      Animated.parallel([
        Animated.timing(translateY, {
          duration: 280,
          easing: Easing.out(Easing.cubic),
          toValue: 0,
          useNativeDriver: true,
        }),
        Animated.timing(opacity, {
          duration: 220,
          easing: Easing.out(Easing.ease),
          toValue: 1,
          useNativeDriver: true,
        }),
      ]).start();
      return;
    }

    Animated.parallel([
      Animated.timing(translateY, {
        duration: 220,
        easing: Easing.in(Easing.cubic),
        toValue: 160,
        useNativeDriver: true,
      }),
      Animated.timing(opacity, {
        duration: 180,
        easing: Easing.in(Easing.ease),
        toValue: 0,
        useNativeDriver: true,
      }),
    ]).start();
  }, [opacity, translateY, visible]);

  const title = useMemo(() => {
    if (typeof streak === 'number' && streak > 0) {
      return `🔥 ${streak} day streak unlocked`;
    }
    return 'Momentum boost unlocked';
  }, [streak]);

  // Dynamic CTA based on streak milestone
  const premiumCTA = useMemo(() => {
    if (!streak || streak < 7) {
      return {
        text: 'Get Premium Habits',
        benefit: 'Science-backed habits from experts'
      };
    }
    if (streak < 14) {
      return {
        text: 'Unlock Streak Protection',
        benefit: 'Never lose progress on rest days'
      };
    }
    if (streak < 30) {
      return {
        text: 'Get Advanced Analytics',
        benefit: 'See your trends & insights'
      };
    }
    return {
      text: 'Join Premium Community',
      benefit: 'Connect with 10k+ habit builders'
    };
  }, [streak]);

  return (
    <AnimatedContainer
      accessibilityLiveRegion='polite'
      className='absolute bottom-6 left-4 right-4'
      pointerEvents='box-none'
      style={{
        opacity,
        transform: [{ translateY }],
      }}
    >
      <View className='rounded-3xl bg-white p-5 shadow-lg shadow-blue-100'>
        <Text className='text-[17px] font-bold leading-[24px] text-[#1c1917]'>{title}</Text>
        <Text className='mt-2 text-[15px] leading-[20px] text-[#44403c]'>{message}</Text>

        {/* Premium value prop */}
        <View className='mt-3 rounded-2xl bg-gradient-to-br from-purple-50 to-blue-50 p-3' style={{ backgroundColor: '#faf5ff' }}>
          <Text className='text-[13px] font-semibold text-[#7c3aed]'>✨ {premiumCTA.benefit}</Text>
        </View>

        <View className='mt-4 flex-row items-center justify-between gap-3'>
          <Pressable
            accessibilityHint='Share this streak to motivate friends'
            accessibilityLabel='Share streak'
            className='flex-1 items-center justify-center rounded-full border border-[#d6d3d1] px-3 py-2.5'
            onPress={() => {
              triggerSelection();
              onSecondaryAction();
            }}
          >
            <Text className='text-[15px] font-semibold leading-[20px] text-[#475467]'>Share</Text>
          </Pressable>
          <Pressable
            accessibilityHint={`${premiumCTA.text}: ${premiumCTA.benefit}`}
            accessibilityLabel={premiumCTA.text}
            className='flex-1 items-center justify-center rounded-full px-3 py-2.5'
            style={{ backgroundColor: '#7c3aed' }}
            onPress={() => {
              triggerSelection();
              onPrimaryAction();
            }}
          >
            <Text className='text-[15px] font-semibold leading-[20px] text-white'>{premiumCTA.text}</Text>
          </Pressable>
        </View>

        <Pressable
          accessibilityLabel='Dismiss reward toast'
          className='mt-3 items-center'
          onPress={() => {
            triggerLightImpact();
            onDismiss();
          }}
        >
          <Text className='text-[10px] font-medium uppercase leading-[12px] tracking-wider text-[#78716c]'>Not now</Text>
        </Pressable>
      </View>
    </AnimatedContainer>
  );
};

export default RewardCelebrationToast;

import { useMutation, useQuery } from 'convex/react';
import { useEffect, useState } from 'react';
import { api } from '../../../convex/_generated/api';
import { DEFAULT_SETTINGS } from './SettingsDialog.config';
import type { Settings } from './SettingsDialog.types';

export function useSettingsDialog(isOpen: boolean) {
  const settings = useQuery(api.settings.get) ?? DEFAULT_SETTINGS;
  const updateSettings = useMutation(api.settings.update);
  const [localSettings, setLocalSettings] = useState<Settings>(settings);

  // Sync local settings when dialog opens
  useEffect(() => {
    if (isOpen) {
      setLocalSettings(settings);
    }
  }, [isOpen, settings]);

  // Apply dark mode class
  useEffect(() => {
    document.documentElement.classList.toggle('dark', localSettings.darkMode === 'dark');
  }, [localSettings.darkMode]);

  const toggleSetting = (key: keyof Settings) => {
    if (key === 'darkMode') {
      const nextDarkMode: Settings['darkMode'] =
        localSettings.darkMode === 'dark' ? 'light' : 'dark';
      const newSettings: Settings = { ...localSettings, darkMode: nextDarkMode };
      setLocalSettings(newSettings);
      updateSettings(newSettings);
      return;
    }

    const newSettings = { ...localSettings, [key]: !localSettings[key] };
    setLocalSettings(newSettings);
    updateSettings(newSettings);
  };

  return { localSettings, toggleSetting };
}

export function useEscapeKey(onEscape: () => void) {
  useEffect(() => {
    const handleEsc = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onEscape();
      }
    };
    document.addEventListener('keydown', handleEsc);
    return () => document.removeEventListener('keydown', handleEsc);
  }, [onEscape]);
}

import { useMutation, useQuery } from 'convex/react';
import { useEffect, useState } from 'react';
import { api } from '../../../convex/_generated/api';

interface UseSettingsModalLogicProps {
  visible: boolean;
  onClose: () => void;
}

type DarkModePreference = 'system' | 'light' | 'dark';

const normalizeDarkModePreference = (value: unknown): DarkModePreference => {
  if (value === 'dark' || value === 'light' || value === 'system') {
    return value;
  }

  if (value === true) {
    return 'dark';
  }

  if (value === false) {
    return 'light';
  }

  return 'light'; // Default to light - dark mode not yet implemented
};

export const useSettingsModalLogic = ({
  visible,
  onClose,
}: UseSettingsModalLogicProps) => {
  const [view, setView] = useState<'settings' | 'archived' | 'paused'>(
    'settings'
  );

  // Get settings from Convex
  const settings = useQuery(api.settings.get);
  const updateSettings = useMutation(api.settings.update);

  // Local state for settings
  const [darkModePreference, setDarkModeState] =
    useState<DarkModePreference>('light');
  const [reduceMotion, setReduceMotionState] = useState(false);
  const [highContrastMode, setHighContrastModeState] = useState(false);
  const [useDyslexicFont, setUseDyslexicFontState] = useState(false);

  // Sync local state with Convex settings
  useEffect(() => {
    if (settings) {
      setDarkModeState(normalizeDarkModePreference(settings.darkMode));
      setReduceMotionState(settings.reduceMotion);
      setHighContrastModeState(settings.highContrastMode);
      setUseDyslexicFontState(settings.useDyslexicFont);
    }
  }, [settings]);

  // Reset to settings view when modal closes
  const handleClose = () => {
    onClose();
    setTimeout(() => setView('settings'), 300); // Reset after animation
  };

  // Setting updaters
  const setDarkModePreference = async (value: DarkModePreference) => {
    setDarkModeState(value);
    if (settings) {
      await updateSettings({
        ...settings,
        darkMode: value,
      });
    }
  };

  const setReduceMotion = async (value: boolean) => {
    setReduceMotionState(value);
    if (settings) {
      await updateSettings({
        ...settings,
        reduceMotion: value,
      });
    }
  };

  const setHighContrastMode = async (value: boolean) => {
    setHighContrastModeState(value);
    if (settings) {
      await updateSettings({
        ...settings,
        highContrastMode: value,
      });
    }
  };

  const setUseDyslexicFont = async (value: boolean) => {
    setUseDyslexicFontState(value);
    if (settings) {
      await updateSettings({
        ...settings,
        useDyslexicFont: value,
      });
    }
  };

  return {
    darkModePreference,
    handleClose,
    highContrastMode,
    reduceMotion,
    setDarkModePreference,
    setHighContrastMode,
    setReduceMotion,
    setUseDyslexicFont,
    setView,
    useDyslexicFont,
    view,
  };
};

import {
  Activity,
  BookOpen,
  Check,
  ChevronLeft,
  Circle,
} from 'lucide-react-native';
import React from 'react';
import { Modal, ScrollView, Text, TouchableOpacity, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import ArchivedHabitsModal from '../ArchivedHabitsModal';
import { SettingsRow } from './SettingsRow';
import { SettingsSection } from './SettingsSection';
import { useSettingsModalLogic } from './SettingsModal.hooks';

interface SettingsModalProps {
  celebrationsEnabled?: boolean;
  dayShape?: 'circle' | 'square';
  habitCompletionIcon?: 'chain' | 'checkbox';
  onChangeDayShape?: (value: 'circle' | 'square') => void | Promise<void>;
  onChangeShowCharacterScreen?: (value: boolean) => void | Promise<void>;
  onChangeHabitCompletionIcon?: (
    value: 'chain' | 'checkbox'
  ) => void | Promise<void>;
  onChangeCelebrationsEnabled?: (value: boolean) => void | Promise<void>;
  onChangeCompact?: (value: boolean) => void | Promise<void>;
  showHabitStrengthPercentage?: boolean;
  onChangeShowHabitStrengthPercentage?: (
    value: boolean
  ) => void | Promise<void>;
  showWeekCompletionBar?: boolean;
  onChangeShowWeekCompletionBar?: (value: boolean) => void | Promise<void>;
  showNotesStats?: boolean;
  onChangeShowNotesStats?: (value: boolean) => void | Promise<void>;
  isHighContrastActive?: boolean;
  isCompact?: boolean;
  onOpenHapticTest?: () => void;
  onClose: () => void;
  showCharacterScreen?: boolean;
  visible: boolean;
}

export default function SettingsModal({
  celebrationsEnabled = true,
  dayShape = 'square',
  habitCompletionIcon = 'chain',
  isCompact = false,
  isHighContrastActive = false,
  onChangeCompact = () => {},
  onChangeCelebrationsEnabled,
  onChangeDayShape = () => {},
  onChangeHabitCompletionIcon = () => {},
  onChangeShowCharacterScreen = () => {},
  showHabitStrengthPercentage = true,
  onChangeShowHabitStrengthPercentage = () => {},
  onChangeShowWeekCompletionBar = () => {},
  showNotesStats = true,
  onChangeShowNotesStats = () => {},
  onClose,
  onOpenHapticTest,
  showCharacterScreen = true,
  showWeekCompletionBar = true,
  visible,
}: SettingsModalProps) {
  const {
    view,
    setView,
    handleClose,
  } = useSettingsModalLogic({ onClose, visible });
  const insets = useSafeAreaInsets();

  const colors = isHighContrastActive
    ? {
        accent: '#facc15',
        background: '#000000',
        card: '#111111',
        cardBorder: '#2f2f2f',
        headerText: '#ffffff',
        icon: '#facc15',
        mutedText: '#facc15',
        versionText: '#facc15',
      }
    : {
        accent: '#1c1917', // stone-800
        background: '#faf9f7',
        card: '#ffffff',
        cardBorder: '#f5f5f4',
        headerText: '#1c1917', // stone-800
        icon: '#1c1917', // stone-800
        mutedText: '#78716c', // stone-500
        versionText: '#78716c', // stone-500
      };

  if (!visible) return null;

  if (view === 'archived') {
    return (
      <Modal
        animationType='slide'
        visible={visible}
        onRequestClose={handleClose}
      >
        <ArchivedHabitsModal
          onBack={() => setView('settings')}
          onClose={handleClose}
        />
      </Modal>
    );
  }

  return (
    <Modal animationType='slide' visible={visible} onRequestClose={handleClose}>
      <View
        className='flex-1 bg-background'
        style={{ backgroundColor: colors.background }}
      >
        {/* Header */}
        <View
          className='bg-background px-4 pb-4'
          style={{ backgroundColor: colors.background, paddingTop: insets.top + 8 }}
        >
          {/* Settings Title */}
          <View className='flex-row items-center justify-between'>
            <TouchableOpacity
              accessibilityLabel='Back'
              accessibilityRole='button'
              className='size-10 items-center justify-center rounded-full'
              onPress={handleClose}
            >
              <ChevronLeft color={colors.icon} size={28} />
            </TouchableOpacity>
            <Text
              className='text-[24px] font-bold leading-[32px] tracking-tight text-foreground'
              style={{ color: colors.headerText }}
            >
              Settings
            </Text>
            <View className='size-10' />
          </View>
        </View>

        <ScrollView
          className='flex-1 px-4'
          showsVerticalScrollIndicator={false}
          style={{ backgroundColor: colors.background }}
        >
          <View className='gap-6 pb-8'>
            {/* Visual Preferences */}
            <SettingsSection
              highContrastMode={isHighContrastActive}
              title='Visual Preferences'
            >
              <SettingsRow
                highContrastMode={isHighContrastActive}
                icon={<Activity color='#16a34a' size={16} />}
                iconBackgroundColor='#bbf7d0'
                label='Daily progress bar'
                type='toggle'
                value={showWeekCompletionBar}
                onToggle={(value) => void onChangeShowWeekCompletionBar(value)}
              />
              <SettingsRow
                highContrastMode={isHighContrastActive}
                icon={<Check color='#0284c7' size={16} />}
                iconBackgroundColor='#bae6fd'
                label='Use checkbox completion icon'
                type='toggle'
                value={habitCompletionIcon === 'checkbox'}
                onToggle={(value) =>
                  void onChangeHabitCompletionIcon(value ? 'checkbox' : 'chain')
                }
              />
              <SettingsRow
                highContrastMode={isHighContrastActive}
                icon={<Circle color='#8b5cf6' size={16} />}
                iconBackgroundColor='#ddd6fe'
                label='Use circles for habit days'
                showBorder={false}
                type='toggle'
                value={dayShape === 'circle'}
                onToggle={(value) =>
                  void onChangeDayShape(value ? 'circle' : 'square')
                }
              />
            </SettingsSection>

            {/* Habit Management */}
            <SettingsSection
              highContrastMode={isHighContrastActive}
              title='Habit Management'
            >
              <SettingsRow
                highContrastMode={isHighContrastActive}
                icon={<BookOpen color='#78716c' size={16} />}
                iconBackgroundColor='#e7e5e4'
                label='Archived Habits'
                showBorder={false}
                type='navigation'
                onPress={() => setView('archived')}
              />
            </SettingsSection>
          </View>

          {/* Footer */}
          <View className='items-center pb-8 pt-4'>
            <Text
              className='text-center text-[13px] leading-[18px]'
              style={{ color: colors.versionText }}
            >
              Habit Tracker v1.0.0
            </Text>
          </View>
        </ScrollView>
      </View>
    </Modal>
  );
}

import { ReactNode } from 'react';
import { Switch, Text, TouchableOpacity, View } from 'react-native';
import { ChevronRight } from 'lucide-react-native';

interface SettingsRowProps {
  icon: ReactNode;
  iconBackgroundColor: string;
  label: string;
  type: 'toggle' | 'navigation' | 'selection';
  value?: boolean | string;
  onPress?: () => void;
  onToggle?: (value: boolean) => void;
  showBorder?: boolean;
  highContrastMode?: boolean;
}

export function SettingsRow({
  icon,
  iconBackgroundColor,
  label,
  type,
  value,
  onPress,
  onToggle,
  showBorder = true,
  highContrastMode = false,
}: SettingsRowProps) {
  const colors = highContrastMode
    ? {
        background: '#111111',
        border: '#2f2f2f',
        chevron: '#facc15',
        label: '#ffffff',
        switchThumb: '#000000',
        switchTrackFalse: '#525252',
        switchTrackTrue: '#facc15',
        value: '#facc15',
      }
    : {
        background: '#ffffff',
        border: '#f5f5f4',
        chevron: '#78716c', // stone-500
        label: '#1c1917', // stone-800
        switchThumb: '#ffffff',
        switchTrackFalse: '#d1d5db',
        switchTrackTrue: '#1c1917', // stone-800
        value: '#78716c', // stone-500
      };

  const content = (
    <View
      className={`flex-row items-center px-4 py-4 ${showBorder ? 'border-b border-stone-100' : ''}`}
      style={{
        backgroundColor: colors.background,
        borderColor: showBorder ? colors.border : undefined,
      }}
    >
      {/* Icon */}
      <View
        className='mr-4 size-10 items-center justify-center rounded-lg'
        style={{
          backgroundColor: iconBackgroundColor,
          borderColor: highContrastMode ? '#facc15' : 'transparent',
          borderWidth: highContrastMode ? 2 : 0,
        }}
      >
        {icon}
      </View>

      {/* Label */}
      <Text
        className='flex-1 text-[17px] font-semibold'
        style={{ color: colors.label }}
      >
        {label}
      </Text>

      {/* Right side content */}
      {type === 'toggle' && (
        <Switch
          accessibilityLabel={label}
          ios_backgroundColor={colors.switchTrackFalse}
          thumbColor={colors.switchThumb}
          trackColor={{
            false: colors.switchTrackFalse,
            true: colors.switchTrackTrue,
          }}
          value={value as boolean}
          onValueChange={onToggle}
        />
      )}

      {type === 'selection' && (
        <View className='flex-row items-center gap-1'>
          <Text
            className='text-[17px] font-medium'
            style={{ color: colors.value }}
          >
            {value as string}
          </Text>
          <ChevronRight color={colors.chevron} size={16} />
        </View>
      )}

      {type === 'navigation' && (
        <ChevronRight color={colors.chevron} size={16} />
      )}
    </View>
  );

  if (type === 'toggle') {
    return content;
  }

  return (
    <TouchableOpacity
      accessibilityRole='button'
      activeOpacity={0.7}
      onPress={onPress}
    >
      {content}
    </TouchableOpacity>
  );
}

/**
 * ShareCardGenerator Example Usage
 *
 * This file demonstrates how to integrate the ShareCardGenerator component
 * into your Milestone Celebration modal or other achievement screens.
 */

import React, { useState } from 'react';
import { View, StyleSheet } from 'react-native';
import {
  ShareCardGenerator,
  type ShareCardData,
  type MilestoneLevel,
} from './ShareCardGenerator';
import { Button } from './Button/Button';

/**
 * Example: Integration with Milestone Celebration Modal
 *
 * When a user reaches a new milestone (e.g., 60% strength = "Strong" level),
 * show the celebration modal with a "Share Your Achievement" button.
 */
export function MilestoneCelebrationExample() {
  const [showShareCard, setShowShareCard] = useState(false);

  // Example habit data from your state/backend
  const habitData: ShareCardData = {
    habitName: 'Morning Meditation',
    milestoneLevel: 'strong' as MilestoneLevel, // 60-80% range
    strengthPercentage: 65,
    userName: 'Alex Johnson', // Optional, from user profile
  };

  return (
    <View style={styles.container}>
      {/* Your celebration modal content here */}
      <Button onPress={() => setShowShareCard(true)}>
        Share Your Achievement
      </Button>

      {/* Share Card Generator Modal */}
      <ShareCardGenerator
        data={habitData}
        visible={showShareCard}
        onClose={() => setShowShareCard(false)}
      />
    </View>
  );
}

/**
 * Example: Determining Milestone Level from Strength Percentage
 *
 * Helper function to map strength percentage to milestone level.
 */
export function getMilestoneLevel(strengthPercentage: number): MilestoneLevel {
  if (strengthPercentage >= 80) return 'automatic'; // ⚡ 80-100%
  if (strengthPercentage >= 60) return 'strong'; // 💪 60-80%
  if (strengthPercentage >= 40) return 'developing'; // 🌳 40-60%
  if (strengthPercentage >= 20) return 'building'; // 🌿 20-40%
  return 'starting'; // 🌱 0-20%
}

/**
 * Example: Triggering Share Card from Analytics Screen
 *
 * Users can also share their achievements from the analytics/stats screen.
 */
export function AnalyticsShareExample() {
  const [showShareCard, setShowShareCard] = useState(false);

  const habit = {
    name: 'Evening Reading',
    strength: 72, // Current strength percentage
    userName: 'Morgan Smith',
  };

  const shareData: ShareCardData = {
    habitName: habit.name,
    milestoneLevel: getMilestoneLevel(habit.strength),
    strengthPercentage: habit.strength,
    userName: habit.userName,
  };

  return (
    <View style={styles.container}>
      <Button onPress={() => setShowShareCard(true)}>Share Progress</Button>

      <ShareCardGenerator
        data={shareData}
        visible={showShareCard}
        onClose={() => setShowShareCard(false)}
      />
    </View>
  );
}

/**
 * Example: Milestone Detection Logic
 *
 * Detect when a user crosses a milestone threshold and trigger celebration.
 */
export function detectMilestoneChange(
  previousStrength: number,
  currentStrength: number
): { crossedMilestone: boolean; newLevel: MilestoneLevel | null } {
  const previousLevel = getMilestoneLevel(previousStrength);
  const currentLevel = getMilestoneLevel(currentStrength);

  const crossedMilestone =
    previousLevel !== currentLevel && currentStrength > previousStrength;

  return {
    crossedMilestone,
    newLevel: crossedMilestone ? currentLevel : null,
  };
}

