      </View>
      <View className='mb-4 h-[1px]' style={{ backgroundColor: '#e7e5e4' }} />
      <View className='flex-row items-center justify-between'>
        {[0, 1, 2, 3, 4, 5, 6].map((i) => (
          <SkeletonLoader key={i} borderRadius={9} height={36} reduceMotion={reduceMotion} width={36} />
        ))}
      </View>
