source:
/**
 * SpotlightHero Component
 * Featured template showcase with gradient background and premium visual treatment
 *
 * Purpose: Highlight a curated template at the top of the Templates screen
 * Features: Gradient background using template accent color, shimmer effect, dual CTAs
 */

import React, { useEffect } from 'react';
import { View, Text, StyleSheet, Pressable } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withDelay,
  withTiming,
  withRepeat,
  withSequence,
  Easing,
  interpolate,
} from 'react-native-reanimated';
import { Sparkles, ArrowRight, FlaskConical } from 'lucide-react-native';
import * as Haptics from 'expo-haptics';
import { useAppTheme } from '../../theme';
import type { Doc } from '../../../convex/_generated/dataModel';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

interface SpotlightHeroProps {
  /** Featured template to display */
  template: Doc<'templates'>;
  /** Handler for preview action */
  onPreview: () => void;
  /** Handler for import action */
  onImport: () => void;
  /** Loading state for import */
  isImporting?: boolean;
  /** Animation delay for staggered entrance */
  animationDelay?: number;
}

export const SpotlightHero: React.FC<SpotlightHeroProps> = ({
  template,
  onPreview,
  onImport,
  isImporting = false,
  animationDelay = 0,
}) => {
  const theme = useAppTheme();

  // Animation values
  const cardScale = useSharedValue(0.95);
  const cardOpacity = useSharedValue(0);
  const shimmerPosition = useSharedValue(-1);
  const pressScale = useSharedValue(1);

  // Entrance animation
  useEffect(() => {
    cardOpacity.value = withDelay(
      animationDelay,
      withTiming(1, { duration: 400, easing: Easing.out(Easing.cubic) })
    );
    cardScale.value = withDelay(
      animationDelay,
      withSpring(1, { damping: 15, stiffness: 100 })
    );

    // Shimmer animation - subtle and periodic
    shimmerPosition.value = withDelay(
      animationDelay + 600,
      withRepeat(
        withSequence(
          withTiming(1, { duration: 2000, easing: Easing.inOut(Easing.ease) }),
          withDelay(4000, withTiming(-1, { duration: 0 }))
        ),
        -1,
        false
      )
    );
  }, [animationDelay]);

  // Animated styles
  const containerStyle = useAnimatedStyle(() => ({
    opacity: cardOpacity.value,
    transform: [
      { scale: cardScale.value * pressScale.value },
    ],
  }));

  const shimmerStyle = useAnimatedStyle(() => ({
    transform: [
      {
        translateX: interpolate(
          shimmerPosition.value,
          [-1, 1],
          [-300, 300]
        ),
      },
    ],
    opacity: interpolate(
      shimmerPosition.value,
      [-1, -0.5, 0, 0.5, 1],
      [0, 0.3, 0.5, 0.3, 0]
    ),
  }));

  // Generate gradient colors from template's iconColor
  const baseColor = template.iconColor;
  const gradientColors = [
    `${baseColor}35`, // 20% opacity
    `${baseColor}18`, // 10% opacity
    `${baseColor}08`, // 5% opacity
  ] as const;

  // Handlers
  const handlePressIn = () => {
    pressScale.value = withSpring(0.98, { damping: 15, stiffness: 200 });
  };

  const handlePressOut = () => {
    pressScale.value = withSpring(1, { damping: 15, stiffness: 200 });
  };

  const handlePreview = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onPreview();
  };

  const handleImport = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    onImport();
  };

  return (
    <AnimatedPressable
      accessible
      accessibilityHint="Tap to preview this featured template"
      accessibilityLabel={`Spotlight: ${template.name}`}
      accessibilityRole="button"
      style={[styles.container, containerStyle]}
      onPress={handlePreview}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
    >
      <LinearGradient
        colors={gradientColors}
        end={{ x: 1, y: 1 }}
        start={{ x: 0, y: 0 }}
        style={styles.gradient}
      >
        {/* Shimmer overlay */}
        <Animated.View style={[styles.shimmer, shimmerStyle]}>
          <LinearGradient
            colors={['transparent', 'rgba(255,255,255,0.4)', 'transparent']}
            end={{ x: 1, y: 0.5 }}
            start={{ x: 0, y: 0.5 }}
            style={styles.shimmerGradient}
          />
        </Animated.View>

        {/* Spotlight badge */}
        <View style={styles.badge}>
          <Sparkles color="#ffffff" size={14} strokeWidth={2.5} />
          <Text style={styles.badgeText}>SPOTLIGHT</Text>
        </View>

        {/* Content */}
        <View style={styles.content}>
          {/* Icon with glow */}
          <View style={styles.iconWrapper}>
            <View
              style={[
                styles.iconGlow,
                { backgroundColor: template.iconColor, shadowColor: template.iconColor },
              ]}
            />
            <View
              style={[
                styles.iconContainer,
                { backgroundColor: `${template.iconColor}30` },
              ]}
            >
              <Text style={styles.icon}>{template.icon}</Text>
            </View>
          </View>

          {/* Text content */}
          <View style={styles.textContent}>
            <Text
              numberOfLines={1}
              style={[
                styles.title,
                { fontFamily: theme.custom.fontFamilies.primary.text },
              ]}
            >
              {template.name}
            </Text>

            <Text
              numberOfLines={2}
              style={[
                styles.description,
                { fontFamily: theme.custom.fontFamilies.primary.text },
              ]}
            >
              {template.description}
            </Text>

            {/* Research indicator */}
            {template.scientificLink && (
              <View style={styles.researchRow}>
                <FlaskConical color="#166534" size={14} strokeWidth={2} />
                <Text style={styles.researchText}>
                  Backed by peer-reviewed research
                </Text>
              </View>
            )}
          </View>
        </View>

        {/* Action buttons */}
        <View style={styles.actions}>
          <Pressable
            accessibilityLabel="Preview template"
            style={styles.previewButton}
            onPress={handlePreview}
          >
            <Text style={styles.previewButtonText}>Preview</Text>
          </Pressable>

          <Pressable
            accessibilityLabel="Import template"
            disabled={isImporting}
            style={[
              styles.importButton,
              { backgroundColor: template.iconColor },
              isImporting && styles.importButtonDisabled,
            ]}
            onPress={handleImport}
          >
            <Text style={styles.importButtonText}>
              {isImporting ? 'Importing...' : 'Import Habit'}
            </Text>
            {!isImporting && (
              <ArrowRight color="#ffffff" size={16} strokeWidth={2.5} />
            )}
          </Pressable>
        </View>
      </LinearGradient>
    </AnimatedPressable>
  );
};

const styles = StyleSheet.create({
  actions: {
    flexDirection: 'row',
    gap: 12,
    marginTop: 20,
  },
  badge: {
    alignItems: 'center',
    alignSelf: 'flex-start',
    backgroundColor: 'rgba(0, 0, 0, 0.15)',
    borderRadius: 20,
    flexDirection: 'row',
    gap: 6,
    paddingHorizontal: 12,
    paddingVertical: 6,
  },
  badgeText: {
    color: '#ffffff',
    fontSize: 11,
    fontWeight: '700',
    letterSpacing: 1,
  },
  container: {
    borderRadius: 20,
    marginBottom: 16,
    marginHorizontal: 20,
    overflow: 'hidden',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.12,
    shadowRadius: 12,
    elevation: 6,
  },
  content: {
    flexDirection: 'row',
    gap: 16,
    marginTop: 16,
  },
  description: {
    color: '#374151',
    fontSize: 14,
    lineHeight: 20,
    marginTop: 4,
  },
  gradient: {
    overflow: 'hidden',
    padding: 20,
  },
  icon: {
    fontSize: 32,
  },
  iconContainer: {
    alignItems: 'center',
    borderRadius: 16,
    height: 64,
    justifyContent: 'center',
    width: 64,
  },
  iconGlow: {
    borderRadius: 32,
    height: 64,
    opacity: 0.3,
    position: 'absolute',
    shadowOffset: { width: 0, height: 0 },
    shadowOpacity: 0.5,
    shadowRadius: 20,
    width: 64,
  },
  iconWrapper: {
    position: 'relative',
  },
  importButton: {
    alignItems: 'center',
    borderRadius: 12,
    flex: 1,
    flexDirection: 'row',
    gap: 8,
    justifyContent: 'center',
    paddingHorizontal: 20,
    paddingVertical: 14,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.15,
    shadowRadius: 4,
    elevation: 3,
  },
  importButtonDisabled: {
    opacity: 0.6,
  },
  importButtonText: {
    color: '#ffffff',
    fontSize: 15,
    fontWeight: '700',
  },
  previewButton: {
    alignItems: 'center',
    backgroundColor: 'rgba(255, 255, 255, 0.9)',
    borderRadius: 12,
    justifyContent: 'center',
    paddingHorizontal: 20,
    paddingVertical: 14,
  },
  previewButtonText: {
    color: '#374151',
    fontSize: 15,
    fontWeight: '600',
  },
  researchRow: {
    alignItems: 'center',
    backgroundColor: 'rgba(16, 185, 129, 0.1)',
    borderRadius: 8,
    flexDirection: 'row',
    gap: 6,
    marginTop: 10,
    paddingHorizontal: 10,
    paddingVertical: 6,
    alignSelf: 'flex-start',
  },
  researchText: {
    color: '#166534',
    fontSize: 12,
    fontWeight: '600',
  },
  shimmer: {
    height: '200%',
    left: 0,
    position: 'absolute',
    top: '-50%',
    width: 100,
  },
  shimmerGradient: {
    flex: 1,
    width: 100,
  },
  textContent: {
    flex: 1,
  },
  title: {
    color: '#111827',
    fontSize: 20,
    fontWeight: '700',
  },
});

export default SpotlightHero;

/**
 * StatsGrid Component
 * Displays key habit statistics with visual polish
 *
 * @deprecated This component has been replaced by the "Journey Stats" section
 * in InsightsSection. All metrics (totalCompletions, successRate, daysTracking)
 * are now displayed there. This component is kept for reference but should not
 * be used in new code.
 */

import React, { useEffect } from 'react';
import { View, Text } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withSpring,
  withTiming,
} from 'react-native-reanimated';
import { CheckCircle2, TrendingUp, Flame, Calendar, BarChart3 } from 'lucide-react-native';

export interface StatsGridProps {
  currentStreak: number;
  daysTracking: number;
  successRate: number;
  totalCompletions: number;
}

interface StatCardProps {
  bgColor: string;
  delay: number;
  icon: React.ReactNode;
  iconBgColor: string;
  label: string;
  suffix?: string;
  value: number | string;
  valueColor: string;
}

function StatCard({
  bgColor,
  delay,
  icon,
  iconBgColor,
  label,
  suffix,
  value,
  valueColor,
}: StatCardProps) {
  const scale = useSharedValue(0.9);
  const opacity = useSharedValue(0);

  useEffect(() => {
    opacity.value = withDelay(delay, withTiming(1, { duration: 200 }));
    scale.value = withDelay(delay, withSpring(1, { damping: 12, stiffness: 180 }));
  }, [delay]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ scale: scale.value }],
  }));

  return (
    <Animated.View
      className={`flex-1 rounded-xl p-4 ${bgColor}`}
      style={animatedStyle}
    >
      <View className={`mb-3 h-10 w-10 items-center justify-center rounded-full ${iconBgColor}`}>
        {icon}
      </View>
      <Text className={`text-3xl font-bold ${valueColor}`}>
        {value}
        {suffix && <Text className="text-xl">{suffix}</Text>}
      </Text>
      <Text className="mt-1 text-xs font-medium text-stone-500">{label}</Text>
    </Animated.View>
  );
}

/** @deprecated Use InsightsSection for metrics display */
export function StatsGrid({
  currentStreak,
  daysTracking,
  successRate,
  totalCompletions,
}: StatsGridProps) {
  const displayRate = Math.round(successRate);

  return (
    <View className="rounded-2xl bg-white/90 p-4 shadow-sm shadow-stone-200/50">
      {/* Header */}
      <View className="mb-4 flex-row items-center justify-center gap-2">
        <BarChart3 className="text-stone-500" size={18} />
        <Text className="text-lg font-semibold text-stone-800">Statistics</Text>
      </View>

      <View className="gap-3">
        {/* Top Row */}
        <View className="flex-row gap-3">
          <StatCard
            bgColor="bg-emerald-50"
            delay={0}
            icon={<CheckCircle2 className="text-emerald-600" size={20} />}
            iconBgColor="bg-emerald-100"
            label="Completed"
            value={totalCompletions}
            valueColor="text-emerald-700"
          />
          <StatCard
            bgColor="bg-stone-50"
            delay={80}
            icon={<TrendingUp className="text-stone-600" size={20} />}
            iconBgColor="bg-stone-100"
            label="Success Rate"
            suffix="%"
            value={displayRate}
            valueColor="text-stone-700"
          />
        </View>

        {/* Bottom Row */}
        <View className="flex-row gap-3">
          <StatCard
            bgColor="bg-amber-50"
            delay={160}
            icon={<Flame className="text-amber-600" fill="#d97706" size={20} />}
            iconBgColor="bg-amber-100"
            label="Current Streak"
            value={currentStreak}
            valueColor="text-amber-700"
          />
          <StatCard
            bgColor="bg-violet-50"
            delay={240}
            icon={<Calendar className="text-violet-600" size={20} />}
            iconBgColor="bg-violet-100"
            label="Days Tracking"
            value={daysTracking}
            valueColor="text-violet-700"
          />
        </View>
      </View>
    </View>
  );
}

export default StatsGrid;

import { useQuery } from 'convex/react';
import { format, startOfDay, subDays } from 'date-fns';
import { useMemo, useState } from 'react';
import { Text, TouchableOpacity, View, ScrollView } from 'react-native';
import Svg, { Line, Circle, Rect, Text as SvgText } from 'react-native-svg';
import { api } from '../../../convex/_generated/api';
import type { Id } from '../../../convex/_generated/dataModel';

export default function HabitStats() {
  const habits = useQuery(api.habits.list) ?? [];
  const [selectedHabitId, setSelectedHabitId] = useState<Id<'habits'> | null>(
    habits[0]?._id ?? null
  );

  const today = useMemo(() => startOfDay(new Date()), []);

  // Get last 30 days for trend chart
  const last30Days = useMemo(
    () =>
      Array.from({ length: 30 }, (_, i) =>
        format(subDays(today, 29 - i), 'yyyy-MM-dd')
      ),
    [today]
  );

  // Get last 7 days for weekly bar chart
  const last7Days = useMemo(
    () =>
      Array.from({ length: 7 }, (_, i) =>
        format(subDays(today, 6 - i), 'yyyy-MM-dd')
      ),
    [today]
  );

  const tracking30 =
    useQuery(api.habits.getTracking, { dates: last30Days }) ?? [];
  const tracking7 =
    useQuery(api.habits.getTracking, { dates: last7Days }) ?? [];

  const selectedHabit = habits.find((h) => h._id === selectedHabitId);

  // Calculate stats for selected habit
  const habitStats = useMemo(() => {
    if (!selectedHabitId) return null;

    const habitTracking30 = tracking30.filter(
      (t) => t.habitId === selectedHabitId
    );
    const habitTracking7 = tracking7.filter(
      (t) => t.habitId === selectedHabitId
    );

    // Calculate current streak
    const completedDates = new Set(
      habitTracking30.filter((t) => t.completed).map((t) => t.date)
    );
    let currentStreak = 0;
    const currentDate = new Date(today);

    while (true) {
      const dateString = format(currentDate, 'yyyy-MM-dd');
      if (completedDates.has(dateString)) {
        currentStreak++;
        currentDate.setDate(currentDate.getDate() - 1);
      } else {
        break;
      }
    }

    // Calculate longest streak in 30-day period
    let longestStreak = 0;
    let tempStreak = 0;

    for (const dateStr of last30Days) {
      if (completedDates.has(dateStr)) {
        tempStreak++;
        longestStreak = Math.max(longestStreak, tempStreak);
      } else {
        tempStreak = 0;
      }
    }

    // 30-day completion data for line chart
    const completionData = last30Days.map((date) => ({
      completed: habitTracking30.some((t) => t.date === date && t.completed),
      date,
    }));

    // 7-day completion data for bar chart
    const weeklyData = last7Days.map((date) => ({
      completed: habitTracking7.some((t) => t.date === date && t.completed),
      date,
    }));

    return {
      completionData,
      currentStreak,
      longestStreak,
      weeklyData,
    };
  }, [selectedHabitId, tracking30, tracking7, last30Days, last7Days, today]);

  if (habits.length === 0) {
    return (
      <View className='items-center py-8'>
        <Text className='text-center text-sm text-stone-500'>
          No habits yet. Create your first habit to see stats!
        </Text>
      </View>
    );
  }

  return (
    <View className='gap-4'>
      <Text className='text-lg font-semibold text-stone-900'>
        Per-Habit Stats
      </Text>

      {/* Habit selector */}
      <View className='gap-2'>
        <Text className='text-xs font-semibold uppercase tracking-[2px] text-stone-500'>
          SELECT HABIT
        </Text>
        <ScrollView
          horizontal
          className='flex-row gap-2'
          showsHorizontalScrollIndicator={false}
        >
          {habits.map((habit) => (
            <TouchableOpacity
              key={habit._id}
              accessibilityLabel={`View stats for ${habit.name}`}
              accessibilityRole='button'
              className={`rounded-xl px-4 py-2 ${
                selectedHabitId === habit._id ? 'bg-stone-900' : 'bg-stone-100'
              }`}
              onPress={() => setSelectedHabitId(habit._id)}
            >
              <Text
                className={`text-sm font-medium ${
                  selectedHabitId === habit._id
                    ? 'text-white'
                    : 'text-stone-700'
                }`}
              >
                {habit.name}
              </Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      </View>

      {selectedHabit && habitStats && (
        <View className='gap-4'>
          {/* Streaks */}
          <View className='flex-row gap-3'>
            <View className='flex-1 rounded-2xl bg-stone-50 p-4'>
              <Text className='text-xs font-semibold uppercase tracking-[2px] text-stone-500'>
                CURRENT STREAK
              </Text>
              <View className='mt-2 flex-row items-baseline gap-2'>
                <Text className='text-3xl font-bold text-[#48bb78]'>
                  {habitStats.currentStreak}
                </Text>
                <Text className='text-xl font-semibold text-stone-400'>
                  {habitStats.currentStreak === 1 ? 'day' : 'days'}
                </Text>
              </View>
            </View>
            <View className='flex-1 rounded-2xl bg-stone-50 p-4'>
              <Text className='text-xs font-semibold uppercase tracking-[2px] text-stone-500'>
                LONGEST STREAK
              </Text>
              <View className='mt-2 flex-row items-baseline gap-2'>
                <Text className='text-3xl font-bold text-[#48bb78]'>
                  {habitStats.longestStreak}
                </Text>
                <Text className='text-xl font-semibold text-stone-400'>
                  {habitStats.longestStreak === 1 ? 'day' : 'days'}
                </Text>
              </View>
            </View>
          </View>

          {/* Weekly bar chart */}
          <View className='rounded-2xl bg-stone-50 p-4'>
            <Text className='mb-3 text-xs font-semibold uppercase tracking-[2px] text-stone-500'>
              LAST 7 DAYS
            </Text>
            <WeeklyBarChart data={habitStats.weeklyData} />
          </View>

          {/* 30-day trend line chart */}
          <View className='rounded-2xl bg-stone-50 p-4'>
            <Text className='mb-3 text-xs font-semibold uppercase tracking-[2px] text-stone-500'>
              30-DAY TREND
            </Text>
            <TrendLineChart data={habitStats.completionData} />
          </View>
        </View>
      )}
    </View>
  );
}

// Simple bar chart for weekly view
function WeeklyBarChart({
  data,
}: {
  data: Array<{ date: string; completed: boolean }>;
}) {
  if (data.length === 0) {
    return null;
  }

  const chartWidth = 300;
  const chartHeight = 120;
  const barWidth = chartWidth / data.length - 8;
  const maxHeight = chartHeight - 30;

  return (
    <View className='items-center'>
      <Svg height={chartHeight} width={chartWidth}>
        {data.map((item, index) => {
          const x = index * (chartWidth / data.length) + 4;
          const barHeight = item.completed ? maxHeight : 10;
          const y = chartHeight - barHeight - 20;

          return (
            <View key={item.date}>
              <Rect
                fill={item.completed ? '#48bb78' : '#dde3ed'}
                height={barHeight}
                rx={4}
                width={barWidth}
                x={x}
                y={y}
              />
              <SvgText
                fill='#78716c'
                fontSize='10'
                textAnchor='middle'
                x={x + barWidth / 2}
                y={chartHeight - 5}
              >
                {format(new Date(item.date), 'EEE')[0]}
              </SvgText>
            </View>
          );
        })}
      </Svg>
      <Text className='mt-2 text-xs text-stone-500'>
        {format(new Date(data[0].date), 'MMM d')} -{' '}
        {format(new Date(data[data.length - 1].date), 'MMM d')}
      </Text>
    </View>
  );
}

// Simple line chart for 30-day trend
function TrendLineChart({
  data,
}: {
  data: Array<{ date: string; completed: boolean }>;
}) {
  if (data.length === 0) {
    return null;
  }

  const chartWidth = 300;
  const chartHeight = 100;
  const pointRadius = 3;
  const denominator = Math.max(1, data.length - 1);

  // Calculate points
  const points = data.map((item, index) => ({
    completed: item.completed,
    x: (index / denominator) * chartWidth,
    y: item.completed ? 20 : chartHeight - 20,
  }));

  // Create path for line
  const pathData = points
    .map((point, index) => {
      if (index === 0) return `M ${point.x} ${point.y}`;
      return `L ${point.x} ${point.y}`;
    })
    .join(' ');

  return (
    <View className='items-center'>
      <Svg height={chartHeight} width={chartWidth}>
        {/* Grid lines */}
        <Line
          stroke='#e7e5e4'
          strokeDasharray='4,4'
          strokeWidth='1'
          x1='0'
          x2={chartWidth}
          y1={chartHeight / 2}
          y2={chartHeight / 2}
        />

        {/* Line path */}
        <Line
          stroke='#d6d3d1'
          strokeWidth='1'
          x1={points[0]?.x ?? 0}
          x2={points.at(-1)?.x ?? 0}
          y1={points[0]?.y ?? 0}
          y2={points.at(-1)?.y ?? 0}
        />

        {/* Points */}
        {points.map((point, index) => (
          <Circle
            key={index}
            cx={point.x}
            cy={point.y}
            fill={point.completed ? '#48bb78' : '#dde3ed'}
            r={pointRadius}
            stroke={point.completed ? '#48bb78' : '#a8a29e'}
            strokeWidth='1.5'
          />
        ))}

        {/* Labels */}
        <SvgText fill='#78716c' fontSize='10' textAnchor='start' x='0' y='15'>
          ✓
        </SvgText>
        <SvgText
          fill='#78716c'
          fontSize='10'
          textAnchor='start'
          x='0'
          y={chartHeight - 10}
        >
          ✗
        </SvgText>
      </Svg>
      <Text className='mt-2 text-xs text-stone-500'>
        {format(new Date(data[0].date), 'MMM d')} -{' '}
        {format(new Date(data[data.length - 1].date), 'MMM d')}
      </Text>
    </View>
  );
}

import { useMutation, useQuery } from 'convex/react';
import { format } from 'date-fns';
import { useState } from 'react';
import {
  Text,
  TextInput,
  TouchableOpacity,
  View,
  ActivityIndicator,
} from 'react-native';
import { api } from '../../../convex/_generated/api';
import type { Id } from '../../../convex/_generated/dataModel';

interface NoteEditorProps {
  noteId?: Id<'notes'>;
  initialBody?: string;
  initialDate?: string;
  initialHabitId?: Id<'habits'>;
  onCancel: () => void;
  onSave: () => void;
}

export default function NoteEditor({
  noteId,
  initialBody = '',
  initialDate,
  initialHabitId,
  onCancel,
  onSave,
}: NoteEditorProps) {
  const [body, setBody] = useState(initialBody);
  const [date, setDate] = useState(
    initialDate || format(new Date(), 'yyyy-MM-dd')
  );
  const [selectedHabitId, setSelectedHabitId] = useState<
    Id<'habits'> | undefined
  >(initialHabitId);

  const createNote = useMutation(api.notes.create);
  const updateNote = useMutation(api.notes.update);
  const habits = useQuery(api.habits.list) ?? [];

  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string>('');

  const characterCount = body.length;
  const isValid = body.trim().length > 0 && characterCount <= 1000;

  const handleSave = async () => {
    if (!isValid) return;

    setIsSaving(true);
    setError('');

    try {
      await (noteId
        ? updateNote({ body: body.trim(), noteId })
        : createNote({
            body: body.trim(),
            date,
            habitId: selectedHabitId,
          }));
      onSave();
    } catch (error_) {
      setError(
        error_ instanceof Error ? error_.message : 'Failed to save note'
      );
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <View className='gap-4'>
      <View className='gap-2'>
        <Text className='text-xs font-semibold uppercase tracking-[2px] text-stone-500'>
          {noteId ? 'EDIT NOTE' : 'NEW NOTE'}
        </Text>

        {!noteId && (
          <>
            <TextInput
              accessibilityLabel='Note date'
              className='w-full rounded-2xl border border-stone-200 bg-white px-4 py-3 text-sm font-medium text-stone-900'
              placeholder='YYYY-MM-DD'
              placeholderTextColor='#a8a29e'
              value={date}
              onChangeText={setDate}
            />

            <View className='rounded-2xl border border-stone-200 bg-white px-4 py-3'>
              <Text className='mb-2 text-xs font-semibold uppercase tracking-[2px] text-stone-500'>
                LINKED HABIT (OPTIONAL)
              </Text>
              <View className='gap-2'>
                <TouchableOpacity
                  accessibilityLabel='No habit selected'
                  accessibilityRole='button'
                  className={`rounded-xl px-3 py-2 ${
                    selectedHabitId ? 'bg-stone-100' : 'bg-stone-900'
                  }`}
                  onPress={() => setSelectedHabitId(undefined)}
                >
                  <Text
                    className={`text-sm font-medium ${
                      selectedHabitId ? 'text-stone-700' : 'text-white'
                    }`}
                  >
                    None
                  </Text>
                </TouchableOpacity>
                {habits.map((habit) => (
                  <TouchableOpacity
                    key={habit._id}
                    accessibilityLabel={`Link to ${habit.name}`}
                    accessibilityRole='button'
                    className={`rounded-xl px-3 py-2 ${
                      selectedHabitId === habit._id
                        ? 'bg-stone-900'
                        : 'bg-stone-100'
                    }`}
                    onPress={() => setSelectedHabitId(habit._id)}
                  >
                    <Text
                      className={`text-sm font-medium ${
                        selectedHabitId === habit._id
                          ? 'text-white'
                          : 'text-stone-700'
                      }`}
                    >
                      {habit.name}
                    </Text>
                  </TouchableOpacity>
                ))}
              </View>
            </View>
          </>
        )}

        <TextInput
          multiline
          accessibilityLabel='Note body'
          className='min-h-[120px] w-full rounded-2xl border border-stone-200 bg-white px-4 py-3 text-sm font-medium text-stone-900'
          placeholder='Write your note here...'
          placeholderTextColor='#a8a29e'
          textAlignVertical='top'
          value={body}
          onChangeText={setBody}
        />

        <View className='flex-row justify-between'>
          <Text
            className={`text-xs ${
              characterCount > 1000 ? 'text-red-500' : 'text-stone-500'
            }`}
          >
            {characterCount} / 1000 characters
          </Text>
        </View>

        {error ? <Text className='text-sm text-red-500'>{error}</Text> : null}
      </View>

      <View className='flex-row items-center justify-end gap-3'>
        <TouchableOpacity
          accessibilityRole='button'
          className='py-2'
          disabled={isSaving}
          onPress={onCancel}
        >
          <Text className='text-xs font-semibold tracking-[2px] text-stone-500'>
            CANCEL
          </Text>
        </TouchableOpacity>
        <TouchableOpacity
          accessibilityRole='button'
          className={`rounded-3xl border border-stone-900 px-5 py-2 ${
            !isValid || isSaving ? 'opacity-40' : ''
          }`}
          disabled={!isValid || isSaving}
          onPress={handleSave}
        >
          {isSaving ? (
            <ActivityIndicator color='#1c1917' size='small' />
          ) : (
            <Text className='text-xs font-semibold tracking-[2px] text-stone-900'>
              {noteId ? 'SAVE' : 'ADD'}
            </Text>
          )}
        </TouchableOpacity>
      </View>
    </View>
  );
}

import { useMutation, useQuery } from 'convex/react';
import { format } from 'date-fns';
import { Plus, Search, Trash2, Edit3, Eye } from 'lucide-react-native';
import { useEffect, useMemo, useState } from 'react';
import {
  Modal,
  ScrollView,
  Text,
  TextInput,
  TouchableOpacity,
  View,
  ActivityIndicator,
} from 'react-native';
import Animated, { FadeIn } from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import * as Haptics from 'expo-haptics';
import { X } from 'lucide-react-native';
import { api } from '../../../convex/_generated/api';
import type { Id } from '../../../convex/_generated/dataModel';
import NoteEditor from './NoteEditor';
import { VisualizationGuide } from '../NotesSection/VisualizationGuide';

interface NotesListProps {
  hideHabitFilter?: boolean;
  initialHabitId?: Id<'habits'>;
  onAddNote?: () => void;
}

export default function NotesList({ hideHabitFilter = false, initialHabitId, onAddNote }: NotesListProps) {
  const [searchText, setSearchText] = useState('');
  const [selectedHabitFilter, setSelectedHabitFilter] = useState<
    Id<'habits'> | 'all'
  >(initialHabitId ?? 'all');
  const [editingNoteId, setEditingNoteId] = useState<Id<'notes'> | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const [showVisualizationGuide, setShowVisualizationGuide] = useState(false);
  const insets = useSafeAreaInsets();

  useEffect(() => {
    if (!initialHabitId) {
      return;
    }
    setSelectedHabitFilter(initialHabitId);
  }, [initialHabitId]);

  const handleOpenVisualizationGuide = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    setShowVisualizationGuide(true);
  };

  const handleCloseVisualizationGuide = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    setShowVisualizationGuide(false);
  };

  const habits = useQuery(api.habits.list) ?? [];
  const notes =
    useQuery(api.notes.search, {
      habitId: selectedHabitFilter === 'all' ? undefined : selectedHabitFilter,
      searchText: searchText || undefined,
    }) ?? [];

  const deleteNote = useMutation(api.notes.remove);
  const [deletingNoteId, setDeletingNoteId] = useState<Id<'notes'> | null>(
    null
  );

  // Group notes by date
  const groupedNotes = useMemo(() => {
    const groups = new Map<string, typeof notes>();

    for (const note of notes) {
      const existing = groups.get(note.date) || [];
      groups.set(note.date, [...existing, note]);
    }

    // Sort by date descending
    return [...groups.entries()]
      .sort(([dateA], [dateB]) => dateB.localeCompare(dateA))
      .map(([date, notes]) => ({
        date,
        notes: notes.sort((a, b) => b._creationTime - a._creationTime),
      }));
  }, [notes]);

  const handleDelete = async (noteId: Id<'notes'>) => {
    setDeletingNoteId(noteId);
    try {
      await deleteNote({ noteId });
    } catch (error) {
      console.error('Failed to delete note:', error);
    } finally {
      setDeletingNoteId(null);
    }
  };

  const editingNote = editingNoteId
    ? notes.find((n) => n._id === editingNoteId)
    : null;

  if (isAdding) {
    return (
      <View>
        <NoteEditor
          onCancel={() => setIsAdding(false)}
          onSave={() => setIsAdding(false)}
        />
      </View>
    );
  }

  if (editingNote) {
    return (
      <View>
        <NoteEditor
          initialBody={editingNote.body}
          initialDate={editingNote.date}
          initialHabitId={editingNote.habitId}
          noteId={editingNote._id}
          onCancel={() => setEditingNoteId(null)}
          onSave={() => setEditingNoteId(null)}
        />
      </View>
    );
  }

  return (
    <View className='gap-4'>
      <View className='flex-row items-center justify-between'>
        <Text className='text-lg font-semibold text-stone-900'>Notes</Text>
        <TouchableOpacity
          accessibilityLabel='Add new note'
          accessibilityRole='button'
          className='h-9 w-9 items-center justify-center rounded-full bg-stone-900'
          onPress={() => setIsAdding(true)}
        >
          <Plus color='#ffffff' size={18} strokeWidth={2.25} />
        </TouchableOpacity>
      </View>

      {/* Search */}
      <View className='relative'>
        <TextInput
          accessibilityLabel='Search notes'
          className='w-full rounded-2xl border border-stone-200 bg-white py-3 pl-11 pr-4 text-sm font-medium text-stone-900'
          placeholder='Search notes...'
          placeholderTextColor='#a8a29e'
          value={searchText}
          onChangeText={setSearchText}
        />
        <View className='absolute left-4 top-3.5'>
          <Search color='#a8a29e' size={18} strokeWidth={2} />
        </View>
      </View>

      {/* Filter by habit */}
      {hideHabitFilter ? null : (
        <View className='gap-2'>
          <Text className='text-xs font-semibold uppercase tracking-[2px] text-stone-500'>
            FILTER BY HABIT
          </Text>
          <View className='flex-row flex-wrap gap-2'>
            <TouchableOpacity
              accessibilityLabel='Show all notes'
              accessibilityRole='button'
              className={`rounded-xl px-3 py-2 ${
                selectedHabitFilter === 'all' ? 'bg-stone-900' : 'bg-stone-100'
              }`}
              onPress={() => setSelectedHabitFilter('all')}
            >
              <Text
                className={`text-sm font-medium ${
                  selectedHabitFilter === 'all' ? 'text-white' : 'text-stone-700'
                }`}
              >
                All
              </Text>
            </TouchableOpacity>
            {habits.map((habit) => (
              <TouchableOpacity
                key={habit._id}
                accessibilityLabel={`Filter by ${habit.name}`}
                accessibilityRole='button'
                className={`rounded-xl px-3 py-2 ${
                  selectedHabitFilter === habit._id
                    ? 'bg-stone-900'
                    : 'bg-stone-100'
                }`}
                onPress={() => setSelectedHabitFilter(habit._id)}
              >
                <Text
                  className={`text-sm font-medium ${
                    selectedHabitFilter === habit._id
                      ? 'text-white'
                      : 'text-stone-700'
                  }`}
                >
                  {habit.name}
                </Text>
              </TouchableOpacity>
            ))}
          </View>
        </View>
      )}

      {/* Visualization Guide Button */}
      <TouchableOpacity
        accessibilityLabel='Open goal visualization guide'
        accessibilityRole='button'
        className='flex-row items-center justify-center gap-2 rounded-2xl bg-gradient-to-r from-violet-500 to-indigo-600 py-3.5 active:opacity-90'
        onPress={handleOpenVisualizationGuide}
      >
        <Eye color='#ffffff' size={18} />
        <Text className='text-sm font-semibold text-white'>
          Visualization Guide
        </Text>
        <View className='rounded-full bg-white/20 px-2 py-0.5'>
          <Text className='text-xs font-medium text-white'>Huberman</Text>
        </View>
      </TouchableOpacity>

      {/* Notes list grouped by date */}
      {groupedNotes.length === 0 ? (
        <View className='items-center py-8'>
          <Text className='text-center text-sm text-stone-500'>
            {searchText || selectedHabitFilter !== 'all'
              ? 'No notes found'
              : 'No notes yet. Add your first note!'}
          </Text>
        </View>
      ) : (
        <View className='gap-6'>
          {groupedNotes.map(({ date, notes: dateNotes }) => (
            <View key={date} className='gap-3'>
              <Text className='text-xs font-semibold uppercase tracking-[2px] text-stone-500'>
                {format(new Date(date), 'MMM d, yyyy')}
              </Text>
              {dateNotes.map((note) => {
                const linkedHabit = note.habitId
                  ? habits.find((h) => h._id === note.habitId)
                  : null;
                const isDeleting = deletingNoteId === note._id;

                return (
                  <View
                    key={note._id}
                    className='gap-2 rounded-2xl bg-stone-50 p-4'
                  >
                    {linkedHabit && (
                      <View className='mb-1'>
                        <Text className='text-xs font-semibold text-stone-600'>
                          {linkedHabit.name}
                        </Text>
                      </View>
                    )}
                    <Text className='text-sm leading-5 text-stone-900'>
                      {note.body}
                    </Text>
                    <View className='flex-row items-center justify-between'>
                      <Text className='text-xs text-stone-400'>
                        {note.updatedAt === note.createdAt
                          ? `Created ${format(note.createdAt, 'MMM d, h:mm a')}`
                          : `Updated ${format(note.updatedAt, 'MMM d, h:mm a')}`}
                      </Text>
                      <View className='flex-row gap-2'>
                        <TouchableOpacity
                          accessibilityLabel='Edit note'
                          accessibilityRole='button'
                          className='rounded-full bg-stone-200 p-2'
                          disabled={isDeleting}
                          onPress={() => setEditingNoteId(note._id)}
                        >
                          <Edit3 color='#57534e' size={14} strokeWidth={2.25} />
                        </TouchableOpacity>
                        <TouchableOpacity
                          accessibilityLabel='Delete note'
                          accessibilityRole='button'
                          className='rounded-full bg-red-100 p-2'
                          disabled={isDeleting}
                          onPress={() => handleDelete(note._id)}
                        >
                          {isDeleting ? (
                            <ActivityIndicator color='#ef4444' size='small' />
                          ) : (
                            <Trash2
                              color='#ef4444'
                              size={14}
                              strokeWidth={2.25}
                            />
                          )}
                        </TouchableOpacity>
                      </View>
                    </View>
                  </View>
                );
              })}
            </View>
          ))}
        </View>
      )}

      {/* Visualization Guide Modal */}
      <Modal
        transparent
        animationType='slide'
        visible={showVisualizationGuide}
        onRequestClose={handleCloseVisualizationGuide}
      >
        <View className='flex-1 bg-gradient-to-b from-violet-50 via-white to-stone-50'>
          {/* Header */}
          <Animated.View
            className='flex-row items-center justify-between border-b border-stone-100 bg-white/95 px-5 pb-4'
            entering={FadeIn.delay(100)}
            style={{ paddingTop: insets.top + 8 }}
          >
            <View className='flex-row items-center gap-3'>
              <View className='h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-violet-500 to-indigo-600'>
                <Eye color='#ffffff' size={20} />
              </View>
              <View>
                <Text className='text-lg font-bold text-stone-900'>
                  Visualization Guide
                </Text>
                <Text className='text-xs text-stone-500'>
                  Science-backed goal techniques
                </Text>
              </View>
            </View>
            <TouchableOpacity
              accessibilityLabel='Close visualization guide'
              accessibilityRole='button'
              className='h-10 w-10 items-center justify-center rounded-full bg-stone-100 active:bg-stone-200'
              onPress={handleCloseVisualizationGuide}
            >
              <X color='#57534e' size={22} />
            </TouchableOpacity>
          </Animated.View>

          {/* Scrollable Content */}
          <ScrollView
            className='flex-1'
            contentContainerStyle={{ padding: 20, paddingBottom: insets.bottom + 20 }}
            showsVerticalScrollIndicator={false}
          >
            <VisualizationGuide onClose={handleCloseVisualizationGuide} />
          </ScrollView>
        </View>
      </Modal>
    </View>
  );
}

