/**
 * useTemplateCardAnimations Hook
 *
 * Animation logic for TemplateCard entrance and success states
 */

import { useEffect } from 'react';
import {
  cancelAnimation,
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withDelay,
  withTiming,
  withSequence,
  Easing,
} from 'react-native-reanimated';

interface UseTemplateCardAnimationsProps {
  animationIndex: number;
  isImported: boolean;
  reducedMotion: boolean;
}

export function useTemplateCardAnimations({
  animationIndex,
  isImported,
  reducedMotion,
}: UseTemplateCardAnimationsProps) {
  const skipAnimation = animationIndex === 0;
  const cardOpacity = useSharedValue(skipAnimation ? 1 : 0);
  const cardTranslateY = useSharedValue(skipAnimation ? 0 : 20);
  const pressScale = useSharedValue(1);
  const shadowOpacity = useSharedValue(0.06);
  const successGlow = useSharedValue(0);
  const checkmarkScale = useSharedValue(0);

  // Entrance animation
  useEffect(() => {
    if (skipAnimation) return;
    const delay = animationIndex * 80;
    cardOpacity.value = withDelay(
      delay,
      withTiming(1, { duration: 350, easing: Easing.out(Easing.cubic) })
    );
    cardTranslateY.value = withDelay(
      delay,
      withSpring(0, { damping: 18, stiffness: 120 })
    );

    return () => {
      cancelAnimation(cardOpacity);
      cancelAnimation(cardTranslateY);
    };
  }, [animationIndex, skipAnimation, cardOpacity, cardTranslateY]);

  // Success glow animation
  useEffect(() => {
    if (isImported) {
      checkmarkScale.value = withSpring(1, { damping: 8, stiffness: 150 });
      if (!reducedMotion) {
        successGlow.value = withSequence(
          withTiming(0.6, { duration: 200 }),
          withTiming(0, { duration: 800 })
        );
      }
    } else {
      checkmarkScale.value = 0;
      successGlow.value = 0;
    }

    return () => {
      cancelAnimation(checkmarkScale);
      cancelAnimation(successGlow);
    };
  }, [isImported, checkmarkScale, successGlow, reducedMotion]);

  const containerStyle = useAnimatedStyle(() => ({
    opacity: cardOpacity.value,
    transform: [
      { translateY: cardTranslateY.value },
      { scale: pressScale.value },
    ],
  }));

  const shadowStyle = useAnimatedStyle(() => ({
    shadowOpacity: shadowOpacity.value,
  }));
  const glowStyle = useAnimatedStyle(() => ({ opacity: successGlow.value }));
  const checkmarkStyle = useAnimatedStyle(() => ({
    opacity: checkmarkScale.value,
    transform: [{ scale: checkmarkScale.value }],
  }));

  return {
    checkmarkStyle,
    containerStyle,
    glowStyle,
    pressScale,
    shadowOpacity,
    shadowStyle,
  };
}

/**
 * TemplateScienceModal - Main orchestration component
 * Displays scientific research and backing for habit templates
 */

import React, { useMemo } from 'react';
import { View } from 'react-native';
import Animated from 'react-native-reanimated';
import Modal from '../Modal';
import {
  ModalHeader,
  ModalContent,
  FooterSection,
  ConfettiOverlay,
  SkeletonLoading,
} from './components';
import {
  useModalAnimations,
  useScrollAnimations,
  useButtonAnimations,
  useAnimatedStyles,
  useModalHandlers,
} from './hooks';
import { layoutStyles } from './styles';
import { calculateReadingTime } from './TemplateScienceModal.utils';
import type { TemplateScienceModalProps } from './TemplateScienceModal.types';

export default function TemplateScienceModal({
  isLoading = false,
  onClose,
  onUseTemplate,
  template,
  visible,
}: TemplateScienceModalProps) {
  const readingTime = useMemo(
    () => (template ? calculateReadingTime(template) : 0),
    [template]
  );
  const modalAnimations = useModalAnimations({ template, visible });
  const scrollAnimations = useScrollAnimations({ template, visible });
  const { scaleValues, createPressHandlers } = useButtonAnimations();
  const handlers = useModalHandlers({ onClose, onUseTemplate, template });

  const animatedStyles = useAnimatedStyles({
    ...modalAnimations,
    ...scrollAnimations,
    backButtonScale: scaleValues.backButton,
    closeButtonScale: scaleValues.closeButton,
    linkButtonScale: scaleValues.linkButton,
    shareButtonScale: scaleValues.shareButton,
    youtubeButtonScale: scaleValues.youtubeButton,
  });

  if (isLoading || !template) {
    return <SkeletonLoading visible={visible} onClose={onClose} />;
  }

  const baseColor = template.iconColor || '#6366F1';
  const isPopular = (template.popularityScore ?? 0) >= 80;

  return (
    <Modal
      disableBackdropClose={false}
      variant='fullScreen'
      visible={visible}
      onClose={onClose}
    >
      <Animated.View style={[layoutStyles.container, animatedStyles.container]}>
        <Animated.View
          style={[
            layoutStyles.dismissIndicator,
            animatedStyles.dismissIndicator,
          ]}
        >
          <View style={layoutStyles.dismissPill} />
        </Animated.View>
        <ModalHeader
          closeButtonAnimatedStyle={animatedStyles.closeButton}
          headerAnimatedStyle={animatedStyles.header}
          headerTitleAnimatedStyle={animatedStyles.headerTitle}
          pressHandlers={createPressHandlers(scaleValues.closeButton, 0.9)}
          shareButtonAnimatedStyle={animatedStyles.shareButton}
          templateName={template.name}
          onClose={handlers.handleClose}
          onShare={handlers.handleShare}
        />
        <ModalContent
          animatedStyles={animatedStyles}
          baseColor={baseColor}
          createPressHandlers={createPressHandlers}
          isPopular={isPopular}
          readingTime={readingTime}
          scaleValues={scaleValues}
          scrollHandler={scrollAnimations.scrollHandler}
          template={template}
          onLinkPress={handlers.handleLinkPress}
          onYoutubePress={handlers.handleYoutubePress}
        />
        <FooterSection
          animatedStyle={animatedStyles.footer}
          backButtonAnimatedStyle={animatedStyles.backButton}
          baseColor={baseColor}
          pressHandlers={createPressHandlers(scaleValues.backButton, 0.95)}
          templateName={template.name}
          onBack={handlers.handleClose}
          onUseTemplate={handlers.handleUseTemplate}
        />
        <ConfettiOverlay visible={handlers.showConfetti} />
      </Animated.View>
    </Modal>
  );
}

