/**
 * Animation hook for TemplateScienceModal entrance animations
 */

import { useEffect } from 'react';
import {
  useSharedValue,
  withDelay,
  withRepeat,
  withSequence,
  withSpring,
  withTiming,
  Easing,
} from 'react-native-reanimated';
import type { Doc } from '../../../../convex/_generated/dataModel';

interface UseModalAnimationsProps {
  visible: boolean;
  template: Doc<'templates'> | null;
}

export const useModalAnimations = ({
  visible,
  template,
}: UseModalAnimationsProps) => {
  const heroOpacity = useSharedValue(0);
  const heroScale = useSharedValue(0.9);
  const iconGlowScale = useSharedValue(1);
  const iconGlowOpacity = useSharedValue(0.25);
  const card1Progress = useSharedValue(0);
  const card2Progress = useSharedValue(0);
  const card3Progress = useSharedValue(0);
  const footerProgress = useSharedValue(0);

  useEffect(() => {
    if (visible && template) {
      heroOpacity.value = 0;
      heroScale.value = 0.9;
      card1Progress.value = 0;
      card2Progress.value = 0;
      card3Progress.value = 0;
      footerProgress.value = 0;

      heroOpacity.value = withTiming(1, {
        duration: 400,
        easing: Easing.out(Easing.cubic),
      });
      heroScale.value = withSpring(1, { damping: 18, stiffness: 100 });
      card1Progress.value = withDelay(
        150,
        withSpring(1, { damping: 20, stiffness: 90 })
      );
      card2Progress.value = withDelay(
        250,
        withSpring(1, { damping: 20, stiffness: 90 })
      );
      card3Progress.value = withDelay(
        350,
        withSpring(1, { damping: 20, stiffness: 90 })
      );
      footerProgress.value = withDelay(
        450,
        withSpring(1, { damping: 20, stiffness: 90 })
      );

      iconGlowScale.value = withRepeat(
        withSequence(
          withTiming(1.15, {
            duration: 1500,
            easing: Easing.inOut(Easing.ease),
          }),
          withTiming(1, { duration: 1500, easing: Easing.inOut(Easing.ease) })
        ),
        -1,
        false
      );
      iconGlowOpacity.value = withRepeat(
        withSequence(
          withTiming(0.35, {
            duration: 1500,
            easing: Easing.inOut(Easing.ease),
          }),
          withTiming(0.2, { duration: 1500, easing: Easing.inOut(Easing.ease) })
        ),
        -1,
        false
      );
    }
  }, [
    visible,
    template,
    heroOpacity,
    heroScale,
    card1Progress,
    card2Progress,
    card3Progress,
    footerProgress,
    iconGlowScale,
    iconGlowOpacity,
  ]);

  return {
    card1Progress,
    card2Progress,
    card3Progress,
    footerProgress,
    heroOpacity,
    heroScale,
    iconGlowOpacity,
    iconGlowScale,
  };
};

/**
 * Event handlers hook for TemplateScienceModal
 */

import { useCallback, useState } from 'react';
import { Linking, Share } from 'react-native';
import * as Haptics from 'expo-haptics';
import type { Doc } from '../../../../convex/_generated/dataModel';

interface UseModalHandlersProps {
  onClose: () => void;
  onUseTemplate: () => void;
  template: Doc<'templates'> | null;
}

export const useModalHandlers = ({
  onClose,
  onUseTemplate,
  template,
}: UseModalHandlersProps) => {
  const [showConfetti, setShowConfetti] = useState(false);

  const handleClose = useCallback(() => {
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onClose();
  }, [onClose]);

  const handleLinkPress = useCallback(async () => {
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    if (template?.scientificLink) {
      const canOpen = await Linking.canOpenURL(template.scientificLink);
      if (canOpen) {
        await Linking.openURL(template.scientificLink);
      }
    }
  }, [template?.scientificLink]);

  const handleYoutubePress = useCallback(async () => {
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    if (template?.youtubeLink) {
      const canOpen = await Linking.canOpenURL(template.youtubeLink);
      if (canOpen) {
        await Linking.openURL(template.youtubeLink);
      }
    }
  }, [template?.youtubeLink]);

  const handleShare = useCallback(async () => {
    if (!template) return;
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    try {
      await Share.share({
        message: `Check out this habit template: "${template.name}"\n\n${template.description}\n\n🔬 Scientific backing: ${template.scientificReference}`,
        title: `${template.name} - Habit Template`,
      });
    } catch (error) {
      console.error('Error sharing template:', error);
    }
  }, [template]);

  const handleUseTemplate = useCallback(() => {
    void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
    setShowConfetti(true);
    setTimeout(() => {
      onUseTemplate();
    }, 800);
  }, [onUseTemplate]);

  return {
    handleClose,
    handleLinkPress,
    handleShare,
    handleUseTemplate,
    handleYoutubePress,
    showConfetti,
  };
};

