/**
 * VisionBoardPreview Component
 *
 * Full-screen preview for vision board cards with gestures:
 * - Swipe down to dismiss
 * - Swipe left/right to navigate between cards
 * - Edit button to open editor
 */

import React, { useEffect, useRef, useCallback } from 'react';
import {
  View,
  Text,
  Pressable,
  Modal as RNModal,
  Dimensions,
  ScrollView,
  AccessibilityInfo,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  runOnJS,
  interpolate,
  Extrapolation,
} from 'react-native-reanimated';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';
import { X, Edit3, ChevronLeft, ChevronRight, Eye } from 'lucide-react-native';
import * as Haptics from 'expo-haptics';
import type { Doc } from '../../../convex/_generated/dataModel';

const { height: SCREEN_HEIGHT, width: SCREEN_WIDTH } = Dimensions.get('window');
const DISMISS_THRESHOLD = 150;
const SWIPE_VELOCITY_THRESHOLD = 500;
const HORIZONTAL_SWIPE_THRESHOLD = 80;

type VisionBoardItem = Doc<'visionBoardItems'>;

interface VisionBoardPreviewProps {
  items: VisionBoardItem[];
  initialIndex: number;
  visible: boolean;
  onClose: () => void;
  onEdit: (item: VisionBoardItem) => void;
}

export function VisionBoardPreview({
  items,
  initialIndex,
  visible,
  onClose,
  onEdit,
}: VisionBoardPreviewProps) {
  const insets = useSafeAreaInsets();
  const [currentIndex, setCurrentIndex] = React.useState(initialIndex);
  const [reduceMotion, setReduceMotion] = React.useState(false);
  const scrollViewRef = useRef<ScrollView>(null);

  // Check reduce motion preference
  useEffect(() => {
    AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
    const subscription = AccessibilityInfo.addEventListener(
      'reduceMotionChanged',
      setReduceMotion
    );
    return () => subscription.remove();
  }, []);

  // Reset to initial index when modal opens
  useEffect(() => {
    if (visible) {
      setCurrentIndex(initialIndex);
    }
  }, [visible, initialIndex]);

  // Animation values
  const translateY = useSharedValue(0);
  const translateX = useSharedValue(0);
  const scale = useSharedValue(1);
  const opacity = useSharedValue(1);

  const currentItem = items[currentIndex];
  const hasNext = currentIndex < items.length - 1;
  const hasPrev = currentIndex > 0;

  const handleClose = useCallback(() => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onClose();
  }, [onClose]);

  const handleEdit = useCallback(() => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    if (currentItem) {
      onEdit(currentItem);
    }
  }, [currentItem, onEdit]);

  const goToNext = useCallback(() => {
    if (hasNext) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      setCurrentIndex((prev) => prev + 1);
    }
  }, [hasNext]);

  const goToPrev = useCallback(() => {
    if (hasPrev) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      setCurrentIndex((prev) => prev - 1);
    }
  }, [hasPrev]);

  // Pan gesture for swipe to dismiss and navigate
  const panGesture = Gesture.Pan()
    .onUpdate((event) => {
      // Vertical swipe (dismiss)
      if (Math.abs(event.translationY) > Math.abs(event.translationX)) {
        translateY.value = event.translationY;
        const progress = Math.abs(event.translationY) / DISMISS_THRESHOLD;
        scale.value = interpolate(progress, [0, 1], [1, 0.9], Extrapolation.CLAMP);
        opacity.value = interpolate(progress, [0, 1], [1, 0.7], Extrapolation.CLAMP);
      } else {
        // Horizontal swipe (navigate)
        translateX.value = event.translationX;
      }
    })
    .onEnd((event) => {
      // Use Math.round on velocity to avoid precision loss error in Reanimated
      const velocityY = Math.round(event.velocityY);
      const velocityX = Math.round(event.velocityX);

      // Check for vertical dismiss
      if (
        Math.abs(event.translationY) > DISMISS_THRESHOLD ||
        Math.abs(velocityY) > SWIPE_VELOCITY_THRESHOLD
      ) {
        translateY.value = reduceMotion
          ? SCREEN_HEIGHT
          : withTiming(SCREEN_HEIGHT, { duration: 200 });
        opacity.value = reduceMotion ? 0 : withTiming(0, { duration: 200 });
        runOnJS(handleClose)();
        return;
      }

      // Check for horizontal navigation
      if (
        event.translationX < -HORIZONTAL_SWIPE_THRESHOLD ||
        velocityX < -SWIPE_VELOCITY_THRESHOLD
      ) {
        // Swipe left - go next
        if (hasNext) {
          runOnJS(goToNext)();
        }
      } else if (
        event.translationX > HORIZONTAL_SWIPE_THRESHOLD ||
        velocityX > SWIPE_VELOCITY_THRESHOLD
      ) {
        // Swipe right - go prev
        if (hasPrev) {
          runOnJS(goToPrev)();
        }
      }

      // Reset animations
      translateY.value = reduceMotion ? 0 : withSpring(0, { damping: 20, stiffness: 200 });
      translateX.value = reduceMotion ? 0 : withSpring(0, { damping: 20, stiffness: 200 });
      scale.value = reduceMotion ? 1 : withSpring(1, { damping: 20, stiffness: 200 });
      opacity.value = reduceMotion ? 1 : withSpring(1, { damping: 20, stiffness: 200 });
    });

  const animatedContainerStyle = useAnimatedStyle(() => ({
    transform: [
      { translateY: translateY.value },
      { translateX: translateX.value },
      { scale: scale.value },
    ],
    opacity: opacity.value,
  }));

  if (!currentItem) {
    return null;
  }

  return (
    <RNModal
      animationType={reduceMotion ? 'none' : 'fade'}
      statusBarTranslucent
      transparent
      visible={visible}
      onRequestClose={handleClose}
    >
      <View className="flex-1 bg-black/90">
        <GestureDetector gesture={panGesture}>
          <Animated.View className="flex-1" style={animatedContainerStyle}>
            {/* Header */}
            <View
              className="flex-row items-center justify-between px-5"
              style={{ paddingTop: insets.top + 16 }}
            >
              {/* Close button */}
              <Pressable
                accessibilityLabel="Close preview"
                accessibilityRole="button"
                className="h-10 w-10 items-center justify-center rounded-full bg-white/10 active:bg-white/20"
                onPress={handleClose}
              >
                <X className="text-white" size={22} />
              </Pressable>

              {/* Counter */}
              <View className="flex-row items-center gap-2">
                <Eye className="text-white/60" size={16} />
                <Text className="text-sm font-medium text-white/80">
                  {currentIndex + 1} of {items.length}
                </Text>
              </View>

              {/* Edit button */}
              <Pressable
                accessibilityLabel="Edit this card"
                accessibilityRole="button"
                className="h-10 w-10 items-center justify-center rounded-full bg-white/10 active:bg-white/20"
                onPress={handleEdit}
              >
                <Edit3 className="text-white" size={20} />
              </Pressable>
            </View>

            {/* Content */}
            <View className="flex-1 justify-center px-6">
              <View className="rounded-3xl bg-white/10 p-6 backdrop-blur-lg">
                {/* Title */}
                <Text className="mb-4 text-center text-2xl font-bold tracking-tight text-white">
                  {currentItem.title}
                </Text>

                {/* Body */}
                {currentItem.body && (
                  <ScrollView
                    className="max-h-80"
                    showsVerticalScrollIndicator={false}
                  >
                    <Text className="text-center text-lg leading-7 text-white/90">
                      {currentItem.body}
                    </Text>
                  </ScrollView>
                )}

                {/* Created date */}
                <Text className="mt-6 text-center text-xs text-white/50">
                  Created{' '}
                  {new Date(currentItem.createdAt).toLocaleDateString('en-US', {
                    month: 'short',
                    day: 'numeric',
                    year: 'numeric',
                  })}
                </Text>
              </View>

              {/* Swipe hint */}
              <Text className="mt-6 text-center text-sm text-white/40">
                Swipe down to close • Swipe left/right to navigate
              </Text>
            </View>

            {/* Navigation arrows */}
            <View
              className="flex-row items-center justify-between px-5 pb-4"
              style={{ paddingBottom: insets.bottom + 16 }}
            >
              {/* Previous */}
              <Pressable
                accessibilityLabel="Previous card"
                accessibilityRole="button"
                className={`h-12 w-12 items-center justify-center rounded-full ${
                  hasPrev ? 'bg-white/10 active:bg-white/20' : 'opacity-30'
                }`}
                disabled={!hasPrev}
                onPress={goToPrev}
              >
                <ChevronLeft className="text-white" size={24} />
              </Pressable>

              {/* Dots indicator */}
              <View className="flex-row items-center gap-2">
                {items.map((_, index) => (
                  <View
                    key={index}
                    className={`h-2 rounded-full ${
                      index === currentIndex ? 'w-6 bg-white' : 'w-2 bg-white/30'
                    }`}
                  />
                ))}
              </View>

              {/* Next */}
              <Pressable
                accessibilityLabel="Next card"
                accessibilityRole="button"
                className={`h-12 w-12 items-center justify-center rounded-full ${
                  hasNext ? 'bg-white/10 active:bg-white/20' : 'opacity-30'
                }`}
                disabled={!hasNext}
                onPress={goToNext}
              >
                <ChevronRight className="text-white" size={24} />
              </Pressable>
            </View>
          </Animated.View>
        </GestureDetector>
      </View>
    </RNModal>
  );
}

/**
 * VisualizationExercise Component
 * Interactive exercise based on Andrew Huberman's visualization techniques
 *
 * Key principles:
 * - Visualize positive outcomes (pull motivation)
 * - Visualize negative outcomes/consequences (push motivation - "fear setting")
 * - Mental contrasting creates productive tension that drives action
 *
 * References:
 * - Huberman Lab Podcast: Goal Setting & Neural Mechanisms
 * - Tim Ferriss "Fear Setting" (influenced by Stoic premeditatio malorum)
 * - Gabriele Oettingen's WOOP method (mental contrasting)
 */

import React, { useState } from 'react';
import { View, KeyboardAvoidingView, Platform } from 'react-native';
import {
  StepIndicator,
  IntroStep,
  PositiveStep,
  NegativeStep,
  SummaryStep,
} from './components';
import type {
  VisualizationStep,
  VisualizationData,
  VisualizationExerciseProps,
} from './types';

const STEP_NUMBERS: Record<VisualizationStep, number> = {
  intro: 1,
  negative: 3,
  positive: 2,
  summary: 4,
};

/**
 * Main VisualizationExercise Component
 * Orchestrates the multi-step visualization flow
 */
export function VisualizationExercise({
  habitName,
  onClose,
  onSave,
}: VisualizationExerciseProps) {
  const [step, setStep] = useState<VisualizationStep>('intro');
  const [positiveVisualization, setPositiveVisualization] = useState('');
  const [negativeVisualization, setNegativeVisualization] = useState('');

  const handleSave = () => {
    const data: VisualizationData = {
      habitName,
      negativeVisualization,
      positiveVisualization,
      timestamp: Date.now(),
    };
    onSave?.(data);
    onClose?.();
  };

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      className='flex-1'
    >
      <View className='flex-1 gap-6'>
        <StepIndicator currentStep={STEP_NUMBERS[step]} totalSteps={4} />

        {step === 'intro' && (
          <IntroStep habitName={habitName} onNext={() => setStep('positive')} />
        )}

        {step === 'positive' && (
          <PositiveStep
            value={positiveVisualization}
            onBack={() => setStep('intro')}
            onNext={() => setStep('negative')}
            onValueChange={setPositiveVisualization}
          />
        )}

        {step === 'negative' && (
          <NegativeStep
            value={negativeVisualization}
            onBack={() => setStep('positive')}
            onNext={() => setStep('summary')}
            onValueChange={setNegativeVisualization}
          />
        )}

        {step === 'summary' && (
          <SummaryStep
            habitName={habitName}
            negativeVisualization={negativeVisualization}
            positiveVisualization={positiveVisualization}
            onBack={() => setStep('negative')}
            onSave={handleSave}
          />
        )}
      </View>
    </KeyboardAvoidingView>
  );
}

export default VisualizationExercise;

/**
 * NavigationButtons Component
 * Back and Continue buttons for step navigation
 */

import React from 'react';
import { View, Text, Pressable } from 'react-native';
import { ChevronRight } from 'lucide-react-native';
import * as Haptics from 'expo-haptics';
import { clsx } from 'clsx';

interface NavigationButtonsProps {
  onBack: () => void;
  onNext: () => void;
  canContinue: boolean;
  activeColor: string;
  activeHoverColor: string;
}

export function NavigationButtons({
  onBack,
  onNext,
  canContinue,
  activeColor,
  activeHoverColor,
}: NavigationButtonsProps) {
  return (
    <View className='flex-row gap-3'>
      <Pressable
        accessibilityLabel='Go back'
        accessibilityRole='button'
        className='flex-1 items-center rounded-xl border border-stone-200 bg-white py-3.5 active:bg-stone-50'
        onPress={() => {
          Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
          onBack();
        }}
      >
        <Text className='text-sm font-medium text-stone-600'>Back</Text>
      </Pressable>
      <Pressable
        accessibilityLabel='Continue'
        accessibilityRole='button'
        className={clsx(
          'flex-1 flex-row items-center justify-center gap-2 rounded-xl py-3.5',
          canContinue
            ? `${activeColor} active:${activeHoverColor}`
            : 'bg-stone-200'
        )}
        disabled={!canContinue}
        onPress={() => {
          Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
          onNext();
        }}
      >
        <Text
          className={clsx(
            'text-sm font-semibold',
            canContinue ? 'text-white' : 'text-stone-400'
          )}
        >
          Continue
        </Text>
        <ChevronRight
          className={canContinue ? 'text-white' : 'text-stone-400'}
          size={18}
        />
      </Pressable>
    </View>
  );
}

/**
 * NegativeStep Component
 * Guides user through negative visualization (failure consequences)
 * Based on Tim Ferriss "Fear Setting" and Stoic premeditatio malorum
 */

import React from 'react';
import { View, Text, TextInput } from 'react-native';
import Animated, { FadeInDown } from 'react-native-reanimated';
import { CloudRain, AlertTriangle, Lightbulb } from 'lucide-react-native';
import { PromptList } from './PromptList';
import { NavigationButtons } from './NavigationButtons';
import type { VisualizationInputStepProps } from '../types';

const PROMPTS = [
  'What happens if you quit this habit?',
  'How will you feel 6 months from now?',
  'What opportunities will you miss?',
];

export function NegativeStep({
  onBack,
  onNext,
  value,
  onValueChange,
}: VisualizationInputStepProps) {
  return (
    <Animated.View className='flex-1 gap-5' entering={FadeInDown.springify()}>
      <View className='items-center gap-3'>
        <View className='h-16 w-16 items-center justify-center rounded-2xl bg-gradient-to-br from-rose-400 to-red-500'>
          <CloudRain className='text-white' size={32} />
        </View>
        <Text className='text-xl font-bold text-stone-900'>
          Visualize Failure
        </Text>
        <Text className='px-4 text-center text-sm text-stone-500'>
          Now imagine you've given up on this habit. What are the consequences?
          Be honest.
        </Text>
      </View>

      <PromptList
        bgColor='bg-rose-50'
        Icon={AlertTriangle}
        iconColor='text-rose-500'
        prompts={PROMPTS}
        textColor='text-rose-800'
        title='Consider these questions:'
        titleColor='text-rose-700'
      />

      <View className='flex-row items-start gap-2 rounded-xl bg-amber-50 p-3'>
        <Lightbulb className='mt-0.5 text-amber-500' size={16} />
        <Text className='flex-1 text-xs leading-relaxed text-amber-800'>
          <Text className='font-semibold'>Why this works: </Text>
          Fear of loss is neurologically twice as powerful as desire for gain.
        </Text>
      </View>

      <View className='flex-1'>
        <Text className='mb-2 text-sm font-medium text-stone-700'>
          Describe the consequences:
        </Text>
        <TextInput
          multiline
          className='flex-1 rounded-2xl border border-stone-200 bg-white p-4 text-base text-stone-800'
          placeholder='If I give up on this habit, I will experience...'
          placeholderTextColor='#a8a29e'
          style={{ minHeight: 150, textAlignVertical: 'top' }}
          value={value}
          onChangeText={onValueChange}
        />
      </View>

      <NavigationButtons
        activeColor='bg-rose-500'
        activeHoverColor='bg-rose-600'
        canContinue={value.trim().length > 0}
        onBack={onBack}
        onNext={onNext}
      />
    </Animated.View>
  );
}

/**
 * PositiveStep Component
 * Guides user through positive visualization (success outcomes)
 */

import React from 'react';
import { View, Text, TextInput } from 'react-native';
import Animated, { FadeInDown } from 'react-native-reanimated';
import { Sun, CheckCircle2 } from 'lucide-react-native';
