import { useOAuth } from '@clerk/clerk-expo';
import * as Linking from 'expo-linking';
import * as WebBrowser from 'expo-web-browser';
import { useState } from 'react';
import { ActivityIndicator, Alert, Text, TouchableOpacity, View } from 'react-native';
import Animated, {
  SharedValue,
  useAnimatedStyle,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';

import { AppleLogo, GoogleLogo } from './logos';

// Required for OAuth to work properly
WebBrowser.maybeCompleteAuthSession();

const AnimatedTouchable = Animated.createAnimatedComponent(TouchableOpacity);

/**
 * SocialLoginButtons - OAuth login buttons for Google and Apple
 *
 * Features:
 * - Google and Apple OAuth flows via Clerk
 * - Professional SVG brand logos
 * - Press animations with spring physics
 * - Individual loading states per button
 * - User-friendly error messages
 * - Accessibility support with labels and hints
 *
 * @example
 * <SocialLoginButtons />
 */
export function SocialLoginButtons() {
  const { startOAuthFlow: startGoogleFlow } = useOAuth({ strategy: 'oauth_google' });
  const { startOAuthFlow: startAppleFlow } = useOAuth({ strategy: 'oauth_apple' });

  const [googleLoading, setGoogleLoading] = useState(false);
  const [appleLoading, setAppleLoading] = useState(false);

  const googleScale = useSharedValue(1);
  const appleScale = useSharedValue(1);

  const googleAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: googleScale.value }],
  }));

  const appleAnimatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: appleScale.value }],
  }));

  const handlePressIn = (scale: SharedValue<number>) => {
    scale.value = withSpring(0.98, { damping: 15, stiffness: 300 });
  };

  const handlePressOut = (scale: SharedValue<number>) => {
    scale.value = withSpring(1, { damping: 15, stiffness: 300 });
  };

  /**
   * Converts OAuth errors into user-friendly messages
   * @param err - The error object from OAuth flow
   * @returns User-friendly error message or null if error should be ignored
   */
  const getErrorMessage = (err: any): string | null => {
    const errorCode = err.errors?.[0]?.code;
    const errorMessage = err.errors?.[0]?.message;

    // Handle common error scenarios with user-friendly messages
    if (errorCode === 'session_exists') {
      return 'You are already signed in. Please sign out and try again.';
    }
    if (errorCode === 'oauth_access_denied') {
      return 'Access was denied. Please try again or use a different sign-in method.';
    }
    if (errorMessage?.includes('cancelled') || errorMessage?.includes('canceled')) {
      return null; // Don't show error for user cancellation
    }
    if (err.message?.includes('network')) {
      return 'Network error. Please check your connection and try again.';
    }

    return errorMessage || 'An unexpected error occurred. Please try again.';
  };

  const handleGoogleSignIn = async () => {
    setGoogleLoading(true);
    try {
      const { createdSessionId, setActive } = await startGoogleFlow({
        redirectUrl: Linking.createURL('/'),
      });

      if (createdSessionId && setActive) {
        await setActive({ session: createdSessionId });
      }
    } catch (err: any) {
      console.error('Google OAuth error:', err);
      const errorMessage = getErrorMessage(err);
      if (errorMessage) {
        Alert.alert('Sign In Failed', errorMessage);
      }
    } finally {
      setGoogleLoading(false);
    }
  };

  const handleAppleSignIn = async () => {
    setAppleLoading(true);
    try {
      const { createdSessionId, setActive } = await startAppleFlow({
        redirectUrl: Linking.createURL('/'),
      });

      if (createdSessionId && setActive) {
        await setActive({ session: createdSessionId });
      }
    } catch (err: any) {
      console.error('Apple OAuth error:', err);
      const errorMessage = getErrorMessage(err);
      if (errorMessage) {
        Alert.alert('Sign In Failed', errorMessage);
      }
    } finally {
      setAppleLoading(false);
    }
  };

  return (
    <View className="gap-3">
      <AnimatedTouchable
        className="flex-row items-center justify-center gap-3 rounded-3xl border border-stone-200 bg-white py-[14px]"
        onPress={handleGoogleSignIn}
        onPressIn={() => handlePressIn(googleScale)}
        onPressOut={() => handlePressOut(googleScale)}
        disabled={googleLoading || appleLoading}
        accessible={true}
        accessibilityLabel="Sign in with Google"
        accessibilityRole="button"
        accessibilityHint="Opens Google sign in flow"
        style={googleAnimatedStyle}
      >
        {googleLoading ? (
          <ActivityIndicator size="small" color="#4285F4" />
        ) : (
          <GoogleLogo size={20} />
        )}
        <Text
          className="text-[15px] font-semibold tracking-[2px] text-stone-900"
          style={{ opacity: googleLoading ? 0.6 : 1 }}
        >
          CONTINUE WITH GOOGLE
        </Text>
      </AnimatedTouchable>

      <AnimatedTouchable
        className="flex-row items-center justify-center gap-3 rounded-3xl border border-stone-200 bg-white py-[14px]"
        onPress={handleAppleSignIn}
        onPressIn={() => handlePressIn(appleScale)}
        onPressOut={() => handlePressOut(appleScale)}
        disabled={googleLoading || appleLoading}
        accessible={true}
        accessibilityLabel="Sign in with Apple"
        accessibilityRole="button"
        accessibilityHint="Opens Apple sign in flow"
        style={appleAnimatedStyle}
      >
        {appleLoading ? (
          <ActivityIndicator size="small" color="#000000" />
        ) : (
          <AppleLogo size={20} />
        )}
        <Text
          className="text-[15px] font-semibold tracking-[2px] text-stone-900"
          style={{ opacity: appleLoading ? 0.6 : 1 }}
        >
          CONTINUE WITH APPLE
        </Text>
      </AnimatedTouchable>

      <View
        className="my-4 flex-row items-center gap-4"
        accessible={true}
        accessibilityRole="none"
        importantForAccessibility="no-hide-descendants"
      >
        <View className="h-[1px] flex-1 bg-stone-200" />
        <Text className="text-xs text-stone-400" aria-hidden={true}>OR</Text>
        <View className="h-[1px] flex-1 bg-stone-200" />
      </View>
    </View>
  );
}

import { useEffect, useRef } from 'react';
import { Animated, Easing, View } from 'react-native';

interface SparkleBurstProps {
  color?: string;
  isActive: boolean;
  onComplete?: () => void;
  reduceMotion?: boolean;
  size?: number;
}

const DOT_COUNT = 6; // Enhanced sparkle for premium celebrations

export const SparkleBurst = ({
  color = '#34D399',
  isActive,
  onComplete,
  reduceMotion = false,
  size = 40, // Slightly larger for more impact
}: SparkleBurstProps) => {
  const opacity = useRef(new Animated.Value(0)).current;
  const scale = useRef(new Animated.Value(0.6)).current;

  useEffect(() => {
    console.log('🌟 SparkleBurst:', { isActive, reduceMotion, color });

    if (!isActive || reduceMotion) {
      if (isActive && reduceMotion) {
        console.log('🌟 SparkleBurst skipped (reduceMotion enabled)');
        onComplete?.();
      }
      return;
    }

    console.log('🌟 SparkleBurst TRIGGERED!');
    opacity.setValue(0.9); // More prominent for celebration
    scale.setValue(0.6);

    Animated.parallel([
      Animated.timing(opacity, {
        duration: 400, // Slightly longer celebration
        easing: Easing.out(Easing.ease),
        toValue: 0,
        useNativeDriver: true,
      }),
      Animated.timing(scale, {
        duration: 400, // Longer expansion for impact
        easing: Easing.out(Easing.cubic),
        toValue: 1.6, // More expansive celebration
        useNativeDriver: true,
      }),
    ]).start(() => {
      console.log('🌟 SparkleBurst completed');
      onComplete?.();
    });
  }, [isActive, onComplete, opacity, reduceMotion, scale]);

  if (!isActive || reduceMotion) {
    return null;
  }

  const dotSize = size * 0.18; // Small, subtle sparkles

  return (
    <Animated.View
      className='absolute items-center justify-center'
      pointerEvents='none'
      style={{
        height: size,
        opacity,
        transform: [{ scale }],
        width: size,
        zIndex: 1000, // Render ABOVE everything
      }}
    >
      {Array.from({ length: DOT_COUNT }).map((_, index) => {
        const angle = (index / DOT_COUNT) * Math.PI * 2;
        // Round to avoid "Loss of precision during arithmetic conversion" error in Reanimated
        const translateX = Math.round(Math.cos(angle) * (size / 2.2));
        const translateY = Math.round(Math.sin(angle) * (size / 2.2));

        return (
          <Animated.View
            // eslint-disable-next-line react/no-array-index-key
            key={index}
            className='absolute rounded-full'
            style={{
              backgroundColor: color, // Use accent color
              height: dotSize,
              left: size / 2 - dotSize / 2,
              top: size / 2 - dotSize / 2,
              transform: [
                { translateX },
                { translateY },
              ],
              width: dotSize,
              shadowColor: color,
              shadowOffset: { width: 0, height: 0 },
              shadowOpacity: 0.5, // Subtle glow
              shadowRadius: 3,
              elevation: 4,
            }}
          />
        );
      })}

      {/* Center glow - subtle */}
      <View
        className='absolute rounded-full'
        pointerEvents='none'
        style={{
          backgroundColor: `${color}40`, // 25% opacity
          height: dotSize * 2,
          width: dotSize * 2,
          shadowColor: color,
          shadowOffset: { width: 0, height: 0 },
          shadowOpacity: 0.4,
          shadowRadius: 4,
        }}
      />
    </Animated.View>
  );
};

export default SparkleBurst;

