          }}
        ]
      );
      return;
    }
    openCreateHabitScreen();
  }, [
    list.hasReachedHabitLimit,
    list.isPremiumUser,
    openCreateHabitScreen,
    triggerWarning,
  ]);

  return (
    <GestureHandlerRootView style={{ flex: 1 }}>
      <View className='flex-1 bg-gradient-to-b from-stone-50 via-amber-50/20 to-stone-100'>
