import { useEffect } from 'react';
import Animated, {
  cancelAnimation,
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withRepeat,
  withSequence,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

import type { FloatingParticleProps } from '../HabitsEmptyState.types';

export function FloatingParticle({
  delay,
  emoji,
  duration = 3000,
}: FloatingParticleProps) {
  const translateY = useSharedValue(0);
  const translateX = useSharedValue(0);
  const opacity = useSharedValue(0);
  const scale = useSharedValue(0.5);

  useEffect(() => {
    opacity.value = withDelay(delay, withTiming(0.6, { duration: 500 }));
    scale.value = withDelay(delay, withSpring(1, { damping: 12 }));

    translateY.value = withDelay(
      delay,
      withRepeat(
        withSequence(
          withTiming(-12, { duration: duration / 2 }),
          withTiming(0, { duration: duration / 2 })
        ),
        -1,
        true
      )
    );

    translateX.value = withDelay(
      delay,
      withRepeat(
        withSequence(
          withTiming(6, { duration: duration / 3 }),
          withTiming(-6, { duration: duration / 3 }),
          withTiming(0, { duration: duration / 3 })
        ),
        -1,
        true
      )
    );

    return () => {
      cancelAnimation(translateY);
      cancelAnimation(translateX);
      cancelAnimation(opacity);
      cancelAnimation(scale);
    };
  }, [delay, duration, translateY, translateX, opacity, scale]);

  const particleStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [
      { translateY: translateY.value },
      { translateX: translateX.value },
      { scale: scale.value },
    ],
  }));

  return (
    <Animated.Text className='text-lg' style={particleStyle}>
      {emoji}
    </Animated.Text>
  );
}

import { Pressable, View } from 'react-native';
import Animated, {
  FadeInDown,
  withSequence,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

import { useHapticFeedback } from '../../../../../../hooks/useHapticFeedback';
import type { QuickStartButtonProps } from '../../HabitsEmptyState.types';
import { QuickStartButtonContent } from './QuickStartButtonContent';
import { useQuickStartAnimations } from './useQuickStartAnimations';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

export function QuickStartButton({
  habit,
  isCreating,
  isSuccess,
  onPress,
  containerStyle,
  index,
}: QuickStartButtonProps) {
  const { triggerLightImpact, triggerSelection } = useHapticFeedback();
  const {
    scale,
    rotation,
    bgProgress,
    animatedStyle,
    pulseRingStyle,
    checkmarkStyle,
    contentStyle,
  } = useQuickStartAnimations(index, isSuccess);

  const handlePress = async () => {
    triggerSelection();
    rotation.value = withSequence(
      withSpring(-3, { damping: 8, stiffness: 400 }),
      withSpring(3, { damping: 8, stiffness: 400 }),
      withSpring(0, { damping: 10, stiffness: 300 })
    );
    await onPress();
  };

  return (
    <View style={containerStyle}>
      <Animated.View
        className='absolute inset-[-2px] rounded-2xl border-2 border-emerald-500'
        pointerEvents='none'
        style={pulseRingStyle}
      />
      <AnimatedPressable
        accessibilityLabel={`Add ${habit.name} habit`}
        accessibilityRole='button'
        className='items-center justify-center gap-2 rounded-2xl border px-3 py-4 shadow-sm'
        disabled={isCreating || isSuccess}
        entering={FadeInDown.delay(200 + index * 100)
          .springify()
          .damping(12)
          .mass(0.8)
          .stiffness(100)}
        style={animatedStyle}
        onPress={handlePress}
        onPressIn={() => {
          triggerLightImpact();
          scale.value = withSpring(0.92, { damping: 12, stiffness: 400 });
          bgProgress.value = withTiming(1, { duration: 100 });
        }}
        onPressOut={() => {
          scale.value = withSpring(1, { damping: 12, stiffness: 300 });
          if (!isCreating) {
            bgProgress.value = withTiming(0, { duration: 150 });
          }
        }}
      >
        <QuickStartButtonContent
          checkmarkStyle={checkmarkStyle}
          contentStyle={contentStyle}
          habit={habit}
          isCreating={isCreating}
          isSuccess={isSuccess}
        />
      </AnimatedPressable>
    </View>
  );
}

import { useEffect } from 'react';
import {
  cancelAnimation,
  interpolateColor,
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withRepeat,
  withSequence,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

export function useQuickStartAnimations(index: number, isSuccess: boolean) {
  const scale = useSharedValue(1);
  const rotation = useSharedValue(0);
  const bgProgress = useSharedValue(0);
  const checkScale = useSharedValue(0);
  const pulseOpacity = useSharedValue(0);
  const pulseScale = useSharedValue(1);

  useEffect(() => {
    const delay = index * 500;
    pulseOpacity.value = withDelay(
      delay,
      withRepeat(
        withSequence(
          withTiming(0, { duration: 0 }),
          withTiming(0.5, { duration: 1000 }),
          withTiming(0, { duration: 1000 })
        ),
        -1,
        false
      )
    );
    pulseScale.value = withDelay(
      delay,
      withRepeat(
        withSequence(
          withTiming(1, { duration: 0 }),
          withTiming(1.02, { duration: 1000 }),
          withTiming(1, { duration: 1000 })
        ),
        -1,
        false
      )
    );

    return () => {
      cancelAnimation(pulseOpacity);
      cancelAnimation(pulseScale);
    };
  }, [index, pulseOpacity, pulseScale]);

  useEffect(() => {
    if (isSuccess) {
      bgProgress.value = withSpring(2, { damping: 12 });
      checkScale.value = withSpring(1, { damping: 10, stiffness: 200 });
      scale.value = withSequence(
        withSpring(1.12, { damping: 8 }),
        withSpring(1, { damping: 12 })
      );
    } else {
      bgProgress.value = withTiming(0, { duration: 300 });
      checkScale.value = withTiming(0, { duration: 200 });
    }
  }, [isSuccess, bgProgress, checkScale, scale]);

  const animatedStyle = useAnimatedStyle(() => ({
    backgroundColor: interpolateColor(
      bgProgress.value,
      [0, 1, 2],
      ['#ffffff', '#fafaf9', '#dcfce7']
    ),
    borderColor: interpolateColor(
      bgProgress.value,
      [0, 1, 2],
      ['#e7e5e4', '#d6d3d1', '#86efac']
    ),
    transform: [{ scale: scale.value }, { rotate: `${rotation.value}deg` }],
  }));

  const pulseRingStyle = useAnimatedStyle(() => ({
    opacity: pulseOpacity.value,
    transform: [{ scale: pulseScale.value }],
  }));

  const checkmarkStyle = useAnimatedStyle(() => ({
    opacity: checkScale.value,
    transform: [{ scale: checkScale.value }],
  }));

  const contentStyle = useAnimatedStyle(() => ({
    opacity: isSuccess ? 0 : 1,
  }));

  return {
    animatedStyle,
    bgProgress,
    checkmarkStyle,
    contentStyle,
    pulseRingStyle,
    rotation,
    scale,
  };
}

