    triggerSelection();
    shuffleScale.value = withSequence(
      withTiming(0.85, { duration: 100 }),
      withSpring(1, { damping: 12 })
    );
    const shuffled = [...ALL_HABITS].sort(() => Math.random() - 0.5);
