import { useCallback, useRef, useState } from 'react';
import { Keyboard, TextInput, View } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useReducedMotion,
  withTiming,
  Easing,
} from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { useHapticFeedback } from '../../../../hooks/useHapticFeedback';
import { useKeyboardVisible } from '../../../../hooks/useKeyboardVisible';
import { useTimeBasedChipAnalytics } from './analytics';
import { AnimatedEntrance } from './AnimatedEntrance';
import { ENTRANCE_DELAYS, KEYBOARD_LAYOUT } from './animations';
import { COLORS, COPY } from './constants';
import { CtaButton } from './CtaButton';
import { ErrorMessage } from './ErrorMessage';
import { HabitInput } from './HabitInput';
import { HeroIcon } from './HeroIcon';
import { InlineHint } from './InlineHint';
import { LoadingSkeleton } from './LoadingSkeleton';
import { SuccessState } from './SuccessState';
import { SuggestionChips } from './SuggestionChips';
import type { HabitsEmptyStateMinimalProps, SuggestionChip } from './types';
import { getTimeBasedChips } from './utils';

/**
 * Minimal empty state for habits screen
 *
 * Provides a streamlined flow for creating the first habit:
 * 1. Hero icon with breathing animation
 * 2. Question headline
 * 3. Text input or suggestion chips
 * 4. Primary CTA button
 * 5. Success celebration on creation
 */
export function HabitsEmptyStateMinimal({
  isLoading = false,
  onQuickCreateHabit,
  openTemplatesScreen,
  openCreateHabitScreen,
  onSuccessTransitionComplete,
}: HabitsEmptyStateMinimalProps) {
  const inputRef = useRef<TextInput>(null);
  const { triggerSuccess } = useHapticFeedback();
  const { isKeyboardVisible } = useKeyboardVisible();
  const shouldReduceMotion = useReducedMotion();
  const insets = useSafeAreaInsets();

  // Extract bottom inset for use in worklet (capture at mount)
  const bottomInset = insets.bottom;

  // Timing config for keyboard-aware transitions
  const timingConfig = {
    duration: shouldReduceMotion ? 0 : KEYBOARD_LAYOUT.transitionDuration,
    easing: Easing.out(Easing.ease),
  };

  // Animated styles for keyboard-aware compact mode
  const containerAnimatedStyle = useAnimatedStyle(() => ({
    justifyContent: isKeyboardVisible ? 'flex-start' : 'center',
    paddingBottom: withTiming(
      isKeyboardVisible ? 0 : bottomInset + 20, // +20 for breathing room above safe area
      timingConfig
    ),
    paddingTop: withTiming(
      isKeyboardVisible ? KEYBOARD_LAYOUT.topPadding : 0,
      timingConfig
    ),
  }));

  const heroAnimatedStyle = useAnimatedStyle(() => ({
    transform: [
      {
        scale: withTiming(
          isKeyboardVisible ? KEYBOARD_LAYOUT.compactHeroSize / 80 : 1,
          timingConfig
        ),
      },
    ],
  }));

  const headlineAnimatedStyle = useAnimatedStyle(() => ({
    fontSize: withTiming(
      isKeyboardVisible ? KEYBOARD_LAYOUT.compactHeadlineFontSize : 24,
      timingConfig
    ),
    marginBottom: withTiming(isKeyboardVisible ? 16 : 32, timingConfig),
    marginTop: withTiming(isKeyboardVisible ? 16 : 32, timingConfig),
  }));

  const chipsAnimatedStyle = useAnimatedStyle(() => ({
    marginBottom: withTiming(isKeyboardVisible ? 0 : 32, timingConfig),
    maxHeight: withTiming(isKeyboardVisible ? 0 : 200, timingConfig),
    opacity: withTiming(isKeyboardVisible ? 0 : 1, timingConfig),
    overflow: 'hidden' as const,
  }));

  const secondaryLinksAnimatedStyle = useAnimatedStyle(() => ({
    maxHeight: withTiming(isKeyboardVisible ? 0 : 100, timingConfig),
    opacity: withTiming(isKeyboardVisible ? 0 : 1, timingConfig),
    overflow: 'hidden' as const,
  }));

  // Component state
  const [inputValue, setInputValue] = useState('');
  const [selectedChipIndex, setSelectedChipIndex] = useState<number | null>(
    null
  );
  const [selectedEmoji, setSelectedEmoji] = useState<string | null>(null);
  const [isCreating, setIsCreating] = useState(false);
  const [successHabitName, setSuccessHabitName] = useState<string | null>(null);
  const [successEmoji, setSuccessEmoji] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  // Analytics tracking
  const analytics = useTimeBasedChipAnalytics();
  const displayTimestampRef = useRef<number>(Date.now());
  const selectedChipDataRef = useRef<SuggestionChip | null>(null);

  // Handle chip selection - populates input with full habit name
  // Tapping a selected chip deselects it and clears input
  const handleChipSelect = useCallback(
    (index: number, chip: SuggestionChip) => {
      if (selectedChipIndex === index) {
        // Deselect if tapping the same chip
        setSelectedChipIndex(null);
        setSelectedEmoji(null);
        setInputValue('');
        selectedChipDataRef.current = null;
      } else {
        setSelectedChipIndex(index);
        setSelectedEmoji(chip.emoji);
        setInputValue(chip.fullName);
        selectedChipDataRef.current = chip;
      }
    },
    [selectedChipIndex]
  );

  // Handle text input changes - deselects chips when typing
  const handleInputChange = useCallback(
    (text: string) => {
      setInputValue(text);
      // Deselect chips when user types manually
      if (selectedChipIndex !== null) {
        setSelectedChipIndex(null);
        setSelectedEmoji(null);
        selectedChipDataRef.current = null;

        // Track manual input after viewing chips
        if (text.trim().length > 0) {
          const chips = getTimeBasedChips();
          analytics.trackManualInputAfterChipView(text, chips);
        }
      }
    },
    [selectedChipIndex, analytics]
  );

  // Handle CTA button press - creates the habit
  const handleCreateHabit = useCallback(async () => {
    if (!inputValue.trim() || isCreating) return;

    Keyboard.dismiss();
    setIsCreating(true);
    setErrorMessage(null);

    try {
      await onQuickCreateHabit(inputValue.trim());
      triggerSuccess();
      setSuccessHabitName(inputValue.trim());
      setSuccessEmoji(selectedEmoji); // Save emoji for success state

      // Track chip-to-habit conversion if a chip was selected
      if (selectedChipDataRef.current && selectedChipIndex !== null) {
        analytics.trackChipConvertedToHabit(
          selectedChipDataRef.current,
          selectedChipIndex,
          displayTimestampRef.current
        );
      }
    } catch (error) {
      setIsCreating(false);
      setErrorMessage(
        error instanceof Error
          ? error.message
          : 'Failed to create habit. Please try again.'
      );
    }
  }, [
    inputValue,
    isCreating,
    onQuickCreateHabit,
    triggerSuccess,
    selectedEmoji,
    selectedChipIndex,
    analytics,
  ]);

  // Handle keyboard submit (Done button)
  const handleSubmitEditing = useCallback(() => {
    if (inputValue.trim() && !isCreating) {
      handleCreateHabit();
    }
  }, [inputValue, isCreating, handleCreateHabit]);

  // Handle clear input button
  const handleClearInput = useCallback(() => {
    setInputValue('');
    setSelectedChipIndex(null);
    setSelectedEmoji(null);
    inputRef.current?.focus();
  }, []);

  // Handle "Add another habit" from success state
  const handleAddAnother = useCallback(() => {
    setSuccessHabitName(null);
    setSuccessEmoji(null);
    setInputValue('');
    setSelectedChipIndex(null);
    setSelectedEmoji(null);
    setIsCreating(false);
    // Focus input for next habit entry
    setTimeout(() => inputRef.current?.focus(), 100);
  }, []);

  // Handle error dismiss
  const handleDismissError = useCallback(() => {
    setErrorMessage(null);
  }, []);

  // Show success state if habit was created
  if (successHabitName) {
    // If we have a transition callback, auto-transition after celebration
    // Otherwise, show "Add another" button
    const shouldAutoTransition = !!onSuccessTransitionComplete;

    return (
      <SuccessState
        autoTransition={shouldAutoTransition}
        habitEmoji={successEmoji}
        habitName={successHabitName}
        onAddAnother={handleAddAnother}
        onTransitionComplete={onSuccessTransitionComplete}
      />
    );
  }

  // Show loading skeleton during initial load
  if (isLoading) {
    return <LoadingSkeleton />;
  }

  const isCtaDisabled = !inputValue.trim();

  return (
    <Animated.View
      style={[
        {
          alignItems: 'center',
          flex: 1,
          minHeight: '100%',
          paddingHorizontal: 16,
          width: '100%',
        },
        containerAnimatedStyle,
      ]}
    >
      {/* Hero Icon - animates to compact size when keyboard visible */}
      <Animated.View style={heroAnimatedStyle}>
        <AnimatedEntrance delay={ENTRANCE_DELAYS.heroIcon}>
          <HeroIcon animate={!isLoading} />
        </AnimatedEntrance>
      </Animated.View>

      {/* Question Headline - animates to smaller font when keyboard visible */}
      <AnimatedEntrance delay={ENTRANCE_DELAYS.headline}>
        <Animated.Text
          style={[
            {
              color: COLORS.stone800,
              fontWeight: '700',
              lineHeight: 32,
              textAlign: 'center',
            },
            headlineAnimatedStyle,
          ]}
        >
          {COPY.headline}
        </Animated.Text>
      </AnimatedEntrance>

      {/* Text Input - full width */}
      <View style={{ marginBottom: 24, maxWidth: 343, width: '100%' }}>
        <AnimatedEntrance delay={ENTRANCE_DELAYS.input}>
          <HabitInput
            ref={inputRef}
            value={inputValue}
            onChangeText={handleInputChange}
            onClear={handleClearInput}
            onSubmitEditing={handleSubmitEditing}
          />
        </AnimatedEntrance>
      </View>

      {/* Suggestion Chips - fades out when keyboard visible */}
      {/* Note: Each chip has its own staggered entrance animation, no wrapper needed */}
      <Animated.View
        accessibilityElementsHidden={isKeyboardVisible}
        importantForAccessibility={
          isKeyboardVisible ? 'no-hide-descendants' : 'auto'
        }
        style={[{ maxWidth: 343, width: '100%' }, chipsAnimatedStyle]}
      >
        <SuggestionChips
          selectedIndex={selectedChipIndex}
          onSelect={handleChipSelect}
        />
      </Animated.View>

      {/* Primary CTA Button - full width */}
      <View style={{ maxWidth: 343, width: '100%' }}>
        <AnimatedEntrance delay={ENTRANCE_DELAYS.cta}>
          <CtaButton
            disabled={isCtaDisabled}
            isLoading={isCreating}
            onPress={handleCreateHabit}
          />
        </AnimatedEntrance>
      </View>

      {/* Error Message */}
      {errorMessage && (
        <ErrorMessage message={errorMessage} onDismiss={handleDismissError} />
      )}

      {/* Inline Hint - fades out when keyboard visible */}
      <Animated.View
        accessibilityElementsHidden={isKeyboardVisible}
        importantForAccessibility={
          isKeyboardVisible ? 'no-hide-descendants' : 'auto'
        }
        style={secondaryLinksAnimatedStyle}
      >
        <AnimatedEntrance delay={ENTRANCE_DELAYS.secondaryLinks}>
          <InlineHint
            onBrowseTemplates={openTemplatesScreen}
            onCreateCustom={openCreateHabitScreen}
          />
        </AnimatedEntrance>
      </Animated.View>
    </Animated.View>
  );
}

/**
 * HeroIcon - Breathing seedling icon for the minimal empty state
 *
 * Features:
 * - Gentle breathing scale animation (1.0 → 1.08 → 1.0)
 * - Emerald gradient container
 * - Shadow glow pulse synced with breathing animation
 * - Respects reduce motion preference
 */

import { useEffect } from 'react';
import { Text, View } from 'react-native';
import Animated, {
  cancelAnimation,
  Easing,
  interpolate,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withRepeat,
  withTiming,
} from 'react-native-reanimated';

import { BREATHING_ANIMATION, HERO_GLOW } from './animations';
import { BORDER_RADIUS, COLORS } from './constants';
import type { HeroIconProps } from './types';

/** Default icon container size */
const DEFAULT_SIZE = 80;
/** Default emoji font size */
const DEFAULT_EMOJI_SIZE = 36;

/**
 * Hero icon with breathing animation
 *
 * @param animate - Whether to animate the breathing effect (default: true)
 * @param size - Icon container size in pixels (default: 80)
 * @param emojiSize - Emoji font size in pixels (default: 36)
 */
export function HeroIcon({
  animate = true,
  size = DEFAULT_SIZE,
  emojiSize = DEFAULT_EMOJI_SIZE,
}: HeroIconProps) {
  const shouldReduceMotion = useReducedMotion();
  const scale = useSharedValue(BREATHING_ANIMATION.minScale);

  useEffect(() => {
    if (!animate || shouldReduceMotion) {
      scale.value = BREATHING_ANIMATION.minScale;
      return;
    }

    // Breathing animation: 1.0 → 1.08 → 1.0 (3s ease-in-out, infinite)
    scale.value = withRepeat(
      withTiming(BREATHING_ANIMATION.maxScale, {
        duration: BREATHING_ANIMATION.duration / 2,
        easing: Easing.inOut(Easing.ease),
      }),
      -1, // Infinite
      true // Reverse
    );

    return () => {
      cancelAnimation(scale);
    };
  }, [animate, scale, shouldReduceMotion]);

  const breathingStyle = useAnimatedStyle(() => {
    // Interpolate shadow values based on scale
    // Scale goes 1.0 → 1.08, map to shadow opacity/radius ranges
    const shadowOpacity = interpolate(
      scale.value,
      [BREATHING_ANIMATION.minScale, BREATHING_ANIMATION.maxScale],
      [HERO_GLOW.minShadowOpacity, HERO_GLOW.maxShadowOpacity]
    );

    const shadowRadius = interpolate(
      scale.value,
      [BREATHING_ANIMATION.minScale, BREATHING_ANIMATION.maxScale],
      [HERO_GLOW.minShadowRadius, HERO_GLOW.maxShadowRadius]
    );

    return {
      shadowOpacity,
      shadowRadius,
      transform: [{ scale: scale.value }],
    };
  });

  // Calculate dynamic border radius based on size ratio
  const dynamicBorderRadius = (size / DEFAULT_SIZE) * BORDER_RADIUS.heroIcon;

  return (
    <Animated.View
      style={[
        breathingStyle,
        {
          alignItems: 'center',
          backgroundColor: COLORS.emerald100,
          borderRadius: dynamicBorderRadius,
          elevation: 4,
          height: size,
          justifyContent: 'center',

          // Emerald tinted shadow (opacity/radius animated via breathingStyle)
          shadowColor: COLORS.emerald500,

          shadowOffset: { height: 8, width: 0 },
          width: size,
        },
      ]}
    >
      {/* Inner gradient effect using overlay */}
      <View
        style={{
          backgroundColor: COLORS.green50,
          borderRadius: dynamicBorderRadius,
          bottom: 0,
          left: 0,
          opacity: 0.5,
          position: 'absolute',
          right: 0,
          top: 0,
        }}
      />
      <Text style={{ fontSize: emojiSize }}>🌱</Text>
    </Animated.View>
  );
}

/**
 * InlineHint - Vertical stack with navigation buttons
 *
 * Features:
 * - Vertical layout that never overflows horizontally
 * - Two pill buttons side-by-side below "or explore" text
 * - Works on all screen sizes (320pt minimum)
 */

import { Pressable, Text, View } from 'react-native';

import { COLORS } from './constants';
import type { InlineHintProps } from './types';

/**
 * Hint section with navigation links in a vertical stack layout
 *
 * Layout:
 *   "or explore"
 *   [📋 templates]  [✨ custom]
 */
export function InlineHint({
  onBrowseTemplates,
  onCreateCustom,
}: InlineHintProps) {
  return (
    <View
      style={{
        alignItems: 'center',
        marginTop: 16,
        width: '100%',
      }}
    >
      {/* Row 1: "or explore" text */}
      <Text
        style={{
          color: COLORS.stone600,
          fontSize: 13,
          lineHeight: 18,
          marginBottom: 10,
          textAlign: 'center',
        }}
      >
        or explore
      </Text>

      {/* Row 2: Buttons side-by-side with gap */}
      <View
        style={{
          flexDirection: 'row',
          gap: 12,
          justifyContent: 'center',
        }}
      >
        <Pressable
          accessibilityHint='Opens screen with pre-made habit templates'
          accessibilityLabel='Browse habit templates'
          accessibilityRole='button'
          style={({ pressed }) => ({
            backgroundColor: pressed
              ? COLORS.emerald100
              : 'rgba(209, 250, 229, 0.5)',
            borderColor: 'rgba(167, 243, 208, 0.8)',
            borderRadius: 9999,
            borderWidth: 1,
            opacity: pressed ? 0.9 : 1,
            paddingHorizontal: 12,
            paddingVertical: 6,
          })}
          onPress={onBrowseTemplates}
        >
          <Text
            style={{
              color: COLORS.emerald700,
              fontSize: 13,
              fontWeight: '600',
              lineHeight: 18,
            }}
          >
            📋 templates
          </Text>
        </Pressable>

        <Pressable
          accessibilityHint='Opens full habit creation screen'
          accessibilityLabel='Create custom habit'
          accessibilityRole='button'
          style={({ pressed }) => ({
            backgroundColor: pressed
              ? COLORS.emerald100
              : 'rgba(209, 250, 229, 0.5)',
            borderColor: 'rgba(167, 243, 208, 0.8)',
            borderRadius: 9999,
            borderWidth: 1,
            opacity: pressed ? 0.9 : 1,
            paddingHorizontal: 12,
            paddingVertical: 6,
          })}
          onPress={onCreateCustom}
        >
          <Text
            style={{
              color: COLORS.emerald700,
              fontSize: 13,
              fontWeight: '600',
              lineHeight: 18,
            }}
          >
            ✨ custom habit
          </Text>
        </Pressable>
      </View>
    </View>
  );
}

/**
 * LoadingSkeleton - Animated skeleton placeholders for loading state
 *
 * Features:
 * - Skeleton elements matching the empty state layout
 * - Shimmer animation using LinearGradient
 * - Skeleton colors: base #E7E5E4, highlight #F5F5F4
 * - Animation duration: 1.5s infinite
 * - Accessibility label for screen readers
 */

import { useEffect } from 'react';
import { StyleSheet, View } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import Animated, {
  Easing,
  interpolate,
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withTiming,
} from 'react-native-reanimated';

import { BORDER_RADIUS, TOUCH_TARGETS } from './constants';

const AnimatedLinearGradient = Animated.createAnimatedComponent(LinearGradient);

/**
 * Skeleton colors per spec
 */
const SKELETON_COLORS = {
  base: '#E7E5E4',
  highlight: '#F5F5F4',
} as const;

/**
 * Shimmer animation duration per spec
 */
const SHIMMER_DURATION = 1500;

/**
 * Skeleton element dimensions matching the empty state layout
 */
const SKELETON_DIMENSIONS = {
  chip: { height: 44, width: 80 },
  cta: { height: 56 },
  headline: { height: 32, width: 260 },
  hero: { height: 80, width: 80 },
  input: { height: 56 },
} as const;

interface ShimmerSkeletonProps {
  width: number | string;
  height: number;
  borderRadius?: number;
  style?: object;
}

/**
 * Single skeleton element with shimmer animation
 */
function ShimmerSkeleton({
  width,
  height,
  borderRadius = 8,
  style,
}: ShimmerSkeletonProps) {
  const shimmerPosition = useSharedValue(0);

  useEffect(() => {
    shimmerPosition.value = withRepeat(
      withTiming(1, {
        duration: SHIMMER_DURATION,
        easing: Easing.inOut(Easing.ease),
      }),
      -1, // Infinite repeat
      false // Don't reverse
    );
  }, [shimmerPosition]);

  const animatedStyle = useAnimatedStyle(() => {
    // Animate the gradient from left to right
    const translateX = interpolate(shimmerPosition.value, [0, 1], [-200, 200]);
    return {
      transform: [{ translateX }],
    };
  });

  return (
    <View
      style={[
        {
          backgroundColor: SKELETON_COLORS.base,
          borderRadius,
          height,
          overflow: 'hidden',
          width,
        },
        style,
      ]}
    >
      <AnimatedLinearGradient
        colors={[
          SKELETON_COLORS.base,
          SKELETON_COLORS.highlight,
          SKELETON_COLORS.base,
        ]}
        end={{ x: 1, y: 0.5 }}
        start={{ x: 0, y: 0.5 }}
        style={[
          StyleSheet.absoluteFillObject,
          { width: '200%' },
          animatedStyle,
        ]}
      />
    </View>
  );
}

/**
 * Loading skeleton for the empty state
 *
 * Renders skeleton placeholders matching the layout:
 * - Hero icon (80x80)
 * - Headline (260x32)
 * - Input (100%x56)
 * - Chips (3 pill shapes)
 * - CTA button (100%x56)
 */
export function LoadingSkeleton() {
  return (
    <View
      accessibilityLabel='Loading'
      accessibilityRole='progressbar'
      style={styles.container}
    >
      {/* Hero Icon Skeleton */}
      <ShimmerSkeleton
        borderRadius={BORDER_RADIUS.heroIcon}
        height={SKELETON_DIMENSIONS.hero.height}
        width={SKELETON_DIMENSIONS.hero.width}
      />

      {/* Headline Skeleton */}
      <ShimmerSkeleton
        borderRadius={8}
        height={SKELETON_DIMENSIONS.headline.height}
        style={styles.headline}
        width={SKELETON_DIMENSIONS.headline.width}
      />

      {/* Input Skeleton */}
      <View style={styles.inputContainer}>
        <ShimmerSkeleton
          borderRadius={BORDER_RADIUS.input}
          height={SKELETON_DIMENSIONS.input.height}
          width='100%'
        />
      </View>

      {/* Chips Row Skeleton - 3 pill shapes */}
      <View style={styles.chipsContainer}>
        <ShimmerSkeleton
          borderRadius={BORDER_RADIUS.chip}
          height={SKELETON_DIMENSIONS.chip.height}
          width={SKELETON_DIMENSIONS.chip.width}
        />
        <ShimmerSkeleton
          borderRadius={BORDER_RADIUS.chip}
          height={SKELETON_DIMENSIONS.chip.height}
          style={styles.chipSpacing}
          width={SKELETON_DIMENSIONS.chip.width}
        />
        <ShimmerSkeleton
          borderRadius={BORDER_RADIUS.chip}
          height={SKELETON_DIMENSIONS.chip.height}
          style={styles.chipSpacing}
          width={SKELETON_DIMENSIONS.chip.width}
        />
      </View>

      {/* CTA Button Skeleton */}
      <View style={styles.ctaContainer}>
        <ShimmerSkeleton
          borderRadius={BORDER_RADIUS.cta}
          height={SKELETON_DIMENSIONS.cta.height}
          width='100%'
        />
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  chipsContainer: {
    flexDirection: 'row',
    justifyContent: 'center',
    marginBottom: 32,
    width: '100%',
  },
  chipSpacing: {
    marginLeft: 12,
  },
  container: {
    alignItems: 'center',
    flex: 1,
    justifyContent: 'center',
  },
  ctaContainer: {
    width: '100%',
  },
  headline: {
    marginBottom: 32,
    marginTop: 32,
  },
  inputContainer: {
    marginBottom: 24,
    width: '100%',
  },
});

