/**
 * ProgressRing - SVG circular progress indicator for success state
 *
 * Features:
 * - Animates stroke-dashoffset from full circumference to 0
 * - Visual feedback for auto-transition timing
 * - Respects reduced motion preference
 * - Uses reanimated for smooth 60fps animation
 */

import { useEffect } from 'react';
import { View, StyleSheet } from 'react-native';
import Svg, { Circle } from 'react-native-svg';
import Animated, {
  Easing,
  useAnimatedProps,
  useReducedMotion,
  useSharedValue,
  withTiming,
} from 'react-native-reanimated';

import { PROGRESS_RING } from './animations';
import { COLORS } from './constants';

const AnimatedCircle = Animated.createAnimatedComponent(Circle);

export interface ProgressRingProps {
  /** Duration of the progress animation in ms (default: 1800ms) */
  duration?: number;
  /** Size of the ring in px (default: 120px) */
  size?: number;
  /** Callback when progress animation completes */
  onComplete?: () => void;
}

/**
 * ProgressRing - Shows visual countdown for auto-transition
 *
 * The ring fills clockwise from 12 o'clock position over the specified
 * duration, giving users visual feedback on when the auto-transition will occur.
 */
export function ProgressRing({
  duration = PROGRESS_RING.duration,
  size = PROGRESS_RING.size,
  onComplete,
}: ProgressRingProps) {
  const shouldReduceMotion = useReducedMotion();

  // Calculate ring geometry
  const strokeWidth = PROGRESS_RING.strokeWidth;
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const center = size / 2;

  // Animated progress value (0 to 1)
  const progress = useSharedValue(0);

  useEffect(() => {
    if (shouldReduceMotion) {
      // Complete instantly if reduced motion is preferred
      progress.value = 1;
      onComplete?.();
      return;
    }

    // Animate progress from 0 to 1 over the specified duration
    progress.value = withTiming(
      1,
      {
        duration,
        easing: Easing.linear,
      },
      (finished) => {
        if (finished && onComplete) {
          // Note: onComplete is called from JS thread, no runOnJS needed
          // since we're using the callback form of withTiming
        }
      }
    );
  }, [duration, progress, shouldReduceMotion, onComplete]);

  // Animated props for the progress circle
  const animatedProps = useAnimatedProps(() => {
    // strokeDashoffset goes from circumference (empty) to 0 (full)
    // Round to avoid "Loss of precision during arithmetic conversion" error in Reanimated
    const strokeDashoffset = Math.round(circumference * (1 - progress.value));
    return {
      strokeDashoffset,
    };
  });

  return (
    <View style={[styles.container, { width: size, height: size }]}>
      <Svg width={size} height={size}>
        {/* Background circle (gray track) */}
        <Circle
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          stroke={COLORS.stone200}
          strokeWidth={strokeWidth}
        />

        {/* Animated progress circle */}
        <AnimatedCircle
          animatedProps={animatedProps}
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          stroke={COLORS.emerald500}
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={circumference}
          strokeLinecap="round"
          // Rotate to start at 12 o'clock (-90 degrees)
          rotation="-90"
          origin={`${center}, ${center}`}
        />
      </Svg>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    position: 'absolute',
    alignItems: 'center',
    justifyContent: 'center',
  },
});

/**
 * SecondaryLinks - Browse templates and create custom habit links
 *
 * Features:
 * - Centered row with dot separator
 * - Subtle hover state
 * - Minimal touch targets
 */

import { Pressable, Text, View } from 'react-native';

import { COLORS, COPY, TOUCH_TARGETS } from './constants';
import type { SecondaryLinksProps } from './types';

/**
 * Secondary navigation links for templates and custom creation
 */
export function SecondaryLinks({
  onBrowseTemplates,
  onCreateCustom,
}: SecondaryLinksProps) {
  return (
    <View
      style={{
        alignItems: 'center',
        flexDirection: 'row',
        gap: 24,
        justifyContent: 'center',
        marginTop: 24,
      }}
    >
      <Pressable
        accessibilityHint='Opens habit templates screen'
        accessibilityLabel={COPY.browseTemplates}
        accessibilityRole='button'
        style={({ pressed }) => ({
          justifyContent: 'center',
          minHeight: TOUCH_TARGETS.minSize,
          minWidth: TOUCH_TARGETS.minSize,
          opacity: pressed ? 0.7 : 1,
          paddingHorizontal: 8,
          paddingVertical: 8,
        })}
        onPress={onBrowseTemplates}
      >
        <Text
          style={{
            color: COLORS.stone500,
            fontSize: 13,
            fontWeight: '400',
          }}
        >
          {COPY.browseTemplates}
        </Text>
      </Pressable>

      {/* Dot separator */}
      <Text
        style={{
          color: COLORS.stone500,
          fontSize: 13,
        }}
      >
        •
      </Text>

      <Pressable
        accessibilityHint='Opens full habit creation screen'
        accessibilityLabel={COPY.createCustom}
        accessibilityRole='button'
        style={({ pressed }) => ({
          justifyContent: 'center',
          minHeight: TOUCH_TARGETS.minSize,
          minWidth: TOUCH_TARGETS.minSize,
          opacity: pressed ? 0.7 : 1,
          paddingHorizontal: 8,
          paddingVertical: 8,
        })}
        onPress={onCreateCustom}
      >
        <Text
          style={{
            color: COLORS.stone500,
            fontSize: 13,
            fontWeight: '400',
          }}
        >
          {COPY.createCustom}
        </Text>
      </Pressable>
    </View>
  );
}

/**
 * SuccessContent - Text and action content for success state
 *
 * Displays headline, subtext, tap hint, and add another button.
 */

import { Pressable, Text, ViewStyle } from 'react-native';
import Animated, { AnimatedStyle } from 'react-native-reanimated';

import { BORDER_RADIUS, COLORS, COPY, TOUCH_TARGETS } from './constants';

interface SuccessContentProps {
  habitName: string;
  autoTransition: boolean;
  contentStyle: AnimatedStyle<ViewStyle>;
  tapHintStyle: AnimatedStyle<ViewStyle>;
  onAddAnother: () => void;
}

export function SuccessContent({
  habitName,
  autoTransition,
  contentStyle,
  tapHintStyle,
  onAddAnother,
}: SuccessContentProps) {
  return (
    <Animated.View
      style={[contentStyle, { alignItems: 'center', width: '100%' }]}
    >
      {/* Headline */}
      <Text
        style={{
          color: COLORS.stone800,
          fontSize: 24,
          fontWeight: '700',
          marginBottom: 8,
          textAlign: 'center',
        }}
      >
        {COPY.successHeadline}
      </Text>

      {/* Subtext */}
      <Text
        style={{
          color: COLORS.stone500,
          fontSize: 13,
          marginBottom: 24,
          textAlign: 'center',
        }}
      >
        {COPY.successSubtext(habitName)}
      </Text>

      {/* Tap to continue hint - only show if auto-transitioning */}
      {autoTransition && (
        <Animated.Text
          style={[
            tapHintStyle,
            {
              color: COLORS.stone500,
              fontSize: 13,
              textAlign: 'center',
            },
          ]}
        >
          Tap anywhere to continue
        </Animated.Text>
      )}

      {/* Add another button - only show if not auto-transitioning */}
      {!autoTransition && (
        <Pressable
          accessibilityHint='Creates another habit'
          accessibilityLabel={COPY.addAnother}
          accessibilityRole='button'
          style={({ pressed }) => ({
            alignItems: 'center',
            backgroundColor: COLORS.stone800,
            borderRadius: BORDER_RADIUS.cta,
            height: TOUCH_TARGETS.ctaHeight,
            justifyContent: 'center',
            opacity: pressed ? 0.9 : 1,
            transform: [{ scale: pressed ? 0.98 : 1 }],
            width: '100%',
          })}
          onPress={onAddAnother}
        >
          <Text
            style={{
              color: '#ffffff',
              fontSize: 15,
              fontWeight: '700',
            }}
          >
            {COPY.addAnother}
          </Text>
        </Pressable>
      )}
    </Animated.View>
  );
}

/**
 * SuccessIcon - Icon container with progress ring and particle burst
 *
 * Displays the success emoji surrounded by visual effects.
 * The progress ring shows countdown to auto-transition.
 */

import { Text, View, ViewStyle } from 'react-native';
import Animated, { AnimatedStyle } from 'react-native-reanimated';

import { PROGRESS_RING, PARTICLE_BURST } from './animations';
import { COLORS } from './constants';
import { ParticleBurst } from './ParticleBurst';
import { ProgressRing } from './ProgressRing';

interface SuccessIconProps {
  emoji: string;
  autoTransition: boolean;
  iconStyle: AnimatedStyle<ViewStyle>;
  ringStyle: AnimatedStyle<ViewStyle>;
  burstStyle: AnimatedStyle<ViewStyle>;
}

export function SuccessIcon({
  emoji,
  autoTransition,
  iconStyle,
  ringStyle,
  burstStyle,
}: SuccessIconProps) {
  return (
    <Animated.View
      style={[
        iconStyle,
        {
          alignItems: 'center',
          height: PROGRESS_RING.size,
          justifyContent: 'center',
          marginBottom: 24,
          width: PROGRESS_RING.size,
        },
      ]}
    >
      {/* Progress Ring - Behind the icon, shows countdown */}
      {autoTransition && (
        <Animated.View
          style={[
            ringStyle,
            {
              height: PROGRESS_RING.size,
              position: 'absolute',
              width: PROGRESS_RING.size,
            },
          ]}
        >
          <ProgressRing
            duration={PROGRESS_RING.duration}
            size={PROGRESS_RING.size}
          />
        </Animated.View>
      )}

      {/* Particle Burst - Positioned behind icon */}
      <Animated.View
        style={[
          burstStyle,
          {
            height: PROGRESS_RING.size,
            position: 'absolute',
            width: PROGRESS_RING.size,
          },
        ]}
      >
        <ParticleBurst
          distance={PARTICLE_BURST.distance}
          duration={PARTICLE_BURST.duration}
        />
      </Animated.View>

      {/* Success Icon Emoji */}
      <View
        style={{
          alignItems: 'center',
          backgroundColor: COLORS.successBackground,
          borderRadius: 48,
          height: 96,
          justifyContent: 'center',
          width: 96,
          zIndex: 10,
        }}
      >
        <Text style={{ fontSize: 48 }}>{emoji}</Text>
      </View>
    </Animated.View>
  );
}

/**
 * SuccessState - Post-creation celebration screen
 *
 * Features:
 * - Pop animation on the success icon
 * - Confetti particles floating upward
 * - Habit name confirmation
 * - Auto-transition to habit list with shared element animation
 * - Tap anywhere to skip and transition immediately
 * - Haptic feedback on mount
 * - "Add another habit" button to reset (if staying on empty state)
 */

import { useEffect, useCallback } from 'react';
import { AccessibilityInfo, Pressable } from 'react-native';
import Animated, { useReducedMotion } from 'react-native-reanimated';

import { useHapticFeedback } from '../../../../hooks/useHapticFeedback';
import { Confetti } from './Confetti';
import { SuccessContent } from './SuccessContent';
import { SuccessIcon } from './SuccessIcon';
import type { SuccessStateProps } from './types';
import { useSuccessStateAnimations } from './useSuccessStateAnimations';

export function SuccessState({
  habitName,
  habitEmoji,
  onAddAnother,
  onTransitionComplete,
  autoTransition = true,
}: SuccessStateProps) {
  const shouldReduceMotion = useReducedMotion();
  const { triggerSuccess } = useHapticFeedback();

  const displayEmoji = habitEmoji || '🌿';

  const {
    iconStyle,
    contentStyle,
    containerStyle,
    tapHintStyle,
    ringStyle,
    burstStyle,
    triggerExitAnimation,
  } = useSuccessStateAnimations({
    autoTransition,
    onTransitionComplete,
    shouldReduceMotion,
  });

  // Tap to skip handler
  const handleTapToSkip = useCallback(() => {
    if (!autoTransition || !onTransitionComplete) return;
    triggerExitAnimation();
  }, [autoTransition, onTransitionComplete, triggerExitAnimation]);

  // Haptic feedback on mount + accessibility announcement
  useEffect(() => {
    triggerSuccess();

    const message = `Success! ${habitName} has been added to your habits. Tap anywhere to continue.`;
    AccessibilityInfo?.announceForAccessibility?.(message);
  }, [habitName, triggerSuccess]);

  return (
    <Pressable
      accessibilityHint='Skip the celebration and view your habit list'
      accessibilityLabel='Tap to continue to your habits'
      accessibilityRole='button'
      style={{ flex: 1 }}
      onPress={handleTapToSkip}
    >
      <Animated.View
        style={[
          containerStyle,
          {
            alignItems: 'center',
            flex: 1,
            justifyContent: 'center',
          },
        ]}
      >
        <Confetti shouldReduceMotion={shouldReduceMotion ?? false} />

        <SuccessIcon
          autoTransition={autoTransition}
          burstStyle={burstStyle}
          emoji={displayEmoji}
          iconStyle={iconStyle}
          ringStyle={ringStyle}
        />

        <SuccessContent
          autoTransition={autoTransition}
          contentStyle={contentStyle}
          habitName={habitName}
          tapHintStyle={tapHintStyle}
          onAddAnother={onAddAnother}
        />
      </Animated.View>
    </Pressable>
  );
}

/**
 * SuggestionChips - Tappable habit suggestion pills
 *
 * Features:
 * - Flex wrap layout with centered chips
 * - Selection state with emerald highlight
 * - Hover/press animations
 * - Haptic feedback on selection
 * - Staggered entrance animation (50ms between each chip)
 */

import { useCallback, useEffect, useRef } from 'react';
import { Pressable, Text, View } from 'react-native';
import Animated, {
  Easing,
  interpolateColor,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withDelay,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

import { useHapticFeedback } from '../../../../hooks/useHapticFeedback';
import { useTimeBasedChipAnalytics } from './analytics';
import {
  CHIP_STAGGER,
  CHIP_TRANSFORMS,
  ENTRANCE_DELAYS,
  SPRING_CONFIGS,
} from './animations';
import { BORDER_RADIUS, COLORS, TOUCH_TARGETS } from './constants';
import type { SuggestionChip, SuggestionChipsProps } from './types';
import { getTimeBasedChips } from './utils';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

interface ChipProps {
  chip: SuggestionChip;
  index: number;
  isSelected: boolean;
  onPress: () => void;
  /** Stagger delay for entrance animation (ms) */
  staggerDelay: number;
}

/**
 * Individual suggestion chip with press animations
 *
 * Animation behavior (per spec):
 * - Entrance: fade in + slide up with stagger delay
 * - Hover (onPressIn): translateY -2px, scale 1.05
 * - Press (onPress): triggers selection, brief scale down
 * - Release (onPressOut): animate back to rest state
 */
function Chip({ chip, isSelected, onPress, staggerDelay }: ChipProps) {
  const { triggerSelection } = useHapticFeedback();
  const shouldReduceMotion = useReducedMotion();
  const scale = useSharedValue(1);
  const translateY = useSharedValue(0);
  const shadowOpacity = useSharedValue(0);
  const selectionProgress = useSharedValue(isSelected ? 1 : 0);

  // Entrance animation values
  const entranceOpacity = useSharedValue(shouldReduceMotion ? 1 : 0);
  const entranceTranslateY = useSharedValue(
    shouldReduceMotion ? 0 : CHIP_STAGGER.translateY
  );

  // Calculate total entrance delay: base chips delay + individual stagger
  const totalEntranceDelay = ENTRANCE_DELAYS.chips + staggerDelay;

  // Trigger entrance animation on mount
  useEffect(() => {
    if (shouldReduceMotion) {
      entranceOpacity.value = 1;
      entranceTranslateY.value = 0;
      return;
    }

    // Fade in with ease-out timing
    entranceOpacity.value = withDelay(
      totalEntranceDelay,
      withTiming(1, {
        duration: CHIP_STAGGER.duration,
        easing: Easing.out(Easing.ease),
      })
    );

    // Slide up with ease-out timing
    entranceTranslateY.value = withDelay(
      totalEntranceDelay,
      withTiming(0, {
        duration: CHIP_STAGGER.duration,
        easing: Easing.out(Easing.ease),
      })
    );
  }, [
    entranceOpacity,
    entranceTranslateY,
    shouldReduceMotion,
    totalEntranceDelay,
  ]);

  // Update selection progress when isSelected prop changes
  // Using useEffect ensures animation always syncs with prop, even during mid-animation
  // Deselection is instant (no animation) for snappier feel; only selection animates
  useEffect(() => {
    if (isSelected) {
      // Animate selection
      selectionProgress.value = shouldReduceMotion
        ? 1
        : withSpring(1, SPRING_CONFIGS.chipPress);
    } else {
      // Instant deselection - no animation
      selectionProgress.value = 0;
    }
  }, [isSelected, selectionProgress, shouldReduceMotion]);

  const animatedStyle = useAnimatedStyle(() => ({
    // Using emerald-700 (#047857) for WCAG AA contrast (5.21:1 with white text)
    backgroundColor: interpolateColor(
      selectionProgress.value,
      [0, 1],
      ['#ffffff', '#047857']
    ),

    borderColor: interpolateColor(
      selectionProgress.value,
      [0, 1],
      [COLORS.stone200, '#047857']
    ),

    // Entrance opacity
    opacity: entranceOpacity.value,

    // Shadow increases on hover
    shadowOpacity: shadowOpacity.value,

    // Combine entrance translateY with interaction translateY
    transform: [
      { translateY: entranceTranslateY.value + translateY.value },
      { scale: scale.value },
    ],
  }));

  const textStyle = useAnimatedStyle(() => ({
    color: interpolateColor(
      selectionProgress.value,
      [0, 1],
      [COLORS.stone700, '#ffffff']
    ),
  }));

  // Hover state: lift up, scale up, increase shadow
  const handlePressIn = useCallback(() => {
    if (shouldReduceMotion) return;
    translateY.value = withSpring(
      CHIP_TRANSFORMS.hoverTranslateY,
      SPRING_CONFIGS.chipHover
    );
    scale.value = withSpring(
      CHIP_TRANSFORMS.hoverScale,
      SPRING_CONFIGS.chipHover
    );
    shadowOpacity.value = withSpring(0.15, SPRING_CONFIGS.chipHover);
  }, [scale, shadowOpacity, shouldReduceMotion, translateY]);

  // Release: animate back to rest state
  const handlePressOut = useCallback(() => {
    if (shouldReduceMotion) return;
    scale.value = withSpring(
      CHIP_TRANSFORMS.selectedScale,
      SPRING_CONFIGS.chipPress
    );
    translateY.value = withSpring(0, SPRING_CONFIGS.chipHover);
    shadowOpacity.value = withSpring(0, SPRING_CONFIGS.chipHover);
  }, [scale, shadowOpacity, shouldReduceMotion, translateY]);

  // Selection: haptic feedback + callback
  const handlePress = useCallback(() => {
    triggerSelection();
    // Brief press feedback (scale down then back up)
    if (!shouldReduceMotion) {
      scale.value = withSpring(
        CHIP_TRANSFORMS.pressScale,
        SPRING_CONFIGS.chipPress
      );
    }
    onPress();
  }, [onPress, scale, shouldReduceMotion, triggerSelection]);

  return (
    <AnimatedPressable
      accessibilityLabel={`Select ${chip.fullName}`}
      accessibilityRole='button'
      accessibilityState={{ selected: isSelected }}
      style={[
        animatedStyle,
        {
          alignItems: 'center',
          borderRadius: BORDER_RADIUS.chip,
          borderWidth: 1,
          elevation: 1,
          flexDirection: 'row',
          gap: 4,
          minHeight: TOUCH_TARGETS.chipHeight,
          paddingHorizontal: 10,

          paddingVertical: 8,
          // Base shadow properties - subtle (opacity animates on hover)
          shadowColor: '#000000',
          shadowOffset: { height: 1, width: 0 },
          shadowRadius: 2,
        },
      ]}
      onPress={handlePress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
    >
      <Text style={{ fontSize: 15 }}>{chip.emoji}</Text>
      <Animated.Text
        style={[
          textStyle,
          {
            fontSize: 13,
            fontWeight: '600',
          },
        ]}
      >
        {chip.label}
      </Animated.Text>
    </AnimatedPressable>
  );
}

/**
 * Pyramid layout of suggestion chips (3-2-1 formation)
 *
 * Stagger delays per spec:
 * - Row 1: 0ms, 50ms, 100ms
 * - Row 2: 150ms, 200ms
 * - Row 3: 250ms
 */
export function SuggestionChips({
  selectedIndex,
  onSelect,
}: SuggestionChipsProps) {
  // Get time-appropriate chips dynamically
  const chips = getTimeBasedChips();

  // Analytics tracking
  const analytics = useTimeBasedChipAnalytics();
  const displayTimestampRef = useRef<number>(0);
  const previousSelectedChipRef = useRef<{
    chip: SuggestionChip;
    index: number;
  } | null>(null);

  // Track chips displayed on mount
  useEffect(() => {
    displayTimestampRef.current = Date.now();
    analytics.trackChipsDisplayed(chips);
  }, [chips, analytics]);

  // Handle chip selection with analytics
  const handleChipSelect = useCallback(
    (index: number, chip: SuggestionChip) => {
      // Track deselection if a chip was previously selected
      if (previousSelectedChipRef.current && selectedIndex !== null) {
        analytics.trackChipDeselected(
          previousSelectedChipRef.current.chip,
          previousSelectedChipRef.current.index
        );
      }

      // Track new selection
      analytics.trackChipSelected(chip, index);
      previousSelectedChipRef.current = { chip, index };

      // Call original onSelect handler
      onSelect(index, chip);
    },
    [analytics, onSelect, selectedIndex]
  );

  // Split chips into rows: 3, 2, 1
  const row1 = chips.slice(0, 3);
  const row2 = chips.slice(3, 5);
  const row3 = chips.slice(5, 6);

  return (
    <View
      style={{
        alignItems: 'center',
        gap: 6,
        width: '100%',
      }}
    >
      {/* Row 1: 3 chips - delays 0, 50, 100ms */}
      <View
        style={{
          flexDirection: 'row',
          gap: 6,
          justifyContent: 'center',
        }}
      >
        {row1.map((chip, i) => (
          <Chip
            key={chip.label}
            chip={chip}
            index={i}
            isSelected={selectedIndex === i}
            staggerDelay={i * CHIP_STAGGER.delay}
            onPress={() => handleChipSelect(i, chip)}
          />
        ))}
      </View>
      {/* Row 2: 2 chips - delays 150, 200ms */}
      <View
        style={{
          flexDirection: 'row',
          gap: 6,
          justifyContent: 'center',
        }}
      >
        {row2.map((chip, i) => {
          const index = i + 3;
          // Continue stagger from row 1 (indices 3, 4)
          const staggerIndex = index;
          return (
            <Chip
              key={chip.label}
              chip={chip}
              index={index}
              isSelected={selectedIndex === index}
              staggerDelay={staggerIndex * CHIP_STAGGER.delay}
              onPress={() => handleChipSelect(index, chip)}
            />
          );
        })}
      </View>
      {/* Row 3: 1 chip - delay 250ms */}
      <View
        style={{
          flexDirection: 'row',
          flexWrap: 'wrap',
          gap: 8,
          justifyContent: 'center',
        }}
      >
        {row3.map((chip, i) => {
          const index = i + 5;
          // Continue stagger from row 2 (index 5)
          const staggerIndex = index;
          return (
            <Chip
              key={chip.label}
              chip={chip}
              index={index}
              isSelected={selectedIndex === index}
              staggerDelay={staggerIndex * CHIP_STAGGER.delay}
              onPress={() => handleChipSelect(index, chip)}
            />
          );
        })}
      </View>
    </View>
  );
}

/**
 * Analytics tracking utilities for Time-Based Suggestion Chips
 *
 * This module provides type-safe analytics event tracking for monitoring
 * time-based chip feature usage and measuring impact on user behavior.
 *
 * Tracks key metrics:
 * - Chip selection rate by time window
 * - Time to first habit creation
 * - Chip-to-habit conversion rate
 * - Time window engagement distribution
 */

import type { SuggestionChip } from './types';

/**
 * Time window categories for analytics
 */
export type TimeWindow = 'morning' | 'afternoon' | 'evening' | 'night';

/**
 * Analytics event types for Time-Based Chips feature
 */
export type TimeBasedChipEvent =
  | {
      type: 'chips_displayed';
      timeWindow: TimeWindow;
      hour: number;
      chipLabels: string[];
      timestamp: number;
    }
  | {
      type: 'chip_selected';
      timeWindow: TimeWindow;
      chipLabel: string;
      chipFullName: string;
      chipEmoji: string;
      chipIndex: number;
      hour: number;
      timestamp: number;
    }
  | {
      type: 'chip_deselected';
      timeWindow: TimeWindow;
      chipLabel: string;
      chipIndex: number;
      previouslySelected: boolean;
      timestamp: number;
    }
  | {
      type: 'chip_converted_to_habit';
      timeWindow: TimeWindow;
      chipLabel: string;
      chipFullName: string;
      chipEmoji: string;
      chipIndex: number;
      timeToConversion: number; // milliseconds from display to habit creation
      timestamp: number;
    }
  | {
      type: 'manual_input_after_chip_view';
      timeWindow: TimeWindow;
      manualHabitName: string;
      chipsViewed: string[];
      timestamp: number;
    }
  | {
      type: 'time_window_distribution';
      timeWindow: TimeWindow;
      hour: number;
      dayOfWeek: number; // 0-6 (Sunday-Saturday)
      timestamp: number;
    };

/**
 * Analytics tracker interface
 * Implement this interface to connect to your analytics provider
 */
export interface TimeBasedChipAnalyticsTracker {
  track(event: TimeBasedChipEvent): void;
}

/**
 * Console logger for development
 * Logs all analytics events to console in development mode
 */
class ConsoleTimeBasedChipAnalyticsTracker implements TimeBasedChipAnalyticsTracker {
  private enabled: boolean;

  constructor() {
    this.enabled = __DEV__;
  }

  track(event: TimeBasedChipEvent): void {
    if (!this.enabled) return;

    // eslint-disable-next-line no-console
    console.log('[Analytics] Time-Based Chips:', {
      timestamp: new Date(event.timestamp).toISOString(),
      type: event.type,
      ...event,
    });
  }
}

/**
 * No-op tracker for production when no analytics provider configured
 */
class NoOpTimeBasedChipAnalyticsTracker implements TimeBasedChipAnalyticsTracker {
  track(_event: TimeBasedChipEvent): void {
    // No-op
  }
}

/**
 * Global analytics tracker instance
 * Override with setTimeBasedChipAnalyticsTracker() to connect your analytics provider
 */
let analyticsTracker: TimeBasedChipAnalyticsTracker = __DEV__
  ? new ConsoleTimeBasedChipAnalyticsTracker()
  : new NoOpTimeBasedChipAnalyticsTracker();

/**
 * Set custom analytics tracker
 * Call this early in your app initialization to connect your analytics provider
 *
 * @example
 * ```ts
 * import { setTimeBasedChipAnalyticsTracker } from '@/features/habits/components/HabitsEmptyStateMinimal/analytics';
 * import analytics from '@/lib/analytics';
 *
 * setTimeBasedChipAnalyticsTracker({
 *   track: (event) => {
 *     analytics.track(event.type, event);
 *   }
 * });
 * ```
 */
export function setTimeBasedChipAnalyticsTracker(
  tracker: TimeBasedChipAnalyticsTracker
): void {
  analyticsTracker = tracker;
}

/**
 * Track analytics event
 * Type-safe wrapper around the global analytics tracker
 */
export function trackTimeBasedChipEvent(event: TimeBasedChipEvent): void {
  try {
    analyticsTracker.track(event);
  } catch (error) {
    // Silently fail - don't let analytics errors break the app
    if (__DEV__) {
      console.error('[Analytics] Error tracking time-based chip event:', error);
    }
  }
}

/**
 * Helper: Get time window category from hour
 */
export function getTimeWindowFromHour(hour: number): TimeWindow {
  if (hour >= 5 && hour < 11) return 'morning';
  if (hour >= 11 && hour < 17) return 'afternoon';
  if (hour >= 17 && hour < 22) return 'evening';
  return 'night';
}

/**
 * Helper: Get chip labels array from chips
 */
export function getChipLabels(chips: SuggestionChip[]): string[] {
  return chips.map((chip) => chip.label);
}

/**
 * Track when user first views chips
 */
function createTrackChipsDisplayed() {
  return (chips: SuggestionChip[]) => {
    const now = new Date();
    const hour = now.getHours();
    const timeWindow = getTimeWindowFromHour(hour);

    trackTimeBasedChipEvent({
      chipLabels: getChipLabels(chips),
      hour,
      timestamp: now.getTime(),
      timeWindow,
      type: 'chips_displayed',
    });

    // Also track time window distribution for analytics
    trackTimeBasedChipEvent({
      dayOfWeek: now.getDay(),
      hour,
      timestamp: now.getTime(),
      timeWindow,
      type: 'time_window_distribution',
    });
  };
}

/**
 * Track chip selection
 */
function createTrackChipSelected() {
  return (chip: SuggestionChip, index: number) => {
    const now = new Date();
    const hour = now.getHours();
    const timeWindow = getTimeWindowFromHour(hour);

    trackTimeBasedChipEvent({
      chipEmoji: chip.emoji,
      chipFullName: chip.fullName,
      chipIndex: index,
      chipLabel: chip.label,
      hour,
      timestamp: now.getTime(),
      timeWindow,
      type: 'chip_selected',
    });
  };
}

/**
 * Track chip deselection (when user clicks away or selects different chip)
 */
function createTrackChipDeselected() {
  return (chip: SuggestionChip, index: number) => {
    const now = new Date();
    const hour = now.getHours();
    const timeWindow = getTimeWindowFromHour(hour);

    trackTimeBasedChipEvent({
      chipIndex: index,
      chipLabel: chip.label,
      previouslySelected: true,
      timestamp: now.getTime(),
      timeWindow,
      type: 'chip_deselected',
    });
  };
}

/**
 * Track successful chip-to-habit conversion
 */
function createTrackChipConvertedToHabit() {
  return (chip: SuggestionChip, index: number, displayTimestamp: number) => {
    const now = new Date();
    const hour = now.getHours();
    const timeWindow = getTimeWindowFromHour(hour);
    const timeToConversion = now.getTime() - displayTimestamp;

    trackTimeBasedChipEvent({
      chipEmoji: chip.emoji,
      chipFullName: chip.fullName,
      chipIndex: index,
      chipLabel: chip.label,
      timestamp: now.getTime(),
      timeToConversion,
      timeWindow,
      type: 'chip_converted_to_habit',
    });
  };
}

/**
 * Track when user types manually instead of using chips
 */
function createTrackManualInputAfterChipView() {
  return (habitName: string, viewedChips: SuggestionChip[]) => {
    const now = new Date();
    const hour = now.getHours();
    const timeWindow = getTimeWindowFromHour(hour);

    trackTimeBasedChipEvent({
      chipsViewed: getChipLabels(viewedChips),
      manualHabitName: habitName,
      timestamp: now.getTime(),
      timeWindow,
      type: 'manual_input_after_chip_view',
    });
  };
}

/**
 * Hook for tracking Time-Based Chip analytics
 * Use this hook in SuggestionChips component to track user interactions
 *
 * @example
 * ```tsx
 * const analytics = useTimeBasedChipAnalytics();
 *
 * // Track chips displayed
 * useEffect(() => {
 *   analytics.trackChipsDisplayed(chips);
 * }, [chips]);
 *
 * // Track chip selection
 * const handleChipSelect = (index: number, chip: SuggestionChip) => {
 *   analytics.trackChipSelected(chip, index);
 *   onSelect(index, chip);
 * };
 * ```
 */
export function useTimeBasedChipAnalytics() {
  return {
    trackChipConvertedToHabit: createTrackChipConvertedToHabit(),
    trackChipDeselected: createTrackChipDeselected(),
    trackChipsDisplayed: createTrackChipsDisplayed(),
    trackChipSelected: createTrackChipSelected(),
    trackManualInputAfterChipView: createTrackManualInputAfterChipView(),
  };
}

