/**
 * Monetization Hero Animations Hook
 * Manages progress, pulse, and shimmer animations
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Animated, Easing } from 'react-native';

interface UseMonetizationAnimationsOptions {
  freeHabitLimit: number;
  habitSlotsUsed: number;
  hasReachedHabitLimit: boolean;
  reduceMotion: boolean;
}

export function useMonetizationAnimations({
  freeHabitLimit,
  habitSlotsUsed,
  hasReachedHabitLimit,
  reduceMotion,
}: UseMonetizationAnimationsOptions) {
  const progress = useRef(new Animated.Value(0)).current;
  const ctaPulse = useRef(new Animated.Value(1)).current;
  const shimmer = useRef(new Animated.Value(0.4)).current;
  const [trackWidth, setTrackWidth] = useState(0);

  const usageRatio = useMemo(
    () =>
      freeHabitLimit === 0 ? 0 : Math.min(habitSlotsUsed / freeHabitLimit, 1),
    [freeHabitLimit, habitSlotsUsed]
  );

  useEffect(() => {
    if (reduceMotion) {
      progress.setValue(trackWidth * usageRatio);
      return;
    }
    const handle = Animated.timing(progress, {
      duration: 420,
      easing: Easing.out(Easing.cubic),
      toValue: trackWidth * usageRatio,
      useNativeDriver: false,
    });
    handle.start();
    return () => {
      handle.stop();
    };
  }, [progress, trackWidth, usageRatio, reduceMotion]);

  useEffect(() => {
    if (reduceMotion || !hasReachedHabitLimit) {
      ctaPulse.stopAnimation();
      ctaPulse.setValue(1);
      return;
    }
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(ctaPulse, {
          duration: 720,
          easing: Easing.inOut(Easing.ease),
          toValue: 1.04,
          useNativeDriver: true,
        }),
        Animated.timing(ctaPulse, {
          duration: 720,
          easing: Easing.inOut(Easing.ease),
          toValue: 1,
          useNativeDriver: true,
        }),
      ])
    );
    loop.start();
    return () => loop.stop();
  }, [ctaPulse, hasReachedHabitLimit, reduceMotion]);

  useEffect(() => {
    if (reduceMotion) {
      shimmer.setValue(1);
      return;
    }
    const wave = Animated.loop(
      Animated.sequence([
        Animated.timing(shimmer, {
          duration: 960,
          easing: Easing.inOut(Easing.ease),
          toValue: 0.9,
          useNativeDriver: true,
        }),
        Animated.timing(shimmer, {
          duration: 960,
          easing: Easing.inOut(Easing.ease),
          toValue: 0.4,
          useNativeDriver: true,
        }),
      ])
    );
    wave.start();
    return () => wave.stop();
  }, [shimmer, reduceMotion]);

  const handleTrackLayout = useCallback(
    (event: { nativeEvent: { layout: { width: number } } }) => {
      setTrackWidth(event.nativeEvent.layout.width);
    },
    []
  );

  return { ctaPulse, handleTrackLayout, progress, shimmer, trackWidth };
}

/**
 * HabitsList Entrance Animations Hook
 * Handles staggered entrance animations for header, calendar, and habit rows
 */

import { useCallback } from 'react';
import { Animated, Easing } from 'react-native';

interface UseHabitsListAnimationsOptions {
  headerOpacity: Animated.Value;
  headerTranslateY: Animated.Value;
  calendarOpacity: Animated.Value;
  calendarTranslateY: Animated.Value;
  habitRowOpacity: Animated.Value;
  habitRowTranslateY: Animated.Value;
  setIsInSuccessCelebration: (value: boolean) => void;
  setShouldTriggerHabitEntrance: (value: boolean) => void;
}

export function useHabitsListAnimations(
  options: UseHabitsListAnimationsOptions
) {
  const {
    headerOpacity,
    headerTranslateY,
    calendarOpacity,
    calendarTranslateY,
    habitRowOpacity,
    habitRowTranslateY,
    setIsInSuccessCelebration,
    setShouldTriggerHabitEntrance,
  } = options;

  const handleSuccessTransitionComplete = useCallback(() => {
    setIsInSuccessCelebration(false);
    const config = {
      duration: 350,
      easing: Easing.out(Easing.cubic),
      useNativeDriver: true,
    };

    headerOpacity.setValue(0);
    headerTranslateY.setValue(20);
    calendarOpacity.setValue(0);
    calendarTranslateY.setValue(20);
    habitRowOpacity.setValue(0);
    habitRowTranslateY.setValue(20);

    Animated.stagger(100, [
      Animated.parallel([
        Animated.timing(headerOpacity, { ...config, toValue: 1 }),
        Animated.timing(headerTranslateY, { ...config, toValue: 0 }),
      ]),
      Animated.parallel([
        Animated.timing(calendarOpacity, { ...config, toValue: 1 }),
        Animated.timing(calendarTranslateY, { ...config, toValue: 0 }),
      ]),
      Animated.parallel([
        Animated.timing(habitRowOpacity, { ...config, toValue: 1 }),
        Animated.timing(habitRowTranslateY, { ...config, toValue: 0 }),
      ]),
    ]).start(() => {
      setTimeout(() => setShouldTriggerHabitEntrance(true), 200);
    });
  }, [
    headerOpacity,
    headerTranslateY,
    calendarOpacity,
    calendarTranslateY,
    habitRowOpacity,
    habitRowTranslateY,
    setIsInSuccessCelebration,
    setShouldTriggerHabitEntrance,
  ]);

  return { handleSuccessTransitionComplete };
}

/**
 * HabitsList Handlers Hook - Event handlers and callbacks
 */

import { useCallback } from 'react';
import { useMutation } from 'convex/react';
import { api } from '../../../../../convex/_generated/api';
import type { Id } from '../../../../../convex/_generated/dataModel';
import { useHapticFeedback } from '../../../../hooks/useHapticFeedback';
import { useHabitsListEffects } from './useHabitsListEffects';
import type { HabitsListProps } from './HabitsList.types';

export interface UseHabitsListHandlersOptions {
  list: HabitsListProps['list'];
  onSettingsChange: HabitsListProps['modals']['onSettingsChange'];
  onCreateHabitRequest: HabitsListProps['onCreateHabitRequest'];
  state: {
    justCreatedHabitId: Id<'habits'> | null;
    setJustCreatedHabitId: (id: Id<'habits'> | null) => void;
    setIsInSuccessCelebration: (value: boolean) => void;
    shouldTriggerHabitEntrance: boolean;
    isInSuccessCelebration: boolean;
    setShouldTriggerHabitEntrance: (value: boolean) => void;
  };
}

export function useHabitsListHandlers(options: UseHabitsListHandlersOptions) {
  const { list, onSettingsChange, onCreateHabitRequest, state } = options;
  const {
    habitSortMode,
    isPremiumUser,
    hasReachedHabitLimit,
    celebrationsEnabled,
    habits,
    reduceMotionPreference,
  } = list;

  const createHabit = useMutation(api.habits.create);
  const { triggerSelection } = useHapticFeedback({
    isEnabled: celebrationsEnabled,
    preference: reduceMotionPreference,
  });

  useHabitsListEffects({
    habitsLength: habits.length,
    isInSuccessCelebration: state.isInSuccessCelebration,
    justCreatedHabitId: state.justCreatedHabitId,
    setJustCreatedHabitId: state.setJustCreatedHabitId,
    setShouldTriggerHabitEntrance: state.setShouldTriggerHabitEntrance,
    shouldTriggerHabitEntrance: state.shouldTriggerHabitEntrance,
  });

  const handleChangeHabitSortMode = useCallback(
    (value: typeof habitSortMode) =>
      void onSettingsChange({ habitSortMode: value }),
    [onSettingsChange]
  );

  const handleQuickCreateHabit = useCallback(
    async (habitName: string) => {
      if (!isPremiumUser && hasReachedHabitLimit) {
        onCreateHabitRequest();
        return;
      }
      try {
        const newHabitId = (await createHabit({
          name: habitName,
          notes: '',
          remindersEnabled: false,
        })) as Id<'habits'>;
        if (newHabitId) {
          state.setJustCreatedHabitId(newHabitId);
          state.setIsInSuccessCelebration(true);
        }
      } catch (error) {
        console.error('Failed to create habit:', error);
      }
    },
    [
      createHabit,
      hasReachedHabitLimit,
      isPremiumUser,
      onCreateHabitRequest,
      state,
    ]
  );

  const handleAddHabitPress = useCallback(
    () => onCreateHabitRequest(),
    [onCreateHabitRequest]
  );
  const handleDragBegin = useCallback(
    () => triggerSelection(),
    [triggerSelection]
  );
  const keyExtractor = useCallback(
    (habit: (typeof habits)[number], index: number) =>
      habit._id ?? `habit-${index}`,
    []
  );

  return {
    handleAddHabitPress,
    handleChangeHabitSortMode,
    handleDragBegin,
    handleQuickCreateHabit,
    isReorderingEnabled: habitSortMode === 'manual',
    keyExtractor,
  };
}

/**
 * HabitsList State Hook
 * Manages local UI state for the HabitsList component
 */

import { useCallback, useState, useRef } from 'react';
import { Animated } from 'react-native';
import type { Id } from '../../../../../convex/_generated/dataModel';

export function useHabitsListState() {
  const [isSortSheetOpen, setIsSortSheetOpen] = useState(false);
  const [selectedDay, setSelectedDay] = useState<Date | null>(null);
  const [isDaySheetOpen, setIsDaySheetOpen] = useState(false);
  const [justCreatedHabitId, setJustCreatedHabitId] =
    useState<Id<'habits'> | null>(null);
  const [isInSuccessCelebration, setIsInSuccessCelebration] = useState(false);
  const [shouldTriggerHabitEntrance, setShouldTriggerHabitEntrance] =
    useState(false);

  const seenHabitIdsRef = useRef<Set<string>>(new Set());

  // Animation values
  const headerOpacity = useRef(new Animated.Value(1)).current;
  const headerTranslateY = useRef(new Animated.Value(0)).current;
  const calendarOpacity = useRef(new Animated.Value(1)).current;
  const calendarTranslateY = useRef(new Animated.Value(0)).current;
  const habitRowOpacity = useRef(new Animated.Value(1)).current;
  const habitRowTranslateY = useRef(new Animated.Value(0)).current;

  const handleOpenSortSheet = useCallback(() => setIsSortSheetOpen(true), []);
  const handleCloseSortSheet = useCallback(() => setIsSortSheetOpen(false), []);
  const handleDayPress = useCallback((date: Date) => {
    setSelectedDay(date);
    setIsDaySheetOpen(true);
  }, []);
  const handleCloseDaySheet = useCallback(() => {
    setIsDaySheetOpen(false);
    setSelectedDay(null);
  }, []);
  const handleHabitEntranceComplete = useCallback((habitId: Id<'habits'>) => {
    seenHabitIdsRef.current.add(habitId);
  }, []);

  return {
    calendarOpacity,
    headerOpacity,
    calendarTranslateY,
    isDaySheetOpen,
    habitRowOpacity,
    isInSuccessCelebration,
    habitRowTranslateY,
    isSortSheetOpen,
    handleOpenSortSheet,
    justCreatedHabitId,
    handleCloseSortSheet,
    selectedDay,
    handleCloseDaySheet,
    seenHabitIdsRef,
    handleDayPress,
    shouldTriggerHabitEntrance,
    handleHabitEntranceComplete,
    headerTranslateY,
    setIsInSuccessCelebration,
    setJustCreatedHabitId,
    setShouldTriggerHabitEntrance,
  };
}

