import { useMutation, useQuery } from 'convex/react';
import {
  addDays,
  eachDayOfInterval,
  format,
  startOfDay,
  subMonths,
} from 'date-fns';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Alert, Platform } from 'react-native';

import { api } from '../../../../convex/_generated/api';
import { useMilestoneDetection } from '../../../hooks/useMilestoneDetection';
import { computeCurrentStreakFromDates } from '../../../utils/streak';
import type { Habit, HabitId, HabitStatus, ShareCardData } from '../types';

type HabitTrackingEntry = {
  habitId: string;
  date: string;
  completed?: boolean | null;
};

export function useHabitsAppState() {
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isCreateHabitOpen, setIsCreateHabitOpen] = useState(false);
  const [showHabitStrengthPercentage, setShowHabitStrengthPercentage] =
    useState(true);
  const [selectedHabit, setSelectedHabit] = useState<Habit | null>(null);
  const [isHabitCalendarOpen, setIsHabitCalendarOpen] = useState(false);
  const [isHabitDetailOpen, setIsHabitDetailOpen] = useState(false);
  const [showShareCard, setShowShareCard] = useState(false);
  const [shareCardData, setShareCardData] = useState<ShareCardData | null>(
    null
  );
  const [showPauseModal, setShowPauseModal] = useState(false);
  const [habitToPause, setHabitToPause] = useState<Habit | null>(null);
  const [habitToEdit, setHabitToEdit] = useState<Habit | null>(null);
  const [showHapticTest, setShowHapticTest] = useState(false);

  const toggleHabit = useMutation(api.habits.toggleHabit);
  const archiveHabit = useMutation(api.habits.archive);
  const pauseHabit = useMutation(api.habits.pause);
  const removeHabit = useMutation(api.habits.remove);
  const reorderHabits = useMutation(api.habits.reorderHabits);
  const updateSettings = useMutation(api.settings.update);

  const habitsQuery = useQuery(api.habits.list);
  const habits = habitsQuery ?? [];
  const isHabitsLoading = habitsQuery === undefined;
  const settings = useQuery(api.settings.get);

  const [lastUpdatedHabit, setLastUpdatedHabit] = useState<{
    id: string;
    name: string;
    strength: number;
  } | null>(null);

  const { milestone, clearMilestone } = useMilestoneDetection(
    lastUpdatedHabit?.id,
    lastUpdatedHabit?.name,
    lastUpdatedHabit?.strength ? lastUpdatedHabit.strength * 100 : undefined
  );

  useEffect(() => {
    if (!milestone) return;
    console.log('🎉 MILESTONE DETECTED!', {
      level: milestone.level,
      strength: milestone.strength + '%',
      habitName: milestone.habitName,
    });
  }, [milestone]);

  // Keep habit state snapshots in sync with the habits array when it updates
  // This ensures that when a habit is edited, the modals/screens show the updated data
  useEffect(() => {
    if (selectedHabit) {
      const updated = habits.find(h => h._id === selectedHabit._id);
      if (updated && updated !== selectedHabit) {
        setSelectedHabit(updated);
      }
    }
  }, [habits, selectedHabit]);

  useEffect(() => {
    if (habitToEdit) {
      const updated = habits.find(h => h._id === habitToEdit._id);
      if (updated && updated !== habitToEdit) {
        setHabitToEdit(updated);
      }
    }
  }, [habits, habitToEdit]);

  useEffect(() => {
    if (habitToPause) {
      const updated = habits.find(h => h._id === habitToPause._id);
      if (updated && updated !== habitToPause) {
        setHabitToPause(updated);
      }
    }
  }, [habits, habitToPause]);

  const prevStrengthsRef = useRef<Map<string, number>>(new Map());

  useEffect(() => {
    if (isHabitsLoading) return;

    habits.forEach((habit) => {
      const prevStrength = prevStrengthsRef.current.get(habit._id) || 0;
      const currentStrength = habit.strength || 0;

      if (currentStrength > prevStrength) {
        console.log('🎯 Strength increased!', {
          habitName: habit.name,
          prevStrength: (prevStrength * 100).toFixed(1) + '%',
          currentStrength: (currentStrength * 100).toFixed(1) + '%',
        });
        setLastUpdatedHabit({
          id: habit._id,
          name: habit.name,
          strength: currentStrength,
        });
      }

      prevStrengthsRef.current.set(habit._id, currentStrength);
    });
  }, [habits, isHabitsLoading]);

  const today = useMemo(() => startOfDay(new Date()), []);
  const [weekAnchor, setWeekAnchor] = useState(today);

  const weekDates = useMemo(
    () => Array.from({ length: 5 }, (_, i) => addDays(weekAnchor, i - 4)),
    [weekAnchor]
  );

  const weekDateStrings = useMemo(
    () => weekDates.map((d) => format(d, 'yyyy-MM-dd')),
    [weekDates]
  );

  const extendedDateRange = useMemo(() => {
    const endDate = today;
    const startDate = subMonths(endDate, 12);
    return eachDayOfInterval({ start: startDate, end: endDate });
  }, [today]);

  const extendedDateStrings = useMemo(
    () => extendedDateRange.map((d) => format(d, 'yyyy-MM-dd')),
    [extendedDateRange]
  );

  const tracking =
    (useQuery(api.habits.getTracking, { dates: extendedDateStrings }) ?? []) as HabitTrackingEntry[];

  const completedDatesByHabit = useMemo(() => {
    const map = new Map<string, Set<string>>();
    for (const entry of tracking) {
      if (!entry.completed) continue;
      if (!map.has(entry.habitId)) {
        map.set(entry.habitId, new Set<string>());
      }
      map.get(entry.habitId)!.add(entry.date);
    }
    return map;
  }, [tracking]);

  const getStreak = useCallback(
    (habitId: string) => {
      const completedDates = completedDatesByHabit.get(habitId);
      if (!completedDates) return 0;
      return computeCurrentStreakFromDates(completedDates, today);
    },
    [completedDatesByHabit, today]
  );

  const handleToggleForm = useCallback(() => {
    setIsCreateHabitOpen(true);
  }, []);

  const handlePreviousWeek = useCallback(() => {
    setWeekAnchor((prev) => addDays(prev, -5));
  }, []);

  const handleNextWeek = useCallback(() => {
    setWeekAnchor((prev) => addDays(prev, 5));
  }, []);

  const canNavigateForward = useMemo(
    () => weekAnchor.getTime() < today.getTime(),
    [weekAnchor, today]
  );

  const getHabitStatus = useCallback<
    (habitId: string, dateString: string) => HabitStatus
  >(
    (habitId, dateString) => {
      const trackingEntry = tracking.find(
        (entry) => entry.habitId === habitId && entry.date === dateString
      );

      if (trackingEntry?.completed) return 'done';

      const [year, month, day] = dateString.split('-').map(Number);
      const date = new Date(year, month - 1, day);
      date.setHours(0, 0, 0, 0);

      if (date < today) return 'missed';
      return 'planned';
    },
    [tracking, today]
  );

  const handleDragEnd = useCallback(
    async ({ data }: { data: Habit[] }) => {
      try {
        const habitIds = data.map((habit) => habit._id);
        console.log('Reordering habits:', habitIds);
        await reorderHabits({ habitIds });
        console.log('Reorder successful');
      } catch (error) {
        console.error('Failed to reorder habits:', error);
      }
    },
    [reorderHabits]
  );

  const handleArchive = useCallback(
    async (habitId: HabitId) => {
      await archiveHabit({ habitId });
    },
    [archiveHabit]
  );

  const handleDeleteHabit = useCallback(
    async (habitId: HabitId) => {
      if (Platform.OS === 'web') {
        if (
          !confirm(
            'Are you sure you want to delete this habit? This cannot be undone.'
          )
        ) {
          return;
        }
        await removeHabit({ habitId });
        setIsHabitDetailOpen(false);
        setSelectedHabit(null);
        return;
      }

      Alert.alert(
        'Delete Habit',
        'Are you sure you want to delete this habit? This cannot be undone.',
        [
          { text: 'Cancel', style: 'cancel' },
          {
            text: 'Delete',
            style: 'destructive',
            onPress: async () => {
              await removeHabit({ habitId });
              setIsHabitDetailOpen(false);
              setSelectedHabit(null);
            },
          },
        ]
      );
    },
    [removeHabit]
  );

  const handleHabitPress = useCallback((habit: Habit) => {
    setSelectedHabit(habit);
    setIsHabitCalendarOpen(true);
  }, []);

  const contentContainerStyle = useMemo(
    () => ({
      paddingHorizontal: 24,
      paddingTop: 48,
      paddingBottom: 96,
    }),
    []
  );

  return {
    habits,
    isHabitsLoading,
    settings,
    toggleHabit,
    updateSettings,
    pauseHabit,
    milestone,
    clearMilestone,
    shareCardData,
    setShareCardData,
    showShareCard,
    setShowShareCard,
    habitToEdit,
    setHabitToEdit,
    isSettingsOpen,
    setIsSettingsOpen,
    isCreateHabitOpen,
    setIsCreateHabitOpen,
    showHabitStrengthPercentage,
    setShowHabitStrengthPercentage,
    selectedHabit,
    setSelectedHabit,
    isHabitCalendarOpen,
    setIsHabitCalendarOpen,
    isHabitDetailOpen,
    setIsHabitDetailOpen,
    showPauseModal,
    setShowPauseModal,
    habitToPause,
    setHabitToPause,
    showHapticTest,
    setShowHapticTest,
    handleToggleForm,
    handleNextWeek,
    handlePreviousWeek,
    canNavigateForward,
    weekDates,
    weekDateStrings,
    handleDragEnd,
    getStreak,
    getHabitStatus,
    handleArchive,
    handleDeleteHabit,
    handleHabitPress,
    contentContainerStyle,
    tracking,
    setLastUpdatedHabit,
  };
}

export type HabitsAppState = ReturnType<typeof useHabitsAppState>;

import { useCallback, useMemo, useState, useRef } from 'react';
import { useMutation, useQuery } from 'convex/react';
import { api } from '../../../../convex/_generated/api';
import type { Id } from '../../../../convex/_generated/dataModel';
import type { Habit, HabitSettings, HabitSortMode, RewardToastData } from '../types';
import { logInteraction } from '../../../lib/analytics/interactions';
import { useHabitsWeekDates } from './useHabitsWeekDates';
import { useHabitsTracking } from './useHabitsTracking';
import type { HabitsListState } from './types';

interface ArchiveUndoState {
  visible: boolean;
  habitId: Id<'habits'> | null;
  habitName: string;
}

export function useHabitsListState(): HabitsListState {
  const [showHabitStrengthPercentage, setShowHabitStrengthPercentage] = useState(true);

  const toggleHabitMutation = useMutation(api.habits.toggleHabit);
  const archiveHabitMutation = useMutation(api.habits.archive);
  const unarchiveHabitMutation = useMutation(api.habits.unarchive);
  const reorderHabits = useMutation(api.habits.reorderHabits);

  // Archive undo toast state
  const [archiveUndo, setArchiveUndo] = useState<ArchiveUndoState>({
    visible: false,
    habitId: null,
    habitName: '',
  });

  const habitsQuery = useQuery(api.habits.list);
  const habitsFromQuery = (habitsQuery ?? []) as Habit[];
  const isHabitsLoading = habitsQuery === undefined;

  const [rewardToast, setRewardToast] = useState<RewardToastData | null>(null);

  const settingsQuery = useQuery(api.settings.get);
  const settings = (settingsQuery ?? undefined) as HabitSettings | undefined;
  const celebrationsEnabled = settings?.showMotivationalMessages ?? true;
  const dayShape = settings?.dayShape ?? 'square';
  const habitSortMode: HabitSortMode = settings?.habitSortMode ?? 'manual';
  const habitCompletionIcon = settings?.habitCompletionIcon ?? 'chain';
  const reduceMotionPreference = settings?.reduceMotion ?? false;
  const isPremiumUser = settings?.hasPremium ?? false;
  const showWeekCompletionBar = settings?.showWeekCompletionBar ?? true;

  const FREE_HABIT_LIMIT = 3;

  const { today, weekDates, weekDateStrings, extendedDateStrings, canNavigateForward, handleNextWeek, handlePreviousWeek } = useHabitsWeekDates();
  const { getStreak, getHabitStatus } = useHabitsTracking(extendedDateStrings, today);

  const habits = useMemo(() => {
    if (habitSortMode === 'manual') {
      return habitsFromQuery;
    }

    const sortedHabits = [...habitsFromQuery];

    // Day Phase sorting (Push → Pivot → Pull, then unassigned)
    if (habitSortMode === 'day_phase') {
      const phaseOrder: Record<string, number> = {
        phase1_push: 0,
        morning: 0, // Legacy mapping
        phase2_pivot: 1,
        afternoon: 1, // Legacy mapping
        phase3_pull: 2,
        evening: 2, // Legacy mapping
      };

      sortedHabits.sort((a, b) => {
        const aPhase = a.preferredTime ? (phaseOrder[a.preferredTime] ?? 99) : 99;
        const bPhase = b.preferredTime ? (phaseOrder[b.preferredTime] ?? 99) : 99;

        if (aPhase !== bPhase) {
          return aPhase - bPhase;
        }

        // Secondary sort by name for habits in same phase
        const aName = a.name.trim().toLowerCase();
        const bName = b.name.trim().toLowerCase();
        return aName.localeCompare(bName);
      });
      return sortedHabits;
    }

    if (habitSortMode === 'name_asc' || habitSortMode === 'name_desc') {
      sortedHabits.sort((a, b) => {
        const aName = a.name.trim().toLowerCase();
        const bName = b.name.trim().toLowerCase();

        if (aName === bName) {
          return 0;
        }

        const direction = habitSortMode === 'name_asc' ? 1 : -1;
        return aName < bName ? -1 * direction : 1 * direction;
      });
      return sortedHabits;
    }

    if (habitSortMode === 'strength_asc' || habitSortMode === 'strength_desc') {
      const direction = habitSortMode === 'strength_desc' ? -1 : 1;
      sortedHabits.sort((a, b) => {
        const aStrength = a.strength ?? 0;
        const bStrength = b.strength ?? 0;
        if (aStrength !== bStrength) {
          return (aStrength - bStrength) * direction;
        }

        const aName = a.name.trim().toLowerCase();
        const bName = b.name.trim().toLowerCase();
        if (aName === bName) {
          return 0;
        }
        return aName < bName ? -1 : 1;
      });
      return sortedHabits;
    }

    const streakByHabitId = new Map(
      sortedHabits.map((habit) => [
        habit._id,
        habit.currentStreak ?? getStreak(habit._id),
      ])
    );

    const direction = habitSortMode === 'streak_desc' ? -1 : 1;
    sortedHabits.sort((a, b) => {
      const aStreak = streakByHabitId.get(a._id) ?? 0;
      const bStreak = streakByHabitId.get(b._id) ?? 0;
      if (aStreak !== bStreak) {
        return (aStreak - bStreak) * direction;
      }

      const aName = a.name.trim().toLowerCase();
      const bName = b.name.trim().toLowerCase();
      if (aName === bName) {
        return 0;
      }
      return aName < bName ? -1 : 1;
    });

    return sortedHabits;
  }, [getStreak, habitSortMode, habitsFromQuery]);

  const habitSlotsUsed = isPremiumUser
    ? habits.length
    : Math.min(habits.length, FREE_HABIT_LIMIT);
  const hasReachedHabitLimit = !isPremiumUser && habits.length >= FREE_HABIT_LIMIT;

  const openCreateHabitScreen = useCallback(() => {
    // This will be handled by the parent component
  }, []);

  const handleDragEnd = useCallback(
    async ({ data }: { data: Habit[] }) => {
      if (habitSortMode !== 'manual') {
        return;
      }

      try {
        const habitIds = data.map((h) => h._id);
        await reorderHabits({ habitIds });
      } catch (error) {
        console.error('Failed to reorder habits:', error);
      }
    },
    [habitSortMode, reorderHabits]
  );

  const handleArchive = useCallback(
    async (habitId: Id<'habits'>) => {
      // Find the habit name before archiving (for undo toast)
      const habit = habits.find((h) => h._id === habitId);
      const habitName = habit?.name ?? 'Habit';

      await archiveHabitMutation({ habitId });

      // Show undo toast
      setArchiveUndo({
        visible: true,
        habitId,
        habitName,
      });

      logInteraction('habit_archived', {
        habitId,
        habitName,
      });
    },
    [archiveHabitMutation, habits]
  );

  const handleArchiveUndo = useCallback(async () => {
    if (archiveUndo.habitId) {
      await unarchiveHabitMutation({ habitId: archiveUndo.habitId });
      logInteraction('habit_archive_undone', {
        habitId: archiveUndo.habitId,
        habitName: archiveUndo.habitName,
      });
    }
    setArchiveUndo({ visible: false, habitId: null, habitName: '' });
  }, [archiveUndo.habitId, archiveUndo.habitName, unarchiveHabitMutation]);

  const dismissArchiveUndo = useCallback(() => {
    setArchiveUndo({ visible: false, habitId: null, habitName: '' });
  }, []);

  const handleHabitPress = useCallback((habit: Habit) => {
    // This will be handled by the parent component
  }, []);

  const toggleHabit = useCallback(
    async (args: { habitId: Id<'habits'>; date: string }) => {
      await toggleHabitMutation(args);
    },
    [toggleHabitMutation]
  );

  const dismissRewardToast = useCallback(() => {
    setRewardToast(null);
  }, []);

  const notifyWeekCompletion = useCallback(
    ({ habit, completedDate }: { habit: Habit; completedDate: string }) => {
      if (!celebrationsEnabled) {
        return;
      }

      const streak = getStreak(habit._id);

      setRewardToast({
        habitId: habit._id,
        habitName: habit.name,
        message:
          'Amazing consistency! Unlock a momentum booster to stack even more wins.',
        streak,
      });

      logInteraction('habit_week_complete', {
        completedDate,
        habitId: habit._id,
        habitName: habit.name,
        streak,
      });
    },
    [celebrationsEnabled, getStreak]
  );

  return {
    celebrationsEnabled,
    dayShape,
    freeHabitLimit: FREE_HABIT_LIMIT,
    habits,
    habitSortMode,
    habitCompletionIcon,
    isHabitsLoading,
    hasReachedHabitLimit,
    weekDates,
    weekDateStrings,
    canNavigateForward,
    showHabitStrengthPercentage,
    showWeekCompletionBar,
    contentPadding: { paddingHorizontal: 24, paddingTop: 0, paddingBottom: 96 },
    dismissRewardToast,
    handleDragEnd,
    handleArchive,
    handleArchiveUndo,
    dismissArchiveUndo,
    archiveUndoVisible: archiveUndo.visible,
    archiveUndoHabitName: archiveUndo.habitName,
    handleHabitPress,
    handleNextWeek,
    handlePreviousWeek,
    openCreateHabitScreen,
    getHabitStatus,
    getStreak,
    notifyWeekCompletion,
    habitSlotsUsed,
    reduceMotionPreference,
    rewardToast,
    toggleHabit,
    isPremiumUser,
  };
}

