import { useEffect, useRef, useState, useCallback } from 'react';
import { useMilestoneDetection } from '../../../hooks/useMilestoneDetection';
import type { Habit, ShareCardData } from '../types';

export function useMilestoneCelebrationState(habits: Habit[], isHabitsLoading: boolean) {
  const [lastUpdatedHabit, setLastUpdatedHabit] = useState<{
    id: string;
    name: string;
    strength: number;
  } | null>(null);

  const { milestone, clearMilestone } = useMilestoneDetection(
    lastUpdatedHabit?.id,
    lastUpdatedHabit?.name,
    lastUpdatedHabit?.strength ? lastUpdatedHabit.strength * 100 : undefined
  );

  useEffect(() => {
    if (milestone) {
      console.log('🎉 MILESTONE DETECTED!', {
        level: milestone.level,
        strength: milestone.strength + '%',
        habitName: milestone.habitName,
      });
    }
  }, [milestone]);

  const prevStrengthsRef = useRef<Map<string, number>>(new Map());

  useEffect(() => {
    if (isHabitsLoading) return;

    habits.forEach((habit) => {
      const prevStrength = prevStrengthsRef.current.get(habit._id) || 0;
      const currentStrength = (habit.strength as number | undefined) ?? 0;

      if (currentStrength > prevStrength) {
        console.log('🎯 Strength increased!', {
          habitName: habit.name,
          prevStrength: (prevStrength * 100).toFixed(1) + '%',
          currentStrength: (currentStrength * 100).toFixed(1) + '%',
        });
        setLastUpdatedHabit({
          id: habit._id,
          name: habit.name,
          strength: currentStrength,
        });
      }

      prevStrengthsRef.current.set(habit._id, currentStrength);
    });
  }, [habits, isHabitsLoading]);

  const [shareCardData, setShareCardData] = useState<ShareCardData | null>(null);
  const [showShareCard, setShowShareCard] = useState(false);

  const openShareCard = useCallback(() => {
    if (!milestone) return;
    setShareCardData({
      habitName: milestone.habitName,
      milestoneLevel: milestone.level,
      strengthPercentage: milestone.strength,
    });
    setShowShareCard(true);
  }, [milestone]);

  const closeShareCard = useCallback(() => {
    setShowShareCard(false);
    setShareCardData(null);
    clearMilestone();
    setLastUpdatedHabit(null);
  }, [clearMilestone]);

  const closeCelebration = useCallback(() => {
    clearMilestone();
    setLastUpdatedHabit(null);
  }, [clearMilestone]);

  return {
    milestone,
    showShareCard,
    shareCardData,
    openShareCard,
    closeShareCard,
    closeCelebration,
  };
}

import { useEffect, useState } from 'react';
import * as SecureStore from 'expo-secure-store';

const BADGE_DISMISSED_KEY = 'template_badge_dismissed';
const BADGE_SHOWN_COUNT_KEY = 'template_badge_shown_count';

interface UseTemplateBadgeParams {
  totalHabits: number;
  hasViewedTemplates?: boolean;
}

/**
 * Smart badge logic:
 * - Show when user has 2+ habits (they're engaged)
 * - Hide if dismissed
 * - Auto-dismiss after 3 sessions
 */
export function useTemplateBadge({ totalHabits, hasViewedTemplates }: UseTemplateBadgeParams) {
  const [showBadge, setShowBadge] = useState(false);

  useEffect(() => {
    checkBadgeVisibility();
  }, [totalHabits, hasViewedTemplates]);

  const checkBadgeVisibility = async () => {
    try {
      // Don't show if already viewed templates
      if (hasViewedTemplates) {
        setShowBadge(false);
        return;
      }

      // Don't show if user dismissed it
      const dismissed = await SecureStore.getItemAsync(BADGE_DISMISSED_KEY);
      if (dismissed === 'true') {
        setShowBadge(false);
        return;
      }

      // Show badge if user has 2+ habits (engaged user)
      if (totalHabits >= 2) {
        // Track how many times shown
        const shownCount = await SecureStore.getItemAsync(BADGE_SHOWN_COUNT_KEY);
        const count = parseInt(shownCount || '0', 10);

        if (count < 3) {
          // Auto-dismiss after 3 sessions
          await SecureStore.setItemAsync(BADGE_SHOWN_COUNT_KEY, String(count + 1));
          setShowBadge(true);
        } else {
          setShowBadge(false);
        }
      } else {
        setShowBadge(false);
      }
    } catch (error) {
      console.error('Error checking badge visibility:', error);
      setShowBadge(false);
    }
  };

  const dismissBadge = async () => {
    try {
      await SecureStore.setItemAsync(BADGE_DISMISSED_KEY, 'true');
      setShowBadge(false);
    } catch (error) {
      console.error('Error dismissing badge:', error);
    }
  };

  return {
    showBadge,
    dismissBadge,
  };
}

import { useState, useEffect, useCallback } from 'react';
import * as SecureStore from 'expo-secure-store';

const TOOLTIP_STORAGE_KEY = 'template_tooltip_shown';

interface UseTemplateTooltipReturn {
  dismissTooltip: () => void;
  showTooltip: boolean;
}

/**
 * Hook to manage the first-time template tooltip
 * Shows tooltip on first app launch, then never again after dismissal
 */
export const useTemplateTooltip = (): UseTemplateTooltipReturn => {
  const [showTooltip, setShowTooltip] = useState(false);

  useEffect(() => {
    const checkTooltipStatus = async () => {
      try {
        const hasSeenTooltip = await SecureStore.getItemAsync(TOOLTIP_STORAGE_KEY);

        // Show tooltip only if user hasn't seen it before
        if (hasSeenTooltip === null) {
          // Add a small delay so it appears after the screen renders
          setTimeout(() => {
            setShowTooltip(true);
          }, 800);
        }
      } catch (error) {
        console.error('Error checking tooltip status:', error);
      }
    };

    checkTooltipStatus();
  }, []);

  const dismissTooltip = useCallback(async () => {
    try {
      await SecureStore.setItemAsync(TOOLTIP_STORAGE_KEY, 'true');
      setShowTooltip(false);
    } catch (error) {
      console.error('Error dismissing tooltip:', error);
      // Still hide it even if storage fails
      setShowTooltip(false);
    }
  }, []);

  return {
    dismissTooltip,
    showTooltip,
  };
};

/**
 * useAudioPlayback Hook - Main orchestrator
 *
 * Audio playback integration using expo-av for Voice Notes feature.
 * Story T10.4: Playback UI with progress bar
 */

import { useEffect } from 'react';
import type { UseAudioPlaybackOptions, UseAudioPlaybackReturn } from './types';
import { formatDuration } from './formatUtils';
import { usePlaybackState } from './usePlaybackState';
import { useAudioMode } from './useAudioMode';
import { usePlaybackStatusHandler } from './usePlaybackStatusHandler';
import { useLoadAudio } from './useLoadAudio';
import { usePlaybackControls } from './usePlaybackControls';
import { useResumeFromInterruption } from './useResumeFromInterruption';
import { useSeekControls } from './useSeekControls';
import { useSpeedAndMute } from './useSpeedAndMute';
import { useAppStatePlayback } from './useAppStatePlayback';

export function useAudioPlayback(
  options?: UseAudioPlaybackOptions
): UseAudioPlaybackReturn {
  const opts = options || {};
  const state = usePlaybackState();
  const { configureAudioMode } = useAudioMode();

  const { onPlaybackStatusUpdate, handleInterruption } =
    usePlaybackStatusHandler(
      {
        currentState: state.status.state,
        setStatus: state.setStatus,
        wasPlayingBeforeInterruptionRef: state.wasPlayingBeforeInterruptionRef,
      },
      {
        onError: opts.onError,
        onFinish: opts.onFinish,
        onInterrupted: opts.onInterrupted,
      }
    );

  const { loadAudio, unloadAudio } = useLoadAudio(
    {
      configureAudioMode,
      onPlaybackStatusUpdate,
      setStatus: state.setStatus,
      soundRef: state.soundRef,
      wasPlayingBeforeInterruptionRef: state.wasPlayingBeforeInterruptionRef,
    },
    { autoPlayOnLoad: opts.autoPlayOnLoad ?? false, onError: opts.onError }
  );

  const { play, pause, togglePlayPause, replay } = usePlaybackControls(
    {
      currentState: state.status.state,
      setStatus: state.setStatus,
      soundRef: state.soundRef,
    },
    { onError: opts.onError }
  );

  const { resumeFromInterruption } = useResumeFromInterruption(
    {
      configureAudioMode,
      currentState: state.status.state,
      setStatus: state.setStatus,
      soundRef: state.soundRef,
      wasPlayingBeforeInterruptionRef: state.wasPlayingBeforeInterruptionRef,
    },
    { onError: opts.onError, onInterruptionEnded: opts.onInterruptionEnded }
  );

  const { seekBackward, seekForward, seekToProgress, seekToSeconds } =
    useSeekControls(
      {
        durationSeconds: state.status.durationSeconds,
        positionSeconds: state.status.positionSeconds,
        setStatus: state.setStatus,
        soundRef: state.soundRef,
      },
      { onError: opts.onError }
    );

  const { setSpeed, toggleMute } = useSpeedAndMute(
    {
      isMuted: state.status.isMuted,
      setStatus: state.setStatus,
      soundRef: state.soundRef,
    },
    { onError: opts.onError }
  );

  useAppStatePlayback(
    {
      currentState: state.status.state,
      handleInterruption,
      previousAppStateRef: state.previousAppStateRef,
    },
    { onInterruptionEnded: opts.onInterruptionEnded }
  );

  useEffect(() => {
    const sound = state.soundRef.current;
    return () => {
      sound?.unloadAsync().catch(() => {});
    };
  }, [state.soundRef]);

  const remainingSeconds =
    state.status.durationSeconds - state.status.positionSeconds;

  return {
    formattedDuration: formatDuration(state.status.durationSeconds),
    formattedPosition: formatDuration(state.status.positionSeconds),
    formattedRemaining: `-${formatDuration(Math.max(0, remainingSeconds))}`,
    isInterrupted: state.status.state === 'interrupted',
    isLoading: state.status.state === 'loading',
    isPlaying: state.status.state === 'playing',
    isReady: ['ready', 'playing', 'paused', 'finished'].includes(
      state.status.state
    ),
    loadAudio,
    pause,
    play,
    replay,
    resumeFromInterruption,
    seekBackward,
    seekForward,
    seekToProgress,
    seekToSeconds,
    setSpeed,
    status: state.status,
    toggleMute,
    togglePlayPause,
    unloadAudio,
  };
}

export default useAudioPlayback;

/**
 * useLoadAudio - Audio loading and unloading
 *
 * Handles loading audio from URI and cleanup.
 */

import { useCallback } from 'react';
import { Audio, AVPlaybackStatus } from 'expo-av';
import type { PlaybackStatus } from './types';
import {
  STATUS_UPDATE_INTERVAL_MS,
  INITIAL_PLAYBACK_STATUS,
} from './constants';

export interface UseLoadAudioOptions {
  autoPlayOnLoad: boolean;
  onError?: (error: Error) => void;
}

export interface UseLoadAudioDeps {
  soundRef: React.MutableRefObject<Audio.Sound | null>;
  wasPlayingBeforeInterruptionRef: React.MutableRefObject<boolean>;
  setStatus: React.Dispatch<React.SetStateAction<PlaybackStatus>>;
  configureAudioMode: () => Promise<void>;
  onPlaybackStatusUpdate: (status: AVPlaybackStatus) => void;
}

export interface UseLoadAudioReturn {
  loadAudio: (uri: string) => Promise<void>;
  unloadAudio: () => Promise<void>;
}

/**
 * Hook for loading and unloading audio
 */
export function useLoadAudio(
  deps: UseLoadAudioDeps,
  options: UseLoadAudioOptions
): UseLoadAudioReturn {
  const {
    soundRef,
    wasPlayingBeforeInterruptionRef,
    setStatus,
    configureAudioMode,
    onPlaybackStatusUpdate,
  } = deps;
  const { autoPlayOnLoad, onError } = options;

  /**
   * Load audio from URI
   */
  const loadAudio = useCallback(
    async (uri: string): Promise<void> => {
      try {
        // Unload any existing audio first
        if (soundRef.current) {
          await soundRef.current.unloadAsync();
          soundRef.current = null;
        }

        setStatus((prev) => ({
          ...prev,
          audioUri: uri,
          didJustFinish: false,
          durationSeconds: 0,
          errorMessage: null,
          positionSeconds: 0,
          progress: 0,
          state: 'loading',
        }));

        // Configure audio mode
        await configureAudioMode();

        // Create and load sound
        const { sound } = await Audio.Sound.createAsync(
          { uri },
          {
            progressUpdateIntervalMillis: STATUS_UPDATE_INTERVAL_MS,
            shouldPlay: autoPlayOnLoad,
          },
          onPlaybackStatusUpdate
        );

        soundRef.current = sound;

        setStatus((prev) => ({
          ...prev,
          state: autoPlayOnLoad ? 'playing' : 'ready',
        }));
      } catch (error) {
        const errorMessage =
          error instanceof Error ? error.message : 'Failed to load audio';
        setStatus((prev) => ({
          ...prev,
          errorMessage,
          state: 'error',
        }));
        onError?.(error instanceof Error ? error : new Error(errorMessage));
      }
    },
    [
      configureAudioMode,
      autoPlayOnLoad,
      onPlaybackStatusUpdate,
      onError,
      soundRef,
      setStatus,
    ]
  );

  /**
   * Unload the current audio
   */
  const unloadAudio = useCallback(async (): Promise<void> => {
    if (soundRef.current) {
      try {
        await soundRef.current.unloadAsync();
      } catch {
        // Ignore unload errors
      }
      soundRef.current = null;
    }

    wasPlayingBeforeInterruptionRef.current = false;
    setStatus(INITIAL_PLAYBACK_STATUS);
  }, [soundRef, wasPlayingBeforeInterruptionRef, setStatus]);

  return { loadAudio, unloadAudio };
}

/**
 * usePlaybackStatusHandler - Handles playback status updates
 *
 * Processes status updates from expo-av and detects audio interruptions.
 */

import { useCallback, useRef, useEffect } from 'react';
import type { AVPlaybackStatus } from 'expo-av';
import type {
  PlaybackState,
  PlaybackStatus,
  InterruptionReason,
} from './types';
import { isPlaybackStatusSuccess } from './statusUtils';

export interface UsePlaybackStatusHandlerOptions {
  onFinish?: () => void;
  onError?: (error: Error) => void;
  onInterrupted?: (reason: InterruptionReason) => void;
}

export interface UsePlaybackStatusHandlerReturn {
  onPlaybackStatusUpdate: (playbackStatus: AVPlaybackStatus) => void;
  handleInterruption: (reason: InterruptionReason) => void;
}

interface HandlerDeps {
  currentState: PlaybackState;
  setStatus: React.Dispatch<React.SetStateAction<PlaybackStatus>>;
  wasPlayingBeforeInterruptionRef: React.MutableRefObject<boolean>;
}

/**
 * Hook for handling playback status updates from expo-av
 */
export function usePlaybackStatusHandler(
  deps: HandlerDeps,
  options: UsePlaybackStatusHandlerOptions
): UsePlaybackStatusHandlerReturn {
  const { currentState, setStatus, wasPlayingBeforeInterruptionRef } = deps;
  const { onFinish, onError, onInterrupted } = options;

  // Use ref to track current state to avoid stale closure in callbacks
  const currentStateRef = useRef<PlaybackState>(currentState);
  useEffect(() => {
    currentStateRef.current = currentState;
  }, [currentState]);

  /**
   * Handle audio interruption (phone call, other app taking audio focus)
   */
  const handleInterruption = useCallback(
    (reason: InterruptionReason) => {
      // Only handle if we're currently playing (use ref for latest state)
      if (currentStateRef.current !== 'playing') return;

      // Mark that we were playing before interruption
      wasPlayingBeforeInterruptionRef.current = true;

      setStatus((prev) => ({
        ...prev,
        interruptionReason: reason,
        state: 'interrupted',
        wasInterrupted: true,
      }));

      onInterrupted?.(reason);
    },
    [onInterrupted, setStatus, wasPlayingBeforeInterruptionRef]
  );

  /**
   * Handle playback status updates from expo-av
   */
  const onPlaybackStatusUpdate = useCallback(
    (playbackStatus: AVPlaybackStatus) => {
      if (!isPlaybackStatusSuccess(playbackStatus)) {
        // Handle error or unloaded state
        if (!playbackStatus.isLoaded && playbackStatus.error) {
          setStatus((prev) => ({
            ...prev,
            errorMessage: playbackStatus.error || 'Playback error',
            state: 'error',
          }));
          onError?.(new Error(playbackStatus.error || 'Playback error'));
        }
        return;
      }

      const positionSeconds = Math.floor(
        (playbackStatus.positionMillis || 0) / 1000
      );
      const durationSeconds = Math.floor(
        (playbackStatus.durationMillis || 0) / 1000
      );
      const progress =
        durationSeconds > 0 ? positionSeconds / durationSeconds : 0;

      // Detect interruption: if we think we're playing but isPlaying is false
      // and we haven't finished and we're not paused by user
      // Use ref to get latest state value
      if (
        !playbackStatus.isPlaying &&
        !playbackStatus.didJustFinish &&
        currentStateRef.current === 'playing'
      ) {
        handleInterruption('system');
        return;
      }

      // Determine state based on playback status
      let newState: PlaybackState = 'ready';
      if (playbackStatus.isBuffering) {
        newState = 'loading';
      } else if (playbackStatus.didJustFinish) {
        newState = 'finished';
        onFinish?.();
      } else if (playbackStatus.isPlaying) {
        newState = 'playing';
      } else if (playbackStatus.positionMillis > 0) {
        newState = 'paused';
      }

      setStatus((prev) => ({
        ...prev,
        didJustFinish: playbackStatus.didJustFinish,
        durationSeconds,
        isMuted: playbackStatus.isMuted,
        positionSeconds,
        progress: Math.min(1, Math.max(0, progress)),
        state: newState,
      }));
    },
    [onFinish, onError, handleInterruption, setStatus]
  );

  return { handleInterruption, onPlaybackStatusUpdate };
}

/**
 * useSeekControls - Seek operations for audio playback
 *
 * Provides seeking functionality (progress, seconds, forward, backward).
 */

import { useCallback } from 'react';
import { Audio } from 'expo-av';
import type { PlaybackStatus } from './types';
import { DEFAULT_SEEK_STEP_SECONDS } from './constants';

export interface UseSeekControlsOptions {
  onError?: (error: Error) => void;
}

export interface UseSeekControlsDeps {
  soundRef: React.MutableRefObject<Audio.Sound | null>;
  durationSeconds: number;
  positionSeconds: number;
  setStatus: React.Dispatch<React.SetStateAction<PlaybackStatus>>;
}

export interface UseSeekControlsReturn {
  seekToProgress: (progress: number) => Promise<void>;
  seekToSeconds: (seconds: number) => Promise<void>;
  seekForward: (seconds?: number) => Promise<void>;
  seekBackward: (seconds?: number) => Promise<void>;
}

/**
 * Hook for seek controls
 */
export function useSeekControls(
  deps: UseSeekControlsDeps,
  options: UseSeekControlsOptions
): UseSeekControlsReturn {
  const { soundRef, durationSeconds, positionSeconds, setStatus } = deps;
  const { onError } = options;

  /**
   * Seek to a specific position (0-1 progress)
   */
  const seekToProgress = useCallback(
    async (progress: number): Promise<void> => {
      if (!soundRef.current || durationSeconds === 0) return;

      try {
        const clampedProgress = Math.min(1, Math.max(0, progress));
        const positionMillis = clampedProgress * durationSeconds * 1000;

        setStatus((prev) => ({ ...prev, state: 'seeking' }));
        await soundRef.current.setPositionAsync(positionMillis);
      } catch (error) {
        const errorMessage =
          error instanceof Error ? error.message : 'Failed to seek';
        setStatus((prev) => ({
          ...prev,
          errorMessage,
          state: 'error',
        }));
        onError?.(error instanceof Error ? error : new Error(errorMessage));
      }
    },
    [durationSeconds, onError, soundRef, setStatus]
  );

  /**
   * Seek to a specific position in seconds
   */
  const seekToSeconds = useCallback(
    async (seconds: number): Promise<void> => {
      if (!soundRef.current) return;

      try {
        const clampedSeconds = Math.min(durationSeconds, Math.max(0, seconds));
        const positionMillis = clampedSeconds * 1000;

        setStatus((prev) => ({ ...prev, state: 'seeking' }));
        await soundRef.current.setPositionAsync(positionMillis);
      } catch (error) {
        const errorMessage =
          error instanceof Error ? error.message : 'Failed to seek';
        setStatus((prev) => ({
          ...prev,
          errorMessage,
          state: 'error',
        }));
        onError?.(error instanceof Error ? error : new Error(errorMessage));
      }
    },
    [durationSeconds, onError, soundRef, setStatus]
  );

  /**
   * Seek forward by a number of seconds
   */
  const seekForward = useCallback(
    async (seconds: number = DEFAULT_SEEK_STEP_SECONDS): Promise<void> => {
      const newPosition = Math.min(positionSeconds + seconds, durationSeconds);
      await seekToSeconds(newPosition);
    },
    [positionSeconds, durationSeconds, seekToSeconds]
  );

  /**
   * Seek backward by a number of seconds
   */
  const seekBackward = useCallback(
    async (seconds: number = DEFAULT_SEEK_STEP_SECONDS): Promise<void> => {
      const newPosition = Math.max(positionSeconds - seconds, 0);
      await seekToSeconds(newPosition);
    },
    [positionSeconds, seekToSeconds]
  );

  return {
    seekBackward,
    seekForward,
    seekToProgress,
    seekToSeconds,
  };
}

/**
 * Permission utilities for microphone access
 *
 * Story T10.2: Audio recording integration (expo-av)
 */

import { Platform, Linking, Alert } from 'react-native';

/**
 * Opens the device settings app so user can grant microphone permission
 * Uses platform-specific URL schemes
 */
export function openMicrophoneSettings(): void {
  if (Platform.OS === 'ios') {
    // On iOS, app-settings: opens the app's settings page directly
    Linking.openURL('app-settings:');
  } else {
    // On Android, openSettings() opens the app details page
    Linking.openSettings();
  }
}

/**
 * Shows an alert when microphone permission is denied
 * Provides option to open Settings
 */
export function showMicrophonePermissionAlert(options?: {
  title?: string;
  message?: string;
  onOpenSettings?: () => void;
  onCancel?: () => void;
}): void {
  const {
    title = 'Microphone Access Required',
    message = 'To record voice notes, please allow microphone access in your device Settings.',
    onOpenSettings,
    onCancel,
  } = options || {};

  Alert.alert(title, message, [
    {
      onPress: onCancel,
      style: 'cancel',
      text: 'Cancel',
    },
    {
      onPress: () => {
        openMicrophoneSettings();
        onOpenSettings?.();
      },
      text: 'Open Settings',
    },
  ]);
}

/**
 * useAudioRecording Hook - Main orchestrator
 *
 * Audio recording integration using expo-av for Voice Notes feature.
 *
 * Scientific Basis:
 * - Voice has 40% higher emotional recall than text (cognitive psychology)
 * - Hearing your own voice from Day 1 creates powerful emotional anchor
 *
 * Story T10.2: Audio recording integration (expo-av)
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import { Audio } from 'expo-av';
import type {
  UseAudioRecordingOptions,
  UseAudioRecordingReturn,
} from './types';
import {
  MAX_RECORDING_DURATION_SECONDS,
  DEFAULT_WARNING_THRESHOLD_SECONDS,
  INITIAL_RECORDING_STATUS,
} from './constants';
import {
  openMicrophoneSettings,
  showMicrophonePermissionAlert,
} from './permissionUtils';
import { formatDuration } from './formatUtils';
import { useRecordingPermission } from './useRecordingPermission';
import { useAudioMode } from './useAudioMode';
import { useRecordingStatusHandler } from './useRecordingStatusHandler';
import { useStartRecording } from './useStartRecording';
import { useStopRecording } from './useStopRecording';
import { useRecordingControl } from './useRecordingControl';
import { useAppStateInterruption } from './useAppStateInterruption';

export function useAudioRecording(
  options?: UseAudioRecordingOptions
): UseAudioRecordingReturn {
  const opts = { ...options };
  const maxDuration = opts.maxDurationSeconds ?? MAX_RECORDING_DURATION_SECONDS;
  const warningThreshold =
    opts.warningThresholdSeconds ?? DEFAULT_WARNING_THRESHOLD_SECONDS;

  const [status, setStatus] = useState(INITIAL_RECORDING_STATUS);
  const recordingRef = useRef<Audio.Recording | null>(null);

  const { requestPermission } = useRecordingPermission(setStatus, {
    onError: opts.onError,
    onPermissionDenied: opts.onPermissionDenied,
  });

  const { configureAudioMode, resetAudioMode } = useAudioMode();

  const {
    durationRef,
    handleInterruption,
    onRecordingStatusUpdate,
    resetRefs,
    wasRecordingBeforeInterruptionRef,
  } = useRecordingStatusHandler(setStatus, status.state, {
    maxDurationSeconds: maxDuration,
    onInterrupted: opts.onInterrupted,
    onMaxDurationReached: opts.onMaxDurationReached,
    onWarningThresholdReached: opts.onWarningThresholdReached,
    warningThresholdSeconds: warningThreshold,
  });

  const { startRecording } = useStartRecording({
    configureAudioMode,
    durationRef,
    hasPermission: status.hasPermission,
    onError: opts.onError,
    onRecordingStatusUpdate,
    recordingRef,
    requestPermission,
    resetRefs,
    setStatus,
  });

  const { cancelRecording, stopRecording } = useStopRecording({
    durationRef,
    onError: opts.onError,
    onRecordingComplete: opts.onRecordingComplete,
    recordingRef,
    resetAudioMode,
    resetRefs,
    setStatus,
  });

  const { pauseRecording, resumeFromInterruption, resumeRecording } =
    useRecordingControl({
      configureAudioMode,
      currentState: status.state,
      onError: opts.onError,
      onInterruptionEnded: opts.onInterruptionEnded,
      recordingRef,
      setStatus,
      wasRecordingBeforeInterruptionRef,
    });

  useAppStateInterruption({
    currentState: status.state,
    handleInterruption,
    onInterruptionEnded: opts.onInterruptionEnded,
  });

  useEffect(() => {
    return () => {
      recordingRef.current?.stopAndUnloadAsync().catch(() => {});
    };
  }, []);

  const reset = useCallback(() => {
    setStatus((p) => ({
      ...INITIAL_RECORDING_STATUS,
      canAskAgain: p.canAskAgain,
      hasPermission: p.hasPermission,
    }));
    resetRefs();
  }, [resetRefs]);

  const openSettings = useCallback(() => {
    openMicrophoneSettings();
    opts.onOpenSettings?.();
  }, [opts.onOpenSettings]);
  const showPermissionAlert = useCallback(() => {
    showMicrophonePermissionAlert({ onOpenSettings: opts.onOpenSettings });
  }, [opts.onOpenSettings]);

  return {
    cancelRecording,
    canStartRecording: status.state === 'idle' || status.state === 'stopped',
    formattedDuration: formatDuration(status.durationSeconds),
    isApproachingMaxDuration: status.isApproachingMaxDuration,
    isInterrupted: status.state === 'interrupted',
    isMaxDurationReached: status.durationSeconds >= maxDuration,
    isPaused: status.state === 'paused',
    isRecording: status.state === 'recording',
    openSettings,
    pauseRecording,
    requestPermission,
    reset,
    resumeFromInterruption,
    resumeRecording,
    secondsUntilMaxDuration: status.secondsUntilMaxDuration,
    showPermissionAlert,
    startRecording,
    status,
    stopRecording,
  };
}

export default useAudioRecording;

/**
 * Hook for pause/resume control during recording
 *
 * Story T10.2: Audio recording integration (expo-av)
 */

import { useCallback, RefObject } from 'react';
import { Audio } from 'expo-av';
import type { RecordingStatus, RecordingState } from './types';

type SetStatus = React.Dispatch<React.SetStateAction<RecordingStatus>>;

interface UseRecordingControlDeps {
  setStatus: SetStatus;
  currentState: RecordingState;
  configureAudioMode: () => Promise<void>;
  recordingRef: RefObject<Audio.Recording | null>;
  wasRecordingBeforeInterruptionRef: RefObject<boolean>;
  onInterruptionEnded?: () => void;
  onError?: (error: Error) => void;
}

export function useRecordingControl(deps: UseRecordingControlDeps) {
  const {
    setStatus,
    currentState,
    configureAudioMode,
    recordingRef,
    wasRecordingBeforeInterruptionRef,
    onInterruptionEnded,
    onError,
  } = deps;

  const pauseRecording = useCallback(async (): Promise<void> => {
    if (!recordingRef.current || currentState !== 'recording') return;

    try {
      await recordingRef.current.pauseAsync();
      setStatus((prev) => ({ ...prev, state: 'paused' }));
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to pause recording';
      setStatus((prev) => ({ ...prev, errorMessage, state: 'error' }));
      onError?.(error instanceof Error ? error : new Error(errorMessage));
    }
  }, [currentState, onError, setStatus, recordingRef]);

  const resumeRecording = useCallback(async (): Promise<void> => {
    if (!recordingRef.current || currentState !== 'paused') return;

    try {
      await recordingRef.current.startAsync();
      setStatus((prev) => ({ ...prev, state: 'recording' }));
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to resume recording';
      setStatus((prev) => ({ ...prev, errorMessage, state: 'error' }));
      onError?.(error instanceof Error ? error : new Error(errorMessage));
    }
  }, [currentState, onError, setStatus, recordingRef]);

  const resumeFromInterruption = useCallback(async (): Promise<void> => {
    if (!recordingRef.current || currentState !== 'interrupted') return;

    try {
      await configureAudioMode();
      await recordingRef.current.startAsync();

      (wasRecordingBeforeInterruptionRef as { current: boolean }).current =
        false;

      setStatus((prev) => ({
        ...prev,
        interruptionReason: null,
        state: 'recording',
      }));

      onInterruptionEnded?.();
    } catch (error) {
      const errorMessage =
        error instanceof Error
          ? error.message
          : 'Failed to resume after interruption';
      setStatus((prev) => ({ ...prev, errorMessage, state: 'error' }));
      onError?.(error instanceof Error ? error : new Error(errorMessage));
    }
  }, [
    currentState,
    configureAudioMode,
    onInterruptionEnded,
    onError,
    setStatus,
    recordingRef,
    wasRecordingBeforeInterruptionRef,
  ]);

  return { pauseRecording, resumeFromInterruption, resumeRecording };
}

/**
 * Hook for handling recording status updates from expo-av
 *
 * Story T10.2: Audio recording integration (expo-av)
 */

import { useCallback, useRef } from 'react';
import { Audio } from 'expo-av';
import type { RecordingStatus, RecordingState } from './types';

type SetStatus = React.Dispatch<React.SetStateAction<RecordingStatus>>;

interface UseRecordingStatusHandlerOptions {
  maxDurationSeconds: number;
  warningThresholdSeconds: number;
  onMaxDurationReached?: () => void;
  onWarningThresholdReached?: (secondsRemaining: number) => void;
  onInterrupted?: (reason: 'phone-call' | 'other-app' | 'system') => void;
}

export function useRecordingStatusHandler(
  setStatus: SetStatus,
  currentState: RecordingState,
  options: UseRecordingStatusHandlerOptions
) {
  const {
    maxDurationSeconds,
    warningThresholdSeconds,
    onMaxDurationReached,
    onWarningThresholdReached,
    onInterrupted,
  } = options;

  const durationRef = useRef<number>(0);
  const warningFiredRef = useRef<boolean>(false);
  const wasRecordingBeforeInterruptionRef = useRef<boolean>(false);

  const handleInterruption = useCallback(
    (reason: 'phone-call' | 'other-app' | 'system') => {
      if (currentState !== 'recording') return;
      wasRecordingBeforeInterruptionRef.current = true;
      setStatus((prev) => ({
        ...prev,
        interruptionReason: reason,
        state: 'interrupted',
        wasInterrupted: true,
      }));
      onInterrupted?.(reason);
    },
    [currentState, onInterrupted, setStatus]
  );

  const onRecordingStatusUpdate = useCallback(
    (recordingStatus: Audio.RecordingStatus) => {
      // Detect unexpected pause (interruption)
      if (
        !recordingStatus.isRecording &&
        recordingStatus.durationMillis &&
        recordingStatus.durationMillis > 0 &&
        currentState === 'recording'
      ) {
        handleInterruption('system');
        return;
      }

      if (!recordingStatus.isRecording) return;

      const durationSeconds = Math.floor(
        (recordingStatus.durationMillis || 0) / 1000
      );
      durationRef.current = durationSeconds;

      // Normalize metering from dB (-160 to 0) to 0-1 range
      const metering = recordingStatus.metering ?? -160;
      const normalizedMetering = Math.max(
        0,
        Math.min(1, (metering + 160) / 160)
      );

      // Calculate warning threshold status
      const warningStartTime = maxDurationSeconds - warningThresholdSeconds;
      const isApproachingMax = durationSeconds >= warningStartTime;
      const secondsRemaining = isApproachingMax
        ? maxDurationSeconds - durationSeconds
        : null;

      // Fire warning callback once per recording
      if (isApproachingMax && !warningFiredRef.current) {
        warningFiredRef.current = true;
        onWarningThresholdReached?.(
          secondsRemaining ?? warningThresholdSeconds
        );
      }

      setStatus((prev) => ({
        ...prev,
        durationSeconds,
        isApproachingMaxDuration: isApproachingMax,
        meteringLevel: normalizedMetering,
        secondsUntilMaxDuration: secondsRemaining,
      }));

      if (durationSeconds >= maxDurationSeconds) onMaxDurationReached?.();
    },
    [
      currentState,
      maxDurationSeconds,
      warningThresholdSeconds,
      onMaxDurationReached,
      onWarningThresholdReached,
      handleInterruption,
      setStatus,
    ]
  );

  const resetRefs = useCallback(() => {
    durationRef.current = 0;
    warningFiredRef.current = false;
    wasRecordingBeforeInterruptionRef.current = false;
  }, []);

  return {
    durationRef,
    handleInterruption,
    onRecordingStatusUpdate,
    resetRefs,
    wasRecordingBeforeInterruptionRef,
  };
}

/**
 * Hook for starting a new recording
 *
 * Story T10.2: Audio recording integration (expo-av)
 */

import { useCallback, RefObject } from 'react';
import { Audio } from 'expo-av';
import type { RecordingStatus } from './types';
import { RECORDING_OPTIONS, STATUS_UPDATE_INTERVAL_MS } from './constants';

type SetStatus = React.Dispatch<React.SetStateAction<RecordingStatus>>;

interface UseStartRecordingDeps {
  setStatus: SetStatus;
  hasPermission: boolean | null;
  requestPermission: () => Promise<boolean>;
  configureAudioMode: () => Promise<void>;
  onRecordingStatusUpdate: (status: Audio.RecordingStatus) => void;
  durationRef: RefObject<number>;
  resetRefs: () => void;
  recordingRef: RefObject<Audio.Recording | null>;
  onError?: (error: Error) => void;
}

export function useStartRecording(deps: UseStartRecordingDeps) {
  const {
    setStatus,
    hasPermission,
    requestPermission,
    configureAudioMode,
    onRecordingStatusUpdate,
    durationRef,
    resetRefs,
    recordingRef,
    onError,
  } = deps;

  const startRecording = useCallback(async (): Promise<void> => {
    try {
      let permission = hasPermission;
      if (permission === null) {
        permission = await requestPermission();
      }

      if (!permission) {
        setStatus((prev) => ({
          ...prev,
          errorMessage: 'Microphone permission required',
          state: 'permission-denied',
        }));
        return;
      }

      setStatus((prev) => ({
        ...prev,
        durationSeconds: 0,
        errorMessage: null,
        isApproachingMaxDuration: false,
        meteringLevel: 0,
        recordingUri: null,
        secondsUntilMaxDuration: null,
        state: 'preparing',
      }));

      resetRefs();
      await configureAudioMode();

      const { recording } = await Audio.Recording.createAsync(
        RECORDING_OPTIONS,
        onRecordingStatusUpdate,
        STATUS_UPDATE_INTERVAL_MS
      );

      (recordingRef as { current: Audio.Recording | null }).current = recording;
      (durationRef as { current: number }).current = 0;

      setStatus((prev) => ({ ...prev, state: 'recording' }));
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to start recording';
      setStatus((prev) => ({ ...prev, errorMessage, state: 'error' }));
      onError?.(error instanceof Error ? error : new Error(errorMessage));
    }
  }, [
    hasPermission,
    requestPermission,
    configureAudioMode,
    onRecordingStatusUpdate,
    onError,
    setStatus,
    durationRef,
    resetRefs,
    recordingRef,
  ]);

  return { startRecording };
}

/**
 * Hook for stopping and canceling recordings
 *
 * Story T10.2: Audio recording integration (expo-av)
 */

import { useCallback, RefObject } from 'react';
import { Audio } from 'expo-av';
import type { RecordingStatus } from './types';

type SetStatus = React.Dispatch<React.SetStateAction<RecordingStatus>>;

interface UseStopRecordingDeps {
  setStatus: SetStatus;
  resetAudioMode: () => Promise<void>;
  durationRef: RefObject<number>;
  resetRefs: () => void;
  recordingRef: RefObject<Audio.Recording | null>;
  onRecordingComplete?: (uri: string, durationSeconds: number) => void;
  onError?: (error: Error) => void;
}

export function useStopRecording(deps: UseStopRecordingDeps) {
  const {
    setStatus,
    resetAudioMode,
    durationRef,
    resetRefs,
    recordingRef,
    onRecordingComplete,
    onError,
  } = deps;

  const stopRecording = useCallback(async (): Promise<string | null> => {
    if (!recordingRef.current) return null;

    try {
      setStatus((prev) => ({ ...prev, state: 'stopping' }));

      await recordingRef.current.stopAndUnloadAsync();
      await resetAudioMode();

      const uri = recordingRef.current.getURI();
      const finalDuration = durationRef.current ?? 0;

      (recordingRef as { current: Audio.Recording | null }).current = null;

      setStatus((prev) => ({ ...prev, recordingUri: uri, state: 'stopped' }));

      if (uri) {
        onRecordingComplete?.(uri, finalDuration);
      }

      return uri;
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to stop recording';
      setStatus((prev) => ({ ...prev, errorMessage, state: 'error' }));
      onError?.(error instanceof Error ? error : new Error(errorMessage));
      return null;
    }
  }, [
    onRecordingComplete,
    onError,
    setStatus,
    durationRef,
    resetAudioMode,
    recordingRef,
  ]);

  const cancelRecording = useCallback(async (): Promise<void> => {
    if (!recordingRef.current) return;

    try {
      try {
        await recordingRef.current.stopAndUnloadAsync();
      } catch {
        // Recording might already be stopped
      }

      await resetAudioMode();

      (recordingRef as { current: Audio.Recording | null }).current = null;
      resetRefs();

      setStatus((prev) => ({
        ...prev,
        durationSeconds: 0,
        errorMessage: null,
        interruptionReason: null,
        isApproachingMaxDuration: false,
        meteringLevel: 0,
        recordingUri: null,
        secondsUntilMaxDuration: null,
        state: 'idle',
        wasInterrupted: false,
      }));
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to cancel recording';
      setStatus((prev) => ({ ...prev, errorMessage, state: 'error' }));
      onError?.(error instanceof Error ? error : new Error(errorMessage));
    }
  }, [onError, setStatus, resetRefs, resetAudioMode, recordingRef]);

  return { cancelRecording, stopRecording };
}

/**
 * useDraftStorage Hook
 * Auto-saves drafts for long-form content (Why, Letters, Reflections) to prevent data loss
 *
 * Part of Edge Case handling: T1 - Data Loss Prevention
 *
 * Features:
 * - Debounced auto-save (1000ms default delay)
 * - AsyncStorage-based persistence (cross-platform)
 * - Draft recovery on mount
 * - Automatic cleanup on successful save
 *
 * Storage Key Pattern: `draft:<habitId>:<contentType>`
 * Example: `draft:abc123:why`, `draft:abc123:letter`, `draft:abc123:reflection`
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';

/**
 * Content types that can be auto-saved
 */
export type DraftContentType =
  | 'why'
  | 'identity'
  | 'letter-title'
  | 'letter-content'
  | 'reflection-note'
  | 'affirmation'
  | 'woop-wish'
  | 'woop-outcome'
  | 'woop-obstacle'
  | 'woop-plan'
  | 'viz-success-body'
  | 'viz-success-mind'
  | 'viz-success-emotion'
  | 'viz-failure-body'
  | 'viz-failure-mind'
  | 'viz-failure-emotion';

/**
 * Draft data structure stored in AsyncStorage
 */
interface StoredDraft {
  content: string;
  timestamp: number;
  version: 1;
}

/**
 * Configuration options for the hook
 */
export interface UseDraftStorageOptions {
  /** Unique identifier for the habit */
  habitId: string;
  /** Type of content being drafted */
  contentType: DraftContentType;
  /** Delay in ms before auto-saving (default: 1000ms) */
  debounceMs?: number;
  /** Whether auto-save is enabled (default: true) */
  enabled?: boolean;
  /** Maximum age of draft in ms before it's considered stale (default: 7 days) */
  maxAgeMs?: number;
  /** Callback when draft is recovered */
  onDraftRecovered?: (content: string) => void;
  /** Callback when save error occurs */
  onSaveError?: (error: Error) => void;
}

/**
 * Return value from the hook
 */
export interface UseDraftStorageReturn {
  /** Current draft value */
  draft: string;
  /** Whether there's an unsaved draft */
  hasDraft: boolean;
  /** Whether the draft was recovered from storage on mount */
  wasRecovered: boolean;
  /** Whether a save is pending (debounced) */
  isSaving: boolean;
  /** Update the draft (will auto-save after debounce) */
  setDraft: (value: string) => void;
  /** Clear the draft from storage */
  clearDraft: () => Promise<void>;
  /** Force an immediate save (bypasses debounce) */
  saveNow: () => Promise<void>;
  /** Discard the recovered draft and use empty state */
  discardRecoveredDraft: () => Promise<void>;
}

// Storage key prefix
const DRAFT_KEY_PREFIX = 'draft:';

// Default values
const DEFAULT_DEBOUNCE_MS = 1000;
const DEFAULT_MAX_AGE_MS = 7 * 24 * 60 * 60 * 1000; // 7 days

/**
 * Generate storage key for a draft
 */
export function getDraftKey(
  habitId: string,
  contentType: DraftContentType
): string {
  return `${DRAFT_KEY_PREFIX}${habitId}:${contentType}`;
}

/**
 * Get a draft from storage
 */
export async function getDraft(
  habitId: string,
  contentType: DraftContentType,
  maxAgeMs: number = DEFAULT_MAX_AGE_MS
): Promise<string | null> {
  try {
    const key = getDraftKey(habitId, contentType);
    const raw = await AsyncStorage.getItem(key);

    if (!raw) return null;

    const stored: StoredDraft = JSON.parse(raw);

    // Check if draft is stale
    if (Date.now() - stored.timestamp > maxAgeMs) {
      // Draft is too old, clean it up
      await AsyncStorage.removeItem(key);
      return null;
    }

    return stored.content;
  } catch (error) {
    console.warn('Failed to read draft:', error);
    return null;
  }
}

/**
 * Save a draft to storage
 */
export async function saveDraft(
  habitId: string,
  contentType: DraftContentType,
  content: string
): Promise<void> {
  try {
    const key = getDraftKey(habitId, contentType);

    if (!content || content.trim().length === 0) {
      // If content is empty, remove the draft
      await AsyncStorage.removeItem(key);
      return;
    }

    const stored: StoredDraft = {
      content,
      timestamp: Date.now(),
      version: 1,
    };

    await AsyncStorage.setItem(key, JSON.stringify(stored));
  } catch (error) {
    console.warn('Failed to save draft:', error);
    throw error;
  }
}

/**
 * Clear a draft from storage
 */
export async function clearDraft(
  habitId: string,
  contentType: DraftContentType
): Promise<void> {
  try {
    const key = getDraftKey(habitId, contentType);
    await AsyncStorage.removeItem(key);
  } catch (error) {
    console.warn('Failed to clear draft:', error);
    // Don't throw - clearing is non-critical
  }
}

/**
 * Clear all drafts for a habit
 */
export async function clearAllDraftsForHabit(habitId: string): Promise<void> {
  try {
    const allKeys = await AsyncStorage.getAllKeys();
    const habitDraftKeys = allKeys.filter((key) =>
      key.startsWith(`${DRAFT_KEY_PREFIX}${habitId}:`)
    );

    if (habitDraftKeys.length > 0) {
      await AsyncStorage.multiRemove(habitDraftKeys);
    }
  } catch (error) {
    console.warn('Failed to clear habit drafts:', error);
  }
}

/**
 * Get all draft keys (for debugging/cleanup)
 */
export async function getAllDraftKeys(): Promise<string[]> {
  try {
    const allKeys = await AsyncStorage.getAllKeys();
    return allKeys.filter((key) => key.startsWith(DRAFT_KEY_PREFIX));
  } catch (error) {
    console.warn('Failed to get draft keys:', error);
    return [];
  }
}

/**
 * useDraftStorage Hook
 *
 * Provides auto-save functionality for form fields with debouncing,
 * persistence to AsyncStorage, and draft recovery on mount.
 *
 * @example
 * ```tsx
 * const { draft, setDraft, clearDraft, wasRecovered } = useDraftStorage({
 *   habitId: habit._id,
 *   contentType: 'why',
 *   onDraftRecovered: (content) => {
 *     // Optionally show a "Draft recovered" message
 *   },
 * });
 *
 * // When user saves successfully:
 * await handleSave();
 * await clearDraft();
 * ```
 */
export function useDraftStorage({
  habitId,
  contentType,
  debounceMs = DEFAULT_DEBOUNCE_MS,
  enabled = true,
  maxAgeMs = DEFAULT_MAX_AGE_MS,
  onDraftRecovered,
  onSaveError,
}: UseDraftStorageOptions): UseDraftStorageReturn {
  const [draft, setDraftState] = useState<string>('');
  const [wasRecovered, setWasRecovered] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);

  // Refs for debouncing
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const pendingDraftRef = useRef<string | null>(null);

  // Recover draft on mount
  useEffect(() => {
    if (!enabled || !habitId) {
      setIsInitialized(true);
      return;
    }

    let isMounted = true;

    const recoverDraft = async () => {
      try {
        const recovered = await getDraft(habitId, contentType, maxAgeMs);

        if (isMounted && recovered && recovered.trim().length > 0) {
          setDraftState(recovered);
          setWasRecovered(true);
          onDraftRecovered?.(recovered);
        }
      } catch (error) {
        console.warn('Draft recovery failed:', error);
      } finally {
        if (isMounted) {
          setIsInitialized(true);
        }
      }
    };

    recoverDraft();

    return () => {
      isMounted = false;
    };
  }, [habitId, contentType, enabled, maxAgeMs, onDraftRecovered]);

  // Cleanup debounce timer on unmount
  useEffect(() => {
    return () => {
      if (debounceTimerRef.current) {
        clearTimeout(debounceTimerRef.current);
      }
    };
  }, []);

  // Internal save function
  const performSave = useCallback(
    async (content: string) => {
      if (!enabled || !habitId) return;

      try {
        setIsSaving(true);
        await saveDraft(habitId, contentType, content);
      } catch (error) {
        onSaveError?.(error as Error);
      } finally {
        setIsSaving(false);
        pendingDraftRef.current = null;
      }
    },
    [enabled, habitId, contentType, onSaveError]
  );

  // Debounced save
  const debouncedSave = useCallback(
    (content: string) => {
      pendingDraftRef.current = content;

      if (debounceTimerRef.current) {
        clearTimeout(debounceTimerRef.current);
      }

      debounceTimerRef.current = setTimeout(() => {
        performSave(content);
      }, debounceMs);
    },
    [debounceMs, performSave]
  );

  // Set draft function exposed to consumers
  const setDraft = useCallback(
    (value: string) => {
      setDraftState(value);

      // Once user starts editing, it's no longer a "recovered" draft
      if (wasRecovered && value !== draft) {
        setWasRecovered(false);
      }

      if (enabled && isInitialized) {
        debouncedSave(value);
      }
    },
    [enabled, isInitialized, debouncedSave, wasRecovered, draft]
  );

  // Force immediate save
  const saveNow = useCallback(async () => {
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
      debounceTimerRef.current = null;
    }

    await performSave(draft);
  }, [draft, performSave]);

  // Clear draft from storage
  const handleClearDraft = useCallback(async () => {
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
      debounceTimerRef.current = null;
    }

    await clearDraft(habitId, contentType);
    setDraftState('');
    setWasRecovered(false);
    pendingDraftRef.current = null;
  }, [habitId, contentType]);

  // Discard recovered draft
  const discardRecoveredDraft = useCallback(async () => {
    await handleClearDraft();
  }, [handleClearDraft]);

  return {
    clearDraft: handleClearDraft,
    discardRecoveredDraft,
    draft,
    hasDraft: draft.trim().length > 0,
    isSaving: isSaving || pendingDraftRef.current !== null,
    saveNow,
    setDraft,
    wasRecovered,
  };
}

export default useDraftStorage;

/**
 * useHabitStrength Hook
 *
 * Calculates habit strength using exponential smoothing algorithm.
 * Returns current strength, historical timeline, and comparison metrics.
 *
 * The algorithm is based on Loop Habit Tracker:
 * - Growth on completion: strength + (1 - strength) * 0.05
 * - Decay on miss: strength * 0.95
 * - Reaches ~100% after ~60-90 days of perfect consistency
 *
 * @example
 * ```tsx
 * const { currentStrength, strengthHistory, metrics, isCalculating } = useHabitStrength(
 *   completedDates,
 *   habitCreatedAt
 * );
 *
 * // Display current strength
 * <Text>{currentStrength}%</Text>
 *
 * // Chart the history
 * <StrengthTimelineChart data={strengthHistory} />
 *
 * // Show comparison metrics
 * <Text>Peak: {metrics.peak}%</Text>
 * ```
 *
 * @see habit-strength-history-spec.md Section 3 for algorithm details
 */

import { useMemo } from 'react';

import { differenceInDays, startOfDay, subDays, subYears } from 'date-fns';

import type { StrengthMetrics, UseHabitStrengthReturn } from '../components/HabitStrengthHistory/types';
import {
  calculateDelta,
  calculateStrengthAtDate,
  calculateStrengthExtremes,
  generateStrengthTimeline,
} from '../components/HabitStrengthHistory/strengthUtils';

/**
 * Hook to calculate habit strength metrics and history.
 *
 * Uses memoization keyed on completedDates.size and habitCreatedAt
 * to avoid expensive recalculations on every render.
 *
 * @param completedDates - Set of completed dates in YYYY-MM-DD format
 * @param habitCreatedAt - Timestamp when the habit was created (ms since epoch)
 * @returns Object with currentStrength, strengthHistory, metrics, and isCalculating
 */
export function useHabitStrength(
  completedDates: Set<string>,
  habitCreatedAt: number
): UseHabitStrengthReturn {
  // Memoize the entire calculation based on inputs
  // Key insight: We use completedDates.size as a proxy for content changes
  // This works because the Set is typically recreated when entries change
  const result = useMemo(() => {
    const createdAtDate = new Date(habitCreatedAt);
    const today = startOfDay(new Date());
    const habitAgeDays = differenceInDays(today, startOfDay(createdAtDate)) + 1;

    // Generate the full strength timeline
    const strengthHistory = generateStrengthTimeline(completedDates, createdAtDate);

    // Current strength is the last value in the timeline
    const currentStrength =
      strengthHistory.length > 0
        ? strengthHistory[strengthHistory.length - 1].strength
        : 0;

    // Calculate strength at 30 days ago (if habit is old enough)
    const thirtyDaysAgo = subDays(today, 30);
    const thirtyDaysAgoStrength =
      habitAgeDays > 30
        ? calculateStrengthAtDate(completedDates, createdAtDate, thirtyDaysAgo)
        : null;

    // Calculate strength at 1 year ago (if habit is old enough)
    const oneYearAgo = subYears(today, 1);
    const oneYearAgoStrength =
      habitAgeDays > 365
        ? calculateStrengthAtDate(completedDates, createdAtDate, oneYearAgo)
        : null;

    // Calculate peak and lowest from history
    const { peak, lowest } = calculateStrengthExtremes(strengthHistory);

    // Calculate delta vs 30 days ago
    const deltaVsMonth =
      thirtyDaysAgoStrength !== null
        ? calculateDelta(currentStrength, thirtyDaysAgoStrength)
        : currentStrength; // If habit < 30 days, delta is the current value

    const metrics: StrengthMetrics = {
      current: currentStrength,
      thirtyDaysAgo: thirtyDaysAgoStrength,
      oneYearAgo: oneYearAgoStrength,
      peak: peak.strength,
      peakDate: peak.date,
      lowest: lowest.strength,
      lowestDate: lowest.date,
      deltaVsMonth,
      habitAgeDays,
    };

    return {
      currentStrength,
      strengthHistory,
      metrics,
      isCalculating: false,
    };
  }, [completedDates, habitCreatedAt]);

  return result;
}

export default useHabitStrength;

import { useMemo } from 'react';
import * as Haptics from 'expo-haptics';
import { Platform } from 'react-native';

import { useReduceMotion } from './useReduceMotion';

type HapticKind = 'light' | 'medium' | 'heavy' | 'success' | 'warning' | 'error';

interface UseHapticFeedbackOptions {
  isEnabled?: boolean;
  preference?: boolean;
}

const noop = async () => {};

const INPUT_TO_FEEDBACK: Record<HapticKind, () => Promise<void>> = {
  error: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error),
  heavy: () => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy),
  light: () => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light),
  medium: () => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium),
  success: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success),
  warning: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning),
};

const isHapticsSupported = Platform.OS === 'ios' || Platform.OS === 'android';

export const useHapticFeedback = ({ isEnabled = true, preference }: UseHapticFeedbackOptions = {}) => {
  const reduceMotion = useReduceMotion({ preference });

  return useMemo(() => {
    if (!isEnabled || reduceMotion || !isHapticsSupported) {
      return {
        triggerError: noop,
        triggerHeavyImpact: noop,
        triggerLightImpact: noop,
        triggerMediumImpact: noop,
        triggerSelection: noop,
        triggerSuccess: noop,
        triggerWarning: noop,
      };
    }

    const safeCall = (fn: () => Promise<void>) => {
      fn().catch(() => {
        // Silently fail - haptics are non-critical UX enhancements
      });
    };

    return {
      triggerError: () => safeCall(INPUT_TO_FEEDBACK.error),
      triggerHeavyImpact: () => safeCall(INPUT_TO_FEEDBACK.heavy),
      triggerLightImpact: () => safeCall(INPUT_TO_FEEDBACK.light),
      triggerMediumImpact: () => safeCall(INPUT_TO_FEEDBACK.medium),
      triggerSelection: () => safeCall(() => Haptics.selectionAsync()),
      triggerSuccess: () => safeCall(INPUT_TO_FEEDBACK.success),
      triggerWarning: () => safeCall(INPUT_TO_FEEDBACK.warning),
    };
  }, [reduceMotion, isEnabled]);
};

export default useHapticFeedback;

/**
 * useImagePicker Hook
 * Handles image selection from camera and library using expo-image-picker
 *
 * Features:
 * - Pick from photo library
 * - Capture from camera
 * - Permission handling with graceful fallback
 * - Configurable aspect ratio and quality
 * - Error handling with descriptive messages
 *
 * Story T12.2: Image picker integration for Vision Board
 */

import { useCallback, useState } from 'react';
import * as ImagePicker from 'expo-image-picker';
import { Alert, Linking, Platform } from 'react-native';

export type ImageSource = 'camera' | 'library';

export interface PickedImage {
  uri: string;
  width: number;
  height: number;
  type: 'image';
  mimeType: string;
  fileSize?: number;
}

export interface ImagePickerOptions {
  /** Aspect ratio for cropping [width, height] */
  aspect?: [number, number];
  /** Image quality 0-1 */
  quality?: number;
  /** Allow editing/cropping */
  allowsEditing?: boolean;
  /** Base64 encoding (increases memory usage) */
  base64?: boolean;
}

export interface UseImagePickerReturn {
  /** Currently picked image */
  image: PickedImage | null;
  /** Loading state during permission check or image selection */
  isLoading: boolean;
  /** Error message if something went wrong */
  error: string | null;
  /** Pick an image from the photo library */
  pickFromLibrary: (
    options?: ImagePickerOptions
  ) => Promise<PickedImage | null>;
  /** Take a photo with the camera */
  pickFromCamera: (options?: ImagePickerOptions) => Promise<PickedImage | null>;
  /** Show action sheet to choose source */
  pickWithChoice: (options?: ImagePickerOptions) => Promise<PickedImage | null>;
  /** Clear the current image */
  clearImage: () => void;
  /** Check and request permissions */
  requestPermissions: (source: ImageSource) => Promise<boolean>;
  /** Whether camera permission is granted */
  hasCameraPermission: boolean | null;
  /** Whether library permission is granted */
  hasLibraryPermission: boolean | null;
}

// Default options for image picking
const DEFAULT_OPTIONS: ImagePickerOptions = {
  allowsEditing: true,
  aspect: [1, 1],
  base64: false,
  quality: 0.8,
};

/**
 * Opens the device settings app for permission management
 */
function openSettings() {
  if (Platform.OS === 'ios') {
    Linking.openURL('app-settings:');
  } else {
    Linking.openSettings();
  }
}

/**
 * Shows an alert when permission is denied
 */
function showPermissionDeniedAlert(source: ImageSource) {
  const sourceText = source === 'camera' ? 'camera' : 'photo library';
  Alert.alert(
    'Permission Required',
    `To add images to your Vision Board, please allow access to your ${sourceText} in Settings.`,
    [
      { style: 'cancel', text: 'Cancel' },
      { onPress: openSettings, text: 'Open Settings' },
    ]
  );
}

/**
 * Custom hook for image picking with expo-image-picker
 */
export function useImagePicker(): UseImagePickerReturn {
  const [image, setImage] = useState<PickedImage | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasCameraPermission, setHasCameraPermission] = useState<
    boolean | null
  >(null);
  const [hasLibraryPermission, setHasLibraryPermission] = useState<
    boolean | null
  >(null);

  /**
   * Check and request permissions for the specified source
   */
  const requestPermissions = useCallback(
    async (source: ImageSource): Promise<boolean> => {
      try {
        if (source === 'camera') {
          const { status } = await ImagePicker.requestCameraPermissionsAsync();
          const granted = status === 'granted';
          setHasCameraPermission(granted);
          if (!granted) {
            showPermissionDeniedAlert('camera');
          }
          return granted;
        } else {
          const { status } =
            await ImagePicker.requestMediaLibraryPermissionsAsync();
          const granted = status === 'granted';
          setHasLibraryPermission(granted);
          if (!granted) {
            showPermissionDeniedAlert('library');
          }
          return granted;
        }
      } catch (error_) {
        console.error('Permission request error:', error_);
        setError('Failed to request permissions');
        return false;
      }
    },
    []
  );

  /**
   * Convert ImagePicker result to our PickedImage format
   */
  const convertAsset = useCallback(
    (asset: ImagePicker.ImagePickerAsset): PickedImage => {
      return {
        fileSize: asset.fileSize,
        height: asset.height,
        mimeType: asset.mimeType || 'image/jpeg',
        type: 'image',
        uri: asset.uri,
        width: asset.width,
      };
    },
    []
  );

  /**
   * Pick an image from the photo library
   */
  const pickFromLibrary = useCallback(
    async (options: ImagePickerOptions = {}): Promise<PickedImage | null> => {
      setError(null);
      setIsLoading(true);

      try {
        // Check permissions
        const hasPermission = await requestPermissions('library');
        if (!hasPermission) {
          setIsLoading(false);
          return null;
        }

        // Merge options with defaults
        const mergedOptions = { ...DEFAULT_OPTIONS, ...options };

        // Launch image picker
        const result = await ImagePicker.launchImageLibraryAsync({
          allowsEditing: mergedOptions.allowsEditing,
          aspect: mergedOptions.aspect,
          base64: mergedOptions.base64,
          mediaTypes: ['images'],
          quality: mergedOptions.quality,
        });

        if (result.canceled || !result.assets || result.assets.length === 0) {
          setIsLoading(false);
          return null;
        }

        const pickedImage = convertAsset(result.assets[0]);
        setImage(pickedImage);
        setIsLoading(false);
        return pickedImage;
      } catch (error_) {
        const errorMessage =
          error_ instanceof Error ? error_.message : 'Failed to pick image';
        setError(errorMessage);
        setIsLoading(false);
        console.error('Image picker error:', error_);
        return null;
      }
    },
    [requestPermissions, convertAsset]
  );

  /**
   * Take a photo with the camera
   */
  const pickFromCamera = useCallback(
    async (options: ImagePickerOptions = {}): Promise<PickedImage | null> => {
      setError(null);
      setIsLoading(true);

      try {
        // Check permissions
        const hasPermission = await requestPermissions('camera');
        if (!hasPermission) {
          setIsLoading(false);
          return null;
        }

        // Merge options with defaults
        const mergedOptions = { ...DEFAULT_OPTIONS, ...options };

        // Launch camera
        const result = await ImagePicker.launchCameraAsync({
          allowsEditing: mergedOptions.allowsEditing,
          aspect: mergedOptions.aspect,
          base64: mergedOptions.base64,
          quality: mergedOptions.quality,
        });

        if (result.canceled || !result.assets || result.assets.length === 0) {
          setIsLoading(false);
          return null;
        }

        const pickedImage = convertAsset(result.assets[0]);
        setImage(pickedImage);
        setIsLoading(false);
        return pickedImage;
      } catch (error_) {
        const errorMessage =
          error_ instanceof Error ? error_.message : 'Failed to capture photo';
        setError(errorMessage);
        setIsLoading(false);
        console.error('Camera error:', error_);
        return null;
      }
    },
    [requestPermissions, convertAsset]
  );

  /**
   * Show action sheet to let user choose between camera and library
   */
  const pickWithChoice = useCallback(
    async (options: ImagePickerOptions = {}): Promise<PickedImage | null> => {
      return new Promise((resolve) => {
        Alert.alert(
          'Add Image',
          'Choose how to add an image to your Vision Board',
          [
            {
              onPress: async () => {
                const result = await pickFromCamera(options);
                resolve(result);
              },
              text: 'Take Photo',
            },
            {
              onPress: async () => {
                const result = await pickFromLibrary(options);
                resolve(result);
              },
              text: 'Choose from Library',
            },
            {
              onPress: () => resolve(null),
              style: 'cancel',
              text: 'Cancel',
            },
          ]
        );
      });
    },
    [pickFromCamera, pickFromLibrary]
  );

  /**
   * Clear the current image
   */
  const clearImage = useCallback(() => {
    setImage(null);
    setError(null);
  }, []);

  return {
    clearImage,
    error,
    hasCameraPermission,
    hasLibraryPermission,
    image,
    isLoading,
    pickFromCamera,
    pickFromLibrary,
    pickWithChoice,
    requestPermissions,
  };
}

export default useImagePicker;

/**
 * useImageUpload Hook
 * Handles uploading images to Convex file storage
 *
 * Flow:
 * 1. Get signed upload URL from Convex
 * 2. Fetch local file as blob
 * 3. POST blob to signed URL
 * 4. Return storage ID for persistence
 *
 * Story T12.3: Image upload to storage for Vision Board
 */

import { useCallback, useState } from 'react';
import { useMutation } from 'convex/react';
import { api } from '../../convex/_generated/api';
import { Id } from '../../convex/_generated/dataModel';
import type { PickedImage } from './useImagePicker';

export interface UploadResult {
  storageId: Id<'_storage'>;
  url: string;
}

export interface UseImageUploadReturn {
  /** Upload an image to Convex storage */
  uploadImage: (image: PickedImage) => Promise<UploadResult | null>;
  /** Loading state during upload */
  isUploading: boolean;
  /** Upload progress 0-1 (not supported natively, always 0 or 1) */
  progress: number;
  /** Error message if upload failed */
  error: string | null;
  /** Clear error state */
  clearError: () => void;
}

/**
 * Custom hook for uploading images to Convex file storage
 */
export function useImageUpload(): UseImageUploadReturn {
  const [isUploading, setIsUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);

  // Convex mutation for generating upload URL
  const generateUploadUrl = useMutation(api.storage.generateUploadUrl);

  /**
   * Upload an image to Convex storage
   */
  const uploadImage = useCallback(
    async (image: PickedImage): Promise<UploadResult | null> => {
      setError(null);
      setIsUploading(true);
      setProgress(0);

      try {
        // Step 1: Get signed upload URL from Convex
        const uploadUrl = await generateUploadUrl();

        // Step 2: Fetch the local file as a blob
        const fileResponse = await fetch(image.uri);
        if (!fileResponse.ok) {
          throw new Error(`Failed to read local file: ${fileResponse.status}`);
        }
        const blob = await fileResponse.blob();

        // Validate blob size (Convex has no hard limit but we set a reasonable one)
        const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10 MB
        if (blob.size > MAX_FILE_SIZE) {
          throw new Error(
            `Image too large. Maximum size is ${MAX_FILE_SIZE / 1024 / 1024}MB`
          );
        }

        // Step 3: Upload the blob to Convex storage
        const uploadResponse = await fetch(uploadUrl, {
          body: blob,
          headers: {
            'Content-Type': image.mimeType || 'image/jpeg',
          },
          method: 'POST',
        });

        if (!uploadResponse.ok) {
          const errorText = await uploadResponse.text();
          throw new Error(
            `Upload failed: ${uploadResponse.status} - ${errorText}`
          );
        }

        // Step 4: Parse the storage ID from the response
        const { storageId } = await uploadResponse.json();

        // The URL will be the upload response but we typically get
        // the final URL via a query. For now, return the storage ID.
        setProgress(1);
        setIsUploading(false);

        return {
          storageId: storageId as Id<'_storage'>,
          url: uploadUrl, // Temporary - will be replaced with getUrl result
        };
      } catch (error_) {
        const errorMessage =
          error_ instanceof Error ? error_.message : 'Failed to upload image';
        setError(errorMessage);
        setIsUploading(false);
        setProgress(0);
        console.error('Image upload error:', error_);
        return null;
      }
    },
    [generateUploadUrl]
  );

  /**
   * Clear error state
   */
  const clearError = useCallback(() => {
    setError(null);
  }, []);

  return {
    clearError,
    error,
    isUploading,
    progress,
    uploadImage,
  };
}

export default useImageUpload;

/**
 * useLetterNotification Hook
 * Manages letter unlock notification scheduling for the Letters to Self feature
 *
 * Part of T11.5: Unlock notification for Letters to Self
 *
 * This hook provides a wrapper for letter creation that automatically
 * schedules unlock notifications when a letter is saved.
 *
 * Scientific Basis:
 * - Temporal self-continuity: Connecting with future self increases self-control
 * - Anticipation psychology: Knowing a letter awaits increases engagement
 */

import { useCallback } from 'react';
import { useMutation } from 'convex/react';
import { api } from '../../convex/_generated/api';
import type { Id } from '../../convex/_generated/dataModel';
import {
  scheduleLetterUnlockNotification,
  cancelLetterUnlockNotification,
} from '../utils/notifications';

export interface UseLetterNotificationParams {
  /** The habit ID to create letters for */
  habitId: Id<'habits'>;
  /** Callback after letter is successfully created and notification scheduled */
  onSuccess?: (letterId: Id<'letters'>) => void;
  /** Callback if letter creation or notification scheduling fails */
  onError?: (error: Error) => void;
}

export interface CreateLetterWithNotificationParams {
  content: string;
  unlockDays: number;
  title?: string;
}

export interface UseLetterNotificationReturn {
  /**
   * Create a letter and schedule an unlock notification
   * Handles both the Convex mutation and local notification scheduling
   */
  createLetterWithNotification: (
    params: CreateLetterWithNotificationParams
  ) => Promise<Id<'letters'> | null>;

  /**
   * Cancel a letter's unlock notification
   * Call this if a letter is deleted before unlocking
   */
  cancelNotification: (letterId: string) => Promise<void>;

  /** Whether a letter creation is in progress */
  isCreating: boolean;
}

/**
 * Hook for creating letters with automatic unlock notification scheduling
 *
 * @example
 * ```tsx
 * const { createLetterWithNotification, isCreating } = useLetterNotification({
 *   habitId,
 *   onSuccess: (letterId) => {
 *     toast.success('Letter saved! You\'ll be notified when it unlocks.');
 *   },
 *   onError: (error) => {
 *     toast.error('Failed to save letter');
 *   },
 * });
 *
 * // In your save handler:
 * await createLetterWithNotification({
 *   content: 'Dear future me...',
 *   unlockDays: 7,
 *   title: 'Keep Going',
 * });
 * ```
 */
export function useLetterNotification({
  habitId,
  onSuccess,
  onError,
}: UseLetterNotificationParams): UseLetterNotificationReturn {
  const createLetter = useMutation(api.letters.create);

  const createLetterWithNotification = useCallback(
    async ({
      content,
      unlockDays,
      title,
    }: CreateLetterWithNotificationParams): Promise<Id<'letters'> | null> => {
      try {
        // Create the letter in Convex
        const letterId = await createLetter({
          content,
          habitId,
          title,
          unlockDays,
        });

        // Calculate unlock timestamp
        const unlockAt = Date.now() + unlockDays * 24 * 60 * 60 * 1000;

        // Schedule the unlock notification
        const notificationId = await scheduleLetterUnlockNotification({
          habitId: habitId.toString(),
          letterId: letterId.toString(),
          letterTitle: title || 'Letter to Self',
          unlockAt,
        });

        if (notificationId) {
          console.log(
            '[useLetterNotification] Letter created with notification:',
            {
              letterId,
              notificationId,
              unlockAt: new Date(unlockAt).toISOString(),
            }
          );
        } else {
          // Letter was created but notification failed - still successful
          console.warn(
            '[useLetterNotification] Letter created but notification scheduling failed:',
            letterId
          );
        }

        onSuccess?.(letterId);
        return letterId;
      } catch (error) {
        console.error(
          '[useLetterNotification] Failed to create letter:',
          error
        );
        onError?.(error instanceof Error ? error : new Error(String(error)));
        return null;
      }
    },
    [createLetter, habitId, onSuccess, onError]
  );

  const cancelNotification = useCallback(async (letterId: string) => {
    await cancelLetterUnlockNotification(letterId);
  }, []);

  return {
    cancelNotification,
    createLetterWithNotification,
    // Note: useMutation doesn't expose isPending in the same way useQuery does
    // The parent component should manage its own loading state
    isCreating: false,
  };
}

export default useLetterNotification;

/**
 * useNotificationResponse Hook
 * Handles notification tap responses for the Motivation System
 *
 * Part of T7.8: Trigger ActivationModal from notification tap
 * Part of T11.5: Handle letter unlock notification taps
 *
 * This hook listens for notification responses (when user taps a notification)
 * and routes to the appropriate handler based on notification type:
 * - Habit reminders → ActivationModal
 * - Letter unlocks → Letter reading modal
 *
 * Scientific Basis:
 * - Implementation intentions (Gollwitzer): 2-3x follow-through when prompted at right moment
 * - Context-aware intervention: Showing motivation content when user is primed to act
 * - Temporal self-continuity: Letters from past self increase self-control (Mischel)
 */

import { useEffect, useRef, useCallback } from 'react';
import * as Notifications from 'expo-notifications';
import type { NotificationResponse } from 'expo-notifications';
import { NOTIFICATION_TYPE_LETTER_UNLOCK } from '../utils/notifications';

export interface NotificationResponseHandler {
  /** Called when a habit notification is tapped */
  onHabitNotificationTap: (habitId: string) => void;
  /** Called when a letter unlock notification is tapped */
  onLetterNotificationTap?: (letterId: string, habitId: string) => void;
}

/**
 * Hook to handle notification response events
 *
 * @param handlers - Callbacks for handling different notification types
 * @returns Object with methods to programmatically trigger responses (for testing)
 *
 * @example
 * ```tsx
 * useNotificationResponse({
 *   onHabitNotificationTap: (habitId) => {
 *     openActivationModalById(habitId);
 *   },
 * });
 * ```
 */
export function useNotificationResponse(handlers: NotificationResponseHandler) {
  const handlersRef = useRef(handlers);

  // Keep handlers ref updated without re-subscribing to notifications
  useEffect(() => {
    handlersRef.current = handlers;
  }, [handlers]);

  const handleNotificationResponse = useCallback(
    (response: NotificationResponse) => {
      const data = response.notification.request.content.data;

      if (!data || typeof data !== 'object') {
        return;
      }

      // Check if this is a letter unlock notification
      if ('type' in data && data.type === NOTIFICATION_TYPE_LETTER_UNLOCK) {
        const letterId = 'letterId' in data ? data.letterId : null;
        const habitId = 'habitId' in data ? data.habitId : null;

        if (
          typeof letterId === 'string' &&
          letterId.length > 0 &&
          typeof habitId === 'string' &&
          habitId.length > 0
        ) {
          console.log('[useNotificationResponse] Letter notification tapped:', {
            habitId,
            letterId,
          });
          handlersRef.current.onLetterNotificationTap?.(letterId, habitId);
        }
        return;
      }

      // Check if this is a habit reminder notification (legacy format without type)
      if ('habitId' in data) {
        const habitId = data.habitId;

        if (typeof habitId === 'string' && habitId.length > 0) {
          console.log(
            '[useNotificationResponse] Habit notification tapped:',
            habitId
          );
          handlersRef.current.onHabitNotificationTap(habitId);
        }
      }
    },
    []
  );

  useEffect(() => {
    // Subscribe to notification response events (when user taps notification)
    const subscription = Notifications.addNotificationResponseReceivedListener(
      handleNotificationResponse
    );

    // Check for any notification that launched the app
    Notifications.getLastNotificationResponseAsync().then((response) => {
      if (response) {
        handleNotificationResponse(response);
      }
    });

    return () => {
      subscription.remove();
    };
  }, [handleNotificationResponse]);

  // Return for testing purposes
  return {
    /** Manually trigger a notification response (for testing) */
    _triggerResponse: handleNotificationResponse,
  };
}

export default useNotificationResponse;

/**
 * useOfflineQueue Hook
 * Offline queue for submissions when network unavailable
 */

import { useState, useEffect, useRef } from 'react';
import {
  DEFAULT_MAX_QUEUE_SIZE,
  DEFAULT_MAX_ITEM_AGE_MS,
  DEFAULT_MAX_RETRIES,
  DEFAULT_BASE_RETRY_DELAY_MS,
} from './constants';
import { loadAllQueueItems } from './storage';
import { calculateQueueStats } from './utils';
import { useQueueOperations } from './useQueueOperations';
import { useQueueQueries } from './useQueueQueries';
import type { UseOfflineQueueOptions, UseOfflineQueueReturn } from './types';

export function useOfflineQueue({
  maxQueueSize = DEFAULT_MAX_QUEUE_SIZE,
  maxItemAgeMs = DEFAULT_MAX_ITEM_AGE_MS,
  maxRetries = DEFAULT_MAX_RETRIES,
  baseRetryDelayMs = DEFAULT_BASE_RETRY_DELAY_MS,
  onItemProcessed,
  onItemFailed,
  onQueueChange,
}: UseOfflineQueueOptions = {}): UseOfflineQueueReturn {
  const [queueCount, setQueueCount] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const isMountedRef = useRef(true);

  useEffect(() => {
    const loadQueue = async () => {
      try {
        const items = await loadAllQueueItems();
        if (isMountedRef.current) {
          setQueueCount(items.length);
          setIsLoading(false);
          onQueueChange?.(calculateQueueStats(items));
        }
      } catch {
        if (isMountedRef.current) setIsLoading(false);
      }
    };
    void loadQueue();
    return () => {
      isMountedRef.current = false;
    };
  }, [onQueueChange]);

  const { enqueue, dequeue, markFailed } = useQueueOperations({
    isMountedRef,
    maxQueueSize,
    maxRetries,
    onItemFailed,
    onItemProcessed,
    onQueueChange,
    setQueueCount,
  });

  const {
    getQueue,
    getRetryableItems,
    getItem,
    clearQueue,
    cleanupStaleItems,
    getStats,
  } = useQueueQueries({
    baseRetryDelayMs,
    dequeue,
    isMountedRef,
    maxItemAgeMs,
    onQueueChange,
    setQueueCount,
  });

  return {
    cleanupStaleItems,
    clearQueue,
    dequeue,
    enqueue,
    getItem,
    getQueue,
    getRetryableItems,
    getStats,
    hasQueuedItems: queueCount > 0,
    isLoading,
    markFailed,
    queueCount,
  };
}

export default useOfflineQueue;

/**
 * Queue operations (enqueue, dequeue, markFailed)
 */

import { useCallback, MutableRefObject } from 'react';
import {
  loadQueueIndex,
  saveQueueIndex,
  loadQueueItem,
  saveQueueItem,
  removeQueueItem,
  loadAllQueueItems,
} from './storage';
import { generateSubmissionId, calculateQueueStats } from './utils';
import type {
  OfflineSubmissionType,
  QueuedSubmission,
  QueueStats,
} from './types';

interface UseQueueOperationsProps {
  maxQueueSize: number;
  maxRetries: number;
  isMountedRef: MutableRefObject<boolean>;
  setQueueCount: (count: number) => void;
  onItemProcessed?: (item: QueuedSubmission) => void;
  onItemFailed?: (item: QueuedSubmission, error: Error) => void;
  onQueueChange?: (stats: QueueStats) => void;
}

export function useQueueOperations({
  maxQueueSize,
  maxRetries,
  isMountedRef,
  setQueueCount,
  onItemProcessed,
  onItemFailed,
  onQueueChange,
}: UseQueueOperationsProps) {
  const enqueue = useCallback(
    async <T>(
      type: OfflineSubmissionType,
      payload: T,
      options?: { habitId?: string; description?: string }
    ): Promise<string> => {
      const ids = await loadQueueIndex();
      if (ids.length >= maxQueueSize) {
        throw new Error(
          `Queue is full (${maxQueueSize} items). Please wait for items to sync.`
        );
      }
      const id = generateSubmissionId();
      const item: QueuedSubmission<T> = {
        description: options?.description,
        habitId: options?.habitId,
        id,
        payload,
        queuedAt: Date.now(),
        retryCount: 0,
        type,
      };
      await saveQueueItem(item as QueuedSubmission);
      ids.push(id);
      await saveQueueIndex(ids);
      if (isMountedRef.current) {
        setQueueCount(ids.length);
        if (onQueueChange) {
          onQueueChange(calculateQueueStats(await loadAllQueueItems()));
        }
      }
      return id;
    },
    [maxQueueSize, isMountedRef, setQueueCount, onQueueChange]
  );

  const dequeue = useCallback(
    async (id: string): Promise<void> => {
      const ids = await loadQueueIndex();
      const newIds = ids.filter((i) => i !== id);
      const item = await loadQueueItem(id);
      await removeQueueItem(id);
      await saveQueueIndex(newIds);
      if (isMountedRef.current) {
        setQueueCount(newIds.length);
        if (item) onItemProcessed?.(item);
        if (onQueueChange) {
          onQueueChange(calculateQueueStats(await loadAllQueueItems()));
        }
      }
    },
    [isMountedRef, setQueueCount, onItemProcessed, onQueueChange]
  );

  const markFailed = useCallback(
    async (id: string, error: string): Promise<void> => {
      const item = await loadQueueItem(id);
      if (!item) return;
      const newRetryCount = item.retryCount + 1;
      if (newRetryCount >= maxRetries) {
        await dequeue(id);
        onItemFailed?.(item, new Error(error));
        return;
      }
      await saveQueueItem({
        ...item,
        lastError: error,
        lastRetryAt: Date.now(),
        retryCount: newRetryCount,
      });
      if (onQueueChange) {
        onQueueChange(calculateQueueStats(await loadAllQueueItems()));
      }
    },
    [maxRetries, dequeue, onItemFailed, onQueueChange]
  );

  return { dequeue, enqueue, markFailed };
}

/**
 * Queue query operations (getQueue, getRetryableItems, getItem, getStats, clearQueue, cleanupStaleItems)
 */

import { useCallback, MutableRefObject } from 'react';
import {
  loadQueueIndex,
  saveQueueIndex,
  loadQueueItem,
  removeQueueItem,
  loadAllQueueItems,
} from './storage';
import {
  calculateRetryDelay,
  calculateQueueStats,
  createEmptyQueueStats,
} from './utils';
import type { QueuedSubmission, QueueStats } from './types';

interface UseQueueQueriesProps {
  baseRetryDelayMs: number;
  maxItemAgeMs: number;
  isMountedRef: MutableRefObject<boolean>;
  setQueueCount: (count: number) => void;
  onQueueChange?: (stats: QueueStats) => void;
  dequeue: (id: string) => Promise<void>;
}

export function useQueueQueries({
  baseRetryDelayMs,
  maxItemAgeMs,
  isMountedRef,
  setQueueCount,
  onQueueChange,
  dequeue,
}: UseQueueQueriesProps) {
  const getQueue = useCallback(() => loadAllQueueItems(), []);

  const getRetryableItems = useCallback(async (): Promise<
    QueuedSubmission[]
  > => {
    const items = await loadAllQueueItems();
    const now = Date.now();
    return items.filter((item) => {
      if (!item.lastRetryAt) return true;
      return (
        now - item.lastRetryAt >=
        calculateRetryDelay(item.retryCount, baseRetryDelayMs)
      );
    });
  }, [baseRetryDelayMs]);

  const getItem = useCallback((id: string) => loadQueueItem(id), []);

  const clearQueue = useCallback(async (): Promise<void> => {
    const ids = await loadQueueIndex();
    for (const id of ids) await removeQueueItem(id);
    await saveQueueIndex([]);
    if (isMountedRef.current) {
      setQueueCount(0);
      onQueueChange?.(createEmptyQueueStats());
    }
  }, [isMountedRef, setQueueCount, onQueueChange]);

  const cleanupStaleItems = useCallback(async (): Promise<number> => {
    const items = await loadAllQueueItems();
    const now = Date.now();
    let removedCount = 0;
    for (const item of items) {
      if (now - item.queuedAt > maxItemAgeMs) {
        await dequeue(item.id);
        removedCount++;
      }
    }
    return removedCount;
  }, [maxItemAgeMs, dequeue]);

  const getStats = useCallback(
    async () => calculateQueueStats(await loadAllQueueItems()),
    []
  );

  return {
    cleanupStaleItems,
    clearQueue,
    getItem,
    getQueue,
    getRetryableItems,
    getStats,
  };
}

import { useEffect, useMemo, useState } from 'react';
import { Platform } from 'react-native';

interface UseReduceMotionOptions {
  preference?: boolean;
}

const isNativePlatform = Platform.OS === 'ios' || Platform.OS === 'android';

// Lazy import AccessibilityInfo only when available
let AccessibilityInfo: any;
try {
  AccessibilityInfo = require('react-native').AccessibilityInfo;
} catch (e) {
  // AccessibilityInfo not available in this environment
  AccessibilityInfo = null;
}

export const useReduceMotion = ({ preference }: UseReduceMotionOptions = {}) => {
  const [systemReduceMotion, setSystemReduceMotion] = useState(false);

  useEffect(() => {
    // Only run on native platforms and if AccessibilityInfo is available
    if (!isNativePlatform || !AccessibilityInfo) {
      return;
    }

    let isMounted = true;

    AccessibilityInfo.isReduceMotionEnabled()
      .then((value: boolean | null | undefined) => {
        if (isMounted) {
          setSystemReduceMotion(value ?? false);
        }
      })
      .catch(() => {
        // Silently fail - default to false if unable to read preference
        if (isMounted) {
          setSystemReduceMotion(false);
        }
      });

    const subscription = AccessibilityInfo.addEventListener(
      'reduceMotionChanged',
      (enabled: boolean | null | undefined) => {
        if (isMounted) {
          setSystemReduceMotion(enabled ?? false);
        }
      }
    );

    return () => {
      isMounted = false;
      subscription?.remove();
    };
  }, []);

  return useMemo(() => Boolean(preference ?? systemReduceMotion), [preference, systemReduceMotion]);
};

export default useReduceMotion;

/**
 * useRescueTrigger Hook
 * Determines when to show Rescue Mode for at-risk habits
 *
 * Part of T8.6-T8.7: Rescue Mode trigger logic
 *
 * Trigger Conditions:
 * 1. X hours before day ends with habit incomplete (configurable)
 * 2. User opens app after missing scheduled notification
 * 3. Manually triggered from habit card (handled elsewhere)
 *
 * Safety Checks:
 * - Don't trigger if habit already completed today
 * - Don't trigger for paused/archived habits
 * - Limit to 1 rescue per habit per day
 * - Respect Do Not Disturb / Quiet Hours settings
 *
 * Do Not Disturb / Quiet Hours:
 * - Uses configurable quiet hours (e.g., 22:00 - 07:00)
 * - Handles overnight ranges correctly
 * - Disabled by default; users can enable in settings
 * - isInQuietHours returned for UI feedback
 *
 * Scientific Basis:
 * - Loss aversion is most powerful close to deadline
 * - Urgency drives action (Duolingo streak protection model)
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import { AppState, type AppStateStatus } from 'react-native';

/** Habit data needed for rescue trigger evaluation */
export interface RescueEligibleHabit {
  /** Habit ID */
  id: string;
  /** Habit name (for logging) */
  name: string;
  /** Whether habit is completed today */
  isCompletedToday: boolean;
  /** Whether habit is active (not paused/archived) */
  isActive: boolean;
  /** Scheduled notification time (HH:MM format or Date) */
  scheduledTime?: string | Date;
  /** Current streak (affects urgency) */
  currentStreak?: number;
  /** Whether rescue was already shown today */
  rescueShownToday?: boolean;
}

/** Quiet hours configuration for Do Not Disturb respect */
export interface QuietHoursConfig {
  /** Whether quiet hours are enabled */
  enabled: boolean;
  /** Start time in HH:MM format (e.g., "22:00") */
  startTime: string;
  /** End time in HH:MM format (e.g., "07:00") */
  endTime: string;
}

export interface RescueTriggerConfig {
  /** Hours before midnight to trigger rescue (default: 3) */
  hoursBeforeEnd?: number;
  /** Minimum streak to show rescue (default: 1, 0 = always) */
  minStreakForRescue?: number;
  /** Enable app resume trigger (default: true) */
  enableAppResumeTrigger?: boolean;
  /** Enable scheduled trigger (default: true) */
  enableScheduledTrigger?: boolean;
  /** Quiet hours / Do Not Disturb configuration */
  quietHours?: QuietHoursConfig;
  /** Whether to respect system Do Not Disturb (checks notification permissions) */
  respectSystemDND?: boolean;
}

export interface RescueTriggerResult {
  /** Habit ID that needs rescue, or null if none */
  habitNeedingRescue: string | null;
  /** Hours remaining until day ends */
  hoursRemaining: number;
  /** Reason rescue was triggered */
  triggerReason: 'scheduled' | 'app_resume' | 'manual' | null;
  /** Clear the rescue trigger (after showing modal) */
  clearRescue: () => void;
  /** Manually trigger rescue for a habit */
  triggerRescue: (habitId: string, reason?: 'manual' | 'scheduled') => void;
  /** Mark rescue as shown for a habit today */
  markRescueShown: (habitId: string) => void;
  /** Check if a habit is eligible for rescue */
  isEligibleForRescue: (habit: RescueEligibleHabit) => boolean;
  /** Whether rescue is currently blocked by quiet hours / DND */
  isInQuietHours: boolean;
}

/** Default quiet hours: 10 PM - 7 AM (disabled by default) */
const DEFAULT_QUIET_HOURS: QuietHoursConfig = {
  enabled: false,
  endTime: '07:00',
  startTime: '22:00',
};

const DEFAULT_CONFIG: Required<RescueTriggerConfig> = {
  enableAppResumeTrigger: true,
  enableScheduledTrigger: true,
  hoursBeforeEnd: 3,
  minStreakForRescue: 1,
  quietHours: DEFAULT_QUIET_HOURS,
  respectSystemDND: true,
};

/**
 * Calculate hours remaining until end of day (midnight)
 */
function getHoursUntilMidnight(): number {
  const now = new Date();
  const midnight = new Date(now);
  midnight.setHours(24, 0, 0, 0);

  const msRemaining = midnight.getTime() - now.getTime();
  return msRemaining / (1000 * 60 * 60);
}

/**
 * Parse time string (HH:MM) to hours and minutes
 */
function parseTimeString(time: string): { hours: number; minutes: number } {
  const [hours, minutes] = time.split(':').map(Number);
  return { hours: hours || 0, minutes: minutes || 0 };
}

/**
 * Check if current time is within quiet hours
 *
 * Handles overnight ranges (e.g., 22:00 - 07:00)
 *
 * @param quietHours - Quiet hours configuration
 * @returns true if currently in quiet hours
 */
export function isInQuietHoursWindow(quietHours: QuietHoursConfig): boolean {
  if (!quietHours.enabled) return false;

  const now = new Date();
  const currentMinutes = now.getHours() * 60 + now.getMinutes();

  const start = parseTimeString(quietHours.startTime);
  const end = parseTimeString(quietHours.endTime);

  const startMinutes = start.hours * 60 + start.minutes;
  const endMinutes = end.hours * 60 + end.minutes;

  // Handle overnight range (e.g., 22:00 - 07:00)
  if (startMinutes > endMinutes) {
    // We're in quiet hours if current time is >= start OR < end
    return currentMinutes >= startMinutes || currentMinutes < endMinutes;
  }

  // Same-day range (e.g., 13:00 - 15:00)
  return currentMinutes >= startMinutes && currentMinutes < endMinutes;
}

/**
 * Check if current time is past the scheduled habit time
 */
function isPastScheduledTime(scheduledTime?: string | Date): boolean {
  if (!scheduledTime) return false;

  const now = new Date();
  let scheduled: Date;

  if (typeof scheduledTime === 'string') {
    // Parse HH:MM format
    const [hours, minutes] = scheduledTime.split(':').map(Number);
    scheduled = new Date(now);
    scheduled.setHours(hours, minutes, 0, 0);
  } else {
    scheduled = scheduledTime;
  }

  return now > scheduled;
}

/**
 * Hook to determine when to show Rescue Mode
 *
 * @param habits - Array of habits to evaluate
 * @param config - Configuration options
 * @returns Rescue trigger state and controls
 *
 * @example
 * ```tsx
 * const {
 *   habitNeedingRescue,
 *   hoursRemaining,
 *   clearRescue,
 * } = useRescueTrigger(habits, { hoursBeforeEnd: 2 });
 *
 * useEffect(() => {
 *   if (habitNeedingRescue) {
 *     openRescueMode(habitNeedingRescue);
 *   }
 * }, [habitNeedingRescue]);
 * ```
 */
export function useRescueTrigger(
  habits: RescueEligibleHabit[],
  config: RescueTriggerConfig = {}
): RescueTriggerResult {
  const mergedConfig = { ...DEFAULT_CONFIG, ...config };

  const [habitNeedingRescue, setHabitNeedingRescue] = useState<string | null>(
    null
  );
  const [triggerReason, setTriggerReason] = useState<
    'scheduled' | 'app_resume' | 'manual' | null
  >(null);
  const [hoursRemaining, setHoursRemaining] = useState(getHoursUntilMidnight);
  const [isInQuietHours, setIsInQuietHours] = useState(() =>
    isInQuietHoursWindow(mergedConfig.quietHours)
  );

  // Track which habits have had rescue shown today
  const rescueShownRef = useRef<Set<string>>(new Set());

  // Track app state for resume detection
  const appStateRef = useRef<AppStateStatus>(AppState.currentState);
  const wasBackgroundRef = useRef(false);

  /**
   * Check if rescue is currently blocked by quiet hours / DND
   */
  const checkQuietHours = useCallback((): boolean => {
    const inQuiet = isInQuietHoursWindow(mergedConfig.quietHours);
    setIsInQuietHours(inQuiet);
    return inQuiet;
  }, [mergedConfig.quietHours]);

  /**
   * Check if a specific habit is eligible for rescue
   */
  const isEligibleForRescue = useCallback(
    (habit: RescueEligibleHabit): boolean => {
      // Already completed - no rescue needed
      if (habit.isCompletedToday) return false;

      // Inactive habit (paused/archived) - skip
      if (!habit.isActive) return false;

      // Already shown rescue today - don't spam
      if (habit.rescueShownToday || rescueShownRef.current.has(habit.id)) {
        return false;
      }

      // Check minimum streak requirement
      const streak = habit.currentStreak ?? 0;
      if (streak < mergedConfig.minStreakForRescue) {
        return false;
      }

      return true;
    },
    [mergedConfig.minStreakForRescue]
  );

  /**
   * Find the highest-priority habit needing rescue
   * Priority: Higher streak = more urgent
   */
  const findHabitNeedingRescue = useCallback(
    (checkScheduled: boolean): RescueEligibleHabit | null => {
      const eligibleHabits = habits.filter((habit) => {
        if (!isEligibleForRescue(habit)) return false;

        // For scheduled check, must be past scheduled time
        if (checkScheduled && !isPastScheduledTime(habit.scheduledTime)) {
          return false;
        }

        return true;
      });

      if (eligibleHabits.length === 0) return null;

      // Sort by streak (highest first) to prioritize most valuable streaks
      eligibleHabits.sort(
        (a, b) => (b.currentStreak ?? 0) - (a.currentStreak ?? 0)
      );

      return eligibleHabits[0];
    },
    [habits, isEligibleForRescue]
  );

  /**
   * Manually trigger rescue for a habit
   */
  const triggerRescue = useCallback(
    (habitId: string, reason: 'manual' | 'scheduled' = 'manual') => {
      const habit = habits.find((h) => h.id === habitId);
      if (habit && isEligibleForRescue(habit)) {
        setHabitNeedingRescue(habitId);
        setTriggerReason(reason);
        setHoursRemaining(getHoursUntilMidnight());
      }
    },
    [habits, isEligibleForRescue]
  );

  /**
   * Clear the current rescue trigger
   */
  const clearRescue = useCallback(() => {
    setHabitNeedingRescue(null);
    setTriggerReason(null);
  }, []);

  /**
   * Mark rescue as shown for a habit
   */
  const markRescueShown = useCallback((habitId: string) => {
    rescueShownRef.current.add(habitId);
  }, []);

  // Check for scheduled trigger (X hours before end of day)
  useEffect(() => {
    if (!mergedConfig.enableScheduledTrigger) return;

    const checkScheduledTrigger = () => {
      const hours = getHoursUntilMidnight();
      setHoursRemaining(hours);

      // Check and update quiet hours status
      const inQuiet = checkQuietHours();

      // Don't trigger during quiet hours (respect DND)
      if (inQuiet) {
        console.log('[useRescueTrigger] In quiet hours, skipping trigger');
        return;
      }

      // Only trigger if within the window
      if (hours <= mergedConfig.hoursBeforeEnd && hours > 0) {
        const habit = findHabitNeedingRescue(true);
        if (habit && !habitNeedingRescue) {
          console.log(
            `[useRescueTrigger] Scheduled trigger for habit: ${habit.name}`
          );
          triggerRescue(habit.id, 'scheduled');
        }
      }
    };

    // Check immediately
    checkScheduledTrigger();

    // Check every 15 minutes
    const interval = setInterval(checkScheduledTrigger, 15 * 60 * 1000);

    return () => clearInterval(interval);
  }, [
    checkQuietHours,
    mergedConfig.enableScheduledTrigger,
    mergedConfig.hoursBeforeEnd,
    findHabitNeedingRescue,
    habitNeedingRescue,
    triggerRescue,
  ]);

  // Check for app resume trigger
  useEffect(() => {
    if (!mergedConfig.enableAppResumeTrigger) return;

    const handleAppStateChange = (nextState: AppStateStatus) => {
      const wasBackground = appStateRef.current.match(/inactive|background/);

      if (wasBackground && nextState === 'active') {
        // App resumed from background
        wasBackgroundRef.current = true;

        // Update hours remaining
        const hours = getHoursUntilMidnight();
        setHoursRemaining(hours);

        // Check and update quiet hours status
        const inQuiet = checkQuietHours();

        // Don't trigger during quiet hours (respect DND)
        if (inQuiet) {
          console.log(
            '[useRescueTrigger] App resume in quiet hours, skipping trigger'
          );
          appStateRef.current = nextState;
          return;
        }

        // Only trigger within the window
        if (hours <= mergedConfig.hoursBeforeEnd && hours > 0) {
          const habit = findHabitNeedingRescue(true);
          if (habit && !habitNeedingRescue) {
            console.log(
              `[useRescueTrigger] App resume trigger for habit: ${habit.name}`
            );
            setHabitNeedingRescue(habit.id);
            setTriggerReason('app_resume');
          }
        }
      }

      appStateRef.current = nextState;
    };

    const subscription = AppState.addEventListener(
      'change',
      handleAppStateChange
    );

    return () => subscription.remove();
  }, [
    checkQuietHours,
    mergedConfig.enableAppResumeTrigger,
    mergedConfig.hoursBeforeEnd,
    findHabitNeedingRescue,
    habitNeedingRescue,
  ]);

  // Reset rescue shown tracking at midnight
  useEffect(() => {
    const checkMidnight = () => {
      const now = new Date();
      if (now.getHours() === 0 && now.getMinutes() === 0) {
        rescueShownRef.current.clear();
      }
    };

    const interval = setInterval(checkMidnight, 60 * 1000);
    return () => clearInterval(interval);
  }, []);

  return {
    clearRescue,
    habitNeedingRescue,
    hoursRemaining,
    isEligibleForRescue,
    isInQuietHours,
    markRescueShown,
    triggerReason,
    triggerRescue,
  };
}

export default useRescueTrigger;

/**
 * useUnsavedChangesGuard Hook
 * Confirms before discarding unsaved changes in form editors
 *
 * Part of Edge Case handling: Data Loss Prevention
 * - Tracks whether current value differs from original
 * - Shows Alert.alert confirmation before discarding
 * - Integrates with useDraftStorage for auto-saved drafts
 *
 * @example
 * ```tsx
 * const { hasUnsavedChanges, confirmDiscard, setOriginalValue } = useUnsavedChangesGuard({
 *   currentValue: whyDraft,
 *   originalValue: habit.why ?? '',
 * });
 *
 * // When closing modal:
 * const handleClose = () => {
 *   if (hasUnsavedChanges) {
 *     confirmDiscard(() => {
 *       onClose();
 *     });
 *   } else {
 *     onClose();
 *   }
 * };
 * ```
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import { Alert, type AlertButton, BackHandler, Platform } from 'react-native';
import * as Haptics from 'expo-haptics';

/**
 * Configuration options for the hook
 */
export interface UseUnsavedChangesGuardOptions {
  /** Current value of the form field */
  currentValue: string;
  /** Original value (from database/props) */
  originalValue: string;
  /** Title for the confirmation dialog */
  alertTitle?: string;
  /** Message for the confirmation dialog */
  alertMessage?: string;
  /** Label for the discard button */
  discardButtonLabel?: string;
  /** Label for the keep editing button */
  keepEditingButtonLabel?: string;
  /** Whether to show the guard (can disable for save-in-progress) */
  enabled?: boolean;
  /** Callback when user confirms discard */
  onDiscard?: () => void;
  /** Whether to intercept Android back button (default: false) */
  interceptBackButton?: boolean;
}

/**
 * Return value from the hook
 */
export interface UseUnsavedChangesGuardReturn {
  /** Whether there are unsaved changes */
  hasUnsavedChanges: boolean;
  /** Show confirmation dialog and execute callback if user confirms discard */
  confirmDiscard: (onConfirm: () => void) => void;
  /** Show confirmation dialog and return Promise<boolean> */
  confirmDiscardAsync: () => Promise<boolean>;
  /** Update the original value (e.g., after successful save) */
  setOriginalValue: (value: string) => void;
  /** Whether the confirmation dialog is currently showing */
  isConfirmationVisible: boolean;
  /** Directly perform discard action (bypasses confirmation) */
  forceDiscard: () => void;
}

// Default strings
const DEFAULT_ALERT_TITLE = 'Discard Changes?';
const DEFAULT_ALERT_MESSAGE =
  'You have unsaved changes. Are you sure you want to discard them?';
const DEFAULT_DISCARD_BUTTON = 'Discard';
const DEFAULT_KEEP_EDITING_BUTTON = 'Keep Editing';

/**
 * Normalize values for comparison (trim whitespace, handle nullish)
 */
function normalizeValue(value: string | null | undefined): string {
  return (value ?? '').trim();
}

/**
 * Check if two values are meaningfully different
 */
function hasChanges(current: string, original: string): boolean {
  return normalizeValue(current) !== normalizeValue(original);
}

/**
 * useUnsavedChangesGuard Hook
 *
 * Provides confirmation dialog before discarding unsaved changes.
 * Works with any form field that has a current and original value.
 */
export function useUnsavedChangesGuard({
  currentValue,
  originalValue,
  alertTitle = DEFAULT_ALERT_TITLE,
  alertMessage = DEFAULT_ALERT_MESSAGE,
  discardButtonLabel = DEFAULT_DISCARD_BUTTON,
  keepEditingButtonLabel = DEFAULT_KEEP_EDITING_BUTTON,
  enabled = true,
  onDiscard,
  interceptBackButton = false,
}: UseUnsavedChangesGuardOptions): UseUnsavedChangesGuardReturn {
  // Track original value internally (can be updated after save)
  const [internalOriginal, setInternalOriginal] = useState(originalValue);
  const [isConfirmationVisible, setIsConfirmationVisible] = useState(false);

  // Refs for async confirmation
  const resolveRef = useRef<((value: boolean) => void) | null>(null);

  // Update internal original when prop changes (e.g., on mount or save)
  useEffect(() => {
    setInternalOriginal(originalValue);
  }, [originalValue]);

  // Calculate if there are unsaved changes
  const hasUnsavedChanges =
    enabled && hasChanges(currentValue, internalOriginal);

  // Show confirmation dialog with callback
  const confirmDiscard = useCallback(
    (onConfirm: () => void) => {
      if (!hasUnsavedChanges) {
        // No changes, just proceed
        onConfirm();
        return;
      }

      // Haptic feedback for important action
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);

      setIsConfirmationVisible(true);

      const buttons: AlertButton[] = [
        {
          onPress: () => {
            setIsConfirmationVisible(false);
          },
          style: 'cancel',
          text: keepEditingButtonLabel,
        },
        {
          onPress: () => {
            setIsConfirmationVisible(false);
            Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
            onDiscard?.();
            onConfirm();
          },
          style: 'destructive',
          text: discardButtonLabel,
        },
      ];

      Alert.alert(alertTitle, alertMessage, buttons, { cancelable: true });
    },
    [
      hasUnsavedChanges,
      alertTitle,
      alertMessage,
      discardButtonLabel,
      keepEditingButtonLabel,
      onDiscard,
    ]
  );

  // Async version for more control flow flexibility
  const confirmDiscardAsync = useCallback((): Promise<boolean> => {
    return new Promise((resolve) => {
      if (!hasUnsavedChanges) {
        resolve(true);
        return;
      }

      // Haptic feedback for important action
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);

      setIsConfirmationVisible(true);
      resolveRef.current = resolve;

      const buttons: AlertButton[] = [
        {
          onPress: () => {
            setIsConfirmationVisible(false);
            resolveRef.current?.(false);
            resolveRef.current = null;
          },
          style: 'cancel',
          text: keepEditingButtonLabel,
        },
        {
          onPress: () => {
            setIsConfirmationVisible(false);
            Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
            onDiscard?.();
            resolveRef.current?.(true);
            resolveRef.current = null;
          },
          style: 'destructive',
          text: discardButtonLabel,
        },
      ];

      Alert.alert(alertTitle, alertMessage, buttons, {
        cancelable: true,
        onDismiss: () => {
          // User dismissed by tapping outside on Android
          setIsConfirmationVisible(false);
          resolveRef.current?.(false);
          resolveRef.current = null;
        },
      });
    });
  }, [
    hasUnsavedChanges,
    alertTitle,
    alertMessage,
    discardButtonLabel,
    keepEditingButtonLabel,
    onDiscard,
  ]);

  // Force discard without confirmation
  const forceDiscard = useCallback(() => {
    onDiscard?.();
  }, [onDiscard]);

  // Update original value (call after successful save)
  const setOriginalValue = useCallback((value: string) => {
    setInternalOriginal(value);
  }, []);

  // Intercept Android back button if enabled
  useEffect(() => {
    if (!interceptBackButton || Platform.OS !== 'android') {
      return;
    }

    const handleBackPress = () => {
      if (hasUnsavedChanges) {
        confirmDiscard(() => {
          // Navigation will be handled by the callback
        });
        return true; // Prevent default back behavior
      }
      return false; // Allow default back behavior
    };

    const subscription = BackHandler.addEventListener(
      'hardwareBackPress',
      handleBackPress
    );

    return () => {
      subscription.remove();
    };
  }, [hasUnsavedChanges, confirmDiscard, interceptBackButton]);

  return {
    confirmDiscard,
    confirmDiscardAsync,
    forceDiscard,
    hasUnsavedChanges,
    isConfirmationVisible,
    setOriginalValue,
  };
}

export default useUnsavedChangesGuard;

type InteractionPayload = Record<string, unknown> | undefined;

export const logInteraction = (eventName: string, payload: InteractionPayload = undefined) => {
  if (!eventName) {
    return;
  }

  const timestamp = new Date().toISOString();
  // eslint-disable-next-line no-console
  console.log(`[interaction:${eventName}]`, { payload, timestamp });
};

export default logInteraction;

/**
 * Business logic hooks for AnalyticsScreen
 */
import { useState, useCallback } from 'react';
import { Alert } from 'react-native';
import { useQuery } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import { exportData, prepareExportData } from '../../utils/exportData';
import type {
  ExportFormat,
  UseAnalyticsScreenReturn,
} from './AnalyticsScreen.types';

export const useAnalyticsScreen = (): UseAnalyticsScreenReturn => {
  const [refreshing, setRefreshing] = useState(false);
  const [showPaywall, setShowPaywall] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);

  // TODO: Replace with actual premium status check
  const isPremiumUser = true;

  // Fetch analytics data from Convex
  const overviewStats = useQuery(api.analytics.getOverviewStats);
  const strengthDistribution = useQuery(api.analytics.getStrengthDistribution);
  const trendData = useQuery(api.analytics.get30DayTrend);
  const complianceData = useQuery(api.analytics.getComplianceData);
  const weeklyInsights = useQuery(api.analytics.getWeeklyInsights);

  const isLoading = !overviewStats;

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    // Convex queries automatically refresh
    setTimeout(() => setRefreshing(false), 1000);
  }, []);

  const handleHabitPress = useCallback((habitId: string) => {
    console.log('Navigate to habit detail:', habitId);
  }, []);

  const handleExportPress = useCallback(() => {
    if (!isPremiumUser) {
      setShowPaywall(true);
      return;
    }
    setShowExportMenu(true);
  }, [isPremiumUser]);

  const handleExport = useCallback(
    async (format: ExportFormat) => {
      setShowExportMenu(false);

      try {
        const exportDataObj = await prepareExportData([], [], overviewStats);
        await exportData(exportDataObj, format);

        Alert.alert(
          'Success',
          `Data exported successfully as ${format.toUpperCase()}`,
          [{ text: 'OK' }]
        );
      } catch (error) {
        console.error('Export error:', error);
        Alert.alert(
          'Export Failed',
          error instanceof Error ? error.message : 'Unable to export data',
          [{ text: 'OK' }]
        );
      }
    },
    [overviewStats]
  );

  const handleStartTrial = useCallback(() => {
    setShowPaywall(false);
    Alert.alert(
      'Start Trial',
      'This would open the subscription flow with RevenueCat/StoreKit integration',
      [{ text: 'OK' }]
    );
  }, []);

  return {
    complianceData,
    isLoading,
    handleExportPress,
    isPremiumUser,
    handleExport,
    onRefresh,
    handleHabitPress,
    refreshing,
    handleStartTrial,
    showExportMenu,
    overviewStats,
    showPaywall,
    setShowExportMenu,
    setShowPaywall,
    strengthDistribution,
    trendData,
    weeklyInsights,
  };
};

/**
 * Styles for AnalyticsScreen
 */
import { StyleSheet } from 'react-native';
