/**
 * HeroSection Component
 * Icon, Name, Description, and Streak Badge
 */

import React, { useEffect } from 'react';
import { View, Text } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
  Easing,
} from 'react-native-reanimated';
import type { HeroSectionProps } from '../HabitDetailScreen.types';

// Get streak badge text based on streak length (T1.2)
const getStreakBadgeText = (streak: number): string => {
  if (streak >= 30) return `🌟 ${streak} day streak!`;
  if (streak >= 14) return `🔥 ${streak} day streak!`;
  return `⚡ ${streak} day streak!`;
};

export function HeroSection({
  currentStreak,
  habit,
  isCompletedToday,
  reduceMotion = false,
}: HeroSectionProps) {
  // Icon bounce animation on load (T1.1)
  const iconScale = useSharedValue(reduceMotion ? 1 : 0.8);
  const iconTranslateY = useSharedValue(reduceMotion ? 0 : -10);

  // Streak badge animation on load (T1.2)
  const showStreakBadge = currentStreak >= 7;
  const badgeScale = useSharedValue(reduceMotion && showStreakBadge ? 1 : 0);
  const badgeOpacity = useSharedValue(reduceMotion && showStreakBadge ? 1 : 0);

  useEffect(() => {
    if (reduceMotion) {
      iconScale.value = 1;
      iconTranslateY.value = 0;
      if (showStreakBadge) {
        badgeScale.value = 1;
        badgeOpacity.value = 1;
      }
      return;
    }

    iconScale.value = withSpring(1, { damping: 8, mass: 1, stiffness: 150 });
    iconTranslateY.value = withSpring(0, {
      damping: 8,
      mass: 1,
      stiffness: 150,
    });

    if (showStreakBadge) {
      setTimeout(() => {
        badgeOpacity.value = withTiming(1, {
          duration: 200,
          easing: Easing.out(Easing.ease),
        });
        badgeScale.value = withSpring(1, {
          damping: 10,
          mass: 1,
          stiffness: 200,
        });
      }, 400);
    }
  }, [showStreakBadge, reduceMotion]);

  const iconAnimatedStyle = useAnimatedStyle(() => ({
    transform: [
      { scale: iconScale.value },
      { translateY: iconTranslateY.value },
    ],
  }));

  const badgeAnimatedStyle = useAnimatedStyle(() => ({
    opacity: badgeOpacity.value,
    transform: [{ scale: badgeScale.value }],
  }));

  return (
    <View className='items-center pb-4'>
      {habit.icon && (
        <Animated.View
          className='mb-3 h-20 w-20 items-center justify-center rounded-2xl shadow-lg'
          style={[
            { backgroundColor: habit.iconColor || '#fef3c7' },
            iconAnimatedStyle,
          ]}
        >
          <Text className='text-4xl'>{habit.icon}</Text>
        </Animated.View>
      )}

      <Text className='text-xl font-bold text-stone-900'>{habit.name}</Text>

      {showStreakBadge && (
        <Animated.View
          accessibilityLabel={`${currentStreak} day streak`}
          className='mt-2 rounded-full bg-gradient-to-r from-orange-100 to-amber-100 px-3 py-1'
          style={badgeAnimatedStyle}
        >
          <Text className='text-xs font-semibold text-orange-600'>
            {getStreakBadgeText(currentStreak)}
          </Text>
        </Animated.View>
      )}

      {habit.notes ? (
        <Text className='mt-1 px-6 text-center text-sm text-stone-500'>
          {habit.notes}
        </Text>
      ) : null}
    </View>
  );
}

/**
 * useCalendarHandlers
 * Calendar toggle and undo/redo handlers for habit detail screen
 */

import { useCallback } from 'react';
import { Alert } from 'react-native';
import { useMutation } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import * as Haptics from 'expo-haptics';
import type { Id } from '../../../convex/_generated/dataModel';
import type { Habit } from './HabitDetailScreen.types';

interface UseCalendarHandlersProps {
  habit: Habit | null;
  isTogglingCalendar: boolean;
  onArchive?: (habitId: Id<'habits'>) => void;
  onClose: () => void;
  onDelete?: (habitId: Id<'habits'>) => void;
  setIsTogglingCalendar: (toggling: boolean) => void;
  setPendingArchive: (pending: boolean) => void;
  setPendingDelete: (pending: boolean) => void;
}

export const useCalendarHandlers = ({
  habit,
  isTogglingCalendar,
  onArchive,
  onClose,
  onDelete,
  setIsTogglingCalendar,
  setPendingArchive,
  setPendingDelete,
}: UseCalendarHandlersProps) => {
  const toggleHabitMutation = useMutation(api.habits.toggleHabit);

  const handleCalendarDayPress = useCallback(
    (date: string, wasCompleted: boolean): void => {
      if (isTogglingCalendar || !habit?._id) return;

      const inputDate = new Date(date);
      const todayDate = new Date();
      inputDate.setHours(0, 0, 0, 0);
      todayDate.setHours(0, 0, 0, 0);
      if (inputDate > todayDate) return;

      setIsTogglingCalendar(true);
      toggleHabitMutation({ date, habitId: habit._id })
        .catch((error: unknown) => {
          console.error('Failed to toggle habit:', error);
          Alert.alert('Error', 'Failed to update habit. Please try again.');
        })
        .finally(() => setIsTogglingCalendar(false));
    },
    [isTogglingCalendar, habit?._id, toggleHabitMutation, setIsTogglingCalendar]
  );

  const handleSwipeDelete = useCallback(() => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
    setPendingDelete(true);
  }, [setPendingDelete]);

  const handleSwipeArchive = useCallback(() => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
    setPendingArchive(true);
  }, [setPendingArchive]);

  const handleConfirmDelete = useCallback(() => {
    setPendingDelete(false);
    if (habit) {
      onDelete?.(habit._id);
      onClose();
    }
  }, [habit, onDelete, onClose, setPendingDelete]);

  const handleConfirmArchive = useCallback(() => {
    setPendingArchive(false);
    if (habit) {
      onArchive?.(habit._id);
      onClose();
    }
  }, [habit, onArchive, onClose, setPendingArchive]);

  const handleUndoDelete = useCallback(
    () => setPendingDelete(false),
    [setPendingDelete]
  );
  const handleUndoArchive = useCallback(
    () => setPendingArchive(false),
    [setPendingArchive]
  );

  return {
    handleCalendarDayPress,
    handleConfirmArchive,
    handleConfirmDelete,
    handleSwipeArchive,
    handleSwipeDelete,
    handleUndoArchive,
    handleUndoDelete,
  };
};

/** useHabitDetailScreenComputed - Computed/derived values for the habit detail screen */

import { useMemo } from 'react';
import type { WeekDayData } from './HabitDetailScreen.types';

interface UseHabitDetailScreenComputedProps {
  completedDates: Set<string>;
  isCompletedToday: boolean;
  today: string;
}

export const useHabitDetailScreenComputed = ({
  completedDates,
  isCompletedToday,
  today,
}: UseHabitDetailScreenComputedProps) => {
  const lastSevenDays = useMemo(
    () =>
      Array.from({ length: 7 }, (_, i) => {
        const date = new Date();
        date.setDate(date.getDate() - (6 - i));
        const dateKey = date.toISOString().split('T')[0];
        return dateKey === today
          ? isCompletedToday
          : completedDates.has(dateKey);
      }),
    [today, isCompletedToday, completedDates]
  );

  const lastThirtyDays = useMemo(
    () =>
      Array.from({ length: 30 }, (_, i) => {
        const date = new Date();
        date.setDate(date.getDate() - (29 - i));
        const dateKey = date.toISOString().split('T')[0];
        return {
          completed:
            dateKey === today ? isCompletedToday : completedDates.has(dateKey),
          date: dateKey,
        };
      }),
    [today, isCompletedToday, completedDates]
  );

  const successRate = useMemo(
    () => (lastThirtyDays.filter((d) => d.completed).length / 30) * 100,
    [lastThirtyDays]
  );

  // Week data for WeeklySummaryStrip (Monday to Sunday)
  const weekData = useMemo<WeekDayData[]>(() => {
    const todayDate = new Date();
    const dayOfWeek = todayDate.getDay(); // 0 = Sunday, 1 = Monday, etc.
    // Convert to Monday-based (0 = Monday, 6 = Sunday)
    const mondayOffset = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
    const monday = new Date(todayDate);
    monday.setDate(todayDate.getDate() - mondayOffset);
    monday.setHours(0, 0, 0, 0);

    return Array.from({ length: 7 }, (_, index) => {
      const date = new Date(monday);
      date.setDate(monday.getDate() + index);
      const dateKey = date.toISOString().split('T')[0];
      const isTodayDate = dateKey === today;

      return {
        completed: isTodayDate ? isCompletedToday : completedDates.has(dateKey),
        date: dateKey,
        isToday: isTodayDate,
      };
    });
  }, [today, isCompletedToday, completedDates]);

  // Last week's completion count for trend comparison
  const lastWeekCompleted = useMemo(() => {
    const todayDate = new Date();
    const dayOfWeek = todayDate.getDay();
    const mondayOffset = dayOfWeek === 0 ? 6 : dayOfWeek - 1;

    const lastMonday = new Date(todayDate);
    lastMonday.setDate(todayDate.getDate() - mondayOffset - 7);
    lastMonday.setHours(0, 0, 0, 0);

    let count = 0;
    for (let i = 0; i < 7; i++) {
      const date = new Date(lastMonday);
      date.setDate(lastMonday.getDate() + i);
      const dateKey = date.toISOString().split('T')[0];
      if (completedDates.has(dateKey)) {
        count++;
      }
    }
    return count;
  }, [completedDates]);

  return {
    lastSevenDays,
    lastThirtyDays,
    lastWeekCompleted,
    successRate,
    weekData,
  };
};

/**
 * useHabitDetailScreenState - State management for the habit detail screen
 */

import { useMemo, useState } from 'react';
import { useQuery } from 'convex/react';
import { api } from '../../../convex/_generated/api';
import type { Id, Doc } from '../../../convex/_generated/dataModel';
import type { HabitTrackingEntry } from '../../features/habits/types';

interface UseHabitDetailScreenStateProps {
  habitCreatedAt: number | undefined;
  habitId: Id<'habits'> | undefined;
  habitStrength: number;
  tracking: HabitTrackingEntry[];
  visible: boolean;
}

export const useHabitDetailScreenState = ({
  habitCreatedAt,
  habitId,
  habitStrength,
  tracking,
  visible,
}: UseHabitDetailScreenStateProps) => {
  // Notes modal states
  const [isNotesEditorOpen, setIsNotesEditorOpen] = useState(false);
  const [isNotesListOpen, setIsNotesListOpen] = useState(false);
  const [editingNoteId, setEditingNoteId] = useState<Id<'notes'> | null>(null);

  // Delete/Archive undo toast states (T3.5: Swipe-to-delete)
  const [pendingDelete, setPendingDelete] = useState(false);
  const [pendingArchive, setPendingArchive] = useState(false);

  // Calendar toggling state
  const [isTogglingCalendar, setIsTogglingCalendar] = useState(false);

  // Fetch habit notes
  const habitNotes =
    useQuery(api.notes.search, visible && habitId ? { habitId } : 'skip') ?? [];

  // Today's date
  const today = useMemo(() => new Date().toISOString().split('T')[0], []);

  // Completed dates set
  const completedDates = useMemo(() => {
    if (!habitId) {
      return new Set<string>();
    }
    return new Set(
      tracking
        .filter((entry) => entry.habitId === habitId && entry.completed)
        .map((entry) => entry.date)
    );
  }, [habitId, tracking]);

  const isCompletedToday = completedDates.has(today);

  // Days tracking calculation
  const daysTracking = useMemo(() => {
    return habitCreatedAt
      ? Math.max(
          0,
          Math.floor((Date.now() - habitCreatedAt) / (1000 * 60 * 60 * 24))
        )
      : 0;
  }, [habitCreatedAt]);

  const totalCompletions = useMemo(() => completedDates.size, [completedDates]);

  const strengthPercent = useMemo(
    () => Math.max(0, Math.min(100, habitStrength * 100)),
    [habitStrength]
  );

  // Get the note being edited
  const editingNote = editingNoteId
    ? habitNotes.find((n) => n._id === editingNoteId)
    : null;

  return {
    completedDates,
    daysTracking,
    editingNote,
    editingNoteId,
    habitNotes,
    isCompletedToday,
    isNotesEditorOpen,
    isNotesListOpen,
    isTogglingCalendar,
    pendingArchive,
    pendingDelete,
    setEditingNoteId,
    setIsNotesEditorOpen,
    setIsNotesListOpen,
    setIsTogglingCalendar,
    setPendingArchive,
    setPendingDelete,
    strengthPercent,
    today,
    totalCompletions,
  };
};

import { useState, useEffect, useCallback } from 'react';
import {
  Alert,
  Keyboard,
  Modal,
  Pressable,
  ScrollView,
  Text,
  TextInput,
  View,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { ChevronLeft, Trash2, Archive } from 'lucide-react-native';
import { useMutation, useQuery } from 'convex/react';
import { api } from '../../convex/_generated/api';
import type { Id } from '../../convex/_generated/dataModel';
import {
  cancelHabitReminder,
  createDateFromTimeString,
  ensureNotificationPermissions,
  formatReminderTime,
  getDefaultReminderTime,
  scheduleHabitReminder,
} from '../utils/notifications';
import { EmojiPicker } from '../components/CreateHabitModal/components/EmojiPicker';
import { ColorPickerSection } from '../components/CreateHabitModal/components/ColorPickerSection';
import { EnhancedReminderSelector } from '../components/CreateHabitModal/components/EnhancedReminderSelector';
import { HABIT_COLORS } from '../components/CreateHabitModal/constants';
import useHapticFeedback from '../hooks/useHapticFeedback';

interface HabitEditScreenProps {
  visible: boolean;
  habitId: Id<'habits'> | null;
  onClose: () => void;
}

export default function HabitEditScreen({
  visible,
  habitId,
  onClose,
}: HabitEditScreenProps) {
  const insets = useSafeAreaInsets();
  const { triggerSelection, triggerSuccess } = useHapticFeedback();

  // Get habit data
  const habit = useQuery(api.habits.get, habitId ? { habitId } : 'skip');

  // State - Only name, emoji, color, and reminder
  const [habitName, setHabitName] = useState('');
  const [selectedEmoji, setSelectedEmoji] = useState<string | null>('💪');
  const [selectedColor, setSelectedColor] = useState('#DBEAFE');
  const [remindersEnabled, setRemindersEnabled] = useState(false);
  const [reminderTime, setReminderTime] = useState<Date>(() =>
    getDefaultReminderTime()
  );

  const updateHabit = useMutation(api.habits.update);
  const removeHabit = useMutation(api.habits.remove);
  const archiveHabit = useMutation(api.habits.archive);

  // Initialize state from habit data
  useEffect(() => {
    if (habit) {
      // Extract emoji and name from habit name (format: "💪 Exercise")
      const parts = habit.name.split(' ');
      const emoji = parts[0];
      const name = parts.slice(1).join(' ');

      setHabitName(name || habit.name);
      setSelectedEmoji(emoji || '💪');
      setSelectedColor(habit.iconColor || '#DBEAFE');
      setRemindersEnabled(habit.remindersEnabled ?? false);
      setReminderTime(
        createDateFromTimeString(habit.reminderTime, getDefaultReminderTime())
      );
    }
  }, [habit]);

  const handleSave = useCallback(async () => {
    if (!habitId || !habitName.trim()) return;

    const trimmedName = habitName.trim();
    const fullName = selectedEmoji
      ? `${selectedEmoji} ${trimmedName}`
      : trimmedName;
    const reminderTimeString = formatReminderTime(reminderTime);

    let enableReminders = remindersEnabled;

    if (remindersEnabled) {
      const hasPermission = await ensureNotificationPermissions();
      enableReminders = hasPermission;

      if (hasPermission) {
        const scheduled = await scheduleHabitReminder({
          body: 'Time to check in on your habit progress!',
          habitId: String(habitId),
          reminderTime,
          skipPermissionCheck: true,
          title: fullName,
        });
        enableReminders = scheduled;
      }

      if (!enableReminders) {
        await cancelHabitReminder(String(habitId));
        Alert.alert(
          'Notifications Disabled',
          'Enable notifications in your device settings to receive habit reminders.'
        );
      }
    } else {
      await cancelHabitReminder(String(habitId));
    }

    await updateHabit({
      habitId,
      icon: selectedEmoji ?? undefined,
      iconColor: selectedColor,
      name: fullName,
      remindersEnabled: enableReminders,
      reminderSound: enableReminders ? 'default' : undefined,
      reminderTime: enableReminders ? reminderTimeString : undefined,
    });

    triggerSuccess();
    onClose();
  }, [
    habitId,
    habitName,
    selectedEmoji,
    selectedColor,
    remindersEnabled,
    reminderTime,
    updateHabit,
    triggerSuccess,
    onClose,
  ]);

  const handleDelete = useCallback(() => {
    if (!habitId) return;

    Alert.alert(
      'Delete Habit',
      'This action cannot be undone. All your progress and history will be permanently deleted.',
      [
        { style: 'cancel', text: 'Cancel' },
        {
          onPress: () => {
            void removeHabit({ habitId }).then(() => {
              triggerSelection();
              onClose();
            });
          },
          style: 'destructive',
          text: 'Delete',
        },
      ]
    );
  }, [habitId, removeHabit, triggerSelection, onClose]);

  const handleArchive = useCallback(() => {
    if (!habitId) return;

    Alert.alert(
      'Archive Habit',
      'This habit will be hidden but your progress will be preserved. You can restore it anytime from Settings.',
      [
        { style: 'cancel', text: 'Cancel' },
        {
          onPress: () => {
            void archiveHabit({ habitId }).then(() => {
              triggerSelection();
              onClose();
            });
          },
          text: 'Archive',
        },
      ]
    );
  }, [habitId, archiveHabit, triggerSelection, onClose]);

  const handleEmojiSelect = useCallback((emoji: string | null) => {
    setSelectedEmoji(emoji);
  }, []);

  const handleColorSelect = useCallback(
    (color: string) => {
      triggerSelection();
      setSelectedColor(color);
    },
    [triggerSelection]
  );

  const handleReminderToggle = useCallback((enabled: boolean) => {
    setRemindersEnabled(enabled);
  }, []);

  const handleReminderTimeChange = useCallback((time: Date) => {
    setReminderTime(time);
  }, []);

  if (!visible || !habitId) {
    return null;
  }

  return (
    <Modal animationType='slide' visible={visible} onRequestClose={onClose}>
      <View className='flex-1 bg-stone-50'>
        {/* Header */}
        <View
          className='flex-row items-center justify-between border-b border-stone-200 bg-stone-50 px-4 pb-3'
          style={{ paddingTop: insets.top + 8 }}
        >
          <Pressable
            accessibilityLabel='Cancel'
            accessibilityRole='button'
            className='h-10 w-10 items-center justify-center rounded-full'
            onPress={() => {
              triggerSelection();
              onClose();
            }}
          >
            <ChevronLeft color='#1c1917' size={24} strokeWidth={2} />
          </Pressable>

          <Pressable
            accessibilityLabel='Save changes'
            accessibilityRole='button'
            className='rounded-full bg-stone-900 px-4 py-2'
            onPress={() => void handleSave()}
          >
            <Text className='text-sm font-semibold text-white'>Save</Text>
          </Pressable>
        </View>

        <ScrollView
          className='flex-1'
          contentContainerStyle={{ paddingBottom: insets.bottom + 100 }}
          keyboardDismissMode='on-drag'
          keyboardShouldPersistTaps='handled'
          showsVerticalScrollIndicator={false}
        >
          <Pressable onPress={Keyboard.dismiss}>
            <View className='flex-1 px-6'>
              {/* Name Input Section */}
              <View
                className='items-center'
                style={{ marginBottom: 32, marginTop: 32 }}
              >
                <Text className='mb-3 text-center text-2xl font-bold text-stone-900'>
                  Edit your habit
                </Text>

                <TextInput
                  className='w-full rounded-2xl border-2 border-stone-200 bg-white px-6 py-5 text-center text-xl text-stone-900'
                  maxLength={50}
                  placeholder='e.g., Read for 20 minutes'
                  placeholderTextColor='#A8A29E'
                  returnKeyType='done'
                  value={habitName}
                  onChangeText={setHabitName}
                  onSubmitEditing={Keyboard.dismiss}
                />

                {/* Character counter */}
                <Text className='mt-2 text-xs text-stone-400'>
                  {habitName.length}/50 characters
                </Text>
              </View>

              {/* Customize Section */}
              <View className='flex-1'>
                {/* Section label */}
                <Text
                  className='mb-4 text-center text-xs font-semibold text-stone-500'
                  style={{ letterSpacing: 0.5 }}
                >
                  CUSTOMIZE
                </Text>

                {/* Emoji picker */}
                <EmojiPicker
                  hideLabel
                  habitName={habitName}
                  selectedEmoji={selectedEmoji}
                  onSelect={handleEmojiSelect}
                />

                {/* Color picker */}
                <ColorPickerSection
                  hideLabel
                  colors={HABIT_COLORS}
                  selectedColor={selectedColor}
                  onSelectColor={handleColorSelect}
                />

                {/* Reminder selector */}
                <EnhancedReminderSelector
                  enabled={remindersEnabled}
                  reminderTime={reminderTime}
                  onTimeChange={handleReminderTimeChange}
                  onToggle={handleReminderToggle}
                />
              </View>

              {/* Danger Zone */}
              <View className='mt-8 border-t border-stone-200 pt-6'>
                <Text
                  className='mb-4 text-center text-xs font-semibold text-stone-400'
                  style={{ letterSpacing: 0.5 }}
                >
                  MANAGE
                </Text>

                {/* Archive Button */}
                <Pressable
                  accessibilityLabel='Archive habit'
                  accessibilityRole='button'
                  className='mb-3 flex-row items-center justify-center gap-2 rounded-xl border border-amber-200 bg-amber-50 py-4'
                  onPress={handleArchive}
                >
                  <Archive color='#d97706' size={18} strokeWidth={2} />
                  <Text className='text-base font-medium text-amber-700'>
                    Archive Habit
                  </Text>
                </Pressable>

                {/* Delete Button */}
                <Pressable
                  accessibilityLabel='Delete habit'
                  accessibilityRole='button'
                  className='flex-row items-center justify-center gap-2 rounded-xl border border-red-200 bg-red-50 py-4'
                  onPress={handleDelete}
                >
                  <Trash2 color='#dc2626' size={18} strokeWidth={2} />
                  <Text className='text-base font-medium text-red-600'>
                    Delete Habit
                  </Text>
                </Pressable>
              </View>
            </View>
          </Pressable>
        </ScrollView>
      </View>
    </Modal>
  );
}

/**
 * State management for TemplatesScreen
 */

import { useEffect, useRef, useState } from 'react';
import { FlatList, ScrollView } from 'react-native';
import type { Doc, Id } from '../../../convex/_generated/dataModel';
import type { Category, SortOption } from '../templates/constants';
import type { BrowseTab, ViewMode } from './TemplatesScreen.types';

interface UseTemplatesScreenStateOptions {
  categories: { id: string }[] | undefined;
}

export function useTemplatesScreenState({
  categories,
}: UseTemplatesScreenStateOptions) {
  const flatListRef = useRef<FlatList<Doc<'templates'>>>(null);
  const scrollViewRef = useRef<ScrollView>(null);

  const [viewMode, setViewMode] = useState<ViewMode>('browse');
  const [browseTab, setBrowseTab] = useState<BrowseTab>('categories');
  const [selectedCategory, setSelectedCategory] = useState<Category>('all');
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(
    new Set()
  );
  const [hasInitializedExpanded, setHasInitializedExpanded] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortOption, setSortOption] = useState<SortOption>('popular');
  const [researchOnly, setResearchOnly] = useState(false);
  const [previewTemplate, setPreviewTemplate] =
    useState<Doc<'templates'> | null>(null);
  const [showFullsizePreview, setShowFullsizePreview] = useState(false);
  const [showCustomizeModal, setShowCustomizeModal] = useState(false);
  const [importedTemplateIds, setImportedTemplateIds] = useState<Set<string>>(
    new Set()
  );
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [importingTemplateId, setImportingTemplateId] =
    useState<Id<'templates'> | null>(null);
  const [showSortOptions, setShowSortOptions] = useState(false);
  const [isSeeding, setIsSeeding] = useState(false);

  useEffect(() => {
    if (categories && !hasInitializedExpanded) {
      const nonAll = categories.filter((c) => c.id !== 'all');
      const init = new Set<string>();
      for (const [i, c] of nonAll.entries()) {
        if ((i + 1) % 3 === 0) init.add(c.id);
      }
      setExpandedCategories(init);
      setHasInitializedExpanded(true);
    }
  }, [categories, hasInitializedExpanded]);

  const isSearching = searchQuery.trim().length > 0;
  const effectiveViewMode = isSearching ? 'search' : viewMode;
  const hasActiveFilters =
    selectedCategory !== 'all' || Boolean(searchQuery.trim()) || researchOnly;

  return {
    browseTab,
    effectiveViewMode,
    expandedCategories,
    flatListRef,
    hasActiveFilters,
    importedTemplateIds,
    importingTemplateId,
    isSearching,
    isSeeding,
    previewTemplate,
    researchOnly,
    scrollViewRef,
    searchQuery,
    selectedCategory,
    setBrowseTab,
    setExpandedCategories,
    setImportedTemplateIds,
    setImportingTemplateId,
    setIsSeeding,
    setPreviewTemplate,
    setResearchOnly,
    setSearchQuery,
    setSelectedCategory,
    setShowCustomizeModal,
    setShowFullsizePreview,
    setShowSortOptions,
    setShowToast,
    setSortOption,
    setToastMessage,
    setViewMode,
    showCustomizeModal,
    showFullsizePreview,
    showSortOptions,
    showToast,
    sortOption,
    toastMessage,
    viewMode,
  };
}

/**
 * Templates Screen - Main orchestration component
 * Browse and import science-backed habit templates
 */

import { TemplatesEmptyState } from './components/TemplatesEmptyState';
import { TemplatesLoadingState } from './components/TemplatesLoadingState';
import { useTemplatesScreenProps } from './hooks/useTemplatesScreenProps';
import { BrowseView, CategorySearchView } from './views';

export default function TemplatesScreen() {
  const props = useTemplatesScreenProps();
  const { data, state, handlers, filteredTemplates, getCategoryLabel } = props;

  if (data.isLoading) return <TemplatesLoadingState />;
  if (!data.allTemplates?.length) {
    return (
      <TemplatesEmptyState
        isSeeding={state.isSeeding}
        onSeedTemplates={handlers.handleSeedTemplates}
      />
    );
  }

  const isCategoryOrSearchMode =
    state.effectiveViewMode === 'category' ||
    state.effectiveViewMode === 'search';
  if (isCategoryOrSearchMode) {
    return (
      <CategorySearchView
        categories={data.categories}
        effectiveViewMode={state.effectiveViewMode}
        filteredTemplates={filteredTemplates}
        getCategoryLabel={getCategoryLabel}
        handlers={handlers}
        hasActiveFilters={state.hasActiveFilters}
        importedTemplateIds={state.importedTemplateIds}
        importingTemplateId={state.importingTemplateId}
        previewTemplate={state.previewTemplate}
        researchOnly={state.researchOnly}
        searchQuery={state.searchQuery}
        selectedCategory={state.selectedCategory}
        setResearchOnly={state.setResearchOnly}
        setSearchQuery={state.setSearchQuery}
        setShowCustomizeModal={state.setShowCustomizeModal}
        setShowFullsizePreview={state.setShowFullsizePreview}
        setShowSortOptions={state.setShowSortOptions}
        setShowToast={state.setShowToast}
        showCustomizeModal={state.showCustomizeModal}
        showFullsizePreview={state.showFullsizePreview}
        showSortOptions={state.showSortOptions}
        showToast={state.showToast}
        sortOption={state.sortOption}
        toastMessage={state.toastMessage}
      />
    );
  }

  return (
    <BrowseView
      animations={props.animations}
      browseTab={state.browseTab}
      categories={data.categories}
      expandedCategories={state.expandedCategories}
      filteredTemplates={filteredTemplates}
      handlers={handlers}
      importedTemplateIds={state.importedTemplateIds}
      importingTemplateId={state.importingTemplateId}
      previewTemplate={state.previewTemplate}
      researchOnly={state.researchOnly}
      scienceCountsByCategory={props.scienceCountsByCategory}
      scrollViewRef={state.scrollViewRef}
      searchQuery={state.searchQuery}
      setResearchOnly={state.setResearchOnly}
      setSearchQuery={state.setSearchQuery}
      setShowCustomizeModal={state.setShowCustomizeModal}
      setShowFullsizePreview={state.setShowFullsizePreview}
      setShowSortOptions={state.setShowSortOptions}
      setShowToast={state.setShowToast}
      showCustomizeModal={state.showCustomizeModal}
      showFullsizePreview={state.showFullsizePreview}
      showSortOptions={state.showSortOptions}
      showToast={state.showToast}
      sortOption={state.sortOption}
      tabIndicator={props.tabIndicator}
      templatesByCategory={props.templatesByCategory}
      toastMessage={state.toastMessage}
      totalCount={data.allTemplates?.length || 0}
      onCloseSortOptions={() => state.setShowSortOptions(false)}
      onTabPress={props.handleTabPress}
    />
  );
}

