import { forwardRef, useState } from 'react';
import { Text, TextInput, TouchableOpacity, View } from 'react-native';
import type { TextInputProps } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  Easing,
} from 'react-native-reanimated';

/**
 * Props for the PasswordInput component
 */
interface PasswordInputProps extends Omit<TextInputProps, 'secureTextEntry'> {
  /** Current password value */
  value: string;
  /** Callback when password changes */
  onChangeText: (text: string) => void;
  /** Placeholder text */
  placeholder?: string;
  /** Error message to display */
  error?: string;
}

/**
 * PasswordInput - Secure text input with visibility toggle
 *
 * Features:
 * - Password visibility toggle with eye icons
 * - Lock icon prefix
 * - Focus/blur animations with border color transition
 * - Error state styling with red border
 * - Full accessibility support
 * - Supports ref forwarding for keyboard navigation
 *
 * @example
 * <PasswordInput
 *   ref={passwordRef}
 *   value={password}
 *   onChangeText={setPassword}
 *   error={passwordError}
 * />
 */
export const PasswordInput = forwardRef<TextInput, PasswordInputProps>(
  function PasswordInput(
    {
      value,
      onChangeText,
      placeholder = 'Enter your password',
      error,
      ...props
    },
    ref
  ) {
  const [isSecure, setIsSecure] = useState(true);
  const [isFocused, setIsFocused] = useState(false);

  // Animated values for focus/blur animations
  const borderColor = useSharedValue(0);
  const shadowOpacity = useSharedValue(0);

  const toggleSecureEntry = () => {
    setIsSecure((prev) => !prev);
  };

  const handleFocus = () => {
    setIsFocused(true);
    borderColor.value = withTiming(1, {
      duration: 200,
      easing: Easing.out(Easing.ease),
    });
    shadowOpacity.value = withTiming(1, {
      duration: 200,
      easing: Easing.out(Easing.ease),
    });
  };

  const handleBlur = () => {
    setIsFocused(false);
    borderColor.value = withTiming(0, {
      duration: 200,
      easing: Easing.out(Easing.ease),
    });
    shadowOpacity.value = withTiming(0, {
      duration: 200,
      easing: Easing.out(Easing.ease),
    });
  };

  const animatedStyle = useAnimatedStyle(() => {
    return {
      borderColor: borderColor.value === 1 ? '#1c1917' : '#e7e5e4', // stone-900 : stone-200
      shadowOpacity: shadowOpacity.value * 0.1,
      shadowColor: '#1c1917',
      shadowOffset: { width: 0, height: 2 },
      shadowRadius: 4,
      elevation: shadowOpacity.value * 2,
    };
  });

  const errorStyle = error
    ? {
        borderColor: '#ef4444', // red-500
        borderWidth: 1,
      }
    : {};

  return (
    <View className="gap-2">
      <Text className="text-[10px] font-medium tracking-[3px] text-stone-500">
        PASSWORD
      </Text>
      <Animated.View
        style={[animatedStyle, errorStyle]}
        className="relative flex-row items-center rounded-3xl border border-stone-200 bg-white"
      >
        {/* Lock Icon Prefix */}
        <View className="pl-5">
          <Text className="text-lg">🔒</Text>
        </View>

        {/* Text Input */}
        <TextInput
          ref={ref}
          secureTextEntry={isSecure}
          autoComplete="password"
          className="flex-1 px-3 py-3.5 text-base font-medium text-stone-900"
          placeholder={placeholder}
          placeholderTextColor="#a8a29e"
          value={value}
          onChangeText={onChangeText}
          onFocus={handleFocus}
          onBlur={handleBlur}
          accessible={true}
          accessibilityLabel="Password input field"
          accessibilityHint="Enter your password to sign in"
          {...props}
        />

        {/* Toggle Visibility Button */}
        <TouchableOpacity
          onPress={toggleSecureEntry}
          className="min-h-[44px] min-w-[44px] items-center justify-center pr-2"
          accessible={true}
          accessibilityLabel={
            isSecure ? 'Show password' : 'Hide password'
          }
          accessibilityRole="button"
          accessibilityHint="Toggle password visibility"
          hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}
        >
          <Text className="text-lg">{isSecure ? '👁' : '🙈'}</Text>
        </TouchableOpacity>
      </Animated.View>

      {/* Error Message */}
      {error && (
        <Text
          className="px-2 text-sm font-medium text-red-600"
          accessibilityLiveRegion="polite"
          accessibilityRole="alert"
        >
          {error}
        </Text>
      )}
    </View>
  );
  }
);

